#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_SCLK_PIN 11
#define ADC_SAMPLE_RATE 1000 // sample once per second

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up SPI
    int spi_fd = spidev_open("/dev/spidev0.0", 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SPI mode and bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        spidev_close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        spidev_close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioWrite(ADC_CS_PIN, 1);

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        spidev_close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        spidev_close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read ADC value
        uint8_t data[2];
        data[0] = 0x00; // Start bit
        data[1] = 0x01; // Single-ended, channel 0
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2, data, data, 2) < 0)) {
            fprintf(stderr, "Failed to read ADC value\n");
            spidev_close(spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Print ADC value and timestamp
        printf("%lu.%09lu %d\n", (unsigned long)ts.tv_sec, (unsigned long)ts.tv_nsec, data[1]);

        // Wait for next sample
        usleep(ADC_SAMPLE_RATE * 1000);
    }

    // Clean up
    spidev_close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

