#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CHANNEL_AIN0 0x00
#define ADS1115_MUX_AIN0 0x00
#define ADS1115_GAIN_4096 0x01
#define ADS1115_DATA_RATE_128SPS 0x0E

#define ADC_CONVERSION_RESULT_SIZE 2
#define ADC_CONVERSION_RESULT_MASK 0xFFFF

#define CURRENT_SENSOR_ADDRESS 0x00

#define ADC_CONVERSION_RESULT_TO_AMPERES(x) ((x * 20.0) / 32768.0)

void cleanup_handler(int sig) {
    if (i2c_close(I2C_OPEN_FILE) == -1) {
        perror("i2c_close");
    }
    ads1115_cleanup();
    exit(0);
}

int main() {
    int i2c_file;
    int result;
    uint8_t data[ADC_CONVERSION_RESULT_SIZE];
    float current;

    if ((i2c_file = i2c_open("/dev/i2c-1", I2C_CLIENT_PIGPIOS)) == -1) {
        perror("i2c_open");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        i2c_close(i2c_file);
        return 1;
    }

    if (ads1115_init(i2c_file, ADS1115_ADDRESS) == -1) {
        perror("ads1115_init");
        i2c_close(i2c_file);
        gpioTerminate();
        return 1;
    }

    if (ads1115_set_mode(i2c_file, ADS1115_CHANNEL_AIN0, ADS1115_MUX_AIN0) == -1) {
        perror("ads1115_set_mode");
        ads1115_cleanup();
        i2c_close(i2c_file);
        gpioTerminate();
        return 1;
    }

    if (ads1115_set_gain(i2c_file, ADS1115_GAIN_4096) == -1) {
        perror("ads1115_set_gain");
        ads1115_cleanup();
        i2c_close(i2c_file);
        gpioTerminate();
        return 1;
    }

    if (ads1115_set_data_rate(i2c_file, ADS1115_DATA_RATE_128SPS) == -1) {
        perror("ads1115_set_data_rate");
        ads1115_cleanup();
        i2c_close(i2c_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup_handler);

    while (1) {
        if (ads1115_read_conversion_result(i2c_file, data, ADC_CONVERSION_RESULT_SIZE) == -1) {
            perror("ads1115_read_conversion_result");
            ads1115_cleanup();
            i2c_close(i2c_file);
            gpioTerminate();
            return 1;
        }

        current = ADC_CONVERSION_RESULT_TO_AMPERES(((uint16_t)data[0] << 8) | data[1]);

        printf("Current: %.4f A\n", current);

        usleep(500000);
    }

    return 0;
}

