// ads1115.c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ADS1115_ADDRESS 0x48

int ads1115_init(int i2c_file, uint8_t address) {
    uint8_t reg = 0x01;
    if (i2c_smbus_write_byte_data(i2c_file, address, reg) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    return 0;
}

int ads1115_set_mode(int i2c_file, uint8_t channel, uint8_t mux) {
    uint8_t reg = 0x01;
    uint8_t data = (channel << 3) | mux;
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, reg) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, data) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    return 0;
}

int ads1115_set_gain(int i2c_file, uint8_t gain) {
    uint8_t reg = 0x02;
    uint8_t data = gain;
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, reg) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, data) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    return 0;
}

int ads1115_set_data_rate(int i2c_file, uint8_t data_rate) {
    uint8_t reg = 0x03;
    uint8_t data = data_rate;
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, reg) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_file, ADS1115_ADDRESS, data) == -1) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    return 0;
}

int ads1115_read_conversion_result(int i2c_file, uint8_t* data, size_t size) {
    uint8_t reg = 0x00;
    if (i2c_smbus_read_byte_data(i2c_file, ADS1115_ADDRESS, &reg) == -1) {
        perror("i2c_smbus_read_byte_data");
        return -1;
    }
    if (reg & 0x80) {
        return -1;
    }
    if (i2c_smbus_read_i2c_block_data(i2c_file, ADS1115_ADDRESS, reg, data, size) == -1) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }
    return 0;
}

void ads1115_cleanup() {
    // No cleanup needed
}
