#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 4
#define MCP3008_CE 8
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0b00
#define SPI_LSB_FIRST 0
#define SPI_CS_HIGH 0

#define FILE_NAME "flame_data.csv"

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    int gpio_fd;
    int flame_detected = 0;
    int temperature = 0;
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", GPIO_FLAME_SENSOR);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MCP3008_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", MCP3008_CE);
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI parameters
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to set SPI LSB first\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) < 0) {
        fprintf(stderr, "Failed to set SPI CS high\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    if ((gpio_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Read digital output from flame sensor
        if (gpioRead(GPIO_FLAME_SENSOR) == 1) {
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }

        // Read analog output from MCP3008
        uint8_t data[3];
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, data, MCP3008_CE, 0, MCP3008_CHANNEL, 0, 0, 0) < 0)) {
            fprintf(stderr, "Failed to read from SPI\n");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate temperature
        temperature = (int)((data[0] & 0x03) * 100);

        // Log data
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(gpio_fd, "%s,%d,%d\n", buffer, flame_detected, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(spi_fd);
    close(gpio_fd);
    gpioTerminate();

    return 0;
}

