    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) < 0) {
        fprintf(stderr, "Failed to set SPI CS high\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    if ((gpio_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Read digital output from flame sensor
        if (gpioRead(GPIO_FLAME_SENSOR) == 1) {
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }

        // Read analog output from MCP3008
        uint8_t data[3];
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, data, MCP3008_CE, 0, MCP3008_CHANNEL, 0, 0, 0) < 0)) {
            fprintf(stderr, "Failed to read from SPI\n");
            close(spi_fd);
            close(gpio_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate temperature
        temperature = (int)((data[0] & 0x03) * 100);

        // Log data
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(gpio_fd, "%s,%d,%d\n", buffer, flame_detected, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(spi_fd);
    close(gpio_fd);
    gpioTerminate();

    return 0;
