#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define ADC_CS_PIN 17
#define FAN_PIN 18
#define THRESHOLD 1000

int main() {
    int spi_fd, gpio_fd;
    int ret;
    uint8_t buffer[2];
    struct spi_ioc_transfer xfer;
    struct tm timeinfo;
    char filename[256];
    char timestamp[32];

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, 0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("Failed to initialize GPIO");
        close(spi_fd);
        return 1;
    }

    // Open log file
    strftime(filename, sizeof(filename), "current_log.txt", NULL);
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set up SPI transfer
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)buffer;
    xfer.rx_buf = (unsigned long)buffer;
    xfer.len = 2;
    xfer.cs_change = 1;

    while (1) {
        // Read current from ADC
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to transfer data over SPI");
            break;
        }

        // Check for sensor-absent condition
        if (buffer[0] == 0xFF && buffer[1] == 0xFF) {
            fprintf(log_file, "Sensor absent at %s\n", asctime(&timeinfo));
            continue;
        }

        // Check for invalid ADC value
        if (buffer[0] == 0x00 && buffer[1] == 0x00) {
            fprintf(log_file, "Invalid ADC value at %s\n", asctime(&timeinfo));
            continue;
        }

        // Calculate current
        uint16_t current = (buffer[0] << 8) | buffer[1];

        // Log current
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        fprintf(log_file, "%s %d\n", timestamp, current);

        // Drive fan
        if (current > THRESHOLD) {
            gpioSetMode(gpio_fd, FAN_PIN, PI_OUTPUT);
            gpioWrite(gpio_fd, FAN_PIN, 1);
        } else {
            gpioSetMode(gpio_fd, FAN_PIN, PI_OUTPUT);
            gpioWrite(gpio_fd, FAN_PIN, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Close SPI device
    close(spi_fd);

    // Release GPIO lines
    gpioTerminate(gpio_fd);

    return 0;
}

