#define MCP3008_CHANNEL 0

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int gpio_export(int gpio) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio_export");
        return -1;
    }
    char buf[10];
    sprintf(buf, "%d", gpio);
    write(fd, buf, strlen(buf));
    close(fd);
    return 0;
}

int gpio_unexport(int gpio) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio_unexport");
        return -1;
    }
    char buf[10];
    sprintf(buf, "%d", gpio);
    write(fd, buf, strlen(buf));
    close(fd);
    return 0;
}

int gpio_direction(int gpio, int direction) {
    int fd = open("/sys/class/gpio/gpio%d/direction", gpio, O_WRONLY);
    if (fd < 0) {
        perror("gpio_direction");
        return -1;
    }
    char buf[10];
    if (direction == GPIO_MODE_IN) {
        sprintf(buf, "in");
    } else if (direction == GPIO_MODE_OUT) {
        sprintf(buf, "out");
    } else {
        perror("gpio_direction");
        close(fd);
        return -1;
    }
    write(fd, buf, strlen(buf));
    close(fd);
    return 0;
}

int gpio_set(int gpio, int value) {
    int fd = open("/sys/class/gpio/gpio%d/value", gpio, O_WRONLY);
    if (fd < 0) {
        perror("gpio_set");
        return -1;
    }
    char buf[10];
    if (value) {
        sprintf(buf, "1");
    } else {
        sprintf(buf, "0");
    }
    write(fd, buf, strlen(buf));
    close(fd);
    return 0;
}

int gpio_get(int gpio) {
    int fd = open("/sys/class/gpio/gpio%d/value", gpio, O_RDONLY);
    if (fd < 0) {
        perror("gpio_get");
        return -1;
    }
    char buf[10];
    read(fd, buf, 10);
    close(fd);
    if (buf[0] == '1') {
        return 1;
    } else {
        return 0;
    }
}

int spi_open(int bus, int speed) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("spi_open");
        return -1;
    }
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 0;
    xfer.speed = speed;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;
    xfer.delay_usecs = 0;
    xfer.cs_high_pre_transfer = 0;
    xfer.cs_low_pre_transfer = 0;
    xfer.delay_usecs_post_transfer = 0;
    xfer.cs_change_active_high = 0;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("spi_open");
        close(fd);
        return -1;
    }
    return fd;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = len;
    xfer.speed = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;
    xfer.delay_usecs = 0;
    xfer.cs_high_pre_transfer = 0;
    xfer.cs_low_pre_transfer = 0;
    xfer.delay_usecs_post_transfer = 0;
    xfer.cs_change_active_high = 0;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("spi_transfer");
        close(fd);
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Export GPIO pins
    gpio_export(MCP3008_CS);
    gpio_export(MCP3008_SCLK);
    gpio_export(MCP3008_MOSI);
    gpio_export(MCP3008_MISO);
    gpio_export(4);

    // Set GPIO direction
    gpio_direction(MCP3008_CS, GPIO_MODE_OUT);
    gpio_direction(MCP3008_SCLK, GPIO_MODE_OUT);
    gpio_direction(MCP3008_MOSI, GPIO_MODE_OUT);
    gpio_direction(MCP3008_MISO, GPIO_MODE_IN);
    gpio_direction(4, GPIO_MODE_IN);

    // Set GPIO pull-up
    gpio_set(MCP3008_MISO, GPIO_PULL_UP);
    gpio_set(4, GPIO_PULL_UP);

    // Open SPI device
    int spi_fd = spi_open(0, 1000000);
    if (spi_fd < 0) {
        return 1;
    }

    // Open file for logging
