    if (fp == NULL) {
        perror("fopen");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read MCP3008 channel 0
        uint8_t tx[] = {0x06, 0x00, 0x00, 0x00};
        uint8_t rx[3];
