            break;
        }

        // Read temperature from ADC
        int temperature = (rx[0] & 0x03) * 256 + (rx[1] & 0xFF);

        // Read flame sensor
        int flame = gpio_get(4);

        // Log data
        fprintf(fp, "%d,%d\n", flame, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close file
    fclose(fp);

    // Unexport GPIO pins
    gpio_unexport(MCP3008_CS);
    gpio_unexport(MCP3008_SCLK);
    gpio_unexport(MCP3008_MOSI);
    gpio_unexport(MCP3008_MISO);
    gpio_unexport(4);

    // Close SPI device
    close(spi_fd);

    return 0;
}

