#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4D
#define CO_SENSOR_REG 0x00
#define NO2_SENSOR_REG 0x01
#define CO_ALERT_THRESHOLD 25
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"

volatile bool running = true;

void signal_handler(int signal) {
    running = false;
}

int main() {
    int i2c_fd;
    int ret;
    uint16_t co_value, no2_value;
    char log_message[256];
    char alert_message[256];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO library");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log files
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    FILE *alert_file = fopen(ALERT_FILE, "a");
    if (!alert_file) {
        perror("Failed to open alert file");
        fclose(log_file);
        gpioTerminate();
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read from CO sensor
        ret = i2c_smbus_read_byte_data(i2c_fd, CO_SENSOR_REG);
        if (ret < 0) {
            perror("Failed to read from CO sensor");
