// Function to read from I2C device
int read_i2c(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = &reg;
    msgs++;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = I2C_M_RD;
    msgs->len = len;
    msgs->buf = buf;
    if (i2c_transfer(I2C_BUS, msgs, 2) < 0) {
        perror("i2c_transfer");
        return -1;
    }
    return 0;
}

// Function to write to I2C device
int write_i2c(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = &reg;
    msgs++;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = len;
    msgs->buf = buf;
    if (i2c_transfer(I2C_BUS, msgs, 2) < 0) {
        perror("i2c_transfer");
        return -1;
    }
    return 0;
}

// Function to read from I2C device and return the sound pressure level
float read_spl(int fd) {
    uint8_t reg = 0x00;
    uint8_t buf[2];
    if (read_i2c(fd, reg, buf, 2) < 0) {
        return -999.0;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    return (float)raw / 1024.0;
}

