    if (gpioSetMode(GPIO2, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }
    if (gpioSetMode(GPIO3, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }

    // Set up I2C emulation
    if (write_i2c(fd1, 0x01, NULL, 0) < 0) {
        perror("write_i2c");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }
    if (write_i2c(fd2, 0x01, NULL, 0) < 0) {
        perror("write_i2c");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        close(fd1);
        close(fd2);
        return 1;
    }

    // Main loop
    while (1) {
        // Read from I2C devices
        float spl1 = read_spl(fd1);
        float spl2 = read_spl(fd2);

        // Compute average
        float avg = (spl1 + spl2) / 2.0;

        // Log to file
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            perror("fopen");
            gpioTerminate();
            close(fd1);
            close(fd2);
            return 1;
        }
        fprintf(fp, "%f %f\n", avg, (float)time(NULL));
        fclose(fp);

        // Sleep
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    gpioTerminate();
    close(fd1);
    close(fd2);
    return 0;
}

