#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MIC1_CS 8
#define MIC2_CS 9
#define LED_PIN 27
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_LSB 0
#define HIGH_THRESHOLD 0.5
#define WINDOW_SIZE 100
#define SAMPLE_RATE 1000

int main() {
    int fd_mcp3008[2];
    int fd_led;
    struct spi_ioc_transfer spi_transfer;
    struct timeval tv;
    uint8_t buffer[2];
    float mic1_rms = 0.0;
    float mic2_rms = 0.0;
    int i;
    int ret;
    char filename[] = "audio_events.csv";
    FILE *fp;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up LED pin as output
    fd_led = gpioOpen(LED_PIN, 1);
    if (fd_led < 0) {
        fprintf(stderr, "Failed to open LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    fd_mcp3008[0] = open("/dev/spidev0.0", O_RDWR);
    if (fd_mcp3008[0] < 0) {
        fprintf(stderr, "Failed to open SPI device 0\n");
        gpioClose(fd_led);
        gpioTerminate();
        return 1;
    }

    fd_mcp3008[1] = open("/dev/spidev0.1", O_RDWR);
    if (fd_mcp3008[1] < 0) {
        fprintf(stderr, "Failed to open SPI device 1\n");
        close(fd_mcp3008[0]);
        gpioClose(fd_led);
        gpioTerminate();
        return 1;
    }

    // Set up SPI parameters
    spi_transfer.tx_buf = (unsigned long)buffer;
    spi_transfer.rx_buf = (unsigned long)buffer;
    spi_transfer.len = 2;
    spi_transfer.speed = SPI_SPEED;
    spi_transfer.delay_usecs = 0;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.cs_change = 1;
    spi_transfer.cs_high = 1;
    spi_transfer.cs_low = 1;
    spi_transfer.mode = SPI_MODE;
    spi_transfer.lsb_first = SPI_LSB;

    // Set up chip select pins
    gpioSetMode(MIC1_CS, PI_OUTPUT);
    gpioWrite(MIC1_CS, 1);
    gpioSetMode(MIC2_CS, PI_OUTPUT);
    gpioWrite(MIC2_CS, 1);

    // Open log file
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd_mcp3008[0]);
        close(fd_mcp3008[1]);
        gpioClose(fd_led);
        gpioTerminate();
        return 1;
    }

    // Main loop
    gettimeofday(&tv, NULL);
    for (i = 0; i < WINDOW_SIZE; i++) {
        // Acquire samples from both microphones
        spiTransfer(fd_mcp3008[0], &spi_transfer);
        spiTransfer(fd_mcp3008[1], &spi_transfer);

        // Compute RMS level for each channel
        mic1_rms = sqrt((buffer[0] * buffer[0] + buffer[1] * buffer[1]) / 2.0);
        mic2_rms = sqrt((buffer[2] * buffer[2] + buffer[3] * buffer[3]) / 2.0);

        // Log timestamp and RMS levels
        fprintf(fp, "%lu,%f,%f\n", tv.tv_sec + tv.tv_usec / 1000000.0, mic1_rms, mic2_rms);

        // Check if either RMS exceeds high threshold
        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            // Turn on LED
            gpioWrite(fd_led, 1);
            usleep(500000);
            gpioWrite(fd_led, 0);
        }

        // Wait for next sample
        usleep(SAMPLE_RATE);
        gettimeofday(&tv, NULL);
    }

    // Close log file
    fclose(fp);

    // Release resources
    close(fd_mcp3008[0]);
    close(fd_mcp3008[1]);
    gpioClose(fd_led);
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Release resources
    close(fd_mcp3008[0]);
    close(fd_mcp3008[1]);
    gpioClose(fd_led);
    gpioTerminate();

    // Exit
    exit(0);
}

// Register signal handler for SIGINT
void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}

