    gpioSetMode(MIC1_CS, PI_OUTPUT);
    gpioWrite(MIC1_CS, 1);
    gpioSetMode(MIC2_CS, PI_OUTPUT);
    gpioWrite(MIC2_CS, 1);

    // Open log file
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd_mcp3008[0]);
        close(fd_mcp3008[1]);
        gpioClose(fd_led);
        gpioTerminate();
        return 1;
    }

    // Main loop
    gettimeofday(&tv, NULL);
    for (i = 0; i < WINDOW_SIZE; i++) {
        // Acquire samples from both microphones
        spiTransfer(fd_mcp3008[0], &spi_transfer);
        spiTransfer(fd_mcp3008[1], &spi_transfer);

        // Compute RMS level for each channel
        mic1_rms = sqrt((buffer[0] * buffer[0] + buffer[1] * buffer[1]) / 2.0);
        mic2_rms = sqrt((buffer[2] * buffer[2] + buffer[3] * buffer[3]) / 2.0);

        // Log timestamp and RMS levels
        fprintf(fp, "%lu,%f,%f\n", tv.tv_sec + tv.tv_usec / 1000000.0, mic1_rms, mic2_rms);

        // Check if either RMS exceeds high threshold
        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            // Turn on LED
            gpioWrite(fd_led, 1);
            usleep(500000);
            gpioWrite(fd_led, 0);
        }

        // Wait for next sample
        usleep(SAMPLE_RATE);
        gettimeofday(&tv, NULL);
    }

    // Close log file
    fclose(fp);

    // Release resources
    close(fd_mcp3008[0]);
    close(fd_mcp3008[1]);
    gpioClose(fd_led);
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Release resources
    close(fd_mcp3008[0]);
    close(fd_mcp3008[1]);
    gpioClose(fd_led);
    gpioTerminate();

    // Exit
    exit(0);
}

// Register signal handler for SIGINT
void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}
```

This code uses the `pigpio` library to interact with the GPIO pins and the `spidev` device to communicate with the SPI bus. It sets up two SPI devices, one for each microphone, and uses the `spiTransfer` function to acquire samples from both microphones. The RMS level for each channel is computed and logged to a file named `audio_events.csv`. The program also checks if either RMS exceeds a high threshold and turns on an LED for 500 ms if so. The program cleanly handles a SIGINT (Ctrl+C) by turning off the LED and releasing all resources before exiting.

