int main(void) {
    int i, j;
    int gpio = 17;
    int sensor = 0;
    int buffer[BUFFER_SIZE];
    float average = 0.0;
    float current = 0.0;
    int fd;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up warning LED
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up warning LED\n");
        return 1;
    }
    if (gpioSetPullUpDnControl(gpio, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set up pull-up/down control for warning LED\n");
        return 1;
    }
    if (gpioSetAlertFunction(gpio, PI_ALTERA) < 0) {
        fprintf(stderr, "Failed to set up alert function for warning LED\n");
        return 1;
    }
    if (gpioSetAlertThreshold(gpio, 1) < 0) {
        fprintf(stderr, "Failed to set up alert threshold for warning LED\n");
        return 1;
    }

    // Initialize I2C
    if ((fd = i2cOpenBus(I2C_BUS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }
    if ((fd = i2cOpen(fd, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        i2cClose(fd);
        return 1;
    }

    // Initialize ADS1115
    if ((ret = ads1115Init()) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        i2cClose(fd);
        return 1;
    }
    if (ads1115SetMode(ADS1115_REG_CONFIG_MODE) < 0) {
        fprintf(stderr, "Failed to set ADS1115 mode\n");
        i2cClose(fd);
        return 1;
    }
    if (ads1115SetPGA(ADS1115_REG_CONFIG_PGA) < 0) {
        fprintf(stderr, "Failed to set ADS1115 PGA\n");
        i2cClose(fd);
        return 1;
    }
    if (ads1115SetSampleRate(SAMPLE_RATE) < 0) {
        fprintf(stderr, "Failed to set ADS1115 sample rate\n");
        i2cClose(fd);
        return 1;
    }
    if (ads1115SetChannel(0) < 0) {
        fprintf(stderr, "Failed to set ADS1115 channel\n");
        i2cClose(fd);
        return 1;
    }

    // Initialize buffer
    for (i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = 0;
    }

    // Main loop
    while (1) {
        // Read raw value from ADS1115
        if ((ret = ads1115GetRawValue()) < 0) {
            fprintf(stderr, "Failed to read raw value from ADS1115\n");
            i2cClose(fd);
            return 1;
        }

        // Convert raw value to voltage
        if ((current = ads1115GetVoltage()) < 0) {
            fprintf(stderr, "Failed to convert raw value to voltage\n");
            i2cClose(fd);
            return 1;
        }

        // Store current in buffer
        for (j = BUFFER_SIZE - 1; j > 0; j--) {
            buffer[j] = buffer[j - 1];
        }
        buffer[0] = current;

        // Calculate average current
        average = 0.0;
        for (i = 0; i < BUFFER_SIZE; i++) {
            average += buffer[i];
        }
        average /= BUFFER_SIZE;

        // Check if average current exceeds threshold
        if (average > CURRENT_THRESHOLD) {
            // Trigger warning LED
            if (gpioSetAlert(gpio, 1) < 0) {
                fprintf(stderr, "Failed to trigger warning LED\n");
                i2cClose(fd);
                return 1;
            }
        } else {
            // Unset warning LED
            if (gpioUnsetAlert(gpio) < 0) {
                fprintf(stderr, "Failed to unset warning LED\n");
                i2cClose(fd);
                return 1;
            }
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    i2cClose(fd);
    gpioUnexport(gpio);
    gpioUnsetAlert(gpio);
    gpioSetAlert(gpio, 0);
    gpioSetPullUpDnControl(gpio, PI_PUD_OFF);
    gpioSetMode(gpio, PI_INPUT);
    gpioUnexport(gpio);
    gpioInitialise();

    return 0;
}

