    int fd;

    if ((fd = i2cOpenBus(bus)) < 0) {
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

int i2cWriteByte(int file, int reg, int value) {
    union i2c_smbus_data data;

    data.byte = value;
    if (i2c_smbus_write_byte_data(file, reg, &data) < 0) {
        return -1;
    }

    return 0;
}

int i2cReadByte(int file, int reg) {
    union i2c_smbus_data data;

    if (i2c_smbus_read_byte_data(file, reg, &data) < 0) {
        return -1;
    }

    return data.byte;
}

int i2cClose(int file) {
    close(file);
    return 0;
}

int ads1115Init(void) {
    int ret;

    // Reset ADS1115
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG, 0x00)) < 0) {
        return -1;
    }

    // Set mode to continuous conversion
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_OS, 0x01)) < 0) {
        return -1;
    }

    // Set PGA to 1/4x
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_PGA, 0x02)) < 0) {
        return -1;
    }

    // Set sample rate to 860SPS
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_DR, 0x04)) < 0) {
        return -1;
    }

    // Set conversion complete interrupt to 0
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_CQUE, 0x00)) < 0) {
        return -1;
    }

    return 0;
}

int ads1115SetMode(int mode) {
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_OS, mode)) < 0) {
        return -1;
    }

    return 0;
}

int ads1115SetPGA(int pga) {
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_PGA, pga)) < 0) {
        return -1;
    }

    return 0;
}

int ads1115SetSampleRate(int rate) {
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_DR, rate)) < 0) {
        return -1;
    }

    return 0;
}

int ads1115SetChannel(int channel) {
    if ((ret = i2cWriteByte(fd, ADS1115_REG_CONFIG_MUX, channel)) < 0) {
        return -1;
    }

    return 0;
}

int ads1115GetRawValue(void) {
    int value;

    if ((value = i2cReadByte(fd, ADS1115_REG_LO_A)) < 0) {
        return -1;
    }

    return value;
}

int ads1115GetVoltage(void) {
    int raw;
    float voltage;

    if ((raw = ads1115GetRawValue()) < 0) {
        return -1;
    }

    voltage = (raw * 4.096) / 32768.0;

    return voltage;
}

int ads1115GetCurrent(void) {
    float voltage;

    if ((voltage = ads1115GetVoltage()) < 0) {
        return -1;
    }

    return voltage * 5.0;
}
