#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define COLOR_LOG_FILE "color_log.csv"

#define MAX_FAILURES 3

struct tcs34725 {
    int fd;
    int failures;
};

static void cleanup(struct tcs34725 *tcs) {
    if (tcs->fd >= 0) {
        close(tcs->fd);
    }
    free(tcs);
}

static void sigint_handler(int sig) {
    struct tcs34725 *tcs = (struct tcs34725 *) sigaction(SIGINT, NULL, NULL)->sa_data;
    if (tcs) {
        close(tcs->fd);
        fclose(log_file);
        tcs34725_cleanup();
        exit(0);
    }
}

static void sigterm_handler(int sig) {
    struct tcs34725 *tcs = (struct tcs34725 *) sigaction(SIGTERM, NULL, NULL)->sa_data;
    if (tcs) {
        close(tcs->fd);
        fclose(log_file);
        tcs34725_cleanup();
        exit(0);
    }
}

static int tcs34725_init(struct tcs34725 **tcs) {
    *tcs = malloc(sizeof(struct tcs34725));
    if (!(*tcs)) {
        return -1;
    }
    (*tcs)->fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if ((*tcs)->fd < 0) {
        free(*tcs);
        return -1;
    }
    if (ioctl((*tcs)->fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        close((*tcs)->fd);
        free(*tcs);
        return -1;
    }
    if (tcs34725_read((*tcs), 0x80) != 0x44) {
        close((*tcs)->fd);
        free(*tcs);
        return -1;
    }
    return 0;
}

static int tcs34725_read(struct tcs34725 *tcs, uint8_t reg) {
    uint8_t buf[2];
    int ret;
    for (int i = 0; i < MAX_FAILURES; i++) {
        ret = read(tcs->fd, buf, 2);
        if (ret == 2) {
            if (buf[0] == (reg >> 8) && buf[1] == (reg & 0xFF)) {
                return buf[1];
            }
        } else if (ret < 0) {
            if (errno == EIO) {
                tcs->failures++;
                if (tcs->failures >= MAX_FAILURES) {
                    return -1;
                }
            } else {
                return -1;
            }
        } else {
            return -1;
        }
    }
    return -1;
}

static void tcs34725_write(struct tcs34725 *tcs, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    int ret;
    for (int i = 0; i < MAX_FAILURES; i++) {
        ret = write(tcs->fd, buf, 2);
        if (ret == 2) {
            return;
        } else if (ret < 0) {
            if (errno == EIO) {
                tcs->failures++;
                if (tcs->failures >= MAX_FAILURES) {
                    return;
                }
            } else {
                return;
            }
        }
    }
}

static void tcs34725_power_on(struct tcs34725 *tcs) {
    tcs34725_write(tcs, 0x81, 0x03);
}

static void tcs34725_power_off(struct tcs34725 *tcs) {
    tcs34725_write(tcs, 0x81, 0x00);
}

static void tcs34725_reset(struct tcs34725 *tcs) {
    tcs34725_write(tcs, 0x80, 0x00);
}

static void tcs34725_set_integration_time(struct tcs34725 *tcs, uint8_t time) {
    tcs34725_write(tcs, 0x82, time);
}

static void tcs34725_set_gain(struct tcs34725 *tcs, uint8_t gain) {
    tcs34725_write(tcs, 0x83, gain);
}

static void tcs34725_set_integration_time_and_gain(struct tcs34725 *tcs, uint8_t time, uint8_t gain) {
    tcs34725_set_integration_time(tcs, time);
    tcs34725_set_gain(tcs, gain);
}

static void tcs34725_read_color(struct tcs34725 *tcs, uint8_t *clear, uint8_t *red, uint8_t *green, uint8_t *blue) {
    tcs34725_write(tcs, 0x80, 0x00);
    usleep(300000);
    *clear = tcs34725_read(tcs, 0x80);
    *red = tcs34725_read(tcs, 0x81);
    *green = tcs34725_read(tcs, 0x82);
    *blue = tcs34725_read(tcs, 0x83);
}

static void log_color(struct tcs34725 *tcs) {
    uint8_t clear, red, green, blue;
    tcs34725_read_color(tcs, &clear, &red, &green, &blue);
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, clear, red, green, blue);
}

static void log_init() {
    FILE *file = fopen(COLOR_LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for writing\n", COLOR_LOG_FILE);
        exit(1);
    }
    if (fseek(file, 0, SEEK_END) == -1) {
        fprintf(stderr, "Failed to seek to end of %s\n", COLOR_LOG_FILE);
        fclose(file);
        exit(1);
    }
    if (ftell(file) == 0) {
        fprintf(file, "timestamp,clear,red,green,blue\n");
    }
    log_file = file;
}

int main() {
    struct tcs34725 *tcs;
    if (tcs34725_init(&tcs) != 0) {
        fprintf(stderr, "Failed to initialize TCS34725\n");
        return 1;
    }
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    tcs34725_power_on(tcs);
    tcs34725_set_integration_time_and_gain(tcs, 0x00, 0x40);
    log_init();
    while (1) {
        log_color(tcs);
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(STDIN_FILENO, &read_fds);
        struct timeval timeout;
        timeout.tv_sec = 1;
        timeout.tv_usec = 0;
        if (select(STDIN_FILENO + 1, &read_fds, NULL, NULL, &timeout) == 1) {
            break;
        }
        usleep(1000000);
    }
    tcs34725_power_off(tcs);
    fclose(log_file);
    tcs34725_cleanup();
    return 0;
}

