#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define GPIO_CE0 8
#define GPIO_MISO 9
#define GPIO_MOSI 10
#define GPIO_SCLK 11
#define MCP3008_CHANNEL1 0
#define MCP3008_CHANNEL2 1
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 16
#define SPI_LSB_FIRST 0
#define SPI_CS_HIGH 0

#define MAX_READINGS 2

struct spi_ioc_transfer transfer;

void cleanup(int sig) {
    if (transfer.fd != -1) {
        close(transfer.fd);
    }
    if (transfer.driver_data != NULL) {
        free(transfer.driver_data);
    }
    exit(0);
}

int main() {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST) == -1) {
        perror("Failed to set SPI LSB first");
        close(spi_fd);
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) == -1) {
        perror("Failed to set SPI CS high");
        close(spi_fd);
        exit(1);
    }

    transfer.fd = spi_fd;
    transfer.tx_buf = (unsigned long)malloc(SPI_BITS_PER_WORD);
    transfer.rx_buf = (unsigned long)malloc(SPI_BITS_PER_WORD);
    transfer.len = SPI_BITS_PER_WORD;
    transfer.speed_hz = SPI_SPEED;
    transfer.delay_usecs = 0;
    transfer.cs_us = 0;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.mode = SPI_MODE;
    transfer.cs_high = SPI_CS_HIGH;

    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        close(spi_fd);
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        close(spi_fd);
        exit(1);
    }

    FILE *log_file = fopen("moisture_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        exit(1);
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint16_t readings[MAX_READINGS];
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1, &transfer, readings, sizeof(readings)));
        if (ret == -1) {
            perror("Failed to read from SPI");
            close(spi_fd);
            fclose(log_file);
            exit(1);
        }

        for (int i = 0; i < MAX_READINGS; i++) {
            if (readings[i] == 0xFFFF) {
                fprintf(log_file, "%ld,%d,%d\n", tv.tv_sec, 0, 0);
            } else {
                fprintf(log_file, "%ld,%d,%d\n", tv.tv_sec, readings[MCP3008_CHANNEL1], readings[MCP3008_CHANNEL2]);
            }
        }

        sleep(5);
    }

    fclose(log_file);
    close(spi_fd);
    free(transfer.tx_buf);
    free(transfer.rx_buf);
    return 0;
}

