#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PRESSURE_LOG_FILE "pressure_log.csv"
#define PRESSURE_LOG_HEADER "timestamp,pressure (kPa)\n"

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void cleanup(void) {
    if (i2c_fd != -1) {
        gpiod_close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

static void sigterm_handler(int sig) {
    cleanup();
    exit(0);
}

static int i2c_open(void) {
    struct i2c_adapter *adapter;
    struct i2c_client *client;
    int ret;

    adapter = gpiod_find_adapter_by_name("i2c-1");
    if (adapter == NULL) {
        fprintf(stderr, "Error: Unable to find I2C adapter\n");
        return -1;
    }

    client = gpiod_client_new(adapter, I2C_ADDRESS);
    if (client == NULL) {
        fprintf(stderr, "Error: Unable to create I2C client\n");
        gpiod_adapter_put(adapter);
        return -1;
    }

    ret = gpiod_client_open(client, O_RDWR);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to open I2C client: %s\n", strerror(-ret));
        gpiod_client_put(client);
        gpiod_adapter_put(adapter);
        return -1;
    }

    i2c_fd = gpiod_client_get_fd(client);
    gpiod_client_put(client);
    gpiod_adapter_put(adapter);

    return 0;
}

static int i2c_read(uint8_t reg, uint8_t *buf, size_t len) {
    int ret;

    ret = gpiod_i2c_read(i2c_fd, reg, buf, len);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to read from I2C bus: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

static int log_pressure(double pressure) {
    char timestamp[32];
    char buffer[64];

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    sprintf(buffer, "%s,%.2f\n", timestamp, pressure);

    if (log_file == NULL) {
        log_file = fopen(PRESSURE_LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Unable to open log file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "%s", PRESSURE_LOG_HEADER);
        fflush(log_file);
    }

    if (fputs(buffer, log_file) == EOF) {
        fprintf(stderr, "Error: Unable to write to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    uint8_t reg;
    uint8_t buf[2];
    double pressure;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (i2c_open() < 0) {
        return 1;
    }

    while (1) {
        ret = i2c_read(0x00, buf, 2);
        if (ret < 0) {
            if (errno == EIO) {
                // Sensor absent, try to open I2C client again
                i2c_close();
                if (i2c_open() < 0) {
                    break;
                }
                continue;
            } else {
                break;
            }
        }

        pressure = (buf[0] << 8 | buf[1]) / 32768.0;

        ret = log_pressure(pressure);
        if (ret < 0) {
            break;
        }

        sleep(1);
    }

    cleanup();

    return 0;
}

