#define TEMPERATURE_CHANNEL 1
#define GPIO_LED 17
#define MAX_RETRIES 3

int i2c_fd;
int gpio_fd;
int pressure;
float temperature;

void cleanup() {
    if (gpio_fd != -1) {
        gpiod_close(gpio_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

void sigint_handler(int sig) {
    cleanup();
}

int read_i2c(int address, uint8_t reg, uint8_t* data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
            if (errno == EBUSY) {
                retries++;
                usleep(100000);
                continue;
            } else {
                perror("ioctl");
                return -1;
            }
        }
        if (i2c_smbus_write_byte(i2c_fd, reg) < 0) {
            perror("i2c_smbus_write_byte");
            return -1;
        }
        if (i2c_smbus_read_byte_data(i2c_fd, reg, data) < 0) {
            perror("i2c_smbus_read_byte_data");
            return -1;
        }
        return 0;
    }
    return -1;
}

int main() {
    struct gpiod_line_request req;
    struct gpiod_line* line;
    int ret;

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    gpio_fd = gpiod_open("/sys/class/gpio/export");
    if (gpio_fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    req.request.line = "gpio17";
    req.request.type = GPIOD_LINE_REQ_DIR_OUT;
    req.request.consumer = "pressure_monitor";
    ret = gpiod_line_request(&req, &line);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_close(gpio_fd);
        return 1;
    }

    gpiod_line_set_value(line, 1);

    while (1) {
        uint8_t data[2];
        if (read_i2c(ADS1115_ADDRESS, 0x00, data, 2) < 0) {
            continue;
        }
        if (read_i2c(ADS1115_ADDRESS, 0x01, data, 2) < 0) {
            continue;
        }
        if (read_i2c(MLX90834_ADDRESS, 0x00, data, 1) < 0) {
            continue;
        }
        if (read_i2c(MLX90834_ADDRESS, 0x01, data, 1) < 0) {
            continue;
        }

        pressure = (data[0] << 8) | data[1];
        temperature = (data[1] << 8) | data[0];

        pressure = (pressure >> 3) * 0.00006103515625;
        temperature = (temperature >> 3) * 0.0625;

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > 105.0) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

