#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define LOG_FILE "co_log.txt"
#define GPIO_ALARM 4
#define GPIO_CE 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SAMPLING_RATE 1000

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    gpiod_close(gpio_handle);
    fclose(log_file);
    gpiod_line_set_value(gpio_handle, GPIO_ALARM, 0);
    gpiod_cleanup();
    exit(0);
}

int main() {
    // Initialize logging
    openlog(NULL, LOG_PID, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));

    // Initialize GPIO
    gpio_handle = gpiod_init();
    if (gpio_handle == NULL) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }

    // Set up GPIO alarm pin as output
    gpio_line = gpiod_line_request_output(gpio_handle, GPIO_ALARM, "alarm");
    if (gpio_line == NULL) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_cleanup();
        exit(1);
    }

    // Set up SPI
    spi_handle = gpiod_spi_new();
    if (spi_handle == NULL) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        gpiod_line_release(gpio_line);
        gpiod_cleanup();
        exit(1);
    }

    // Set up SPI configuration
    spi_config = gpiod_spi_new_config();
    if (spi_config == NULL) {
        syslog(LOG_ERR, "Failed to create SPI configuration");
        gpiod_spi_unref(spi_handle);
        gpiod_line_release(gpio_line);
        gpiod_cleanup();
        exit(1);
    }

    gpiod_spi_config_set_speed(spi_config, SPI_SPEED);
    gpiod_spi_config_set_mode(spi_config, SPI_MODE);
    gpiod_spi_config_set_chip_select(spi_config, GPIO_CE);
    gpiod_spi_config_set_chip_select_active_high(spi_config, true);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_spi_unref(spi_config);
        gpiod_spi_unref(spi_handle);
        gpiod_line_release(gpio_line);
        gpiod_cleanup();
        exit(1);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read SPI
        uint8_t data[2];
        if (gpiod_spi_transfer(spi_handle, data, 2, spi_config) != 0) {
            syslog(LOG_ERR, "SPI transfer failed");
            sleep(1);
            continue;
        }

        // Calculate voltage
        uint16_t voltage = (data[0] << 8) | data[1];
        float voltage_f = (float)voltage / 1024.0 * 3.3;

        // Log data
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage_f);

        // Turn on/off alarm
        if (voltage_f > 2.5) {
            gpiod_line_set_value(gpio_handle, GPIO_ALARM, 1);
        } else {
            gpiod_line_set_value(gpio_handle, GPIO_ALARM, 0);
        }

        // Sleep
        sleep(SAMPLING_RATE);
    }

    // Cleanup
    fclose(log_file);
    gpiod_spi_unref(spi_config);
    gpiod_spi_unref(spi_handle);
    gpiod_line_release(gpio_line);
    gpiod_cleanup();
    closelog();

    return 0;
}

