#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS GPIO_PIN_8
#define SPI_CLK GPIO_PIN_11
#define SPI_MISO GPIO_PIN_9
#define SPI_MOSI GPIO_PIN_10

#define LOG_FILE "methane_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int spi_open() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)malloc(2),
        .rx_buf = (unsigned long)malloc(2),
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Failed to configure SPI transfer\n");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_read(int fd) {
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)malloc(2),
        .rx_buf = (unsigned long)malloc(2),
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Failed to read from SPI device\n");
        close(fd);
        return -1;
    }

    uint16_t value = *(uint16_t*)xfer.rx_buf;
    free(xfer.tx_buf);
    free(xfer.rx_buf);
    return value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);

    int fd = spi_open();
    if (fd < 0) {
        return 1;
    }

    struct tm time;
    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        uint16_t value = spi_read(fd);
        if (value < 0) {
            continue;
        }

        struct tm* local_time;
        time_t raw_time = time(NULL);
        localtime_r(&raw_time, &local_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file);

        if (value > 1000) {
            fprintf(stderr, "Methane leak detected: %d ppm\n", value);
        }

        sleep(1);
    }

    fclose(log_file);
    close(fd);
    gpioTerminate();

    return 0;
}

