// Define the SPI bus and chip-select pin
#define SPI_BUS 0
#define CHIP_SELECT 8

// Define the ADC channel and gain
#define ADC_CHANNEL 0
#define ADC_GAIN 1

// Define the email alert threshold
#define HUMIDITY_THRESHOLD 80

// Define the email alert subject and body
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeded 80% threshold"

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Release resources
    gpioTerminate();
    syslog(LOG_INFO, "Released resources");
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library: %s", strerror(errno));
        exit(1);
    }

    // Set up the chip-select pin as an output
    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up chip-select pin: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Initialize the ADC driver
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set up the SPI bus
    if (ioctl(adc_fd, SPI_IOC_WR_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set up SPI bus: %s", strerror(errno));
        close(adc_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up the chip-select pin as an output
    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up chip-select pin: %s", strerror(errno));
        close(adc_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handler: %s", strerror(errno));
        close(adc_fd);
        gpioTerminate();
        exit(1);
    }

    // Open the log file
    FILE *log_file = fopen("humidity_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(adc_fd);
        gpioTerminate();
        exit(1);
    }

    // Main loop
    while (1) {
        // Select the chip-select pin high
        gpioWrite(CHIP_SELECT, 1);

        // Select the ADC channel and gain
        uint8_t config = (ADC_CHANNEL << 4) | (ADC_GAIN << 2);
        if (write(adc_fd, &config, 1) < 0) {
            syslog(LOG_ERR, "Failed to write to SPI device: %s", strerror(errno));
            close(adc_fd);
            gpioTerminate();
            exit(1);
        }

        // Wait for the conversion to complete
        usleep(100000);

        // Select the chip-select pin low
        gpioWrite(CHIP_SELECT, 0);

        // Read the ADC value
        uint16_t adc_value;
        if (read(adc_fd, &adc_value, 2) < 0) {
            syslog(LOG_ERR, "Failed to read from SPI device: %s", strerror(errno));
            close(adc_fd);
            gpioTerminate();
            exit(1);
        }

        // Convert the ADC value to a humidity and temperature reading
        float humidity = (adc_value * 100.0) / 4096.0;
        float temperature = (adc_value * 100.0) / 4096.0;

        // Append the reading to the log file
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        sprintf(buffer, "%s,%.2f,%.2f\n", buffer, humidity, temperature);
        if (fputs(buffer, log_file) < 0) {
            syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
            close(adc_fd);
            gpioTerminate();
            exit(1);
        }

        // Check if the humidity value exceeds the threshold
        if (humidity > HUMIDITY_THRESHOLD) {
            // Send an email alert
            FILE *email_file = popen("ssmtp -t < email_template.txt", "w");
            if (!email_file) {
                syslog(LOG_ERR, "Failed to open email file: %s", strerror(errno));
                close(adc_fd);
                gpioTerminate();
                exit(1);
            }
            fprintf(email_file, "Subject: %s\n", EMAIL_SUBJECT);
            fprintf(email_file, "%s", EMAIL_BODY);
            pclose(email_file);
        }

        // Sleep for 10 seconds
        usleep(10000000);
    }

    // Release resources
    close(adc_fd);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

