#define LOG_FILE "temperature_log.csv"
#define ADC_CHANNEL 0
#define ADC_VREF 3300.0
#define ADC_RESOLUTION 12
#define ADC_MAX 4095
#define TMP36_OFFSET 0.5
#define TMP36_GAIN 100.0
#define TMP36_MIN -40.0
#define TMP36_MAX 125.0

int spi_fd;
int gpio_fd;
int gpio_ce0;
int gpio_sclk;
int gpio_mosi;
int gpio_miso;
bool log_file_open = false;
FILE *log_file;

void cleanup(int sig) {
    if (log_file_open) {
        fclose(log_file);
        log_file_open = false;
    }
    if (gpio_fd >= 0) {
        gpio_set_value(gpio_ce0, 0);
        gpio_unexport(gpio_ce0);
        gpio_unexport(gpio_sclk);
        gpio_unexport(gpio_mosi);
        gpio_unexport(gpio_miso);
        close(gpio_fd);
        gpio_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    exit(0);
}

int main() {
    struct spi_ioc_transfer xfer;
    struct gpiohandle_request gpio_request;
    struct gpiohandle_data gpio_data;
    char timestamp[20];
    time_t now;
    int ret;

    // Initialize GPIO
    gpio_ce0 = gpio_to_chip(gpio_request.gpio, 4);
    gpio_sclk = gpio_to_chip(gpio_request.gpio, 11);
    gpio_mosi = gpio_to_chip(gpio_request.gpio, 10);
    gpio_miso = gpio_to_chip(gpio_request.gpio, 9);
    gpio_request.mode = GPIOF_OUT_INIT;
    gpio_request.flags = GPIOF_EXPORT;
    gpio_request.lineoffset = 0;
    gpio_request.length = 4;
    gpio_request.default_value = 0;
    gpio_request.debounce = 0;
    gpio_request.flags |= GPIOF_EXPORT;
    ret = gpio_request(gpio_fd, &gpio_request);
    if (ret < 0) {
        perror("gpio_request");
        return 1;
    }
    gpio_set_value(gpio_ce0, 1);
    gpio_set_value(gpio_sclk, 0);
    gpio_set_value(gpio_mosi, 0);
    gpio_set_value(gpio_miso, 0);

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 2;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 1;
    xfer.cs_high = 1;
    xfer.cs_low = 1;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &xfer.cs_high);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &xfer.bits_per_word);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &xfer.speed_hz);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_file = fopen(LOG_FILE, "w");
        log_file_open = true;
    }

    // Signal handling
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Read ADC value
        xfer.tx_buf = 0;
        xfer.rx_buf = 0;
        xfer.len = 2;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("ioctl");
            cleanup(0);
        }
        uint16_t adc_value = *(uint16_t *)xfer.rx_buf;

        // Validate ADC reading
        if (adc_value > ADC_MAX) {
            printf("ADC out of range: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to temperature
        float temperature_celsius = (adc_value * ADC_VREF / ADC_MAX - TMP36_OFFSET) / TMP36_GAIN + TMP36_MIN;

        // Log temperature
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature_celsius);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
