        spi_transfer.delay_usecs = 0;
        spi_transfer.bits_per_word = 16;
        spi_transfer.mode = 0;

        // Read Z axis
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &spi_transfer) < 0)) {
            fprintf(stderr, "Failed to read Z axis\n");
            free(spi_transfer.tx_buf);
            free(spi_transfer.rx_buf);
            fclose(log_file);
            close(spi_fd);
            gpioTerminate();
            return 1;
        }

        int16_t z = (spi_transfer.rx_buf[0] << 8) | spi_transfer.rx_buf[1];

        // Select chip-select line low
        gpioWrite(8, 0);

        // Validate ADC values
        if (x < 0 || x > 1023 || y < 0 || y > 1023 || z < 0 || z > 1023) {
            fprintf(stderr, "Invalid ADC value\n");
            free(spi_transfer.tx_buf);
            free(spi_transfer.rx_buf);
            fclose(log_file);
            close(spi_fd);
            gpioTerminate();
            return 1;
        }

        // Log ADC values
        fprintf(log_file, "%d,%d,%d\n", x, y, z);

        // Check for impact
        if (x > ADC_THRESHOLD || y > ADC_THRESHOLD || z > ADC_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        // Sleep for sample period
        usleep(100000 / SAMPLE_RATE);
    }

    // Close log file
    fclose(log_file);

    // Close SPI device
    close(spi_fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
