#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x3C
#define I2C_TIMEOUT 1000
#define LOG_FILE "biometric_log.csv"
#define LOG_HEADER "Unix timestamp,HR (bpm),SpO₂ (%),Error flag\n"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int ret;
    char log_buffer[256];
    uint16_t ir_adc, red_adc;
    uint8_t status;
    uint16_t hr, spo2;
    struct i2c_msg msg;
    struct i2c_msg msg2;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_smbus_ioctl_data i2c_ioctl_data;
    struct stat sb;
    FILE *log_file;

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Check if log file exists and truncate it
    if (stat(LOG_FILE, &sb) == 0) {
        if (unlink(LOG_FILE) < 0) {
            fprintf(stderr, "Failed to truncate log file\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Open log file for writing
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    if (fprintf(log_file, LOG_HEADER) < 0) {
        fprintf(stderr, "Failed to write log header\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize I2C device\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    while (running) {
        // Read IR and RED ADC values
        msg.msg_type = I2C_MSG_READ;
        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.len = 2;
        msg.buf = &ir_adc;
        msg2.msg_type = I2C_MSG_READ;
        msg2.addr = I2C_ADDRESS;
        msg2.flags = 0;
        msg2.len = 2;
        msg2.buf = &red_adc;

        i2c_data.msgs = &msg;
        i2c_data.nmsgs = 1;
        i2c_data.msgs[1] = &msg2;
        i2c_data.nmsgs++;

        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            if (errno == EIO) {
                // Transient I2C error, try again
                usleep(I2C_TIMEOUT);
                continue;
            } else if (errno == ENXIO) {
                // I2C device not found, write error row to log file
                fprintf(log_file, "%lu,0,0,2\n", time(NULL));
                continue;
            } else {
                // Other I2C error, write error row to log file
                fprintf(log_file, "%lu,0,0,1\n", time(NULL));
                continue;
            }
        }

        // Read status register
        i2c_ioctl_data.read_buf = &status;
        i2c_ioctl_data.read_len = 1;
        i2c_ioctl_data.write_len = 0;
        i2c_ioctl_data.addr = I2C_ADDRESS;
        i2c_ioctl_data.cmd = 0x00;
        ret = ioctl(i2c_fd, I2C_SMBUS_READ, &i2c_ioctl_data);
        if (ret < 0) {
            if (errno == EIO) {
                // Transient I2C error, try again
                usleep(I2C_TIMEOUT);
                continue;
            } else if (errno == ENXIO) {
                // I2C device not found, write error row to log file
                fprintf(log_file, "%lu,0,0,2\n", time(NULL));
                continue;
            } else {
                // Other I2C error, write error row to log file
                fprintf(log_file, "%lu,0,0,1\n", time(NULL));
                continue;
            }
        }

        // Convert raw ADC values to HR and SpO₂ (note: this is a simplified implementation and actual conversion may require more complex algorithm)
        hr = ir_adc;
        spo2 = red_adc;

        // Write log row to file
        if (fprintf(log_file, "%lu,%u,%u,0\n", time(NULL), hr, spo2) < 0) {
            fprintf(stderr, "Failed to write log row\n");
            fclose(log_file);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Flush log file
        if (fflush(log_file) < 0) {
            fprintf(stderr, "Failed to flush log file\n");
            fclose(log_file);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

