        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI mode and clock speed
    if (gpioSetMode(spi_fd, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockSpeed(spi_fd, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

