        // Validate the flow rate
        if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
            fprintf(stderr, "Invalid flow rate: %.2f L/min\n", flow_rate);
            continue;
        }

        // Get the current time
        time_t now = time(NULL);
        localtime_r(&now, &time_info);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S.%06u,%.2f", &time_info, flow_rate);

        // Log the measurement
        fprintf(log_file, "%s\n", log_line);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    gpioClose(spi_fd);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

