#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define MEASUREMENT_COMMAND 0x00
#define PRESSURE_MSB 0x00
#define PRESSURE_LSB 0x01
#define TEMPERATURE_MSB 0x02
#define TEMPERATURE_LSB 0x03
#define CRC1 0x04
#define CRC2 0x05

#define CSV_FILE "environmental_data.csv"

#define PRESSURE_CALIBRATION 32768.0
#define TEMPERATURE_CALIBRATION 2000.0
#define PRESSURE_OFFSET 0.0
#define TEMPERATURE_OFFSET 0.0

volatile bool running = true;

void signal_handler(int signal) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("i2c_write: ioctl");
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        perror("i2c_write: write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t address, uint8_t* buffer, int size) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("i2c_read: ioctl");
        return -1;
    }
    if (read(fd, buffer, size) != size) {
        perror("i2c_read: read");
        return -1;
    }
    return 0;
}

double calculate_pressure(uint16_t msb, uint16_t lsb) {
    return (msb << 8 | lsb) * PRESSURE_CALIBRATION / PRESSURE_OFFSET;
}

double calculate_temperature(uint16_t msb, uint16_t lsb) {
    return (msb << 8 | lsb) * TEMPERATURE_CALIBRATION / TEMPERATURE_OFFSET;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    FILE* csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_write(fd, I2C_ADDRESS, MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Error: unable to write to I2C bus\n");
            sleep(5);
            continue;
        }

        uint8_t buffer[6];
        if (i2c_read(fd, I2C_ADDRESS, buffer, 6) < 0) {
            fprintf(stderr, "Error: unable to read from I2C bus\n");
            sleep(5);
            continue;
        }

        double pressure = calculate_pressure(buffer[PRESSURE_MSB], buffer[PRESSURE_LSB]);
        double temperature = calculate_temperature(buffer[TEMPERATURE_MSB], buffer[TEMPERATURE_LSB]);

        fprintf(csv_file, "%f,%f\n", pressure, temperature);
        fprintf(stderr, "Pressure: %f Pa, Temperature: %f C\n", pressure, temperature);

        sleep(5);
    }

    fclose(csv_file);
    close(fd);
    return 0;
}

