#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <getopt.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the SPI configuration
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0

// Define the MCP3008 channel configuration
#define MCP3008_CHANNEL_A0 0
#define MCP3008_CHANNEL_A1 1

// Define the gain control values
#define MIN_GAIN 0
#define MAX_GAIN 10
#define DEFAULT_GAIN 5

// Define the noise-cancellation algorithm parameters
#define NOISE_CANCELLATION_WINDOW_SIZE 10
#define NOISE_CANCELLATION_ALPHA 0.5

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Release resources
    gpioTerminate();
    exit(0);
}

int main(int argc, char **argv) {
    // Parse command-line arguments
    int gain = DEFAULT_GAIN;
    int c;
    while ((c = getopt(argc, argv, "g:")) != -1) {
        switch (c) {
            case 'g':
                gain = atoi(optarg);
                if (gain < MIN_GAIN || gain > MAX_GAIN) {
                    fprintf(stderr, "Invalid gain value. Using default value.\n");
                    gain = DEFAULT_GAIN;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-g <gain>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        return 1;
    }

    // Set up SPI0 CE0/GPIO8
    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up SPI0 CE0/GPIO8.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (spiOpen(0, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MCP3008 channels
    int channel_a0 = spiXfer(0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
    int channel_a1 = spiXfer(0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);

    // Initialize noise-cancellation buffer
    int noise_cancellation_buffer[NOISE_CANCELLATION_WINDOW_SIZE];

    // Main loop
    while (1) {
        // Read audio samples from MCP3008 channels
        int sample_a0 = spiXfer(0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        int sample_a1 = spiXfer(0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);

        // Apply noise-cancellation algorithm
        int noise_cancellation_sum = 0;
        for (int i = 0; i < NOISE_CANCELLATION_WINDOW_SIZE; i++) {
            noise_cancellation_sum += noise_cancellation_buffer[i];
        }
        noise_cancellation_sum *= NOISE_CANCELLATION_ALPHA;
        noise_cancellation_buffer[NOISE_CANCELLATION_WINDOW_SIZE - 1] = sample_a0 - sample_a1 + noise_cancellation_sum;
        for (int i = 0; i < NOISE_CANCELLATION_WINDOW_SIZE - 1; i++) {
            noise_cancellation_buffer[i] = noise_cancellation_buffer[i + 1];
        }

        // Print audio samples to terminal in CSV format
        printf("%d,%d\n", sample_a0, sample_a1);

        // Sleep for 1 ms
        usleep(1000);
    }

    // Release resources
    spiClose(0);
    gpioTerminate();

    return 0;
}

