#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>

#define LOG_FILE "flame_log.txt"
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define DEFAULT_AMBIENT_TEMP 25.0
#define RETRY_COUNT 3

// Structure to hold ADC data
typedef struct {
    uint8_t start;
    uint8_t single_ended;
    uint8_t dummy;
} adc_data_t;

// Function to read ambient temperature from file
float read_ambient_temp() {
    FILE *file = fopen("ambient_temp.txt", "r");
    if (!file) {
        return DEFAULT_AMBIENT_TEMP;
    }

    char buffer[10];
    if (fscanf(file, "%f", buffer) != 1) {
        fclose(file);
        return DEFAULT_AMBIENT_TEMP;
    }

    float temp = atof(buffer);
    fclose(file);
    return temp;
}

// Function to perform SPI transfer
int spi_transfer(int fd, uint8_t *data, int len) {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)data;
    xfer.rx_buf = (unsigned long)data;
    xfer.len = len;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;
    xfer.delay_usecs = 0;
    xfer.cs_high_pre = 0;
    xfer.cs_low_pre = 0;
    xfer.cs_active_high = 0;

    return ioctl(fd, SPI_IOC_MESSAGE(1), &xfer);
}

// Function to log data to file
void log_data(float voltage, float compensated_voltage, bool flame_detected) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }

    char buffer[50];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
    fprintf(file, "%s,raw_adc=%d,voltage=%.2f,compensated_voltage=%.2f,temperature=%.2f,flame_detected=%d\n",
            buffer, ADC_MAX - voltage, voltage, compensated_voltage, read_ambient_temp(), flame_detected);
    fclose(file);
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    syslog(LOG_INFO, "SIGINT received, stopping sampling loop");
    log_data(0, 0, false);
    syslog(LOG_INFO, "Buzzer turned OFF");
    gpio_set_level(BUZZER_GPIO, 0);
    syslog(LOG_INFO, "Closing log file");
    fclose(log_data_file);
    syslog(LOG_INFO, "Releasing driver resources");
    close(fd);
    exit(0);
}

int main() {
    // Initialize logging
    openlog("flame_sensor", LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize GPIO
    int gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }

    // Initialize SPI
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        gpio_release(gpio_fd);
        exit(1);
    }

    // Set SPI mode
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)&xfer;
    xfer.rx_buf = (unsigned long)&xfer;
    xfer.len = sizeof(xfer);
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;
    xfer.delay_usecs = 0;
    xfer.cs_high_pre = 0;
    xfer.cs_low_pre = 0;
    xfer.cs_active_high = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &xfer.mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(fd);
        gpio_release(gpio_fd);
        exit(1);
    }

    // Initialize buzzer
    gpio_set_direction(BUZZER_GPIO, GPIO_OUT);
    gpio_set_level(BUZZER_GPIO, 1);

    // Open log file
    log_data_file = fopen(LOG_FILE, "a");
    if (!log_data_file) {
        syslog(LOG_ERR, "Failed to open log file");
        close(fd);
        gpio_release(gpio_fd);
        exit(1);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main sampling loop
    while (1) {
        // Read ADC value
        adc_data_t data;
        data.start = 0x40;
        data.single_ended = 0x01;
        data.dummy = 0x00;
        int retry_count = 0;
        while (1) {
            if (spi_transfer(fd, (uint8_t *)&data, 3) < 0) {
                syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
                gpio_set_level(BUZZER_GPIO, 0);
                continue;
            }

            uint16_t adc_value = (data.rx[0] << 8) | data.rx[1];
            if (adc_value < 0 || adc_value > ADC_MAX) {
                syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
                if (++retry_count < RETRY_COUNT) {
                    continue;
                } else {
                    syslog(LOG_ERR, "Abandoning iteration");
                    break;
                }
            }

            // Temperature compensation
            float voltage = (adc_value / (float)ADC_MAX) * 3.3;
            float compensated_voltage = voltage / (1 + (voltage / 1000.0 * read_ambient_temp()));

            // Log data
            log_data(voltage, compensated_voltage, compensated_voltage > 1.5);

            // Buzzer control
            gpio_set_level(BUZZER_GPIO, compensated_voltage > 1.5);

            break;
        }

        // Sleep for 500ms
        usleep(500000);
    }

    // Release resources
    close(fd);
    gpio_release(gpio_fd);
    fclose(log_data_file);
    closelog();

    return 0;
}

