#define JSON_FILE "water_levels.json"
#define LED_PIN 17
#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_MISO_PIN 9
#define ADC_MOSI_PIN 10
#define ADC_SCLK_PIN 11
#define ADC_SPEED 1000000
#define ADC_MODE 0
#define ADC_HYST 5

int main() {
    int spi_fd;
    int gpio_fd;
    int led_state = 0;
    int last_level = 0;
    json_object *json_root = NULL;
    json_object *json_array = NULL;
    json_object *json_level = NULL;
    json_object *json_timestamp = NULL;
    struct timeval last_read_time;
    struct timeval current_time;
    char buffer[20];

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", gpio_fd);
        return 1;
    }

    // Set up LED pin as output
    if (gpioSetMode(led_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin: %d\n", gpioError());
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_fd = spidevOpen(0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI parameters
    if (spidevSetSpeed(spi_fd, ADC_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %d\n", spidevError(spi_fd));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (spidevSetMode(spi_fd, ADC_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %d\n", spidevError(spi_fd));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open JSON file for appending
    FILE *json_file = fopen(JSON_FILE, "a");
    if (!json_file) {
        fprintf(stderr, "Failed to open JSON file: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize JSON
    json_root = json_object_new_object();
    json_array = json_object_new_array();
    json_object_object_add(json_root, "water_levels", json_array);

    while (1) {
        // Read current time
        gettimeofday(&current_time, NULL);

        // Read ADC value
        int adc_value = spidevTransfer(spi_fd, ADC_CHANNEL, 1);
        if (adc_value < 0) {
            fprintf(stderr, "SPI transfer error: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to percentage
        int level = (adc_value * 100) / 1024;

        // Check if level has changed
        if (level > last_level + ADC_HYST || level < last_level - ADC_HYST) {
            // Update LED state
            if (level > 75 && led_state == 0) {
                gpioWrite(led_pin, 1);
                led_state = 1;
            } else if (level <= 70 && led_state == 1) {
                gpioWrite(led_pin, 0);
                led_state = 0;
            }

            // Create JSON object
            json_level = json_object_new_int(level);
            json_timestamp = json_object_new_string(gettimeofday_to_iso8601(&current_time));
            json_object_array_add(json_array, json_level);
            json_object_array_add(json_array, json_timestamp);

            // Write JSON to file
            fprintf(json_file, "{\"level\": %d, \"timestamp\": \"%s\"}\n", level, json_object_get_string(json_timestamp));
            fflush(json_file);
        }

        // Update last level
        last_level = level;

        // Sleep for 5 seconds
        struct timeval sleep_time;
        sleep_time.tv_sec = 5;
        sleep_time.tv_usec = 0;
        while (select(0, NULL, NULL, NULL, &sleep_time) == -1 && errno == EINTR) {
            sleep_time.tv_sec = 0;
            sleep_time.tv_usec = 100000;
        }
    }

    // Close JSON file
    fclose(json_file);

    // Close SPI handle
    spidevClose(spi_fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

char *gettimeofday_to_iso8601(struct timeval *tv) {
    static char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%03dZ", localtime(&tv->tv_sec));
    return buffer;
}

