#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1024
#define ADC_MIN 0
#define ADC_RESOLUTION (1 << ADC_BITS)
#define ADC_VOLTAGE_MAX 5.0
#define ADC_VOLTAGE_MIN 0.0
#define ADC_LPM_MAX 1000.0
#define ADC_LPM_MIN 0.0
#define ADC_LPM_RESOLUTION (ADC_LPM_MAX - ADC_LPM_MIN) / (ADC_MAX - ADC_MIN)
#define SAMPLE_INTERVAL 100000  // 100ms
#define CSV_FILE "airflow_log.csv"

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int gpio_fd;
    uint8_t buffer[2];
    uint16_t adc_value;
    struct tm time;
    char timestamp[20];
    FILE *file;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioError(gpio_fd));
        return 1;
    }

    // Initialize SPI
    spi_fd = spidevOpen(0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode and clock speed
    if (spidevSetMode(spi_fd, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (spidevSetClock(spi_fd, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(24, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 24 as output: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 23 as output: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(19, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 19 as output: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(21, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 21 as input: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(21, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO pin 21: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    file = fopen(CSV_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spidevClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(file, "timestamp,lpm\n");

    while (running) {
        // Read ADC value
        buffer[0] = 0x01;  // Start bit
        buffer[1] = 0x00;  // Channel 0
        if (spidevXfer(spi_fd, buffer, buffer, 2) < 0) {
            fprintf(stderr, "Failed to read from ADC: %s\n", strerror(errno));
            break;
        }
        adc_value = (buffer[1] & 0x03) << 8 | buffer[0];

        // Convert ADC value to LPM
        float lpm = (adc_value * ADC_LPM_RESOLUTION / ADC_RESOLUTION) + ADC_LPM_MIN;

        // Get current time
        time = *localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &time);

        // Write to log file
        fprintf(file, "%s,%f\n", timestamp, lpm);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close log file
    fclose(file);

    // Release SPI handle
    spidevClose(spi_fd);

    // Release GPIO handle
    gpioTerminate();

    return 0;
}

