int main(int argc, char **argv) {
    int spi_channel = 0;
    int adc_channel = 0;
    int min_cal = 0;
    int max_cal = 100;
    struct sigaction sa;
    struct tm *timeinfo;
    time_t rawtime;
    char buffer[256];
    char *line;
    FILE *fp;
    int fd;
    int ret;
    int moisture;
    char email_body[256];

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--spi-channel") == 0) {
            spi_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--adc-channel") == 0) {
            adc_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--min-cal") == 0) {
            min_cal = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--max-cal") == 0) {
            max_cal = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--threshold") == 0) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--log-interval") == 0) {
            log_interval = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--email-addr") == 0) {
            email_addr = argv[++i];
        } else if (strcmp(argv[i], "--msmtp-config") == 0) {
            msmtp_config = argv[++i];
        }
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO
    if ((fd = gpiod_open("/dev/spidev0.0")) < 0) {
        perror("gpiod_open");
        exit(1);
    }

    // Initialize SPI
    if (gpiod_spi_setup(fd, 500000, 0, 0, 0) < 0) {
        perror("gpiod_spi_setup");
        gpiod_close(fd);
        exit(1);
    }

    // Initialize ADC
    if (gpiod_adc_setup(fd, adc_channel, 0) < 0) {
        perror("gpiod_adc_setup");
        gpiod_close(fd);
        exit(1);
    }

    // Open log file
    if ((fp = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        gpiod_close(fd);
        gpiod_driver_unregister();
        exit(1);
    }

    // Main loop
