        // Calculate moisture percentage
        moisture = (moisture * 100) / (max_cal - min_cal);

        // Log data
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(fp, "%s, %d\n", buffer, moisture);
        fflush(fp);

