#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define ADC_CHANNEL 0
#define ADC_CLOCK_SPEED 1000000
#define ADC_TRANSFER_SIZE 3
#define ADC_BITS 10
#define ADC_MAX 1023
#define MOISTURE_MAX 100

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd = -1;
    int gpio_fd = -1;
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set up SPI parameters
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = ADC_TRANSFER_SIZE;
    xfer.speed_hz = ADC_CLOCK_SPEED;
    xfer.bits_per_word = 8;

    // Set up GPIO pins
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(spi_fd);
        return 1;
    }

    // Export GPIO pins
    ret = ioctl(gpio_fd, GPIO_LINE_REQUEST, GPIO_CE0);
    if (ret < 0) {
        perror("Failed to export GPIO pin");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set GPIO pin direction
    ret = ioctl(gpio_fd, GPIO_SET_LINE_DIRECTION, GPIO_CE0, GPIO_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO pin direction");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set GPIO pin value
    ret = ioctl(gpio_fd, GPIO_SET_LINE_VALUE, GPIO_CE0, 1);
    if (ret < 0) {
        perror("Failed to set GPIO pin value");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        // Select GPIO pin value
        ret = ioctl(gpio_fd, GPIO_GET_LINE_VALUE, GPIO_CE0, &ret);
        if (ret < 0) {
            perror("Failed to get GPIO pin value");
            break;
        }

        // Select SPI mode
        ret = ioctl(spi_fd, SPI_IOC_WR_MODE, 0);
        if (ret < 0) {
            perror("Failed to set SPI mode");
            break;
        }

        // Select SPI bits per word
        ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
        if (ret < 0) {
            perror("Failed to set SPI bits per word");
            break;
        }

        // Select SPI max speed
        ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, ADC_CLOCK_SPEED);
        if (ret < 0) {
            perror("Failed to set SPI max speed");
            break;
        }

        // Select SPI chip select
        ret = ioctl(spi_fd, SPI_IOC_WR_CHIP_SELECT, 0);
        if (ret < 0) {
            perror("Failed to set SPI chip select");
            break;
        }

        // Select ADC channel
        ret = ioctl(spi_fd, SPI_IOC_WR_CHIPSSELECT, 0);
        if (ret < 0) {
            perror("Failed to set ADC channel");
            break;
        }

        // Read ADC value
        xfer.tx_buf = 0;
        xfer.rx_buf = 0;
        xfer.len = ADC_TRANSFER_SIZE;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("Failed to read ADC value");
            break;
        }

        // Calculate moisture percentage
        uint16_t adc_value = (xfer.rx_buf[0] << 8) | xfer.rx_buf[1];
        float moisture = (adc_value * 100.0) / ADC_MAX;

        // Print ADC value and moisture percentage
        printf("ADC value: %d, Moisture: %.2f%%\n", adc_value, moisture);

        // Wait 5 seconds
        usleep(5000000);
    }

    // Release GPIO pin
    ret = ioctl(gpio_fd, GPIO_SET_LINE_VALUE, GPIO_CE0, 0);
    if (ret < 0) {
        perror("Failed to release GPIO pin");
    }

    // Unexport GPIO pin
    ret = ioctl(gpio_fd, GPIO_LINE_REQUEST, GPIO_CE0);
    if (ret < 0) {
        perror("Failed to unexport GPIO pin");
    }

    // Close GPIO device
    close(gpio_fd);

    // Close SPI device
    close(spi_fd);

    return 0;
}

