        count++;

        // Check for sensor failure
        if (count >= MAX_READINGS && readings[0] == readings[MAX_READINGS - 1]) {
            printf("Sensor failure detected\n");
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
