#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_SCLK_PIN 11
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_SAMPLE_INTERVAL 5000000 // 5 seconds

// Function to handle signal interrupts
void sigint_handler(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pins for SPI
    if (gpioSetMode(ADC_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d: %s\n", ADC_CS_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d: %s\n", ADC_SCLK_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_MOSI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d: %s\n", ADC_MOSI_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_MISO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d: %s\n", ADC_MISO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    int spi_fd = gpioOpen(ADC_CS_PIN, SPI_MODE_0, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler for SIGINT: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler for SIGTERM: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Select the ADC channel
        if (gpioSetMode(ADC_CS_PIN, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set up GPIO pin %d: %s\n", ADC_CS_PIN, strerror(errno));
            break;
        }
        gpioWrite(ADC_CS_PIN, 0);

        // Read the ADC value
        uint16_t adc_value;
        if (spiXfer(spi_fd, &adc_value, 2, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
            break;
        }

        // Check for stuck ADC value
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC value stuck at %d, sensor absent or wiring fault\n", adc_value);
            break;
        }

        // Print the ADC value
        struct timeval tv;
        gettimeofday(&tv, NULL);
        printf("%ld.%06ld: ADC value: %d\n", tv.tv_sec, tv.tv_usec, adc_value);

        // Wait for the next sample interval
        usleep(ADC_SAMPLE_INTERVAL);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

