        buffer[2] = 0x00; // Don't-care byte
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret < 0) {
            perror("Failed to send SPI message");
            break;
        }

        // Read result
        reading = (buffer[1] << 8) | buffer[2];

        // Clamp reading to 0-100%
        moisture = (reading * 100.0f) / 1023.0f;

