        if (++i >= AVERAGE_READINGS) {
            printf("Moisture: %.2f%%\n", sum / AVERAGE_READINGS);
            sum = 0.0f;
            i = 0;
        }

        usleep(5000000);
    }

    // Close SPI device
    close(spi_fd);

    return EXIT_SUCCESS;
}

