// Structure to hold a single sample
typedef struct {
    int moisture;
    bool pump_state;
    time_t timestamp;
} sample_t;

// Circular buffer to store samples
sample_t buffer[MAX_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Stop the timer
    gpioTimerStop(0);

    // Ensure the pump is turned off
    gpioWrite(17, 0);

    // Close the SPI interface
    spiClose(0);

    // Cleanly terminate the driver library
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the driver library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize the driver library\n");
        return 1;
    }

    // Set up the GPIO pins
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin 17\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI interface
    if (spiOpen(0, 0, 1000000) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI transfer mode
    if (spiSetMode(0, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI transfer mode\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Set up the SPI clock speed
    if (spiSetClock(0, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Set up the SPI chip select pin
    if (gpioSetMode(10, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin 10\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Set up the SPI MISO pin
    if (gpioSetMode(9, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin 9\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Set up the SPI SCLK pin
    if (gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin 11\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Initialize the timer
    if (gpioTimerStart(0, SAMPLE_INTERVAL, 0) < 0) {
        fprintf(stderr, "Failed to start timer\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read the SPI interface
        uint8_t data[3];
        if (spiXfer(0, (uint8_t[]){0x00, 0x00, 0x00}, data, 3) < 0) {
            fprintf(stderr, "Failed to read SPI interface\n");
            spiClose(0);
            gpioTerminate();
            return 1;
        }

        // Extract the moisture level from the data
        int moisture = (data[1] & 0x03) << 8 | data[2];

        // Check if the pump should be turned on or off
        bool pump_state = (moisture < LOW_THRESHOLD) && !buffer_tail || (moisture > HIGH_THRESHOLD) && buffer_tail;
        if (pump_state != (buffer_tail > 0)) {
            // Update the pump state
            gpioWrite(17, pump_state ? 1 : 0);

            // Update the buffer
            buffer[buffer_tail].pump_state = pump_state;
            buffer[buffer_tail].timestamp = time(NULL);
            buffer_tail = (buffer_tail + 1) % MAX_BUFFER_SIZE;
        }

        // Add the new sample to the buffer
        buffer[buffer_head].moisture = moisture;
        buffer[buffer_head].timestamp = time(NULL);
        buffer_head = (buffer_head + 1) % MAX_BUFFER_SIZE;

        // Print the buffer
        for (int i = 0; i < MAX_BUFFER_SIZE; i++) {
            sample_t *sample = &buffer[(i + buffer_tail) % MAX_BUFFER_SIZE];
            printf("%d, %d, %s\n", sample->moisture, sample->pump_state, ctime(&sample->timestamp));
        }
    }

    return 0;
}

