#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_BUS 0
#define SPI_CS 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_CS_ACTIVE_HIGH 0
#define SPI_CS_HIGH 1
#define SPI_CS_LOW 0
#define SPI_CS_HOLD 0
#define SPI_CS_RELEASE 0
#define SPI_READ 0
#define SPI_WRITE 1
#define SPI_TRANSFER_SIZE 3
#define CSV_FILE "analog_log.csv"
#define CSV_HEADER "Timestamp,Channel,Voltage\n"
#define CSV_FORMAT "%Y-%m-%dT%H:%M:%SZ,%,f\n"
#define CSV_BUFFER_SIZE 1024

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer xfer;
    uint8_t buffer[SPI_TRANSFER_SIZE];
    char csv_buffer[CSV_BUFFER_SIZE];
    FILE *csv_file;
    struct tm time;
    time_t now;
    int retry_count = 0;
    int retry_max = 5;

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(1);
    }

    // Set up SPI
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HOLD, &SPI_CS_HOLD) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS_RELEASE, &SPI_CS_RELEASE) < 0) {
        perror("ioctl");
        exit(1);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("fopen");
        exit(1);
    }

    // Write header to CSV file
    fprintf(csv_file, CSV_HEADER);

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Get current time
        time = *localtime(&now);
        strftime(csv_buffer, CSV_BUFFER_SIZE, CSV_FORMAT, &time);

        // Read from SPI
        memset(buffer, 0, SPI_TRANSFER_SIZE);
        xfer.tx_buf = (unsigned long)buffer;
        xfer.rx_buf = (unsigned long)buffer;
        xfer.len = SPI_TRANSFER_SIZE;
        xfer.speed_hz = SPI_SPEED;
        xfer.delay_usecs = 0;
        xfer.cs_change = 1;
        xfer.cs_high = SPI_CS_HIGH;
        xfer.cs_low = SPI_CS_LOW;
        xfer.bits_per_word = 8;
        xfer.mode = SPI_MODE;
        xfer.nss = SPI_CS;
        xfer.cs = SPI_CS_ACTIVE_HIGH;

        for (int i = 0; i < 3; i++) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
                if (retry_count < retry_max) {
                    retry_count++;
                    continue;
                } else {
                    fprintf(stderr, "SPI read failed after %d retries\n", retry_count);
                    retry_count = 0;
                    break;
                }
            }
            retry_count = 0;

            // Convert SPI data to voltage
            uint16_t voltage = (buffer[0] << 8) | buffer[1];

            // Write to CSV file
            fprintf(csv_file, "%s,%d,%f\n", csv_buffer, i, (float)voltage / 1024);
        }

        // Sleep
        usleep(500000);
    }

    // Close SPI handle
    close(spi_fd);

    // Terminate driver
    gpiod_chip_close(chip);

    // Close CSV file
    fclose(csv_file);

    return 0;
}

