        exit(1);
    }
    return fd;
}

int i2c_read(int fd, uint8_t *buf, int count) {
    int bytes_read = read(fd, buf, count);
    if (bytes_read < 0) {
        perror("read");
        return -1;
    }
    return bytes_read;
}

int i2c_write(int fd, uint8_t *buf, int count) {
    int bytes_written = write(fd, buf, count);
    if (bytes_written < 0) {
        perror("write");
        return -1;
    }
    return bytes_written;
}

int main() {
    struct i2c_client *client;
    int fd = i2c_open(ADC_I2C_BUS);
    fd = i2c_set_slave(fd, ADC_I2C_SLAVE_ADDRESS);

    // Initialize GPIO
    int relay_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (relay_fd < 0) {
