#include <syslog.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define DEFAULT_SPI_SPEED 1000000
#define DEFAULT_SPI_MODE 0

#define GPIO_PUMP 18
#define GPIO_CE 8

#define MAX_LOG_LINE 256

static volatile bool running = true;
static int spi_fd = -1;
static int pump_fd = -1;

static void sigint_handler(int sig) {
    running = false;
}

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);
}

static void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_ERR, format, args);
    va_end(args);
}

static int open_spi(void) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        log_error("Failed to open SPI device: %s", strerror(errno));
        return -1;
    }
    return fd;
}

static int configure_spi(int fd, uint32_t speed, uint8_t mode) {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 0;
    xfer.speed = speed;
    xfer.bits_per_word = 8;
    xfer.delay_usecs = 0;
    xfer.cs_change = 0;
    xfer.cs_high = 1;
    xfer.cs_low = 0;
    xfer.bits_per_word = 8;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error("Failed to set SPI mode: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        log_error("Failed to set SPI speed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, uint8_t *data) {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = (uintptr_t)data;
    xfer.len = 1;
    xfer.speed = DEFAULT_SPI_SPEED;
    xfer.bits_per_word = 8;
    xfer.delay_usecs = 0;
    xfer.cs_change = 0;
    xfer.cs_high = 1;
    xfer.cs_low = 0;
    xfer.bits_per_word = 8;
    int retries = 0;
    while (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0 && retries < 3) {
        syslog(LOG_ERR, "SPI read error: %s, retrying...", strerror(errno));
        retries++;
    }
    if (retries >= 3) {
        log_error("Failed to read ADC value after 3 retries");
        return -1;
    }
    return 0;
}

static int get_adc_value(int fd) {
    uint8_t data;
    if (read_adc(fd, &data) < 0) {
        return -1;
    }
    return (data * 3.3) / 255;
}

static void activate_pump(void) {
    if (gpiod_cset(GPIO_PUMP, GPIOD_LINE_ACTIVE_HIGH) < 0) {
        log_error("Failed to activate pump");
    }
}

static void deactivate_pump(void) {
    if (gpiod_cset(GPIO_PUMP, GPIOD_LINE_ACTIVE_LOW) < 0) {
        log_error("Failed to deactivate pump");
    }
}

static void pump_cycle(int threshold, int duration) {
    int moisture = get_adc_value(spi_fd);
    if (moisture < (3.3 * threshold)) {
        log_message("Moisture level below threshold, activating pump");
        activate_pump();
        sleep(duration);
        deactivate_pump();
    } else {
        log_message("Moisture level above threshold, skipping pump");
    }
}

static void usage(void) {
    fprintf(stderr, "Usage: %s [-t <threshold>] [-d <duration>] [-s <sleep>]\n", argv[0]);
    exit(1);
}

int main(int argc, char **argv) {
    int threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                usage();
        }
    }
    if (optind < argc) {
        usage();
    }

    openlog("irrigation", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_fd = open_spi();
    if (spi_fd < 0) {
        exit(1);
    }
    if (configure_spi(spi_fd, DEFAULT_SPI_SPEED, DEFAULT_SPI_MODE) < 0) {
        exit(1);
    }

    while (running) {
        pump_cycle(threshold, pump_duration);
        sleep(sleep_interval);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (pump_fd >= 0) {
        gpiod_cset(GPIO_PUMP, GPIOD_LINE_ACTIVE_LOW);
        close(pump_fd);
    }
    gpiod_close();
    closelog();
    return 0;
}

