// Structure to hold ADC data
typedef struct {
    int fd;
    uint8_t cs;
    uint8_t clk;
    uint8_t mosi;
    uint8_t miso;
} spi_t;

// Function to initialize SPI
int spi_init(spi_t *spi) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        close(fd);
        return -1;
    }

    spi->fd = fd;
    spi->cs = 8;  // GPIO8
    spi->clk = 11;  // GPIO11
    spi->mosi = 10;  // GPIO10
    spi->miso = 9;  // GPIO9

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        close(fd);
        return -1;
    }

    if (gpioSetMode(spi->cs, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set CS pin mode");
        gpioTerminate();
        close(fd);
        return -1;
    }

    if (gpioSetMode(spi->clk, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set CLK pin mode");
        gpioTerminate();
        close(fd);
        return -1;
    }

    if (gpioSetMode(spi->mosi, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MOSI pin mode");
        gpioTerminate();
        close(fd);
        return -1;
    }

    if (gpioSetMode(spi->miso, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MISO pin mode");
        gpioTerminate();
        close(fd);
        return -1;
    }

    return 0;
}

// Function to read ADC value
int spi_read(spi_t *spi) {
    uint8_t data[2];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .mode = 0,
        .nbytes = 2
    };

    if (ioctl(spi->fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "Failed to read from ADC");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to detect peak
bool detect_peak(int value, int prev_value) {
    return (value > THRESHOLD && prev_value <= THRESHOLD);
}

// Function to log peak
void log_peak(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *lt = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

    fprintf(fp, "%s %d\n", timestamp, value);
    fclose(fp);
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    gpioTerminate();
    close(spi->fd);
    exit(0);
}

int main() {
    setlogmask(LOG_UPTO(LOG_INFO));
    openlog("sound_peak_detector", LOG_PID | LOG_CONS, LOG_USER);

    spi_t spi;
    if (spi_init(&spi) < 0) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        exit(1);
    }

    int prev_value = 0;
    while (1) {
        int value = spi_read(&spi);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read from ADC");
            break;
        }

        if (detect_peak(value, prev_value)) {
            log_peak(value);
        }

        prev_value = value;

        usleep(SAMPLE_RATE * 1000);
    }

    close(spi->fd);
    gpioTerminate();
    syslog(LOG_INFO, "Shutting down");
    closelog();
    return 0;
}

