#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and device addresses
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDRESS 0x4B

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the I2C file descriptor
    if (close(i2c_fd) != 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set the I2C bus to the PCF8591 device address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the PCF8591
    if (i2c_smbus_write_byte(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_write_byte");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Perform a dummy read to discard the previous result
        if (i2c_smbus_read_byte(i2c_fd) < 0) {
            perror("i2c_smbus_read_byte");
            exit(EXIT_FAILURE);
        }

        // Read the current 8-bit sample
        uint8_t sample;
        if (i2c_smbus_read_byte(i2c_fd, &sample) < 0) {
            perror("i2c_smbus_read_byte");
            exit(EXIT_FAILURE);
        }

        // Print the sample value
        printf("%d\n", sample);

        // Sleep for 100ms
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

