#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define the ADC address and the GPIO pin
#define ADC_ADDRESS 0x48
#define GPIO_PIN 27

// Define the ADC channel and the sample rate
#define ADC_CHANNEL 0
#define SAMPLE_RATE 1

// Define the threshold and the buffer size
#define THRESHOLD 500
#define BUFFER_SIZE 100

// Define the circular buffer
uint16_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Define the rolling average
float average = 0.0;

// Define the I2C handle
int i2c_handle;

// Define the GPIO handle
int gpio_handle;

// Function to read the ADC value
uint16_t read_adc() {
    uint16_t value;
    if (ioctl(i2c_handle, I2C_SLAVE, ADC_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        return 0;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, 0x01, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to ADC");
        return 0;
    }
    if (i2c_smbus_read_byte_data(i2c_handle, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to read from ADC");
        return 0;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, 0x01, 0x04) < 0) {
        syslog(LOG_ERR, "Failed to write to ADC");
        return 0;
    }
    if (i2c_smbus_read_i2c_block_data(i2c_handle, 0x00, 2, &value) < 0) {
        syslog(LOG_ERR, "Failed to read from ADC");
        return 0;
    }
    return value;
}

// Function to calculate the magnetic field strength
float calculate_magnetic_field(uint16_t value) {
    // The SS49E has a sensitivity of 0.1 mV/Gauss
    // The ADC has a resolution of 16 bits
    // The voltage range is 0-3.3V
    float voltage = (float)value / 65535.0 * 3.3;
    return (voltage / 0.1) * 1000.0;
}

// Function to handle the signal
void signal_handler(int signal) {
    if (gpio_write(gpio_handle, GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to reset GPIO");
    }
    if (i2c_close(i2c_handle) < 0) {
        syslog(LOG_ERR, "Failed to close I2C handle");
    }
    syslog(LOG_INFO, "Exiting");
    exit(0);
}

int main() {
    // Open the I2C bus
    if ((i2c_handle = open("/dev/i2c-1", O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return 1;
    }

    // Initialize the GPIO
    if ((gpio_handle = gpioInitialise()) < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Set up the GPIO pin as an output
    if (gpio_set_mode(gpio_handle, GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        return 1;
    }

    // Initialize the syslog
    openlog("hall_sensor", LOG_PID | LOG_PERROR, LOG_USER);

    // Main loop
    while (1) {
        // Read the ADC value
        uint16_t value = read_adc();
        if (value == 0) {
            syslog(LOG_INFO, "ADC read failed");
            continue;
        }

        // Calculate the magnetic field strength
        float magnetic_field = calculate_magnetic_field(value);
        syslog(LOG_INFO, "Magnetic field: %f Gauss", magnetic_field);

        // Store the value in the buffer
        buffer[buffer_index] = value;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_count++;

        // Update the rolling average
        average = (average * (BUFFER_SIZE - 1) + magnetic_field) / BUFFER_SIZE;

        // Check if the threshold is exceeded
        if (magnetic_field > THRESHOLD) {
            syslog(LOG_INFO, "Threshold exceeded");
            if (gpio_write(gpio_handle, GPIO_PIN, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO high");
            }
        } else {
            if (gpio_write(gpio_handle, GPIO_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to reset GPIO");
            }
        }

        // Sleep for the sample period
        usleep(1000000 / SAMPLE_RATE);
    }

    // Clean up
    if (gpioTerminate() < 0) {
        syslog(LOG_ERR, "Failed to terminate GPIO");
    }
    if (close(i2c_handle) < 0) {
        syslog(LOG_ERR, "Failed to close I2C handle");
    }
    closelog();

    return 0;
}

