        uint16_t value = read_adc();
        if (value == 0) {
            syslog(LOG_INFO, "ADC read failed");
            continue;
        }

        // Calculate the magnetic field strength
        float magnetic_field = calculate_magnetic_field(value);
        syslog(LOG_INFO, "Magnetic field: %f Gauss", magnetic_field);

        // Store the value in the buffer
        buffer[buffer_index] = value;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_count++;

        // Update the rolling average
        average = (average * (BUFFER_SIZE - 1) + magnetic_field) / BUFFER_SIZE;

        // Check if the threshold is exceeded
        if (magnetic_field > THRESHOLD) {
            syslog(LOG_INFO, "Threshold exceeded");
            if (gpio_write(gpio_handle, GPIO_PIN, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO high");
            }
        } else {
            if (gpio_write(gpio_handle, GPIO_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to reset GPIO");
            }
        }

        // Sleep for the sample period
        usleep(1000000 / SAMPLE_RATE);
    }

    // Clean up
    if (gpioTerminate() < 0) {
        syslog(LOG_ERR, "Failed to terminate GPIO");
    }
    if (close(i2c_handle) < 0) {
        syslog(LOG_ERR, "Failed to close I2C handle");
    }
    closelog();

    return 0;
}
