#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_CS_HIGH 0
#define ADC_CHANNEL 0
#define ADC_VDD 3.3
#define ADC_FULL_SCALE 1023
#define ADC_RESOLUTION 10

volatile bool running = true;

