    running = false;
}

int main() {
    int spi_fd;
    int ret;
    uint8_t data[2];
    uint16_t adc_value;
    float intensity;

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI parameters
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI LSB first\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI CS high\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Send command to ADC
        data[0] = 0x01; // Start bit
        data[1] = 0x00; // Single-ended, channel 0
        ret = write(spi_fd, data, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to send command to ADC\n");
            continue;
        }

        // Read data from ADC
        ret = read(spi_fd, data, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read data from ADC\n");
            continue;
        }

        // Convert data to 16-bit value
        adc_value = (data[0] << 8) | data[1];

        // Map ADC value to intensity
        intensity = (adc_value * 100) / ADC_FULL_SCALE;

        // Print result
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        printf("%04d-%02d-%02d %02d:%02d:%02d: %d %f\n",
               lt->tm_year + 1900, lt->tm_mon + 1, lt->tm_mday, lt->tm_hour, lt->tm_min, lt->tm_sec, adc_value, intensity);

        usleep(1000000);
    }

    // Close SPI device
    close(spi_fd);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

