#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define PGA_GAIN 4.096
#define DEFAULT_THRESHOLD 100.0
#define LED_PIN 17
#define SAMPLE_RATE 100

// Function to handle signal interrupts
void signal_handler(int signal) {
    // Turn off the LED
    gpioWrite(LED_PIN, 0);
    // Release the GPIO resources
    gpioTerminate();
    // Exit the program
    exit(0);
}

// Function to read the ADC value
int read_adc(int fd, int channel) {
    // Set the channel
    i2c_smbus_write_byte_data(fd, ADC_ADDRESS, 0x01 << channel);
    // Read the data
    uint16_t data = i2c_smbus_read_word_data(fd, ADC_ADDRESS);
    // Return the value
    return (int) (data * PGA_GAIN / 32768.0);
}

int main(int argc, char **argv) {
    // Parse the command-line arguments
    int threshold = DEFAULT_THRESHOLD;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t <threshold>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up the LED pin as an output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C bus
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, ADC_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        int value = read_adc(fd, ADC_CHANNEL);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Calculate the magnetic field strength
        double field = value / 1000.0;

        // Check if the field exceeds the threshold
        if (field > threshold) {
            // Blink the LED
            for (int i = 0; i < 20; i++) {
                gpioWrite(LED_PIN, 1);
                usleep(50000);
                gpioWrite(LED_PIN, 0);
                usleep(50000);
            }
        }

        // Print the field strength
        printf("%f G\n", field);

        // Sleep for 100ms
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

