struct mosquitto_message {
    char* topic;
    char* payload;
    int payload_len;
};

void on_connect(struct mosquitto* mosq, void* userdata, int rc) {
    syslog(LOG_INFO, "Connected to MQTT broker with result code %d", rc);
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_SUB, 0);
}

void on_message(struct mosquitto* mosq, void* userdata, const struct mosquitto_message* message) {
    if (strcmp(message->topic, MQTT_TOPIC_SUB) == 0) {
        if (strcmp(message->payload, "pump_on") == 0) {
            gpio_write(PUMP_GPIO, 1);
            syslog(LOG_INFO, "Pump turned on");
        } else if (strcmp(message->payload, "pump_off") == 0) {
            gpio_write(PUMP_GPIO, 0);
            syslog(LOG_INFO, "Pump turned off");
        }
        free(message->payload);
        mosquitto_message_free(message);
    }
}

void on_publish(struct mosquitto* mosq, void* userdata, int mid) {
    syslog(LOG_INFO, "Published message with mid %d", mid);
}

void on_disconnect(struct mosquitto* mosq, void* userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with result code %d", rc);
}

void on_subscribe(struct mosquitto* mosq, void* userdata, int mid, int qos_count, const int* granted_qos) {
    syslog(LOG_INFO, "Subscribed to topic %s with mid %d and QoS %d", MQTT_TOPIC_SUB, mid, granted_qos[0]);
}

void on_unsubscribe(struct mosquitto* mosq, void* userdata, int mid) {
    syslog(LOG_INFO, "Unsubscribed from topic %s with mid %d", MQTT_TOPIC_SUB, mid);
}

void on_log(struct mosquitto* mosq, void* userdata, int level, const char* str) {
    syslog(LOG_INFO, "MQTT log: %s", str);
}

int main() {
    int fd;
    int ret;
    struct spi_ioc_transfer xfer;
    uint8_t buf[3];
    uint16_t value;
