    if (ioctl(fd, SPI_IOC_WR_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosq = mosquitto_new(NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT object");
        close(fd);
        gpioTerminate();
        return 1;
