#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 10
#define SPI_SPEED 1000000
#define SPI_LSBFIRST 0
#define SPI_CS_PIN 8
#define SPI_CLK_PIN 11
#define SPI_MISO_PIN 9
#define SPI_MOSI_PIN 10

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 2;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS_PER_WORD;
    xfer.cs_change = 1;
    xfer.cs_high = 1;
    xfer.cs_low = 1;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSBFIRST) < 0) {
        perror("Failed to set SPI LSB first");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &xfer.cs_high) < 0) {
        perror("Failed to set CS high");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_LOW, &xfer.cs_low) < 0) {
        perror("Failed to set CS low");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &xfer.cs_change) < 0) {
        perror("Failed to set CS change");
        close(spi_fd);
        return 1;
    }

    struct spi_cs_control cs_control;
    cs_control.cs = SPI_CS_PIN;
    if (ioctl(spi_fd, SPI_IOC_SCSI, &cs_control) < 0) {
        perror("Failed to set CS pin");
        close(spi_fd);
        return 1;
    }

    struct spi_sck_control sck_control;
    sck_control.sck = SPI_CLK_PIN;
    if (ioctl(spi_fd, SPI_IOC_SCKI, &sck_control) < 0) {
        perror("Failed to set SCK pin");
        close(spi_fd);
        return 1;
    }

    struct spi_mosi_control mosi_control;
    mosi_control.mosi = SPI_MOSI_PIN;
    if (ioctl(spi_fd, SPI_IOC_MOSII, &mosi_control) < 0) {
        perror("Failed to set MOSI pin");
        close(spi_fd);
        return 1;
    }

    struct spi_miso_control miso_control;
    miso_control.miso = SPI_MISO_PIN;
    if (ioctl(spi_fd, SPI_IOC_MISI, &miso_control) < 0) {
        perror("Failed to set MISO pin");
        close(spi_fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t raw_value;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to send SPI message");
            close(spi_fd);
            return 1;
        }

        raw_value = *(uint16_t *)xfer.rx_buf;

        float voltage = (raw_value * 3.3 / (1 << SPI_BITS_PER_WORD));

        printf("Raw value: %d, Voltage: %f V\n", raw_value, voltage);

        usleep(500000);
    }

    close(spi_fd);
    return 0;
}

