#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 0
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define SAMPLING_RATE 10  // ms
#define THRESHOLD 500
#define PWM_FREQ 100  // Hz
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Stop motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Close SPI device
    close(spidev_fd);

    // Log a message
    syslog(LOG_INFO, "Received signal %d, exiting cleanly.", sig);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the logging system
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", strerror(errno));
        exit(1);
    }

    // Set up SPI
    spidev_fd = open("/dev/spidev0.0", O_RDWR);
    if (spidev_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set up SPI mode and bits per word
    if (ioctl(spidev_fd, SPI_IOC_WR_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(spidev_fd);
        gpioTerminate();
        exit(1);
    }
    if (ioctl(spidev_fd, SPI_IOC_WR_BITS_PER_WORD, 12) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        close(spidev_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up PWM
    gpioSetMode(MOTOR1_PIN, PI_PWM);
    gpioSetMode(MOTOR2_PIN, PI_PWM);
    gpioSetPWM(MOTOR1_PIN, 0, PWM_FREQ);
    gpioSetPWM(MOTOR2_PIN, 0, PWM_FREQ);

    // Open the log file
    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(spidev_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read from ADC
        uint16_t adc_value;
        if (ioctl(spidev_fd, SPI_IOC_READ, &adc_value) < 0) {
            syslog(LOG_ERR, "Failed to read from ADC: %s", strerror(errno));
            continue;
        }

        // Check if the noise level exceeds the threshold
        if (adc_value > THRESHOLD) {
            // Log a vibration event
            fprintf(log_file, "%lu\n", time(NULL));
        }

        // Modulate the motors
        uint16_t duty = (uint16_t)((adc_value - THRESHOLD) * 100 / (0xFFFF - THRESHOLD));
        if (duty > PWM_DUTY_MAX) {
            duty = PWM_DUTY_MAX;
        }
        gpioPWM(MOTOR1_PIN, duty);
        gpioPWM(MOTOR2_PIN, duty);

        // Sleep for the sampling period
        usleep(SAMPLING_RATE * 1000);
    }

    // Close the log file
    fclose(log_file);

    // Close the SPI device
    close(spidev_fd);

    // Terminate the GPIO driver
    gpioTerminate();

    // Close the log file descriptor
    closelog();

    return 0;
}

