#define ADC_CHANNEL 0
#define RELAY_GPIO 17
#define SPI_SPEED 1000000
#define SPI_MODE 0b00
#define SPI_LSB_FIRST 0
#define SPI_CS_ACTIVE_HIGH 0
#define SPI_READ 0
#define THRESHOLD 30
#define READ_INTERVAL 60

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int adc_fd;
    uint8_t buffer[2];
    uint16_t reading;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up relay pin as output
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set relay pin to low (off)
    gpioWrite(RELAY_GPIO, 0);

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SPI parameters
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to set SPI LSB first\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to set SPI CS active high\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open ADC device
    if ((adc_fd = open("/dev/mcp3008", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open ADC device\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read from ADC
        memset(buffer, 0, sizeof(buffer));
        if (read(spi_fd, buffer, 2) != 2) {
            if (errno == EAGAIN) {
                // Retry up to three times
                for (int i = 0; i < 3; i++) {
                    if (read(spi_fd, buffer, 2) == 2) {
                        break;
                    }
                    usleep(100000);
                }
                if (read(spi_fd, buffer, 2) != 2) {
                    fprintf(stderr, "Failed to read from ADC\n");
                    close(adc_fd);
                    close(spi_fd);
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            } else {
                fprintf(stderr, "Failed to read from ADC\n");
                close(adc_fd);
                close(spi_fd);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        // Validate SPI transfer
        if (buffer[0] != 0x00 || buffer[1] != 0x00) {
            fprintf(stderr, "Invalid SPI transfer\n");
            close(adc_fd);
            close(spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Read from ADC
        if (pread(adc_fd, &reading, sizeof(reading), 0) != sizeof(reading)) {
            fprintf(stderr, "Failed to read from ADC\n");
            close(adc_fd);
            close(spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Validate ADC reading
        if (reading < 0 || reading > 1023) {
            fprintf(stderr, "Invalid ADC reading\n");
            close(adc_fd);
            close(spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Calculate moisture percentage
        double moisture = (double)reading / 1023 * 100;

        // Log reading
        printf("%f%%\n", moisture);

        // Activate pump if moisture is below threshold
        if (moisture < THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1);
        } else {
            gpioWrite(RELAY_GPIO, 0);
        }

        // Sleep for READ_INTERVAL seconds
        usleep(READ_INTERVAL * 1000000);
    }

    // Turn off pump
    gpioWrite(RELAY_GPIO, 0);

    // Close SPI device
    close(spi_fd);

    // Close ADC device
    close(adc_fd);

    // Release GPIO resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

