#define FAN_PIN 18
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define CO2_MAX 1000
#define LOG_FILE "air_quality.log"
#define LOG_INTERVAL 5000000 // 5 seconds in microseconds

// Function to convert ADC value to CO2 concentration
double co2_from_adc(uint16_t adc_value) {
    // Assuming a linear relationship between ADC value and CO2 concentration
    // This is a rough estimate and may need to be calibrated for the specific sensor
    return (adc_value / (double) ADC_MAX) * CO2_MAX;
}

// Function to log data to file
void log_data(double co2_ppm, bool fan_on) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s,%.2f,%d\n", timestamp, co2_ppm, fan_on);
    fclose(file);
}

// Signal handler to turn off fan and close SPI interface on exit
void sig_handler(int sig) {
    gpioWrite(FAN_PIN, 0);
    spiClose(0);
    exit(0);
}

int main() {
    // Initialize GPIO and SPI
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI interface
    int spi_fd = spiOpen(0, 0, 0);
    if (spi_fd < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Set up fan pin as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Turn fan off

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
