#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define ADC_CHANNEL 0
#define ADC_CS_PIN 24
#define ADC_SPEED 1000000
#define DEBOUNCE_DELAY 1000
#define LOG_FILE "door_events.log"
#define LOG_BUFFER_SIZE 256

volatile bool running = true;
bool debounced = false;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (ioctl(adc_fd, SPI_IOC_WR_MODE, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (ioctl(adc_fd, SPI_IOC_WR_MAX_SPEED_HZ, &ADC_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (gpioSetMode(gpio_fd, RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (gpioSetMode(gpio_fd, ADC_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ADC CS pin mode: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (gpioWrite(gpio_fd, RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set relay pin low: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    if (gpioWrite(gpio_fd, ADC_CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set ADC CS pin high: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    struct timeval last_detection;
    gettimeofday(&last_detection, NULL);

    while (running) {
        if (gpioRead(gpio_fd, ADC_CS_PIN) < 0) {
            fprintf(stderr, "Failed to read ADC CS pin: %s\n", strerror(errno));
            break;
        }

        if (gpioWrite(gpio_fd, ADC_CS_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set ADC CS pin low: %s\n", strerror(errno));
            break;
        }

        uint16_t value;
        if (ioctl(adc_fd, SPI_IOC_READ, &value) < 0) {
            fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
            break;
        }

        if (gpioWrite(gpio_fd, ADC_CS_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set ADC CS pin high: %s\n", strerror(errno));
            break;
        }

        int distance = (1024 - value) * 20 / 1024;
        if (distance < 20 && !debounced) {
            gettimeofday(&last_detection, NULL);
            debounced = true;
            if (gpioWrite(gpio_fd, RELAY_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set relay pin high: %s\n", strerror(errno));
                break;
            }
            usleep(DEBOUNCE_DELAY * 1000);
            if (gpioWrite(gpio_fd, RELAY_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set relay pin low: %s\n", strerror(errno));
                break;
            }
        }

        if (gettimeofday(&last_detection, NULL) < 0) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            break;
        }

        if (timeval_diff(&last_detection, NULL) > 100) {
            debounced = false;
        }

        char buffer[LOG_BUFFER_SIZE];
        sprintf(buffer, "%lu: Distance: %d cm\n", (unsigned long)time(NULL), distance);
        if (fwrite(buffer, 1, strlen(buffer), log_file) < strlen(buffer)) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }
        fflush(log_file);
    }

    fclose(log_file);
    close(adc_fd);
    gpioTerminate(gpio_fd);
    return 0;
}

long timeval_diff(struct timeval *a, struct timeval *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_usec - b->tv_usec);
}

