#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define VALVE_GPIO 17
#define VALVE_FREQ 100
#define VALVE_DUTY_MIN 0
#define VALVE_DUTY_MAX 100
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int log_fd;
    int adc_values[3];
    float average;
    float valve_duty;

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SPI parameters
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)malloc(2),
        .rx_buf = (unsigned long)malloc(2),
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .bits_per_word = 8,
    };

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up valve PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWM(VALVE_GPIO, 0, VALVE_FREQ);

    while (running) {
        // Read three successive ADC samples
        for (int i = 0; i < 3; i++) {
            transfer.tx_buf = (unsigned long)malloc(2);
            transfer.rx_buf = (unsigned long)malloc(2);
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &transfer) < 0)) {
                free(transfer.tx_buf);
                free(transfer.rx_buf);
                continue;
            }
            adc_values[i] = *(uint16_t*)transfer.rx_buf;
            free(transfer.tx_buf);
            free(transfer.rx_buf);
        }

        // Compute average of ADC values
        average = 0;
        int count = 0;
        for (int i = 0; i < 3; i++) {
            if (adc_values[i] != 0) {
                average += adc_values[i];
                count++;
            }
        }
        if (count > 0) {
            average /= count;
        }

        // Set valve position based on average
        valve_duty = (average / 1023.0) * VALVE_DUTY_MAX;
        gpioPWM(VALVE_GPIO, (int)valve_duty);

        // Log data
        char log_str[256];
        time_t now = time(NULL);
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(log_str + strlen(log_str), ",ADC1: %d,ADC2: %d,ADC3: %d,Average: %.2f,Valve: %.2f%%\n",
                adc_values[0], adc_values[1], adc_values[2], average, valve_duty);
        write(log_fd, log_str, strlen(log_str));

        // Sleep for log interval
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up
    close(log_fd);
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

