#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_SPEED 1000000
#define ADC_MODE 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define RETRIES 5
#define BACKOFF 100
#define LOG_FILE "soil_data.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int read_adc(int retries) {
    int fd = gpioOpen(ADC_CS_PIN, GPIO_MODE_OUTPUT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI CS pin\n");
        return -1;
    }

    int attempts = 0;
    int result = -1;
    while (attempts < retries) {
        if (gpioDelay(BACKOFF * attempts) < 0) {
            fprintf(stderr, "Failed to delay\n");
            break;
        }

        if (gpioSetMode(ADC_CS_PIN, GPIO_MODE_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set CS pin mode\n");
            break;
        }

        if (gpioWrite(ADC_CS_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set CS pin low\n");
            break;
        }

        if (gpioSetMode(ADC_CS_PIN, GPIO_MODE_ALT0) < 0) {
            fprintf(stderr, "Failed to set CS pin mode\n");
            break;
        }

        if (spiXfer(fd, 0x00, 0x00, 1, 1, ADC_SPEED, ADC_MODE) < 0) {
            fprintf(stderr, "Failed to send command\n");
            break;
        }

        if (gpioDelay(10) < 0) {
            fprintf(stderr, "Failed to delay\n");
            break;
        }

        if (spiXfer(fd, 0x00, 0x00, 1, 1, ADC_SPEED, ADC_MODE) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        if (gpioWrite(ADC_CS_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set CS pin high\n");
            break;
        }

        if (gpioSetMode(ADC_CS_PIN, GPIO_MODE_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set CS pin mode\n");
            break;
        }

        uint8_t data[2];
        if (spiXfer(fd, 0x00, data, 2, 1, ADC_SPEED, ADC_MODE) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        result = (data[0] << 8) | data[1];
        if (result >= 0 && result <= ADC_MAX) {
            break;
        }

        attempts++;
    }

    gpioClose(fd);
    return result;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    struct stat sb;
    if (stat(LOG_FILE, &sb) == 0 && S_ISREG(sb.st_mode)) {
        unlink(LOG_FILE);
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    struct timeval last_sample;
    gettimeofday(&last_sample, NULL);

    while (running) {
        int result = read_adc(RETRIES);
        if (result >= 0) {
            struct timeval now;
            gettimeofday(&now, NULL);
            double elapsed = (now.tv_sec - last_sample.tv_sec) + (now.tv_usec - last_sample.tv_usec) / 1e6;
            if (elapsed >= 5) {
                last_sample = now;
                fprintf(fp, "%.3f, %d\n", now.tv_sec + now.tv_usec / 1e6, result);
                fflush(fp);
            }
        } else {
            fprintf(fp, "%.3f, ERROR\n", now.tv_sec + now.tv_usec / 1e6);
            fflush(fp);
        }

        usleep(100000);
    }

    fclose(fp);
    gpioTerminate();
    return 0;
}

