#define MIN_VOLUME 0

// Structure to hold calibration parameters
typedef struct {
    int min_distance;
    int max_distance;
    int min_volume;
    int max_volume;
} calibration_params;

// Function to read calibration parameters from file
calibration_params read_calibration_params() {
    calibration_params params;
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file == NULL) {
        return (calibration_params){MAX_DISTANCE, MIN_DISTANCE, MAX_VOLUME, MIN_VOLUME};
    }

    if (fscanf(file, "%d %d %d %d", &params.min_distance, &params.max_distance, &params.min_volume, &params.max_volume) != 4) {
        fclose(file);
        return (calibration_params){MAX_DISTANCE, MIN_DISTANCE, MAX_VOLUME, MIN_VOLUME};
    }

    fclose(file);
    return params;
}

// Function to write calibration parameters to file
void write_calibration_params(calibration_params params) {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file == NULL) {
        return;
    }

    fprintf(file, "%d %d %d %d", params.min_distance, params.max_distance, params.min_volume, params.max_volume);
    fclose(file);
}

// Function to read LDR value using MCP3008 ADC
int read_ldr() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)malloc(4);
    xfer.rx_buf = (unsigned long)malloc(4);
    xfer.len = 4;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;

    uint8_t cs = 0x18; // MCP3008 chip select
    uint8_t config = 0x01; // Single-ended input, 8-bit resolution
    uint8_t channel = LDR_CHANNEL;
    uint8_t data[4] = {cs, config, channel, 0x00};

    if (ioctl(fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
        free(xfer.tx_buf);
        free(xfer.rx_buf);
        close(fd);
        return -1;
    }

    uint16_t ldr_value = ((uint16_t*)xfer.rx_buf)[0] << 8 | ((uint16_t*)xfer.rx_buf)[1];
    free(xfer.tx_buf);
    free(xfer.rx_buf);
    close(fd);
    return ldr_value;
}

