    int fd = open("/sys/class/pwm/pwm0/export", O_WRONLY);
    if (fd < 0) {
        return;
    }

    char buffer[10];
    sprintf(buffer, "%d", 1);
    write(fd, buffer, strlen(buffer));
    close(fd);

    fd = open("/sys/class/pwm/pwm0/period", O_WRONLY);
    if (fd < 0) {
        return;
    }

    sprintf(buffer, "%d", 1000000 / frequency);
    write(fd, buffer, strlen(buffer));
    close(fd);

    fd = open("/sys/class/pwm/pwm0/duty_cycle", O_WRONLY);
    if (fd < 0) {
        return;
    }

    sprintf(buffer, "%d", (int)((double)volume / 100 * 1000000 / 100));
    write(fd, buffer, strlen(buffer));
    close(fd);

    fd = open("/sys/class/pwm/pwm0/enable", O_WRONLY);
    if (fd < 0) {
        return;
    }

    sprintf(buffer, "%d", 1);
    write(fd, buffer, strlen(buffer));
    close(fd);
}

