    int end_time = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        end_time = gpioGetTicks(ECHO_PIN);
    }

    int distance = (end_time - start_time) * 34300 / 2;
    gpioCleanup();
    return distance;
}

