#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define LOG_FILE "air_quality.log"
#define FAN_PIN 18
#define ADC_CHANNEL 0
#define ADC_SPI_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define RETRY_COUNT 3
#define RETRY_DELAY 1000

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Turn off the fan
    gpioWrite(FAN_PIN, 0);
    // Close the SPI interface
    spiClose(ADC_SPI_CHANNEL);
    // Close the log file
    fclose(log_file);
    // Terminate the driver library
    gpioTerminate();
    // Exit the program
    exit(0);
}

// Function to read the ADC value
int read_adc(int channel) {
    int value;
    int retry_count = 0;
    while (retry_count < RETRY_COUNT) {
        if (spiXfer(ADC_SPI_CHANNEL, 0, 1, &value, 1) == 0) {
            return value;
        }
        retry_count++;
        usleep(RETRY_DELAY);
    }
    // If all retries fail, return an error
    return -1;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI interface
    if (spiOpen(ADC_SPI_CHANNEL, ADC_SPI_SPEED, ADC_SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        fclose(log_file);
        gpioTerminate();
