#define ADC_MODE 0
#define ADC_BITS 8
#define ADC_THRESHOLD_HIGH 50
#define ADC_THRESHOLD_LOW 20

#define LOG_FILE "alcohol_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_measurement(double value) {
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s,%.2f\n", timestamp, value);
    fclose(log_file);
}

void read_adc(int fd, double *value) {
    uint8_t data[2];
    int retries = 0;
    while (retries < 3) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1, &data, 1, ADC_CHANNEL, ADC_CS_PIN, ADC_SPEED, ADC_MODE, ADC_BITS) == -1)) {
            if (errno == EIO) {
                retries++;
                usleep(100000);
            } else {
                perror("ioctl");
                exit(EXIT_FAILURE);
            }
        } else {
            *value = (double)data[0] / 1023.0 * 3.3;
            return;
        }
    }
    fprintf(stderr, "Failed to read ADC value after 3 retries\n");
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioWrite(ADC_CS_PIN, 1);
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, SPI_IOC_WR_MODE, &ADC_MODE) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &ADC_SPEED) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    double value;
    while (running) {
        read_adc(fd, &value);
        if (value == 0 || value == 1023) {
            fprintf(stderr, "Sensor absent\n");
        } else if (value > ADC_THRESHOLD_HIGH) {
            log_measurement(value);
            fprintf(stderr, "Alcohol detected! Limit exceeded.\n");
        } else if (value < ADC_THRESHOLD_LOW) {
            log_measurement(value);
            fprintf(stderr, "Sobriety confirmed.\n");
        } else {
            log_measurement(value);
            fprintf(stderr, "Alcohol level within acceptable range.\n");
        }
        sleep(1);
    }
    close(fd);
    gpioWrite(ADC_CS_PIN, 0);
    gpioTerminate();
    return 0;
}

