#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <pigpio.h>

#define LOG_FILE "irrigation.log"
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define THRESHOLD 300
#define SAMPLE_INTERVAL 60

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int log_fd;
    int moisture;
    char timestamp[20];
    char log_str[100];
    struct tm *timeinfo;

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open SPI interface
    spi_fd = gpioOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI interface");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up SPI pins
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetPullUpDnControl(SPI_MISO, PI_PUD_UP);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioClose(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    char *log_message = "Timestamp,Moisture,Pump Status\n";
    write(log_fd, log_message, strlen(log_message));

    while (running) {
        // Read moisture value from sensor
        uint8_t data[3];
        data[0] = 0x06; // Start bit, single-ended, channel 0
        data[1] = 0x00; // No gain, 10-bit resolution
        data[2] = 0x00; // No gain, 10-bit resolution
        if (gpioSPIDataRW(spi_fd, data, 3) < 0) {
            syslog(LOG_ERR, "Failed to read moisture value");
            continue;
        }
        moisture = (data[1] << 8) | data[2];

        // Check if moisture level is below threshold
        if (moisture < THRESHOLD) {
            // Turn on pump
            gpioWrite(PUMP_GPIO, 1);
        } else {
            // Turn off pump
            gpioWrite(PUMP_GPIO, 0);
        }

        // Get current timestamp
        timeinfo = localtime(time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log reading
        sprintf(log_str, "%s,%d,%s\n", timestamp, moisture, (moisture < THRESHOLD) ? "ON" : "OFF");
        write(log_fd, log_str, strlen(log_str));

        // Sleep for sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Turn off pump
    gpioWrite(PUMP_GPIO, 0);

    // Close SPI interface
    gpioClose(spi_fd);

    // Close log file
    close(log_fd);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

