#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define GPIO_CE0 8
#define GPIO_MOTOR1_ENABLE 18
#define GPIO_MOTOR1_DIRECTION 23
#define GPIO_MOTOR2_ENABLE 24
#define GPIO_MOTOR2_DIRECTION 25
#define GPIO_MOTOR1_SPEED 0
#define GPIO_MOTOR2_SPEED 1
#define MAX_SPEED 100
#define ACCELERATION 10
#define DECELERATION 10
#define HOLD_TIME 2
#define PAUSE_TIME 5
#define REVERSE_TIME 0.1

// Define signal handlers
void sigint_handler(int sig) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

// Define cleanup function
void cleanup() {
    // Release PWM resources
    gpioPWM(GPIO_MOTOR1_ENABLE, 0);
    gpioPWM(GPIO_MOTOR2_ENABLE, 0);

    // Release GPIO resources
    gpioSetMode(GPIO_MOTOR1_DIRECTION, PI_INPUT);
    gpioSetMode(GPIO_MOTOR2_DIRECTION, PI_INPUT);
    gpioSetMode(GPIO_MOSI, PI_INPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_SCLK, PI_INPUT);
    gpioSetMode(GPIO_CE0, PI_INPUT);

    // Release SPI resources
    close(spiOpen("/dev/spidev0.0", SPI_MODE, SPI_SPEED, SPI_BITS_PER_WORD, 0));
}

// Define function to read SPI bus
int read_spi(int fd, uint8_t* data) {
    struct spi_ioc_transfer xfer[] = {
        {
            .tx_buf = (unsigned long)data,
            .rx_buf = (unsigned long)data,
            .len = 1,
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
            .cs_change = 1,
            .delay_usecs = 0,
            .cs_high = 1,
            .cs_low = 1,
            .delay_usecs = 0,
        }
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

// Define function to map ADC reading to speed value
int map_adc_to_speed(uint16_t adc_value) {
    return (adc_value * MAX_SPEED) / 1023;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR2_DIRECTION, PI_OUTPUT);
    gpioSetMode(GPIO_MOSI, PI_OUTPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_SCLK, PI_OUTPUT);
    gpioSetMode(GPIO_CE0, PI_OUTPUT);

    // Initialize PWM
    gpioPWM(GPIO_MOTOR1_ENABLE, 0);
    gpioPWM(GPIO_MOTOR2_ENABLE, 0);

    // Open SPI device
    int fd = spiOpen("/dev/spidev0.0", SPI_MODE, SPI_SPEED, SPI_BITS_PER_WORD, 0);
    if (fd < 0) {
        perror("spiOpen");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ADC values
        uint8_t data[2];
        if (read_spi(fd, data) < 0) {
            perror("read_spi");
            cleanup();
            return 1;
        }

        // Map ADC values to speed values
        int motor1_speed = map_adc_to_speed(data[0]);
        int motor2_speed = map_adc_to_speed(data[1]);

        // Accelerate motors
        for (int speed = 0; speed <= motor1_speed; speed += ACCELERATION) {
            gpioPWM(GPIO_MOTOR1_ENABLE, speed);
            gpioPWM(GPIO_MOTOR2_ENABLE, speed);
            usleep(10000);
        }

        // Hold constant speed
        gpioPWM(GPIO_MOTOR1_ENABLE, motor1_speed);
