    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Calibrate ambient noise level
    uint16_t baseline = 0;
    for (int i = 0; i < CALIBRATION_TIME; i++) {
        // Read from MCP3008
        uint16_t sample;
        xfer.tx_buf = 0;
        xfer.rx_buf = (uint64_t)&sample;
