            close(spi_fd);
            gpioTerminate();
            return 1;
        }

        // Update baseline
        baseline += sample;
        usleep(100000);
    }
    baseline /= CALIBRATION_TIME;

    // Set up signal handler for SIGINT
    signal(SIGINT, cleanup);

    while (running) {
        // Read from MCP3008
        uint16_t sample;
        xfer.tx_buf = 0;
        xfer.rx_buf = (uint64_t)&sample;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            close(spi_fd);
            gpioTerminate();
            return 1;
        }

        // Check if sound level exceeds threshold
        if (sample > baseline + (baseline * 0.2)) {
            // Debounce
            if (gpioRead(LED_PIN) == 0) {
                gpioWrite(LED_PIN, 1);
                usleep(DEBOUNCE_TIME * 1000);
            }
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(10000);
    }

    return 0;
}

