int spi_open() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open /dev/spidev0.0");
        exit(1);
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_ns = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        exit(1);
    }

    return fd;
}

int spi_release(int fd) {
    close(fd);
    return 0;
}

