#include <pigpio.h>

// Define the SPI bus and chip-select pin
#define SPI_BUS 0
#define CHIP_SELECT 8

// Define the ADC channels for each axis
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Define the SPI mode and bits per word
#define SPI_MODE 0
#define SPI_BITS 10

// Define the Kalman filter parameters
#define KALMAN_ALPHA 0.1
#define KALMAN_BETA 0.1

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release the SPI bus and GPIO resources
    spi_close(SPI_BUS);
    gpioTerminate();
    exit(0);
}

// Define the function to read a single ADC channel
int read_adc_channel(int channel) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)malloc(SPI_BITS / 8),
        .rx_buf = (unsigned long)malloc(SPI_BITS / 8),
        .len = SPI_BITS / 8,
        .speed_hz = 1000000,
        .bits_per_word = SPI_BITS,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .mode = SPI_MODE,
    };

    // Set the chip-select pin as an output
    gpioSetMode(CHIP_SELECT, PI_OUTPUT);
    gpioWrite(CHIP_SELECT, 1);

    // Select the channel
    gpioWrite(CHIP_SELECT, 0);
    usleep(1);

    // Read the channel
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to read SPI device");
        free(xfer.tx_buf);
        free(xfer.rx_buf);
        close(fd);
        return -1;
    }

    // Release the chip-select pin
    gpioWrite(CHIP_SELECT, 1);

    // Convert the raw sample to a 10-bit value
    int value = ((int8_t*)xfer.rx_buf)[0] << 8 | ((int8_t*)xfer.rx_buf)[1];

    // Release the SPI bus and GPIO resources
    free(xfer.tx_buf);
    free(xfer.rx_buf);
    close(fd);

    return value;
}

// Define the function to apply a Kalman filter
float kalman_filter(int value, float previous_value, float previous_error) {
    float innovation = value - previous_value;
    float prediction = previous_value + KALMAN_ALPHA * innovation;
    float error = prediction - previous_value;
    float gain = KALMAN_BETA * error / (1 - KALMAN_BETA * error);
    return prediction + gain * innovation;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO library");
        return 1;
    }

    // Set the SPI bus and GPIO pins
    if (gpioSetMode(SPI_BUS, PI_SPI) < 0) {
        perror("Failed to set SPI bus mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) < 0) {
        perror("Failed to set chip-select pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(10, PI_ALT5) < 0) {
        perror("Failed to set MOSI pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(9, PI_ALT5) < 0) {
        perror("Failed to set MISO pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(11, PI_ALT5) < 0) {
        perror("Failed to set SCLK pin mode");
        gpioTerminate();
        return 1;
    }

    // Initialize the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the previous values
    float x_value = 0.0;
    float y_value = 0.0;
    float z_value = 0.0;

    // Main loop
    while (1) {
        // Read the ADC channels
        int x_sample = read_adc_channel(X_CHANNEL);
        int y_sample = read_adc_channel(Y_CHANNEL);
        int z_sample = read_adc_channel(Z_CHANNEL);

        // Check for errors
        if (x_sample < 0 || y_sample < 0 || z_sample < 0) {
            perror("Failed to read ADC channel");
            gpioTerminate();
            return 1;
        }

        // Apply the Kalman filter
        x_value = kalman_filter(x_sample / 1024.0 * 3.3, x_value, x_value - x_sample / 1024.0 * 3.3);
        y_value = kalman_filter(y_sample / 1024.0 * 3.3, y_value, y_value - y_sample / 1024.0 * 3.3);
        z_value = kalman_filter(z_sample / 1024.0 * 3.3, z_value, z_value - z_sample / 1024.0 * 3.3);

        // Print the filtered values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_value, y_value, z_value);

        // Sleep for 100ms
        usleep(100000);
    }

    // Release the SPI bus and GPIO resources
    gpioTerminate();

    return 0;
}
