#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LOG_FILE "watering.log"
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define ADC_CS 0
#define ADC_SPEED 500000
#define ADC_MODE 0
#define ADC_THRESHOLD 30

// Signal handlers
void sigint_handler(int sig) {
    gpioWrite(PUMP_GPIO, 0);
    syslog(LOG_INFO, "SIGINT received, shutting down...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(PUMP_GPIO, 0);
    syslog(LOG_INFO, "SIGTERM received, shutting down...\n");
    exit(0);
}

// Function to read ADC value
int read_adc(int fd, int channel) {
    struct spi_ioc_transfer xfer[] = {
        {
            .tx_buf = (unsigned long)0,
            .rx_buf = (unsigned long)0,
            .len = 3,
            .cs_change = 1,
            .speed_hz = ADC_SPEED,
            .bits_per_word = 8,
            .delay_usecs = 0,
            .cs_high = 1,
            .cs_low = 1,
            .delay_usecs = 0,
        }
    };

    uint8_t data[3];
    memset(data, 0, 3);

    if (ioctl(fd, SPI_IOC_MESSAGE(1, xfer), data) < 0) {
        syslog(LOG_ERR, "Failed to send SPI message\n");
        return -1;
    }

    // Calculate ADC value
    int adc_value = (data[1] << 8) | data[2];

    return adc_value;
}

int main() {
    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device\n");
        exit(1);
    }

    // Set up SPI parameters
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)0;
    xfer.rx_buf = (unsigned long)0;
    xfer.len = 3;
    xfer.cs_change = 1;
    xfer.speed_hz = ADC_SPEED;
    xfer.bits_per_word = 8;
    xfer.delay_usecs = 0;
    xfer.cs_high = 1;
    xfer.cs_low = 1;
    xfer.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &xfer.mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode\n");
        close(spi_fd);
        exit(1);
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO\n");
        close(spi_fd);
        exit(1);
    }

    // Set up pump GPIO
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file\n");
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler\n");
        fclose(log_file);
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value\n");
            continue;
        }

        // Calculate moisture level
        int moisture_level = (adc_value * 100) / 1024;

        // Log moisture level
        fprintf(log_file, "%lu: Moisture level: %d%%\n", time(NULL), moisture_level);

        // Turn pump on/off
        if (moisture_level < ADC_THRESHOLD) {
            if (gpioRead(PUMP_GPIO) == 0) {
                gpioWrite(PUMP_GPIO, 1);
                fprintf(log_file, "%lu: Pump turned on\n", time(NULL));
            }
        } else {
            if (gpioRead(PUMP_GPIO) == 1) {
                gpioWrite(PUMP_GPIO, 0);
                fprintf(log_file, "%lu: Pump turned off\n", time(NULL));
            }
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    close(spi_fd);
    return 0;
}

