    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file\n");
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler\n");
        fclose(log_file);
        gpioTerminate();
        close(spi_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value\n");
            continue;
        }

        // Calculate moisture level
        int moisture_level = (adc_value * 100) / 1024;

        // Log moisture level
        fprintf(log_file, "%lu: Moisture level: %d%%\n", time(NULL), moisture_level);

        // Turn pump on/off
        if (moisture_level < ADC_THRESHOLD) {
            if (gpioRead(PUMP_GPIO) == 0) {
                gpioWrite(PUMP_GPIO, 1);
                fprintf(log_file, "%lu: Pump turned on\n", time(NULL));
            }
        } else {
            if (gpioRead(PUMP_GPIO) == 1) {
                gpioWrite(PUMP_GPIO, 0);
                fprintf(log_file, "%lu: Pump turned off\n", time(NULL));
            }
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    close(spi_fd);
    return 0;
}
