volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    int csv_fd;
    uint8_t buffer[3];
    char line[256];

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long) buffer;
    xfer.rx_buf = (unsigned long) buffer;
    xfer.len = 3;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.cs_change = 1;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    if ((csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read from SPI device
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to read from SPI device");
            exit(EXIT_FAILURE);
        }

        // Convert ADC values to 12-bit integers
        uint16_t values[3];
        for (int i = 0; i < 3; i++) {
            values[i] = (buffer[i] << 4) | (buffer[i + 1] >> 4);
        }

        // Format line for CSV file
        sprintf(line, "%d,%d,%d\n", values[0], values[1], values[2]);

        // Write to CSV file
        if (write(csv_fd, line, strlen(line)) < 0) {
            perror("Failed to write to CSV file");
            exit(EXIT_FAILURE);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close CSV file
    if (close(csv_fd) < 0) {
        perror("Failed to close CSV file");
    }

    // Release SPI resources
    if (close(spi_fd) < 0) {
        perror("Failed to release SPI resources");
    }

    return 0;
}

