#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>

#include <gpiod.h>
#include <json-c/json.h>

#include <mosquitto.h>

#define MQTT_SERVER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_PIN 17

#define MAX_RECONNECT_ATTEMPTS 10
#define MAX_RECONNECT_BACKOFF 60

struct mosquitto *mosq;
struct mosquitto_message *msg;
struct gpiod_line *line;

void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    syslog(LOG_INFO, "Clean shutdown");
    exit(0);
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "SIGINT received, shutting down");
    cleanup();
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "SIGTERM received, shutting down");
    cleanup();
}

void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS, on_subscribe);
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", rc);
        mosquitto_destroy(mosq);
        mosq = NULL;
        sleep(1);
    }
}

void on_subscribe(struct mosquitto *mosq, void *userdata, int mid, int qos_count, const int *granted_qos) {
    syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->topic == MQTT_TOPIC) {
        json_object *root = json_tokener_parse(message->data);
        if (root) {
            json_object *led_state = json_object_object_get(root, "led_state");
            if (led_state && json_object_get_type(led_state) == json_type_boolean) {
                int state = json_object_get_boolean(led_state);
                if (state) {
                    syslog(LOG_INFO, "Turning LED on");
                    gpiod_line_set_value(line, 1);
                } else {
                    syslog(LOG_INFO, "Turning LED off");
                    gpiod_line_set_value(line, 0);
                }
                json_object_put(root);
            } else {
                syslog(LOG_ERR, "Invalid JSON payload");
                json_object_put(root);
            }
        } else {
            syslog(LOG_ERR, "Failed to parse JSON payload");
        }
    } else {
        syslog(LOG_ERR, "Received message on unexpected topic %s", message->topic);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("rpi_led_control", LOG_PID | LOG_PERROR, LOG_USER);

    if ((line = gpiod_line_request_output("gpiochip0", LED_PIN, "active-high")) == NULL) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        return 1;
    }

    gpiod_line_set_value(line, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_subscribe_callback_set(mosq, on_subscribe);

    int reconnect_attempts = 0;
    struct timeval last_reconnect;
    gettimeofday(&last_reconnect, NULL);

    while (1) {
        if (!mosq) {
            mosquitto_connect(mosq, MQTT_SERVER, MQTT_PORT, 60, NULL, NULL);
            if (mosq) {
                gettimeofday(&last_reconnect, NULL);
                reconnect_attempts = 0;
            }
        }

        if (mosq) {
            int rc = mosquitto_loop(mosq, 1000);
            if (rc == MOSQ_ERR_SUCCESS) {
                continue;
            } else if (rc == MOSQ_ERR_CONN_LOST) {
                syslog(LOG_ERR, "Connection to MQTT broker lost");
                mosquitto_destroy(mosq);
                mosq = NULL;
                reconnect_attempts++;
                if (reconnect_attempts < MAX_RECONNECT_ATTEMPTS) {
                    struct timeval now;
                    gettimeofday(&now, NULL);
                    int backoff = 1 << (reconnect_attempts - 1);
                    if (now.tv_sec - last_reconnect.tv_sec > backoff) {
                        last_reconnect = now;
                        sleep(backoff);
                    }
                } else {
                    syslog(LOG_ERR, "Maximum reconnect attempts reached");
                    break;
                }
            } else {
                syslog(LOG_ERR, "Failed to loop MQTT client: %d", rc);
                mosquitto_destroy(mosq);
                mosq = NULL;
            }
        } else {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

