#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Function to handle signal to clean up GPIO resources
void cleanup(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up alarm LED pin as output
    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up alarm LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up sound sensor pin as input
    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up sound sensor pin\n");
        gpioTerminate();
        return 1;
    }

    // Open the chip
    if (gpioOpen(17, PI_READ) < 0) {
        fprintf(stderr, "Failed to open sound sensor pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Read the sound sensor pin
        int level = gpioRead(17);
        if (level < 0) {
            fprintf(stderr, "Failed to read sound sensor pin\n");
            gpioTerminate();
            return 1;
        }

        // Check if sound event detected
        if (level == 0) {
            // Trigger alarm LED
            gpioWrite(18, 1);
            sleep(1);
            gpioWrite(18, 0);
        }

        // Print sound level reading
        printf("%d\n", level);

        // Delay for 100ms
        usleep(100000);
    }

    return 0;
}

