#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

// Flag to indicate whether the program should exit
volatile sig_atomic_t exit_flag = 0;

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    int chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd == -1) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the line with the specified label
    int line_fd = gpiod_line_request_by_name(chip_fd, "vibration-monitor", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_EVENT_RISING | GPIOD_LINE_EVENT_FALLING);
    if (line_fd == -1) {
        perror("gpiod_line_request_by_name");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Open the log file in append mode
    int log_fd = open("/var/log/vibration_shutdown.log", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("open");
        gpiod_line_release(line_fd);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Main loop
