                close(log_fd);
                gpiod_line_release(line_fd);
                gpiod_chip_close(chip_fd);
                return 1;
            }
        }
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line_fd);
    gpiod_chip_close(chip_fd);

    // Close the log file
    close(log_fd);

    return 0;
