#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define CSV_FILE "flame_events.log"
#define PIN 17
#define POLL_INTERVAL 1000  // milliseconds

static void cleanup(int sig) {
    gpioTerminate();
    exit(0);
}

static void log_event(double timestamp, int pin, int state) {
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening %s for writing: %s\n", CSV_FILE, strerror(errno));
        exit(1);
    }
    fprintf(file, "%f,%d,%d\n", timestamp, pin, state);
    fclose(file);
}

int main() {
    int gpio_fd;
    int pin_state;
    double last_timestamp = 0.0;

    // Initialize GPIO
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpio_strerror(gpio_fd));
        exit(1);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set up pin as input with pull-down resistor
    if (gpioSetMode(PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting pin %d as input: %s\n", PIN, gpio_strerror(gpio_fd));
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down resistor on pin %d: %s\n", PIN, gpio_strerror(gpio_fd));
        gpioTerminate();
        exit(1);
    }

    while (1) {
        // Poll pin
        pin_state = gpioRead(PIN);
        if (pin_state < 0) {
            fprintf(stderr, "Error reading pin %d: %s\n", PIN, gpio_strerror(gpio_fd));
            gpioTerminate();
            exit(1);
        }

        // Log event
        double timestamp = time(NULL);
        if (timestamp - last_timestamp >= 1.0) {
            log_event(timestamp, PIN, pin_state);
            last_timestamp = timestamp;
        }

        // Check for alarm
        if (pin_state == 1) {
            printf("ALARM: Flame detected!\n");
        }

        // Sleep
        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

