#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_BUS 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 3
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1
#define ADC_CHANNEL_2 2
#define LOG_FILE "soil_data.txt"

void sigint_handler(int sig) {
    if (spi_close(SPI_BUS) < 0) {
        perror("spi_close");
    }
    if (fclose(log_file) < 0) {
        perror("fclose");
    }
    if (spi_release(SPI_BUS) < 0) {
        perror("spi_release");
    }
    printf("Goodbye!\n");
    exit(0);
}

int main() {
    struct spi_ioc_transfer transfer;
    int fd;
    FILE *log_file;
    char log_line[32];
    struct tm time;
    int adc_values[ADC_CHANNELS];

    // Initialize the SPI interface
    fd = spi_open(SPI_BUS, SPI_MODE, SPI_SPEED);
    if (fd < 0) {
        perror("spi_open");
        exit(1);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        if (spi_close(SPI_BUS) < 0) {
            perror("spi_close");
        }
        exit(1);
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read the ADC values
        memset(&transfer, 0, sizeof(transfer));
        transfer.tx_buf = NULL;
        transfer.rx_buf = NULL;
        transfer.len = 2;
        transfer.cs_change = 1;
        transfer.speed_hz = SPI_SPEED;
        transfer.delay_usecs = 0;
        transfer.bits_per_word = 8;
        transfer.cs_high_pre_transfer = 1;
        transfer.cs_low_pre_transfer = 1;
        transfer.cs_change_pre_transfer = 1;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            transfer.cs = i;
            if (ioctl(fd, SPI_IOC_MESSAGE(1, &transfer) < 0)) {
                perror("ioctl");
                if (fclose(log_file) < 0) {
                    perror("fclose");
                }
                if (spi_close(SPI_BUS) < 0) {
                    perror("spi_close");
                }
                exit(1);
            }
            adc_values[i] = (transfer.rx_buf[0] << 8) | transfer.rx_buf[1];
            if (adc_values[i] < 0 || adc_values[i] > 1023) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_values[i]);
                continue;
            }
        }

        // Log the ADC values
        time = *localtime(&time(NULL));
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", &time);
        for (int i = 0; i < ADC_CHANNELS; i++) {
            fprintf(log_file, "%s %d\n", log_line, adc_values[i]);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    return 0;
}

