// Function to handle signal to clean up GPIO resources
void cleanup(int sig) {
    // Deactivate all relays
    for (int i = 1; i <= 4; i++) {
        gpioWrite(i, 0);
    }
    // Release all GPIO lines
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Set up GPIO pins for the relays
    for (int i = 17; i <= 24; i++) {
        if (gpioSetMode(i, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", i);
            gpioTerminate();
            return 1;
        }
        // Set all relay pins to inactive (LOW)
        gpioWrite(i, 0);
    }

    // Main loop
    while (1) {
        for (int i = 17; i <= 24; i++) {
            // Activate the current relay
            if (gpioWrite(i, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO value for pin %d\n", i);
                gpioTerminate();
                return 1;
            }
            // Wait for 1 second
            usleep(1000000);
            // Deactivate the current relay
            if (gpioWrite(i, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO value for pin %d\n", i);
                gpioTerminate();
                return 1;
            }
            // Wait for 1 second
            usleep(1000000);
        }
    }

    // This line will never be reached due to the infinite loop
    return 0;
}

