#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define LED_PIN 16
#define DEBOUNCE_DELAY 100
#define THRESHOLD 500
#define LOG_FILE "sound_events.log"

volatile bool running = true;

void sigint_handler(int sig) {
    (void)sig;
    running = false;
}

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s: %s\n", timestamp, message);
    fclose(file);
}

int main() {
    int spi_fd;
    int adc_value;
    int gpio_fd;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("ioctl");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    while (running) {
        // Read ADC value
        struct spi_ioc_transfer transfer = {
            .tx_buf = NULL,
            .rx_buf = NULL,
            .len = 2,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 0,
            .cs_high = 1,
            .cs_low = 1,
            .delay_usecs = 0,
            .bits_per_word = 8,
        };

        transfer.cs = SPI_CS;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &transfer) < 0)) {
            perror("ioctl");
            close(spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        adc_value = (transfer.rx_buf[0] << 8) | transfer.rx_buf[1];

        if (adc_value > THRESHOLD) {
            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Log event
            log_event("Sound detected");

            // Debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

