#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_THRESHOLD 5
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_MOTOR_IN1 17
#define GPIO_MOTOR_IN2 18
#define GPIO_MOTOR_ENA 27
#define PWM_DUTY 150
#define PWM_MAX 255
#define GPIO_MOTOR_FORWARD 1
#define GPIO_MOTOR_REVERSE -1
#define GPIO_MOTOR_STOP 0
#define LOG_FILE "rain_log.txt"

volatile sig_atomic_t stop_motor = 0;

void sig_handler(int sig) {
    stop_motor = 1;
}

int main() {
    int spi_fd, log_fd;
    int motor_fd;
    int motor_state = GPIO_MOTOR_FORWARD;
    char timestamp[20];
    struct timeval tv;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;
    char buffer[4];

    // Initialize the driver library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize the GPIO library: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    sa_int.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa_int, NULL);
    sigaction(SIGTERM, &sa_int, NULL);

    // Open the SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open the SPI device: %s", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up the SPI interface
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to set the SPI mode: %s", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set the SPI speed: %s", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open the log file: %s", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize the motor
    motor_fd = gpioOpen(GPIO_MOTOR_IN1, GPIO_MODE_OUTPUT);
    if (motor_fd < 0) {
        syslog(LOG_ERR, "Failed to open the motor pin: %s", strerror(errno));
        close(spi_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    motor_fd = gpioOpen(GPIO_MOTOR_IN2, GPIO_MODE_OUTPUT);
    if (motor_fd < 0) {
        syslog(LOG_ERR, "Failed to open the motor pin: %s", strerror(errno));
        close(spi_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    motor_fd = gpioOpen(GPIO_MOTOR_ENA, GPIO_MODE_OUTPUT);
    if (motor_fd < 0) {
        syslog(LOG_ERR, "Failed to open the motor pin: %s", strerror(errno));
        close(spi_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up the PWM
    if (gpioSetMode(GPIO_MOTOR_ENA, GPIO_MODE_OUTPUT_PWM) < 0) {
        syslog(LOG_ERR, "Failed to set the motor pin as PWM: %s", strerror(errno));
        close(spi_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioPWM(GPIO_MOTOR_ENA, 0) < 0) {
        syslog(LOG_ERR, "Failed to set the PWM duty cycle: %s", strerror(errno));
        close(spi_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (!stop_motor) {
        // Read the rain sensor
        if (read(spi_fd, buffer, 4) < 0) {
            syslog(LOG_ERR, "Failed to read the rain sensor: %s", strerror(errno));
            break;
        }

        // Convert the raw value to a rain level
        int rain_level = (buffer[0] << 8) | buffer[1];

        // Log the rain level
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
            syslog(LOG_ERR, "Failed to write to the log file: %s", strerror(errno));
            break;
        }
        if (write(log_fd, " Rain level: ", strlen(" Rain level: ")) < 0) {
            syslog(LOG_ERR, "Failed to write to the log file: %s", strerror(errno));
            break;
        }
        if (write(log_fd, buffer, 2) < 0) {
            syslog(LOG_ERR, "Failed to write to the log file: %s", strerror(errno));
            break;
        }
        if (write(log_fd, "\n", 1) < 0) {
            syslog(LOG_ERR, "Failed to write to the log file: %s", strerror(errno));
            break;
        }
        if (fsync(log_fd) < 0) {
            syslog(LOG_ERR, "Failed to flush the log file: %s", strerror(errno));
            break;
        }

        // Check if the rain level exceeds the threshold
        if (rain_level > RAIN_THRESHOLD) {
            // Drive the motor forward
            motor_state = GPIO_MOTOR_FORWARD;
            if (gpioWrite(GPIO_MOTOR_IN1, GPIO_MOTOR_FORWARD) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioWrite(GPIO_MOTOR_IN2, GPIO_MOTOR_STOP) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioPWM(GPIO_MOTOR_ENA, PWM_DUTY) < 0) {
                syslog(LOG_ERR, "Failed to set the PWM duty cycle: %s", strerror(errno));
                break;
            }
            usleep(3000000);
            if (gpioWrite(GPIO_MOTOR_IN1, GPIO_MOTOR_STOP) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioWrite(GPIO_MOTOR_IN2, GPIO_MOTOR_FORWARD) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioPWM(GPIO_MOTOR_ENA, 0) < 0) {
                syslog(LOG_ERR, "Failed to set the PWM duty cycle: %s", strerror(errno));
                break;
            }
        } else {
            // Drive the motor reverse
            motor_state = GPIO_MOTOR_REVERSE;
            if (gpioWrite(GPIO_MOTOR_IN1, GPIO_MOTOR_STOP) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioWrite(GPIO_MOTOR_IN2, GPIO_MOTOR_FORWARD) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioPWM(GPIO_MOTOR_ENA, PWM_DUTY) < 0) {
                syslog(LOG_ERR, "Failed to set the PWM duty cycle: %s", strerror(errno));
                break;
            }
            usleep(3000000);
            if (gpioWrite(GPIO_MOTOR_IN1, GPIO_MOTOR_FORWARD) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioWrite(GPIO_MOTOR_IN2, GPIO_MOTOR_STOP) < 0) {
                syslog(LOG_ERR, "Failed to set the motor direction: %s", strerror(errno));
                break;
            }
            if (gpioPWM(GPIO_MOTOR_ENA, 0) < 0) {
                syslog(LOG_ERR, "Failed to set the PWM duty cycle: %s", strerror(errno));
                break;
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(spi_fd);
    close(log_fd);
    gpioTerminate();

    return 0;
}

