static void init_adc() {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = {
        .consumer = "clap_detector",
        .direction = GPIOD_LINE_DIRECTION_INPUT,
        .active_state = GPIOD_LINE_ACTIVE_LOW,
        .edge = GPIOD_LINE_EVENT_BOTH,
        .flags = GPIOD_LINE_FLAG_BIAS_PULL_UP
    };

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    if ((adc_line = gpiod_chip_get_line(chip, ADC_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(adc_line, GPIOD_LINE_REQUEST_FLAG_NONE) != 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_config(adc_line, &config) != 0) {
        perror("gpiod_line_config");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((led_line = gpiod_chip_get_line(chip, LED_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, GPIOD_LINE_REQUEST_FLAG_NONE) != 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(led_line);
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(led_line, 0);
}

static void cleanup() {
    gpiod_line_release(led_line);
    gpiod_line_release(adc_line);
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
