#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_CS 8
#define ADC_DIN 9
#define ADC_CLK 11
#define ADC_DOUT 10
#define ADC_VREF 3300
#define ADC_VDD 3300
#define ADC_VCC 3300
#define ADC_VOUT 0
#define ADC_GAIN 1.0
#define ADC_OFFSET 0
#define ADC_SCALE 1.0
#define ADC_SAMPLING_PERIOD 500000
#define LOG_FILE "magnetic_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd, gpio_fd;
    int ret;
    uint8_t buf[2];
    uint16_t raw_reading;
    double magnetic_field;
    time_t now;
    struct sigaction sa;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(ADC_CS, PI_OUTPUT);
    gpioSetMode(ADC_DIN, PI_OUTPUT);
    gpioSetMode(ADC_CLK, PI_OUTPUT);
    gpioSetMode(ADC_DOUT, PI_INPUT);
    gpioSetPullUpDnControl(ADC_DOUT, PI_PUD_UP);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read ADC value
        buf[0] = 0x00; // Start bit
        buf[1] = 0x01; // Single-ended, channel 0
        ret = write(spi_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
            continue;
        }
        ret = read(spi_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read from SPI device: %s\n");
            continue;
        }

        // Check for errors
        if (buf[0] & 0x80) {
            fprintf(stderr, "ADC read error\n");
            continue;
        }

        // Convert raw reading to magnetic field strength
        raw_reading = (buf[1] << 8) | buf[0];
        magnetic_field = (raw_reading * ADC_GAIN - ADC_OFFSET) * ADC_SCALE;

        // Log data
        time(&now);
        fprintf(log_file, "%lu,%f\n", now, magnetic_field);
        fflush(log_file);

        // Sleep
        usleep(ADC_SAMPLING_PERIOD);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

