#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 10.0
#define ADC_GAIN 0.5
#define ADC_OFFSET 0.0
#define LED_PIN 21
#define LOG_FILE "magnetic_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetMode(LED_PIN, GPIO_MODE_OUTPUT);
    gpioWrite(LED_PIN, 0);

    if (spiOpen(0, 0, 0) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        exit(1);
    }

    spiClose(0);
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetMode(LED_PIN, GPIO_MODE_OUTPUT);

    if (spiOpen(0, 0, 0) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        gpioTerminate();
        exit(1);
    }

    if (access(LOG_FILE, F_OK) == -1) {
        if (creat(LOG_FILE, 0644) == -1) {
            fprintf(stderr, "Failed to create log file\n");
            spiClose(0);
            gpioTerminate();
            exit(1);
        }
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(0);
        gpioTerminate();
        exit(1);
    }

    while (running) {
        int adc_value = spiXfer(0, 0, 0, 1, 0, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        float magnetic_field = (adc_value * ADC_GAIN) + ADC_OFFSET;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %f\n", timestamp, magnetic_field);

        if (magnetic_field > ADC_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(100000);
    }

    fclose(log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

