#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 0
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define LOG_INTERVAL 60

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int adc_fd;
    char log_buf[32];
    struct tm *log_time;
    time_t log_time_t;
    uint16_t raw_value;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open ADC device
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open ADC device\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        close(adc_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read ADC value
        if (ioctl(adc_fd, SPI_IOC_READ, &raw_value) < 0) {
            fprintf(log_fd, "%s -1\n", ctime_r(&log_time_t, log_buf));
            continue;
        }

        // Format log message
        log_time_t = time(NULL);
        log_time = localtime(&log_time_t);
        sprintf(log_buf, "%04d-%02d-%02d %02d:%02d:%02d %d\n", log_time->tm_year + 1900, log_time->tm_mon + 1, log_time->tm_mday, log_time->tm_hour, log_time->tm_min, log_time->tm_sec, raw_value);

        // Write log message
        if (write(log_fd, log_buf, strlen(log_buf)) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            close(spi_fd);
            close(adc_fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        // Sleep for log interval
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up
    close(spi_fd);
    close(adc_fd);
    close(log_fd);
    gpioTerminate();

    return 0;
}

