#include <signal.h>
#include <errno.h>

#define GPIO17 17
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_VCC 5.0
#define ADC_VCC_MV 1000.0
#define ADC_RESOLUTION 10
#define LOG_FILE "current_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int gpio_export(int gpio) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    if (write(fd, &gpio, sizeof(gpio)) != sizeof(gpio)) {
        perror("Failed to write to /sys/class/gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_direction(int gpio, int direction) {
    int fd = open("/sys/class/gpio/gpio" + gpio + "/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/gpio" + gpio + "/direction");
        return -1;
    }

    if (direction == 1) {
        if (write(fd, "out", 3) != 3) {
            perror("Failed to write to /sys/class/gpio/gpio" + gpio + "/direction");
            close(fd);
            return -1;
        }
    } else if (direction == 0) {
        if (write(fd, "in", 2) != 2) {
            perror("Failed to write to /sys/class/gpio/gpio" + gpio + "/direction");
            close(fd);
            return -1;
        }
    }

    close(fd);
    return 0;
}

int gpio_set_value(int gpio, int value) {
    int fd = open("/sys/class/gpio/gpio" + gpio + "/value", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/gpio" + gpio + "/value");
        return -1;
    }

    if (write(fd, value ? "1" : "0", 1) != 1) {
        perror("Failed to write to /sys/class/gpio/gpio" + gpio + "/value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to configure SPI device");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, uint8_t *data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)0,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to transfer data over SPI");
        return -1;
    }

    return 0;
}

int main() {
    int gpio_fd = gpio_export(GPIO17);
    if (gpio_fd < 0) {
        return 1;
    }

    if (gpio_set_direction(GPIO17, 1) < 0) {
        close(gpio_fd);
        return 1;
    }

    gpio_set_value(GPIO17, 1);

    int spi_fd = spi_open("/dev/spidev0.0");
    if (spi_fd < 0) {
        gpio_set_value(GPIO17, 0);
        close(gpio_fd);
        return 1;
    }

    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        close(spi_fd);
        gpio_set_value(GPIO17, 0);
        close(gpio_fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    struct timespec last_sample = {0, 0};
    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        if (now.tv_sec - last_sample.tv_sec >= 1) {
            last_sample = now;

            uint8_t data = 0;
            if (spi_transfer(spi_fd, &data) < 0) {
                close(spi_fd);
                gpio_set_value(GPIO17, 0);
                close(gpio_fd);
                close(log_fd);
                return 1;
            }

            int adc_value = (data * ADC_MAX) / 255;
            double current = (adc_value * ADC_VCC_MV) / ADC_MAX / ADC_RESOLUTION;
            char buffer[64];
            sprintf(buffer, "%ld,%f\n", now.tv_sec, current);
            if (write(log_fd, buffer, strlen(buffer)) != strlen(buffer)) {
                perror("Failed to write to log file");
                close(spi_fd);
                gpio_set_value(GPIO17, 0);
                close(gpio_fd);
                close(log_fd);
                return 1;
            }
        }

        usleep(100000);
    }

    close(spi_fd);
    gpio_set_value(GPIO17, 0);
    close(gpio_fd);
    close(log_fd);
    return 0;
}

