#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <gpiod.h>

// Flag to break the sampling loop
volatile int stop_sampling = 0;

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    stop_sampling = 1;
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up SPI bus
    int spi_fd = gpioOpen(0, 8); // CE0 on GPIO8
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode and speed
    if (gpioSetMode(spi_fd, SPI_MODE_0) < 0 || gpioSetClockSpeed(spi_fd, 1000000) < 0) {
        fprintf(stderr, "Failed to set up SPI bus\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize gpiod library
    int chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to initialize gpiod library\n");
        fclose(log_file);
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Get line for SPI0 CE0
    int line = gpiod_chip_get_line(chip_fd, 8);
    if (line < 0) {
        fprintf(stderr, "Failed to get line for SPI0 CE0\n");
        gpiod_chip_close(chip_fd);
        fclose(log_file);
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set line as output
    if (gpiod_line_request_output(line, "active-high") < 0) {
        fprintf(stderr, "Failed to set line as output\n");
        gpiod_chip_close(chip_fd);
        fclose(log_file);
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main sampling loop
    struct timeval last_sample_time;
    gettimeofday(&last_sample_time, NULL);
    while (!stop_sampling) {
        // Sample sensor
        int sample = gpiod_line_get_value(line);
        if (sample < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Convert ADC reading to current value
        int voltage = (sample * 5.0) / 1024.0;

        // Check if voltage is within valid range
        if (voltage < 0 || voltage > 5.0) {
            fprintf(stderr, "Warning: voltage out of range\n");
            continue;
        }

        // Append to log file
        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
        fprintf(log_file, "%s %.2f A\n", timestamp, voltage);
        fflush(log_file);

        // Sleep for 100ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI bus
    gpioClose(spi_fd);

    // Terminate gpiod library
    gpiod_chip_close(chip_fd);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

