#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_line_release(GPIO4);
    gpiod_line_release(GPIO17);
    gpiod_context_free(gpiod_ctx);
    exit(0);
}

int main() {
    // Initialize GPIO context
    gpiod_ctx = gpiod_ctx_new();
    if (!gpiod_ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    // Initialize GPIO lines
    gpio4 = gpiod_line_request_output(gpiod_ctx, "gpio4", GPIOD_LINE_ACTIVE_LOW);
    if (!gpio4) {
        fprintf(stderr, "Failed to request GPIO4\n");
        gpiod_ctx_free(gpiod_ctx);
        return 1;
    }

    gpio17 = gpiod_line_request_output(gpiod_ctx, "gpio17", GPIOD_LINE_ACTIVE_LOW);
    if (!gpio17) {
        fprintf(stderr, "Failed to request GPIO17\n");
        gpiod_line_release(gpio4);
        gpiod_ctx_free(gpiod_ctx);
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpiod_line_release(gpio4);
        gpiod_line_release(gpio17);
