#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        if (spi_close()) {
            printf("Error closing SPI handle\n");
        }
        driver_terminate();
        exit(0);
    }
}

void log_data(double moisture_level) {
    char buffer[256];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 256, "%Y-%m-%d %H:%M:%S,", timeinfo);
    sprintf(buffer + strlen(buffer), "%.2f", moisture_level);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(file, "%s\n", buffer);
    fclose(file);
    printf("%s\n", buffer);
}

int read_mcp3008(int channel) {
    spi_config_t config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .mode = 0,
        .bits = 8,
        .cs = 0,
        .clock_edge = SPI_CPHA_0,
        .clock_polarity = SPI_CPOL_0
    };
    if (spi_setup(config) < 0) {
        printf("Error setting up SPI\n");
        return -1;
    }
    uint16_t value;
    if (spi_transfer(channel, MCP3008_CHANNEL, &value, 2) < 0) {
        printf("Error transferring data\n");
        sleep(1);
        return read_mcp3008(channel);
    }
    return value;
}

double calculate_moisture_level(int adc_value) {
    return (adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC) * 100;
}

int spi_setup(spi_config_t config) {
    return driver_spi_setup(config.channel, config.baud, config.mode, config.bits, config.cs, config.clock_edge, config.clock_polarity);
}

int main() {
    if (driver_init() < 0) {
        printf("Error initializing driver library\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        sleep(READ_DELAY);
    }
    return 0;
}

