#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define POLL_INTERVAL 50
#define CAPTURE_COMMAND "libcamera-still -o %s"

#define LOG_TAG "security_cam"

static void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    gpiod_close();
    syslog(LOG_INFO, "Released GPIO resources");
    closelog();
    syslog(LOG_INFO, "Closed syslog");
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line %d", PIR_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);
    if (ret) {
        syslog(LOG_ERR, "Failed to request line %d as input", PIR_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_event_fd(line, -1);
    gpiod_line_set_active_state(line, 0);
    gpiod_line_set_event_fd(line, -1);

    syslog(LOG_INFO, "Initialized GPIO");
}

static void capture_image(const char *filename) {
    pid_t pid;
    int status;

    pid = fork();
    if (pid == -1) {
        syslog(LOG_ERR, "Failed to fork");
        return;
    }

    if (pid == 0) {
        execl("/usr/bin/libcamera-still", "libcamera-still", "-o", filename, NULL);
        syslog(LOG_ERR, "Failed to execute libcamera-still");
        exit(EXIT_FAILURE);
    }

    waitpid(pid, &status, 0);
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still failed with exit status %d", WEXITSTATUS(status));
    }
}

int main() {
    int fd;
    struct gpiod_line *line;
    int prev_state;
    char filename[256];
    struct tm *tm;
    time_t now;

    openlog(LOG_TAG, LOG_PID | LOG_PERROR, LOG_USER);

    init_gpio();

    syslog(LOG_INFO, "Started");

    while (1) {
        fd = gpiod_line_get_value(PIR_PIN);
        if (fd == -1) {
            syslog(LOG_ERR, "Failed to get line %d value", PIR_PIN);
            break;
        }

        if (fd != prev_state) {
            syslog(LOG_INFO, "Motion detected");
            prev_state = fd;

            sleep(DEBOUNCE_DELAY);
            fd = gpiod_line_get_value(PIR_PIN);
            if (fd == -1) {
                syslog(LOG_ERR, "Failed to get line %d value after debounce", PIR_PIN);
                break;
            }

            if (fd != prev_state) {
                syslog(LOG_INFO, "Confirmed motion");
                prev_state = fd;

                time(&now);
                tm = localtime(&now);
                strftime(filename, sizeof(filename), "/home/pi/security_cam/%Y-%m-%d_%H-%M-%S_%s.jpg", tm);
                capture_image(filename);
            }
        }

        sleep(POLL_INTERVAL);
    }

    gpiod_close();
    syslog(LOG_INFO, "Released GPIO resources");
    closelog();
    syslog(LOG_INFO, "Closed syslog");

    return EXIT_SUCCESS;
}

