    if (argc > 1) {
        device_path = argv[1];
    }

    // Open the device
    fd = open(device_path, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        return 1;
    }

    // Get the device info
    struct libcamera_device_info info;
    if (libcamera_device_get_info(fd, &info) < 0) {
        perror("libcamera_device_get_info");
        close(fd);
        return 1;
    }

    // Create a stream
    device = libcamera_device_new(fd);
    if (!device) {
        perror("libcamera_device_new");
        close(fd);
        return 1;
    }

    // Create a stream
    stream = libcamera_stream_new(device, 0);
    if (!stream) {
        perror("libcamera_stream_new");
        libcamera_device_unref(device);
        close(fd);
        return 1;
    }

    // Configure the stream
    struct libcamera_stream_format format;
    format.width = 1920;
    format.height = 1080;
    format.format = LIBCAMERA_FORMAT_Y8;
    if (libcamera_stream_set_format(stream, &format) < 0) {
        perror("libcamera_stream_set_format");
        libcamera_stream_unref(stream);
        libcamera_device_unref(device);
        close(fd);
        return 1;
    }

    // Map the buffer
    buffer_size = 1920 * 1080 * 2;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        libcamera_stream_unref(stream);
        libcamera_device_unref(device);
        close(fd);
        return 1;
    }

    // Open the output file
    char filename[MAX_FILENAME_LENGTH];
    sprintf(filename, "image_0001.pgm");
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        munmap(buffer, buffer_size);
        libcamera_stream_unref(stream);
        libcamera_device_unref(device);
        close(fd);
        return 1;
    }

    // Write the PGM header
    fprintf(fp, "P5\n%d %d\n255\n", 1920, 1080);

    // Main loop
    struct timeval timeout;
    fd_set read_fds;
    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);
        timeout.tv_sec = 2;
        timeout.tv_usec = 0;
        if (select(fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            perror("select");
            break;
        }

        if (FD_ISSET(fd, &read_fds)) {
            // Dequeue a frame
            struct libcamera_buffer *buffer;
            if (libcamera_stream_dequeue(stream, &buffer) < 0) {
                if (errno == EAGAIN) {
                    continue;
                }
                perror("libcamera_stream_dequeue");
                break;
            }

            // Copy the frame to the mapped buffer
            memcpy(buffer, buffer, buffer_size);

            // Save the frame to a file
            fwrite(buffer, 1, buffer_size, fp);

            // Unref the buffer
            libcamera_buffer_unref(buffer);
        }
    }

    // Close the output file
    fclose(fp);

    // Unmap the buffer
    munmap(buffer, buffer_size);

    // Unref the stream
    libcamera_stream_unref(stream);

    // Unref the device
    libcamera_device_unref(device);

    // Close the device
    close(fd);

    return 0;
