#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <signal.h>
#include <errno.h>

#define VIDEO_DEV "/dev/video0"
#define VIDEO_BUS "/dev/video0"
#define BUFFER_COUNT 4
#define BUFFER_SIZE 1920 * 1080 * 2 // YUYV format, 1920x1080 resolution
#define MAX_DGRAM_SIZE 65000
#define TARGET_IP "192.168.1.100"
#define TARGET_PORT 1234

struct v4l2_format format = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .fmt = V4L2_PIX_FMT_YUYV,
    .width = 1920,
    .height = 1080,
    .num_planes = 1,
    .reserved = {0},
};

struct v4l2_requestbuffers req = {
    .count = BUFFER_COUNT,
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
};

struct v4l2_buffer buf[BUFFER_COUNT];

struct sockaddr_in target_addr;
int sock;

void sigint_handler(int sig) {
    printf("Caught signal %d, stopping streaming...\n", sig);
    close(sock);
    munmap(buf[0].m.userptr, BUFFER_SIZE);
    for (int i = 1; i < BUFFER_COUNT; i++) {
        munmap(buf[i].m.userptr, BUFFER_SIZE);
    }
    exit(0);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <library's API call>\n", argv[0]);
        return 1;
    }

    // Open video device
    int fd = open(VIDEO_DEV, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set format
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return 1;
    }

    // Request buffers
    req.count = BUFFER_COUNT;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return 1;
    }

    // Map buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        buf[i].index = i;
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return 1;
        }
        buf[i].m.userptr = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].offset);
        if (buf[i].m.userptr == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return 1;
        }
    }

    // Create UDP socket
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        for (int i = 0; i < BUFFER_COUNT; i++) {
            munmap(buf[i].m.userptr, buf[i].length);
        }
        close(fd);
        return 1;
    }

    // Set target address
    target_addr.sin_family = AF_INET;
    inet_pton(AF_INET, TARGET_IP, &target_addr.sin_addr);
    target_addr.sin_port = htons(TARGET_PORT);

    // Start streaming
    int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(sock);
        for (int i = 0; i < BUFFER_COUNT; i++) {
            munmap(buf[i].m.userptr, buf[i].length);
        }
        close(fd);
        return 1;
    }

    // Signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int frame_index = 0;
    int fragment_index = 0;
    int total_fragments = 0;
    int bytes_sent = 0;

    while (1) {
        // Read frame
        if (read(fd, buf[0].m.userptr, BUFFER_SIZE) < 0) {
            perror("read");
            close(sock);
            for (int i = 0; i < BUFFER_COUNT; i++) {
                munmap(buf[i].m.userptr, buf[i].length);
            }
            close(fd);
            return 1;
        }

        // Fragment frame
        int fragment_size = BUFFER_SIZE;
        int datagram_size = 0;
        char datagram[MAX_DGRAM_SIZE];
        while (fragment_size > 0) {
            // Create header
            char header[16];
            header[0] = (char) (frame_index >> 24);
            header[1] = (char) (frame_index >> 16);
            header[2] = (char) (frame_index >> 8);
            header[3] = (char) frame_index;
            header[4] = (char) (fragment_index >> 24);
            header[5] = (char) (fragment_index >> 16);
            header[6] = (char) (fragment_index >> 8);
            header[7] = (char) fragment_index;
            header[8] = (char) (total_fragments >> 24);
            header[9] = (char) (total_fragments >> 16);
            header[10] = (char) (total_fragments >> 8);
            header[11] = (char) total_fragments;
            header[12] = (char) (datagram_size >> 24);
            header[13] = (char) (datagram_size >> 16);
            header[14] = (char) (datagram_size >> 8);
            header[15] = (char) datagram_size;

            // Copy fragment
            memcpy(datagram + datagram_size, buf[0].m.userptr, fragment_size);
            datagram_size += fragment_size;
            fragment_size -= fragment_size;

            // Send datagram
            if (sendto(sock, datagram, datagram_size, 0, (struct sockaddr *) &target_addr, sizeof(target_addr)) < 0) {
                perror("sendto");
                close(sock);
                for (int i = 0; i < BUFFER_COUNT; i++) {
                    munmap(buf[i].m.userptr, buf[i].length);
                }
                close(fd);
                return 1;
            }

            bytes_sent += datagram_size;
            fragment_index++;
            total_fragments++;
        }

        // Move to next frame
        frame_index++;
        for (int i = 0; i < BUFFER_COUNT; i++) {
            if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
                perror("VIDIOC_QBUF");
                close(sock);
                for (int j = 0; j < BUFFER_COUNT; j++) {
                    munmap(buf[j].m.userptr, buf[j].length);
                }
                close(fd);
                return 1;
            }
        }
    }

    return 0;
}

