    close(sock);
    munmap(buf[0].m.userptr, BUFFER_SIZE);
    for (int i = 1; i < BUFFER_COUNT; i++) {
        munmap(buf[i].m.userptr, BUFFER_SIZE);
    }
    exit(0);
