            munmap(buffers[i], buffers[i].length);
        }
        free(buffers);
        close(fd);
        exit(1);
    }

    // Unmap the buffers
    for (i = 0; i < req.count; i++) {
        munmap(buffers[i], buffers[i].length);
    }

    // Free the buffer array
    free(buffers);

