// Define the GPIO pin numbers
#define PAN_SERVO 4
#define TILT_SERVO 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define the servo mid-position value
#define MID_POSITION 75

// Define the servo pulse width range
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define the button press threshold
#define BUTTON_PRESS_THRESHOLD 0.5

// Define the poll interval
#define POLL_INTERVAL 50

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Release all allocated resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the servo pins as PWM outputs
    if (gpioSetMode(PAN_SERVO, PI_PWM) < 0 || gpioSetMode(TILT_SERVO, PI_PWM) < 0) {
        fprintf(stderr, "Failed to set up servo pins as PWM outputs\n");
        gpioTerminate();
        return 1;
    }

    // Set up the button pins as inputs with internal pull-ups
    if (gpioSetMode(TILT_UP_BUTTON, PI_INPUT) < 0 || gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT) < 0 || gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up button pins as inputs\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the servos to the mid-position
    if (gpioHardwarePWM(PAN_SERVO, 1000) < 0 || gpioHardwarePWM(TILT_SERVO, 1000) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Poll the button states
        int tilt_up = gpioRead(TILT_UP_BUTTON) == 0;
        int tilt_down = gpioRead(TILT_DOWN_BUTTON) == 0;
        int pan_left = gpioRead(PAN_LEFT_BUTTON) == 0;
        int pan_right = gpioRead(PAN_RIGHT_BUTTON) == 0;

        // Adjust the tilt axis
        if (tilt_up) {
            int tilt_position = gpioGetPWM(TILT_SERVO) + 5;
            if (tilt_position > 125) {
                tilt_position = 125;
            }
            gpioHardwarePWM(TILT_SERVO, (tilt_position * 1000) / 125);
        } else if (tilt_down) {
            int tilt_position = gpioGetPWM(TILT_SERVO) - 5;
            if (tilt_position < 25) {
                tilt_position = 25;
            }
            gpioHardwarePWM(TILT_SERVO, (tilt_position * 1000) / 125);
        }

        // Adjust the pan axis
        if (pan_left) {
            int pan_position = gpioGetPWM(PAN_SERVO) - 5;
            if (pan_position < 25) {
                pan_position = 25;
            }
            gpioHardwarePWM(PAN_SERVO, (pan_position * 1000) / 125);
        } else if (pan_right) {
            int pan_position = gpioGetPWM(PAN_SERVO) + 5;
            if (pan_position > 125) {
                pan_position = 125;
            }
            gpioHardwarePWM(PAN_SERVO, (pan_position * 1000) / 125);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Release all allocated resources
    gpioTerminate();
    return 0;
}

