#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NODE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmt;
    struct v4l2_frmsizeenum size;
    struct v4l2_frmivalenum interval;
    struct v4l2_control control;
    int i, j;

    // Open the device node
    fd = open(DEVICE_NODE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device node");
        return 1;
    }

    // Check if the device node exists and can be opened
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    // Print device information
    printf("Device: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Driver: %s\n", cap.driver);
    printf("Card type: %s\n", cap.card_type);

    // Enumerate supported frame sizes
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        printf("Format: %s\n", fmt.description);
        size.index = 0;
        size.type = V4L2_FRMSIZE_TYPE_DISCRETE;
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &size) == 0) {
            printf("  Size: %dx%d\n", size.discrete.width, size.discrete.height);
            size.index++;
        }
        fmt.index++;
    }

    // Check if frame size enumeration failed
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return 1;
    }

    // Enumerate frame intervals for each size
    for (i = 0; i < fmt.index; i++) {
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.index = i;
        ioctl(fd, VIDIOC_ENUM_FMT, &fmt);
        size.index = 0;
        size.type = V4L2_FRMSIZE_TYPE_DISCRETE;
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &size) == 0) {
            interval.index = 0;
            interval.type = V4L2_FRMIVAL_TYPE_DISCRETE;
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &interval) == 0) {
                printf("  Size: %dx%d, Interval: %d/%d\n", size.discrete.width, size.discrete.height, interval.discrete numerator, interval.discrete.denominator);
                interval.index++;
            }
            size.index++;
        }
    }

    // Check if frame interval enumeration failed
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("Failed to enumerate frame intervals");
        close(fd);
        return 1;
    }

    // Query autofocus control
    control.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &control) < 0) {
        perror("Failed to query autofocus control");
        close(fd);
        return 1;
    }

    // Print autofocus capability
    if (control.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus: Disabled\n");
    } else if (control.flags & V4L2_CTRL_FLAG_READ_ONLY) {
        printf("Autofocus: Read-only\n");
    } else {
        printf("Autofocus: Supported\n");
    }

    // Close the device node
    close(fd);

    return 0;
}

