#define GPIO17 17
#define PIR_PIN GPIO17
#define PULL_DOWN 1
#define DEBOUNCE_TIME 2000000
#define POLL_TIME 100000
#define JPEG_QUALITY 85
#define HTTP_PORT 8080
#define HTTP_ENDPOINT "http://<IP>:<port>/upload"

int http_init = 0;
int gpio_fd = -1;
int motion_detected = 0;
time_t last_motion = 0;

void cleanup() {
    if (http_init) {
        curl_global_cleanup();
        http_init = 0;
    }
    if (gpio_fd != -1) {
        gpio_fd = -1;
        gpioTerminate();
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    cleanup();
    exit(0);
}

void init_gpio() {
    if (gpio_fd == -1) {
        gpio_fd = gpioInitialise();
        if (gpio_fd < 0) {
            fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
            exit(1);
        }
        if (gpioSetMode(gpio_fd, PIR_PIN, PI_INPUT) < 0) {
            fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
            exit(1);
        }
        if (gpioSetPullUpDnControl(gpio_fd, PIR_PIN, PULL_DOWN) < 0) {
            fprintf(stderr, "Error setting pull-down resistor: %s\n", strerror(errno));
            exit(1);
        }
    }
}

void poll_gpio() {
    if (gpioRead(gpio_fd, PIR_PIN) == 1 && !motion_detected) {
        motion_detected = 1;
        last_motion = time(NULL);
    } else if (gpioRead(gpio_fd, PIR_PIN) == 0 && motion_detected) {
        motion_detected = 0;
