#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO17 17
#define DEBOUNCE_TIMEOUT 50
#define CAPTURE_TIMEOUT 2000
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGES_DIR "/home/pi/images"

// Function to log a message to the log file
void log_message(const char *format, ...) {
    char timestamp[32];
    time_t now;
    struct tm *lt;
    va_list args;

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", lt);

    va_start(args, format);
    vfprintf(stderr, format, args);
    fprintf(stderr, " [%s]\n", timestamp);
    va_end(args);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fclose(log_file);
}

// Function to capture an image using the camera utility
int capture_image(const char *filename) {
    char command[256];
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return -1;
    }

    sprintf(command, "raspistill -o %s -w 640 -h 480 -q 85 -t %d -nopreview", filename, CAPTURE_TIMEOUT);
    if (system(command) != 0) {
        fprintf(log_file, "Error capturing image: %s\n", strerror(errno));
        fclose(log_file);
        return -1;
    }

    fclose(log_file);
    return 0;
}

// Signal handler to clean up resources
void sigint_handler(int sig) {
    gpiod_close();
    exit(0);
}

int main() {
    int fd;
    int value;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    int num_events;
    char filename[64];

    // Open the GPIO chip
    fd = gpiod_chip_open("/dev/gpiochip0");
    if (fd < 0) {
        log_message("Error opening GPIO chip: %s", strerror(errno));
        return 1;
    }

    // Claim GPIO17 as an input with edge-falling detection
    line = gpiod_chip_get_line(fd, GPIO17);
    if (line == NULL) {
        log_message("Error claiming GPIO17: %s", strerror(errno));
        gpiod_chip_close(fd);
        return 1;
    }

    gpiod_line_request_fd(line, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_EITHER_EDGE);
    gpiod_line_set_event_fd(line, GPIOD_LINE_EVENT_RISING | GPIOD_LINE_EVENT_FALLING);

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        // Wait for a falling edge on GPIO17
        if (gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING, DEBOUNCE_TIMEOUT * 1000) == 0) {
            continue;
        }

        // Get the timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t now = tv.tv_sec;
        struct tm *lt = localtime(&now);
        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_mmm.jpg", lt);

        // Capture an image
        if (capture_image(filename) != 0) {
            continue;
        }

        // Log the event
        log_message("Motion detected at %s", filename);
    }

    // Clean up resources
    gpiod_line_set_event_fd(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(fd);

    return 0;
}

