#include <linux/videodev2.h>

#define WIDTH 640
#define HEIGHT 480
#define FRAMESIZE (WIDTH * HEIGHT * 2)
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_X (WIDTH - CROP_WIDTH) / 2
#define CROP_Y (HEIGHT - CROP_HEIGHT) / 2

struct v4l2_format format = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .fmt = V4L2_PIX_FMT_YUYV,
    .fmt_extension = V4L2_PIX_FMT_YUYV,
    .disp_width = WIDTH,
    .disp_height = HEIGHT,
    .field = V4L2_FIELD_NONE,
};

struct v4l2_requestbuffers reqbufs = {
    .count = 1,
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
};

void sigint_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &format.type) == -1) {
            perror("VIDIOC_STREAMOFF");
            exit(EXIT_FAILURE);
        }
        munmap(buffer, FRAMESIZE);
        close(fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_buffer buf;
    void *buffer;
    int fd;

    if ((fd = open("/dev/video0", O_RDWR)) == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

