        perror("VIDIOC_G_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (format.fmt != V4L2_PIX_FMT_YUYV) {
        printf("Device does not support YUYV format\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_S_FMT, &format) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

