    .count = 1,
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
};

void sigint_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &format.type) == -1) {
            perror("VIDIOC_STREAMOFF");
            exit(EXIT_FAILURE);
        }
        munmap(buffer, FRAMESIZE);
        close(fd);
        exit(EXIT_SUCCESS);
    }
