int main() {
    struct v4l2_capability cap;
    struct v4l2_buffer buf;
    void *buffer;
    int fd;

    if ((fd = open("/dev/video0", O_RDWR)) == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Device supports video capture\n");
    } else {
        printf("Device does not support video capture\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_G_FMT, &format) == -1) {
        perror("VIDIOC_G_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (format.fmt != V4L2_PIX_FMT_YUYV) {
        printf("Device does not support YUYV format\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_S_FMT, &format) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_REQBUFS, &reqbufs) == -1) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if ((buffer = mmap(NULL, FRAMESIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0)) == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        munmap(buffer, FRAMESIZE);
        close(fd);
        exit(EXIT_FAILURE);
    }

