            if (buf.bytesused != FRAMESIZE) {
                printf("Unexpected bytesused: %d\n", buf.bytesused);
                munmap(buffer, FRAMESIZE);
                close(fd);
                exit(EXIT_FAILURE);
            }

            if (buf.m.userptr != buffer) {
                printf("Unexpected buffer pointer\n");
                munmap(buffer, FRAMESIZE);
                close(fd);
                exit(EXIT_FAILURE);
            }

            uint8_t *yuyv = buffer;
            uint8_t *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
            if (!cropped) {
                perror("malloc");
                munmap(buffer, FRAMESIZE);
                close(fd);
                exit(EXIT_FAILURE);
            }

