    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    if ((pan_line = gpiod_chip_get_line(chip, SERVO_PAN_GPIO)) == NULL) {
        fprintf(stderr, "Failed to get line for servo pan\n");
