        exit(1);
    }

    if (gpiod_line_request_output(pan_line, "servo_pan") < 0) {
        fprintf(stderr, "Failed to request output for servo pan\n");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(tilt_line, "servo_tilt") < 0) {
        fprintf(stderr, "Failed to request output for servo tilt\n");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set both servos to neutral position
    if (gpiod_line_set_value(pan_line, 0) < 0) {
        fprintf(stderr, "Failed to set servo pan to neutral\n");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_value(tilt_line, 0) < 0) {
        fprintf(stderr, "Failed to set servo tilt to neutral\n");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set up PWM
    struct gpiod_pwmchip *pwm_chip;
    if ((pwm_chip = gpiod_chip_get_pwmchip(chip)) == NULL) {
        fprintf(stderr, "Failed to get PWM chip\n");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    struct gpiod_pwm *pan_pwm, *tilt_pwm;
    if ((pan_pwm = gpiod_pwm_get(pwm_chip, SERVO_PAN_GPIO)) == NULL) {
        fprintf(stderr, "Failed to get PWM for servo pan\n");
        gpiod_pwm_release(pwm_chip);
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if ((tilt_pwm = gpiod_pwm_get(pwm_chip, SERVO_TILT_GPIO)) == NULL) {
        fprintf(stderr, "Failed to get PWM for servo tilt\n");
        gpiod_pwm_release(pwm_chip);
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

