        fprintf(stderr, "Failed to set PWM frequency for servo pan\n");
        gpiod_pwm_release(pwm_chip);
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_pwm_set_frequency(tilt_pwm, SERVO_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for servo tilt\n");
        gpiod_pwm_release(pwm_chip);
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_chip_close(chip);
        exit(1);
