            fprintf(stderr, "Failed to set PWM duty cycle for servo tilt\n");
            gpiod_pwm_release(pwm_chip);
            gpiod_line_release(pan_line);
            gpiod_line_release(tilt_line);
            gpiod_chip_close(chip);
            exit(1);
        }

        usleep(DELAY);
    }

    // Clean up
    gpiod_pwm_set_duty_cycle(pan_pwm, SERVO_NEUTRAL * 100 / SERVO_MAX);
    gpiod_pwm_set_duty_cycle(tilt_pwm, SERVO_NEUTRAL * 100 / SERVO_MAX);

    gpiod_pwm_release(pwm_chip);
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_chip_close(chip);

    return 0;
