#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_FLOW_SENSOR 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_ROWS 4
#define LCD_COLS 20

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Release GPIO resources
    gpioTerminate();
    // Release I2C resources
    close(i2c_fd);
    // Exit the program
    exit(0);
}

// Function to initialize GPIO
int gpio_init() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return -1;
    }
    // Set up GPIO pin for flow sensor as input
    if (gpioSetMode(GPIO_FLOW_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin for flow sensor\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int i2c_init() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }
    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

// Function to write to LCD
void lcd_write(char *str) {
    // Send command to LCD to move cursor to first line and first column
    i2c_smbus_write_byte(i2c_fd, 0x80);
    // Send command to LCD to clear display
    i2c_smbus_write_byte(i2c_fd, 0x01);
    // Send string to LCD
    for (int i = 0; str[i]; i++) {
        i2c_smbus_write_byte(i2c_fd, str[i]);
    }
}

int main() {
    // Initialize GPIO
    if (gpio_init() < 0) {
        return 1;
    }
    // Initialize I2C
    if (i2c_init() < 0) {
        gpioTerminate();
        return 1;
    }
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    // Initialize variables
    int last_edge = 0;
    int total_volume = 0;
    struct timeval last_update;
    gettimeofday(&last_update, NULL);
    // Main loop
    while (1) {
        // Read GPIO pin
