#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_BUS 1
#define LCD_ADDRESS 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

#define FLOW_SENSOR_INTERVAL 1000  // 1 second
#define FLOW_SENSOR_ZERO_PULSE_COUNT 10  // 10 seconds without pulses

// Function to handle signal interrupts
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Cleanly release all resources
        gpioTerminate();
        i2cClose();
        printf("\nExiting...\n");
        exit(0);
    }
}

// Function to initialize GPIO
void gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
}

// Function to set up GPIO mode and alert
void gpio_setup() {
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        exit(1);
    }
    if (gpioSetAlert(FLOW_SENSOR_GPIO, PI_GPIOTHRESHOLD, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO alert\n");
        exit(1);
    }
}

// Function to initialize I2C bus
void i2c_init() {
    int fd = open("/dev/i2c-" LCD_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, LCD_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        exit(1);
    }
}

// Function to write to LCD
void lcd_write(const char *str) {
    int fd = i2cGetFd();
    if (fd < 0) {
        fprintf(stderr, "Failed to get I2C file descriptor\n");
        exit(1);
    }
    uint8_t buffer[2] = {0x80, 0};
    for (size_t i = 0; i < strlen(str); i++) {
        buffer[1] = str[i];
        if (i2cWrite(fd, buffer, 2) < 0) {
            fprintf(stderr, "Failed to write to LCD\n");
            close(fd);
            exit(1);
        }
    }
}

// Function to read flow sensor pulses
int flow_sensor_read() {
    int pulses = 0;
    struct timeval start, end;
    gettimeofday(&start, NULL);
    fd_set read_fds;
    FD_ZERO(&read_fds);
    FD_SET(FLOW_SENSOR_GPIO, &read_fds);
    struct timeval timeout = {0, FLOW_SENSOR_INTERVAL};
    if (select(FLOW_SENSOR_GPIO + 1, &read_fds, NULL, NULL, &timeout) < 0) {
        fprintf(stderr, "Failed to select on GPIO\n");
        exit(1);
    }
    if (FD_ISSET(FLOW_SENSOR_GPIO, &read_fds)) {
        int value = gpioRead(FLOW_SENSOR_GPIO);
        if (value == 1) {
            pulses++;
        }
    }
