    // Release all GPIO lines
    for (int i = 0; i < num_cols; i++) {
        gpiod_line_release(col_cathodes[i]);
    }
    for (int i = 0; i < num_rows; i++) {
        gpiod_line_release(row_anodes[i]);
    }
    exit(0);
}

int main() {
    // Install the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize the GPIO lines
    for (int i = 0; i < num_cols; i++) {
        if (gpiod_line_request_output(col_cathodes[i], GPIOD_LINE_ACTIVE_LOW) == -1) {
            perror("gpiod_line_request_output");
            exit(1);
        }
