        for (int i = 0; i < num_cols; i++) {
            gpiod_line_set_value(col_cathodes[i], 1);
        }
        for (int i = 0; i < num_rows; i++) {
            gpiod_line_set_value(row_anodes[i], 0);
        }

        // Light the LEDs sequentially by setting the corresponding row anodes HIGH
        for (int col = 0; col < num_cols; col++) {
            for (int row = 0; row < num_rows; row++) {
                gpiod_line_set_value(row_anodes[row], (row == col) ? 1 : 0);
            }
            usleep(delay_ms * 1000);
            for (int row = 0; row < num_rows; row++) {
                gpiod_line_set_value(row_anodes[row], 0);
            }
        }
    }

    return 0;
}
