#define I2C_BUS 1
#define I2C_ADDRESS 0x32
#define FILE_NAME "depth_log.csv"
#define SAMPLE_INTERVAL 100000 // 100ms in microseconds
#define MAX_BUFFER_SIZE 1024

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint32_t timestamp;
} SensorData;

// Function to read data from the sensor
int readSensor(int i2cHandle) {
    uint8_t buffer[2];
    if (ioctl(i2cHandle, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2cHandle, 0x00, buffer) < 0) {
        perror("Failed to read data from sensor");
        return -1;
    }

    uint16_t distance = (buffer[0] << 8) | buffer[1];
    return distance;
}

// Function to write data to the log file
void writeLog(SensorData data) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    if (fseek(file, 0, SEEK_END) < 0) {
        perror("Failed to seek to end of log file");
        fclose(file);
        return;
    }

    if (ftell(file) == 0) {
        fprintf(file, "timestamp,distance\n");
    }

    fprintf(file, "%lu,%d\n", data.timestamp, data.distance);
    fclose(file);
}

// Function to handle SIGINT signal
void sigintHandler(int signal) {
    if (signal == SIGINT) {
        // Close I2C handle
        if (close(i2cHandle) < 0) {
            perror("Failed to close I2C handle");
        }

        // Close log file
        if (fclose(logFile) < 0) {
            perror("Failed to close log file");
        }

        // Terminate sensor interface
        // No need to do anything here, as the program will exit
    }
}

int main() {
    // Open I2C bus
    char i2cDevice[20];
    sprintf(i2cDevice, "/dev/i2c-%d", I2C_BUS);
    i2cHandle = open(i2cDevice, O_RDWR);
    if (i2cHandle < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize signal handler
    signal(SIGINT, sigintHandler);

    // Open log file
    logFile = fopen(FILE_NAME, "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        close(i2cHandle);
        return 1;
    }

    // Create header row if file is newly created
    if (fseek(logFile, 0, SEEK_END) == 0) {
        fprintf(logFile, "timestamp,distance\n");
    }

    // Initialize sensor interface
    // No need to do anything here, as the program will use the I2C bus directly

    // Main loop
    while (1) {
        SensorData data;
        data.timestamp = (uint32_t)time(NULL);

        // Read data from sensor
        int distance = readSensor(i2cHandle);
        if (distance < 0) {
            // Log error and attempt to re-open I2C handle
            fprintf(stderr, "Error reading from sensor, attempting to re-open I2C handle\n");
            if (close(i2cHandle) < 0) {
                perror("Failed to close I2C handle");
            }
            i2cHandle = open(i2cDevice, O_RDWR);
            if (i2cHandle < 0) {
                perror("Failed to open I2C bus");
                break;
            }
            continue;
