#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_PROXIMITY 4
#define GPIO_LINE_LED 17
#define DETECTION_INTERVAL 100000 // 100 ms
#define DETECTION_THRESHOLD 1000 // 1 s

// Function to handle signal
void signal_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open(GPIO_CHIP_NAME));
    gpiod_line_release(GPIO_LINE_PROXIMITY);
    gpiod_line_release(GPIO_LINE_LED);
    exit(0);
}

int main() {
    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        exit(1);
    }

    // Open GPIO line for proximity sensor
    gpiod_line_t *proximity_line = gpiod_chip_get_line(chip, GPIO_LINE_PROXIMITY);
    if (!proximity_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_PROXIMITY, strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open GPIO line for LED
    gpiod_line_t *led_line = gpiod_chip_get_line(chip, GPIO_LINE_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_LED, strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Export lines
    if (gpiod_line_export(proximity_line) < 0) {
        fprintf(stderr, "Failed to export line %d: %s\n", GPIO_LINE_PROXIMITY, strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_export(led_line) < 0) {
        fprintf(stderr, "Failed to export line %d: %s\n", GPIO_LINE_LED, strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set direction of lines
    if (gpiod_line_request_output(proximity_line, 0) < 0) {
        fprintf(stderr, "Failed to set direction of line %d: %s\n", GPIO_LINE_PROXIMITY, strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_output(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set direction of line %d: %s\n", GPIO_LINE_LED, strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open log file
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Main loop
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = DETECTION_INTERVAL;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = DETECTION_INTERVAL;
    timerfd_t timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (timerfd_settime(timer_fd, &timer) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        close(timer_fd);
        fclose(log_file);
        gpiod_line_release(proximity_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    while (1) {
        // Read timer
        uint64_t expires;
        ssize_t bytes_read = read(timer_fd, &expires, sizeof(expires));
        if (bytes_read != sizeof(expires)) {
            fprintf(stderr, "Failed to read timer: %s\n", strerror(errno));
            close(timer_fd);
            fclose(log_file);
            gpiod_line_release(proximity_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(1);
        }

        // Read proximity sensor
        int value;
        if (gpiod_line_get_value(proximity_line, &value) < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_PROXIMITY, strerror(errno));
            close(timer_fd);
            fclose(log_file);
            gpiod_line_release(proximity_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(1);
        }
        if (value == 0) {
            // Blink LED
            gpiod_line_set_value(led_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);
            usleep(900000);

            // Write to log file
            struct tm *timeinfo;
            time_t rawtime;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s Object detected\n", timestamp);
            fflush(log_file);
        }
    }

    // Clean up
    close(timer_fd);
    fclose(log_file);
    gpiod_line_release(proximity_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return 0;
