#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_HZ 10
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_INTERVAL 60

struct gpiod_line *trigger_line = NULL;
struct gpiod_line *echo_line = NULL;

void cleanup() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (fclose(log_file) != 0) {
        syslog(LOG_ERR, "Failed to close log file: %s", strerror(errno));
    }
    syslog(LOG_INFO, "Exiting...");
    closelog();
    exit(EXIT_SUCCESS);
}

void sigint_handler(int sig) {
    cleanup();
}

void sigterm_handler(int sig) {
    cleanup();
}

int main() {
    int ret;
    char timestamp[32];
    struct tm *timeinfo;
    FILE *log_file;

    // Initialize logging
    openlog("ultrasonic_sensor", LOG_PID | LOG_CONS, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    ret = gpiod_chip_open("/dev/gpiochip0");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(ret, TRIGGER_PIN);
    if (!trigger_line) {
        syslog(LOG_ERR, "Failed to get trigger line: %s", gpiod_strerror(ret));
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(ret, ECHO_PIN);
    if (!echo_line) {
        syslog(LOG_ERR, "Failed to get echo line: %s", gpiod_strerror(ret));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(trigger_line, 0, "active-high");
    gpiod_line_request_input(echo_line, 0);

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Generate trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10 * 1000);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rise
        ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, 30000);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to wait for echo rise: %s", gpiod_strerror(ret));
            continue;
        }

        // Wait for echo pulse width
        ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, 30000);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to wait for echo fall: %s", gpiod_strerror(ret));
            continue;
        }

        // Compute distance
        uint64_t pulse_width = gpiod_line_event_get_timestamp(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE) - gpiod_line_event_get_timestamp(echo_line, GPIOD_LINE_EVENT_RISING_EDGE);
        if (pulse_width == 0) {
            syslog(LOG_INFO, "Echo never rose");
            continue;
        }

        double distance = (pulse_width / 2.0) * 343.0 / 2.0; // 343 m/s speed of sound, 2 = 1kΩ/2kΩ voltage divider
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            syslog(LOG_INFO, "Distance out of range: %f cm", distance);
            continue;
        }

        // Log result
        timeinfo = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        fprintf(log_file, "%s %f cm\n", timestamp, distance);
        if (distance < 15) {
            syslog(LOG_INFO, "Time to water the plant!");
        }

        // Sleep before next measurement
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

