#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5B
#define PROXIMITY_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"
#define CSV_MODE "w"
#define CSV_DELIMITER ","

#define MAX_LINE_LENGTH 256

#define SIGINT_HANDLER SIGINT
#define SIGTERM_HANDLER SIGTERM

// Function to read a byte from the APDS9960 sensor
uint8_t read_byte(uint8_t reg) {
    uint8_t value;
    if (i2c_read(I2C_BUS, I2C_ADDRESS, &reg, 1, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C bus\n");
        return 0;
    }
    return value;
}

// Function to write a byte to the APDS9960 sensor
void write_byte(uint8_t reg, uint8_t value) {
    if (i2c_write(I2C_BUS, I2C_ADDRESS, &reg, 1, &value, 1) != 1) {
        fprintf(stderr, "Error writing to I2C bus\n");
    }
}

// Function to initialize the APDS9960 sensor
void init_apds9960() {
    // Reset the APDS9960 sensor
    write_byte(0x80, 0x00);
    // Enable the proximity sensor
    write_byte(0x80, 0x01);
    // Enable the RGB sensor
    write_byte(0x81, 0x03);
}

// Function to read the proximity and RGB values from the APDS9960 sensor
void read_values(uint8_t *proximity, uint8_t *red, uint8_t *green, uint8_t *blue) {
    // Read the proximity value
    *proximity = read_byte(0xFF);
    // Read the red value
    *red = read_byte(0x92);
    // Read the green value
    *green = read_byte(0x93);
    // Read the blue value
    *blue = read_byte(0x94);
}

// Function to write a line to the CSV file
void write_to_csv(const char *line) {
    FILE *file = fopen(CSV_FILE, CSV_MODE);
    if (file == NULL) {
        fprintf(stderr, "Error opening CSV file for writing\n");
        return;
    }
    if (fputs(line, file) == EOF) {
        fprintf(stderr, "Error writing to CSV file\n");
        fclose(file);
        return;
    }
    fclose(file);
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    // Close the I2C handle
    i2c_close(I2C_BUS);
    // Finalize the CSV file
    write_to_csv("\n");
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the I2C bus
    if (i2c_open(I2C_BUS, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }
    // Initialize the APDS9960 sensor
    init_apds9960();
    // Set up the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    // Open the CSV file for writing
    write_to_csv("timestamp,red,green,blue,proximity\n");
    // Main loop
    while (1) {
        // Read the proximity and RGB values
        uint8_t proximity, red, green, blue;
        read_values(&proximity, &red, &green, &blue);
        // Check if the proximity reading exceeds the threshold
        if (proximity > PROXIMITY_THRESHOLD) {
            // Format the line to write to the CSV file
            char line[MAX_LINE_LENGTH];
            struct timeval tv;
            gettimeofday(&tv, NULL);
            sprintf(line, "%ld,%d,%d,%d,%d\n", tv.tv_sec, red, green, blue, proximity);
            // Write the line to the CSV file
            write_to_csv(line);
        }
        // Sleep for 100ms
        usleep(100000);
    }
    // Close the I2C handle
    i2c_close(I2C_BUS);
    // Finalize the CSV file
    write_to_csv("\n");
    return 0;
}

