#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_SLAVE_ADDRESS 0x29
#define GPIO_TRIGGER_PIN 17
#define GPIO_TRIGGER_EDGE_FALLING
#define GPIO_TRIGGER_DEBOUNCE 100
#define LOG_FILE "distance_log.txt"
#define LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_distance(double timestamp, double distance_mm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%.3f,%.3f\n", timestamp, distance_mm);
    fclose(file);
}

int main() {
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    char buffer[256];
    sprintf(buffer, "17\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "in\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/edge", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "%s\n", GPIO_TRIGGER_EDGE_FALLING);
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/active_low", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/pull", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "up\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];

    msg[0].addr = I2C_SLAVE_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = (uint8_t *) "\x00";

    msg[1].addr = I2C_SLAVE_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 1;
    msg[1].buf = (uint8_t *) "\x00";

    data.msgs = msg;
    data.nmsgs = 2;

    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    while (running) {
        if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
            perror("ioctl");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (msg[0].buf[0] != 0x01) {
            printf("Sensor not present\n");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        gpio_fd = open("/sys/class/gpio/gpio17/value", O_RDONLY);
        if (gpio_fd < 0) {
            perror("open");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        char buffer[2];
        if (read(gpio_fd, buffer, 1) != 1) {
            perror("read");
            close(i2c_fd);
            close(gpio_fd);
            exit(EXIT_FAILURE);
        }

        close(gpio_fd);

        if (buffer[0] == '0') {
            clock_gettime(CLOCK_REALTIME, &start);
            if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
                perror("ioctl");
                close(i2c_fd);
                exit(EXIT_FAILURE);
            }

            struct i2c_rdwr_ioctl_data data2;
            struct i2c_msg msg2[1];

            msg2[0].addr = I2C_SLAVE_ADDRESS;
            msg2[0].flags = 0;
            msg2[0].len = 1;
            msg2[0].buf = (uint8_t *) "\x00";

            data2.msgs = msg2;
            data2.nmsgs = 1;

            if (ioctl(i2c_fd, I2C_RDWR, &data2) < 0) {
                perror("ioctl");
                close(i2c_fd);
                exit(EXIT_FAILURE);
            }

            uint16_t distance = (uint16_t) ((msg2[0].buf[0] << 8) | msg2[0].buf[1]);

            clock_gettime(CLOCK_REALTIME, &end);
            double timestamp = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

            log_distance(timestamp, distance / 100.0);

            usleep(GPIO_TRIGGER_DEBOUNCE * 1000);
        }
    }

    close(i2c_fd);

    gpio_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "17\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    return 0;
}

