            uint16_t distance = (uint16_t) ((msg2[0].buf[0] << 8) | msg2[0].buf[1]);

            clock_gettime(CLOCK_REALTIME, &end);
            double timestamp = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

            log_distance(timestamp, distance / 100.0);

