    gpio_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "17\n");
    if (write(gpio_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);

    return 0;
}
