#define SAMPLING_PERIOD 200
#define TRIGGER_DELAY 50

#define MAX_ERROR_LENGTH 256

static char log_buffer[LOG_BUFFER_SIZE];
static char error_message[MAX_ERROR_LENGTH];

static void sigint_handler(int signal) {
    (void)signal;
    printf("\nCaught SIGINT, exiting...\n");
    gpioTerminate();
    close(log_file);
    exit(EXIT_SUCCESS);
}

static int open_i2c_bus() {
    int fd = gpioOpen(I2C_BUS, I2C_SLAVE_ADDRESS);
    if (fd < 0) {
        sprintf(error_message, "Failed to open I2C bus %d: %s", I2C_BUS, strerror(errno));
        fprintf(stderr, "%s\n", error_message);
        return -1;
    }
    return fd;
}

static int write_i2c_byte(int fd, uint8_t byte) {
    int bytes_written = gpioI2CWriteByte(fd, byte);
    if (bytes_written < 0) {
        sprintf(error_message, "Failed to write byte 0x%02x to I2C bus %d: %s", byte, I2C_BUS, strerror(errno));
        fprintf(stderr, "%s\n", error_message);
        return -1;
    }
    return 0;
}

static int read_i2c_byte(int fd) {
    uint8_t byte;
    int bytes_read = gpioI2CReadByte(fd, &byte);
    if (bytes_read < 0) {
        sprintf(error_message, "Failed to read byte from I2C bus %d: %s", I2C_BUS, strerror(errno));
        fprintf(stderr, "%s\n", error_message);
        return -1;
    }
    return byte;
}

static int open_log_file() {
    log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file < 0) {
        sprintf(error_message, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        fprintf(stderr, "%s\n", error_message);
        return -1;
    }
    return 0;
}

int main() {
    struct tm time;
    struct timeval tv;
    int fd;
    int log_file;
    int i;
    uint8_t trigger_byte = 0x01;
    uint8_t echo_byte;
    char timestamp[20];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        sprintf(error_message, "Failed to initialize GPIO: %s", strerror(errno));
        fprintf(stderr, "%s\n", error_message);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    fd = open_i2c_bus();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    if (open_log_file() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up trigger and echo pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main sampling loop
    while (1) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(TRIGGER_DELAY * 1000);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        // Wait for echo to start
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            usleep(10);
        }

        // Wait for echo to stop
        gettimeofday(&tv, NULL);
        i = 0;
        while (gpioRead(ECHO_PIN) == PI_HIGH) {
            usleep(10);
            i++;
            if (i > 1000000) {
                break;
            }
        }

        // Read echo byte
        if (i > 1000000) {
            continue;
        }
        if (write_i2c_byte(fd, 0x00) < 0) {
            continue;
        }
        echo_byte = read_i2c_byte(fd);
        if (echo_byte < 0) {
            continue;
        }

        // Calculate distance
        uint16_t distance_mm = echo_byte * 10;

        // Format timestamp
        time = *localtime(&tv.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time);

        // Log and print result
        sprintf(log_buffer, "%s, %d\n", timestamp, distance_mm);
        write(log_file, log_buffer, strlen(log_buffer));
        printf("%s, %d\n", timestamp, distance_mm);

        // Wait for next sample
        usleep(SAMPLING_PERIOD * 1000);
    }

    // Clean up
    close(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

