#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define LOG_FILE "obstacle_log.txt"
#define LOG_INTERVAL 100000 // 100ms in microseconds

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorStr(gpioInitError));
        return EXIT_FAILURE;
    }

    // Set up GPIO as inputs
    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0 || gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", gpioErrorStr(gpioInitError));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        close(log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp = tv.tv_sec * 1000000 + tv.tv_usec;

        // Read sensor values
        int sensor1_value = gpioRead(GPIO_SENSOR1);
        int sensor2_value = gpioRead(GPIO_SENSOR2);

        // Log sensor values
        char log_str[32];
        sprintf(log_str, "%llu %d %d\n", timestamp, sensor1_value, sensor2_value);
        if (write(log_fd, log_str, strlen(log_str)) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        }

        // Sleep for 100ms
        usleep(LOG_INTERVAL);
    }

    // Clean up
    close(log_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

