#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define DISTANCE_LOG_FILE "distance_log.txt"
#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define SAMPLING_INTERVAL 100000 // 100 ms
#define DISTANCE_THRESHOLD 20 // cm

// Function to handle signal interrupts
void signal_handler(int signal) {
    // Release resources
    gpioTerminate();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

// Function to log a distance reading
void log_distance(double distance) {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if ((i2c_fd = open("/dev/i2c-%d", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address 0x%02x\n", I2C_ADDRESS);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    log_file = fopen(DISTANCE_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", DISTANCE_LOG_FILE);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pin
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as output\n", GPIO_PIN);
        close(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance from sensor
        uint8_t data[2];
        if (i2c_smbus_read_byte_data(i2c_fd, 0x00, data) < 0) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            close(i2c_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
        double distance = (double)data[0] * 256 + data[1];
        if (distance > 65535) {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
            close(i2c_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Log distance reading
        log_distance(distance);

        // Drive LED
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Release resources
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

