#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x10
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main(int argc, char **argv) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up LED pin as output
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t who_am_i;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_smbus_read_byte_data(i2c_fd, 0x0F) != 0x00) {
        fprintf(stderr, "Sensor not detected\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance measurement
        uint16_t distance;
        if (i2c_smbus_read_word_data(i2c_fd, 0x00) < 0) {
            fprintf(stderr, "Failed to read distance measurement\n");
            break;
        }
        distance = i2c_smbus_read_word_data(i2c_fd, 0x00);

        // Check if distance is below threshold
        if (distance < threshold) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s: %d mm\n", timestamp, distance);

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

