#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x50
#define COMMAND_FRAME 0x00, 0x00, 0x00, 0x00
#define RESPONSE_HEADER 0x55
#define RESPONSE_LENGTH 15
#define DISTANCE_OFFSET 11
#define DISTANCE_LENGTH 2
#define DELAY 100000 // 100 ms
#define SAMPLES 10
#define LOG_FILE "intrusion_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Send command frame
        if (write(i2c_fd, COMMAND_FRAME, 4) != 4) {
            perror("Failed to send command frame");
            break;
        }

        // Wait for response
        usleep(10000); // 10 ms

        // Read response
        uint8_t response[RESPONSE_LENGTH];
        if (read(i2c_fd, response, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
            perror("Failed to read response");
            break;
        }

        // Check response header
        if (response[0] != RESPONSE_HEADER) {
            fprintf(stderr, "Invalid response header\n");
            break;
        }

        // Extract distance
        uint16_t distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];

        // Sample sensor
        uint16_t total_distance = 0;
        for (int i = 0; i < SAMPLES; i++) {
            // Send command frame
            if (write(i2c_fd, COMMAND_FRAME, 4) != 4) {
                perror("Failed to send command frame");
                break;
            }

            // Wait for response
            usleep(10000); // 10 ms

            // Read response
            uint8_t response[RESPONSE_LENGTH];
            if (read(i2c_fd, response, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
                perror("Failed to read response");
                break;
            }

            // Check response header
            if (response[0] != RESPONSE_HEADER) {
                fprintf(stderr, "Invalid response header\n");
                break;
            }

            // Extract distance
            uint16_t distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
            total_distance += distance;
        }

        // Compute average distance
        uint16_t average_distance = total_distance / SAMPLES;

        // Check for intrusion
        if (average_distance < 1000) {
            // Log intrusion
            fprintf(log_file, "%lu %d\n", time(NULL), average_distance);
        }

        // Delay
        usleep(DELAY);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    if (fclose(log_file) != 0) {
        perror("Failed to close log file");
    }

    return 0;
}

