        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    struct timeval last_measurement;
    gettimeofday(&last_measurement, NULL);
    while (running) {
        // Poll RESULT_INTERRUPT_STATUS
        ret = gpiod_i2c_read(chip, I2C_ADDRESS, 0x0F, NULL, 0);
        if (ret) {
