        sleep_time.tv_nsec = (MEASUREMENT_INTERVAL_US % 1000000) * 1000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(sda);
    gpiod_line_release(scl);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
