#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A // Silicon Labs Si1182 default I2C address
#define PROXIMITY_REGISTER 0x00 // Si1182 proximity data register
#define PROXIMITY_REGISTER_SIZE 2 // 16-bit proximity data
#define POLL_INTERVAL 500000 // 500 ms

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpioSetMode(I2C_SDA, PI_INPUT) < 0 || gpioSetMode(I2C_SCL, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set I2C pin modes\n");
        gpioClose(i2c_fd);
        return 1;
    }

    if (gpioSetPullUpDnControl(I2C_SDA, PI_PUD_UP) < 0 || gpioSetPullUpDnControl(I2C_SCL, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set I2C pull-up/down resistors\n");
        gpioClose(i2c_fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioClose(i2c_fd);
        return 1;
    }

    while (running) {
        uint8_t data[PROXIMITY_REGISTER_SIZE];
        if (i2cWriteReg8(i2c_fd, I2C_ADDRESS, PROXIMITY_REGISTER, 0x00) < 0) {
            fprintf(stderr, "Failed to write to Si1182\n");
            break;
        }

        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = 100000; // 100 ms timeout
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(i2c_fd, &fds);
        if (select(i2c_fd + 1, &fds, NULL, NULL, &timeout) < 0) {
            fprintf(stderr, "Failed to select on I2C file descriptor\n");
            break;
        }

        if (FD_ISSET(i2c_fd, &fds)) {
            if (i2cReadReg8(i2c_fd, I2C_ADDRESS, PROXIMITY_REGISTER, data, PROXIMITY_REGISTER_SIZE) < 0) {
                fprintf(stderr, "Failed to read from Si1182\n");
                break;
            }

            if (data[0] == 0xFF) {
                fprintf(stderr, "Sensor absent\n");
                break;
            }

            uint16_t proximity = (data[0] << 8) | data[1];
            printf("Proximity: %d\n", proximity);
        }

        usleep(POLL_INTERVAL);
    }

    gpioClose(i2c_fd);
    return 0;
}

