#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and device addresses
#define I2C_BUS 1
#define I2C_DEVICE 0x5A // Melexis MLX75030 I2C address

// Define the signal handler function
void sigint_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int i2c_fd = -1;
    int ret;

    // Install the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the I2C bus device file
    i2c_fd = open("/dev/i2c-" + I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(1);
    }

    // Set the I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        exit(1);
    }

    // Verify that the device responds
    uint8_t response = 0;
    ret = i2c_smbus_read_byte(i2c_fd, &response);
    if (ret == -1) {
        fprintf(stderr, "Error: unable to read from device\n");
        close(i2c_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the distance measurement
        uint16_t distance;
        ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
        if (ret == -1) {
            fprintf(stderr, "Error: unable to read from device\n");
            continue;
        }
        distance = ret;

        // Print the distance
        printf("Distance: %d mm\n", distance);

        // Sleep for 500ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000;
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

