#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CHANNEL 0
#define PERIOD 500  // in milliseconds

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint8_t error_flags;
} opt3101_data_t;

// Function to read data from the OPT3101 sensor
int read_opt3101(int i2c_fd, opt3101_data_t *data) {
    uint8_t reg = 0x00; // Register to read from
    uint8_t buf[2];

    // Read distance measurement from channel 0
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x00) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, 0x00, buf) < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    data->distance = (buf[0] << 8) | buf[1];

    // Read ambient light value
    if (i2c_smbus_write_byte_data(i2c_fd, 0x01, 0x00) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, 0x01, buf) < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    data->ambient_light = buf[0];

    // Read error flags
    if (i2c_smbus_write_byte_data(i2c_fd, 0x02, 0x00) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, 0x02, buf) < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    data->error_flags = buf[0];

    return 0;
}

// Function to handle SIGINT (Ctrl-C)
void sigint_handler(int sig) {
    printf("\nCaught SIGINT, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd;
    opt3101_data_t data;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read data from the OPT3101 sensor
        if (read_opt3101(i2c_fd, &data) < 0) {
            perror("Failed to read from OPT3101 sensor");
            break;
        }

        // Log data to console
        printf("Distance: %d mm, Ambient Light: %d, Error Flags: 0x%02x\n", data.distance, data.ambient_light, data.error_flags);

        // Sleep for 500ms
        usleep(PERIOD * 1000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

