#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define MAX_DISTANCE 38.0  // Maximum distance in cm
#define MAX_TIMEOUT 200000  // Maximum timeout in microseconds
#define MEASUREMENT_INTERVAL 1000000  // Measurement interval in microseconds (1 second)

// Function to handle signal interrupts
void signal_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    exit(0);
}

int main() {
    // Initialize GPIO chip
    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Set up trigger pin as output
    struct gpiod_line *trigger_line;
    if ((trigger_line = gpiod_line_request_output(chip, TRIGGER_GPIO, "active-high")) == NULL) {
        gpiod_chip_close(chip);
        perror("Failed to request trigger line");
        return 1;
    }

    // Set up echo pin as input with pull-up resistor
    struct gpiod_line *echo_line;
    if ((echo_line = gpiod_line_request_input(chip, ECHO_GPIO, GPIOD_LINE_ACTIVE_STATE_HIGH)) == NULL) {
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        perror("Failed to request echo line");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        perror("Failed to set up signal handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        perror("Failed to set up signal handler");
        return 1;
    }

    // Main loop
    while (1) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);  // 10 us pulse
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rising edge
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, MAX_TIMEOUT) == -1) {
            gpiod_line_release(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_chip_close(chip);
            perror("Failed to wait for echo rising edge");
            return 1;
        }

        // Wait for echo falling edge
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, MAX_TIMEOUT) == -1) {
            gpiod_line_release(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_chip_close(chip);
            perror("Failed to wait for echo falling edge");
            return 1;
        }

        // Calculate pulse duration
        uint64_t pulse_duration = gpiod_line_event_get_timestamp(echo_line) - gpiod_line_event_get_timestamp(event);

        // Check for invalid pulse duration
        if (pulse_duration <= 0 || pulse_duration > MAX_TIMEOUT) {
            gpiod_line_release(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_chip_close(chip);
            fprintf(stderr, "Invalid pulse duration\n");
            return 1;
        }

        // Calculate distance
        double distance = (pulse_duration * 0.5 * 34300) / 1000000;  // Speed of sound in cm/us

        // Log measurement
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(stderr, "%ld.%06ld: Distance: %.2f cm\n", tv.tv_sec, tv.tv_usec, distance);

        // Wait for next measurement
        usleep(MEASUREMENT_INTERVAL);
    }

    // Clean up
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    return 0;
}

