#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/signal.h>
#include <syslog.h>
#include <errno.h>
#include <getopt.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE B115200
#define UART_TIMEOUT 1000
#define GPIO_ALERT_PIN 17
#define INTRUSION_LOG_FILE "intrusion_log.csv"
#define DISTANCE_THRESHOLD 1.0

// Function to handle signal interrupts
void signal_handler(int sig) {
    // Release GPIO resources
    gpiod_close(gpio_fd);
    // Close UART device
    close(uart_fd);
    // Exit with status code 0
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize logging
    openlog(NULL, LOG_PID, LOG_USER);

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up signal handler for SIGINT");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up signal handler for SIGTERM");
        exit(1);
    }

    // Open UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        syslog(LOG_ERR, "Failed to open UART device: %s", strerror(errno));
        exit(1);
    }

    // Set up UART baudrate and timeout
    if (cfsetispeed(uart_fd, UART_BAUDRATE) == -1) {
        syslog(LOG_ERR, "Failed to set UART baudrate: %s", strerror(errno));
        close(uart_fd);
        exit(1);
    }
    if (cfsetospeed(uart_fd, UART_BAUDRATE) == -1) {
        syslog(LOG_ERR, "Failed to set UART baudrate: %s", strerror(errno));
        close(uart_fd);
        exit(1);
    }
    if (cfsetspeed(uart_fd, UART_TIMEOUT) == -1) {
        syslog(LOG_ERR, "Failed to set UART timeout: %s", strerror(errno));
        close(uart_fd);
        exit(1);
    }

    // Open GPIO device
    gpio_fd = gpiod_open("/sys/class/gpio/gpio17");
    if (gpio_fd == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO device");
        close(uart_fd);
        exit(1);
    }

    // Export GPIO pin
    if (gpiod_export(gpio_fd, GPIO_ALERT_PIN) == -1) {
        syslog(LOG_ERR, "Failed to export GPIO pin");
        gpiod_close(gpio_fd);
        close(uart_fd);
        exit(1);
    }

    // Set GPIO direction to output
    if (gpiod_direction(gpio_fd, GPIO_ALERT_PIN, GPIOD_OUT) == -1) {
        syslog(LOG_ERR, "Failed to set GPIO direction");
        gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
        gpiod_close(gpio_fd);
        close(uart_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read UART data
        char buffer[256];
        ssize_t bytes_read = read(uart_fd, buffer, 256);
        if (bytes_read == -1) {
            syslog(LOG_ERR, "Failed to read UART data: %s", strerror(errno));
            gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
            gpiod_close(gpio_fd);
            close(uart_fd);
            exit(1);
        }

        // Check for magic word header
        if (bytes_read < 8) {
            continue;
        }
        uint32_t magic_word = *(uint32_t *)buffer;
        if (magic_word != 0x12345678) {
            continue;
        }

        // Extract range profile data
        uint16_t *profile = (uint16_t *)(buffer + 8);
        for (int i = 0; i < 64; i++) {
            if (profile[i] < (DISTANCE_THRESHOLD * 65536)) {
                // Log intrusion
                char timestamp[32];
                strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
                FILE *log_file = fopen(INTRUSION_LOG_FILE, "a");
                if (log_file == NULL) {
                    syslog(LOG_ERR, "Failed to open intrusion log file");
                    gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
                    gpiod_close(gpio_fd);
                    close(uart_fd);
                    exit(1);
                }
                fprintf(log_file, "%s,%f\n", timestamp, (double)profile[i] / 65536.0);
                fclose(log_file);

                // Activate alert LED
                if (gpiod_write(gpio_fd, GPIO_ALERT_PIN, 1) == -1) {
                    syslog(LOG_ERR, "Failed to activate alert LED");
                    gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
                    gpiod_close(gpio_fd);
                    close(uart_fd);
                    exit(1);
                }
                usleep(2000000);
                if (gpiod_write(gpio_fd, GPIO_ALERT_PIN, 0) == -1) {
                    syslog(LOG_ERR, "Failed to deactivate alert LED");
                    gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
                    gpiod_close(gpio_fd);
                    close(uart_fd);
                    exit(1);
                }
            }
        }
    }

    // Release resources
    gpiod_unexport(gpio_fd, GPIO_ALERT_PIN);
    gpiod_close(gpio_fd);
    close(uart_fd);
    closelog();
    return 0;
}

