#define READ_INTERVAL 100000 // 100ms

// Function to handle signal
void signal_handler(int signal) {
    // Release I2C handle
    if (i2c_close(I2C_BUS) != 0) {
        perror("i2c_close");
    }

    // Release GPIO pin
    gpioRelease(GPIO_ALERT_PIN);

    // Close log file
