    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up GPIO alert pin as output
    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Create log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance measurement
        uint16_t distance;
        if (i2cWriteReg8(I2C_BUS, 0x00, 0x00) != 0) {
            fprintf(stderr, "Failed to write to I2C register\n");
            break;
        }
        if (i2cReadReg16(I2C_BUS, 0x00, &distance) != 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            break;
        }

        // Check for sensor absence
        if (distance == 0xFFFF) {
            fprintf(stderr, "Sensor not detected\n");
            break;
        }

        // Log distance measurement
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(log_file, "%s %.2f cm\n", timestamp, (double)distance / 10.0);

        // Check for alert condition
        if (distance < 10.0) {
            gpioWrite(GPIO_ALERT_PIN, 1);
        } else {
            gpioWrite(GPIO_ALERT_PIN, 0);
        }

        // Sleep for read interval
        usleep(READ_INTERVAL);
    }

    // Release resources
    fclose(log_file);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

