#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define LOG_FILE "distance_log.csv"
#define MEASUREMENT_INTERVAL 100 // ms

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Release I2C handle
    gpio_i2c_close(I2C_BUS);

    // Close log file
    fclose(log_file);

    // De-initialize sensor driver
    vl53l1x_deinit();

    // Exit the program
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    // Initialize I2C bus
    int i2c_fd = gpio_i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Initialize VL53L1X sensor driver
    if (vl53l1x_init(i2c_fd, I2C_ADDRESS) != 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor driver\n");
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        exit(1);
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        if (errno == ENOENT) {
            // Create the file with a header row
            log_file = fopen(LOG_FILE, "w");
            fprintf(log_file, "timestamp,distance_mm\n");
            if (ferror(log_file)) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                vl53l1x_deinit();
                gpio_i2c_close(I2C_BUS);
                gpioTerminate();
                exit(1);
            }
        } else {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            vl53l1x_deinit();
            gpio_i2c_close(I2C_BUS);
            gpioTerminate();
            exit(1);
        }
    }

    // Main loop
    while (1) {
        // Poll the sensor
        uint16_t distance_mm = vl53l1x_get_distance_mm();
        if (distance_mm == 0) {
            fprintf(stderr, "Failed to get distance from VL53L1X sensor\n");
            break;
        }

        // Print parking guidance message
        if (distance_mm < 300) {
            printf("STOP\n");
        } else if (distance_mm < 600) {
            printf("APPROACH\n");
        } else if (distance_mm < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Append measurement to log file
        fprintf(log_file, "%lu,%d\n", (unsigned long)time(NULL), distance_mm);
        if (ferror(log_file)) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }

        // Sleep for MEASUREMENT_INTERVAL ms
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Close log file
    fclose(log_file);

    // De-initialize sensor driver
    vl53l1x_deinit();

    // Release I2C handle
    gpio_i2c_close(I2C_BUS);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

