#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define LED_GPIO 18
#define LED_RESISTOR 330
#define BLINK_FREQ_MAX 10
#define BLINK_FREQ_MIN 0.1
#define SAMPLE_RATE 100000 // 100 ms
#define MAX_RETRIES 3
#define DELAY 10000 // 10 ms

// Function to blink the LED
void blink_led(bool on) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (on) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

// Function to read distance from the TDK InvenSense CH201 ultrasonic Time-of-Flight sensor
uint16_t read_distance() {
    int fd;
    char filename[20];
    uint16_t distance;

    // Open the I2C device
    sprintf(filename, "/dev/i2c-%d", I2C_BUS);
    if ((fd = open(filename, O_RDWR)) < 0) {
        perror("open");
        return 0;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 0;
    }

    // Read the distance
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_smbus_read_byte_data(fd, 0x00) == 0x00) {
            // Read the distance
            uint8_t data[2];
            if (i2c_smbus_read_i2c_block_data(fd, 0x01, 2, data) == 2) {
                distance = (data[0] << 8) | data[1];
                break;
            }
        }
        usleep(DELAY);
    }

    close(fd);
    return distance;
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    struct timeval last_time;
    gettimeofday(&last_time, NULL);
    while (1) {
        uint16_t distance = read_distance();
        if (distance == 0) {
            // Sensor absent or bus error
            printf("Sensor absent or bus error\n");
