// Function to read distance from the TDK InvenSense CH201 ultrasonic Time-of-Flight sensor
uint16_t read_distance() {
    int fd;
    char filename[20];
    uint16_t distance;

    // Open the I2C device
    sprintf(filename, "/dev/i2c-%d", I2C_BUS);
    if ((fd = open(filename, O_RDWR)) < 0) {
        perror("open");
        return 0;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 0;
    }

    // Read the distance
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_smbus_read_byte_data(fd, 0x00) == 0x00) {
            // Read the distance
            uint8_t data[2];
            if (i2c_smbus_read_i2c_block_data(fd, 0x01, 2, data) == 2) {
                distance = (data[0] << 8) | data[1];
                break;
            }
        }
        usleep(DELAY);
    }

    close(fd);
    return distance;
}

