int i2c_read(int fd, uint8_t *buf, int size) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            if (errno == EBUSY) {
                retries++;
                usleep(100000);
            } else {
                fprintf(stderr, "I2C bus error: %s\n", strerror(errno));
                return -1;
            }
        }
        if (i2c_smbus_read_byte_data(fd, MELEXIS_COMMAND) < 0) {
            if (errno == ETIMEDOUT) {
                retries++;
                usleep(100000);
            } else {
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
                return -1;
            }
        }
        if (i2c_smbus_read_i2c_block_data(fd, MELEXIS_DELAY_US, MELEXIS_READ_SIZE, buf) < 0) {
            if (errno == ETIMEDOUT) {
                retries++;
                usleep(100000);
            } else {
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
                return -1;
            }
        }
        return 0;
    }
    fprintf(stderr, "Maximum retries exceeded\n");
    return -1;
}

int main() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *file = fopen(DISTANCE_LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    char timestamp[32];
    time_t now;
    struct tm *lt;
    while (running) {
        time(&now);
        lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);
        uint8_t buf[MELEXIS_READ_SIZE];
        if (i2c_read(fd, buf, MELEXIS_READ_SIZE) < 0) {
            continue;
        }
        uint16_t distance = (buf[0] << 8) | buf[1];
        fprintf(file, "%s,%d\n", timestamp, distance);
        fflush(file);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(file);
    close(fd);
    return 0;
}

