#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 27
#define DEBOUNCE_TIME 50
#define POLLING_TIME 10
#define LOG_FILE "proximity_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_event(int sensor_id, const char *event_type) {
    char timestamp[32];
    time_t now;
    struct tm *lt;
    char log_line[128];

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", lt);

    sprintf(log_line, "%s %d %s\n", timestamp, sensor_id, event_type);
    if (fputs(log_line, fopen(LOG_FILE, "a")) == EOF) {
        perror("fputs");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int gpio_fd;
    int sensor1_state = 0;
    int sensor2_state = 0;
    int sensor1_prev_state = 0;
    int sensor2_prev_state = 0;
    struct sigaction sa;

    if (sigemptyset(&sa.sa_mask) == -1) {
        perror("sigemptyset");
        exit(EXIT_FAILURE);
    }
    sa.sa_flags = SA_RESTART;
    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR1);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR2);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (running) {
        int sensor1_curr_state = gpioRead(GPIO_SENSOR1);
        int sensor2_curr_state = gpioRead(GPIO_SENSOR2);

        if (sensor1_curr_state != sensor1_prev_state) {
            if (sensor1_curr_state == 1 && sensor1_prev_state == 0) {
                log_event(1, "DETECTED");
            } else if (sensor1_curr_state == 0 && sensor1_prev_state == 1) {
                log_event(1, "CLEARED");
            }
            sensor1_state = sensor1_curr_state;
        }
        if (sensor2_curr_state != sensor2_prev_state) {
            if (sensor2_curr_state == 1 && sensor2_prev_state == 0) {
                log_event(2, "DETECTED");
            } else if (sensor2_curr_state == 0 && sensor2_prev_state == 1) {
                log_event(2, "CLEARED");
            }
            sensor2_state = sensor2_curr_state;
        }

        if (sensor1_state == 1) {
            usleep(DEBOUNCE_TIME * 1000);
            if (gpioRead(GPIO_SENSOR1) == 0) {
                sensor1_state = 0;
                log_event(1, "CLEARED");
            }
        }
        if (sensor2_state == 1) {
            usleep(DEBOUNCE_TIME * 1000);
            if (gpioRead(GPIO_SENSOR2) == 0) {
                sensor2_state = 0;
                log_event(2, "CLEARED");
            }
        }

        sensor1_prev_state = sensor1_curr_state;
        sensor2_prev_state = sensor2_curr_state;

        usleep(POLLING_TIME * 1000);
    }

    if (fclose(fopen(LOG_FILE, "a")) == EOF) {
        perror("fclose");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioTerminate();
    return 0;
}

