#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_FILE "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x32
#define MEAS_STATUS_REGISTER 0x00
#define MEAS_DATA_REGISTER 0x01
#define MEAS_STATUS_SUCCESS 0x01
#define MEAS_STATUS_TIMEOUT 0x00
#define MEAS_DATA_MASK 0x3FFF
#define CSV_FILE "distance_log.csv"

#define MAX_LINE_LENGTH 1024

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(0);
}

static void sigterm_handler(int sig) {
    sigint_handler(sig);
}

static int i2c_write_then_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timeval timeout;

    msg[0].addr = I2C_SLAVE_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_SLAVE_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = data;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    timeout.tv_sec = 0;
    timeout.tv_usec = 50000;

    if (ioctl(fd, I2C_RDWR, &i2c_data) == -1) {
        perror("ioctl");
        return -1;
    }

    if (select(fd + 1, NULL, NULL, NULL, &timeout) == -1) {
        perror("select");
        return -1;
    }

    return 0;
}

int main() {
    struct tm *timestamp;
    char line[MAX_LINE_LENGTH];
    char timestamp_str[32];
    uint16_t distance;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (i2c_write_then_read(i2c_fd, MEAS_STATUS_REGISTER, &distance, 2) == -1) {
            fprintf(stderr, "I2C error: %d\n", errno);
            continue;
        }

        if (distance == MEAS_STATUS_SUCCESS) {
