static void sigterm_handler(int sig) {
    sigint_handler(sig);
}

static int i2c_write_then_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct timeval timeout;

    msg[0].addr = I2C_SLAVE_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_SLAVE_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = data;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    timeout.tv_sec = 0;
    timeout.tv_usec = 50000;

    if (ioctl(fd, I2C_RDWR, &i2c_data) == -1) {
        perror("ioctl");
        return -1;
    }

    if (select(fd + 1, NULL, NULL, NULL, &timeout) == -1) {
