#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define MLX75030_REG_DISTANCE 0x00
#define MLX75030_REG_STATUS 0x01
#define MLX75030_REG_CONFIG 0x02
#define MLX75030_CONFIG_MODE 0x01

#define MAX_RETRIES 3
#define RETRY_DELAY 10

void sigint_handler(int sig) {
    gpiod_close();
    exit(0);
}

int main() {
    int i2c_fd = -1;
    int retries = 0;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *req;
    uint16_t distance;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) == -1) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Initialize I2C handle
    if ((chip = gpiod_chip_open("/dev/i2c-" I2C_BUS)) == NULL) {
        perror("Failed to open I2C chip");
        close(i2c_fd);
        exit(1);
    }

    // Request I2C line
    if ((line = gpiod_chip_get_line(chip, "SCL")) == NULL) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Request I2C line
    if ((req = gpiod_line_request_output(line, GPIOD_LINE_ACTIVE_HIGH)) == NULL) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Configure I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        gpiod_line_release(req);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Initialize sensor
    uint8_t config = MLX75030_CONFIG_MODE;
    if (i2c_smbus_write_byte_data(i2c_fd, MLX75030_REG_CONFIG, config) == -1) {
        if (retries < MAX_RETRIES) {
            retries++;
            sleep(RETRY_DELAY / 1000);
            continue;
        } else {
            gpiod_line_release(req);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            exit(1);
        }
    }

    while (1) {
        // Read distance measurement
        if (i2c_smbus_read_word_data(i2c_fd, MLX75030_REG_DISTANCE) == -1) {
            if (retries < MAX_RETRIES) {
                retries++;
                sleep(RETRY_DELAY / 1000);
                continue;
            } else {
                gpiod_line_release(req);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                close(i2c_fd);
                exit(1);
            }
        }

        // Get current timestamp
        uint64_t timestamp = getnanos() / 1000000;

        // Print measurement
        printf("%llu %d\n", timestamp, distance);

        // Wait for next measurement
        sleep(0.1);
    }

    // Close I2C handle
    gpiod_line_release(req);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

