#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define INTERRUPT_STATUS_REG 0x80
#define DISTANCE_REG 0x00

volatile bool running = true;

void sigint_handler(int sig) {
    gpiod_close(I2C_BUS);
    gpiod_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_close(I2C_BUS);
    gpiod_cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod library\n");
        exit(1);
    }

    int i2c_fd = gpiod_open(I2C_BUS, I2C_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_cleanup();
        exit(1);
    }

    if (gpiod_i2c_set_slave_address(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        gpiod_close(i2c_fd);
        gpiod_cleanup();
        exit(1);
    }

    while (running) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp = (uint64_t)tv.tv_sec * 1000000 + tv.tv_usec;

        if (gpiod_i2c_write_byte(i2c_fd, INTERRUPT_STATUS_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt status register\n");
            gpiod_close(i2c_fd);
            gpiod_cleanup();
            exit(1);
        }

        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(i2c_fd, &read_fds);
        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = 500000;
        if (select(i2c_fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                fprintf(stderr, "Failed to poll I2C bus\n");
                gpiod_close(i2c_fd);
                gpiod_cleanup();
                exit(1);
            }
        }

        if (FD_ISSET(i2c_fd, &read_fds)) {
            uint8_t interrupt_status;
            if (gpiod_i2c_read_byte(i2c_fd, INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
                fprintf(stderr, "Failed to read interrupt status register\n");
                gpiod_close(i2c_fd);
                gpiod_cleanup();
                exit(1);
            }

            if (interrupt_status & 0x01) {
                uint16_t distance;
                if (gpiod_i2c_read_word(i2c_fd, DISTANCE_REG, &distance) < 0) {
                    fprintf(stderr, "Failed to read distance register\n");
                    gpiod_close(i2c_fd);
                    gpiod_cleanup();
                    exit(1);
                }
                printf("%llu, %d mm\n", timestamp, distance);
            }
        }
    }

    gpiod_close(i2c_fd);
    gpiod_cleanup();
    return 0;
}

