#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_Buzzer 22
#define DISTANCE_THRESHOLD 100
#define MEASUREMENT_INTERVAL 500000 // 500ms in microseconds

// Function to handle SIGINT signal for clean shutdown
void sigint_handler(int sig) {
    printf("Caught SIGINT, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up GPIO buzzer pin as output
    if (gpioSetMode(GPIO_Buzzer, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int fd = gpioOpen(I2C_BUS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Configure VL53L1X for continuous ranging mode
    uint8_t config = 0x01; // Continuous high rate mode
    if (i2cWriteReg8(fd, 0x00, config) < 0) {
        fprintf(stderr, "Failed to configure VL53L1X\n");
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance measurement
        uint16_t distance;
        if (i2cReadReg16(fd, 0x00, &distance) < 0) {
            fprintf(stderr, "Failed to read distance measurement\n");
            continue;
        }

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            // Activate buzzer
            gpioWrite(GPIO_Buzzer, 1);
        } else {
            // Deactivate buzzer
            gpioWrite(GPIO_Buzzer, 0);
        }

        // Wait for next measurement interval
        usleep(MEASUREMENT_INTERVAL);
    }

    // Clean up on exit
    gpioClose(fd);
    gpioTerminate();
    return 0;
}

