#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SERVO 17
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90
#define LOOP_INTERVAL 200
#define TIMEOUT 50

void sigint_handler(int sig) {
    gpio_set_servo_pulsewidth(GPIO_SERVO, 0);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_set_servo_pulsewidth(GPIO_SERVO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    int fd;
    struct stat sb;
    struct sigaction sa;
    struct itimerval timer;
    struct timeval tv;
    int servo_angle;
    int distance;
    char filename[] = "sensor_data.log";
    char buffer[256];

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set up the servo pin as a PWM output
    if (gpioServo(GPIO_SERVO, SERVO_MIN) < 0) {
        fprintf(stderr, "Failed to set servo minimum pulse width\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    if ((fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up the timer
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = LOOP_INTERVAL;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = LOOP_INTERVAL;
    setitimer(ITIMER_REAL, &timer, NULL);

    while (1) {
        // Generate a 10µs trigger pulse
        if (gpioTrigger(GPIO_TRIGGER, 10, 1) < 0) {
            fprintf(stderr, "Failed to generate trigger pulse\n");
            break;
        }

        // Wait for the echo
        gettimeofday(&tv, NULL);
        while (gpioRead(GPIO_ECHO) == 1) {
            if (gettimeofday(&tv, NULL) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                break;
            }
            if ((tv.tv_sec * 1000000 + tv.tv_usec) - (tv.tv_sec * 1000000 + tv.tv_usec) > TIMEOUT * 1000) {
                // Sensor timeout
                distance = -1;
                break;
            }
        }

        if (gpioRead(GPIO_ECHO) == 0) {
            // Calculate the distance
            struct timeval start, end;
            gettimeofday(&start, NULL);
            while (gpioRead(GPIO_ECHO) == 0) {
                if (gettimeofday(&end, NULL) < 0) {
                    fprintf(stderr, "Failed to get current time\n");
                    break;
                }
            }
            if (gettimeofday(&end, NULL) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                break;
            }
            distance = (end.tv_sec * 1000000 + end.tv_usec - start.tv_sec * 1000000 - start.tv_usec) / 58;
            if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
                // Invalid distance
                distance = -1;
            }
        }

        // Map the distance to a servo angle
        if (distance >= 0) {
            servo_angle = (int)((double)(distance - DISTANCE_MIN) / (double)(DISTANCE_MAX - DISTANCE_MIN) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);
            if (gpioServo(GPIO_SERVO, servo_angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            } else {
                // Log the distance
                sprintf(buffer, "%d %d\n", (int)tv.tv_sec, distance);
                if (write(fd, buffer, strlen(buffer)) < 0) {
                    fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                }
            }
        }

        // Sleep until the next loop
        usleep(LOOP_INTERVAL * 1000);
    }

    // Release all resources
    gpioTerminate();
    close(fd);
    unlink(filename);
    return 0;
}

