#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define TRIGGER_HZ 10
#define BUZZER_HZ 1000
#define BUZZER_DUTY_CYCLE 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MEASUREMENT_INTERVAL 100000  // 100 ms

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void trigger_pulse(gpiod_line_t *trigger_line) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10 * 1000);  // 10 us
    gpiod_line_set_value(trigger_line, 0);
}

void measure_distance(gpiod_line_t *trigger_line, gpiod_line_t *echo_line, int *distance) {
    gpiod_line_direction_t direction;
    gpiod_line_get_direction(echo_line, &direction);
    if (direction != GPIOD_LINE_DIRECTION_INPUT) {
        fprintf(stderr, "Error: Echo line is not configured as input\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_BOTH, NULL, NULL, NULL);
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);

    struct gpiod_line_event event;
    while (gpiod_line_event_next(echo_line, &event) == 0) {
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_BOTH, NULL, NULL, NULL);
            gpiod_line_set_value(trigger_line, 1);
            gpiod_line_set_value(trigger_line, 0);
            break;
        }
    }

    if (gpiod_line_event_next(echo_line, &event) != 0) {
        fprintf(stderr, "Error: No echo event received\n");
        *distance = -1;
        return;
    }

    uint64_t start_time = event.timestamp;
    while (gpiod_line_event_next(echo_line, &event) == 0) {
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            uint64_t end_time = event.timestamp;
            *distance = (end_time - start_time) * 340 / 2 / 1000000;
            if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
                *distance = -1;
            }
            break;
        }
    }

    gpiod_line_event_unsubscribe(echo_line);
}

int main() {
    gpiod_context_t *ctx;
    gpiod_line_t *trigger_line;
    gpiod_line_t *echo_line;
    gpiod_line_t *buzzer_line;

    if (gpiod_ctx_new(&ctx) != 0) {
        fprintf(stderr, "Error: Failed to create GPIO context\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_by_name(ctx, TRIGGER_PIN, "input", GPIOD_LINE_REQUEST_OUTPUT, NULL) != 0) {
        fprintf(stderr, "Error: Failed to request trigger line\n");
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }
    trigger_line = gpiod_line_request_by_name(ctx, TRIGGER_PIN, "input", GPIOD_LINE_REQUEST_OUTPUT, NULL);
    if (trigger_line == NULL) {
        fprintf(stderr, "Error: Failed to request trigger line\n");
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_by_name(ctx, ECHO_PIN, "input", GPIOD_LINE_REQUEST_INPUT, NULL) != 0) {
        fprintf(stderr, "Error: Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }
    echo_line = gpiod_line_request_by_name(ctx, ECHO_PIN, "input", GPIOD_LINE_REQUEST_INPUT, NULL);
    if (echo_line == NULL) {
        fprintf(stderr, "Error: Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_by_name(ctx, BUZZER_PIN, "output", GPIOD_LINE_REQUEST_OUTPUT, NULL) != 0) {
        fprintf(stderr, "Error: Failed to request buzzer line\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }
    buzzer_line = gpiod_line_request_by_name(ctx, BUZZER_PIN, "output", GPIOD_LINE_REQUEST_OUTPUT, NULL);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Error: Failed to request buzzer line\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        int distance;
        measure_distance(trigger_line, echo_line, &distance);
        if (distance == -1) {
            printf("Sensor absent or invalid reading\n");
        } else {
            printf("Distance: %d cm\n", distance);
            if (distance < 30) {
                gpiod_line_set_value(buzzer_line, 1);
                usleep(1000000 / BUZZER_HZ);
                gpiod_line_set_value(buzzer_line, 0);
                usleep(1000000 / BUZZER_HZ);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }
        usleep(MEASUREMENT_INTERVAL);
    }

    gpiod_line_release(buzzer_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_ctx_free(ctx);
    return EXIT_SUCCESS;
}

