#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_INTERVAL_US 20000000
#define TRIGGER_PULSE_US 10000
#define MIN_PULSE_US 100000
#define MAX_PULSE_US 30000
#define TIMEOUT_US 6000000
#define LOG_FILE "distance_log.txt"

struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;
struct gpiod_line_event *event = NULL;
struct gpiod_line_event *event2 = NULL;
uint32_t rising_tick = 0;
uint32_t falling_tick = 0;
bool trigging = false;
bool echo_detected = false;
bool timeout = false;

void sigint_handler(int sig) {
    gpiod_line_set_value(trig_line, 0);
    gpiod_line_unexport(trig_line);
    gpiod_line_unexport(echo_line);
    gpiod_close(trig_line);
    gpiod_close(echo_line);
    fclose(log_file);
    exit(0);
}

void alert_handler(struct gpiod_line_event *event, void *user_data) {
    if (event->line == echo_line) {
        echo_detected = true;
        if (event->edge == GPIOD_LINE_EVENT_RISING_EDGE) {
            rising_tick = event->timestamp;
        } else if (event->edge == GPIOD_LINE_EVENT_FALLING_EDGE) {
            falling_tick = event->timestamp;
            if (falling_tick > rising_tick) {
                falling_tick -= (1 << 32);
            }
            uint32_t pulse_width = falling_tick - rising_tick;
            if (pulse_width >= MIN_PULSE_US && pulse_width <= MAX_PULSE_US) {
                double distance = (pulse_width / 2.0) * 0.0343;
                char timestamp[32];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
                fprintf(stdout, "%s distance: %.2f m\n", timestamp, distance);
                fprintf(log_file, "%s distance: %.2f m\n", timestamp, distance);
                fflush(log_file);
            } else {
                fprintf(stderr, "Warning: invalid pulse width: %u us\n", pulse_width);
            }
        }
    }
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_new("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get line %d\n", TRIG_PIN);
        gpiod_chip_unref(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get line %d\n", ECHO_PIN);
        gpiod_line_unref(trig_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig_line, 0) < 0) {
        fprintf(stderr, "Failed to request output on line %d\n", TRIG_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo_line, GPIOD_LINE_EVENT_BOTH) < 0) {
        fprintf(stderr, "Failed to request input on line %d\n", ECHO_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_set_pull_up_down(echo_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on line %d\n", ECHO_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_set_value(trig_line, 1) < 0) {
        fprintf(stderr, "Failed to set high on line %d\n", TRIG_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    sleep(1);

    if (gpiod_line_set_value(trig_line, 0) < 0) {
        fprintf(stderr, "Failed to set low on line %d\n", TRIG_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_set_event_trigger(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, alert_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set event trigger on line %d\n", ECHO_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    if (gpiod_line_set_event_trigger(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, alert_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set event trigger on line %d\n", ECHO_PIN);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        gpiod_line_unref(trig_line);
        gpiod_line_unref(echo_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = TRIGGER_INTERVAL_US;
    while (1) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Failed to set high on line %d\n", TRIG_PIN);
            break;
        }
        nanosleep(&timeout);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set low on line %d\n", TRIG_PIN);
            break;
        }
        timeout.tv_sec = 0;
        timeout.tv_nsec = TRIGGER_INTERVAL_US;
        trigging = true;
        timeout.tv_sec = 0;
        timeout.tv_nsec = TIMEOUT_US;
        while (trigging && !echo_detected) {
            nanosleep(&timeout);
            if (gpiod_line_get_value(echo_line, NULL) == 1) {
                timeout.tv_sec = 0;
                timeout.tv_nsec = 1000000;
                while (gpiod_line_get_value(echo_line, NULL) == 1) {
                    nanosleep(&timeout);
                }
            }
        }
        if (!echo_detected) {
            fprintf(stderr, "Warning: no echo detected within 60 ms\n");
        }
        echo_detected = false;
        trigging = false;
    }

    fclose(log_file);
    gpiod_line_unref(trig_line);
    gpiod_line_unref(echo_line);
    gpiod_chip_unref(chip);
    return 0;
}

