#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>
#include <errno.h>

#define LOG_FILE "parking_log.txt"
#define VL53L1X_I2C_ADDRESS 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PIN 18
#define DETECT_DISTANCE 50
#define CLOSE_DISTANCE 60

// Function to log a message to the file
void log_message(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

// Function to read a byte from the VL53L1X sensor
uint8_t read_byte(uint8_t reg) {
    int fd = i2c_open("/dev/i2c-1", I2C_CLIENT_PIGPIO);
    if (fd < 0) {
        perror("i2c_open");
        return 0;
    }
    uint8_t data;
    if (i2c_smbus_read_byte_data(fd, VL53L1X_I2C_ADDRESS, reg, &data) < 0) {
        perror("i2c_smbus_read_byte_data");
        i2c_close(fd);
        return 0;
    }
    i2c_close(fd);
    return data;
}

// Function to write a byte to the VL53L1X sensor
void write_byte(uint8_t reg, uint8_t data) {
    int fd = i2c_open("/dev/i2c-1", I2C_CLIENT_PIGPIO);
    if (fd < 0) {
        perror("i2c_open");
        return;
    }
    if (i2c_smbus_write_byte_data(fd, VL53L1X_I2C_ADDRESS, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
        i2c_close(fd);
    } else {
        i2c_close(fd);
    }
}

// Function to initialize the VL53L1X sensor
bool init_vl53l1x() {
    // Check the model ID
    uint8_t model_id = read_byte(0xE0);
    if (model_id != 0x10) {
        log_message("Invalid VL53L1X model ID");
        return false;
    }

    // Set the shutdown pin as an output
    gpio_set_mode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT);
    gpio_write(VL53L1X_SHUTDOWN_PIN, 1);

    // Set the interrupt pin as an input
    gpio_set_mode(VL53L1X_INTERRUPT_PIN, PI_INPUT);

    // Set the I2C address
    write_byte(0xE0, 0x01);

    // Start the sensor
    write_byte(0x00, 0x01);

    return true;
}

// Function to read the distance from the VL53L1X sensor
uint16_t read_distance() {
    int fd = i2c_open("/dev/i2c-1", I2C_CLIENT_PIGPIO);
    if (fd < 0) {
        perror("i2c_open");
        return 0;
    }
    uint16_t distance;
    if (i2c_smbus_read_word_data(fd, VL53L1X_I2C_ADDRESS, 0x04, &distance) < 0) {
        perror("i2c_smbus_read_word_data");
        i2c_close(fd);
        return 0;
    }
    i2c_close(fd);
    return distance;
}

// Function to control the servo motor
void control_servo(uint8_t position) {
    gpio_set_mode(SERVO_PIN, PI_OUTPUT);
    gpio_pwm(SERVO_PIN, position);
}

// Function to handle the interrupt
void interrupt_handler(int signal) {
    log_message("Interrupt received");
    uint16_t distance = read_distance();
    if (distance < DETECT_DISTANCE) {
        log_message("Object detected at distance %d cm", distance);
        control_servo(0);
    } else {
        log_message("Object not detected at distance %d cm", distance);
        control_servo(100);
    }
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (!init_vl53l1x()) {
        return 1;
    }

    // Set up the interrupt handler
    signal(SIGINT, interrupt_handler);
    signal(SIGTERM, interrupt_handler);

    // Initialize the servo motor
    control_servo(100);

    // Main loop
    while (1) {
        uint16_t distance = read_distance();
        if (distance < DETECT_DISTANCE) {
            log_message("Object detected at distance %d cm", distance);
            control_servo(0);
        } else if (distance > CLOSE_DISTANCE) {
            log_message("Object not detected at distance %d cm", distance);
            control_servo(100);
        }
        sleep(0.1);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

