    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_OPEN_PIN, PI_OUTPUT) < 0 || gpioSetMode(GPIO_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
