        gpioTerminate();
        return 1;
    }

    // Configure timing budget
    uint8_t timing_budget = 0x0a;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, timing_budget) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    uint8_t start = 0x01;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x80, start) < 0) {
