            fclose(log_file);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (i2c_smbus_read_byte_data(i2c_fd, 0x80, &status) < 0) {
            fprintf(stderr, "Failed to read status\n");
            fclose(log_file);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check if object is detected
        if (status & 0x01 && distance < DISTANCE_THRESHOLD) {
            // Open gate
            gpioWrite(GPIO_OPEN_PIN, 1);
            gpioWrite(GPIO_CLOSE_PIN, 0);
            fprintf(log_file, "%s: Gate opened\n", ctime_r(&time(NULL), buf));
        } else {
            // Close gate
            gpioWrite(GPIO_OPEN_PIN, 0);
            gpioWrite(GPIO_CLOSE_PIN, 1);
            fprintf(log_file, "%s: Gate closed\n", ctime_r(&time(NULL), buf));
        }

        // Sleep for 500ms
        usleep(500000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

