#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <gpiod.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300
#define MAX_RETRIES 10
#define BACKOFF_FACTOR 2

// Define the VL53L1X register addresses
#define VL53L1X_SYSRST_ID 0x00
#define VL53L1X_START_MEASUREMENT 0x00
#define VL53L1X_STATUS 0x80
#define VL53L1X_DISTANCE 0x00

// Define the VL53L1X distance value structure
typedef struct {
    uint16_t distance;
} vl53l1x_distance_t;

// Function to perform a soft reset on the VL53L1X sensor
int vl53l1x_soft_reset(int i2c_handle) {
    uint8_t data = 0x00;
    int retries = 0;

    while (i2c_write_byte(i2c_handle, I2C_ADDRESS, VL53L1X_SYSRST_ID, &data, 1) != 0) {
        if (retries++ >= MAX_RETRIES) {
            fprintf(stderr, "Failed to perform soft reset on VL53L1X sensor\n");
            return -1;
        }
        usleep(100000 * BACKOFF_FACTOR);
    }

    return 0;
}

// Function to start a measurement on the VL53L1X sensor
int vl53l1x_start_measurement(int i2c_handle) {
    uint8_t data = 0x00;
    int retries = 0;

    while (i2c_write_byte(i2c_handle, I2C_ADDRESS, VL53L1X_START_MEASUREMENT, &data, 1) != 0) {
        if (retries++ >= MAX_RETRIES) {
            fprintf(stderr, "Failed to start measurement on VL53L1X sensor\n");
            return -1;
        }
        usleep(100000 * BACKOFF_FACTOR);
    }

    return 0;
}

// Function to read the distance value from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle, vl53l1x_distance_t *distance) {
    uint8_t data[2];
    int retries = 0;

    while (i2c_read_byte_data(i2c_handle, I2C_ADDRESS, VL53L1X_DISTANCE, data, 2) != 0) {
        if (retries++ >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read distance value from VL53L1X sensor\n");
            return -1;
        }
        usleep(100000 * BACKOFF_FACTOR);
    }

    distance->distance = (data[0] << 8) | data[1];
    return 0;
}

// Function to check if the VL53L1X sensor is present
int vl53l1x_is_present(int i2c_handle) {
    uint8_t data;
    int retries = 0;

    while (i2c_read_byte(i2c_handle, I2C_ADDRESS, VL53L1X_SYSRST_ID, &data, 1) != 0) {
        if (retries++ >= MAX_RETRIES) {
            fprintf(stderr, "Failed to check if VL53L1X sensor is present\n");
            return -1;
        }
        usleep(100000 * BACKOFF_FACTOR);
    }

    return data == 0x00;
}

// Function to handle the GPIO interrupt
void gpio_isr(int gpio, int level, void *user_data) {
    int i2c_handle = *(int *)user_data;
    vl53l1x_distance_t distance;

    if (vl53l1x_is_present(i2c_handle) == 0) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
        return;
    }

    if (vl53l1x_soft_reset(i2c_handle) != 0) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
        return;
    }

    if (vl53l1x_start_measurement(i2c_handle) != 0) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
        return;
    }

    while (1) {
        if (i2c_read_byte_data(i2c_handle, I2C_ADDRESS, VL53L1X_STATUS, NULL, 1) == 0) {
            break;
        }
        usleep(10000);
    }

    if (vl53l1x_read_distance(i2c_handle, &distance) != 0) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
        return;
    }

    if (distance.distance < DISTANCE_THRESHOLD_FORWARD) {
        gpio_write(GPIO_MOTOR_FORWARD, 1);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
    } else if (distance.distance > DISTANCE_THRESHOLD_BACKWARD) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 1);
    } else {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
    }

    printf("Distance: %d mm\n", distance.distance);
}

int main() {
    int i2c_handle;
    int gpio_handle;

    // Initialize the I2C bus
    if ((i2c_handle = i2c_open(I2C_BUS)) == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the GPIO pins
    if (gpioInitialise() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2c_close(i2c_handle);
        return 1;
    }

    gpio_handle = gpioOpen(GPIO_TRIGGER, GPIO_READ);
    if (gpio_handle == -1) {
        fprintf(stderr, "Failed to open GPIO pin\n");
        gpioTerminate();
        i2c_close(i2c_handle);
        return 1;
    }

    // Set up the GPIO interrupt
    gpioSetMode(GPIO_TRIGGER, GPIO_INPUT);
    gpioSetPullUpDnControl(GPIO_TRIGGER, GPIO_PUD_UP);
    gpioISR(GPIO_TRIGGER, EITHER_EDGE, gpio_isr, &i2c_handle);

    // Start the I2C bus
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_ADDRESS, VL53L1X_SYSRST_ID, 0x00) != 0) {
        fprintf(stderr, "Failed to start I2C bus\n");
        gpioTerminate();
        i2c_close(i2c_handle);
        return 1;
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    // Clean up on exit
    gpioTerminate();
    i2c_close(i2c_handle);
    return 0;
}

// Signal handler to clean up on exit
void sigint_handler(int signal) {
    gpioTerminate();
    i2c_close(i2c_handle);
    exit(0);
}

// Signal handler to clean up on exit
void sigterm_handler(int signal) {
    gpioTerminate();
    i2c_close(i2c_handle);
    exit(0);
}

// Register the signal handlers
void setup_signal_handlers() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    setup_signal_handlers();
    return main();
}

