        usleep(10000);
    }

    if (vl53l1x_read_distance(i2c_handle, &distance) != 0) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
        return;
    }

    if (distance.distance < DISTANCE_THRESHOLD_FORWARD) {
        gpio_write(GPIO_MOTOR_FORWARD, 1);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
    } else if (distance.distance > DISTANCE_THRESHOLD_BACKWARD) {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 1);
    } else {
        gpio_write(GPIO_MOTOR_FORWARD, 0);
        gpio_write(GPIO_MOTOR_BACKWARD, 0);
