#define LED_PIN 27
#define PROXIMITY_LOG_FILE "proximity.log"

// Function to handle signal interrupts
void signal_handler(int signal) {
    // Release I2C bus
    i2c_close(fd);
    // Release GPIO
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus
    char i2c_dev[] = "/dev/i2c-1";
    if ((fd = open(i2c_dev, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus to MPR121 address
    if (ioctl(fd, I2C_SLAVE, MPR121_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read device ID to verify the sensor is present
    uint8_t device_id;
    if (i2c_smbus_read_byte(fd, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "Device ID mismatch\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure FFI (Filter Frequency Inversion)
    uint8_t ffi = 0x00;
    if (i2c_smbus_write_byte(fd, 0x02, &ffi) < 0) {
        fprintf(stderr, "Failed to configure FFI\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure SFI (Sample Frequency Inversion)
    uint8_t sfi = 0x00;
    if (i2c_smbus_write_byte(fd, 0x03, &sfi) < 0) {
        fprintf(stderr, "Failed to configure SFI\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure ESI (Enable Scan Inversion)
    uint8_t esi = 0x00;
    if (i2c_smbus_write_byte(fd, 0x04, &esi) < 0) {
        fprintf(stderr, "Failed to configure ESI\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure debounce
    uint8_t debounce = 0x00;
    if (i2c_smbus_write_byte(fd, 0x05, &debounce) < 0) {
        fprintf(stderr, "Failed to configure debounce\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure AFE (Analog Front End)
    uint8_t afe = 0x00;
    if (i2c_smbus_write_byte(fd, 0x06, &afe) < 0) {
        fprintf(stderr, "Failed to configure AFE\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure baseline filtering
    uint8_t baseline = 0x00;
    if (i2c_smbus_write_byte(fd, 0x07, &baseline) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    FILE *log_file = fopen(PROXIMITY_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read touch inputs
        uint8_t touch_inputs;
        if (i2c_smbus_read_byte(fd, &touch_inputs) < 0) {
            fprintf(stderr, "Failed to read touch inputs\n");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Check for proximity event
        if (touch_inputs & 0x01) {
            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Log proximity event
            time_t timestamp = time(NULL);
            fprintf(log_file, "%lu: Proximity event detected\n", timestamp);

            // Wait for 1 second
            sleep(1);

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Release resources
    fclose(log_file);
    close(fd);
    gpioTerminate();

    return 0;
}

