#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    int trigger_fd = gpioInitialise();
    if (trigger_fd < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", strerror(errno));
        return 1;
    }

    int echo_fd = gpioInitialise();
    if (echo_fd < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", strerror(errno));
        gpioTerminate(trigger_fd);
        return 1;
    }

    gpioSetMode(trigger_fd, PI_OUTPUT);
    gpioSetMode(echo_fd, PI_INPUT);

    struct stat sb;
    if (stat(LOG_FILE, &sb) == 0 && S_ISREG(sb.st_mode)) {
        unlink(LOG_FILE);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate(trigger_fd);
        gpioTerminate(echo_fd);
        return 1;
    }

    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    while (!stop) {
        if (gpioRead(echo_fd) == 1) {
            fprintf(stderr, "Error: Sensor absent\n");
            continue;
        }

        gpioWrite(trigger_fd, 0);
        usleep(5 * 1000);

        gpioWrite(trigger_fd, 1);
        usleep(10 * 1000);
        gpioWrite(trigger_fd, 0);

        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t start_time = tv.tv_sec * 1000000 + tv.tv_usec;

        while (gpioRead(echo_fd) == 0 && !stop) {
            usleep(1000);
            gettimeofday(&tv, NULL);
            if (tv.tv_sec * 1000000 + tv.tv_usec - start_time > 30000) {
                fprintf(stderr, "Error: Timeout waiting for echo\n");
                break;
            }
        }

        if (stop) {
            break;
        }

        uint64_t end_time = tv.tv_sec * 1000000 + tv.tv_usec;
        uint64_t pulse_width = end_time - start_time;

        if (pulse_width < 10000 || pulse_width > 400000) {
            fprintf(stderr, "Error: Invalid pulse width\n");
            continue;
        }

        double distance = (pulse_width / 2.0) * 34300 / 1000000.0;

        char buffer[32];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
        fprintf(log_file, "%s %.2f cm\n", buffer, distance);
        fflush(log_file);

        usleep(1000000);
    }

    fclose(log_file);
    gpioTerminate(trigger_fd);
    gpioTerminate(echo_fd);
    return 0;
}

