#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_HZ 1
#define MIN_DISTANCE_CM 1
#define MAX_DISTANCE_CM 400

volatile bool isRunning = true;
volatile uint32_t lastEdge = 0;
volatile uint32_t pulseWidth = 0;

void cleanup() {
    gpioSetMode(TRIG_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioUnexport(TRIG_PIN);
    gpioUnexport(ECHO_PIN);
    close(logFile);
    gpioTerminate();
    gpiod_cleanup();
    exit(0);
}

void sigintHandler(int sig) {
    isRunning = false;
}

void echoISR(int edge, int level, uint32_t tick) {
    if (edge == RISING_EDGE) {
        lastEdge = tick;
    } else if (edge == FALLING_EDGE && isRunning) {
        pulseWidth = tick - lastEdge;
        if (pulseWidth > 0 && pulseWidth < 25000000) {
            double distance = (pulseWidth / 2.0) * 0.034 / 2;
            char buffer[32];
            time_t now = time(NULL);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(logFile, "%s %.2f\n", buffer, distance);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioExport(TRIG_PIN) < 0) {
        fprintf(stderr, "Failed to export TRIG pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioExport(ECHO_PIN) < 0) {
        fprintf(stderr, "Failed to export ECHO pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod library\n");
        gpioTerminate();
        return 1;
    }

    if (signal(SIGINT, sigintHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return 1;
    }

    if (signal(SIGTERM, sigintHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        gpioTerminate();
        return 1;
    }

    struct stat sb;
    if (stat("distance_log.txt", &sb) == 0 && S_ISREG(sb.st_mode)) {
        logFile = fopen("distance_log.txt", "a");
    } else {
        logFile = fopen("distance_log.txt", "w");
    }

    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (isRunning) {
        if (gpioRead(TRIG_PIN) == 0) {
            gpioWrite(TRIG_PIN, 1);
            usleep(10 * 1000 / TRIGGER_HZ);
            gpioWrite(TRIG_PIN, 0);
            gpiod_set_event_detect(ECHO_PIN, RISING_EDGE, 1, 0);
            gpiod_set_event_detect(ECHO_PIN, FALLING_EDGE, 1, 0);
        }
        usleep(1000 / TRIGGER_HZ);
    }

    cleanup();
    return 0;
}

