#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_XSHUT_PIN 27
#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_FILE "/dev/i2c-1"
#define VL53L1X_I2C_SPEED 100000

#define LOG_TAG "vl53l1x"

static void sigint_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, closing I2C handle and exiting", sig);
    close(i2c_fd);
    pigpioTerminate();
    exit(0);
}

static void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, closing I2C handle and exiting", sig);
    close(i2c_fd);
    pigpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd;
    int ret;
    uint8_t reg;
    uint16_t distance;
    char buffer[256];

    // Initialize syslog
    openlog(LOG_TAG, LOG_PID | LOG_CONS, LOG_INFO);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }

    // Set XSHUT pin as output and high
    if (gpioSetMode(VL53L1X_XSHUT_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin mode");
        gpioTerminate();
        exit(1);
    }
    if (gpioWrite(VL53L1X_XSHUT_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin high");
        gpioTerminate();
        exit(1);
    }

    // Open I2C device
    i2c_fd = open(VL53L1X_I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        exit(1);
    }

    // Set I2C speed
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C speed");
        close(i2c_fd);
        gpioTerminate();
        exit(1);
    }

    // Initialize VL53L1X driver
    if (pigpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X driver");
        close(i2c_fd);
        gpioTerminate();
        exit(1);
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read distance
        ret = i2c_smbus_read_byte_data(i2c_fd, 0x00);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read distance");
            continue;
        }

        // Read distance
        ret = i2c_smbus_read_word_data(i2c_fd, 0x04);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read distance");
            continue;
        }
        distance = ret;

        // Log reading
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        syslog(LOG_INFO, "Distance: %d mm, Status: %s", distance, "OK");

        // Sleep for 100ms
        usleep(100000);
    }

    // Close I2C handle
    close(i2c_fd);

    // Terminate driver library
    pigpioTerminate();

    // Close GPIO
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

