#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GATE_PIN 24
#define LOG_FILE "gate_log.txt"
#define MEASUREMENT_INTERVAL 100000 // 100ms in microseconds

// Function to convert 16-bit register value to centimeters
uint16_t to_cm(uint16_t value) {
    return (uint16_t)((value * 100) / 512);
}

// Function to log a message to the log file
void log_message(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, message);
    fclose(file);
}

// Function to read distance measurement from VL53L1X sensor
uint16_t read_distance() {
    int fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        perror("i2c_open");
        return 0;
    }
    uint16_t value;
    if (i2c_smbus_read_byte_data(fd, 0x80, &value) < 0) {
        perror("i2c_smbus_read_byte_data");
        i2c_close(fd);
        return 0;
    }
    i2c_close(fd);
    return to_cm(value);
}

// Function to control the gate actuator
void control_gate(bool open) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return;
    }
    if (open) {
        gpioSetMode(GATE_PIN, PI_OUTPUT);
        gpioWrite(GATE_PIN, 1);
        log_message("Gate opened");
    } else {
        gpioSetMode(GATE_PIN, PI_OUTPUT);
        gpioWrite(GATE_PIN, 0);
        log_message("Gate closed");
    }
    gpioTerminate();
}

// SIGINT/SIGTERM handler
void sig_handler(int sig) {
    log_message("Received signal, shutting down");
    i2c_close(I2C_BUS);
    fclose(LOG_FILE);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }
    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, 0);
    log_message("Gate initialized to closed state");
    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        perror("fopen");
        return 1;
    }
    fclose(file);
    while (1) {
        uint16_t distance = read_distance();
        if (distance == 0) {
            log_message("Failed to read distance measurement");
            continue;
        }
        if (distance < 20) {
            control_gate(true);
        } else {
            control_gate(false);
        }
        log_message("Distance: %d cm", distance);
        usleep(MEASUREMENT_INTERVAL);
    }
    return 0;
}

