#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/gpiod.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SERVO 18
#define CSV_FILE "distance_log.csv"
#define CSV_HEADER "timestamp,distance,angle\n"
#define SAMPLES 5
#define FILTER_WEIGHT 0.1

volatile sig_atomic_t stop = 0;
volatile uint32_t pulse_width = 0;
volatile bool new_pulse = false;

int gpio_fd;
int servo_fd;
int csv_fd;
uint32_t last_timestamp = 0;
uint32_t last_distance = 0;
uint32_t last_angle = 0;
uint32_t filter_sum = 0;
uint32_t filter_count = 0;
uint32_t filter_sum2 = 0;
uint32_t filter_count2 = 0;

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        last_timestamp = tick;
    } else {
        uint32_t pulse = tick - last_timestamp;
        if (pulse > 0) {
            pulse_width = pulse;
            new_pulse = true;
        }
    }
}

int main() {
    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up trigger pin as output
    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up trigger pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up echo pin as input
    if (gpioSetMode(GPIO_ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up servo pin as output
    if (gpioSetMode(GPIO_SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up servo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on echo pin
    if (gpioSetISR(GPIO_ECHO, EITHER_EDGE, echo_callback) < 0) {
        fprintf(stderr, "Failed to set up interrupt on echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Initialize servo
    servo_fd = gpioServoCreate(GPIO_SERVO);
    if (servo_fd < 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_fd = fopen(CSV_FILE, "w");
    if (csv_fd == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row to CSV file
    fprintf(csv_fd, CSV_HEADER);
    fflush(csv_fd);

    // Pulse trigger pin every 100ms
    while (!stop) {
        // Pulse trigger pin
        gpioPulse(GPIO_TRIGGER, 10, 1000000);

        // Wait for echo
        uint32_t start = gpioTick();
        while (gpioRead(GPIO_ECHO) == 0 && gpioTick() - start < 30000000) {
            // Do nothing
        }

        // Check if echo timed out
        if (gpioTick() - start >= 30000000) {
            fprintf(csv_fd, "%u,-1.0,90\n", gpioTick());
            fflush(csv_fd);
            gpioServoSetPosition(servo_fd, 90);
            continue;
        }

        // Check if new pulse available
        while (!new_pulse) {
            // Do nothing
        }
        new_pulse = false;

        // Calculate distance
        uint32_t distance = (pulse_width * 0.0343) / 2;
        if (distance < 2 || distance > 400) {
            distance = -1.0;
        }

        // Filter distance
        filter_sum = (filter_sum * (SAMPLES - 1) + distance) / SAMPLES;
        filter_count = (filter_count + 1) % SAMPLES;
        filter_sum2 = (filter_sum2 * (SAMPLES - 1) + filter_sum) / SAMPLES;
        filter_count2 = (filter_count2 + 1) % SAMPLES;

        // Log distance and angle
        fprintf(csv_fd, "%u,%f,%f\n", gpioTick(), filter_sum2, gpioServoGetAngle(servo_fd));
        fflush(csv_fd);

        // Update servo angle
        gpioServoSetPosition(servo_fd, filter_sum2);

        // Reset pulse width
        pulse_width = 0;
    }

    // Stop servo
    gpioServoSetPosition(servo_fd, 0);

    // Close CSV file
    fclose(csv_fd);

    // Cleanup
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Call main function
    return main();
}

