#define VL53L1X_ADDRESS 0x29
#define VL53L1X_DEFAULT_CONFIG 0x00
#define VL53L1X_SIGNAL_RATE_CHECKING 0x01
#define VL53L1X_CROSS_TALK_COMPENSATION 0x02
#define VL53L1X_START_RANGING 0x04
#define VL53L1X_DISTANCE 0x30
#define VL53L1X_DISTANCE_SIZE 2
#define BUFFER_SIZE 10
#define LED_PIN 17
#define READ_TIMEOUT 50

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int fd;
    int ret;
    uint8_t buffer[VL53L1X_DISTANCE_SIZE];
    uint16_t distance;
    uint16_t buffer[BUFFER_SIZE];
    int head = 0;
    int tail = 0;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C interface
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C interface\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, VL53L1X_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (i2c_smbus_write_byte(fd, VL53L1X_DEFAULT_CONFIG) < 0) {
        fprintf(stderr, "Failed to set default configuration\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_smbus_write_byte(fd, VL53L1X_SIGNAL_RATE_CHECKING) < 0) {
        fprintf(stderr, "Failed to enable signal-rate checking\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_smbus_write_byte(fd, VL53L1X_CROSS_TALK_COMPENSATION) < 0) {
        fprintf(stderr, "Failed to configure cross-talk compensation\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_smbus_write_byte(fd, VL53L1X_START_RANGING) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = 0;
    }

    // Set up LED pin
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPullUpDown(LED_PIN, PI_PUD_UP);

    while (running) {
        // Read distance
        if (i2c_smbus_read_byte_data(fd, VL53L1X_DISTANCE, buffer) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        // Convert distance to millimeters
        distance = (buffer[0] << 8) | buffer[1];

        // Store in buffer
        buffer[tail] = distance;
        tail = (tail + 1) % BUFFER_SIZE;

        // Check if buffer is full
        if (tail == head) {
            head = (head + 1) % BUFFER_SIZE;
        }

        // Check if distance is below threshold
        if (distance < 200) {
            gpioSetMode(LED_PIN, PI_OUTPUT);
            gpioWrite(LED_PIN, 1);
        } else {
            gpioSetMode(LED_PIN, PI_OUTPUT);
            gpioWrite(LED_PIN, 0);
        }

        // Wait for next measurement
        usleep(READ_TIMEOUT * 1000);
    }

    // Clean up
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    close(fd);
    return 0;
}

