#define DEFAULT_THRESHOLD 1000
#define DEFAULT_I2C_ADDRESS 0x5A

#define PROXIMITY_LOG_FILE "proximity.log"

struct proximity_data {
    int i2c_fd;
    int gpio_fd;
    int threshold;
    int i2c_address;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    bool interrupt_pending;
};

static void sigint_handler(int sig) {
    struct proximity_data *data = NULL;
    pthread_mutex_lock(&data->mutex);
    data->interrupt_pending = false;
    pthread_mutex_unlock(&data->mutex);
    close(data->i2c_fd);
    close(data->gpio_fd);
    pthread_exit(NULL);
}

static void *interrupt_handler(void *arg) {
    struct proximity_data *data = (struct proximity_data *)arg;
    while (1) {
        int ret = gpiod_read_line(data->gpio_fd, GPIOD_LINE_BOTH, 1);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO: %s\n", strerror(errno));
            pthread_exit(NULL);
        }
        pthread_mutex_lock(&data->mutex);
        data->interrupt_pending = true;
        pthread_cond_signal(&data->cond);
        pthread_mutex_unlock(&data->mutex);
    }
    pthread_exit(NULL);
}

