#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SPEAKER 18
#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100
#define DISTANCE_MIN 2
#define DISTANCE_MAX 200
#define FREQUENCY_MIN 200
#define FREQUENCY_MAX 2000
#define TIMEOUT_US 200000

void sigint_handler(int sig) {
    gpioPWM(GPIO_SPEAKER, 0);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_ECHO, PI_INPUT) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_SPEAKER, PI_OUTPUT_PWM) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    gpioPulse(GPIO_TRIGGER, 10, 1);
    usleep(10);
    gpioPulse(GPIO_TRIGGER, 0, 1);

    double frequency = FREQUENCY_MIN;
    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        int64_t start = tv.tv_sec * 1000000 + tv.tv_usec;
        int level = gpioRead(GPIO_ECHO);
        while (level == 0 && (tv.tv_sec * 1000000 + tv.tv_usec - start) < TIMEOUT_US) {
            gettimeofday(&tv, NULL);
            level = gpioRead(GPIO_ECHO);
        }
        if (level == 0) {
            frequency = FREQUENCY_MIN;
        } else {
            int64_t duration = tv.tv_sec * 1000000 + tv.tv_usec - start;
            double distance = (duration * 34300) / 2;
            if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
                distance = (distance < DISTANCE_MIN) ? DISTANCE_MIN : DISTANCE_MAX;
            }
            frequency = FREQUENCY_MIN + (FREQUENCY_MAX - FREQUENCY_MIN) * log2(distance / DISTANCE_MIN);
        }
        int duty = (int) ((frequency / PWM_FREQ) * PWM_DUTY_MAX);
        if (gpioPWM(GPIO_SPEAKER, duty) == -1) {
            perror("gpioPWM");
            gpioTerminate();
            return 1;
        }
        usleep(1000000 / PWM_FREQ);
    }

    gpioTerminate();
    return 0;
}

