#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BCM_GPIO18 18
#define BCM_GPIO23 23
#define BCM_GPIO24 24
#define ECHO_TIMEOUT_US 100000
#define MIN_DISTANCE_CM 5
#define MAX_DISTANCE_CM 50
#define MIN_FREQ_HZ 200
#define MAX_FREQ_HZ 2000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int gpio = gpioInitialise();
    if (gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpioSetMode(gpio, BCM_GPIO18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(gpio, BCM_GPIO23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO23 mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(gpio, BCM_GPIO24, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO24 mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(gpio, BCM_GPIO24, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO24 pull-down resistor\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioPWM(BCM_GPIO18, 0);

    while (running) {
        gpioWrite(BCM_GPIO23, 0);
        usleep(10);
        gpioWrite(BCM_GPIO23, 1);
        usleep(10);
        int duration = gpioDuration(BCM_GPIO24, 0, ECHO_TIMEOUT_US);
        if (duration < 0) {
            fprintf(stderr, "Failed to read echo duration\n");
            continue;
        }

        if (duration > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Echo timeout\n");
            duration = gpioDuration(BCM_GPIO24, 0, ECHO_TIMEOUT_US);
            if (duration < 0) {
                fprintf(stderr, "Failed to read echo duration\n");
                continue;
            }
        }

        double distance_cm = (double)duration * 0.034 / 2;
        if (distance_cm < MIN_DISTANCE_CM) {
            distance_cm = MIN_DISTANCE_CM;
        } else if (distance_cm > MAX_DISTANCE_CM) {
            distance_cm = MAX_DISTANCE_CM;
        }

        double freq_hz = (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * (MAX_FREQ_HZ - MIN_FREQ_HZ) + MIN_FREQ_HZ;

        gpioPWM(BCM_GPIO18, (int)(freq_hz * 1000 / 32000000));

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance_cm, freq_hz);

        usleep(10000);
    }

    gpioPWM(BCM_GPIO18, 0);
    gpioTerminate();

    return 0;
}

