#include <signal.h>
#include <gpiod.h>

// Flag to exit the loop
bool exit_flag = false;

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    exit_flag = true;
}

int main() {
    // Initialize the driver library
    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get the line numbers for GPIO17 and GPIO18
    struct gpiod_line *trigger_line, *echo_line;
    if ((trigger_line = gpiod_chip_get_line(chip, 17)) == NULL) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if ((echo_line = gpiod_chip_get_line(chip, 18)) == NULL) {
        fprintf(stderr, "Failed to get line 18\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the trigger pin as an output initially low
    if (gpiod_line_request_output(trigger_line, 0) != 0) {
        fprintf(stderr, "Failed to request output for line 17\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the echo pin as an input
    if (gpiod_line_request_input(echo_line, 0) != 0) {
        fprintf(stderr, "Failed to request input for line 18\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!exit_flag) {
        // Trigger the sensor
        if (gpiod_line_set_value(trigger_line, 1) != 0) {
            fprintf(stderr, "Failed to set trigger high\n");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            return 1;
        }
        usleep(10 * 1000); // 10us
        if (gpiod_line_set_value(trigger_line, 0) != 0) {
            fprintf(stderr, "Failed to set trigger low\n");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Measure the echo pulse duration
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(echo_line, 50 * 1000, &event) != 0) {
            // Timeout, treat as -1 result
            printf("Invalid reading\n");
        } else {
            uint64_t pulse_duration = event.timestamp - event.edge;
            if (pulse_duration < 2 * 1000 * 1000 || pulse_duration > 400 * 1000 * 1000) {
                printf("Invalid reading\n");
            } else {
                double distance = (pulse_duration / 2.0) / 29.1;
                printf("Distance: %.2f cm", distance);
                if (distance < 10) {
                    printf(" Too close!\n");
                }
                printf("\n");
            }
        }

        // Sleep for 500ms
        usleep(500 * 1000);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}
