#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define LOG_FILE "proximity_log.csv"
#define LOG_HEADER "timestamp,als_visible\n"

#define READ_SIZE 2

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("i2c_open");
        close(fd);
        exit(EXIT_FAILURE);
    }
    return fd;
}

int i2c_read(int fd, uint8_t *buf, size_t count) {
    if (read(fd, buf, count) != count) {
        perror("i2c_read");
        close(fd);
        exit(EXIT_FAILURE);
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    int fd = i2c_open();
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        close(fd);
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s", LOG_HEADER);

    while (running) {
        uint8_t buf[READ_SIZE];
        if (i2c_read(fd, buf, READ_SIZE) < 0) {
            break;
        }
        uint16_t als_visible = (buf[0] << 8) | buf[1];
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(log_file, "%s,%u\n", timestamp, als_visible);
        sleep(5);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

