#define SI1120_ALS_REGISTER 0x02
#define SI1120_PROX_REGISTER 0x03
#define SI1120_PART_ID_VALUE 0x12
#define SI1120_RESET_VALUE 0x55

#define LOG_FILE "si1120_log.txt"

int i2c_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *reset_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (reset_line != NULL) {
        gpiod_line_release(reset_line);
    }
    unlink(LOG_FILE);
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int i2c_open() {
    int fd;
    char i2c_dev[] = "/dev/i2c-1";
    struct i2c_devinfo devinfo;
    struct i2c_msg msg;
    struct i2c_msg msg2;
    char buffer[2];

    fd = open(i2c_dev, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1120_ADDRESS) == -1) {
        perror("ioctl");
        close(fd);
        return -1;
    }

    msg.addr = SI1120_ADDRESS;
    msg.flags = 0;
    msg.buf = buffer;
    msg.len = 1;
    msg2.addr = SI1120_ADDRESS;
    msg2.flags = 0;
    msg2.buf = buffer;
    msg2.len = 1;

    for (int i = 0; i < 3; i++) {
        if (i2c_smbus_write_byte(fd, SI1120_RESET_REGISTER, SI1120_RESET_VALUE) == -1) {
            perror("i2c_smbus_write_byte");
            close(fd);
            return -1;
        }
        usleep(10000);
        if (i2c_smbus_read_byte(fd, SI1120_PART_ID_REGISTER, &buffer[0]) == -1) {
            perror("i2c_smbus_read_byte");
            close(fd);
            return -1;
        }
        if (buffer[0] != SI1120_PART_ID_VALUE) {
            fprintf(stderr, "Invalid part ID\n");
            close(fd);
            return -1;
        }
    }

    return fd;
}

int main() {
    struct tm *timeinfo;
    time_t rawtime;
    char timestamp[20];
    FILE *log_file;
    uint16_t als, prox;
    uint8_t buffer[2];

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(1);
    }

    reset_line = gpiod_line_request_output(chip, 0, "reset");
    if (reset_line == NULL) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(1);
    }

    gpiod_line_set_value(reset_line, 1);
    usleep(100);
    gpiod_line_set_value(reset_line, 0);

    i2c_fd = i2c_open();
    if (i2c_fd == -1) {
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    while (1) {
        for (int i = 0; i < 3; i++) {
            if (i2c_smbus_read_byte(fd, SI1120_ALS_REGISTER, &buffer[0]) == -1) {
                perror("i2c_smbus_read_byte");
                fclose(log_file);
                close(i2c_fd);
                gpiod_line_release(reset_line);
                gpiod_chip_close(chip);
                exit(1);
            }
            if (i2c_smbus_read_byte(fd, SI1120_PROX_REGISTER, &buffer[1]) == -1) {
                perror("i2c_smbus_read_byte");
                fclose(log_file);
                close(i2c_fd);
                gpiod_line_release(reset_line);
                gpiod_chip_close(chip);
                exit(1);
            }
            als = (buffer[0] << 8) | buffer[1];
            prox = (buffer[1] << 8) | buffer[0];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s ALS: %d, Prox: %d\n", timestamp, als, prox);
            fflush(log_file);
        }
        usleep(500000);
    }

    cleanup();
    return 0;
}

