#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182A_ADDRESS 0x4A
#define SI1182A_PART_ID 0x00
#define SI1182A_MEAS_RATE 0x01
#define SI1182A_MEAS_RATE_VAL 0x03
#define SI1182A_MEAS_RATE_MASK 0x0F
#define SI1182A_MEAS_RATE_SHIFT 0
#define SI1182A_LUX 0x02
#define SI1182A_PROX 0x03

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t val) {
    struct i2c_msg msg = {
        .addr = SI1182A_ADDRESS,
        .flags = 0,
        .buf = &val,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_SLAVE, SI1182A_ADDRESS);
    if (ret < 0) {
        perror("i2c_write");
        return -1;
    }
    ret = ioctl(fd, I2C_RDWR, &msgs[0]);
    if (ret < 0) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t* val) {
    struct i2c_msg msg = {
        .addr = SI1182A_ADDRESS,
        .flags = I2C_M_RD,
        .buf = val,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_SLAVE, SI1182A_ADDRESS);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }
    ret = ioctl(fd, I2C_RDWR, &msgs[0]);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    uint8_t part_id;
    if (i2c_read(fd, SI1182A_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading part ID\n");
        close(fd);
        return 1;
    }
    if (part_id != SI1182A_PART_ID) {
        fprintf(stderr, "Invalid part ID 0x%02x\n", part_id);
        close(fd);
        return 1;
    }

    if (i2c_write(fd, SI1182A_MEAS_RATE, SI1182A_MEAS_RATE_VAL) < 0) {
        fprintf(stderr, "Error writing measurement rate\n");
        close(fd);
        return 1;
    }

    FILE* log_file = fopen("biometric_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t lux, prox;
        if (i2c_read(fd, SI1182A_LUX, &lux) < 0) {
            fprintf(stderr, "Error reading lux\n");
