            retries++;
            usleep(100000); // wait 100ms before retrying
            continue;
        }
        if (i2c_smbus_read_i2c_block_data(file, reg, len, data) < 0) {
            syslog(LOG_ERR, "Failed to read from I2C register 0x%02x: %s", reg, strerror(errno));
            retries++;
            usleep(100000); // wait 100ms before retrying
            continue;
        }
        return 0;
    }
    syslog(LOG_ERR, "Failed to read from I2C register 0x%02x after %d retries", reg, MAX_RETRIES);
    return -1;
}

// Function to handle I2C write operation
int i2c_write(int file, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(file, I2C_SLAVE, I2C_ADDRESS) < 0) {
            syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
            return -1;
        }
        if (i2c_smbus_write_byte_data(file, reg, *data) < 0) {
            syslog(LOG_ERR, "Failed to write to I2C register 0x%02x: %s", reg, strerror(errno));
            retries++;
            usleep(100000); // wait 100ms before retrying
            continue;
        }
        return 0;
    }
    syslog(LOG_ERR, "Failed to write to I2C register 0x%02x after %d retries", reg, MAX_RETRIES);
    return -1;
}

