#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <gpiod.h>

// Define constants
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIGGER_LEVEL 1
#define BUZZER_LEVEL 1
#define DISTANCE_THRESHOLD 20
#define TRIGGER_PULSE_WIDTH_US 10
#define MEASUREMENT_INTERVAL_S 1

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_line_release(TRIGGER_PIN);
    gpiod_line_release(ECHO_PIN);
    gpiod_line_release(BUZZER_PIN);
    gpiod_driver_close();
    exit(0);
}

// Function to measure distance using HC-SR04 ultrasonic sensor
double measure_distance() {
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    int num_events;
    struct timeval start, end;
    double distance;

    // Initialize trigger and echo lines
    trigger_line = gpiod_line_request_output(TRIGGER_PIN, "active-high");
    if (!trigger_line) {
        fprintf(stderr, "Failed to request trigger line\n");
        exit(1);
    }

    echo_line = gpiod_line_request_input(ECHO_PIN, "both");
    if (!echo_line) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        exit(1);
    }

    // Generate trigger pulse
    gpiod_line_set_value(trigger_line, TRIGGER_LEVEL);
    usleep(TRIGGER_PULSE_WIDTH_US * 1000);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo event
    while (1) {
        num_events = gpiod_line_read_events(echo_line, &event, 1);
        if (num_events > 0) {
            break;
        }
        usleep(1000);
    }

    // Record start timestamp
    gettimeofday(&start, NULL);

    // Wait for falling edge
    while (1) {
        num_events = gpiod_line_read_events(echo_line, &event, 1);
        if (num_events > 0 && event.event == GPIOD_LINE_EVENT_FALLING_EDGE) {
            break;
        }
        usleep(1000);
    }

    // Record end timestamp
    gettimeofday(&end, NULL);

    // Calculate distance
    distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
    distance = distance / 2.0 / 58.82; // Speed of sound in cm/μs

    // Release lines
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);

    return distance;
}

int main() {
    struct gpiod_driver *driver;
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line, *buzzer_line;

    // Initialize driver library
    driver = gpiod_driver_new();
    if (!driver) {
        fprintf(stderr, "Failed to initialize driver library\n");
        exit(1);
    }

    // Open chip
    chip = gpiod_chip_new(driver, "gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        gpiod_driver_close(driver);
        exit(1);
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Configure trigger line
    gpiod_line_request_output(trigger_line, "active-high");
    if (!gpiod_line_direction(trigger_line, GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to set trigger line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Configure echo line
    gpiod_line_request_input(echo_line, "both");
    if (!gpiod_line_direction(echo_line, GPIOD_LINE_DIRECTION_IN)) {
        fprintf(stderr, "Failed to set echo line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Configure buzzer line
    gpiod_line_request_output(buzzer_line, "active-high");
    if (!gpiod_line_direction(buzzer_line, GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to set buzzer line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Main loop
    while (1) {
        double distance = measure_distance();
        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpiod_line_set_value(buzzer_line, BUZZER_LEVEL);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(MEASUREMENT_INTERVAL_S * 1000000);
    }

    return 0;
}

