    struct gpiod_line *trigger_line, *echo_line, *buzzer_line;

    // Initialize driver library
    driver = gpiod_driver_new();
    if (!driver) {
        fprintf(stderr, "Failed to initialize driver library\n");
        exit(1);
    }

    // Open chip
    chip = gpiod_chip_new(driver, "gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        gpiod_driver_close(driver);
        exit(1);
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Configure trigger line
    gpiod_line_request_output(trigger_line, "active-high");
    if (!gpiod_line_direction(trigger_line, GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to set trigger line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Configure echo line
    gpiod_line_request_input(echo_line, "both");
    if (!gpiod_line_direction(echo_line, GPIOD_LINE_DIRECTION_IN)) {
        fprintf(stderr, "Failed to set echo line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Configure buzzer line
    gpiod_line_request_output(buzzer_line, "active-high");
    if (!gpiod_line_direction(buzzer_line, GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to set buzzer line direction\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpiod_driver_close(driver);
        exit(1);
    }

    // Main loop
    while (1) {
        double distance = measure_distance();
        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpiod_line_set_value(buzzer_line, BUZZER_LEVEL);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(MEASUREMENT_INTERVAL_S * 1000000);
    }

    return 0;
}
