#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 20
#define PULSE_0 500
#define PULSE_90 1500
#define PULSE_180 2500
#define UPDATE_INTERVAL 100000 // 100ms

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
    gpioTerminate();
    exit(0);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for trigger pin\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for echo pin\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for servo pin\n");
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, sigint_handler);
}

void cleanup_gpio() {
    gpioTerminate();
}

void measure_distance() {
    int distance = -1.0;

    gpioWrite(TRIGGER_PIN, 1);
    usleep(10);
    gpioWrite(TRIGGER_PIN, 0);

    int start_time = gpioGetTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTickDiff(start_time) > 1000000) {
            return;
        }
    }

    int end_time = gpioGetTick();
    distance = (gpioTickDiff(start_time) * 34300) / 2;

    if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    } else if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    }

    return distance;
}

void update_servo(int distance) {
    int pulse = (PULSE_0 + (PULSE_90 - PULSE_0) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE));
    gpioPwm(SERVO_PIN, pulse, 20);
}

int main() {
    setup_gpio();

    while (running) {
        int distance = measure_distance();
        if (distance == -1.0) {
            printf("Error measuring distance\n");
            continue;
        }

        update_servo(distance);
        printf("Distance: %d cm, Servo angle: %d°\n", distance, (int)((PULSE_0 + (PULSE_90 - PULSE_0) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE)) / 10));

        usleep(UPDATE_INTERVAL);
    }

    cleanup_gpio();
    return 0;
}

