#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define MODEL_ID_REG 0x0D
#define DISTANCE_REG 0x04
#define TIMING_BUDGET_REG 0x01
#define GATE_PIN 18
#define GATE_OPEN_WIDTH 1000
#define GATE_CLOSE_WIDTH 2000
#define HYSTERESIS 50
#define LOG_FILE "gate_log.txt"

int i2c_handle;
int gpio_handle;
FILE *log_file;

void i2c_init() {
    if ((i2c_handle = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(i2c_handle, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
    if (write(i2c_handle, &value, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void i2c_read(uint8_t reg, uint8_t *value) {
    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(i2c_handle, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
    if (read(i2c_handle, value, 1) != 1) {
        perror("Failed to read from I2C register");
        exit(1);
    }
}

void gpio_init() {
    if ((gpio_handle = gpioInitialise()) < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }
    if (gpioSetMode(gpio_handle, GATE_PIN, PI_PWM) < 0) {
        perror("Failed to set GPIO mode");
        exit(1);
    }
}

void gpio_set_pulse_width(int width) {
    if (gpioHardwarePWM(gpio_handle, GATE_PIN, width) < 0) {
        perror("Failed to set PWM");
        exit(1);
    }
}

void log_event(int event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld %d\n", tv.tv_sec, tv.tv_usec, event);
    fflush(log_file);
}

int main() {
    i2c_init();
    gpio_init();
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    // Verify model ID
    uint8_t model_id;
    i2c_read(MODEL_ID_REG, &model_id);
    if (model_id != 0x00) {
        fprintf(stderr, "Invalid model ID 0x%02x\n", model_id);
        exit(1);
    }

    // Program timing budget
    i2c_write(TIMING_BUDGET_REG, 0x0A);

    // Start ranging
    i2c_write(0x00, 0x01);

    while (1) {
        uint16_t distance;
        i2c_read(DISTANCE_REG, (uint8_t *)&distance);
        int gate_width = (distance > 250) ? GATE_OPEN_WIDTH : GATE_CLOSE_WIDTH;
        if (gate_width != gpioGetPWM(gpio_handle, GATE_PIN)) {
            gpio_set_pulse_width(gate_width);
            log_event(gate_width > GATE_OPEN_WIDTH ? 1 : -1);
        }
        usleep(10000);
    }

    gpioTerminate(gpio_handle);
    close(i2c_handle);
    fclose(log_file);
    return 0;
}

