#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SERVO 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TIMEOUT_US 50000
#define DELAY_US 100000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    gpioServoWrite(GPIO_SERVO, SERVO_MIN);
    gpioTerminate();
    exit(0);
}

int main() {
    int gpio_fd;
    int ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO driver
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up servo API
    if ((ret = gpioServoInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize servo API\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Generate 10us trigger pulse
        gpioPulse(GPIO_TRIGGER, 10, 1);

        // Wait for rising edge
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t start = tv.tv_sec * 1000000 + tv.tv_usec;
        while (gpioRead(GPIO_ECHO) == 0 && (tv.tv_sec * 1000000 + tv.tv_usec - start) < TIMEOUT_US) {
            gettimeofday(&tv, NULL);
        }
        if (tv.tv_sec * 1000000 + tv.tv_usec - start >= TIMEOUT_US) {
            printf("Timeout on rising edge\n");
            printf("Distance: -1.0, Angle: -1.0\n");
            continue;
        }

        // Wait for falling edge
        gettimeofday(&tv, NULL);
        uint64_t end = tv.tv_sec * 1000000 + tv.tv_usec;
        while (gpioRead(GPIO_ECHO) == 1 && (tv.tv_sec * 1000000 + tv.tv_usec - end) < TIMEOUT_US) {
            gettimeofday(&tv, NULL);
        }
        if (tv.tv_sec * 1000000 + tv.tv_usec - end >= TIMEOUT_US) {
            printf("Timeout on falling edge\n");
            printf("Distance: -1.0, Angle: -1.0\n");
            continue;
        }

        // Calculate distance
        uint64_t duration = tv.tv_sec * 1000000 + tv.tv_usec - end;
        double distance = (duration * 0.5 * 34300) / 2;

        // Map distance to angle
        double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX - SERVO_MIN) + SERVO_MIN;
        if (distance < MIN_DISTANCE) {
            angle = SERVO_MIN;
        } else if (distance > MAX_DISTANCE) {
            angle = SERVO_MAX;
        } else if (angle < SERVO_MIN) {
            angle = SERVO_MIN;
        } else if (angle > SERVO_MAX) {
            angle = SERVO_MAX;
        }

        // Print distance and angle
        printf("Distance: %.1f cm, Angle: %.1f°\n", distance, angle);

        // Set servo angle
        if ((ret = gpioServoWrite(GPIO_SERVO, (int)angle)) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            gpioTerminate();
            return 1;
        }

        // Pause before next measurement
        usleep(DELAY_US);
    }

    // Clean up
    cleanup();
    return 0;
}

