#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and device addresses
#define I2C_BUS 1
#define SHT40_ADDRESS 0x44

// Define the CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

// Define the signal handlers
void sigint_handler(int sig) {
    // Close the I2C handle and terminate the driver library
    if (i2c_close(i2c_fd) == -1) {
        perror("i2c_close");
    }
    exit(0);
}

void sigterm_handler(int sig) {
    // Close the I2C handle and terminate the driver library
    if (i2c_close(i2c_fd) == -1) {
        perror("i2c_close");
    }
    exit(0);
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(uint8_t *data, size_t len, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Open the I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd == -1) {
        perror("i2c_open");
        exit(1);
    }

    // Set the I2C bus to 100 kHz
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) == -1) {
        perror("ioctl");
        exit(1);
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Main loop
    while (1) {
        // Trigger a high-repeatability measurement
        uint8_t cmd[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        if (write(i2c_fd, cmd, 6) != 6) {
            perror("write");
            // Re-open the I2C bus
            close(i2c_fd);
            i2c_fd = open(i2c_dev_path, O_RDWR);
            if (i2c_fd == -1) {
                perror("i2c_open");
                exit(1);
            }
            ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS);
            continue;
        }

        // Wait at least 10 ms
        usleep(10000);

        // Read the response
        uint8_t response[6];
        if (read(i2c_fd, response, 6) != 6) {
            perror("read");
            // Re-open the I2C bus
            close(i2c_fd);
            i2c_fd = open(i2c_dev_path, O_RDWR);
            if (i2c_fd == -1) {
                perror("i2c_open");
                exit(1);
            }
            ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS);
            continue;
        }

        // Validate the CRC-8 checksums
        uint8_t temp_crc = crc8(response, 2, CRC_INIT);
        uint8_t hum_crc = crc8(response + 3, 2, CRC_INIT);
        if (temp_crc != response[2] || hum_crc != response[5]) {
            fprintf(stderr, "CRC failure\n");
            // Re-open the I2C bus
            close(i2c_fd);
            i2c_fd = open(i2c_dev_path, O_RDWR);
            if (i2c_fd == -1) {
                perror("i2c_open");
                exit(1);
            }
            ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS);
            continue;
        }

        // Extract the temperature and humidity values
        int16_t temp = (response[0] << 8) | response[1];
        int16_t hum = (response[3] << 8) | response[4];

        // Log the readings
        printf("Temperature: %d.%02d°C, Humidity: %d.%02d%%\n",
               temp / 100, temp % 100, hum / 100, hum % 100);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the I2C handle and terminate the driver library
    if (i2c_close(i2c_fd) == -1) {
        perror("i2c_close");
    }
    return 0;
}

