#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define FILE_NAME "enclosure_temp_log.txt"
#define ERROR_FILE "error_log.txt"
#define TEMPERATURE_FILE "/sys/bus/i2c/devices/i2c-1/i2c-1:00/iio:device0/in_temp1_input"
#define TEMPERATURE_SCALE 1000.0
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

// Function to handle signal termination
void sigint_handler(int sig) {
    // Release I2C bus
    i2c_close(I2C_BUS);
    // Close log files
    fclose(flog);
    fclose(ferror);
    // Exit with status code 0
    exit(0);
}

int main() {
    // Open log files
    FILE *flog = fopen(FILE_NAME, "a");
    if (flog == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", FILE_NAME, strerror(errno));
        return 1;
    }

    FILE *ferror = fopen(ERROR_FILE, "a");
    if (ferror == NULL) {
        fprintf(stderr, "Failed to open error log file '%s': %s\n", ERROR_FILE, strerror(errno));
        fclose(flog);
        return 1;
    }

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(ferror, "Failed to initialize GPIO library: %s\n", strerror(errno));
        fclose(flog);
        fclose(ferror);
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(ferror, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        fclose(flog);
        fclose(ferror);
        return 1;
    }

    // Set up signal handler for termination
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(ferror, "Failed to set up signal handler: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        fclose(flog);
        fclose(ferror);
        return 1;
    }

    // Set up I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(ferror, "Failed to set I2C address: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        fclose(flog);
        fclose(ferror);
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature from file
        FILE *f = fopen(TEMPERATURE_FILE, "r");
        if (f == NULL) {
            fprintf(ferror, "Failed to open temperature file: %s\n", strerror(errno));
            break;
        }

        char buffer[32];
        if (fgets(buffer, sizeof(buffer), f) == NULL) {
            fprintf(ferror, "Failed to read temperature: %s\n", strerror(errno));
            fclose(f);
            break;
        }

        float temperature = atof(buffer);
        temperature /= TEMPERATURE_SCALE;

        // Log temperature
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(flog, "%s: %.2f°C\n", timestamp, temperature);

        // Close temperature file
        fclose(f);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Release I2C bus
    i2cClose(i2c_fd);

    // Close log files
    fclose(flog);
    fclose(ferror);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

