// Sensirion SHT40 I2C address
#define SHT40_ADDRESS 0x44

// Sensirion SHT40 CRC-8 polynomial and initial value
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xC2

// Sensirion SHT40 high-repeatability measurement command
#define SHT40_MEAS_HIGH_REPEATABILITY 0x00

// Sensirion SHT40 measurement result structure
typedef struct {
    uint16_t temperature_msb;
    uint16_t temperature_lsb;
    uint8_t temperature_crc;
    uint16_t humidity_msb;
    uint16_t humidity_lsb;
    uint8_t humidity_crc;
} sht40_measurement_t;

// Function to calculate Sensirion CRC-8
uint8_t sht40_crc8(uint8_t data, uint8_t crc) {
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
        } else {
            crc = crc << 1;
        }
        crc &= 0xFF;
    }
    return crc;
}

// Function to validate Sensirion CRC-8
bool sht40_validate_crc(uint8_t data, uint8_t crc) {
    return crc == sht40_crc8(data, SHT40_CRC_INIT);
}

// Function to read a byte from the SHT40 sensor
uint8_t sht40_read_byte(int i2c_fd) {
    uint8_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("ioctl");
        return 0;
    }
    if (write(i2c_fd, &SHT40_MEAS_HIGH_REPEATABILITY, 1) != 1) {
        perror("write");
        return 0;
    }
    usleep(10000);
    if (read(i2c_fd, &data, 1) != 1) {
        perror("read");
        return 0;
    }
    return data;
}

// Function to read a 16-bit word from the SHT40 sensor
uint16_t sht40_read_word(int i2c_fd) {
    uint16_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("ioctl");
        return 0;
    }
    if (write(i2c_fd, &SHT40_MEAS_HIGH_REPEATABILITY, 1) != 1) {
        perror("write");
        return 0;
    }
    usleep(10000);
    if (read(i2c_fd, &data, 2) != 2) {
        perror("read");
        return 0;
    }
    return data;
}

// Function to read a measurement from the SHT40 sensor
sht40_measurement_t sht40_read_measurement(int i2c_fd) {
    sht40_measurement_t measurement;
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("ioctl");
        return (sht40_measurement_t){};
    }
    if (write(i2c_fd, &SHT40_MEAS_HIGH_REPEATABILITY, 1) != 1) {
        perror("write");
        return (sht40_measurement_t){};
    }
    usleep(10000);
    if (read(i2c_fd, &measurement.temperature_msb, 2) != 2) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (read(i2c_fd, &measurement.temperature_lsb, 2) != 2) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (read(i2c_fd, &measurement.temperature_crc, 1) != 1) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (read(i2c_fd, &measurement.humidity_msb, 2) != 2) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (read(i2c_fd, &measurement.humidity_lsb, 2) != 2) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (read(i2c_fd, &measurement.humidity_crc, 1) != 1) {
        perror("read");
        return (sht40_measurement_t){};
    }
    if (!sht40_validate_crc(measurement.temperature_msb, measurement.temperature_crc) ||
        !sht40_validate_crc(measurement.temperature_lsb, measurement.temperature_crc) ||
        !sht40_validate_crc(measurement.humidity_msb, measurement.humidity_crc) ||
        !sht40_validate_crc(measurement.humidity_lsb, measurement.humidity_crc)) {
        return (sht40_measurement_t){};
    }
    return measurement;
}

// Function to log a measurement to a file
void sht40_log_measurement(sht40_measurement_t measurement, FILE *log_file) {
    fprintf(log_file, "%lu %d.%02d %d.%02d\n",
            time(NULL), measurement.temperature_msb, measurement.temperature_lsb, measurement.humidity_msb, measurement.humidity_lsb);
}

// Signal handler for SIGINT and SIGTERM
void sht40_signal_handler(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_fd;
    FILE *log_file;

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Open the log file
    log_file = fopen("sht40_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sht40_signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        sht40_measurement_t measurement = sht40_read_measurement(i2c_fd);
        if (measurement.temperature_msb) {
            sht40_log_measurement(measurement, log_file);
        }
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    return 0;
}

