#define I2C_BUS 1
#define I2C_ADDRESS 0x57
#define MEASUREMENT_COMMAND 0x00
#define MEASUREMENT_RESPONSE_SIZE 6
#define MAX_RETRIES 3
#define BACKOFF_FACTOR 1000000 // 1ms
#define SAMPLING_INTERVAL 100000 // 100ms

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int i2c_read(int fd, uint8_t *buf, int size) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
            if (errno == EAGAIN) {
                usleep(BACKOFF_FACTOR * retries);
                retries++;
                continue;
            }
            perror("ioctl");
            return -1;
        }
        if (i2c_smbus_read_byte_data(fd, MEASUREMENT_COMMAND, buf) == -1) {
            if (errno == EAGAIN) {
                usleep(BACKOFF_FACTOR * retries);
                retries++;
                continue;
            }
            perror("i2c_smbus_read_byte_data");
            return -1;
        }
        if (i2c_smbus_read_i2c_block_data(fd, MEASUREMENT_COMMAND, size, buf) == -1) {
            if (errno == EAGAIN) {
                usleep(BACKOFF_FACTOR * retries);
                retries++;
                continue;
            }
            perror("i2c_smbus_read_i2c_block_data");
            return -1;
        }
        return 0;
    }
    return -1;
}

int main() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        return 1;
    }

    char filename[] = "airflow.log";
    int log_fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        close(fd);
        return 1;
    }

    while (!stop) {
        uint8_t response[MEASUREMENT_RESPONSE_SIZE];
        if (i2c_read(fd, response, MEASUREMENT_RESPONSE_SIZE) == -1) {
            continue;
        }
        uint16_t pressure = (response[0] << 8) | response[1];
        uint16_t temperature = (response[3] << 8) | response[4];
        uint8_t crc = response[2] ^ response[5];
        for (int i = 0; i < MEASUREMENT_RESPONSE_SIZE - 2; i++) {
            crc ^= response[i];
        }
        if (crc != 0) {
            continue;
        }
        double pressure_pa = (double)pressure / 32768.0;
        double temperature_c = (double)temperature / 128.0 - 40.0;
        char timestamp[32];
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        char buffer[128];
        sprintf(buffer, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        if (write(log_fd, buffer, strlen(buffer)) == -1) {
            perror("write");
            break;
        }
        if (fsync(log_fd) == -1) {
            perror("fsync");
            break;
        }
        usleep(SAMPLING_INTERVAL);
    }

    close(log_fd);
    close(fd);
    pigpio_cleanup();
    return 0;
}

