#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define COMMAND_TEMP 0x00
#define COMMAND_HUMIDITY 0x01
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_close(I2C_BUS);
    gpiod_exit();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize the gpiod library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod library: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = gpiod_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("sensor_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        gpiod_close(i2c_fd);
        gpiod_exit();
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Write command to sensor
        uint8_t command = COMMAND_TEMP;
        if (gpiod_i2c_write(i2c_fd, I2C_ADDRESS, &command, 1) < 0) {
            fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
            gpiod_close(i2c_fd);
            gpiod_exit();
            fclose(log_file);
            return 1;
        }

        // Poll for measurement ready
        uint8_t status;
        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = 20000;
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(i2c_fd, &read_fds);
        if (select(i2c_fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Failed to poll for measurement ready: %s\n", strerror(errno));
            gpiod_close(i2c_fd);
            gpiod_exit();
            fclose(log_file);
            return 1;
        }

        // Read status byte
        if (gpiod_i2c_read(i2c_fd, I2C_ADDRESS, &status, 1) < 0) {
            fprintf(stderr, "Failed to read status byte: %s\n", strerror(errno));
            gpiod_close(i2c_fd);
            gpiod_exit();
            fclose(log_file);
            return 1;
        }

        // Check if measurement is ready
        if (status & 0x80) {
            // Read measurement bytes
            uint16_t measurement;
            if (gpiod_i2c_read(i2c_fd, I2C_ADDRESS, (uint8_t *)&measurement, 2) < 0) {
                fprintf(stderr, "Failed to read measurement bytes: %s\n", strerror(errno));
                gpiod_close(i2c_fd);
                gpiod_exit();
                fclose(log_file);
                return 1;
            }

            // Log and print measurement
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%lu.%06lu %d.%02d\n", tv.tv_sec, tv.tv_usec, measurement >> 8, measurement & 0xFF);
            fprintf(stderr, "%lu.%06lu %d.%02d\n", tv.tv_sec, tv.tv_usec, measurement >> 8, measurement & 0xFF);

            // Wait for next sample
            usleep(SAMPLE_INTERVAL);
        } else {
            // If measurement is not ready, retry
            continue;
        }
    }

    // Clean up
    gpiod_close(i2c_fd);
    gpiod_exit();
    fclose(log_file);
    return 0;
}

