#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_ADDRESS 0x70
#define MEASUREMENT_TRIGGER 0x00
#define PRESSURE_VALUE 0x01
#define TEMPERATURE_VALUE 0x02
#define SCALE_FACTOR_VALUE 0x03
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define FILE_NAME "airflow_data.txt"

int fd;
bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void crc8(uint8_t* data, uint8_t len, uint8_t* crc) {
    uint8_t i, j;
    *crc = CRC8_INIT;
    for (i = 0; i < len; i++) {
        *crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = ((*crc << 1) ^ CRC8_POLYNOMIAL);
            } else {
                *crc <<= 1;
            }
        }
    }
}

int main() {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_msg;
    uint8_t data[9];
    uint8_t crc;
    char timestamp[20];
    FILE* file;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    file = fopen(FILE_NAME, "a+");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Write the header row
    fprintf(file, "timestamp,pressure,power\n");

    // Register the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        // Trigger a measurement
        msg.buf = &MEASUREMENT_TRIGGER;
        msg.len = 1;
        msg.flags = 0;
        i2c_msg.msg = &msg;
        i2c_msg.nmsgs = 1;
        i2c_msg.nbytes = 1;
        if (ioctl(fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to trigger measurement");
            break;
        }

        // Wait for 45ms
        usleep(45000);

        // Read the data
        msg.buf = data;
        msg.len = 9;
        msg.flags = 0;
        i2c_msg.msg = &msg;
        i2c_msg.nmsgs = 1;
        i2c_msg.nbytes = 9;
        if (ioctl(fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to read data");
            break;
        }

        // Validate the CRCs
        crc = data[8];
        crc8(data, 7, &crc);
        if (crc != data[8]) {
            fprintf(stderr, "Invalid CRC for pressure value\n");
            break;
        }
        crc = data[7];
        crc8(data + 3, 4, &crc);
        if (crc != data[7]) {
            fprintf(stderr, "Invalid CRC for temperature value\n");
            break;
        }
        crc = data[5];
        crc8(data + 6, 3, &crc);
        if (crc != data[5]) {
            fprintf(stderr, "Invalid CRC for scale factor value\n");
            break;
        }

        // Log the data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(file, "%s,%d.%03d,%d\n", timestamp, (int)data[0] << 8 | data[1], (int)data[2], (int)data[3] << 8 | data[4]);

        // Wait for 100ms
        usleep(100000);
    }

    // Close the I2C device
    close(fd);

    // Close the log file
    fclose(file);

    return 0;
}

