    running = false;
}

void crc8(uint8_t* data, uint8_t len, uint8_t* crc) {
    uint8_t i, j;
    *crc = CRC8_INIT;
    for (i = 0; i < len; i++) {
        *crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = ((*crc << 1) ^ CRC8_POLYNOMIAL);
            } else {
                *crc <<= 1;
            }
        }
    }
}

