        i2c_msg.nmsgs = 1;
        i2c_msg.nbytes = 9;
        if (ioctl(fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to read data");
            break;
        }

        // Validate the CRCs
        crc = data[8];
        crc8(data, 7, &crc);
        if (crc != data[8]) {
            fprintf(stderr, "Invalid CRC for pressure value\n");
            break;
        }
        crc = data[7];
        crc8(data + 3, 4, &crc);
        if (crc != data[7]) {
            fprintf(stderr, "Invalid CRC for temperature value\n");
            break;
        }
        crc = data[5];
        crc8(data + 6, 3, &crc);
        if (crc != data[5]) {
            fprintf(stderr, "Invalid CRC for scale factor value\n");
            break;
        }

        // Log the data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(file, "%s,%d.%03d,%d\n", timestamp, (int)data[0] << 8 | data[1], (int)data[2], (int)data[3] << 8 | data[4]);

        // Wait for 100ms
        usleep(100000);
    }

