int main() {
    struct i2c_adapter *adapter;
    struct i2c_msg msg;
    char buffer[3];
    int fd;
    FILE *log_file = fopen(LOG_FILE, "a");
    FILE *error_file = fopen(ERROR_FILE, "a");
    struct itimerspec timer;
    struct sigaction sa;
    int ret;

    if (log_file == NULL || error_file == NULL) {
