        return 1;
    }

    adapter = i2c_get_adapter(I2C_BUS);
    if (adapter == NULL) {
        fprintf(error_file, "%s: Failed to get I2C adapter\n", ctime(&time(NULL)));
        return 1;
    }

    fd = i2c_open(adapter, I2C_ADDRESS);
    if (fd == -1) {
        fprintf(error_file, "%s: Failed to open I2C device\n", ctime(&time(NULL)));
        i2c_put_adapter(adapter);
        return 1;
    }

    while (1) {
        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.len = 1;
        msg.buf = &MEASUREMENT_COMMAND;
        ret = i2c_smbus_write_byte(fd, &msg);
        if (ret < 0) {
            fprintf(error_file, "%s: Failed to write to I2C device\n", ctime(&time(NULL)));
            i2c_close(fd);
            i2c_put_adapter(adapter);
            return 1;
        }

        usleep(15000);

        msg.addr = I2C_ADDRESS;
        msg.flags = I2C_M_RD;
        msg.len = 3;
        msg.buf = buffer;
        ret = i2c_smbus_read_i2c_msg(fd, &msg);
        if (ret < 0) {
            fprintf(error_file, "%s: Failed to read from I2C device\n", ctime(&time(NULL)));
            i2c_close(fd);
            i2c_put_adapter(adapter);
            return 1;
        }

        uint8_t crc = 0;
        for (int i = 0; i < 2; i++) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLYNOMIAL : 0);
            crc ^= buffer[i];
        }
        crc ^= CRC_INIT;
        if (crc != buffer[2]) {
            fprintf(error_file, "%s: CRC mismatch\n", ctime(&time(NULL)));
            continue;
        }

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&time(NULL)));
        fprintf(log_file, "%s %.2f\n", timestamp, (buffer[0] << 8 | buffer[1]) / 16.0);
        fflush(log_file);
    }

    i2c_close(fd);
    i2c_put_adapter(adapter);
    fclose(log_file);
    fclose(error_file);
    return 0;
