uint8_t sht40_crc8(uint8_t data, uint8_t crc) {
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
        } else {
            crc = crc << 1;
        }
        crc &= 0xFF;
    }
    return crc;
}

// Function to validate CRC-8
bool sht40_validate_crc(uint8_t data, uint8_t crc) {
    uint8_t calculated_crc = sht40_crc8(data, SHT40_CRC_INIT);
    return calculated_crc == crc;
}

