    if (ioctl(sht40_i2c_fd, I2C_SLAVE, SHT40_I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Open log file
    sht40_log_file = fopen("sht40_log.txt", "a");
    if (sht40_log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
