// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x70

// Define the command for continuous measurement
#define CONTINUOUS_MEASUREMENT 0x00

// Define the polynomial for CRC-8 calculation
#define CRC_POLYNOMIAL 0x1D

// Define the initial value for CRC-8 calculation
#define CRC_INITIAL_VALUE 0x00

// Function to calculate CRC-8
uint8_t crc8(uint8_t data, uint8_t crc) {
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x80) && (data & 0x01)) {
            crc = (crc << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc = crc << 1;
        }
        data >>= 1;
    }
    return crc;
}

// Function to read data from the sensor
int read_data(int file, uint8_t *data) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    uint8_t buffer[6];

    // Write the command for continuous measurement
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = &CONTINUOUS_MEASUREMENT;
    if (ioctl(file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }
    if (i2c_smbus_write_byte(file, CONTINUOUS_MEASUREMENT) < 0) {
        perror("i2c_smbus_write_byte");
        return -1;
    }

    // Read the response from the sensor
    msgs->addr = I2C_ADDRESS;
    msgs->flags = I2C_M_RD;
    msgs->len = 6;
    msgs->buf = buffer;
    if (i2c_smbus_xfer(file, msgs, 1, NULL, 0) < 0) {
        perror("i2c_smbus_xfer");
        return -1;
    }

    // Validate the CRC-8 checks
    uint8_t crc = crc8(buffer[4], buffer[5]);
    if (crc != buffer[5]) {
        fprintf(stderr, "Invalid CRC-8 for pressure\n");
        return -1;
    }
    crc = crc8(buffer[2], buffer[3]);
    if (crc != buffer[3]) {
        fprintf(stderr, "Invalid CRC-8 for temperature\n");
        return -1;
    }

    // Copy the valid data to the output buffer
    memcpy(data, buffer, 6);
    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(uint8_t *data) {
    uint16_t pressure = (data[0] << 8) | data[1];
    uint16_t temperature = (data[2] << 8) | data[3];
    double pressure_pa = (pressure * 500.0) / 32768.0;
    double temperature_c = (temperature * 175.72) / 65536.0 - 46.85;
    printf("%f,%f,%f\n", data[0], pressure_pa, temperature_c);
}

// Function to handle SIGINT
void sigint_handler(int sig) {
    close(0);
    close(1);
    exit(0);
}

