#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define FAN_GPIO 18
#define CIRCULAR_BUFFER_SIZE 60
#define TEMPERATURE_REGISTER 0xE3
#define HUMIDITY_REGISTER 0xE5
#define FAN_HYSTERESIS 1.0
#define FAN_ON_TEMPERATURE 28.0
#define FAN_OFF_TEMPERATURE 27.0

#define I2C_RETRY_COUNT 3

int i2c_fd = -1;
int fan_state = 0;
int circular_buffer_index = 0;
int circular_buffer[CIRCULAR_BUFFER_SIZE][2];
struct timeval last_read_time;

void sigint_handler(int sig) {
    gpioWrite(FAN_GPIO, 0);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    call();
    exit(0);
}

int i2c_read_byte(uint8_t reg) {
    int retry_count = 0;
    while (retry_count < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl");
            return -1;
        }
        uint8_t data;
        if (i2c_smbus_read_byte_data(i2c_fd, reg, &data) < 0) {
            perror("i2c_smbus_read_byte_data");
            retry_count++;
            usleep(100000);
        } else {
            return data;
        }
    }
    return -1;
}

int i2c_read_word(uint8_t reg) {
    int retry_count = 0;
    while (retry_count < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl");
            return -1;
        }
        uint16_t data;
        if (i2c_smbus_read_word_data(i2c_fd, reg, &data) < 0) {
            perror("i2c_smbus_read_word_data");
            retry_count++;
            usleep(100000);
        } else {
            return data;
        }
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    if (i2c_read_byte(0x00) != 0x40) {
        printf("Sensor not present\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        if (circular_buffer_index == CIRCULAR_BUFFER_SIZE) {
            circular_buffer_index = 0;
        }
        circular_buffer[circular_buffer_index][0] = current_time.tv_sec;
        circular_buffer[circular_buffer_index][1] = i2c_read_word(TEMPERATURE_REGISTER) / 128.0;
        circular_buffer_index++;

        if (circular_buffer[circular_buffer_index % CIRCULAR_BUFFER_SIZE][1] > FAN_ON_TEMPERATURE + FAN_HYSTERESIS) {
            if (gpioRead(FAN_GPIO) == 0) {
                gpioWrite(FAN_GPIO, 1);
            }
        } else if (circular_buffer[circular_buffer_index % CIRCULAR_BUFFER_SIZE][1] < FAN_OFF_TEMPERATURE - FAN_HYSTERESIS && fan_state == 1) {
            gpioWrite(FAN_GPIO, 0);
            fan_state = 0;
        }

        if (circular_buffer_index % 2 == 0) {
            printf("%ld %f\n", circular_buffer[circular_buffer_index % CIRCULAR_BUFFER_SIZE][0], circular_buffer[circular_buffer_index % CIRCULAR_BUFFER_SIZE][1]);
        }

        gettimeofday(&last_read_time, NULL);
        usleep(2000000);
    }

    close(i2c_fd);
    gpioTerminate();
    return 0;
}

