#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SCD40_ADDRESS 0x61
#define SCD40_MEASUREMENT_COMMAND 0x02
#define SCD40_STOP_MEASUREMENT_COMMAND 0x04
#define SCD40_DATA_READY_FLAG 0x01
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0x00
#define SCD40_DATA_LENGTH 9
#define SCD40_CO2_OFFSET 0x00
#define SCD40_TEMPERATURE_OFFSET 0x02
#define SCD40_HUMIDITY_OFFSET 0x04

#define LOG_FILE "air_quality.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int ret;
    uint8_t data[SCD40_DATA_LENGTH];
    uint8_t crc;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    struct i2c_msg msg;
    struct i2c_msg *msgs = NULL;
    struct i2c_rdwr_ioctl_data i2c_rdwr;
    struct i2c_smbus_data smbus_data;
    struct stat sb;
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    if (stat(LOG_FILE, &sb) == 0 && S_ISREG(sb.st_mode)) {
        unlink(LOG_FILE);
    }
    if ((ret = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I²C driver
    if ((ret = gpioInitialise()) == -1) {
        fprintf(stderr, "Failed to initialize I²C driver: %s\n", strerror(errno));
        close(ret);
        return 1;
    }

    // Open I²C bus 1
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "Failed to open I²C bus 1: %s\n", strerror(errno));
        gpioTerminate();
        close(ret);
        return 1;
    }

    // Set I²C bus speed to 100 kHz
    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDRESS) == -1) {
        fprintf(stderr, "Failed to set I²C bus speed: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        close(ret);
        return 1;
    }

    // Start periodic measurement
    msg.addr = SCD40_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &SCD40_MEASUREMENT_COMMAND;
    msgs = &msg;
    i2c_rdwr.msgs = msgs;
    i2c_rdwr.nmsgs = 1;
    i2c_rdwr.msgs[0].len = 1;
    if ((ret = ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr)) == -1) {
        fprintf(stderr, "Failed to start periodic measurement: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        close(ret);
        return 1;
    }

    // Wait at least one second before the first read
    sleep(1);

    while (running) {
        // Check data-ready flag
        msg.addr = SCD40_ADDRESS;
        msg.flags = 0;
        msg.len = 1;
        msg.buf = &SCD40_DATA_READY_FLAG;
        msgs = &msg;
        i2c_rdwr.msgs = msgs;
        i2c_rdwr.nmsgs = 1;
        i2c_rdwr.msgs[0].len = 1;
        if ((ret = ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr)) == -1) {
            fprintf(stderr, "Failed to check data-ready flag: %s\n", strerror(errno));
            close(i2c_fd);
            gpioTerminate();
            close(ret);
            return 1;
        }
        if (msg.buf[0] == 0) {
            sleep(1);
            continue;
        }

        // Read data
        msg.addr = SCD40_ADDRESS;
        msg.flags = 0;
        msg.len = SCD40_DATA_LENGTH;
        msg.buf = data;
        msgs = &msg;
        i2c_rdwr.msgs = msgs;
        i2c_rdwr.nmsgs = 1;
        i2c_rdwr.msgs[0].len = SCD40_DATA_LENGTH;
        if ((ret = ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr)) == -1) {
            fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
            close(i2c_fd);
            gpioTerminate();
            close(ret);
            return 1;
        }

        // Verify CRC
        crc = 0;
        for (int i = 0; i < SCD40_DATA_LENGTH - 3; i++) {
            crc = (crc << 1) ^ (crc & 0x80 ? SCD40_CRC_POLYNOMIAL : 0);
            crc ^= data[i];
        }
        if (crc != data[SCD40_DATA_LENGTH - 2] || data[SCD40_DATA_LENGTH - 1] != SCD40_CRC_INIT) {
            fprintf(stderr, "Invalid CRC\n");
            close(i2c_fd);
            gpioTerminate();
            close(ret);
            return 1;
        }

        // Extract data
        co2 = (data[SCD40_CO2_OFFSET] << 8) | data[SCD40_CO2_OFFSET + 1];
        temperature = (data[SCD40_TEMPERATURE_OFFSET] << 8) | data[SCD40_TEMPERATURE_OFFSET + 1];
        humidity = (data[SCD40_HUMIDITY_OFFSET] << 8) | data[SCD40_HUMIDITY_OFFSET + 1];

        // Append log entry
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(ret, "%s,%.2f,%.2f,%.2f\n", timestamp, co2 / 100.0, temperature / 100.0, humidity / 100.0);
        fflush(ret);

        // Wait five seconds before next read
        sleep(5);
    }

    // Stop periodic measurement
    msg.addr = SCD40_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &SCD40_STOP_MEASUREMENT_COMMAND;
    msgs = &msg;
    i2c_rdwr.msgs = msgs;
    i2c_rdwr.nmsgs = 1;
    i2c_rdwr.msgs[0].len = 1;
    if ((ret = ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr)) == -1) {
        fprintf(stderr, "Failed to stop periodic measurement: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        close(ret);
        return 1;
    }

    // Close I²C handle
    close(i2c_fd);

    // Terminate I²C driver
    gpioTerminate();

    // Close log file
    close(ret);

    return 0;
}

