#define SCD40_ADDRESS 0x61
#define CO2_REGISTER 0x00
#define TEMP_REGISTER 0x01
#define HUM_REGISTER 0x02
#define CO2_WARNING_THRESHOLD 1000
#define BUFFER_SIZE 20
#define BUFFER_MASK (BUFFER_SIZE - 1)

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} reading_t;

volatile bool running = true;
volatile bool sensor_initialized = false;
volatile bool i2c_initialized = false;
volatile int i2c_fd = -1;
volatile int gpio_fd = -1;
volatile reading_t buffer[BUFFER_SIZE];
volatile int buffer_head = 0;
volatile int buffer_tail = 0;

void sigint_handler(int sig) {
    running = false;
}

void stop_sensor() {
    if (i2c_initialized) {
        if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDRESS) < 0) {
            perror("ioctl");
        }
        i2c_initialized = false;
    }
    if (gpio_fd != -1) {
        gpioTerminate();
        gpio_fd = -1;
    }
}

void validate_crc8(uint8_t data) {
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = (crc << 1) ^ ((crc & 0x80) ? 0x31 : 0);
        crc &= 0xFF;
        crc ^= data & 1;
        data >>= 1;
    }
    if (crc != 0) {
        fprintf(stderr, "CRC-8 validation failed\n");
    }
}

void read_sensor() {
    if (i2c_initialized) {
        uint8_t data[2];
        if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDRESS) < 0) {
            perror("ioctl");
            return;
        }
        if (i2c_smbus_write_byte_data(i2c_fd, CO2_REGISTER, 0x78) < 0) {
            perror("i2c_smbus_write_byte_data");
            return;
        }
        if (i2c_smbus_read_i2c_block_data(i2c_fd, CO2_REGISTER, 2, data) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            return;
        }
        validate_crc8(data[0]);
        uint16_t co2 = (data[0] << 8) | data[1];
        if (co2 > 0) {
            buffer[buffer_head].co2 = co2;
            buffer_head = (buffer_head + 1) & BUFFER_MASK;
        }

        if (i2c_smbus_write_byte_data(i2c_fd, TEMP_REGISTER, 0x78) < 0) {
            perror("i2c_smbus_write_byte_data");
            return;
        }
        if (i2c_smbus_read_i2c_block_data(i2c_fd, TEMP_REGISTER, 2, data) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            return;
        }
        validate_crc8(data[0]);
        float temperature = (data[0] << 8) | data[1];
        temperature /= 10.0f;
        buffer[buffer_head].temperature = temperature;
        buffer_head = (buffer_head + 1) & BUFFER_MASK;

        if (i2c_smbus_write_byte_data(i2c_fd, HUM_REGISTER, 0x78) < 0) {
            perror("i2c_smbus_write_byte_data");
            return;
        }
        if (i2c_smbus_read_i2c_block_data(i2c_fd, HUM_REGISTER, 2, data) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            return;
        }
        validate_crc8(data[0]);
        uint16_t humidity = (data[0] << 8) | data[1];
        humidity /= 10.0f;
        buffer[buffer_head].humidity = humidity;
        buffer_head = (buffer_head + 1) & BUFFER_MASK;
    }
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        reading_t *reading = &buffer[(buffer_tail + i) & BUFFER_MASK];
        if (reading->co2 > 0) {
            printf("CO2: %d ppm, Temperature: %.2f°C, Humidity: %.2f%%\n", reading->co2, reading->temperature, reading->humidity);
            if (reading->co2 > CO2_WARNING_THRESHOLD) {
                if (gpio_fd == -1) {
                    gpio_fd = gpioInitialise();
                    if (gpio_fd < 0) {
                        perror("gpioInitialise");
                        exit(1);
                    }
                }
                if (gpioSetMode(gpio_fd, 17, PI_OUTPUT) < 0) {
                    perror("gpioSetMode");
                    exit(1);
                }
                if (gpioWrite(gpio_fd, 17, 1) < 0) {
                    perror("gpioWrite");
                    exit(1);
                }
            } else {
                if (gpio_fd != -1) {
                    if (gpioWrite(gpio_fd, 17, 0) < 0) {
                        perror("gpioWrite");
                        exit(1);
                    }
                }
            }
        }
    }
    buffer_tail = (buffer_tail + BUFFER_SIZE) & BUFFER_MASK;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    if ((gpio_fd = open("/dev/mem", O_RDWR)) < 0) {
        perror("open");
        exit(1);
    }

    if (mknod("/dev/i2c-1", S_IFCHR | S_IRUSR | S_IWUSR, 0) < 0) {
        perror("mknod");
        exit(1);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }

    i2c_initialized = true;

    while (running) {
        read_sensor();
        print_buffer();
        usleep(5000000);
    }

    stop_sensor();
    close(i2c_fd);
    close(gpio_fd);
    gpioTerminate();
    return 0;
}

