#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define GPIO_EDGE RISING_EDGE
#define GPIO_TIMEOUT 50000  // 50 ms
#define SAMPLE_INTERVAL 5000000  // 5 s
#define TEMPERATURE_FILE "temperature_log.txt"

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    gpiod_close();
    fclose(log_file);
    exit(0);
}

// Function to read temperature from TMP05 sensor
float read_temperature(gpiod_line *line) {
    uint64_t high_time, low_time, cycle_time;
    int ret;

    // Read high and low pulse widths
    ret = gpiod_line_event_read(line, &high_time, &low_time, &cycle_time, GPIO_TIMEOUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read event: %s", gpiod_error_str(ret));
        return -1.0f;
    }

    // Calculate temperature
    float temperature = (high_time - low_time) / (cycle_time - low_time) * 100.0f;

    return temperature;
}

int main() {
    gpiod_context *ctx;
    gpiod_line *line;
    FILE *log_file;
    int failure_count = 0;
    time_t last_log_time = 0;
    float last_temperature = -1.0f;

    // Initialize logging
    openlog("temperature_reader", LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize GPIO driver
    ctx = gpiod_context_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create GPIO context");
        exit(1);
    }

    // Open GPIO line
    line = gpiod_line_request_by_name(ctx, "gpio4", GPIO_PIN, GPIO_EDGE, 0);
    if (!line) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_context_free(ctx);
        exit(1);
    }

    // Open log file
    log_file = fopen(TEMPERATURE_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_line_release(line);
        gpiod_context_free(ctx);
        exit(1);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read temperature
        float temperature = read_temperature(line);
        if (temperature < 0.0f) {
            failure_count++;
            if (failure_count >= 3) {
                syslog(LOG_ERR, "SENSOR MALFUNCTION");
                break;
            }
            continue;
        }

        // Check temperature range
        if (temperature < -40.0f || temperature > 150.0f) {
            syslog(LOG_ERR, "Invalid temperature reading: %.2f°C", temperature);
            failure_count++;
            if (failure_count >= 3) {
                syslog(LOG_ERR, "SENSOR MALFUNCTION");
                break;
            }
            continue;
        }

        // Log temperature
        time_t now = time(NULL);
        if (difftime(now, last_log_time) >= 0) {
            fprintf(log_file, "%s %.2f°C\n", ctime(&now), temperature);
            last_log_time = now;
        }

        // Update last temperature
        last_temperature = temperature;

        // Sleep
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_context_free(ctx);
    fclose(log_file);
    closelog();

    return 0;
}

