            if (errno == EAGAIN) {
                usleep(1000000);
                retry++;
                continue;
            } else {
                fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
                exit(1);
            }
        }

        if (i2c_smbus_write_byte(sht35_fd, SHT35_MEASUREMENT_COMMAND) < 0) {
            if (errno == EAGAIN) {
                usleep(1000000);
                retry++;
                continue;
            } else {
                fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
                exit(1);
            }
        }

        if (i2c_smbus_read_i2c_block_data(sht35_fd, SHT35_TEMP_WORD, 6, data) < 0) {
            if (errno == EAGAIN) {
                usleep(1000000);
                retry++;
                continue;
            } else {
                fprintf(stderr, "Failed to read temperature and humidity data: %s\n", strerror(errno));
                exit(1);
            }
