#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

#define CSV_FILE "airflow.csv"

// Function to calculate CRC-8
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure data to pascals
float pressure_to_pascals(uint16_t raw_pressure) {
    return (float)raw_pressure * 100.0 / 32768.0;
}

// Function to convert raw temperature data to degrees Celsius
float temperature_to_celsius(uint16_t raw_temperature) {
    return (float)raw_temperature * 175.72 / 65536.0 - 46.86;
}

// Function to handle signal interrupts
void signal_handler(int sig) {
    // Close I2C file descriptor
    if (gpio_i2c_close(I2C_BUS) != 0) {
        perror("gpio_i2c_close");
    }

    // Close CSV file handle
    if (fclose(fptr) != 0) {
        perror("fclose");
    }

