int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpio_i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    FILE *fptr = fopen(CSV_FILE, "a");
    if (fptr == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    uint8_t command = MEASUREMENT_COMMAND;
    if (i2c_smbus_write_byte_data(i2c_fd, I2C_ADDRESS, &command) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Wait for conversion time
    usleep(45000);

    // Read pressure data
    uint8_t pressure_data[9];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDRESS, PRESSURE_REGISTER, pressure_data, 9) != 0) {
        fprintf(stderr, "Failed to read pressure data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 of pressure data
    uint8_t pressure_crc = calculate_crc8(pressure_data, 8);
    if (pressure_crc != pressure_data[8]) {
        fprintf(stderr, "Invalid CRC-8 for pressure data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Read temperature data
    if (i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDRESS, TEMPERATURE_REGISTER, pressure_data, 9) != 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 of temperature data
    uint8_t temperature_crc = calculate_crc8(pressure_data, 8);
    if (temperature_crc != pressure_data[8]) {
        fprintf(stderr, "Invalid CRC-8 for temperature data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Read scale factor data
    if (i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDRESS, SCALE_FACTOR_REGISTER, pressure_data, 9) != 0) {
        fprintf(stderr, "Failed to read scale factor data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 of scale factor data
    uint8_t scale_factor_crc = calculate_crc8(pressure_data, 8);
    if (scale_factor_crc != pressure_data[8]) {
        fprintf(stderr, "Invalid CRC-8 for scale factor data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Convert raw data to pressure and temperature
    uint16_t raw_pressure = (pressure_data[0] << 8) | pressure_data[1];
    uint16_t raw_temperature = (pressure_data[2] << 8) | pressure_data[3];
    float pressure = pressure_to_pascals(raw_pressure);
    float temperature = temperature_to_celsius(raw_temperature);

    // Log data to CSV file
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(fptr, "%ld,%f,%f\n", tv.tv_sec, pressure, temperature);

    // Close I2C file descriptor
    if (gpio_i2c_close(I2C_BUS) != 0) {
        perror("gpio_i2c_close");
    }

    // Close CSV file handle
    if (fclose(fptr) != 0) {
        perror("fclose");
    }

    // Exit the program
    return 0;
