    if (scale_factor_crc != pressure_data[8]) {
        fprintf(stderr, "Invalid CRC-8 for scale factor data\n");
        fclose(fptr);
        gpio_i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Convert raw data to pressure and temperature
    uint16_t raw_pressure = (pressure_data[0] << 8) | pressure_data[1];
    uint16_t raw_temperature = (pressure_data[2] << 8) | pressure_data[3];
    float pressure = pressure_to_pascals(raw_pressure);
    float temperature = temperature_to_celsius(raw_temperature);

