#include <sht35.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define FILE_NAME "environment.csv"
#define SAMPLING_INTERVAL 5000000 // 5 seconds in microseconds
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INIT 0xC0

// Function to calculate CRC-8 checksum
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = (crc >> 1) ^ ((crc & 1) * CRC_POLYNOMIAL);
        crc &= 0xFF;
        crc ^= data[i];
    }
    return crc;
}

// Function to handle SIGINT and SIGTERM signals
void sigint_handler(int sig) {
    sht35_shutdown();
    i2c_close(I2C_BUS);
    exit(0);
}

int main() {
    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize the SHT35 library
    if (sht35_init() != SHT35_OK) {
        fprintf(stderr, "Failed to initialize SHT35 library\n");
        return 1;
    }

    // Open the I2C bus
    int fd = i2c_open(I2C_BUS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        sht35_shutdown();
        return 1;
    }

    // Open the CSV file for writing
    FILE *file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file %s: %s\n", FILE_NAME, strerror(errno));
        i2c_close(I2C_BUS);
        sht35_shutdown();
        return 1;
    }

    // Check if the file is empty or does not exist, and write a header row if necessary
    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "timestamp,temperature,C,humidity,%%\n");
    }

    // Main loop
    while (1) {
        // Issue the single-shot high-repeatability measurement command
        uint8_t command[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        if (i2c_write(fd, I2C_ADDRESS, command, 8) != 8) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            fclose(file);
            i2c_close(I2C_BUS);
            sht35_shutdown();
            return 1;
        }

        // Wait at least 15 ms
        usleep(15000);

        // Read the six-byte result
        uint8_t data[6];
        if (i2c_read(fd, I2C_ADDRESS, data, 6) != 6) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            fclose(file);
            i2c_close(I2C_BUS);
            sht35_shutdown();
            return 1;
        }

        // Validate the CRC-8 checksums
        if (crc8(data, 4) != data[4] || crc8(data + 4, 2) != data[6]) {
            fprintf(stderr, "Invalid CRC-8 checksum\n");
            continue;
        }

        // Extract the temperature and humidity values
        uint16_t temperature = (data[0] << 8) | data[1];
        uint16_t humidity = (data[2] << 8) | data[3];

        // Convert the temperature and humidity values to Celsius and percent
        float temp = (temperature / 65536.0) * 200 - 50;
        float humid = (humidity / 65536.0) * 100;

        // Log the reading to the CSV file
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(file, "%s,%.2f,%.2f,%.2f\n", timestamp, temp, humid);

        // Sleep for the sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Clean up
    fclose(file);
    i2c_close(I2C_BUS);
    sht35_shutdown();

    return 0;
}

