#include <unistd.h>
#include <signal.h>
#include <poll.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 100
#define CSV_FILE "environment.log"
#define CSV_HEADER "timestamp,temperature_C,humidity_percent\n"
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

#define SIGINT_HANDLER SigintHandler
#define SIGTERM_HANDLER SigtermHandler

static void SigintHandler(int sig) {
    (void)sig;
    close(i2c_fd);
    exit(0);
}

static void SigtermHandler(int sig) {
    (void)sig;
    close(i2c_fd);
    exit(0);
}

static int crc8(uint8_t *data, size_t len, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(int fd, uint8_t *data) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = (uint8_t[]){0x00}; // Read command
    int ret = i2c_smbus_read_i2c_block_data(fd, msgs, 1, data);
    if (ret < 0) {
        if (errno == EIO) {
            // Sensor absent, try to reset it
            struct i2c_msg reset_msg;
            reset_msg.addr = I2C_ADDRESS;
            reset_msg.flags = 0;
            reset_msg.len = 1;
            reset_msg.buf = (uint8_t[]){0xB8}; // Reset command
            i2c_smbus_write_byte(fd, &reset_msg);
            return -1;
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int read_temperature(int fd, uint8_t *data) {
    uint8_t temp[3];
    if (read_sensor(fd, temp) < 0) {
        return -1;
    }
    if (crc8(temp, 2, CRC_INIT) != temp[2]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }
    uint16_t temp_value = (temp[0] << 8) | temp[1];
    return temp_value;
}

static int read_humidity(int fd, uint8_t *data) {
    uint8_t hum[3];
    if (read_sensor(fd, hum) < 0) {
        return -1;
    }
    if (crc8(hum, 2, CRC_INIT) != hum[2]) {
        fprintf(stderr, "CRC error: humidity\n");
        return -1;
    }
    uint16_t hum_value = (hum[0] << 8) | hum[1];
    return hum_value;
}

int main() {
    struct i2c_adapter *adapter;
    adapter = i2c_get_adapter(I2C_BUS);
    if (!adapter) {
        fprintf(stderr, "Failed to get I2C adapter\n");
        return 1;
    }

    int i2c_fd = i2c_open(adapter, I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = SIGINT_HANDLER;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }

    sa.sa_handler = SIGTERM_HANDLER;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        return 1;
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(csv_file, CSV_HEADER);
    fclose(csv_file);

    struct timeval last_log_time;
    gettimeofday(&last_log_time, NULL);

    while (1) {
        struct pollfd pfd;
        pfd.fd = i2c_fd;
        pfd.events = POLLOUT;
        if (poll(&pfd, 1, I2C_TIMEOUT * 1000) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                fprintf(stderr, "Poll error: %s\n", strerror(errno));
                break;
            }
        }

        uint8_t data[3];
        if (read_temperature(i2c_fd, data) < 0) {
            continue;
        }
        uint16_t temperature = read_temperature(i2c_fd, data);

        if (read_humidity(i2c_fd, data) < 0) {
            continue;
        }
        uint16_t humidity = read_humidity(i2c_fd, data);

        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_log_time.tv_sec >= 5) {
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));
            fprintf(csv_file, "%s,%d,%d\n", timestamp, temperature, humidity);
            fclose(csv_file);
            csv_file = fopen(CSV_FILE, "a");
            if (!csv_file) {
                fprintf(stderr, "Failed to reopen CSV file\n");
                break;
            }
            last_log_time = now;
        }
    }

    fclose(csv_file);
    i2c_close(i2c_fd);
    i2c_delete_adapter(adapter);
    return 0;
}

