#define RESPONSE_SIZE 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure and temperature to floating-point values
void convert_to_float(uint8_t *data, float *pressure, float *temperature) {
    *pressure = (data[0] << 8 | data[1]) * 100.0 / 32768.0;
    *temperature = (data[4] << 8 | data[5]) * 100.0 / 32768.0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    if (gpiod_close(i2c_fd) != 0) {
        perror("gpiod_close");
    }
    gpiod_driver_detach();
    fclose(file);
    exit(0);
}

int main() {
    // Initialize GPIO driver
    if (gpiod_driver_attach() != 0) {
        perror("gpiod_driver_attach");
        return 1;
    }

    // Open I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    if ((i2c_fd = open(i2c_dev_path, O_RDWR)) < 0) {
        perror("open");
        gpiod_driver_detach();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_driver_detach();
        return 1;
    }

    // Open file for logging
    file = fopen("airflow.dat", "ab");
    if (file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpiod_driver_detach();
        return 1;
