#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4D
#define FAN_GPIO 18
#define FAN_FREQ 25000
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL 100000 // 100ms

// Structure to hold sensor data
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
} sensor_data_t;

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    // Write command to read data
    uint8_t cmd[] = {0x00, 0x00, 0x00, 0x00};
    if (i2c_smbus_write_byte_data(fd, 0x00, cmd[0]) < 0) {
        fprintf(stderr, "Failed to write command to sensor\n");
        i2c_close(fd);
        return -1;
    }

    // Read data
    uint8_t data_bytes[4];
    if (i2c_smbus_read_i2c_block_data(fd, 0x00, 4, data_bytes) < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        i2c_close(fd);
        return -1;
    }

    // Extract pressure and temperature
    data->pressure = (data_bytes[0] << 8) | data_bytes[1];
    data->temperature = (data_bytes[2] << 8) | data_bytes[3];

    i2c_close(fd);
    return 0;
}

// Function to calculate flow rate
float calculate_flow_rate(sensor_data_t data) {
    // Assuming the sensor's datasheet provides a formula to calculate flow rate
    // from pressure and temperature
    // For example:
    float flow_rate = (data.pressure / 100.0f) * 10.0f;
    return flow_rate;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return;
    }

    if (gpioSetMode(FAN_GPIO, PI_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return;
    }

    if (gpioSetPWMdutycycle(FAN_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return;
    }
}

int main() {
    sensor_data_t data;
    float flow_rate;
    int duty_cycle = 0;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&data) < 0) {
            continue;
        }

        // Calculate flow rate
        flow_rate = calculate_flow_rate(data);

        // Log data
        char log_str[64];
        sprintf(log_str, "%lu,%f\n", (unsigned long)time(NULL), flow_rate);
        fwrite(log_str, 1, strlen(log_str), log_file);

        // Update PWM duty cycle
        duty_cycle = (int)(flow_rate * 100.0f);
        if (duty_cycle > 100) {
            duty_cycle = 100;
        } else if (duty_cycle < 0) {
            duty_cycle = 0;
        }
        set_pwm_duty_cycle(duty_cycle);

        // Sleep
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    set_pwm_duty_cycle(0);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

