void set_pwm_duty_cycle(int duty_cycle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return;
    }

    if (gpioSetMode(FAN_GPIO, PI_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return;
    }

    if (gpioSetPWMdutycycle(FAN_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return;
    }
