    sensor_data_t data;
    float flow_rate;
    int duty_cycle = 0;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&data) < 0) {
            continue;
        }

        // Calculate flow rate
        flow_rate = calculate_flow_rate(data);

        // Log data
        char log_str[64];
        sprintf(log_str, "%lu,%f\n", (unsigned long)time(NULL), flow_rate);
        fwrite(log_str, 1, strlen(log_str), log_file);

        // Update PWM duty cycle
        duty_cycle = (int)(flow_rate * 100.0f);
        if (duty_cycle > 100) {
            duty_cycle = 100;
        } else if (duty_cycle < 0) {
            duty_cycle = 0;
        }
        set_pwm_duty_cycle(duty_cycle);

        // Sleep
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    set_pwm_duty_cycle(0);
    gpioTerminate();
    fclose(log_file);
    return 0;
}
