    stop = 1;
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, I2C_SLAVE_ADDRESS);
    if (i2c_fd < 0) {
