        fclose(log_file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    uint8_t reg = 0x00;
    if (i2cWriteReg8(i2c_fd, 0x40, 0x00) < 0) {
        fprintf(stderr, "Failed to write to sensor register: %s\n", strerror(errno));
        fclose(log_file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Read pressure and temperature from sensor
        uint16_t pressure, temperature;
        if (i2cReadReg16(i2c_fd, 0x00, &pressure) < 0 || i2cReadReg16(i2c_fd, 0x02, &temperature) < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n");
            fprintf(stderr, "%s\n", ctime(&time(NULL)));
            fprintf(log_file, "%s\n", ctime(&time(NULL)));
            fflush(log_file);
            continue;
        }

        // Convert pressure and temperature to human-readable format
        char pressure_str[10];
        sprintf(pressure_str, "%04.2f", (float)pressure / 32768.0 * 1000.0);
        char temperature_str[6];
        sprintf(temperature_str, "%04.2f", (float)temperature / 128.0);

        // Get current time
        struct tm *time_info;
        time_t rawtime;
        time(&rawtime);
        time_info = localtime_r(&rawtime, &time_info);
        if (!time_info) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            fclose(log_file);
            gpioClose(i2c_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Log data
        char log_str[80];
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S, Pressure: %s hPa, Temperature: %s°C\n", time_info);
        fprintf(log_file, "%s%s%s", log_str, pressure_str, temperature_str);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    gpioClose(i2c_fd);

    // Close log file
    fclose(log_file);

    // Terminate GPIO library
    gpioTerminate();

    return EXIT_SUCCESS;
}

