#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define TEMPERATURE_SENSOR_ADDRESS 0x48
#define TEMPERATURE_SENSOR_REGISTER 0x00
#define CIRCULAR_BUFFER_SIZE 10
#define LED_GPIO 17
#define AVERAGE_WINDOW_SIZE 10

volatile bool running = true;

void cleanup() {
    gpioSetMode(LED_GPIO, GPIO_MODE_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    i2cClose(0);
    gpiod_cleanup();
    exit(0);
}

void signal_handler(int signal) {
    running = false;
}

int main() {
    int i2c_fd;
    int temperature;
    int average = 0;
    int count = 0;
    int circular_buffer[CIRCULAR_BUFFER_SIZE];
    int i;
    gpioInitialise();

    // Check if the driver library initializes correctly
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the LED pin as an output
    gpioSetMode(LED_GPIO, GPIO_MODE_OUTPUT);

    // Open the I2C bus
    i2c_fd = i2cOpen(0, TEMPERATURE_SENSOR_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read the temperature from the sensor
        if (i2cRead(i2c_fd, TEMPERATURE_SENSOR_REGISTER, 2, (uint8_t*)&temperature, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            i2cClose(i2c_fd);
            gpiod_cleanup();
            return 1;
        }

        // Convert the temperature to Celsius
        temperature = (temperature >> 4) * 0.0625;

        // Store the temperature in the circular buffer
        for (i = CIRCULAR_BUFFER_SIZE - 1; i > 0; i--) {
            circular_buffer[i] = circular_buffer[i - 1];
        }
        circular_buffer[0] = temperature;

        // Update the average
        average = 0;
        for (i = 0; i < AVERAGE_WINDOW_SIZE; i++) {
            average += circular_buffer[i];
        }
        average /= AVERAGE_WINDOW_SIZE;

        // Turn the LED on if the average temperature exceeds 28.0°C
        gpioWrite(LED_GPIO, average > 28.0 ? 1 : 0);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Turn the LED off and close the I2C handle
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_fd);

    // Clean up
    gpiod_cleanup();

    return 0;
}

