#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP32_ADDRESS 0x70
#define SDP32_REG_PRESSURE 0x00
#define SDP32_REG_TEMPERATURE 0x01
#define SDP32_REG_SCALE_FACTOR 0x02
#define SDP32_REG_CRC 0x03

#define DEFAULT_INTERVAL 1000

static volatile bool running = true;
static int interval = DEFAULT_INTERVAL;

static void signal_handler(int sig) {
    running = false;
}

static int i2c_read(uint8_t reg, uint8_t *buf, int len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDRESS) < 0) {
        perror("i2c_sla");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("i2c_write");
        close(fd);
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("i2c_read");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int i2c_write(uint8_t reg, uint8_t *buf, int len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDRESS) < 0) {
        perror("i2c_sla");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("i2c_write");
        close(fd);
        return -1;
    }

    if (write(fd, buf, len) != len) {
        perror("i2c_write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int read_sdp32_pressure(uint8_t *buf) {
    uint8_t reg = SDP32_REG_PRESSURE;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t pressure_crc = crc8(buf, 6);
    if (crc != pressure_crc) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }

    return 0;
}

static int read_sdp32_temperature(uint8_t *buf) {
    uint8_t reg = SDP32_REG_TEMPERATURE;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t temperature_crc = crc8(buf, 6);
    if (crc != temperature_crc) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    return 0;
}

static int read_sdp32_scale_factor(uint8_t *buf) {
    uint8_t reg = SDP32_REG_SCALE_FACTOR;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t scale_factor_crc = crc8(buf, 6);
    if (crc != scale_factor_crc) {
        fprintf(stderr, "Scale factor CRC error\n");
        return -1;
    }

    return 0;
}

static uint8_t crc8(uint8_t *buf, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc = crc8_update(crc, buf[i]);
    }
    return crc;
}

static uint8_t crc8_update(uint8_t crc, uint8_t byte) {
    crc = (crc ^ byte) ^ ((crc >> 4) & 0x0F);
    crc = (crc ^ (crc & 0x0F) ^ (crc >> 5));
    crc = (crc ^ (crc & 0x0F) ^ (crc >> 5));
    return crc;
}

static void print_reading(uint8_t *buf) {
    uint16_t pressure = (buf[0] << 8) | buf[1];
    uint16_t temperature = (buf[3] << 8) | buf[4];
    uint16_t scale_factor = (buf[6] << 8) | buf[7];

    struct timeval tv;
    gettimeofday(&tv, NULL);
    printf("%ld.%06ld: Pressure: %d Pa, Temperature: %d C, Scale factor: %d\n",
           tv.tv_sec, tv.tv_usec, pressure, temperature, scale_factor);
}

int main(int argc, char **argv) {
    struct option long_options[] = {
        {"interval", required_argument, 0, 'i'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "i:", long_options, NULL)) != -1) {
        switch (opt) {
        case 'i':
            interval = atoi(optarg);
            break;
        default:
            fprintf(stderr, "Usage: %s [-i <interval>]\n", argv[0]);
            exit(1);
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t buf[9];

    while (running) {
        if (read_sdp32_pressure(buf) < 0) {
            fprintf(stderr, "Error reading pressure\n");
            exit(1);
        }

        if (read_sdp32_temperature(buf) < 0) {
            fprintf(stderr, "Error reading temperature\n");
            exit(1);
        }

        if (read_sdp32_scale_factor(buf) < 0) {
            fprintf(stderr, "Error reading scale factor\n");
            exit(1);
        }

        print_reading(buf);

        usleep(interval * 1000);
    }

    return 0;
}

