        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int i2c_write(uint8_t reg, uint8_t *buf, int len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDRESS) < 0) {
        perror("i2c_sla");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("i2c_write");
        close(fd);
        return -1;
    }

    if (write(fd, buf, len) != len) {
        perror("i2c_write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int read_sdp32_pressure(uint8_t *buf) {
    uint8_t reg = SDP32_REG_PRESSURE;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t pressure_crc = crc8(buf, 6);
    if (crc != pressure_crc) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }

    return 0;
}

static int read_sdp32_temperature(uint8_t *buf) {
    uint8_t reg = SDP32_REG_TEMPERATURE;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t temperature_crc = crc8(buf, 6);
    if (crc != temperature_crc) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    return 0;
}

static int read_sdp32_scale_factor(uint8_t *buf) {
    uint8_t reg = SDP32_REG_SCALE_FACTOR;
    if (i2c_read(reg, buf, 9) < 0) {
        return -1;
    }

    uint8_t crc = buf[7];
    uint8_t scale_factor_crc = crc8(buf, 6);
    if (crc != scale_factor_crc) {
        fprintf(stderr, "Scale factor CRC error\n");
        return -1;
    }

    return 0;
}

static uint8_t crc8(uint8_t *buf, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc = crc8_update(crc, buf[i]);
    }
    return crc;
}

static uint8_t crc8_update(uint8_t crc, uint8_t byte) {
    crc = (crc ^ byte) ^ ((crc >> 4) & 0x0F);
    crc = (crc ^ (crc & 0x0F) ^ (crc >> 5));
    crc = (crc ^ (crc & 0x0F) ^ (crc >> 5));
    return crc;
}

static void print_reading(uint8_t *buf) {
    uint16_t pressure = (buf[0] << 8) | buf[1];
    uint16_t temperature = (buf[3] << 8) | buf[4];
    uint16_t scale_factor = (buf[6] << 8) | buf[7];

    struct timeval tv;
    gettimeofday(&tv, NULL);
    printf("%ld.%06ld: Pressure: %d Pa, Temperature: %d C, Scale factor: %d\n",
           tv.tv_sec, tv.tv_usec, pressure, temperature, scale_factor);
}

