#define SDP810_CRC_POLYNOMIAL 0x1D
#define SDP810_CRC_INIT 0x00

// Function to calculate CRC-8
uint8_t sdp810_crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = SDP810_CRC_INIT;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
bool sdp810_read_data(int i2c_fd, uint8_t reg, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return false;
    }

    uint8_t command = (reg << 1) | 0x00;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C bus");
        return false;
    }

    usleep(45000); // Wait for conversion to complete

    if (read(i2c_fd, data, 9) != 9) {
        perror("Failed to read from I2C bus");
        return false;
    }

    // Validate CRC-8 on each 3-byte word
    for (uint8_t i = 0; i < 3; i++) {
        uint8_t crc = sdp810_crc8(data + (i * 3), 3);
        if (crc != data[3 + i]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return false;
        }
    }

    return true;
}

