        perror("Failed to set SCL pin mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(SDA_PIN, PI_PUD_UP) < 0) {
        perror("Failed to set SDA pull-up/down control");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(SCL_PIN, PI_PUD_UP) < 0) {
        perror("Failed to set SCL pull-up/down control");
        gpioTerminate();
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t data[9];
        if (sdp810_read_data(i2c_fd, SDP810_REG_PRESSURE, data)) {
            printf("Pressure: %d Pa, Temperature: %d C\n", (data[0] << 8 | data[1]), (data[2] << 8 | data[3]));
        } else {
            fprintf(stderr, "Failed to read data from SDP810\n");
        }

        usleep(1000000); // Wait 1 second
    }

    if (close(i2c_fd) < 0) {
        perror("Failed to close I2C file descriptor");
    }

    gpioTerminate();
    return 0;
}

