#include <errno.h>

#define I2C_BUS 1
#define I2C_SDA 2
#define I2C_SCL 3
#define HDC1000_ADDRESS 0x40
#define HDC1000_REG_CONFIG 0x02
#define HDC1000_REG_HUMIDITY 0x00
#define HDC1000_REG_TEMPERATURE 0x01
#define HDC1000_REG_CONVERSION_READY 0x00

int i2c_fd = -1;
volatile bool exit_request = false;

void sigint_handler(int sig) {
    exit_request = true;
}

void sigterm_handler(int sig) {
    exit_request = true;
}

int main() {
    struct i2c_adapter *adapter;
    struct i2c_client *client;
    char i2c_dev_path[256];
    char buffer[2];

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C device
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed to 100 kHz
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize HDC1000
    uint8_t config = 0x60; // 14-bit temperature and humidity conversion
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to HDC1000");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!exit_request) {
        // Wait for conversion to complete
        usleep(20000);

        // Read conversion ready status
        if (read(i2c_fd, buffer, 1) != 1) {
            fprintf(stderr, "Error reading conversion ready status\n");
            continue;
        }

        // Read temperature and humidity
        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Error reading temperature and humidity\n");
            continue;
        }

        uint16_t temp = (buffer[0] << 8) | buffer[1];
        uint16_t humidity = (buffer[0] << 8) | buffer[1];

        // Convert to Celsius and percentage
        float temp_c = (temp * 175.72) / 65536.0 - 46.85;
        float humidity_p = (humidity * 100.0) / 65536.0;

        // Print values
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, humidity_p);

        // Wait 5 seconds before next measurement
        usleep(5000000);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

