}

// Function to read a 16-bit word from the SI7051 sensor
uint16_t si7051_read_word(int i2c_fd, uint8_t reg) {
    uint16_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, SI7051_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return 0;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, reg, 0) < 0) {
        perror("i2c_smbus_write_byte_data");
        return 0;
    }
    if (i2c_smbus_read_word_data(i2c_fd, reg) < 0) {
        perror("i2c_smbus_read_word_data");
        return 0;
    }
    return 0;
