// Function to calculate the temperature from the raw data
float si7051_get_temperature(int i2c_fd) {
    uint16_t raw_data = si7051_read_word(i2c_fd, SI7051_REG_TEMP_MSB);
    if (raw_data == 0) {
        return 0.0;
