        gettimeofday(&tv, NULL);
        printf("%ld.%06ld: Pressure: %d mbar\n", tv.tv_sec, tv.tv_usec, msg.buf[0]);

        // Wait for the sampling interval
        usleep(SAMPLING_INTERVAL * 1000000);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

