#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define the I2C bus and device addresses
#define I2C_BUS 1
#define DEVICE_ADDRESS 0x00

// Define the sensor registers
#define REG_MEASURE 0x00
#define REG_DATA 0x01
#define REG_CRC 0x02

// Define the CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

// Define the measurement interval in milliseconds
#define MEASUREMENT_INTERVAL 45

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the file descriptor for the log file
FILE *log_file;

// Function to calculate the CRC-8
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_data(int fd, uint8_t *data) {
    // Write the measure command to the sensor
    if (i2c_write(fd, REG_MEASURE, 1, 1) < 0) {
        perror("i2c_write");
        return -1;
    }

    // Wait for the measurement to complete
    usleep(MEASUREMENT_INTERVAL * 1000);

    // Read the data from the sensor
    if (i2c_read(fd, REG_DATA, data, NUM_BYTES) < 0) {
        perror("i2c_read");
        return -1;
    }

    // Validate the CRC-8 of each word
    for (int i = 0; i < 3; i++) {
        uint16_t word = (data[i * 2] << 8) | data[i * 2 + 1];
        if (calculate_crc8((uint8_t *)&word, 2) != data[i * 2 + 8]) {
            return -1;
        }
    }

    return 0;
}

// Function to log the data to a file
void log_data(uint16_t pressure, uint16_t temperature) {
    char timestamp[20];
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (double)pressure / 100.0, (double)temperature / 100.0);
    fflush(log_file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Close the I2C file descriptor
    close(i2cOpen(I2C_BUS, DEVICE_ADDRESS));

    // Close the log file
    fclose(log_file);

    // Exit the program
    exit(0);
}

int main() {
    // Open the I2C bus
    int fd = i2cOpen(I2C_BUS, DEVICE_ADDRESS);
    if (fd < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read data from the sensor
        uint8_t data[NUM_BYTES];
        if (read_data(fd, data) < 0) {
            // If the sensor is absent, log an error and continue
            fprintf(log_file, "Error: Sensor absent\n");
            continue;
        }

        // Log the data
        log_data((uint16_t)((data[0] << 8) | data[1]), (uint16_t)((data[2] << 8) | data[3]));

        // Sleep for the measurement interval
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Close the I2C file descriptor
    close(fd);

    // Close the log file
    fclose(log_file);

    return 0;
}

