static void sdp800_trigger(void) {
    uint8_t trigger_cmd = 0x01;
    if (i2c_fd == -1) {
        return;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        sdp800_present = false;
        return;
    }
    if (write(i2c_fd, &trigger_cmd, 1) != 1) {
        sdp800_present = false;
        return;
    }
}

