#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PRESSURE_REGISTER 0x00
#define PRESSURE_REGISTER_SIZE 2
#define SAFE_TIRE_PRESSURE_MIN 200
#define SAFE_TIRE_PRESSURE_MAX 250
#define LOG_FILE "pressure_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    char buffer[PRESSURE_REGISTER_SIZE];
    struct i2c_msg msg;
    struct i2c_msg msg_read;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_smbus_ioctl_data i2c_ioctl_data;
    struct stat log_stat;
    char timestamp[20];
    time_t now;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Get log file size
    if (fstat(log_fd, &log_stat) < 0) {
        fprintf(stderr, "Failed to get log file size\n");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Check if log file is new
    if (log_stat.st_size == 0) {
        // Write header row
        fprintf(log_fd, "timestamp,pressure_kPa\n");
    }

    // Initialize I2C register
    msg_read.addr = I2C_ADDRESS;
    msg_read.flags = 0;
    msg_read.len = PRESSURE_REGISTER_SIZE;
    msg_read.buf = buffer;
    msg_read.read = 1;
    msg_write.addr = I2C_ADDRESS;
    msg_write.flags = 0;
    msg_write.len = 0;
    msg_write.buf = NULL;
    msg_write.write = 0;

    while (running) {
        // Read I2C register
        i2c_data.msgs = &msg_read;
        i2c_data.nmsgs = 1;
        i2c_data.msgs[0].len = PRESSURE_REGISTER_SIZE;
        i2c_data.msgs[0].buf = buffer;
        i2c_data.nread = PRESSURE_REGISTER_SIZE;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            // Close and reopen I2C handle
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            continue;
        }

        // Read pressure value
        i2c_ioctl_data.read = 1;
        i2c_ioctl_data.addr = I2C_ADDRESS;
        i2c_ioctl_data.len = PRESSURE_REGISTER_SIZE;
        i2c_ioctl_data.buf = buffer;
        if (ioctl(i2c_fd, I2C_SMBUS_READ, &i2c_ioctl_data) < 0) {
            // Close and reopen I2C handle
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            continue;
        }

        // Convert pressure value to kPa
        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        float pressure_kPa = (float)pressure / 32768.0;

        // Check if pressure is within safe tire range
        if (pressure_kPa < SAFE_TIRE_PRESSURE_MIN || pressure_kPa > SAFE_TIRE_PRESSURE_MAX) {
            fprintf(stderr, "Warning: Pressure out of safe tire range: %f kPa\n", pressure_kPa);
        }

        // Append to log file
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%f\n", timestamp, pressure_kPa);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    close(i2c_fd);

    // Flush and close log file
    fsync(log_fd);
    close(log_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

