#define SENT_TICK_TIME_US 3000
#define SENT_SYNC_PULSE_WIDTH 56
#define SENT_MIN_PULSE_WIDTH 12
#define SENT_MAX_PULSE_WIDTH 271
#define SENT_NIBBLE_WIDTH 8
#define SENT_STATUS_NIBBLE 0x0F
#define SENT_CHECKSUM_NIBBLE 0x0F

#define SENT_NIBBLE_TO_PRESSURE(nibble) ((nibble) * 1000.0 / 16.0)

#define SENT_STATUS_MASK 0x0F
#define SENT_DATA_MASK 0x0F
#define SENT_CHECKSUM_MASK 0x0F

#define SENT_ERROR_NONE 0
#define SENT_ERROR_TIMEOUT 1
#define SENT_ERROR_CHECKSUM 2
#define SENT_ERROR_OUT_OF_RANGE 3

#define SENT_LOG_FILE "pressure_log.txt"

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int gpio_fd;
    int error;
    uint32_t tick;
    uint8_t sync_pulse_width;
    uint8_t pulse_width;
    uint8_t status_nibble;
    uint8_t data_nibbles[3];
    uint8_t checksum_nibble;
    uint32_t pressure;
    FILE *log_file;
    struct stat log_file_stat;

    // Initialize GPIO
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO4 as an input
    if (gpioSetMode(gpio_fd, 4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO4 as an input: %s\n", strerror(errno));
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    log_file = fopen(SENT_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Get log file stats
    if (fstat(fileno(log_file), &log_file_stat) < 0) {
        fprintf(stderr, "Failed to get log file stats: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for synchronization pulse
        tick = gpioTick(gpio_fd, 4, SENT_SYNC_PULSE_WIDTH * SENT_TICK_TIME_US);
        if (tick < 0) {
            fprintf(stderr, "Failed to wait for synchronization pulse: %s\n", strerror(errno));
            break;
        }

        // Wait for data pulse
        pulse_width = gpioTick(gpio_fd, 4, SENT_MAX_PULSE_WIDTH * SENT_TICK_TIME_US);
        if (pulse_width < 0) {
            fprintf(stderr, "Failed to wait for data pulse: %s\n");
            break;
        }

        // Check for timeout
        if (pulse_width < SENT_MIN_PULSE_WIDTH * SENT_TICK_TIME_US) {
            fprintf(stderr, "Timeout\n");
            break;
        }

        // Check for out-of-range pulse width
        if (pulse_width > SENT_MAX_PULSE_WIDTH * SENT_TICK_TIME_US) {
            fprintf(stderr, "Out-of-range pulse width\n");
            break;
        }

        // Extract nibbles
        status_nibble = (pulse_width / (SENT_TICK_TIME_US * SENT_NIBBLE_WIDTH)) & SENT_STATUS_MASK;
        data_nibbles[0] = (pulse_width / (SENT_TICK_TIME_US * SENT_NIBBLE_WIDTH)) >> 4 & SENT_DATA_MASK;
        data_nibbles[1] = (pulse_width / (SENT_TICK_TIME_US * SENT_NIBBLE_WIDTH)) >> 2 & SENT_DATA_MASK;
        data_nibbles[2] = (pulse_width / (SENT_TICK_TIME_US * SENT_NIBBLE_WIDTH)) >> 0 & SENT_DATA_MASK;
        checksum_nibble = (pulse_width / (SENT_TICK_TIME_US * SENT_NIBBLE_WIDTH)) >> 6 & SENT_CHECKSUM_MASK;

        // Check for checksum mismatch
        if (status_nibble != SENT_STATUS_NIBBLE || data_nibbles[0] != SENT_DATA_NIBBLE || data_nibbles[1] != SENT_DATA_NIBBLE || data_nibbles[2] != SENT_DATA_NIBBLE || checksum_nibble != SENT_CHECKSUM_NIBBLE) {
            fprintf(stderr, "Checksum mismatch\n");
            break;
        }

        // Calculate pressure
        pressure = SENT_NIBBLE_TO_PRESSURE(data_nibbles[0]) + SENT_NIBBLE_TO_PRESSURE(data_nibbles[1]) * 10 + SENT_NIBBLE_TO_PRESSURE(data_nibbles[2]) * 100;

        // Log reading
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n", (int)time(NULL) % 10000, (int)time(NULL) / 10000 % 100, (int)time(NULL) / 1000000 % 100, (int)time(NULL) / 10000000 % 60, (int)time(NULL) / 600000 % 60, (int)time(NULL) / 36000000 % 24, pressure);
        fflush(log_file);

        // Wait for next pulse
        usleep(SENT_MAX_PULSE_WIDTH * SENT_TICK_TIME_US);
    }

    // Close log file
    fclose(log_file);

    // Release GPIO
    gpioTerminate(gpio_fd);

    return 0;
}

