#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int read_sht40(gpiod_chip *chip, uint8_t *data) {
    // Write the command to start a measurement
    if (gpiod_chip_write(chip, 0x00, 0x00, 1) < 0) {
        perror("gpiod_chip_write");
        return -1;
    }

    // Wait for the measurement to complete
    usleep(8500000);

    // Read the data
    if (gpiod_chip_read(chip, 0x00, data, 6) < 0) {
        perror("gpiod_chip_read");
        return -1;
    }

    // Validate the CRC-8 values
    uint8_t crc_temp = crc8(data, 2);
    uint8_t crc_humidity = crc8(data + 3, 2);
    if (crc_temp != data[2] || crc_humidity != data[5]) {
        fprintf(stderr, "Invalid CRC\n");
        return -1;
    }

    return 0;
}

// Signal handler to clean up on exit
void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/i2c-1"));
    gpiod_driver_close();
    fclose(log_file);
    exit(0);
}

int main() {
    // Open the I2C interface
    gpiod_chip *chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip);
        gpiod_driver_close();
        return 1;
    }

    // Install the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_driver_close();
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t data[6];
        if (read_sht40(chip, data) < 0) {
            break;
        }

        // Convert the temperature and humidity values
        float temperature = (data[0] << 8) | data[1];
        float humidity = (data[3] << 8) | data[4];

        // Append the data to the log file
        char timestamp[20];
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        fprintf(log_file, "%s %.2f°C %.2f%%\n", timestamp, temperature / 100.0, humidity / 100.0);
        fflush(log_file);

        // Wait for 5 seconds
        usleep(5000000);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);
    gpiod_driver_close();
    return 0;
}

