#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define I2C_ADDRESS 0x48  // Texas Instruments TMP117 I2C address

// Structure to hold temperature data
typedef struct {
    float temperature;
    uint32_t timestamp;
} TemperatureSample;

// Function to handle signal interrupts
void signal_handler(int signal) {
    // Flush the buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (samples[i].temperature != 0.0f) {
            // Write the sample to the file
            FILE *file = fopen("temperature_log.dat", "ab");
            if (file == NULL) {
                perror("fopen");
                exit(1);
            }
            fwrite(&samples[i], sizeof(TemperatureSample), 1, file);
            fclose(file);
        }
    }

    // Release resources
    gpioTerminate();
    close(i2c_fd);
    munmap(i2c_addr, I2C_SIZE);
    unlink("/dev/i2c-1");
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Map I2C device memory
    I2C_SIZE = 0x100;  // Assuming 256 bytes
    i2c_addr = mmap(NULL, I2C_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_addr == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // Initialize circular buffer
    samples = malloc(BUFFER_SIZE * sizeof(TemperatureSample));
    if (samples == NULL) {
        perror("malloc");
        return 1;
    }

    // Initialize file for logging
    FILE *file = fopen("temperature_log.dat", "wb");
    if (file == NULL) {
        perror("fopen");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        uint8_t reg = 0x00;  // Register address for temperature
        if (i2c_smbus_read_byte_data(i2c_fd, reg) < 0) {
            perror("i2c_smbus_read_byte_data");
            continue;
        }

        // Read temperature data
        uint16_t data = i2c_smbus_read_word_data(i2c_fd, reg + 1);
        float temperature = (data >> 8) + (data & 0xFF) / 256.0f;

        // Store sample in buffer
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (samples[i].temperature == 0.0f) {
                samples[i].temperature = temperature;
                samples[i].timestamp = time(NULL);
                break;
            }
        }

        // Write sample to file
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (samples[i].temperature != 0.0f) {
                // Write the sample to the file
                FILE *file = fopen("temperature_log.dat", "ab");
                if (file == NULL) {
                    perror("fopen");
                    exit(1);
                }
                fwrite(&samples[i], sizeof(TemperatureSample), 1, file);
                fclose(file);
            }
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

