#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define REG_SPEED 0x00
#define REG_TEMP 0x01
#define LOG_FILE "mag_temp_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int log_fd;
    char log_buffer[256];
    char header[] = "time,temperature,rotational_speed\n";
    struct i2c_msg msg;
    struct i2c_msg msg2;
    uint8_t data[2];
    uint16_t speed;
    uint16_t temp;
    struct stat sb;
    time_t last_log_time = 0;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check if log file exists
    if (stat(LOG_FILE, &sb) == 0) {
        // Append to existing log file
        log_fd = open(LOG_FILE, O_WRONLY | O_APPEND);
    } else {
        // Create new log file
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        // Write header to log file
        if (write(log_fd, header, strlen(header)) != strlen(header)) {
            perror("Failed to write header to log file");
            close(i2c_fd);
            close(log_fd);
            exit(EXIT_FAILURE);
        }
    }

    while (running) {
        // Read temperature and speed from sensor
        msg.buf = data;
        msg.len = 2;
        msg.flags = 0;
        msg.addr = I2C_ADDRESS;
        msg2.buf = NULL;
        msg2.len = 0;
        msg2.flags = 0;
        msg2.addr = I2C_ADDRESS;

        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            // If read fails, write NaN values to log file
            fprintf(log_buffer, "%lu,%f,%f\n", time(NULL), NAN, NAN);
            if (write(log_fd, log_buffer, strlen(log_buffer)) != strlen(log_buffer)) {
                perror("Failed to write to log file");
                close(i2c_fd);
                close(log_fd);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        // Read temperature and speed from data
        temp = (data[0] << 8) | data[1];
        speed = (data[2] << 8) | data[3];

        // Format log data
        char log_line[256];
        sprintf(log_line, "%lu,%d,%d\n", time(NULL), temp, speed);

        // Write log data to file
        if (write(log_fd, log_line, strlen(log_line)) != strlen(log_line)) {
            perror("Failed to write to log file");
            close(i2c_fd);
            close(log_fd);
            exit(EXIT_FAILURE);
        }

        // Sleep for 1 second
        usleep(1000000);

        // Check if 1 second has passed since last log
        if (difftime(time(NULL), last_log_time) >= 1) {
            last_log_time = time(NULL);
        }
    }

    // Close I2C handle
    close(i2c_fd);

    // Flush and close log file
    fsync(log_fd);
    close(log_fd);

    return 0;
}

