#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDRESS 0x48
#define TEMPERATURE_REGISTER 0x00
#define MAX_ATTEMPTS 3

int i2c_fd = -1;
bool i2c_initialized = false;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int i2c_init() {
    if (i2c_fd != -1) {
        return i2c_fd;
    }

    for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd == -1) {
            if (errno == EACCES) {
                printf("Error: Permission denied to access I2C bus\n");
                exit(1);
            } else if (errno == ENOENT) {
                printf("Error: I2C bus not found\n");
                exit(1);
            } else {
                printf("Error: Failed to open I2C bus (attempt %d/%d)\n", attempt + 1, MAX_ATTEMPTS);
            }
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDRESS) < 0) {
            printf("Error: Failed to set I2C slave address\n");
            close(i2c_fd);
            i2c_fd = -1;
            sleep(1);
            continue;
        }

        i2c_initialized = true;
        break;
    }

    if (!i2c_initialized) {
        printf("Error: Failed to initialize I2C bus after %d attempts\n", MAX_ATTEMPTS);
        exit(1);
    }

    return i2c_fd;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = i2c_init();

    FILE *file = fopen("temperature_log.txt", "a");
    if (file == NULL) {
        printf("Error: Failed to open temperature log file\n");
        exit(1);
    }

    while (1) {
        if (!i2c_initialized) {
            i2c_fd = i2c_init();
            if (i2c_fd == -1) {
                break;
            }
        }

        uint16_t temperature;
        if (i2c_smbus_read_byte_data(i2c_fd, TEMPERATURE_REGISTER, &temperature) < 0) {
            printf("Error: Failed to read temperature\n");
            break;
        }

        double temp_c = (double)temperature / 128.0;
        if (temp_c < -128.0) {
            temp_c = -128.0;
        }

        char timestamp[20];
        time_t rawtime;
        time(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&rawtime));
        fprintf(file, "%s, Temperature: %.2f C\n", timestamp, temp_c);

        sleep(1);
    }

    fclose(file);
    close(i2c_fd);
    return 0;
}

