#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define FLOW_SENSOR_ADDRESS 0x00
#define FLOW_SENSOR_REGISTER 0x00
#define TEMPERATURE_REGISTER 0x01
#define FLOW_VALUE_REGISTER 0x02
#define TEMPERATURE_VALUE_REGISTER 0x03
#define FLOW_VALUE_MASK 0x3FFF
#define TEMPERATURE_VALUE_MASK 0xFFF
#define FLOW_VALUE_SHIFT 0
#define TEMPERATURE_VALUE_SHIFT 12

#define LOG_FILE "flow_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    char log_buffer[256];

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = gpioOpen(1, 2); // Raspberry Pi Zero W: SCL on GPIO 2, SDA on GPIO 3
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize I2C handle
    if (i2cSetup(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C handle\n");
        close(log_fd);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for 2 seconds to allow sensor to stabilize
    sleep(2);

    while (running) {
        // Read 4 bytes from flow sensor
        uint8_t buffer[4];
        if (i2cRead(i2c_fd, FLOW_SENSOR_ADDRESS, FLOW_SENSOR_REGISTER, buffer, 4) < 0) {
            // Log read error and attempt to re-initialize I2C handle
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            if (i2cSetup(i2c_fd, 100000) < 0) {
                fprintf(stderr, "Failed to re-initialize I2C handle\n");
                close(log_fd);
                gpioClose(i2c_fd);
                gpioTerminate();
                return 1;
            }
            continue;
        }

        // Extract flow and temperature values
        uint16_t flow_value = (buffer[0] << FLOW_VALUE_SHIFT) | (buffer[1] & FLOW_VALUE_MASK);
        uint16_t temperature_value = (buffer[2] << TEMPERATURE_VALUE_SHIFT) | (buffer[3] & TEMPERATURE_VALUE_MASK);

        // Ignore first two reads after power-up
        if (flow_value == 0 && temperature_value == 0) {
            continue;
        }

        // Write timestamped measurement to log file
        time_t timestamp = time(NULL);
        sprintf(log_buffer, "%lu %d %d\n", timestamp, flow_value, temperature_value);
        if (write(log_fd, log_buffer, strlen(log_buffer)) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            close(log_fd);
            gpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanly close I2C handles and log file
    close(log_fd);
    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

