// CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

// SHT31-D sensor I2C address
#define SHT31_ADDRESS 0x44

// SHT31-D sensor command to start a measurement
#define SHT31_MEASURE_CMD 0x00

// SHT31-D sensor command to read the measurement result
#define SHT31_READ_CMD 0x00

// SHT31-D sensor data format
typedef struct {
    uint16_t temperature;
    uint16_t humidity;
} sht31d_data_t;

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT31-D sensor
bool read_sht31d_data(int i2c_fd, sht31d_data_t *data) {
    // Send the measurement command
    if (i2c_write(i2c_fd, SHT31_ADDRESS, SHT31_MEASURE_CMD, 1, 1) != 1) {
        return false;
    }

    // Wait for the measurement to complete
    usleep(15000);

    // Read the measurement result
    uint8_t buffer[6];
    for (int i = 0; i < 3; i++) {
        if (i2c_read(i2c_fd, SHT31_ADDRESS, buffer, 6, 1) != 6) {
            return false;
        }

        // Validate the CRC-8
        if (crc8(buffer, 5) != buffer[5]) {
            return false;
        }

        // Check if the sensor is still responding
        if (i > 0 && i2c_read(i2c_fd, SHT31_ADDRESS, buffer, 6, 1) != 6) {
            return false;
        }
    }

    // Extract the temperature and humidity from the data
    data->temperature = (buffer[0] << 8) | buffer[1];
    data->humidity = (buffer[2] << 8) | buffer[3];

    return true;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the I2C bus
    int i2c_fd = i2cOpen(1, 1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C pins
    if (gpioSetMode(2, PI_INPUT) < 0 || gpioSetMode(3, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up I2C pins\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("sht31d_data.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        sht31d_data_t data;
        if (read_sht31d_data(i2c_fd, &data)) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (double)data.temperature / 100, (double)data.humidity / 100);
        } else {
            fprintf(stderr, "Failed to read data from SHT31-D sensor\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

