#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define the I2C bus and address of the sensor
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A

// Define the sensor register addresses
#define PRESSURE_REGISTER 0x00
#define TEMPERATURE_REGISTER 0x01

// Define the log file name
#define LOG_FILE "pressure_log.txt"

// Function to log an error with a timestamp
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Function to read the sensor data
int read_sensor_data(int i2c_fd) {
    uint16_t pressure, temperature;
    char buffer[2];

    // Read the pressure and temperature from the sensor
    if (i2c_smbus_write_byte_data(i2c_fd, PRESSURE_REGISTER, 0x00) < 0) {
        log_error("Failed to write to pressure register");
        return -1;
    }
    if (i2c_smbus_read_i2c_block_data(i2c_fd, PRESSURE_REGISTER, 2, buffer) < 0) {
        log_error("Failed to read pressure data");
        return -1;
    }
    pressure = (buffer[0] << 8) | buffer[1];

    if (i2c_smbus_write_byte_data(i2c_fd, TEMPERATURE_REGISTER, 0x00) < 0) {
        log_error("Failed to write to temperature register");
        return -1;
    }
    if (i2c_smbus_read_i2c_block_data(i2c_fd, TEMPERATURE_REGISTER, 2, buffer) < 0) {
        log_error("Failed to read temperature data");
        return -1;
    }
    temperature = (buffer[0] << 8) | buffer[1];

    return pressure, temperature;
}

// Function to log the sensor data
void log_data(uint16_t pressure, uint16_t temperature) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    char log_message[50];
    sprintf(log_message, "%s: Pressure: %d mbar, Temperature: %d°C", timestamp, pressure, temperature);
    fprintf(stderr, "%s\n", log_message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s\n", log_message);
    fclose(log_file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    // Cleanly release resources
    i2c_close(I2C_BUS);
    fclose(stderr);
    pigpio_cleanup();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (pigpio_initialise() < 0) {
        log_error("Failed to initialize GPIO library");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the sensor data
        int result = read_sensor_data(i2c_fd);
        if (result < 0) {
            continue;
