#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define FAN_GPIO 18
#define SAMPLES 60
#define HYS 2.0

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int gpio_fd;
    int i;
    int samples[SAMPLES];
    float sum = 0.0;
    float avg;
    float prev_avg;
    float temp;
    bool fan_on = false;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C interface
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C interface: %s\n", strerror(errno));
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Set up I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Initialize circular buffer
    for (i = 0; i < SAMPLES; i++) {
        samples[i] = 0;
    }

    // Main loop
    while (running) {
        // Read temperature
        if (i2c_smbus_read_byte_data(i2c_fd, 0x00) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue;
        }
        temp = (i2c_smbus_read_byte_data(i2c_fd, 0x01) << 8) | i2c_smbus_read_byte_data(i2c_fd, 0x00);
        temp = (temp * 175.72) / 65536 - 46.85;

        // Add to circular buffer
        sum -= samples[i % SAMPLES];
        samples[i % SAMPLES] = temp;
        sum += temp;

        // Compute running average
        avg = sum / SAMPLES;

        // Check hysteresis
        if (avg > 28.0 + HYS && !fan_on) {
            gpioWrite(gpio_fd, FAN_GPIO, 1);
            fan_on = true;
        } else if (avg < 26.0 - HYS && fan_on) {
            gpioWrite(gpio_fd, FAN_GPIO, 0);
            fan_on = false;
        }

        // Log temperature
        printf("Temperature: %.2f°C\n", avg);

        // Sleep
        usleep(1000000);
    }

    // Clean up
    gpioWrite(gpio_fd, FAN_GPIO, 0);
    close(i2c_fd);
    gpioTerminate(gpio_fd);

    return 0;
}

