// Sensirion SDP810-500Pa sensor I2C address
#define SDP810_ADDRESS 0x70

// Sensirion CRC-8 polynomial
#define SDP810_CRC_POLYNOMIAL 0x1D

// Sensirion CRC-8 initial value
#define SDP810_CRC_INITIAL_VALUE 0x00

// Function to calculate the CRC-8 checksum
uint8_t sdp810_crc8(uint8_t *data, size_t len) {
    uint8_t crc = SDP810_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int sdp810_read_data(int i2c_fd, uint8_t *data) {
    // Send the read command
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }
    if (write(i2c_fd, "\x00\x00\x00\x00\x00\x00\x00\x00", 8) < 0) {
        perror("write");
        return -1;
    }

    // Wait 45ms
    usleep(45000);

    // Read the data
    if (read(i2c_fd, data, 9) < 9) {
        perror("read");
        return -1;
    }

    // Validate the CRC
    uint8_t crc = sdp810_crc8(data, 8);
    if (crc != data[8]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    return 0;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Cleanly close the I2C handle
    gpio_i2c_close();

    // Close the log file
    fclose(log_file);

    // Invoke the library's call() cleanup function
    gpio_cleanup();
    exit(0);
}

int main() {
    // Open the I2C device
    int i2c_fd = gpio_i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        perror("gpio_i2c_open");
        return 1;
    }

    // Open the log file
    log_file = fopen("airflow.log", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the SDP810 sensor
        uint8_t data[9];
        if (sdp810_read_data(i2c_fd, data) < 0) {
            // If the sensor is absent or there's an I2C error, wait 1 second and try again
            usleep(1000000);
            continue;
        }

        // Extract the differential pressure and temperature from the data
        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];

        // Log the reading to the file
        fprintf(log_file, "%lu,%d,%d\n", time(NULL), pressure, temperature);

        // Print a warning if the pressure exceeds 5.0 Pa
        if (pressure > 5000) {
            fprintf(stderr, "Pressure exceeds 5.0 Pa: %d Pa\n", pressure);
        }

        // Wait 1 second before the next reading
        usleep(1000000);
    }

    return 0;
}

