#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4b
#define GPIO_LED 17
#define HYS 0.5

volatile bool running = true;

void cleanup(int sig) {
    running = false;
    gpioSetMode(GPIO_LED, GPIO_MODE_OUTPUT);
    gpioWrite(GPIO_LED, 0);
    close(i2c_fd);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd = -1;
    int ret;

    // Initialize GPIO
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", ret);
        return 1;
    }

    // Set up GPIO LED pin as output
    if ((ret = gpioSetMode(GPIO_LED, GPIO_MODE_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if ((ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to set I2C address: %d\n", errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read temperature from STTS2004
        uint16_t temperature;
        if ((ret = i2c_smbus_read_word_data(i2c_fd, 0x00)) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read failed: %d\n", errno);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            usleep(100000);
            continue;
        }
        temperature = ret;

        // Apply hysteresis
        if (temperature > 28 + HYS && gpioRead(GPIO_LED) == 0) {
            gpioWrite(GPIO_LED, 1);
        } else if (temperature < 27 - HYS && gpioRead(GPIO_LED) == 1) {
            gpioWrite(GPIO_LED, 0);
        }

        // Log temperature
        printf("Temperature: %d°C\n", temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

