        if ((ret = i2c_smbus_read_word_data(i2c_fd, 0x00)) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read failed: %d\n", errno);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            usleep(100000);
            continue;
        }
        temperature = ret;

        // Apply hysteresis
        if (temperature > 28 + HYS && gpioRead(GPIO_LED) == 0) {
            gpioWrite(GPIO_LED, 1);
        } else if (temperature < 27 - HYS && gpioRead(GPIO_LED) == 1) {
            gpioWrite(GPIO_LED, 0);
        }

        // Log temperature
        printf("Temperature: %d°C\n", temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    return 0;
}
