#include <pigpio.h>

// Define the I2C bus and address of the sensor
#define I2C_BUS 1
#define I2C_ADDRESS 0x70

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Release I2C bus
    i2c_close(I2C_BUS);
    // Exit with status code 0
    exit(0);
}

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2c_open");
        exit(1);
    }

    // Initialize I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        i2c_close(i2c_fd);
        exit(1);
    }

    // Open file for logging
    FILE *log_file = fopen("flow_data.txt", "a");
    if (!log_file) {
        perror("fopen");
        i2c_close(i2c_fd);
        exit(1);
    }

    // Define the measurement delay in milliseconds
    const int delay = 45;

    // Main loop
    while (1) {
        // Start measurement
        if (i2c_write(i2c_fd, 0x00, 1) < 0) {
            perror("i2c_write");
            fclose(log_file);
            i2c_close(i2c_fd);
            exit(1);
        }

        // Wait for measurement to complete
        usleep(delay * 1000);

        // Read measurement data
        uint8_t data[9];
        if (i2c_read(i2c_fd, data, 9) < 9) {
            perror("i2c_read");
            fclose(log_file);
            i2c_close(i2c_fd);
            exit(1);
        }

        // Validate CRC-8 for differential pressure
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "Invalid CRC-8 for differential pressure\n");
            continue;
        }

        // Validate CRC-8 for temperature
        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Invalid CRC-8 for temperature\n");
            continue;
        }

        // Validate CRC-8 for scale-factor data
        if (crc8(data + 6, 3) != data[8]) {
            fprintf(stderr, "Invalid CRC-8 for scale-factor data\n");
            continue;
        }

        // Extract measured values
        int16_t pressure = (data[0] << 8) | data[1];
        int16_t temperature = (data[3] << 8) | data[4];
        uint16_t scale_factor = (data[6] << 8) | (data[7] << 4) | (data[8] >> 4);

        // Log measured values
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pressure / 100.0, temperature / 100.0, scale_factor / 100.0);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus and log file
    fclose(log_file);
    i2c_close(i2c_fd);

    return 0;
