#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define LOG_FILE "environment.log"
#define LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define LOG_FILE_PERMS (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SDA_PIN 2
#define SCL_PIN 3
#define MEASURE_RH_NO_HOLD 0xE5
#define MEASURE_TEMP_NO_HOLD 0xE3
#define MEASURE_TEMP_FROM_RH 0xE7
#define RETRY_COUNT 3

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

static void sigterm_handler(int sig) {
    cleanup();
    exit(0);
}

static int i2c_open(void) {
    struct i2c_dev *i2c_dev;
    int retry = 0;
    while (retry < RETRY_COUNT) {
        i2c_dev = i2c_open(I2C_BUS);
        if (i2c_dev != NULL) {
            i2c_fd = i2c_open(I2C_BUS);
            if (i2c_fd >= 0) {
                return 0;
            }
            i2c_close(i2c_dev);
        }
        retry++;
        usleep(100000);
    }
    fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
    return -1;
}

static int i2c_write_byte(uint8_t byte) {
    int retry = 0;
    while (retry < RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == 0) {
            if (write(i2c_fd, &byte, 1) == 1) {
                return 0;
            }
        }
        retry++;
        usleep(100000);
    }
    fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
    return -1;
}

static int i2c_read_byte(uint8_t *byte) {
    int retry = 0;
    while (retry < RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == 0) {
            if (read(i2c_fd, byte, 1) == 1) {
                return 0;
            }
        }
        retry++;
        usleep(100000);
    }
    fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
    return -1;
}

static int i2c_read_bytes(uint8_t *buffer, int count) {
    int retry = 0;
    while (retry < RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == 0) {
            if (read(i2c_fd, buffer, count) == count) {
                return 0;
            }
        }
        retry++;
        usleep(100000);
    }
    fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
    return -1;
}

static int read_eid(void) {
    uint8_t buffer[2];
    if (i2c_write_byte(0x00) < 0) {
        return -1;
    }
    if (i2c_read_bytes(buffer, 2) < 0) {
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

static int read_firmware_revision(void) {
    uint8_t buffer[2];
    if (i2c_write_byte(0x00) < 0) {
        return -1;
    }
    if (i2c_read_bytes(buffer, 2) < 0) {
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

static int read_temperature(void) {
    uint8_t buffer[3];
    if (i2c_write_byte(MEASURE_TEMP_NO_HOLD) < 0) {
        return -1;
    }
    usleep(200000);
    if (i2c_read_bytes(buffer, 3) < 0) {
        return -1;
    }
    return ((buffer[0] << 8) | buffer[1]) >> 4;
}

static int read_humidity(void) {
    uint8_t buffer[3];
    if (i2c_write_byte(MEASURE_RH_NO_HOLD) < 0) {
        return -1;
    }
    usleep(200000);
    if (i2c_read_bytes(buffer, 3) < 0) {
        return -1;
    }
    return ((buffer[0] << 8) | buffer[1]) >> 4;
}

static int read_temperature_from_rh(void) {
    uint8_t buffer[3];
    if (i2c_write_byte(MEASURE_TEMP_FROM_RH) < 0) {
        return -1;
    }
    if (i2c_read_bytes(buffer, 3) < 0) {
        return -1;
    }
    return ((buffer[0] << 8) | buffer[1]) >> 4;
}

static void log_reading(double temperature, double humidity) {
    char buffer[256];
    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.2f,%.2f\n", buffer, temperature, humidity);
    fprintf(stderr, "%s,%.2f,%.2f\n", buffer, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }
    if (i2c_open() < 0) {
        return 1;
    }
    if (access(LOG_FILE, F_OK) == 0) {
        if (unlink(LOG_FILE) < 0) {
            fprintf(stderr, "Error removing existing log file: %s\n", strerror(errno));
            return 1;
        }
    }
    if (access(LOG_FILE, F_OK) == -1) {
        if (creat(LOG_FILE, LOG_FILE_MODE) < 0) {
            fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
            return 1;
        }
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    fchmod(fileno(log_file), LOG_FILE_PERMS);
    fchown(fileno(log_file), getuid(), getpwnam("pi")->pw_gid);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    while (1) {
        double temperature, humidity;
        if (read_eid() != 0x00) {
            time_t now = time(NULL);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(stderr, "%s: Error: Sensor not present\n", buffer);
            fclose(log_file);
            return 1;
        }
        if (read_firmware_revision() != 0x10) {
            time_t now = time(NULL);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(stderr, "%s: Error: Firmware revision mismatch\n", buffer);
            fclose(log_file);
            return 1;
        }
        temperature = read_temperature();
        humidity = read_humidity();
        log_reading(temperature, humidity);
        sleep(60);
    }
    return 0;
}

