#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

// Define the I2C bus and address of the sensor
#define I2C_BUS 1
#define I2C_ADDRESS 0x70

// Define the polynomial and initial value for CRC-8
#define CRC_POLYNOMIAL 0x1D
#define CRC_INIT 0x00

// Define the scale factor for the pressure and temperature
#define PRESSURE_SCALE 0.0009765625
#define TEMPERATURE_SCALE 0.0625

// Function to calculate the CRC-8
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read the sensor data
int read_sensor_data(gpiod_chip_t *chip, uint8_t *data) {
    // Trigger a measurement
    gpiod_line_request_output(chip, "PWR", GPIOD_LINE_ACTIVE_HIGH);
    usleep(50 * 1000);
    gpiod_line_request_output(chip, "PWR", GPIOD_LINE_LOW);

    // Read the 9-byte result
    int ret = gpiod_i2c_read(chip, I2C_ADDRESS, 0x00, data, 9);
    if (ret < 0) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Validate the CRC-8
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "Error: Invalid CRC-8\n");
        return -1;
    }

    crc = crc8(data + 4, 2);
    if (crc != data[6]) {
        fprintf(stderr, "Error: Invalid CRC-8\n");
        return -1;
    }

    return 0;
}

// Function to log the data to a file
void log_data(double pressure, double temperature) {
    FILE *file = fopen("hvac_pressure_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(file, "%lu,%f,%f\n", tv.tv_sec, pressure, temperature);
    fclose(file);
}

int main() {
    // Initialize the I2C bus
    gpiod_chip_t *chip;
    int ret = gpiod_chip_open(I2C_BUS, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the GPIO lines
    ret = gpiod_line_request_output(chip, "PWR", GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error requesting PWR line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    FILE *file = fopen("hvac_pressure_log.txt", "w");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t data[9];
        ret = read_sensor_data(chip, data);
        if (ret < 0) {
            continue;
        }

        // Convert the pressure and temperature to double
        double pressure = (data[0] << 8 | data[1]) * PRESSURE_SCALE;
        double temperature = (data[4] << 8 | data[5]) * TEMPERATURE_SCALE;

        log_data(pressure, temperature);

        // Wait for 1 second
        struct timeval tv;
        gettimeofday(&tv, NULL);
        while (tv.tv_sec < tv.tv_sec + 1) {
            fd_set read_fds;
            FD_ZERO(&read_fds);
            FD_SET(STDIN_FILENO, &read_fds);
            struct timeval timeout;
            timeout.tv_sec = 1;
            timeout.tv_usec = 0;
            ret = select(STDIN_FILENO + 1, &read_fds, NULL, NULL, &timeout);
            if (ret > 0) {
                break;
            }
            gettimeofday(&tv, NULL);
        }
    }

    // Clean up
    gpiod_line_release(chip, "PWR");
    gpiod_chip_close(chip);
    fclose(file);
    gpiod_cleanup();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    gpiod_line_release(gpiod_chip_get_handle(), "PWR");
    gpiod_chip_close(gpiod_chip_get_handle());
    fclose(fopen("hvac_pressure_log.txt", "a"));
    gpiod_cleanup();
    exit(0);
}

// Register the signal handler
void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}

