#include <linux/i2c.h>

// Define the I2C bus and address for the SCD40 sensor
#define SCD40_I2C_BUS 1
#define SCD40_I2C_ADDRESS 0x61

// Define the size of the circular buffer
#define BUFFER_SIZE 100

// Define the logging directory and file paths
#define LOG_DIR "/var/log/scd40_data"
#define LOG_ERROR_FILE "/var/log/scd40_error.log"
#define LOG_DATA_FILE "/var/log/scd40_data/scd40_data.csv"

// Define the CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x1D
#define CRC_INITIAL_VALUE 0x00

// Define the SCD40 commands
#define SCD40_START_PERIODIC_MEASUREMENT 0x02
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x03

// Define the SCD40 register addresses
#define SCD40_REGISTER_STATUS 0x00
#define SCD40_REGISTER_MEASUREMENT 0x01

// Define the SCD40 measurement data structure
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    uint8_t crc;
} scd40_measurement_t;

// Define the circular buffer structure
typedef struct {
    scd40_measurement_t data[BUFFER_SIZE];
    int head;
    int tail;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Define the logging thread function
void* log_thread(void* arg) {
    circular_buffer_t* buffer = (circular_buffer_t*) arg;
    FILE* log_file = fopen(LOG_DATA_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return NULL;
    }
    while (1) {
        pthread_mutex_lock(&buffer->mutex);
        if (buffer->head == buffer->tail) {
            pthread_mutex_unlock(&buffer->mutex);
            usleep(60000000); // 60 seconds
            continue;
        }
        for (int i = buffer->tail; i != buffer->head; i = (i + 1) % BUFFER_SIZE) {
            fprintf(log_file, "%lu,%d,%d,%d\n", time(NULL), buffer->data[i].co2, buffer->data[i].temperature, buffer->data[i].humidity);
        }
        buffer->tail = (buffer->tail + BUFFER_SIZE - (buffer->head - buffer->tail)) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer->mutex);
        if (fclose(log_file) != 0) {
            syslog(LOG_ERR, "Failed to close log file: %s", strerror(errno));
        }
        return NULL;
    }
}

// Define the main function
int main() {
    // Initialize the logging system
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Create the log directory if it does not exist
    mkdir(LOG_DIR, 0755);
    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create log directory: %s", strerror(errno));
        return 1;
    }

    // Initialize the circular buffer
    circular_buffer_t buffer;
    buffer.head = 0;
    buffer.tail = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    // Create the logging thread
    pthread_t log_thread_id;
    if (pthread_create(&log_thread_id, NULL, log_thread, &buffer) != 0) {
        syslog(LOG_ERR, "Failed to create logging thread: %s", strerror(errno));
        return 1;
    }

    // Open the I2C device
    int i2c_fd = open("/dev/i2c-" + SCD40_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Start periodic measurement
    uint8_t start_command = SCD40_START_PERIODIC_MEASUREMENT;
    if (write(i2c_fd, &start_command, 1) != 1) {
        syslog(LOG_ERR, "Failed to start periodic measurement: %s", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wait for 1 second before reading the first measurement
    usleep(1000000);

    // Main loop
    volatile sig_atomic_t running = 1;
    signal(SIGINT, SIG_IGN);
    while (running) {
        // Read the status register
        uint8_t status;
        if (read(i2c_fd, &status, 1) != 1) {
            syslog(LOG_ERR, "Failed to read status register: %s", strerror(errno));
            continue;
        }

        // Check if a measurement is available
        if (status & 0x01) {
            // Read the measurement data
            scd40_measurement_t measurement;
            if (read(i2c_fd, &measurement, sizeof(measurement)) != sizeof(measurement)) {
                syslog(LOG_ERR, "Failed to read measurement data: %s", strerror(errno));
                continue;
            }

            // Validate the CRC-8
            uint8_t crc = 0;
