// Function to calculate the CRC-8
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read from the I2C bus
int i2c_read(int fd, uint8_t *data, size_t len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = SDP810_ADDRESS;
    msgs->flags = 0;
    msgs->len = len;
    msgs->buf = data;
    int ret = i2c_transfer(I2C_BUS, msgs, 1);
    if (ret < 0) {
        perror("i2c_transfer");
        return -1;
    }
    return 0;
}

// Function to write to the I2C bus
int i2c_write(int fd, uint8_t *data, size_t len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = SDP810_ADDRESS;
    msgs->flags = I2C_M_WR;
    msgs->len = len;
    msgs->buf = data;
    int ret = i2c_transfer(I2C_BUS, msgs, 1);
    if (ret < 0) {
        perror("i2c_transfer");
        return -1;
    }
    return 0;
}

// Function to handle SIGINT
void sigint_handler(int sig) {
    // Close the I2C handle
    close(i2c_fd);
    // Terminate any driver resources
    i2c_close(i2c_fd);
    // Close the log file
    fclose(log_file);
    // Exit cleanly
    exit(0);
}

int main() {
    // Open the I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the SDP810 sensor
    uint8_t init_cmd[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (i2c_write(i2c_fd, init_cmd, 9) < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the measurement
        uint8_t trigger_cmd[] = {0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
