        uint8_t data[NUM_BYTES];
        if (i2c_read(i2c_fd, data, NUM_BYTES) < 0) {
            continue;
        }

        // Validate the CRC-8
        if (calculate_crc8(data, 2) != data[8] || calculate_crc8(data + 2, 2) != data[10] || calculate_crc8(data + 4, 2) != data[12]) {
            fprintf(log_file, "CRC failure\n");
            continue;
        }

        // Extract the data
        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];
        uint16_t scale_factor = (data[4] << 8) | data[5];

        // Log the data
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld,%d,%d\n", tv.tv_sec, pressure, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close the I2C handle
    close(i2c_fd);

    // Terminate any driver resources
    i2c_close(i2c_fd);

    // Close the log file
    fclose(log_file);

    return 0;
}

