#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define FILE_NAME "environmental_data.txt"
#define SLEEP_TIME 5000  // 5 seconds
#define READ_DELAY 10  // 10 ms

// Flag to exit the loop
bool exit_flag = false;

// Function to handle SIGINT
void sigint_handler(int sig) {
    exit_flag = true;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = gpioOpen(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C bus
    struct i2c_msg msg;
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = NULL;

    // Open the file for writing
    FILE *file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!exit_flag) {
        // Wait for 5 seconds
        usleep(SLEEP_TIME * 1000);

        // Wait for 10 ms
        usleep(READ_DELAY * 1000);

        // Read the temperature and pressure
        msg.buf = malloc(2);
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            fprintf(stderr, "Failed to set I2C slave address\n");
            free(msg.buf);
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        if (i2c_transfer(i2c_fd, &msg, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            free(msg.buf);
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert the data to temperature and pressure
        uint16_t temp = (msg.buf[0] << 8) | msg.buf[1];
        float pressure = (temp / 32768.0) * 10.0;

        // Get the current time
        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t t = tv.tv_sec;
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        // Write the data to the file and stdout
        fprintf(file, "%s %.2f %.2f\n", timestamp, pressure, (float)temp / 10.0);
        fflush(file);
        printf("%s %.2f %.2f\n", timestamp, pressure, (float)temp / 10.0);

        free(msg.buf);
    }

    // Close the I2C handle
    gpioClose(i2c_fd);

    // Close the file
    fclose(file);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

