    int i2c_fd = -1;
    int gpio_fd = -1;
    uint8_t buffer[6];

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("Failed to initialize GPIO");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO LED as output
    if (gpioSetMode(gpio_fd, GPIO_LED, GPIO_MODE_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read from I2C bus
        if (i2c_smbus_read_byte_data(i2c_fd, 0x00, buffer) < 0) {
            perror("Failed to read from I2C bus");
            close(i2c_fd);
            gpioTerminate(gpio_fd);
            exit(EXIT_FAILURE);
        }

        // Check CRC
        if (buffer[4] != (buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3]) & 0xFF ||
            buffer[5] != (buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3]) >> 8) {
            printf("CRC error\n");
            continue;
        }

        // Check sensor absent or bus error
        if (buffer[0] == 0xFF) {
            printf("Sensor absent or bus error\n");
            continue;
        }

        // Check pressure threshold
        if (buffer[0] * 256 + buffer[1] < PRESSURE_THRESHOLD) {
            // Blink LED at 5 Hz
            gpioWrite(gpio_fd, GPIO_LED, 1);
            usleep(LED_ON_TIME * 1000);
            gpioWrite(gpio_fd, GPIO_LED, 0);
            usleep(LED_OFF_TIME * 1000);
        } else {
            // Blink LED at 1 Hz
            gpioWrite(gpio_fd, GPIO_LED, 1);
            usleep(LED_ON_TIME * 1000);
            gpioWrite(gpio_fd, GPIO_LED, 0);
            usleep(LED_OFF_TIME * 1000);
        }

        // Delay
        usleep(DELAY * 1000);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Release GPIO line
    gpioTerminate(gpio_fd);

    return 0;
}

