#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDRESS 0x44
#define MEASUREMENT_COMMAND 0x00
#define READ_DATA_COMMAND 0x00
#define SHT40_RETRY_COUNT 3

// Function to handle signal interrupts
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Cleanly release all resources
        gpioTerminate();
        close(httpd_socket);
        close(i2c_fd);
        exit(0);
    }
}

// Function to read data from the SHT40 sensor
int read_sht40_data(int i2c_fd, uint8_t *data) {
    int retry_count = 0;
    while (retry_count < SHT40_RETRY_COUNT) {
        if (i2c_master_send(i2c_fd, SHT40_ADDRESS, &MEASUREMENT_COMMAND, 1, 100) == 0) {
            usleep(10000); // Wait at least 10ms
            if (i2c_master_recv(i2c_fd, SHT40_ADDRESS, data, 6, 100) == 0) {
                return 0;
            }
        }
        retry_count++;
    }
    return -1;
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus speed to 100 kHz
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C bus speed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Create a socket for the HTTP server
    httpd_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (httpd_socket < 0) {
        fprintf(stderr, "Failed to create socket\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Bind the socket to port 8080
    struct sockaddr_in httpd_addr;
    httpd_addr.sin_family = AF_INET;
    httpd_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &httpd_addr.sin_addr);
    if (bind(httpd_socket, (struct sockaddr *)&httpd_addr, sizeof(httpd_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        close(httpd_socket);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(httpd_socket, 1) < 0) {
        fprintf(stderr, "Failed to listen for connections\n");
        close(httpd_socket);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Accept incoming connections
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(httpd_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            continue;
        }

        // Read data from the SHT40 sensor
        uint8_t data[6];
        if (read_sht40_data(i2c_fd, data) < 0) {
            // If the sensor is not present or the bus is busy, send an error message
            char error_message[] = "Error reading from SHT40 sensor";
            send(client_fd, error_message, strlen(error_message), 0);
            close(client_fd);
            continue;
        }

        // Extract temperature and humidity values
        uint16_t temperature = (data[0] << 8) | data[1];
        uint16_t humidity = (data[3] << 8) | data[4];

        // Clamp humidity to the range 0-100%
        if (humidity > 100) {
            humidity = 100;
        } else if (humidity < 0) {
            humidity = 0;
        }

        // Create an HTML page with the current temperature and humidity values
        char html_page[] = "<html><body><h1>Temperature: %d°C, Humidity: %d%%</h1></body></html>";
        char buffer[100];
        sprintf(buffer, html_page, temperature / 100, humidity);
        send(client_fd, buffer, strlen(buffer), 0);

        // Close the client socket
        close(client_fd);
    }

    // Cleanly release all resources
    close(httpd_socket);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

