    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open CSV file for appending
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up measurement loop
    struct timeval last_measurement;
    gettimeofday(&last_measurement, NULL);
    while (running) {
        // Read temperature
        uint16_t temperature;
        if (i2c_read(i2c_fd, &temperature, 2) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue;
        }

        // Convert temperature to Celsius
        float temp_celsius = (float)temperature / 256.0;

        // Get current time
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        // Format timestamp
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));

        // Append to CSV file
        fprintf(csv_file, "%s,%.2f\n", timestamp, temp_celsius);

        // Sleep until next measurement
        struct timeval next_measurement;
        next_measurement.tv_sec = last_measurement.tv_sec + (MEASUREMENT_INTERVAL / 1000000);
        next_measurement.tv_usec = last_measurement.tv_usec + (MEASUREMENT_INTERVAL % 1000000);
        if (next_measurement.tv_usec >= 1000000) {
            next_measurement.tv_sec++;
            next_measurement.tv_usec -= 1000000;
        }
        while (gettimeofday(&current_time, NULL) && current_time.tv_sec < next_measurement.tv_sec || current_time.tv_sec == next_measurement.tv_sec && current_time.tv_usec < next_measurement.tv_usec);

        last_measurement = current_time;
    }

    // Close I2C handle
    gpioClose(i2c_fd);

    // Close CSV file
    fclose(csv_file);

    // Terminate GPIO library
    gpioTerminate();

    return EXIT_SUCCESS;
}
