    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        // Clear MEASUREMENT_CONFIG register
        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.buf = NULL;
        msg.len = 0;
        i2c_data.msgs = &msg;
        i2c_data.nmsgs = 1;
        i2c_data.nbytes = 0;
        i2c_data.flags = 0;

        while (1) {
            // Read MEASUREMENT_CONFIG register
            msg.addr = I2C_ADDRESS;
            msg.flags = 0;
            msg.buf = &data[0];
            msg.len = 1;
            i2c_data.msgs = &msg;
            i2c_data.nmsgs = 1;
            i2c_data.nbytes = 1;
            i2c_data.flags = 0;

            if ((result = ioctl(i2c_fd, I2C_RDWR, &i2c_data)) < 0) {
                if (errno == EIO) {
                    // Transient I2C failure, retry
                    if (retries < MAX_RETRIES) {
                        retries++;
                        usleep(timeout * 1000);
                        continue;
