        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.buf = &data[0];
        msg.len = 2;
        i2c_data.msgs = &msg;
        i2c_data.nmsgs = 1;
        i2c_data.nbytes = 2;
        i2c_data.flags = 0;

        if ((result = ioctl(i2c_fd, I2C_RDWR, &i2c_data)) < 0) {
            if (errno == EIO) {
                // Transient I2C failure, retry
                if (retries < MAX_RETRIES) {
                    retries++;
                    usleep(timeout * 1000);
                    continue;
                } else {
                    // Maximum retries exceeded, exit
                    perror("Failed to read temperature and humidity");
                    close(i2c_fd);
                    exit(EXIT_FAILURE);
                }
            } else if (errno == EBUSY) {
                // Bus error, exit
                perror("Bus error");
                close(i2c_fd);
                exit(EXIT_FAILURE);
            } else {
                // Other error, exit
                perror("Failed to read temperature and humidity");
                close(i2c_fd);
                exit(EXIT_FAILURE);
            }
        }

        // Print temperature and humidity
        printf("Temperature: %d.%02d°C, Humidity: %d.%02d%%\n",
               (data[TEMPERATURE_MSB] << 8) | data[TEMPERATURE_LSB],
               (data[TEMPERATURE_LSB] & 0x0F),
               (data[HUMIDITY_MSB] << 8) | data[HUMIDITY_LSB],
               (data[HUMIDITY_LSB & 0x0F));

        // Wait 5 seconds
        usleep(5000000);
    }

    // Close I2C handle
    close(i2c_fd);

    // Call library's API call() before exiting
    gpioInitialise();
    gpioTerminate();

    return 0;
