#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define PRESSURE_REGISTER 0x00
#define TEMPERATURE_REGISTER 0x01
#define CRC_POLYNOMIAL 0x1D
#define CRC_INITIAL_VALUE 0x00

#define PRESSURE_REGISTER_SIZE 2
#define TEMPERATURE_REGISTER_SIZE 3

#define MEASUREMENT_DELAY 45000
#define LOG_INTERVAL 500000

volatile bool running = true;

void cleanup() {
    gpiod_cleanup();
    close(i2c_fd);
}

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }

    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod library");
        close(i2c_fd);
        exit(1);
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        gpiod_cleanup();
        exit(1);
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpiod_cleanup();
        exit(1);
    }

    gpiod_line_request_output(line, 0);
    gpiod_line_set_value(line, 1);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpiod_cleanup();
        exit(1);
    }

    while (running) {
        uint8_t buffer[PRESSURE_REGISTER_SIZE + TEMPERATURE_REGISTER_SIZE + 2];
        if (i2c_smbus_write_byte_data(i2c_fd, PRESSURE_REGISTER, 0x00) < 0) {
            perror("Failed to write to pressure register");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            gpiod_cleanup();
            exit(1);
        }

        usleep(MEASUREMENT_DELAY);

        if (i2c_smbus_read_i2c_block_data(i2c_fd, PRESSURE_REGISTER, PRESSURE_REGISTER_SIZE, buffer) < 0) {
            perror("Failed to read from pressure register");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            gpiod_cleanup();
            exit(1);
        }

        if (buffer[0] != 0x00 || buffer[1] != 0x00) {
            fprintf(stderr, "Invalid pressure data\n");
            continue;
        }

        uint8_t crc = buffer[PRESSURE_REGISTER_SIZE];
        uint8_t calculated_crc = 0;
        for (int i = 0; i < PRESSURE_REGISTER_SIZE; i++) {
            calculated_crc = (calculated_crc ^ buffer[i]) ^ (calculated_crc >> 1);
        }
        if (calculated_crc != crc) {
            fprintf(stderr, "Invalid pressure CRC\n");
            continue;
        }

        uint16_t pressure = (buffer[0] << 8) | buffer[1];

        if (i2c_smbus_write_byte_data(i2c_fd, TEMPERATURE_REGISTER, 0x00) < 0) {
            perror("Failed to write to temperature register");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            gpiod_cleanup();
            exit(1);
        }

        usleep(MEASUREMENT_DELAY);

        if (i2c_smbus_read_i2c_block_data(i2c_fd, TEMPERATURE_REGISTER, TEMPERATURE_REGISTER_SIZE, buffer) < 0) {
            perror("Failed to read from temperature register");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            gpiod_cleanup();
            exit(1);
        }

        if (buffer[0] != 0x00 || buffer[1] != 0x00 || buffer[2] != 0x00) {
            fprintf(stderr, "Invalid temperature data\n");
            continue;
        }

        uint8_t crc = buffer[TEMPPERATURE_REGISTER_SIZE];
        calculated_crc = 0;
        for (int i = 0; i < TEMPERATURE_REGISTER_SIZE; i++) {
            calculated_crc = (calculated_crc ^ buffer[i]) ^ (calculated_crc >> 1);
        }
        if (calculated_crc != crc) {
            fprintf(stderr, "Invalid temperature CRC\n");
            continue;
        }

        uint16_t temperature = (buffer[0] << 8) | buffer[1];

        printf("Pressure: 0x%04x, Temperature: 0x%04x\n", pressure, temperature);

        usleep(LOG_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    gpiod_cleanup();

    return 0;
}

