#define PID_KP 10.0
#define PID_KI 0.1
#define PID_KD 0.0
#define PID_DT 0.01
#define PID_INT_MAX 1000.0
#define PID_INT_MIN -1000.0

typedef struct {
    double kp;
    double ki;
    double kd;
    double dt;
    double integral;
    double last_error;
    double last_input;
} pid_t;

pid_t pid;

void pid_init(pid_t *p, double kp, double ki, double kd, double dt) {
    p->kp = kp;
    p->ki = ki;
    p->kd = kd;
    p->dt = dt;
    p->integral = 0.0;
    p->last_error = 0.0;
    p->last_input = 0.0;
}

double pid_update(pid_t *p, double input, double target) {
    double error = target - input;
    p->integral += error * p->ki * p->dt;
    if (p->integral > PID_INT_MAX) {
        p->integral = PID_INT_MAX;
    } else if (p->integral < PID_INT_MIN) {
        p->integral = PID_INT_MIN;
    }
    double derivative = (error - p->last_error) / p->dt;
    double output = p->kp * error + p->integral + p->kd * derivative;
    p->last_error = error;
    p->last_input = input;
    return output;
}

int main() {
    int spi_fd;
    int gpio_fd;
    int profile_fd;
    char line[256];
    double target_temp;
    double time;
    double last_time;
    double last_output;
    double temperature;
    double output;
    FILE *log_file;
    struct spi_ioc_transfer transfer;
    struct gpio_handle *gpio_handle;
    struct gpio_config gpio_config;
    struct gpio_config gpio_config_ss;
    struct gpio_config gpio_config_ssr;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Configure SPI
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = NULL;
    transfer.rx_buf = NULL;
    transfer.len = 2;
    transfer.speed = SPI_SPEED;
    transfer.delay_usecs = 0;
    transfer.cs_change = 1;
    transfer.bits_per_word = SPI_BITS;
    transfer.mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &transfer.mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Initialize PID
    pid_init(&pid, PID_KP, PID_KI, PID_KD, PID_DT);

