    profile_fd = open(PROFILE_FILE, O_RDONLY);
    if (profile_fd < 0) {
        fprintf(stderr, "Failed to open profile file\n");
        fclose(log_file);
        close(spi_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

