            gpioTerminate(gpio_fd);
            return 1;
        }
        // Log temperature
        fprintf(log_file, "%f,%f\n", time, temperature);
        // Wait for next time step
        usleep((time - last_time) * 1000000);
        last_time = time;
    }

    // Close profile file
    close(profile_fd);

