        // Update SSR duty cycle
        gpio_config_ssr.mode = GPIO_MODE_OUTPUT;
        gpio_config_ssr.value = (int) (output * 255);
        if (gpioSetMode(gpio_fd, SSR_PIN, GPIO_MODE_OUTPUT) < 0) {
