            close(spi_fd);
            fclose(log_file);
            gpioTerminate(gpio_fd);
            return 1;
        }
        if (gpioServo(gpio_fd, SSR_PIN, gpio_config_ssr.value) < 0) {
            fprintf(stderr, "Failed to set SSR duty cycle\n");
            close(spi_fd);
            fclose(log_file);
            gpioTerminate(gpio_fd);
            return 1;
        }
        // Log temperature
        fprintf(log_file, "%f,%f\n", last_time, temperature);
        // Wait for next time step
        usleep(1000000);
        last_time += 1.0;
    }

    // Close log file
    fclose(log_file);

    // Close SPI device
    close(spi_fd);

    // Terminate GPIO
    gpioTerminate(gpio_fd);

    return 0;
}

