        syslog(LOG_ERR, "Failed to get relay line.");
        exit(1);
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        syslog(LOG_ERR, "Failed to get PWM line.");
        exit(1);
    }

    if (gpiod_line_request_output(relay_line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output.");
        exit(1);
    }

    if (gpiod_line_request_output(pwm_line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to request PWM line as output.");
        exit(1);
    }

    if (gpiod_line_export(relay_line) < 0) {
        syslog(LOG_ERR, "Failed to export relay line.");
        exit(1);
    }

    if (gpiod_line_export(pwm_line) < 0) {
        syslog(LOG_ERR, "Failed to export PWM line.");
        exit(1);
    }

    if (gpiod_line_direction_set(relay_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set relay line direction.");
        exit(1);
    }

    if (gpiod_line_direction_set(pwm_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set PWM line direction.");
        exit(1);
    }

    if (gpiod_line_value_set(relay_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay line value.");
        exit(1);
    }

    if (gpiod_line_value_set(pwm_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM line value.");
        exit(1);
    }
}

void init_pwm() {
    if (pwm_fd = open("/dev/pwm/0", O_RDWR) < 0) {
        syslog(LOG_ERR, "Failed to open PWM device.");
        exit(1);
    }

    if (ioctl(pwm_fd, PWM_IOCTL_SET_PARAMS, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM parameters.");
        exit(1);
    }

    if (ioctl(pwm_fd, PWM_IOCTL_ENABLE, 0) < 0) {
        syslog(LOG_ERR, "Failed to enable PWM.");
        exit(1);
    }
}

void init_temp() {
    if (temp_fd = open(TEMP_FILE, O_RDONLY) < 0) {
        syslog(LOG_ERR, "Failed to open temperature file.");
        exit(1);
    }
}

void read_temp() {
    char buffer[64];
    ssize_t bytes_read;

    if ((bytes_read = read(temp_fd, buffer, 64)) < 0) {
        syslog(LOG_ERR, "Failed to read temperature file.");
        exit(1);
    }

    if (bytes_read < 9) {
        syslog(LOG_ERR, "Invalid temperature reading.");
        exit(1);
    }

    char *ptr = buffer;
    while (*ptr != '\n') {
        ptr++;
    }

    ptr++;
    while (*ptr != '\n') {
        ptr++;
    }

    double temp = atof(ptr);
    if (temp < -40.0 || temp > 125.0) {
        syslog(LOG_ERR, "Invalid temperature reading.");
        exit(1);
    }

    pid.setpoint = temp;
}

void pid_control() {
    double error = pid.setpoint - pid.integral / pid.Ki;
    pid.integral += error * 0.01;
    double derivative = (error - pid.last_error) / 0.01;
    pid.last_error = error;

    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    if (output > 1.0) {
        output = 1.0;
    } else if (output < 0.0) {
        output = 0.0;
    }

    if (output > 0.5) {
        gpiod_line_value_set(relay_line, 1);
    } else {
        gpiod_line_value_set(relay_line, 0);
    }

    if (output > 0.0) {
        if (ioctl(pwm_fd, PWM_IOCTL_SET_DUTY, output * 100) < 0) {
            syslog(LOG_ERR, "Failed to set PWM duty cycle.");
            exit(1);
        }
    } else {
        if (ioctl(pwm_fd, PWM_IOCTL_SET_DUTY, 0) < 0) {
            syslog(LOG_ERR, "Failed to set PWM duty cycle.");
            exit(1);
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 5) {
        syslog(LOG_ERR, "Usage: %s <setpoint> <Kp> <Ki> <Kd>", argv[0]);
        exit(1);
    }

    pid.Kp = atof(argv[2]);
    pid.Ki = atof(argv[3]);
    pid.Kd = atof(argv[4]);
    pid.setpoint = atof(argv[1]);

    if (pid.Kp <= 0.0 || pid.Ki <= 0.0 || pid.Kd <= 0.0) {
        syslog(LOG_ERR, "Invalid PID gains.");
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler.");
        exit(1);
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler.");
        exit(1);
    }

    openlog("greenhouse", LOG_PID | LOG_PERROR, LOG_INFO);

    init_gpio();
    init_pwm();
    init_temp();

    struct timeval last_log;
    gettimeofday(&last_log, NULL);

    while (1) {
        read_temp();
        pid_control();

        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_log.tv_sec >= 5) {
            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                syslog(LOG_ERR, "Failed to open log file.");
                exit(1);
            }

            fprintf(log_file, "%ld.%06ld %f %f %f %f\n", now.tv_sec, now.tv_usec, pid.integral / pid.Ki, pid.setpoint, gpiod_line_value_get(pwm_line));
            fclose(log_file);

            last_log = now;
        }

        usleep(100000);
    }

    return 0;
}
