#define HUMIDITY_THRESHOLD_LOW 55

#define I2C_RETRY(func, ...) do { \
    int retry = 0; \
    while (retry < MAX_RETRIES) { \
        if (func(__VA_ARGS__)) { \
            break; \
        } \
        retry++; \
        usleep(RETRY_DELAY_MS * 1000); \
    } \
    if (retry == MAX_RETRIES) { \
        fprintf(stderr, "Failed to %s I2C transaction after %d retries\n", #func, MAX_RETRIES); \
    } \
} while (0)

