    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, AHT20_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return 1;
    }

    while (1) {
        I2C_RETRY(ioctl, i2c_file, I2C_SLAVE, AHT20_ADDRESS);
        I2C_RETRY(write, i2c_file, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        usleep(MEASUREMENT_DELAY_US / 1000);
        uint8_t data[6];
        I2C_RETRY(read, i2c_file, data, 6);
