            fprintf(stderr, "AHT20 status byte indicates calibration failed\n");
            continue;
        }
        if (data[0] & 0x40) {
            fprintf(stderr, "AHT20 status byte indicates busy\n");
            continue;
        }
        float humidity = (data[0] << 8 | data[1]) / 65536.0 * 100;
        fprintf(stderr, "%f\n", humidity);
        if (humidity > HUMIDITY_THRESHOLD_HIGH) {
            gpio_write(Relay_GPIO, 1);
        } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
            gpio_write(Relay_GPIO, 0);
        }
        sleep(5);
    }

    return 0;
}

