#define BMP280_DIG_H3 0xE3
#define BMP280_DIG_H4 0xE5
#define BMP280_DIG_H5 0xE7
#define BMP280_DIG_H6 0xE9

#define PRESSURE_LOG_FILE "pressure_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        perror("Failed to read I2C data");
        return -1;
    }
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) {
        perror("Failed to read I2C block data");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, reg, *buf) < 0) {
        perror("Failed to write I2C data");
        return -1;
    }
    if (i2c_smbus_write_i2c_block_data(fd, reg, len, buf) < 0) {
        perror("Failed to write I2C block data");
        return -1;
    }
    return 0;
}

void read_bmp280(int fd) {
    uint8_t chip_id;
    if (i2c_read(fd, 0xD0, &chip_id, 1) < 0) {
        return;
    }
    if (chip_id != BMP280_CHIP_ID) {
        printf("Invalid chip ID: 0x%02x\n", chip_id);
        return;
    }

    uint8_t cal_data[11];
    if (i2c_read(fd, BMP280_DIG_T1, cal_data, 11) < 0) {
        return;
    }

    uint16_t t_fine = 0;
    t_fine = (cal_data[0] << 8) | cal_data[1];
    t_fine = (t_fine << 8) | cal_data[2];
    t_fine = (t_fine << 8) | cal_data[3];
    t_fine = (t_fine >> 4) & 0xFF;
    t_fine = (t_fine << 12) | (cal_data[4] << 4) | (cal_data[5] >> 4);
    t_fine = (t_fine + (cal_data[6] << 20)) >> 4;

    uint32_t p = 0;
    uint16_t p_lsb = 0;
    uint16_t p_msb = 0;
    if (i2c_read(fd, BMP280_PRESSURE_LSB, &p_lsb, 1) < 0) {
        return;
    }
    if (i2c_read(fd, BMP280_PRESSURE_MSB, &p_msb, 1) < 0) {
        return;
    }
    p = (p_msb << 8) | p_lsb;
    p = (p << 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p >> 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p << 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p >> 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));

    float temp = (t_fine / 5120.0) - 45.0;
    float pressure = 1048576.0 - p;
    pressure = (pressure * 100.0) / 256.0;
    pressure = pressure / 100.0;
    pressure = pressure + (temp * 0.0345);

    if (pressure > 1020 || pressure < 980) {
        FILE *file = fopen(PRESSURE_LOG_FILE, "a");
        if (file == NULL) {
            perror("Failed to open pressure log file");
            return;
        }
        fprintf(file, "%f\n", pressure);
        fclose(file);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    while (running) {
        read_bmp280(fd);
        usleep(2000000);
    }

    close(fd);
    gpioTerminate();
    return 0;
}

