    uint16_t p_msb = 0;
    if (i2c_read(fd, BMP280_PRESSURE_LSB, &p_lsb, 1) < 0) {
        return;
    }
    if (i2c_read(fd, BMP280_PRESSURE_MSB, &p_msb, 1) < 0) {
        return;
    }
    p = (p_msb << 8) | p_lsb;
    p = (p << 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p >> 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p << 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));
    p = (p >> 8) | (i2c_read(fd, BMP280_PRESSURE_OS, NULL, 0));

    float temp = (t_fine / 5120.0) - 45.0;
    float pressure = 1048576.0 - p;
    pressure = (pressure * 100.0) / 256.0;
    pressure = pressure / 100.0;
    pressure = pressure + (temp * 0.0345);

    if (pressure > 1020 || pressure < 980) {
        FILE *file = fopen(PRESSURE_LOG_FILE, "a");
        if (file == NULL) {
            perror("Failed to open pressure log file");
            return;
        }
        fprintf(file, "%f\n", pressure);
        fclose(file);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    while (running) {
        read_bmp280(fd);
        usleep(2000000);
    }

    close(fd);
    gpioTerminate();
    return 0;
}
