        fprintf(stderr, "Error reading motion detection: %s\n", gpiod_error());
        return -1;
    }
    return value;
}

int main() {
    int fd;
    struct stat sb;
    struct tm *timeinfo;
    char filename[256];
    char buffer[256];
    int temperature, humidity, motion;

    // Open I2C bus
    fd = i2c_open("/dev/i2c-1");
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Check if log file exists
    if (stat(LOG_FILE, &sb) == 0) {
        // Get current time
        timeinfo = get_current_time();
        // Create new log file if it's a new day
        if (timeinfo->tm_mday != sb.st_mtime) {
            sprintf(filename, "%s_%04d-%02d-%02d.log", LOG_FILE, timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday);
            rename(LOG_FILE, filename);
            fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (fd < 0) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
