        gpiod_chip_close(PIR_CHIP);
        i2c_close(fd);
        return 1;
    }

    // Log header
    fprintf(fd, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");

    while (1) {
        // Get current time
        timeinfo = get_current_time();

        // Read temperature
        temperature = get_temperature(fd);
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature\n");
            gpiod_line_release(PIR_CHIP, PIR_LINE);
            gpiod_chip_close(PIR_CHIP);
            i2c_close(fd);
            return 1;
        }

        // Read humidity
        humidity = get_humidity(fd);
        if (humidity < 0) {
            fprintf(stderr, "Error reading humidity\n");
            gpiod_line_release(PIR_CHIP, PIR_LINE);
            gpiod_chip_close(PIR_CHIP);
            i2c_close(fd);
            return 1;
        }

        // Read motion detection
        motion = get_motion_detection();
        if (motion < 0) {
            fprintf(stderr, "Error reading motion detection\n");
            gpiod_line_release(PIR_CHIP, PIR_LINE);
            gpiod_chip_close(PIR_CHIP);
            i2c_close(fd);
            return 1;
        }

        // Log data
        sprintf(buffer, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                temperature, humidity, motion);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            gpiod_line_release(PIR_CHIP, PIR_LINE);
            gpiod_chip_close(PIR_CHIP);
            i2c_close(fd);
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    gpiod_line_release(PIR_CHIP, PIR_LINE);
    gpiod_chip_close(PIR_CHIP);
    i2c_close(fd);
    return 0;
