#define GPIO17 17
#define GPIO22 22
#define GPIO23 23
#define GPIO24 24

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpiod_close();
    exit(0);
}

int main() {
    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the GPIO chip
    int chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == -1) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Export GPIO lines
    if (gpiod_chip_export(chip, GPIO17, GPIOD_LINE_ACTIVE_LOW) == -1) {
        perror("gpiod_chip_export");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_chip_export(chip, GPIO22, GPIOD_LINE_ACTIVE_LOW) == -1) {
        perror("gpiod_chip_export");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_chip_export(chip, GPIO23, GPIOD_LINE_ACTIVE_LOW) == -1) {
        perror("gpiod_chip_export");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_chip_export(chip, GPIO24, GPIOD_LINE_ACTIVE_LOW) == -1) {
        perror("gpiod_chip_export");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set up the YL-83 rain sensor pin as an input
    int line = gpiod_line_request_output(chip, GPIO17, GPIOD_LINE_ACTIVE_LOW);
    if (line == -1) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set up the motor control pins as outputs
    line = gpiod_line_request_output(chip, GPIO22, GPIOD_LINE_ACTIVE_LOW);
    if (line == -1) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
    line = gpiod_line_request_output(chip, GPIO23, GPIOD_LINE_ACTIVE_LOW);
    if (line == -1) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
    line = gpiod_line_request_output(chip, GPIO24, GPIOD_LINE_ACTIVE_LOW);
    if (line == -1) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set the initial state of the motor control pins to low
    if (gpiod_line_set_value(line, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_set_value(line, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_set_value(line, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the state of the rain sensor
        int value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("gpiod_line_get_value");
            gpiod_line_release(line);
            gpiod_line_release(line);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(1);
        }

        // Check if rain is detected
        if (value == 0) {
            // Log the detection
            struct timeval tv;
            gettimeofday(&tv, NULL);
            printf("%ld.%06ld: Rain detected\n", tv.tv_sec, tv.tv_usec);

            // Start the motor
            if (gpiod_line_set_value(line, 1) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(1);
            }
            if (gpiod_line_set_value(line, 1) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(1);
            }
            if (gpiod_line_set_value(line, 1) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(1);
            }

            // Wait for 5 seconds
            struct timespec ts;
            ts.tv_sec = 5;
            ts.tv_nsec = 0;
            nanosleep(&ts);

            // Stop the motor
            if (gpiod_line_set_value(line, 0) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(1);
