            if (gpiod_line_set_value(line, 0) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(1);
            }
        }

        // Wait for 2 seconds
        struct timespec ts;
        ts.tv_sec = 2;
        ts.tv_nsec = 0;
        nanosleep(&ts);
    }

    // Release the GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
