#define SAMPLE_INTERVAL 500000 // 500ms in microseconds

// Signal handler to turn off the LED and clean up on exit
void sig_handler(int sig) {
    gpioPWM(LED_RED_PIN, 0);
    gpioPWM(LED_GREEN_PIN, 0);
    gpioPWM(LED_BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Function to read CPU load from /proc/stat
int read_cpu_load() {
    FILE *fp;
    char buffer[256];
    int load = 0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the first line of /proc/stat
    char *token;
    token = strtok(buffer, " ");
    if (token == NULL) {
        return -1;
    }

    // The first token is "cpu", so skip it
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the user time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the nice time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the system time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the idle time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the iowait time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the irq time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the softirq time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the steal time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the guest time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // The next token is the guest_nice time
    token = strtok(NULL, " ");
    if (token == NULL) {
        return -1;
    }

    // Calculate the total time
    int user_time = atoi(token);
    int nice_time = atoi(token);
    int system_time = atoi(token);
    int idle_time = atoi(token);
    int iowait_time = atoi(token);
    int irq_time = atoi(token);
    int softirq_time = atoi(token);
    int steal_time = atoi(token);
    int guest_time = atoi(token);
    int guest_nice_time = atoi(token);
    int total_time = user_time + nice_time + system_time + idle_time + iowait_time + irq_time + softirq_time + steal_time + guest_time + guest_nice_time;

    // Calculate the load
    load = (user_time + nice_time + system_time) * 100 / total_time;

    return load;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Set up PWM
    gpioSetMode(LED_RED_PIN, PI_OUTPUT);
    gpioSetMode(LED_GREEN_PIN, PI_OUTPUT);
    gpioSetMode(LED_BLUE_PIN, PI_OUTPUT);
    gpioPWM(LED_RED_PIN, 0);
    gpioPWM(LED_GREEN_PIN, 0);
    gpioPWM(LED_BLUE_PIN, 0);

    // Initialize previous load
    int prev_load = 0;

    while (1) {
        // Read the current load
        int load = read_cpu_load();
        if (load < 0) {
            fprintf(stderr, "Failed to read CPU load\n");
            break;
        }

        // Calculate the color based on the load
        int r, g, b;
        if (load < 50) {
            r = 0;
            g = (load * 2);
            b = 0;
        } else if (load < 100) {
            r = (load - 50) * 2;
            g = 0;
            b = 0;
        } else {
            r = 255;
            g = 0;
            b = 0;
        }

        // Clamp the PWM values
        r = (r < 0) ? 0 : (r > PWM_RANGE) ? PWM_RANGE : r;
        g = (g < 0) ? 0 : (g > PWM_RANGE) : g;
        b = (b < 0) ? 0 : (b > PWM_RANGE) : b;

        // Update the PWM values
        gpioPWM(LED_RED_PIN, r);
        gpioPWM(LED_GREEN_PIN, g);
        gpioPWM(LED_BLUE_PIN, b);

        // Print the load
        printf("Load: %d%%\n", load);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

