#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP280_I2C_ADDRESS 0x76
#define BMP280_PRESSURE_REGISTER 0xF4
#define BMP280_TEMP_REGISTER 0xF5
#define BMP280_PRESSURE_DATA_REGISTER 0xF6
#define BMP280_TEMP_DATA_REGISTER 0xF7
#define BMP280_PRESSURE_DATA_SIZE 3
#define BMP280_TEMP_DATA_SIZE 2
#define UDP_PORT 5000
#define UDP_ADDRESS "192.168.1.100"
#define JSON_FORMAT "{\"temperature\": %f, \"pressure\": %f}"

int i2c_fd;
int udp_socket;
struct sockaddr_in udp_server;
char json_buffer[256];

void sigint_handler(int signal) {
    close(udp_socket);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signal) {
    close(udp_socket);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Failed to create UDP socket\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up UDP server address
    memset(&udp_server, 0, sizeof(udp_server));
    udp_server.sin_family = AF_INET;
    inet_pton(AF_INET, UDP_ADDRESS, &udp_server.sin_addr);
    udp_server.sin_port = htons(UDP_PORT);

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read temperature and pressure from BMP280
        uint8_t temp_data[BMP280_TEMP_DATA_SIZE];
        uint8_t press_data[BMP280_PRESSURE_DATA_SIZE];
        if (i2c_smbus_write_byte(i2c_fd, BMP280_TEMP_REGISTER) < 0) {
            fprintf(stderr, "Failed to write to temperature register\n");
            close(udp_socket);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        usleep(100000);
        if (i2c_smbus_read_byte_data(i2c_fd, BMP280_TEMP_DATA_REGISTER, temp_data) < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            close(udp_socket);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (i2c_smbus_write_byte(i2c_fd, BMP280_PRESSURE_REGISTER) < 0) {
            fprintf(stderr, "Failed to write to pressure register\n");
            close(udp_socket);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        usleep(100000);
        if (i2c_smbus_read_byte_data(i2c_fd, BMP280_PRESSURE_DATA_REGISTER, press_data) < 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            close(udp_socket);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert temperature and pressure data
        float temperature = (temp_data[0] << 8 | temp_data[1]) / 100.0;
        float pressure = (press_data[0] << 16 | press_data[1] << 8 | press_data[2]) / 256.0;

        // Format data into JSON string
        sprintf(json_buffer, JSON_FORMAT, temperature, pressure);

        // Send data via UDP
        if (sendto(udp_socket, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&udp_server, sizeof(udp_server)) < 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
            close(udp_socket);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Wait 5 seconds before next measurement
        usleep(5000000);
    }

    close(udp_socket);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

