#include <signal.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x77
#define GPIO_PIN 2
#define LOG_FILE "altitude_log.txt"

volatile bool logging = false;
volatile bool interrupt_occurred = false;

void interrupt_handler(int signal) {
    logging = true;
    interrupt_occurred = true;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Configure GPIO2 as a falling-edge interrupt with internal pull-up
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down control\n");
        gpioTerminate();
        return 1;
    }
    if (gpioEdgeDetect(GPIO_PIN, PI_FALLING_EDGE, interrupt_handler) < 0) {
        fprintf(stderr, "Failed to set edge detect\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        fprintf(stderr, "Failed to configure I2C bus\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for interrupt
        if (interrupt_occurred) {
            interrupt_occurred = false;
            logging = true;
        }

        // Check if logging is active
        if (logging) {
            // Read calibration data
            uint8_t cal_data[6];
            if (i2c_smbus_read_byte_data(i2c_fd, 0x88) < 0) {
                fprintf(stderr, "Failed to read calibration data\n");
                fclose(log_file);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x89, 6, cal_data) < 0) {
                fprintf(stderr, "Failed to read calibration data\n");
                fclose(log_file);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Read temperature and pressure
            uint8_t data[3];
            if (i2c_smbus_write_byte_data(i2c_fd, 0xF4, 0x2E) < 0) {
                fprintf(stderr, "Failed to write command\n");
                fclose(log_file);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            usleep(100000); // wait for 100ms
            if (i2c_smbus_read_i2c_block_data(i2c_fd, 0xF6, 3, data) < 0) {
                fprintf(stderr, "Failed to read temperature and pressure\n");
                fclose(log_file);
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Calculate temperature and pressure
            int16_t temp = (data[0] << 8) | data[1];
            int16_t press = (data[0] << 8) | data[1];
            temp = temp >> 4;
            press = press >> 4;
            press = press * 100;
            press = press / 256;
            press = press / 100;

            // Append log entry
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%ld,%d,%d\n", tv.tv_sec, temp, press);

            // Reset logging flag
            logging = false;
        }

        // Poll at one-second intervals
        usleep(1000000);
    }

    // Close I2C handle
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Release GPIO
    gpioTerminate();

    return 0;
}

