#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define the SPI bus and chip select pin
#define SPI_BUS 0
#define CHIP_SELECT 8

// Define the SPI mode and speed
#define SPI_MODE 0
#define SPI_SPEED 1000000

// Define the RTD mode and bias voltage
#define RTD_MODE 3
#define BIAS_VOLTAGE 1

// Define the log file name
#define LOG_FILE "rtd_log.csv"

// Define the Callendar-Van Dusen equation coefficients
#define A 3.908357
#define B 0.00014616
#define C 0.00000005575
#define D 0.00000000135

// Function to compute the temperature using the Callendar-Van Dusen equation
double compute_temperature(uint16_t raw_value) {
    double temperature = (A + B * raw_value + C * raw_value * raw_value + D * raw_value * raw_value * raw_value) * 100;
    return temperature;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    // Close the SPI device file descriptor
    if (gpio_spi_close(SPI_BUS) != 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    // Close the log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO library: %s\n", strerror(errno));
        return 1;
    }

    // Set the chip select pin as an output
    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting chip select pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open the SPI device
    int spi_fd = gpio_spi_open(SPI_BUS, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_spi_close(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpio_spi_close(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set the chip select pin low
        if (gpioWrite(CHIP_SELECT, 0) != 0) {
            fprintf(stderr, "Error setting chip select pin low: %s\n", strerror(errno));
            break;
        }

        // Wait for 1 microsecond
        usleep(1);

        // Send the read command to the RTD converter
        uint8_t read_command[] = {0x00, 0x00, 0x00, 0x00};
        if (gpio_spi_xfer(spi_fd, read_command, 4, NULL, 0) != 4) {
            fprintf(stderr, "Error sending read command: %s\n", strerror(errno));
            break;
        }

        // Wait for 1 microsecond
        usleep(1);

        // Set the chip select pin high
        if (gpioWrite(CHIP_SELECT, 1) != 0) {
            fprintf(stderr, "Error setting chip select pin high: %s\n", strerror(errno));
            break;
        }

        // Wait for 1 microsecond
        usleep(1);

        // Read the raw value from the RTD converter
        uint8_t raw_value[2];
        if (gpio_spi_xfer(spi_fd, NULL, 0, raw_value, 2) != 2) {
            fprintf(stderr, "Error reading raw value: %s\n", strerror(errno));
            break;
        }

        // Check the fault status register
        if (raw_value[0] & 0x80) {
            fprintf(stderr, "Fault status register indicates a problem\n");
            break;
        }

        // Compute the temperature
        double temperature = compute_temperature(raw_value[1] << 8 | raw_value[0]);

        // Log the temperature
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the SPI device file descriptor
    if (gpio_spi_close(SPI_BUS) != 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    // Close the log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

