// Structure to hold a single sample
typedef struct {
    uint32_t timestamp;
    int16_t pressure;
} sample_t;

// Circular buffer to hold the last 60 seconds of samples
sample_t buffer[CIRCULAR_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

// Function to calculate the rolling average of the pressure values in the buffer
int calculate_average() {
    int sum = 0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[(buffer_head + i) % CIRCULAR_BUFFER_SIZE].pressure;
    }
    return sum / buffer_count;
}

// Function to check if the current pressure deviates by more than the threshold from the average
bool check_pressure_deviation() {
    int average = calculate_average();
    int current_pressure = 0;
    // Read the current pressure from the BMP180
    int ret = gpiod_cdev_read(BMP180_ADDRESS, BMP180_PRESSURE_REGISTER, BMP180_PRESSURE_REGISTER_SIZE, &current_pressure);
    if (ret < 0) {
        fprintf(stderr, "Error reading pressure from BMP180: %d\n", ret);
        return false;
    }
    return abs(average - current_pressure) > PRESSURE_DEVIATION_THRESHOLD;
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // Cleanly release resources
    gpiod_cdev_close(BMP180_ADDRESS);
    gpio_write(24, 0);
    gpiod_driver_close();
    exit(0);
}

