    int ret = gpiod_cdev_open(BMP180_ADDRESS, GPIOD_CDEV_OPEN_NONBLOCK);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C interface: %d\n", ret);
        return 1;
