    gpio_set_mode(24, PI_OUTPUT);
    gpio_write(24, 0);

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the timer
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = SAMPLE_INTERVAL * 1000000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = SAMPLE_INTERVAL * 1000000;
    int timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        fprintf(stderr, "Failed to create timer: %d\n", timer_fd);
        return 1;
    }
    if (timerfd_settime(timer_fd, 0, &timer, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %d\n", timer_fd);
        return 1;
    }

    // Main sampling loop
    while (1) {
        // Wait for the timer to expire
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = SAMPLE_INTERVAL * 1000000;
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(timer_fd, &read_fds);
        int ret = select(timer_fd + 1, &read_fds, NULL, NULL, &timeout);
