            fprintf(stderr, "Error in select: %d\n", ret);
            break;
        }

        // Read the current pressure from the BMP180
        int current_pressure = 0;
        ret = gpiod_cdev_read(BMP180_ADDRESS, BMP180_PRESSURE_REGISTER, BMP180_PRESSURE_REGISTER_SIZE, &current_pressure);
        if (ret < 0) {
            fprintf(stderr, "Error reading pressure from BMP180: %d\n", ret);
            break;
        }

        // Store the sample in the buffer
        buffer[buffer_head].timestamp = time(NULL);
        buffer[buffer_head].pressure = current_pressure;
        buffer_head = (buffer_head + 1) % CIRCULAR_BUFFER_SIZE;
        buffer_count++;

        // Check if the buffer is full
        if (buffer_count >= PRESSURE_AVERAGE_WINDOW) {
            buffer_tail = (buffer_tail + 1) % CIRCULAR_BUFFER_SIZE;
            buffer_count--;
        }

        // Check if the current pressure deviates by more than the threshold from the average
        if (check_pressure_deviation()) {
            // Assert the alert
            gpio_write(24, 1);
            fprintf(stderr, "Pressure deviation detected: %d\n", current_pressure);
        } else {
            // Clear the alert
            gpio_write(24, 0);
        }
    }

    return 0;
}

