#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define the I2C bus and address of the BMP180 sensor
#define I2C_BUS 1
#define BMP180_ADDRESS 0x77

// Define the calibration data registers
#define BMP180_AC1 0xAA
#define BMP180_AC2 0xAC
#define BMP180_AC3 0xAE
#define BMP180_AC4 0xB0
#define BMP180_AC5 0xB2
#define BMP180_AC6 0xB4
#define BMP180_X1 0xB6
#define BMP180_X2 0xB8
#define BMP180_X3 0xBA
#define BMP180_X4 0xBC
#define BMP180_X5 0xBE

// Define the oversampling setting
#define BMP180_OVERSAMPLING 0

// Define the timer interrupt frequency
#define TIMER_FREQ 500

// Define the file to log the results
#define LOG_FILE "bmp180_log.txt"

// Function to read a byte from the BMP180 sensor
uint8_t read_byte(uint8_t reg) {
    int fd = gpio_i2c_open(I2C_BUS, 0);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    int ret = gpio_i2c_write_byte(fd, BMP180_ADDRESS, reg);
    if (ret < 0) {
        perror("Failed to write to I2C bus");
        gpio_i2c_close(fd);
        exit(1);
    }

    ret = gpio_i2c_read_byte(fd, BMP180_ADDRESS, reg);
    if (ret < 0) {
        perror("Failed to read from I2C bus");
        gpio_i2c_close(fd);
        exit(1);
    }

    gpio_i2c_close(fd);
    return ret;
}

// Function to read a 16-bit word from the BMP180 sensor
uint16_t read_word(uint8_t reg) {
    uint8_t msb = read_byte(reg);
    uint8_t lsb = read_byte(reg + 1);
    return (msb << 8) | lsb;
}

// Function to read the calibration data from the BMP180 sensor
void read_calibration_data() {
    uint16_t ac1 = read_word(BMP180_AC1);
    uint16_t ac2 = read_word(BMP180_AC2);
    uint16_t ac3 = read_word(BMP180_AC3);
    uint16_t ac4 = read_word(BMP180_AC4);
    uint16_t ac5 = read_word(BMP180_AC5);
    uint16_t ac6 = read_word(BMP180_AC6);
    uint16_t x1 = read_word(BMP180_X1);
    uint16_t x2 = read_word(BMP180_X2);
    uint16_t x3 = read_word(BMP180_X3);
    uint16_t x4 = read_word(BMP180_X4);
    uint16_t x5 = read_word(BMP180_X5);
    uint16_t x6 = read_word(BMP180_X6);

    // Validate the calibration data
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        x1 == 0 || x2 == 0 || x3 == 0 || x4 == 0 || x5 == 0 || x6 == 0) {
        fprintf(stderr, "Invalid calibration data\n");
        exit(1);
    }
}

// Function to read the temperature and pressure from the BMP180 sensor
void read_temperature_and_pressure() {
    uint16_t ut = read_word(0xF6);
    uint8_t msb = read_byte(0xF7);
    uint8_t lsb = read_byte(0xF7 + 1);
    uint32_t up = (msb << 8) | lsb;

    uint32_t t = (uint32_t)ut * 256 + up;
    uint32_t p = (uint32_t)read_word(0xF4) * 256 + read_word(0xF6);

    // Calculate the temperature in degrees Celsius
    int32_t t_fine = (int32_t)t - 4000;
    int32_t t_celsius = (t_fine * 5 + (int32_t)ac6 * t_fine * t_fine + (int32_t)ac5 * t_fine + (int32_t)ac4) >> 15;

    // Calculate the pressure in pascals
    int32_t p_fine = (int32_t)p - (int32_t)ac3 * t_fine * t_fine - (int32_t)ac2 * t_fine - (int32_t)ac1;
    p_fine = (p_fine / (int32_t)ac5) + (int32_t)ac6 * t_fine;
    p_fine = (p_fine / (int32_t)ac4) + (int32_t)ac3 * t_fine * t_fine;

    // Apply the temperature and pressure compensation
    p_fine = p_fine + (int32_t)x1 * t_fine + (int32_t)x2 * t_fine * t_fine + (int32_t)x3 * t_fine * t_fine * t_fine;
    p_fine = p_fine / (int32_t)x4 + (int32_t)x5 * t_fine / (int32_t)x4;

    // Validate the temperature and pressure
    if (t_celsius < -40 || t_celsius > 85 || p_fine < 30000 || p_fine > 110000) {
        fprintf(stderr, "Invalid temperature or pressure\n");
        exit(1);
    }

    // Log the results
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    fprintf(file, "%d %d\n", t_celsius, p_fine);
    fclose(file);
}

// Function to handle the timer interrupt
void timer_interrupt(int gpio, int level, uint32_t tick) {
    read_temperature_and_pressure();
    gpio_timer_clear(I2C_BUS, 0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO library");
        exit(1);
    }

    // Open the I2C bus
    int fd = gpio_i2c_open(I2C_BUS, 0);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        exit(1);
    }

    // Read the calibration data
    read_calibration_data();

    // Set up the timer interrupt
    gpio_timer_setmode(I2C_BUS, 0, TIMER_FREQ);
    gpio_timer_setalarm(I2C_BUS, 0, TIMER_FREQ);
    gpio_timer_setcallback(I2C_BUS, 0, timer_interrupt);

    // Handle SIGINT and SIGTERM signals
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Wait for the timer interrupt
        gpio_timer_wait(I2C_BUS, 0);
    }

    // Cleanly exit
    gpio_i2c_close(fd);
    gpioTerminate();
    return 0;
}

