#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_PWM 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_MIN 40
#define TEMP_MAX 70
#define TEMP_OFFSET 30

void sigint_handler(int sig) {
    gpioPWM(GPIO_PWM, 0);
    close(log_fd);
    pwm_destroy();
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main() {
    int pwm_fd;
    int log_fd;
    char log_buf[256];
    char temp_buf[32];
    int temp;
    int duty;
    struct gpio_pwm pwm;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        exit(1);
    }

    // Initialize PWM driver
    pwm_fd = gpioInitialise();
    if (pwm_fd == -1) {
        perror("gpioInitialise");
        close(log_fd);
        exit(1);
    }

    // Set up PWM
    pwm = (struct gpio_pwm) {
        .gpio = GPIO_PWM,
        .freq = PWM_FREQ,
        .range = PWM_RANGE
    };
    if (gpioPWM(pwm_fd, pwm) == -1) {
        perror("gpioPWM");
        gpioTerminate();
        close(log_fd);
        exit(1);
    }

    while (1) {
        // Read temperature
        int temp_fd = open(TEMP_FILE, O_RDONLY);
        if (temp_fd == -1) {
            perror("open");
            gpioPWM(pwm_fd, 0);
            close(log_fd);
            gpioTerminate();
            exit(1);
        }

        if (read(temp_fd, temp_buf, sizeof(temp_buf)) == -1) {
            perror("read");
            close(temp_fd);
            gpioPWM(pwm_fd, 0);
            close(log_fd);
            gpioTerminate();
            exit(1);
        }

        close(temp_fd);

        temp = atoi(temp_buf);
        if (temp < 0 || temp > 1000000) {
            fprintf(stderr, "Invalid temperature value: %s\n", temp_buf);
            continue;
        }

        // Map temperature to duty cycle
        duty = (temp - TEMP_MIN) * PWM_RANGE / (TEMP_MAX - TEMP_MIN + TEMP_OFFSET);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        // Write to PWM
        if (gpioPWM(pwm_fd, duty) == -1) {
            perror("gpioPWM");
            gpioPWM(pwm_fd, 0);
            close(log_fd);
            gpioTerminate();
            exit(1);
        }

        // Log temperature and duty cycle
        time_t now = time(NULL);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %d %d\n", log_buf, temp, duty);
        fflush(log_fd);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    close(log_fd);
    gpioTerminate();
    return 0;
}

