#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define BMP280_DEFAULT_ADDRESS 0x58
#define BMP280_ALTERNATE_ADDRESS 0x60
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_TEMP_MSB_REG 0xF6
#define BMP280_TEMP_LSB_REG 0xF7
#define BMP280_PRESS_MSB_REG 0xF6
#define BMP280_PRESS_LSB_REG 0xF7
#define BMP280_PRESS_XLSB_REG 0xF8
#define BMP280_STATUS_REG 0xF3

#define GPIO_SDA 3
#define GPIO_SCL 5

#define FILE_NAME "weather_data.txt"

int i2c_fd = -1;
FILE *file = NULL;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(0);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_DEFAULT_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }
}

void read_bmp280_temperature(int address) {
    uint8_t data[2];
    if (i2c_smbus_write_byte_data(i2c_fd, BMP280_CTRL_MEAS_REG, 0x2E) == -1) {
        perror("Failed to write to BMP280 control register");
        exit(1);
    }
    usleep(100000); // wait for measurement to complete
    if (i2c_smbus_read_i2c_block_data(i2c_fd, BMP280_TEMP_MSB_REG, 2, data) == -1) {
        perror("Failed to read BMP280 temperature");
        exit(1);
    }
    uint16_t temp = (data[0] << 8) | data[1];
    temp = temp * 165.0 / 10.0;
    printf("Temperature: %.2f °C\n", temp);
}

void read_bmp280_pressure(int address) {
    uint8_t data[3];
    if (i2c_smbus_write_byte_data(i2c_fd, BMP280_CTRL_MEAS_REG, 0x34) == -1) {
        perror("Failed to write to BMP280 control register");
        exit(1);
    }
    usleep(100000); // wait for measurement to complete
    if (i2c_smbus_read_i2c_block_data(i2c_fd, BMP280_PRESS_MSB_REG, 3, data) == -1) {
        perror("Failed to read BMP280 pressure");
        exit(1);
    }
    uint32_t press = (data[0] << 16) | (data[1] << 8) | data[2];
    press = press * 3125.0 / 100.0;
    uint32_t temp = (data[3] << 8) | data[4];
    temp = temp * 250.0 / 100.0;
    press = press / (1.0 + (temp * 0.0180 / 100.0));
    printf("Pressure: %.2f hPa\n", press);
}

void log_data() {
    time_t now = time(NULL);
    struct tm *lt = localtime(&now);
    char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", lt);
    fprintf(file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", buffer, 165.0 * (read_bmp280_temperature(BMP280_DEFAULT_ADDRESS) / 10.0), read_bmp280_pressure(BMP280_DEFAULT_ADDRESS));
    fflush(file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_i2c();

    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file");
        close(i2c_fd);
        exit(1);
    }

    while (1) {
        log_data();
        usleep(5000000);
    }

    return 0;
}

