#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define AVG_WINDOW 10

#define LOG_ERROR(...) fprintf(stderr, __VA_ARGS__)

int i2c_fd;
gpio_desc_t *gpio_desc;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
float buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int avg_count = 0;
float running_avg = 0.0;

void *thread_func(void *arg) {
    while (1) {
        int ret = gpiod_line_get(gpio_desc, GPIO_PIN, GPIOD_LINE_ACTIVE_LOW);
        if (ret < 0) {
            LOG_ERROR("Failed to get GPIO line: %s\n", gpiod_strerror(ret));
            break;
        }

        int temperature;
        ret = i2c_smbus_read_byte_data(i2c_fd, 0x00);
        if (ret < 0) {
            LOG_ERROR("Failed to read temperature: %s\n");
            if (errno == EIO) {
                // Attempt to re-initialize the I2C bus
                close(i2c_fd);
                i2c_fd = open("/dev/i2c-%d", O_RDWR);
                if (i2c_fd < 0) {
                    LOG_ERROR("Failed to open I2C bus: %s\n", strerror(errno));
                    break;
                }
                ret = i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x00);
                if (ret < 0) {
                    LOG_ERROR("Failed to write to I2C bus: %s\n", strerror(errno));
                    break;
                }
            } else {
                break;
            }
        }

        temperature = (ret & 0xFF);
        ret = i2c_smbus_read_byte_data(i2c_fd, 0x01);
        if (ret < 0) {
            LOG_ERROR("Failed to read temperature: %s\n");
            if (errno == EIO) {
                // Attempt to re-initialize the I2C bus
                close(i2c_fd);
                i2c_fd = open("/dev/i2c-%d", O_RDWR);
                if (i2c_fd < 0) {
                    LOG_ERROR("Failed to open I2C bus: %s\n", strerror(errno));
                    break;
                }
                ret = i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x00);
                if (ret < 0) {
                    LOG_ERROR("Failed to write to I2C bus: %s\n", strerror(errno));
                    break;
                }
            } else {
                break;
            }
        }

        temperature |= (ret & 0xFF) << 8;
        temperature >>= 8;

        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_head] = temperature;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        avg_count++;
        running_avg = (running_avg * (avg_count - 1) + temperature) / avg_count;
        pthread_mutex_unlock(&buffer_mutex);

        if (temperature > 28.0) {
            gpiod_line_set_value(gpio_desc, GPIO_PIN, 1);
        } else {
            gpiod_line_set_value(gpio_desc, GPIO_PIN, 0);
        }

        usleep(1000000);
    }

    gpiod_line_release(gpio_desc, GPIO_PIN);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);
    return NULL;
}

int main() {
    i2c_fd = open("/dev/i2c-%d", O_RDWR);
    if (i2c_fd < 0) {
        LOG_ERROR("Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

