        return -1;
    }
    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        return -1;
    }
    return 0;
}

int spi_init() {
    int fd = gpiod_open("/dev/spidev0.0");
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        return -1;
    }
    if (gpiod_set_mode(fd, SPI_CS_HIGH | SPI_MODE_0 | SPI_CPOL_0 | SPI_CPHA_0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        gpiod_close(fd);
        return -1;
    }
    if (gpiod_set_speed(fd, 500000) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        gpiod_close(fd);
        return -1;
    }
    return fd;
}

int max31865_init(int fd) {
    uint8_t config = (MAX31865_GAIN_1 | MAX31865_REF_430);
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    return 0;
}

int max31865_read(int fd) {
    uint8_t status;
    if (gpiod_transfer(fd, MAX31865_STATUS, &status, 1) < 0) {
        syslog(LOG_ERR, "Failed to read from MAX31865");
        return -1;
    }
    if (status & MAX31865_FAULT) {
        syslog(LOG_ERR, "MAX31865 fault detected");
        return -1;
    }
    return 0;
}

int max31865_reset(int fd) {
    uint8_t config = MAX31865_RESET_ENABLE;
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    usleep(100000);
    config = MAX31865_RESET_DISABLE;
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    return 0;
}

int read_temperature(int fd) {
    uint8_t data[2];
    if (gpiod_transfer(fd, MAX31865_READ, data, 2) < 0) {
        syslog(LOG_ERR, "Failed to read from MAX31865");
        return -1;
    }
    int32_t temperature = (data[0] << 8) | data[1];
    temperature *= 100;
    temperature /= 430;
    temperature /= 100;
    return temperature;
}

int pid_loop(int fd, int target_temp, int kp, int ki, int kd, int *duty) {
    int temperature = read_temperature(fd);
    if (temperature < 0) {
        syslog(LOG_ERR, "Failed to read temperature");
        return -1;
    }
    int error = target_temp - temperature;
    *duty = (int)((kp * error) + (ki * error) + (kd * (error - (*duty)));
    if (*duty < PWM_DUTY_MIN) {
        *duty = PWM_DUTY_MIN;
    } else if (*duty > PWM_DUTY_MAX) {
        *duty = PWM_DUTY_MAX;
    }
    return 0;
}

