            syslog(LOG_ERR, "Failed to read from MAX31865");
            gpiod_close(fd);
            return 1;
        }
        if (read_temperature(fd) > 80) {
            syslog(LOG_ERR, "Temperature exceeded 80°C");
            gpiod_close(fd);
            return 1;
        }
    }
    return 0;
