        syslog(LOG_ERR, "Failed to set SPI speed");
        gpiod_close(fd);
        return -1;
    }
    return fd;
}

int max31865_init(int fd) {
    uint8_t config = (MAX31865_GAIN_1 | MAX31865_REF_430);
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    return 0;
}

int max31865_read(int fd) {
    uint8_t status;
    if (gpiod_transfer(fd, MAX31865_STATUS, &status, 1) < 0) {
        syslog(LOG_ERR, "Failed to read from MAX31865");
        return -1;
    }
    if (status & MAX31865_FAULT) {
        syslog(LOG_ERR, "MAX31865 fault detected");
        return -1;
    }
    return 0;
}

int max31865_reset(int fd) {
    uint8_t config = MAX31865_RESET_ENABLE;
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    usleep(100000);
    config = MAX31865_RESET_DISABLE;
    if (gpiod_transfer(fd, MAX31865_CONFIG, &config, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to MAX31865");
        return -1;
    }
    return 0;
}

int read_temperature(int fd) {
    uint8_t data[2];
    if (gpiod_transfer(fd, MAX31865_READ, data, 2) < 0) {
        syslog(LOG_ERR, "Failed to read from MAX31865");
        return -1;
    }
    int32_t temperature = (data[0] << 8) | data[1];
    temperature *= 100;
    temperature /= 430;
    temperature /= 100;
    return temperature;
}

int pid_loop(int fd, int target_temp, int kp, int ki, int kd, int *duty) {
    int temperature = read_temperature(fd);
    if (temperature < 0) {
        syslog(LOG_ERR, "Failed to read temperature");
        return -1;
    }
    int error = target_temp - temperature;
    *duty = (int)((kp * error) + (ki * error) + (kd * (error - (*duty)));
    if (*duty < PWM_DUTY_MIN) {
        *duty = PWM_DUTY_MIN;
    } else if (*duty > PWM_DUTY_MAX) {
        *duty = PWM_DUTY_MAX;
    }
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(GPIO_HEATER, 0);
    gpiod_close(fd);
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler");
        return 1;
    }
    if (gpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }
    if (spi_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        return 1;
    }
    int fd = spi_init();
    if (max31865_init(fd) < 0) {
        syslog(LOG_ERR, "Failed to initialize MAX31865");
        gpiod_close(fd);
        return 1;
    }
    json_object *config = json_object_from_file(JSON_FILE);
    if (!config) {
        syslog(LOG_ERR, "Failed to load configuration");
        gpiod_close(fd);
        return 1;
    }
    int target_temp = json_object_get_int(config, "target_temp", DEFAULT_TARGET_TEMP);
    int kp = json_object_get_int(config, "kp", DEFAULT_KP);
    int ki = json_object_get_int(config, "ki", DEFAULT_KI);
    int kd = json_object_get_int(config, "kd", DEFAULT_KD);
    json_object_put(config);
    int duty = 0;
    while (1) {
        if (pid_loop(fd, target_temp, kp, ki, kd, &duty) < 0) {
            syslog(LOG_ERR, "Failed to execute PID loop");
            gpiod_close(fd);
            return 1;
        }
        gpioWrite(GPIO_HEATER, duty);
        usleep(100000);
        if (max31865_read(fd) < 0) {
            syslog(LOG_ERR, "Failed to read from MAX31865");
            gpiod_close(fd);
            return 1;
        }
        if (read_temperature(fd) > 80) {
            syslog(LOG_ERR, "Temperature exceeded 80°C");
            gpiod_close(fd);
            return 1;
        }
    }
    return 0;
}
