#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define the I2C bus and device addresses
#define I2C_BUS 1
#define BMP180_ADDRESS 0x77

// Define the GPIO pin for the interrupt
#define GPIO_INTERRUPT 27

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define the logging interval in seconds
#define LOG_INTERVAL 2

// Define the file name for logging
#define LOG_FILE "pressure_log.txt"

// Function to read a byte from the BMP180 sensor
uint8_t read_byte(uint8_t reg) {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    uint8_t data;
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("Failed to write to I2C device");
        close(fd);
        exit(1);
    }

    if (i2c_smbus_read_byte(fd, &data) < 0) {
        perror("Failed to read from I2C device");
        close(fd);
        exit(1);
    }

    close(fd);
    return data;
}

// Function to read a 16-bit word from the BMP180 sensor
uint16_t read_word(uint8_t reg) {
    uint8_t msb = read_byte(reg);
    uint8_t lsb = read_byte(reg + 1);
    return (msb << 8) | lsb;
}

// Function to read the temperature from the BMP180 sensor
float read_temperature() {
    uint16_t ut = read_word(0xF6);
    uint16_t up = read_word(0xF6);
    uint8_t x1 = (uint8_t)((ut >> 4) * 5 + (up >> 4));
    uint8_t x2 = (uint8_t)((ut * 5) + (up >> 5));
    uint8_t b5 = x1 + (x2 - 4000);
    return (b5 / 4.0) - 45.0;
}

// Function to read the pressure from the BMP180 sensor
float read_pressure() {
    uint16_t ut = read_word(0xF6);
    uint16_t up = read_word(0xF6);
    uint8_t x1 = (uint8_t)((ut >> 4) * 5 + (up >> 4));
    uint8_t x2 = (uint8_t)((ut * 5) + (up >> 5));
    uint8_t b5 = x1 + (x2 - 4000);
    float b6 = b5 - 4000;
    float b6_scaled = b6 * 2.0 / 4.0;
    float b3 = b6_scaled * b6_scaled;
    float b4 = b6_scaled * b6_scaled * b6_scaled;
    float b7 = (b3 * 4.0 + b2) * 2.0;
    float p = (b7 * 4.0) / 2048.0;
    float p_scaled = p / 2.0;
    float p_offset = 0.0;
    float p_sens = 0.0;
    uint8_t data[3];
    if (i2c_smbus_read_i2c_block_data(BMP180_ADDRESS, 0xF7, 3, data) < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    p_offset = (data[0] << 8) | data[1];
    p_sens = (data[2] & 0xFF);
    return (p_scaled + (p_offset * 2.0) / 4.0 + (p_sens * 2.0)) / 4.0;
}

// Function to handle the interrupt
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        // Debounce the interrupt
        gpioDelay(DEBOUNCE_TIME * 1000);
        // Toggle logging
        logging = !logging;
    }
}

// Global variables
