    if (signum == SIGINT || signum == SIGTERM) {
        // Clean up resources
        if (log_fd >= 0) {
            close(log_fd);
            log_fd = -1;
        }
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }

    // Set up the interrupt
    if (gpioSetMode(GPIO_INTERRUPT, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(GPIO_INTERRUPT, PI_PUD_UP) < 0) {
        perror("Failed to set pull-up/down control");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetAlertFunc(GPIO_INTERRUPT, interrupt_handler) < 0) {
        perror("Failed to set alert function");
        gpioTerminate();
        exit(1);
    }

    // Initialize logging
    log_fd = -1;

    // Main loop
    while (1) {
        // Read temperature and pressure
        float temperature = read_temperature();
        float pressure = read_pressure();

        // Log data if enabled
        if (logging) {
            log_data(pressure);
        }

        // Sleep for the logging interval
        sleep(LOG_INTERVAL);

        // Check for I2C communication errors
        if (gpioRead(GPIO_INTERRUPT) == 0) {
            // Debounce the interrupt
            gpioDelay(DEBOUNCE_TIME * 1000);
            // Toggle logging
            logging = !logging;
        }
    }

    // Clean up resources
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
    gpioTerminate();

    return 0;
