#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define LOG_FILE "heater_log.csv"
#define MAX_DUTY_CYCLE 0.8
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define MAX31855_FAULT_OPEN_CIRCUIT 0x8000
#define MAX31855_FAULT_SHORT_GROUND 0x4000
#define MAX31855_FAULT_SHORT_VCC 0x2000

// Function to handle SIGINT and SIGTERM signals
void sigint_handler(int sig) {
    // Turn off the heater
    gpiod_line_set_value(17, 0);
    // Close the SPI interface
    gpiod_chip_close(gpiod_chip_open("/dev/spidev0.0"));
    // Close the log file
    fclose(log_file);
    // Terminate the driver library
    gpiod_driver_exit();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the logger
    openlog(NULL, LOG_PID, LOG_USER);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        exit(1);
    }

    // Initialize the SPI interface
    gpiod_chip_t *chip = gpiod_chip_open("/dev/spidev0.0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open SPI interface");
        fclose(log_file);
        exit(1);
    }

    // Initialize the GPIO lines
    gpiod_line_t *cs = gpiod_line_create_onuprobe(chip, 8);
    gpiod_line_t *miso = gpiod_line_create_onuprobe(chip, 9);
    gpiod_line_t *mosi = gpiod_line_create_onuprobe(chip, 10);
    gpiod_line_t *sclk = gpiod_line_create_onuprobe(chip, 11);
    gpiod_line_t *heater = gpiod_line_request_output(chip, 17, "heater");

    // Set up the SPI interface
    gpiod_chip_config_t config = {
        .mode = GPIOD_MODE_SPI,
        .speed = 2000000,
        .bits_per_word = 8,
        .chip_select = GPIOD_CS_ACTIVE_HIGH,
    };
    if (gpiod_chip_config(chip, &config)) {
        syslog(LOG_ERR, "Failed to configure SPI interface");
        gpiod_line_release(heater);
        gpiod_line_release(miso);
        gpiod_line_release(mosi);
        gpiod_line_release(sclk);
        gpiod_line_release(cs);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(1);
    }

    // Initialize the PI controller
    double target_temperature = DEFAULT_TARGET_TEMPERATURE;
    double last_temperature = 0.0;
    double last_duty_cycle = 0.0;

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) || sigaction(SIGTERM, &sa, NULL)) {
        syslog(LOG_ERR, "Failed to set up signal handlers");
        gpiod_line_release(heater);
        gpiod_line_release(miso);
        gpiod_line_release(mosi);
        gpiod_line_release(sclk);
        gpiod_line_release(cs);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the temperature from the MAX31855
        uint16_t temperature = 0;
        if (gpiod_spi_transfer(chip, &temperature, 2, 1, cs, miso, mosi, sclk)) {
            syslog(LOG_ERR, "Failed to read temperature from MAX31855");
            gpiod_line_set_value(heater, 0);
            continue;
        }

        // Check for MAX31855 fault conditions
        if (temperature & MAX31855_FAULT_OPEN_CIRCUIT) {
            syslog(LOG_ERR, "MAX31855 open circuit fault");
            gpiod_line_set_value(heater, 0);
            continue;
        }
        if (temperature & MAX31855_FAULT_SHORT_GROUND) {
            syslog(LOG_ERR, "MAX31855 short to ground fault");
            gpiod_line_set_value(heater, 0);
            continue;
        }
        if (temperature & MAX31855_FAULT_SHORT_VCC) {
            syslog(LOG_ERR, "MAX31855 short to VCC fault");
            gpiod_line_set_value(heater, 0);
            continue;
        }

        // Calculate the duty cycle
        double temperature_celsius = (temperature >> 8) * 0.01;
        double error = target_temperature - temperature_celsius;
        double duty_cycle = (error / 100.0) * MAX_DUTY_CYCLE;
        if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
        }

        // Update the PI controller
        last_temperature = temperature_celsius;
        last_duty_cycle = duty_cycle;

        // Set the duty cycle
        gpiod_line_set_value(heater, (int)(duty_cycle * 255));

        // Log the measurement and duty cycle
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature_celsius, duty_cycle);
        fflush(log_file);
    }

    // Clean up
    gpiod_line_release(heater);
    gpiod_line_release(miso);
    gpiod_line_release(mosi);
    gpiod_line_release(sclk);
    gpiod_line_release(cs);
    gpiod_chip_close(chip);
    fclose(log_file);
    closelog();

    return 0;
}

