#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_FREQ 1000
#define PWM_RANGE 255

volatile sig_atomic_t stop = 0;

void sig_handler(int sig) {
    stop = 1;
}

int main() {
    int fd;
    int pwm_fd[3];
    int ret;
    float temp;
    char filename[] = "/sys/class/thermal/thermal_zone0/temp";
    char buffer[32];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up PWM channels
    for (int i = 0; i < 3; i++) {
        pwm_fd[i] = gpioPWM(GPIO_RED + i, 0);
        if (pwm_fd[i] < 0) {
            fprintf(stderr, "Failed to set up PWM channel %d\n", GPIO_RED + i);
            return 1;
        }
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        return 1;
    }

    // Open temperature file
    fd = open(filename, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open temperature file: %s\n", filename);
        return 1;
    }

    while (!stop) {
        // Read temperature
        if (read(fd, buffer, sizeof(buffer)) < 0) {
            if (ferror(stdin)) {
                fprintf(stderr, "Failed to read temperature: %s\n", filename);
            }
            close(fd);
            return 1;
        }
        temp = atof(buffer) / 1000.0;

        // Set PWM values
        for (int i = 0; i < 3; i++) {
            if ((ret = gpioHardwarePWM(pwm_fd[i], (temp < 40000) ? 0 : (temp < 60000) ? 255 : PWM_RANGE)) < 0) {
                fprintf(stderr, "Failed to set PWM value for channel %d: %s\n", GPIO_RED + i, strerror(errno));
                close(fd);
                gpioTerminate();
                return 1;
            }
