#define GPIO_PIN 4
#define DHT22_PIN 7
#define DHT22_BIT_LENGTH 40
#define DHT22_CHECKSUM_LENGTH 8
#define MAX_RETRIES 3
#define URL "http://yourserver.com/api/humidity"

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_dht22(int pin) {
    int fd;
    int retries = 0;
    int data[DHT22_BIT_LENGTH];
    int checksum;
    int humidity;
    int temperature;

    while (running && retries < MAX_RETRIES) {
        if ((fd = gpiod_open("/dev/gpiochip0", GPIOD_LINE_REQUEST_BOTH, DHT22_PIN)) < 0) {
            fprintf(stderr, "Failed to open GPIO line: %s\n", strerror(errno));
            return -1;
        }

        if (gpiod_direction_set(fd, GPIOD_LINE_DIRECTION_OUT) < 0) {
            fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
            gpiod_close(fd);
            return -1;
        }

        if (gpiod_write(fd, 0, 1) < 0) {
            fprintf(stderr, "Failed to pull GPIO low: %s\n", strerror(errno));
            gpiod_close(fd);
            return -1;
        }

        usleep(1000000);

        if (gpiod_write(fd, 1, 1) < 0) {
            fprintf(stderr, "Failed to pull GPIO high: %s\n", strerror(errno));
            gpiod_close(fd);
            return -1;
        }

        usleep(1000000);

        if (gpiod_direction_set(fd, GPIOD_LINE_DIRECTION_IN) < 0) {
            fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
            gpiod_close(fd);
            return -1;
        }

        for (int i = 0; i < DHT22_BIT_LENGTH; i++) {
            if (gpiod_read(fd, &data[i], 1) < 0) {
                fprintf(stderr, "Failed to read GPIO: %s\n", strerror(errno));
                gpiod_close(fd);
                return -1;
            }
        }

        gpiod_close(fd);

        checksum = 0;
        for (int i = 0; i < DHT22_CHECKSUM_LENGTH; i++) {
            checksum += data[i];
        }

        if (checksum != 0) {
            retries++;
            continue;
        }

        humidity = (data[0] << 7) | (data[1] << 5) | (data[2] << 3) | (data[3] >> 1);
        temperature = (data[4] << 6) | (data[5] << 4) | (data[6] << 2) | (data[7] >> 2);

        CURL *curl;
        CURLcode res;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            char *post_data = "{\"humidity\": %d, \"temperature\": %d}";
            char *post_url = URL;
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");

            curl_easy_setopt(curl, CURLOPT_URL, post_url);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "Failed to send data: %s\n", curl_easy_strerror(res));
            }

            curl_easy_cleanup(curl);
        }

        curl_global_cleanup();

        return 0;
    }

    return -1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    while (running) {
        if (read_dht22(GPIO_PIN) == 0) {
            break;
        }

        usleep(1000000);
    }

    gpiod_cleanup();

    return 0;
}

