#define I2C_BUS 1
#define BMP180_ADDRESS 0x77
#define GPIO_BUTTON 4
#define DEBOUNCE_TICKS 200000
#define PRESSURE_LOG_FILE "pressure_log.txt"

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1, ac2, ac3, ac4, ac5, ac6;
    uint16_t b1, b2;
    int16_t mb, mc, md;
} bmp180_cal;

// Structure to hold BMP180 data
typedef struct {
    int32_t up, up5;
    int32_t b5;
} bmp180_data;

// Function to read 16-bit unsigned integer from I2C device
uint16_t i2c_read16(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(fd, reg, 2, buf) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(1);
    }
    return (buf[0] << 8) | buf[1];
}

// Function to read 24-bit unsigned integer from I2C device
uint32_t i2c_read24(int fd, uint8_t reg) {
    uint8_t buf[3];
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(fd, reg, 3, buf) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(1);
    }
    return (buf[0] << 16) | (buf[1] << 8) | buf[2];
}

// Function to write 16-bit unsigned integer to I2C device
void i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[2];
    buf[0] = (val >> 8) & 0xFF;
    buf[1] = val & 0xFF;
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (i2c_smbus_write_i2c_block_data(fd, reg, 2, buf) < 0) {
        perror("i2c_smbus_write_i2c_block_data");
        exit(1);
    }
}

// Function to read BMP180 calibration data
void read_cal(int fd, bmp180_cal *cal) {
    cal->ac1 = i2c_read16(fd, 0xAA);
    cal->ac2 = i2c_read16(fd, 0xAC);
    cal->ac3 = i2c_read16(fd, 0xAE);
    cal->ac4 = i2c_read16(fd, 0xB0);
    cal->ac5 = i2c_read16(fd, 0xB2);
    cal->ac6 = i2c_read16(fd, 0xB4);
    cal->b1 = i2c_read16(fd, 0xB6);
    cal->b2 = i2c_read16(fd, 0xB8);
    cal->mb = i2c_read16(fd, 0xBC);
    cal->mc = i2c_read16(fd, 0xBE);
    cal->md = i2c_read16(fd, 0xC0);
}

// Function to read BMP180 data
void read_data(int fd, bmp180_data *data, bmp180_cal *cal) {
    uint8_t buf[3];
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, 0xF4) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, 0x34) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    usleep(26 * 1000);
    if (i2c_smbus_read_i2c_block_data(fd, 0xF6, 3, buf) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(1);
    }
    data->up = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->b5 = (data->up - cal->ac6) * cal->ac5 >> 15;
    data->up5 = data->b5 + (cal->mc << 11) || (data->b5 - (cal->md << 11));
    data->up = data->up5 >> 8;
}

// Function to handle GPIO interrupt
void gpio_handler(int signum) {
    // Ignore SIGINT
}

// Function to debounce GPIO interrupt
bool debounce(int fd, int ticks) {
    struct itimerval it;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 0;
    it.it_value.tv_sec = ticks / 1000000;
    it.it_value.tv_usec = ticks % 1000000;
    setitimer(ITIMER_REAL, &it, NULL);
    while (1) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 1000;
        if (select(fd + 1, &read_fds, NULL, NULL, &tv) < 0) {
            perror("select");
            exit(1);
        }
        if (FD_ISSET(fd, &read_fds)) {
            break;
        }
    }
    return true;
}

int main() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Initialize GPIO
    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(1);
    }
    write(gpio_fd, "4", 1);
    close(gpio_fd);
    gpio_fd = open("/sys/class/gpio/gpio4/direction", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(1);
    }
    write(gpio_fd, "f", 1);
    close(gpio_fd);

    // Initialize BMP180
    bmp180_cal cal;
    read_cal(fd, &cal);
    if (cal.ac1 == 0 || cal.ac2 == 0 || cal.ac3 == 0 || cal.ac4 == 0 || cal.ac5 == 0 || cal.ac6 == 0 || cal.b1 == 0 || cal.b2 == 0 || cal.mb == 0 || cal.mc == 0 || cal.md == 0) {
        fprintf(stderr, "Invalid calibration data\n");
        exit(1);
    }

    // Initialize logging
    FILE *log_file = fopen(PRESSURE_LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = gpio_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Main loop
    bool logging = false;
    while (1) {
        if (debounce(gpio_fd, DEBOUNCE_TICKS)) {
            if (logging) {
                logging = false;
                fprintf(stderr, "Logging disabled\n");
            } else {
                logging = true;
                fprintf(stderr, "Logging enabled\n");
            }
        }
        if (logging) {
            bmp180_data data;
            read_data(fd, &data, &cal);
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s %d\n", timestamp, data.up / 100);
            fflush(log_file);
        }
        usleep(2000000);
    }

    // Clean up
    close(fd);
    close(gpio_fd);
    fclose(log_file);
    return 0;
}

