    if (ioctl(fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, 0xF4) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_write_byte(fd, 0x34) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    usleep(26 * 1000);
    if (i2c_smbus_read_i2c_block_data(fd, 0xF6, 3, buf) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(1);
    }
    data->up = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->b5 = (data->up - cal->ac6) * cal->ac5 >> 15;
    data->up5 = data->b5 + (cal->mc << 11) || (data->b5 - (cal->md << 11));
    data->up = data->up5 >> 8;
}

// Function to handle GPIO interrupt
void gpio_handler(int signum) {
    // Ignore SIGINT
}

// Function to debounce GPIO interrupt
bool debounce(int fd, int ticks) {
    struct itimerval it;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 0;
    it.it_value.tv_sec = ticks / 1000000;
    it.it_value.tv_usec = ticks % 1000000;
    setitimer(ITIMER_REAL, &it, NULL);
    while (1) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 1000;
        if (select(fd + 1, &read_fds, NULL, NULL, &tv) < 0) {
            perror("select");
            exit(1);
        }
        if (FD_ISSET(fd, &read_fds)) {
            break;
        }
    }
    return true;
}

int main() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Initialize GPIO
    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(1);
    }
    write(gpio_fd, "4", 1);
    close(gpio_fd);
    gpio_fd = open("/sys/class/gpio/gpio4/direction", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open");
        exit(1);
    }
    write(gpio_fd, "f", 1);
    close(gpio_fd);

    // Initialize BMP180
    bmp180_cal cal;
    read_cal(fd, &cal);
    if (cal.ac1 == 0 || cal.ac2 == 0 || cal.ac3 == 0 || cal.ac4 == 0 || cal.ac5 == 0 || cal.ac6 == 0 || cal.b1 == 0 || cal.b2 == 0 || cal.mb == 0 || cal.mc == 0 || cal.md == 0) {
        fprintf(stderr, "Invalid calibration data\n");
        exit(1);
    }

    // Initialize logging
    FILE *log_file = fopen(PRESSURE_LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = gpio_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Main loop
    bool logging = false;
    while (1) {
        if (debounce(gpio_fd, DEBOUNCE_TICKS)) {
            if (logging) {
                logging = false;
                fprintf(stderr, "Logging disabled\n");
            } else {
                logging = true;
                fprintf(stderr, "Logging enabled\n");
            }
        }
        if (logging) {
            bmp180_data data;
            read_data(fd, &data, &cal);
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s %d\n", timestamp, data.up / 100);
            fflush(log_file);
        }
        usleep(2000000);
    }

    // Clean up
    close(fd);
    close(gpio_fd);
    fclose(log_file);
    return 0;
