#include <errno.h>
#include <libgen.h>
#include <libgen.h>
#include <linux/ioctl.h>
#include <linux/gpiod.h>

#define FAN_CONTROL_LOG_FILE "/var/log/fan_control.log"
#define FAN_CONTROL_SYSFS "/sys/class/thermal/cooling_device0"
#define FAN_SPEED_SYSFS "/sys/class/thermal/cooling_device0/state"
#define CPU_TEMP_SYSFS "/sys/class/thermal/thermal_zone0/temp"

#define FAN_SPEED_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"

#define FAN_SPEED_TIER_0 0
#define FAN_SPEED_TIER_1 1
#define FAN_SPEED_TIER_2 2
#define FAN_SPEED_TIER_3 3

#define FAN_SPEED_TIER_MAP { FAN_SPEED_TIER_0, FAN_SPEED_TIER_1, FAN_SPEED_TIER_2, FAN_SPEED_TIER_3 }
#define FAN_SPEED_TIER_TEMPERATURES { 45, 55, 65 }

#define FAN_SPEED_TIER_COUNT (sizeof(FAN_SPEED_TIER_MAP) / sizeof(FAN_SPEED_TIER_MAP[0]))

static int fan_speed_tier = FAN_SPEED_TIER_0;
static int fan_speed_max_state = 0;

static void log_event(const char *message) {
    FILE *file = fopen(FAN_CONTROL_LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s: %s\n", __func__, message);
    fclose(file);
}

static int get_fan_speed_max_state() {
    int fd = open(FAN_SPEED_MAX_STATE_FILE, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    char buffer[32];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("read");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    fan_speed_max_state = atoi(buffer);
    close(fd);
    return 0;
}

static int get_cpu_temperature() {
    int fd = open(CPU_TEMP_SYSFS, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    char buffer[32];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("read");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    int temperature = atoi(buffer);
    close(fd);
    return temperature;
}

static int get_fan_speed() {
    int fd = open(FAN_SPEED_SYSFS, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    char buffer[32];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("read");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    int speed = atoi(buffer);
    close(fd);
    return speed;
}

static int set_fan_speed(int speed) {
    if (speed < 0 || speed > fan_speed_max_state) {
        log_event("Invalid fan speed");
        return -1;
    }

    int fd = open(FAN_SPEED_SYSFS, O_WRONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    ssize_t bytes_written = write(fd, "1", 1);
    if (bytes_written < 0) {
        perror("write");
        close(fd);
        return -1;
    }

    char buffer[32];
    sprintf(buffer, "%d", speed);
    bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written < 0) {
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static void fan_speed_tier_update() {
    int temperature = get_cpu_temperature();
    if (temperature < 0) {
        log_event("Failed to read CPU temperature");
        return;
    }

    int tier = 0;
    for (int i = 0; i < FAN_SPEED_TIER_COUNT; i++) {
        if (temperature < FAN_SPEED_TIER_TEMPERATURES[i]) {
            tier = i;
            break;
        }
    }

    if (tier != fan_speed_tier) {
        fan_speed_tier = tier;
        int speed = FAN_SPEED_TIER_MAP[tier];
        if (set_fan_speed(speed) < 0) {
            log_event("Failed to set fan speed");
        } else {
            log_event("Fan speed updated to tier %d", fan_speed_tier);
        }
    }
}

static void signal_handler(int signal) {
    log_event("Received signal, shutting down");
    if (set_fan_speed(FAN_SPEED_TIER_0) < 0) {
        log_event("Failed to set fan speed to 0");
    }
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (get_fan_speed_max_state() < 0) {
        log_event("Failed to read fan speed max state");
        return 1;
    }

    while (1) {
        fan_speed_tier_update();
        sleep(5);
    }

    return 0;
}

