#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

// PID controller parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define PID_SAMPLE_TIME 0.01  // seconds

// GPIO pin definitions
#define HEATER_PIN 18
#define SPI_CLK_PIN 11
#define SPI_CS_PIN 8
#define SPI_DO_PIN 9

// SPI transfer buffer
uint8_t spi_buf[4];

// PID state
double pid_error = 0.0;
double pid_prev_error = 0.0;
double pid_integral = 0.0;
double pid_derivative = 0.0;

// PID output
double pid_output = 0.0;

// MAX31855 fault bits
uint8_t max31855_fault = 0;

// File pointer for logging
FILE *log_file;

void sigint_handler(int sig) {
    // Turn off the heater
    gpioWrite(HEATER_PIN, 0);
    // Close the SPI interface
    close_spi();
    // Terminate the driver
    gpioTerminate();
    // Exit the program
    exit(0);
}

void close_spi() {
    // Close the SPI interface
    gpioSetMode(SPI_CS_PIN, PI_INPUT);
}

void init_gpio() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    // Set the SPI clock pin as an output
    gpioSetMode(SPI_CLK_PIN, PI_OUTPUT);
    // Set the SPI chip select pin as an output
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    // Set the SPI data out pin as an input
    gpioSetMode(SPI_DO_PIN, PI_INPUT);

    // Set the heater pin as an output
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    // Set the initial duty cycle to 0
    gpioWrite(HEATER_PIN, 0);
}

void init_spi() {
    // Open the SPI interface
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        exit(1);
    }

    // Set the SPI clock speed to 500 kHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 500000) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed\n");
        exit(1);
    }

    // Set the SPI mode to 0 (CPOL=0, CPHA=0)
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        exit(1);
    }
}

void read_spi() {
    // Send a read command to the MAX31855
    spi_buf[0] = 0x00;
    if (write(spi_fd, spi_buf, 1) < 1) {
        fprintf(stderr, "Failed to send read command\n");
        exit(1);
    }

    // Read 4 bytes from the MAX31855
    if (read(spi_fd, spi_buf, 4) < 4) {
        fprintf(stderr, "Failed to read from MAX31855\n");
        exit(1);
    }

    // Check for fault conditions
    max31855_fault = (spi_buf[0] & 0x80) >> 7;
    if (max31855_fault) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (spi_buf[0] & 0x40) {
            fprintf(stderr, "open-circuit\n");
        } else if (spi_buf[0] & 0x20) {
            fprintf(stderr, "short-to-GND\n");
        } else if (spi_buf[0] & 0x10) {
            fprintf(stderr, "short-to-VCC\n");
        }
        // Disable the heater and reset the PID state
        gpioWrite(HEATER_PIN, 0);
        pid_error = 0.0;
        pid_integral = 0.0;
        pid_derivative = 0.0;
    }

    // Calculate the temperature
    double temperature = (spi_buf[1] << 8) | spi_buf[2];
    temperature /= 100.0;
    if (temperature > 100.0 || temperature < 0.0) {
        // Failsafe: disable the heater if the reading is out of range
        gpioWrite(HEATER_PIN, 0);
        return;
    }

    // Log the temperature
    fprintf(log_file, "%f,%f,%f\n", temperature, pid_output, max31855_fault);
    fflush(log_file);
}

void pid_update() {
    // Calculate the error
    double error = 50.0 - temperature;

    // Calculate the derivative
    pid_derivative = (error - pid_prev_error) / PID_SAMPLE_TIME;

    // Calculate the integral
    pid_integral += error * PID_SAMPLE_TIME;

    // Calculate the PID output
    pid_output = Kp * error + Ki * pid_integral + Kd * pid_derivative;

    // Limit the output to the duty cycle range
    pid_output = fmax(0.0, fmin(pid_output, 100.0));

    // Update the previous error
    pid_prev_error = error;
}

int main() {
    // Initialize the GPIO library
    init_gpio();

    // Initialize the SPI interface
    init_spi();

    // Open the log file
    log_file = fopen("heater_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read the temperature from the MAX31855
        read_spi();

        // Update the PID state
        pid_update();

        // Set the PWM duty cycle
        gpioPWM(HEATER_PIN, (int)(pid_output * 100));

        // Sleep for the sample time
        usleep((int)(PID_SAMPLE_TIME * 1000000));
    }

    // Close the log file
    fclose(log_file);

    // Close the SPI interface
    close_spi();

    // Terminate the driver
    gpioTerminate();

    return 0;
}

