        gpioTerminate();
        exit(1);
    }

    if (gpioSetPWMfrequency(GPIO_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PWM);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPWMrange(GPIO_PWM, 0, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_PWM);
        gpioTerminate();
        exit(1);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s for writing: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        exit(1);
    }

    fprintf(log_file, "%s", LOG_HEADER);
    struct timeval last_log;
    gettimeofday(&last_log, NULL);

    while (running) {
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_log.tv_sec >= 5) {
            int temperature = 0;
            FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
            if (!temp_file) {
                fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
                gpioTerminate();
                exit(1);
            }
            if (fscanf(temp_file, "%d", &temperature) != 1) {
                fprintf(stderr, "Failed to read temperature\n");
                fclose(temp_file);
                gpioTerminate();
                exit(1);
            }
            fclose(temp_file);

            double duty_cycle = (temperature - 40.0) / (70.0 - 40.0) * 100.0;
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;

            if (gpioSetPWM(GPIO_PWM, duty_cycle) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", GPIO_PWM);
                gpioTerminate();
                exit(1);
            }

            char log_line[MAX_LOG_LINE];
            sprintf(log_line, "%ld,%d,%f\n", now.tv_sec, temperature, duty_cycle);
            if (fputs(log_line, log_file) == EOF) {
                fprintf(stderr, "Failed to write to log file %s: %s\n", LOG_FILE, strerror(errno));
                gpioTerminate();
                exit(1);
            }

            gettimeofday(&last_log, NULL);
        }
        usleep(100000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

