#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define FLOW_SENSOR_COUNT 2
#define FLOW_SENSOR_ADDRESS 0x10
#define FLOW_SENSOR_REGISTER 0x00
#define FLOW_SENSOR_REGISTER_SIZE 3
#define FLOW_SENSOR_RETRY_COUNT 3

#define FLOW_LOG_FILE "flow_log.txt"

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void flow_log(const char *format, ...) {
    char buffer[256];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);
    FILE *file = fopen(FLOW_LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", buffer);
        fclose(file);
    }
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    int i2c_bus = 1;
    int i2c_address = FLOW_SENSOR_ADDRESS;
    int retry_count = 0;

    struct timeval last_read_time;
    gettimeofday(&last_read_time, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        for (int i = 0; i < FLOW_SENSOR_COUNT; i++) {
            int sensor_address = i2c_address + (i * 2);
            int retry = 0;
            while (retry < FLOW_SENSOR_RETRY_COUNT) {
                int data[3];
                int bytes_read = i2cReadReg(i2c_fd, i2c_bus, sensor_address, FLOW_SENSOR_REGISTER, FLOW_SENSOR_REGISTER_SIZE, data);
                if (bytes_read == FLOW_SENSOR_REGISTER_SIZE) {
                    uint8_t crc = data[2];
                    uint8_t calculated_crc = sensirion_crc8(data, FLOW_SENSOR_REGISTER_SIZE - 1);
                    if (crc == calculated_crc) {
                        struct timeval current_time;
                        gettimeofday(&current_time, NULL);
                        int64_t time_diff = (current_time.tv_sec - last_read_time.tv_sec) * 1000000 + (current_time.tv_usec - last_read_time.tv_usec);
                        if (time_diff >= 1000000) {
                            flow_log("%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f",
                                     current_time.tv_sec, current_time.tv_usec / 1000000, data[0], data[1], data[2], data[3], (float)data[0] / 100.0, (float)data[1] / 100.0);
                            last_read_time = current_time;
                        }
                    }
                    break;
                } else {
                    retry++;
                    if (retry >= FLOW_SENSOR_RETRY_COUNT) {
                        fprintf(stderr, "Failed to read from sensor %d: %s\n", i, strerror(errno));
                        break;
                    }
                }
            }
        }
        usleep(1000000);
    }

    gpioTerminate();
    return 0;
}

uint8_t sensirion_crc8(const uint8_t *data, size_t size) {
    uint8_t crc = 0;
    for (size_t i = 0; i < size; i++) {
        crc = (crc ^ data[i]) ^ (crc >> 4);
    }
    return crc;
}

