// Define the GPIO pin numbers for the encoder channels
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the file name for logging
#define LOG_FILE "encoder_log.txt"

// Define the signal handler function
void signal_handler(int sig) {
    // Clean up GPIO resources
    gpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %s\n", gpioErrorStr(gpioInitResult));
        return 1;
    }

    // Set up the GPIO pins as open-drain outputs with internal pull-up resistors
    if (gpioSetMode(ENCODER_A, PI_OUTPUT) < 0 || gpioSetMode(ENCODER_B, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pins: %s\n", gpioErrorStr(gpioGetLastErrorCode()));
        gpioTerminate();
        return 1;
    }

    // Set the initial state of the GPIO pins to high (pull-up enabled)
    if (gpioWrite(ENCODER_A, 1) < 0 || gpioWrite(ENCODER_B, 1) < 0) {
        fprintf(stderr, "Failed to set initial GPIO pin state: %s\n", gpioErrorStr(gpioGetLastErrorCode()));
        gpioTerminate();
        return 1;
    }

    // Open the log file for writing
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the state machine variables
    int state = 0;
    int position = 0;
    int last_state = 0;

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of the GPIO pins
        int a = gpioRead(ENCODER_A);
        int b = gpioRead(ENCODER_B);

        // Update the state machine
        switch (state) {
            case 0:
                if (a == 0 && b == 0) {
                    state = 1;
                }
                break;
            case 1:
                if (a == 1 && b == 0) {
                    state = 2;
                } else if (a == 0 && b == 0) {
                    state = 0;
                }
                break;
            case 2:
                if (a == 0 && b == 1) {
                    state = 3;
                } else if (a == 1 && b == 0) {
                    state = 1;
                }
                break;
            case 3:
                if (a == 1 && b == 1) {
                    state = 0;
                    position++;
                } else if (a == 0 && b == 1) {
                    state = 2;
                }
                break;
        }

        // Check for position change
        if (state != last_state) {
            // Calculate the new position
            double angle = (double)position * 360.0 / PULSES_PER_REVOLUTION;
            // Log the position change
            char buffer[20];
            sprintf(buffer, "%f\n", angle);
            if (write(log_fd, buffer, strlen(buffer)) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            // Update the last state
            last_state = state;
        }

        // Sleep for a short period to avoid consuming too much CPU
        usleep(10000);
    }

    // Clean up resources
    close(log_fd);
    gpioTerminate();
    return 0;
}

