    int state = 0;
    int position = 0;
    int last_state = 0;

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of the GPIO pins
        int a = gpioRead(ENCODER_A);
        int b = gpioRead(ENCODER_B);

        // Update the state machine
        switch (state) {
            case 0:
                if (a == 0 && b == 0) {
                    state = 1;
                }
                break;
            case 1:
                if (a == 1 && b == 0) {
                    state = 2;
                } else if (a == 0 && b == 0) {
                    state = 0;
                }
                break;
            case 2:
                if (a == 0 && b == 1) {
                    state = 3;
                } else if (a == 1 && b == 0) {
                    state = 1;
                }
                break;
            case 3:
                if (a == 1 && b == 1) {
                    state = 0;
                    position++;
                } else if (a == 0 && b == 1) {
                    state = 2;
                }
                break;
        }

        // Check for position change
        if (state != last_state) {
            // Calculate the new position
            double angle = (double)position * 360.0 / PULSES_PER_REVOLUTION;
            // Log the position change
            char buffer[20];
            sprintf(buffer, "%f\n", angle);
            if (write(log_fd, buffer, strlen(buffer)) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            // Update the last state
            last_state = state;
        }

        // Sleep for a short period to avoid consuming too much CPU
        usleep(10000);
    }

    // Clean up resources
    close(log_fd);
    gpioTerminate();
    return 0;
}
