    write_ir(0x00, 0x00); // Reset
    write_ir(0x01, 0x00); // Disable interrupts
    write_ir(0x02, 0x00); // Disable LED
    write_ir(0x03, 0x00); // Disable LED

    // Main loop
    while (1) {
        // Read data from ADPD144RI sensor
        uint16_t red = read_ir(0x04);
        uint16_t ir = read_ir(0x05);

        // Log data
        log_data(time(NULL), red, ir);

        // Check if IR value exceeds threshold
        if (ir > THRESHOLD) {
            // Activate LED
            gpioWrite(GPIO_LED, 1);
        } else {
            // Deactivate LED
            gpioWrite(GPIO_LED, 0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

