#include <fcntl.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Mutex for protecting the pulse counter
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Pulse counter
volatile uint32_t pulse_count = 0;

// Log file descriptor
int log_fd = -1;

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    // Terminate the driver library
    gpiod_close(GPIO_PIN);
    gpiod_exit();

    // Close the log file
    if (log_fd != -1) {
        fclose(log_fd);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Exit the program
    exit(0);
}

// Interrupt service routine
void isr(int pin, uint32_t value, uint32_t timestamp, void *user_data) {
    // Check if the pin is the one we're interested in
    if (pin == GPIO_PIN) {
        // Check if the value is a rising edge
        if (value == 1) {
            // Lock the mutex
            pthread_mutex_lock(&pulse_mutex);

            // Increment the pulse counter
            pulse_count++;

            // Unlock the mutex
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
}

int main() {
    // Initialize the driver library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize the driver library: %s\n", strerror(errno));
        return 1;
    }

    // Open the GPIO pin as an input with a pull-down resistor
    int pin_fd = gpiod_open(GPIO_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_RISING_EDGE);
    if (pin_fd < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Register the interrupt service routine
    if (gpiod_set_event_detect(pin_fd, GPIOD_LINE_RISING_EDGE, 1, 0, isr, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR: %s\n", strerror(errno));
        gpiod_close(pin_fd);
        gpiod_exit();
        return 1;
    }

    // Open the log file in append mode with immediate flushing
    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_close(pin_fd);
        gpiod_exit();
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        gpiod_close(pin_fd);
        gpiod_exit();
        return 1;
    }

    // Main loop
    struct timeval last_time;
    gettimeofday(&last_time, NULL);
    while (1) {
        // Wait for 1 second
        struct timeval now;
        gettimeofday(&now, NULL);
        if ((now.tv_sec - last_time.tv_sec) >= 1) {
            // Lock the mutex
            pthread_mutex_lock(&pulse_mutex);

            // Calculate the RPM
            double rpm = (pulse_count * 60.0) / (now.tv_sec - last_time.tv_sec);

            // Unlock the mutex
            pthread_mutex_unlock(&pulse_mutex);

            // Log the RPM
            fprintf(log_fd, "%.2f\n", rpm);
            fflush(log_fd);

            // Reset the pulse counter
            pulse_count = 0;

            // Update the last time
            last_time = now;
        }
    }

    return 0;
}

