#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define GPIO_LED 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL 100000 // 100 ms

// Function to handle I2C read operation
int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    msg[0].addr = I2C_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    ret = ioctl(fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }

    return 0;
}

// Function to handle I2C write operation
int i2c_write(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    msg[0].addr = I2C_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_ADDRESS;
    msg[1].flags = 0;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    ret = ioctl(fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

// Function to read data from the ADPD144RI sensor
int read_sensor(int fd) {
    uint8_t reg = 0x00; // Register address for data read
    uint8_t data[2];

    if (i2c_read(fd, reg, data, 2) < 0) {
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to log data to a file
void log_data(int fd, int timestamp, int red, int infrared) {
    char buffer[256];
    sprintf(buffer, "%d,%d,%d\n", timestamp, red, infrared);
    write(fd, buffer, strlen(buffer));
}

