volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_event(const char *level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s %s\n", timestamp, level);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO18, GAIN_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO18 low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        int level = gpioRead(GPIO17);
        if (level == 1 && gpioRead(GPIO17) == 0) {
            log_event("1");
        }
        usleep(SAMPLE_RATE * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

