#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <sys/time.h>
#include <sys/select.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x10
#define FLOW_SENSOR_REG 0x00
#define CRC_POLYNOMIAL 0x1D
#define CRC_INIT 0x00

#define FLOW_LOG_FILE "flow_log.csv"

int i2c_fd = -1;
FILE *log_file = NULL;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        gpiod_close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    if (gpiod_init() == -1) {
        perror("gpiod_init");
        exit(1);
    }

    if ((i2c_fd = gpiod_open(I2C_BUS, I2C_ADDRESS, 0)) == -1) {
        perror("gpiod_open");
        gpiod_exit();
        exit(1);
    }

    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = (uint8_t *)&FLOW_SENSOR_REG;

    struct i2c_msg *msgs_read = &msg;
    msgs_read->addr = I2C_ADDRESS;
    msgs_read->flags = I2C_M_RD;
    msgs_read->len = 3;
    msgs_read->buf = (uint8_t *)malloc(3);

    while (1) {
        if (gpiod_i2c_transfer(i2c_fd, msgs, 1, msgs_read, 1) == -1) {
            perror("gpiod_i2c_transfer");
            if (errno == EIO) {
                continue;
            } else {
                break;
            }
        }

        uint16_t raw_value = (msgs_read->buf[0] << 8) | msgs_read->buf[1];
        uint8_t crc = msgs_read->buf[2];

        uint8_t calculated_crc = 0;
        for (int i = 0; i < 2; i++) {
            calculated_crc = (calculated_crc << 1) ^ (calculated_crc >> 7);
            calculated_crc ^= raw_value & 0xFF;
            raw_value >>= 8;
        }
        calculated_crc ^= raw_value;
        calculated_crc ^= CRC_INIT;
        for (int i = 0; i < 8; i++) {
            calculated_crc = (calculated_crc << 1) ^ (calculated_crc >> 7);
        }

        if (calculated_crc != crc) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        fprintf(log_file, "%s,%d\n", timestamp, raw_value);
        fflush(log_file);

        usleep(1000000);
    }

    if (i2c_fd != -1) {
        gpiod_close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_exit();

    return 0;
}

