    return 0;
}

int i2c_write(uint8_t reg, uint8_t *data, int len) {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        close(fd);
        exit(1);
    }

    if (write(fd, data, len) != len) {
        perror("Failed to write to I2C register");
        close(fd);
        exit(1);
    }

    close(fd);
    return 0;
}

void log_data(double iaq, double tvoc, double eCO2) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(1);
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(file, "%ld,%f,%f,%f\n", tv.tv_sec, iaq, tvoc, eCO2);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);

    uint8_t data[2];

    while (running) {
        if (i2c_read(IAQ_REGISTER, data, 2) < 0) {
            fprintf(stderr, "Error reading IAQ register\n");
            sleep(1);
            continue;
        }

        double iaq = (data[0] << 8) | data[1];
        iaq /= 10.0;

        if (i2c_read(TVOC_REGISTER, data, 2) < 0) {
            fprintf(stderr, "Error reading TVOC register\n");
            sleep(1);
            continue;
        }

        double tvoc = (data[0] << 8) | data[1];
        tvoc /= 10.0;

        if (i2c_read(eCO2_REGISTER, data, 2) < 0) {
            fprintf(stderr, "Error reading eCO2 register\n");
            sleep(1);
            continue;
        }

        double eCO2 = (data[0] << 8) | data[1];
        eCO2 /= 10.0;

        log_data(iaq, tvoc, eCO2);

        sleep(5);
    }

    return 0;
}
```

This code assumes that the I2C bus is configured to use the default settings. If you need to use a different I2C bus or settings, you'll need to modify the `I2C_BUS` define accordingly.

The `i2c_read` and `i2c_write` functions handle the I2C communication, checking for errors and closing the file descriptor if an error occurs. The `log_data` function appends a line to the log file with the current timestamp, IAQ value, TVOC value, and eCO2 value.

The `main` function sets up a SIGINT handler to catch the interrupt signal and sets the `running` flag to false when the signal is received. The main loop reads the IAQ, TVOC, and eCO2 values from the sensor, computes the IAQ index, logs the data, and sleeps for 5 seconds before repeating. If an error occurs while reading from the sensor, it prints an error message and continues to the next iteration.

