#include <libgpiod.h>

#define GPIO_PIN 17
#define GPIO_LINE "17"
#define GPIO_LABEL "ttp223_tamper"
#define POLL_INTERVAL_US 100000
#define TOUCH_THRESHOLD_S 5

static volatile bool running = true;
static uint64_t last_touch_time = 0;

void cleanup(int sig) {
    gpiod_line_release(GPIO_LINE);
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request the line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as an input
    ret = gpiod_line_request_input(line, GPIO_LABEL, GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event, 1);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (event.value == GPIOD_LINE_EVENT_VALUE_RISING_EDGE) {
            uint64_t now = gpiod_chip_get_time_ns(chip);
            if (now - last_touch_time > TOUCH_THRESHOLD_S * 1e9) {
                last_touch_time = now;
                printf("Intrusion alert\n");
            }
        } else if (event.value == GPIOD_LINE_EVENT_VALUE_FALLING_EDGE) {
            last_touch_time = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

