#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 4
#define GPIO_FAN 18
#define DEBOUNCE_TIME 50
#define PWM_FREQ 100
#define LOG_FILE "flame_log.txt"

bool flame_detected = false;
bool fan_on = false;
struct timeval last_flame_time;

void cleanup(int sig) {
    if (flame_detected) {
        fprintf(stderr, "Flame detected at %s\n", ctime(&last_flame_time.tv_sec));
    }
    if (fan_on) {
        gpioPWM(GPIO_FAN, 0);
        fan_on = false;
    }
    gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioCleanup();
    fclose(log_file);
    exit(0);
}

int main() {
    int log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file == -1) {
        perror("open");
        return 1;
    }
    log_file = dup(log_file);
    if (log_file == -1) {
        perror("dup");
        return 1;
    }
    FILE *log_file_ptr = fdopen(log_file, "a");
    if (!log_file_ptr) {
        perror("fdopen");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_FAN, PI_OUTPUT);

    struct timeval start_time;
    gettimeofday(&start_time, NULL);
    fprintf(log_file_ptr, "Program started at %s\n", ctime(&start_time.tv_sec));

    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        int flame_state = gpioRead(GPIO_FLAME_SENSOR);
        if (flame_state == -1) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_FLAME_SENSOR, strerror(errno));
            break;
        }
        if (flame_state == 0) {
            if (!flame_detected) {
                gettimeofday(&last_flame_time, NULL);
                flame_detected = true;
                fprintf(log_file_ptr, "Flame detected at %s\n", ctime(&last_flame_time.tv_sec));
                fan_on = true;
                gpioPWM(GPIO_FAN, 100);
            }
        } else {
            if (flame_detected) {
                gettimeofday(&current_time, NULL);
                if ((current_time.tv_sec - last_flame_time.tv_sec) > DEBOUNCE_TIME / 1000) {
                    flame_detected = false;
                    fprintf(log_file_ptr, "Flame ended at %s\n", ctime(&current_time.tv_sec));
                }
            }
        }
        usleep(50000);
    }

    cleanup(SIGTERM);
    return 0;
}

