#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

// Define the magic number for the binary file header
#define MAGIC_NUMBER 0x4144

// Define the configuration struct
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
} config_t;

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Close the SPI device
    gpio_spi_close(0);
    // Release the GPIO pins
    gpio_cleanup();
    // Close the log file
    fclose(log_file);
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the hardware frame trigger on GPIO23 (BCM)
    if (gpioSetMode(23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO23 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(23, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO23 high\n");
        gpioTerminate();
        return 1;
    }

    // Set up the data-ready interrupt on GPIO24 (BCM)
    if (gpioSetMode(24, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO24 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(24, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor on GPIO24\n");
        gpioTerminate();
        return 1;
    }

    // Open the SPI device
    int spi_fd = gpio_spi_open(0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI configuration
    if (gpio_spi_set_mode(spi_fd, 0, 1, 0, 0) < 0) {
        fprintf(stderr, "Failed to set up SPI mode\n");
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpio_spi_set_speed(spi_fd, 1000000) < 0) {
        fprintf(stderr, "Failed to set up SPI speed\n");
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Create a configuration struct
    config_t config = {
        .start_frequency = 77000000000,
        .end_frequency = 79000000000,
        .num_chirps = 64,
        .num_samples = 256
    };

    // Open the log file
    FILE *log_file = fopen("mmwave_log.bin", "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write the magic number to the log file
    if (fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number to log file\n");
        fclose(log_file);
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write the configuration struct to the log file
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write configuration to log file\n");
        fclose(log_file);
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Wait for the data-ready interrupt
        if (gpioRead(24) == 0) {
            // Trigger the hardware frame trigger
            gpioWrite(23, 0);
            usleep(10);
            gpioWrite(23, 1);

            // Read the frame data from the SPI device
            uint8_t *frame_data = malloc(32768);
            if (!frame_data) {
                fprintf(stderr, "Failed to allocate memory for frame data\n");
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (gpio_spi_xfer(spi_fd, frame_data, 32768) < 0) {
                fprintf(stderr, "Failed to read frame data from SPI device\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }

            // Write the frame data to the log file
            uint64_t timestamp = getnanosec();
            if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
                fprintf(stderr, "Failed to write timestamp to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (fwrite(&config.num_frames, sizeof(config.num_frames), 1, log_file) != 1) {
                fprintf(stderr, "Failed to write frame number to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (fwrite(frame_data, 32768, 1, log_file) != 1) {
                fprintf(stderr, "Failed to write frame data to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }

            // Free the frame data
            free(frame_data);
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Close the log file
    fclose(log_file);

    // Close the SPI device
    gpio_spi_close(spi_fd);

    // Release the GPIO pins
    gpioTerminate();

    return 0;
}

