    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write configuration to log file\n");
        fclose(log_file);
        gpio_spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Wait for the data-ready interrupt
        if (gpioRead(24) == 0) {
            // Trigger the hardware frame trigger
            gpioWrite(23, 0);
            usleep(10);
            gpioWrite(23, 1);

            // Read the frame data from the SPI device
            uint8_t *frame_data = malloc(32768);
            if (!frame_data) {
                fprintf(stderr, "Failed to allocate memory for frame data\n");
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (gpio_spi_xfer(spi_fd, frame_data, 32768) < 0) {
                fprintf(stderr, "Failed to read frame data from SPI device\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }

            // Write the frame data to the log file
            uint64_t timestamp = getnanosec();
            if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
                fprintf(stderr, "Failed to write timestamp to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (fwrite(&config.num_frames, sizeof(config.num_frames), 1, log_file) != 1) {
                fprintf(stderr, "Failed to write frame number to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (fwrite(frame_data, 32768, 1, log_file) != 1) {
                fprintf(stderr, "Failed to write frame data to log file\n");
                free(frame_data);
                fclose(log_file);
                gpio_spi_close(spi_fd);
                gpioTerminate();
                return 1;
            }

            // Free the frame data
            free(frame_data);
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Close the log file
    fclose(log_file);

    // Close the SPI device
    gpio_spi_close(spi_fd);

    // Release the GPIO pins
    gpioTerminate();

    return 0;
}
