#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

bool running = true;
gpiod_line_t line;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct tm *now;
    char timestamp[32];
    char state[16];
    FILE *log_file;
    int ret;

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpiod_chip_t *chip;
    if ((ret = gpiod_chip_open(GPIO_CHIP, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, NULL)) != 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(ret));
        return EXIT_FAILURE;
    }
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open line
    if ((ret = gpiod_line_request_output(chip, GPIO_PIN, GPIOD_LINE_REQUEST_ACTIVE_LOW)) != 0) {
        fprintf(stderr, "Failed to request line: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read line state
        if ((ret = gpiod_line_get_value(line, GPIOD_LINE_VALUE_GET)) != 0) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_error_str(ret));
            break;
        }
        bool state_new = (gpiod_line_get_value(line, GPIOD_LINE_VALUE_GET) == 1);

        // Check for state change
        if (state_new != state[0]) {
            // Get current timestamp
            time_t now_time = time(NULL);
            now = localtime(&now_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", now);

            // Write to log file
            fprintf(log_file, "%s %s\n", timestamp, state_new ? "flame detected" : "flame cleared");
            if (ferror(log_file)) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                break;
            }

            // Update state
            strcpy(state, state_new ? "1" : "0");
        }

        // Sleep
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

