#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CONVERSION_TIME_US 100000
#define MAX_RETRIES 5

// Function to handle signal interrupts
void signal_handler(int sig) {
    // Release I2C bus handle
    if (i2c_del_client(i2c_get_bus(I2C_BUS)) < 0) {
        perror("i2c_del_client");
    }

    // Close all open file handles
    fclose(fopen(NULL, "a")); // This will close all open files

    // Exit the program
    exit(0);
}

int main() {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_CLIENT_DRIVER);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    // Open the I2C device file
    char i2c_dev_path[256];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    int i2c_dev_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_dev_fd < 0) {
        perror("open");
        i2c_close(i2c_fd);
        return 1;
    }

    // Set up the I2C bus
    if (ioctl(i2c_dev_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_dev_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Configure the sensor for continuous conversion mode with automatic full-scale range
    uint8_t reg = 0x01; // Configuration register
    uint8_t val = 0x00; // Value to write
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_smbus_write_byte_data(i2c_dev_fd, reg, val) < 0) {
            perror("i2c_smbus_write_byte_data");
            close(i2c_dev_fd);
            i2c_close(i2c_fd);
            return 1;
        }
        // Wait for the conversion to complete
        usleep(CONVERSION_TIME_US);
    }

    // Open the file to write data to
    FILE *file = fopen("light_data.txt", "a");
    if (!file) {
        perror("fopen");
        close(i2c_dev_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the lux value from the sensor
        uint16_t lux;
        for (int i = 0; i < MAX_RETRIES; i++) {
            if (i2c_smbus_read_word_data(i2c_dev_fd, 0x00) < 0) {
                perror("i2c_smbus_read_word_data");
                fclose(file);
                close(i2c_dev_fd);
                i2c_close(i2c_fd);
                return 1;
            }
            // Wait for the conversion to complete
            usleep(CONVERSION_TIME_US);
        }

        // Convert the lux value to a string
        char lux_str[10];
        sprintf(lux_str, "%d", lux);

        // Get the current timestamp
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Write the data to the file
        fprintf(file, "%s %s\n", timestamp, lux_str);

        // Sleep for a short period
        usleep(100000);
    }

    // Clean up on exit
    fclose(file);
    close(i2c_dev_fd);
    i2c_close(i2c_fd);
    return 0;
}

