#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define GPIO_DIRECTION_IN
#define GPIO_ACTIVE_LOW

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *req;
    int ret;

    // Initialize the driver library
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the line as an input with a pulled-up bias
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(line, GPIO_ACTIVE_LOW);
    if (ret) {
        fprintf(stderr, "Failed to request line %d as input: %d\n", GPIO_LINE, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install a SIGINT handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!stop) {
        ret = gpiod_line_get_value(line);
        if (ret) {
            fprintf(stderr, "Failed to get line value: %d\n", ret);
            break;
        }

        time_t now;
        char timestamp[20];
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s Flame Detected: %s\n", timestamp, ret == 0 ? "YES" : "NO");

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_line_unref(line);
    gpiod_chip_unref(chip);

    return 0;
}

