#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES {2, 3, 4, 5, 6, 7, 8, 9}

int main() {
    gpiod_context *ctx;
    gpiod_chip *chip;
    gpiod_line *lines[8];
    int i;
    int ret;
    struct gpiod_line_event event;
    struct gpiod_line_event_data data;
    struct tm *timestamp;
    char timestamp_str[20];

    // Initialize the GPIO context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open(ctx, GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    // Request the lines
    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line %d: %s\n", GPIO_LINES[i], strerror(errno));
            gpiod_chip_close(chip);
            gpiod_ctx_free(ctx);
            return EXIT_FAILURE;
        }
    }

    // Set the direction of the lines to input
    for (i = 0; i < 8; i++) {
        ret = gpiod_line_request_output(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d to input: %s\n", GPIO_LINES[i], strerror(errno));
            gpiod_chip_close(chip);
            gpiod_ctx_free(ctx);
            return EXIT_FAILURE;
        }
    }

    // Handle SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        // Read the lines
        for (i = 0; i < 8; i++) {
            ret = gpiod_line_get_value(lines[i], &event, &data);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINES[i], strerror(errno));
                gpiod_chip_close(chip);
                gpiod_ctx_free(ctx);
                return EXIT_FAILURE;
            }
            if (data.value == 1) {
                printf("%d: 1\n", GPIO_LINES[i]);
            } else {
                printf("%d: 0\n", GPIO_LINES[i]);
            }
        }

        // Print timestamp
        time_t rawtime;
        time(&rawtime);
        timestamp = localtime(&rawtime);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp);
        printf("%s ", timestamp_str);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    for (i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    gpiod_ctx_free(ctx);

    return EXIT_SUCCESS;
}

