#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpiod_line_release_all();
    exit(0);
}

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize the gpiod library
    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Configure the eight sensor output pins as inputs with pull-down resistors
    for (int i = 2; i <= 9; i++) {
        struct gpiod_line *line;
        if ((line = gpiod_chip_get_line(chip, i)) == NULL) {
            perror("gpiod_chip_get_line");
            gpiod_chip_close(chip);
            exit(1);
        }
        if (gpiod_line_request_input(line, GPIOD_LINE_ACTIVE_LOW) == -1) {
            perror("gpiod_line_request_input");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(1);
        }
        gpiod_line_set_pull_up_down(line, GPIOD_LINE_PULL_DOWN);
        gpiod_line_release(line);
    }

    // Initialize the gpiod line event API
    struct gpiod_line_event *event;
    if ((event = gpiod_line_event_new(chip, 100000)) == NULL) {
        perror("gpiod_line_event_new");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the current state of the lines
        struct gpiod_line_event_value *values;
        if ((values = gpiod_line_event_read(event)) == NULL) {
            perror("gpiod_line_event_read");
            gpiod_line_event_free(event);
            gpiod_chip_close(chip);
            exit(1);
        }

        // Print the current state of the lines
        printf("[%+06d] ", (int)time(NULL));
        for (int i = 0; i < 8; i++) {
            printf("CH%d=%d ", i + 1, values[i].value);
        }
        printf("\n");

        // Free the event values
        gpiod_line_event_free(values);
    }

    // Clean up
    gpiod_line_event_free(event);
    gpiod_chip_close(chip);
    return 0;
}

