#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Release GPIO resources
    gpiod_line_release(GPIO4);
    gpiod_line_release(GPIO5);
    gpiod_ctx_release(ctx);
    exit(0);
}

int main() {
    // Initialize GPIO context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    // Initialize GPIO lines
    GPIO4 = gpiod_line_request_byname(ctx, "gpio4", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_OPEN_DRAIN);
    if (!GPIO4) {
        fprintf(stderr, "Failed to request GPIO4\n");
        gpiod_ctx_release(ctx);
        return 1;
    }

    GPIO5 = gpiod_line_request_byname(ctx, "gpio5", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_OPEN_DRAIN);
