        fprintf(stderr, "Failed to request GPIO5\n");
        gpiod_line_release(GPIO4);
        gpiod_ctx_release(ctx);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

