        // Read sensor states
        int state4 = gpiod_line_get_value(GPIO4);
        int state5 = gpiod_line_get_value(GPIO5);

        // Log sensor states
        printf("Sensor 1: %s\n", state4 ? "HIGH" : "LOW");
        printf("Sensor 2: %s\n", state5 ? "HIGH" : "LOW");

        // Sleep for 500ms
