        printf("Sensor 1: %s\n", state4 ? "HIGH" : "LOW");
        printf("Sensor 2: %s\n", state5 ? "HIGH" : "LOW");

        // Sleep for 500ms
        usleep(500000);
    }

    // Release GPIO resources
    gpiod_line_release(GPIO4);
    gpiod_line_release(GPIO5);
    gpiod_ctx_release(ctx);

    return 0;
}
