#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES {2, 3, 4, 17, 27, 22, 10, 9}
#define NUM_LINES (sizeof(GPIO_LINES) / sizeof(GPIO_LINES[0]))
#define POLL_INTERVAL 50  // ms
#define POLL_TIMEOUT 1000  // ms

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line **lines = malloc(NUM_LINES * sizeof(struct gpiod_line *));
    struct gpiod_line **lines_array = malloc(NUM_LINES * sizeof(struct gpiod_line *));
    struct tm *timestamp;
    char timestamp_str[32];
    char buffer[256];
    int i;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    // Request the lines
    for (i = 0; i < NUM_LINES; i++) {
        if ((lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i])) == NULL) {
            fprintf(stderr, "Failed to request line %d: %s\n", GPIO_LINES[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "bias-pull-down") < 0) {
            fprintf(stderr, "Failed to configure line %d as input: %s\n", GPIO_LINES[i], strerror(errno));
            gpiod_line_release(lines[i]);
            goto cleanup;
        }
        lines_array[i] = lines[i];
    }

    // Main loop
    while (running) {
        // Get the current timestamp
        time_t now = time(NULL);
        timestamp = localtime(&now);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timestamp);

        // Poll the lines
        for (i = 0; i < NUM_LINES; i++) {
            if (gpiod_line_event_wait(lines_array[i], POLL_TIMEOUT) < 0) {
                fprintf(stderr, "Failed to poll line %d: %s\n", GPIO_LINES[i], strerror(errno));
                gpiod_line_release(lines_array[i]);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
        }

        // Write the states to the console
        for (i = 0; i < NUM_LINES; i++) {
            if (gpiod_line_get_value(lines_array[i]) == 1) {
                buffer[i * 2] = '1';
            } else {
                buffer[i * 2] = '0';
            }
        }
        buffer[NUM_LINES * 2] = '\n';
        buffer[NUM_LINES * 2 + 1] = '\0';
        fprintf(stdout, "%s,%s", timestamp_str, buffer);
    }

cleanup:
    // Release the lines
    for (i = 0; i < NUM_LINES; i++) {
        gpiod_line_release(lines_array[i]);
    }

    // Close the chip
    gpiod_chip_close(chip);

    // Free the memory
    free(lines);
    free(lines_array);

    return EXIT_SUCCESS;
}

