    gpiod_close(ctx);
    exit(0);
}

int main() {
    // Print startup banner
    printf("Raspberry Pi Zero W Omron D7E-1 Tilt Sensor Poller\n");

    // Initialize GPIO context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return EXIT_FAILURE;
    }

    // Open GPIO line
    line = gpiod_line_request_by_name(ctx, "gpio4", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_REQUEST_INPUT);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO line\n");
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor
    if (gpiod_line_request_pulldown(line, 0) < 0) {
        fprintf(stderr, "Failed to enable internal pull-up resistor\n");
        gpiod_line_release(line);
        gpiod_ctx_free(ctx);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            gpiod_line_release(line);
            gpiod_ctx_free(ctx);
            return EXIT_FAILURE;
        }

        // Validate value
        if (value != 0 && value != 1) {
            fprintf(stderr, "Unexpected GPIO value: %d\n", value);
            gpiod_line_release(line);
            gpiod_ctx_free(ctx);
            return EXIT_FAILURE;
        }

        // Print tilt state
        if (value == 0) {
            printf("\033[2K\rTilted");
        } else {
            printf("\033[2K\rNot Tilted");
        }

        // Flush stdout
        fflush(stdout);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up on exit
    gpiod_line_release(line);
    gpiod_ctx_free(ctx);
    return 0;
}

