#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define CSV_FILE "uv_als_log.csv"

// Function to handle I2C communication
int i2c_read(uint8_t reg, uint8_t *buf, int len) {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        close(fd);
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C register");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to handle I2C communication and calculate UV index and ambient light
int get_uv_als_data(uint8_t *buf) {
    uint16_t uv_index, als_visible;
    if (i2c_read(0x00, buf, 2) < 0) {
        return -1;
    }
    uv_index = (buf[0] << 8) | buf[1];
    if (i2c_read(0x01, buf, 2) < 0) {
        return -1;
    }
    als_visible = (buf[0] << 8) | buf[1];
    return (uv_index << 8) | als_visible;
}

// Function to handle signal handling
void sigint_handler(int sig) {
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(0);
}

int main() {
    // Open the log file in append mode
    FILE *log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handling");
        fclose(log_file);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handling");
        fclose(log_file);
        return 1;
    }

    // Initialize I2C bus
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return 1;
    }

    // Check if the sensor is present
    uint8_t buf[2];
    if (i2c_read(0x00, buf, 2) < 0) {
        fprintf(stderr, "Error: I2C communication failed or sensor not present\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        int data = get_uv_als_data(buf);
        if (data < 0) {
            fprintf(stderr, "Error: I2C communication failed\n");
            break;
        }

        // Extract UV index and ambient light
        uint16_t uv_index = (data >> 8);
        uint16_t als_visible = data & 0xFF;

        // Print data to console
        printf("UV Index: %d, Ambient Light: %d\n", uv_index, als_visible);

        // Append data to log file
        fprintf(log_file, "%lu,%d,%d\n", time(NULL), uv_index, als_visible);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

