#define FLOW_LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define FLOW_LOG_FILE_PERMS (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)

#define SLF3S0600F_REG_CONFIG 0x00
#define SLF3S0600F_REG_STATUS 0x01
#define SLF3S0600F_REG_FLOW_RATE 0x02
#define SLF3S0600F_REG_CRC 0x03

#define SLF3S0600F_CONFIG_START 0x01
#define SLF3S0600F_CONFIG_RESET 0x00

#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

int i2c_fd;
int gpio_fd;
FILE *log_file;

void crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t i, j;
    *crc = CRC_INIT;
    for (i = 0; i < len; i++) {
        *crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = ((*crc << 1) ^ CRC_POLYNOMIAL);
            } else {
                *crc <<= 1;
            }
        }
    }
}

int read_flow_rate(int i2c_fd, uint8_t *data) {
    uint8_t reg = SLF3S0600F_REG_FLOW_RATE;
    uint8_t crc;
    int ret;

    ret = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (ret < 0) {
        fprintf(stderr, "Error reading flow rate register: %d\n", ret);
        return -1;
    }

    crc = 0;
    crc8(&reg, 1, &crc);
    crc8(data, 2, &crc);
    crc8(&crc, 1, &crc);

    if (crc != data[2]) {
        fprintf(stderr, "CRC error: expected 0x%02x, got 0x%02x\n", crc, data[2]);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void log_flow_rate(double avg_flow_rate) {
    char buffer[32];
    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s %.2f\n", buffer, avg_flow_rate);
    fflush(log_file);
}

