    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO mode: %d\n", ret);
        gpioTerminate(gpio_fd);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C address: %d\n", ret);
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %d\n", errno);
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    chmod(FLOW_LOG_FILE, FLOW_LOG_FILE_MODE);
