#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define BUFFER_SIZE 100
#define POLL_INTERVAL_US 50000
#define GPIO_PIN 7

static gpiod_line_t *line;
static gpiod_line_direction_t direction;
static gpiod_line_edge_t edge;
static gpiod_line_event_t event;
static uint8_t buffer[BUFFER_SIZE];
static uint8_t buffer_index = 0;
static uint64_t last_timestamp = 0;

void signal_handler(int sig) {
    gpiod_line_release(line);
    gpiod_context_free(gpiod_context_default());
    printf("Detection buffer:\n");
    for (uint8_t i = 0; i < BUFFER_SIZE; i++) {
        printf("%llu: %u\n", last_timestamp + (i * POLL_INTERVAL_US), buffer[i]);
    }
    exit(0);
}

int main() {
    gpiod_context_t *ctx = gpiod_context_default();
    if (!ctx) {
        fprintf(stderr, "Failed to create gpiod context\n");
        return 1;
    }

    line = gpiod_line_request_by_name(ctx, "gpio4", GPIOD_LINE_ACTIVE_STATE_HIGH, GPIOD_LINE_DIRECTION_INPUT, GPIOD_LINE_EDGE_BOTH);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_context_free(ctx);
        return 1;
    }

    direction = GPIOD_LINE_DIRECTION_INPUT;
    edge = GPIOD_LINE_EDGE_BOTH;

    gpiod_line_set_edge(line, direction, edge);

    gpiod_line_set_active_state(line, GPIOD_LINE_ACTIVE_STATE_HIGH);

    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = POLL_INTERVAL_US * 1000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpiod_line_release(line);
        gpiod_context_free(ctx);
        return 1;
    }

    while (1) {
        if (gpiod_line_event_wait(line, &event, &timer) == -1) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_line_release(line);
            gpiod_context_free(ctx);
            return 1;
        }

        if (event.value == GPIOD_LINE_EVENT_FALLING_EDGE) {
            buffer[buffer_index] = 1;
        } else {
            buffer[buffer_index] = 0;
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        last_timestamp = event.timestamp;

        if (event.value == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Obstacle detected at %llu\n", last_timestamp);
        }
    }

    return 0;
}

