#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <time.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_SPEED 400000
#define SAMPLE_INTERVAL 500000
#define MAX_SAMPLES 1000

#define I2C_SLAVE_ADDRESS 0x1D

#define CSV_FILE "fan_health.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int ret;
    uint8_t mode = 0x00;
    uint8_t data[6];
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_msg_data;
    struct timespec start_time;
    struct tm *start_time_tm;
    FILE *csv_file;
    char timestamp[32];

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up I2C pins
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Set I2C speed
    ret = ioctl(i2c_fd, I2C_SLAVE_SPEED, I2C_SPEED);
    if (ret < 0) {
        perror("Failed to set I2C speed");
        exit(EXIT_FAILURE);
    }

    // Switch sensor to mode 0
    msg.msg_type = I2C_MSG_WRITE;
    msg.addr = I2C_SLAVE_ADDRESS;
    msg.len = 1;
    msg.buf = &mode;
    i2c_msg_data.msgs = &msg;
    i2c_msg_data.nmsgs = 1;
    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_msg_data);
    if (ret < 0) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }

    // Wait for sensor to become active
    clock_gettime(CLOCK_REALTIME, &start_time);
    start_time_tm = localtime(&start_time.tv_sec);
    while (running && (time(NULL) - start_time.tv_sec) < 1) {
        ret = ioctl(i2c_fd, I2C_SLAVE_SPEED, I2C_SPEED);
        if (ret < 0) {
            perror("Failed to set I2C speed");
            continue;
        }
        msg.msg_type = I2C_MSG_READ;
        msg.addr = I2C_SLAVE_ADDRESS;
        msg.len = 1;
        msg.buf = data;
        i2c_msg_data.msgs = &msg;
        i2c_msg_data.nmsgs = 1;
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_msg_data);
        if (ret < 0) {
            perror("Failed to read from I2C bus");
            continue;
        }
        if (data[0] == 0x01) {
            break;
        }
    }
    if (!running) {
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    }
    if (time(NULL) - start_time.tv_sec >= 1) {
        fprintf(stderr, "Sensor did not become active within 1 second\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header row to CSV file
    fprintf(csv_file, "timestamp,X,Y,Z\n");

    // Poll sensor
    while (running) {
        clock_gettime(CLOCK_REALTIME, &start_time);
        ret = ioctl(i2c_fd, I2C_SLAVE_SPEED, I2C_SPEED);
        if (ret < 0) {
            perror("Failed to set I2C speed");
            continue;
        }
        msg.msg_type = I2C_MSG_READ;
        msg.addr = I2C_SLAVE_ADDRESS;
        msg.len = 6;
        msg.buf = data;
        i2c_msg_data.msgs = &msg;
        i2c_msg_data.nmsgs = 1;
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_msg_data);
        if (ret < 0) {
            perror("Failed to read from I2C bus");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", start_time_tm);
        fprintf(csv_file, "%s,%02x,%02x,%02x\n", timestamp, data[1], data[2], data[3]);
        usleep(SAMPLE_INTERVAL);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C file descriptor
    close(i2c_fd);

    return EXIT_SUCCESS;
}

