    if (pin1 == -1 || pin2 == -1 || pin_led == -1) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line direction
    int dir1 = gpiod_line_request_output(pin1, "in");
    int dir2 = gpiod_line_request_output(pin2, "in");
    int dir_led = gpiod_line_request_output(pin_led, "out");
