#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define STALL_CONFIRMATION_TIME 2  // seconds
#define STALL_LOG_FILE "stall_log.txt"

bool stall_confirmed = false;
time_t last_stall_timestamp = 0;
bool sensor1_last_read = false;
bool sensor2_last_read = false;

void sigint_handler(int sig) {
    (void)sig;
    printf("Caught signal, exiting...\n");
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    (void)sig;
    printf("Caught signal, exiting...\n");
    gpioTerminate();
    exit(0);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }
    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR1);
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR2);
        gpioTerminate();
        exit(1);
    }
}

void read_sensors() {
    int sensor1_value = gpioRead(GPIO_SENSOR1);
    int sensor2_value = gpioRead(GPIO_SENSOR2);
    if (sensor1_value == 0 && sensor2_value == 0) {
        if (!stall_confirmed) {
            stall_confirmed = true;
            last_stall_timestamp = time(NULL);
        }
    } else {
        stall_confirmed = false;
    }
    sensor1_last_read = (bool)sensor1_value;
    sensor2_last_read = (bool)sensor2_value;
}

void log_stall() {
    FILE *file = fopen(STALL_LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", STALL_LOG_FILE, strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&last_stall_timestamp));
    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        exit(1);
    }
    init_gpio();
    while (1) {
        read_sensors();
        if (stall_confirmed && difftime(time(NULL), last_stall_timestamp) >= STALL_CONFIRMATION_TIME) {
            log_stall();
        }
        usleep(100000);  // 100ms
    }
    return 0;
}

