#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define CSV_FILE "magnetic_log.csv"

// Function to handle SIGINT and SIGTERM signals
void sigint_handler(int sig) {
    // Cleanly release resources
    i2c_close(I2C_BUS);
    fclose(flog);
    tmag5170_cleanup();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    FILE *flog = fopen(CSV_FILE, "w");
    if (!flog) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Write header row to CSV file
    fprintf(flog, "timestamp,X,Y,Z\n");

    // Initialize TMAG5170 sensor
    if (tmag5170_init(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize TMAG5170 sensor\n");
        fclose(flog);
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Configure TMAG5170 sensor for continuous-conversion mode with all three axes enabled and 50mT range
    if (tmag5170_config(i2c_fd, I2C_ADDRESS, TMAG5170_CONTINUOUS_MODE, TMAG5170_ALL_AXES, TMAG5170_RANGE_50MT) < 0) {
        fprintf(stderr, "Failed to configure TMAG5170 sensor\n");
        tmag5170_cleanup();
        fclose(flog);
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&tv.tv_sec));
        strncat(timestamp, ".", 1);
        sprintf(timestamp + strlen(timestamp), "%06d", tv.tv_usec);

        // Read X, Y, and Z magnetic field values
        int16_t x, y, z;
        if (tmag5170_read(i2c_fd, I2C_ADDRESS, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read TMAG5170 sensor\n");
            continue;
        }

        // Write reading to CSV file
        fprintf(flog, "%s,%d,%d,%d\n", timestamp, x, y, z);

        // Sleep for 100ms
        usleep(100000);
    }

    return 0;
}

