#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60

// Function to handle signal to exit cleanly
void sigint_handler(int sig) {
    gpiod_close();
    syslog(LOG_INFO, "Exiting cleanly");
    exit(0);
}

// Function to handle signal to exit cleanly
void sigterm_handler(int sig) {
    gpiod_close();
    syslog(LOG_INFO, "Exiting cleanly");
    exit(0);
}

int main() {
    // Initialize logging
    openlog(NULL, LOG_PID, LOG_USER);

    // Initialize GPIO
    gpiod_context *ctx = gpiod_ctx_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create GPIO context");
        return 1;
    }

    // Open GPIO line
    gpiod_line *line = gpiod_line_new(ctx, "gpio23", GPIOD_LINE_ACTIVE_LOW);
    if (!line) {
        syslog(LOG_ERR, "Failed to open GPIO line");
        gpiod_ctx_free(ctx);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_line_release(line);
        gpiod_ctx_free(ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO line");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_ctx_free(ctx);
            sleep(REINIT_DELAY);
            continue;
        }

        // Check if water detected
        if (value == 1) {
            // Log alert
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
            fprintf(log_file, "%s ALERT: Water detected\n", timestamp);
            syslog(LOG_INFO, "Water detected");
            printf("Water detected\n");
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_ctx_free(ctx);
    closelog();

    return 0;
}

