#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_WINDOW 1000  // 1 second

volatile int pulse_count = 0;
volatile bool alert = false;
volatile bool timer_running = false;

void alert_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        atomic_fetch_add_explicit(&pulse_count, 1, memory_order_relaxed);
    }
}

void timer_callback() {
    if (timer_running) {
        timer_running = false;
        alert = false;
    }
}

void sigint_handler(int sig) {
    timer_running = false;
    alert = false;
}

void sigterm_handler(int sig) {
    timer_running = false;
    alert = false;
}

int main() {
    int fd;
    int ret;
    struct itimerspec timer;
    struct sigaction sa;
    struct tm time;
    char log_line[32];

    // Initialize GPIO
    if ((fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioError(fd));
        return 1;
    }

    // Set up GPIO pin as input with internal pull-up resistor
    if (gpioSetMode(fd, GPIO_PIN, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", gpioError(fd));
        gpioTerminate(fd);
        return 1;
    }
    if (gpioSetPullUpDown(fd, GPIO_PIN, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down: %s\n", gpioError(fd));
        gpioTerminate(fd);
        return 1;
    }

    // Set up GPIO interrupt
    if (gpioSetISR(fd, GPIO_PIN, RISING_EDGE, alert_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO interrupt: %s\n", gpioError(fd));
        gpioTerminate(fd);
        return 1;
    }

    // Set up timer
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 0;
    timer.it_value.tv_sec = SAMPLE_WINDOW / 1000000;
    timer.it_value.tv_nsec = (SAMPLE_WINDOW % 1000000) * 1000;
    if (timerfd_create(CLOCK_REALTIME, 0) == -1) {
        perror("timerfd_create");
        gpioTerminate(fd);
        return 1;
    }
    if (timerfd_settime(fd, 0, &timer, NULL) == -1) {
        perror("timerfd_settime");
        close(fd);
        gpioTerminate(fd);
        return 1;
    }
    sa.sa_handler = timer_callback;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        gpioTerminate(fd);
        return 1;
    }

    // Open log file
    if ((fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        perror("open");
        close(timerfd);
        gpioTerminate(fd);
        return 1;
    }

    // Install signal handlers
    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        close(timerfd);
        gpioTerminate(fd);
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        close(timerfd);
        gpioTerminate(fd);
        return 1;
    }

    // Start timer
    if (timerfd_settime(fd, 0, &timer, NULL) == -1) {
        perror("timerfd_settime");
        close(fd);
        close(timerfd);
        gpioTerminate(fd);
        return 1;
    }

    // Main loop
    while (1) {
        struct itimerspec remaining;
        if (timerfd_gettime(fd, &remaining) == -1) {
            perror("timerfd_gettime");
            close(fd);
            close(timerfd);
            gpioTerminate(fd);
            return 1;
        }
        if (remaining.it_value.tv_sec == 0 && remaining.it_value.tv_nsec == 0) {
            break;
        }
        if (atomic_load_explicit(&pulse_count, memory_order_relaxed) == 0) {
            // If no pulses were detected, log an RPM of 0
            time = *localtime(&time(NULL));
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S %d RPM", &time);
            write(fd, log_line, strlen(log_line));
            write(fd, " 0\n", 3);
            write(STDOUT_FILENO, log_line, strlen(log_line));
            write(STDOUT_FILENO, " 0\n", 3);
            fflush(fd);
        } else {
            // Compute RPM
            double rpm = (double)atomic_load_explicit(&pulse_count, memory_order_relaxed) * 60 / (SAMPLE_WINDOW / 1000000.0);
            time = *localtime(&time(NULL));
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S %d RPM", &time);
            write(fd, log_line, strlen(log_line));
            write(fd, " ", 1);
            char rpm_str[10];
            sprintf(rpm_str, "%.2f", rpm);
            write(fd, rpm_str, strlen(rpm_str));
            write(fd, "\n", 1);
            write(STDOUT_FILENO, log_line, strlen(log_line));
            write(STDOUT_FILENO, " ", 1);
            write(STDOUT_FILENO, rpm_str, strlen(rpm_str));
            write(STDOUT_FILENO, "\n", 1);
            fflush(fd);
        }
        atomic_store_explicit(&pulse_count, 0, memory_order_relaxed);
    }

    // Clean up
    close(fd);
    close(timerfd);
    gpioTerminate(fd);
    return 0;
}

