#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define ROTATION_LOG_FILE "rotation_log.txt"

// Mutex for protecting shared state
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared state for quadrature state machine
enum { STATE_A, STATE_B, STATE_AB, STATE_BA };
int state = STATE_A;

// Condition variable for main loop to wait on
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Flag to indicate if the program should exit
volatile bool exit_flag = false;

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    (void)sig;
    exit_flag = true;
}

// Interrupt service routine for GPIO17
void gpio17_isr(int instance, uint32_t value, uint32_t timestamp) {
    (void)instance;
    (void)timestamp;

    // Acquire the mutex to protect shared state
    pthread_mutex_lock(&state_mutex);

    // Update the state based on the interrupt
    if (value == 1) {
        switch (state) {
            case STATE_A:
                state = STATE_AB;
                break;
            case STATE_AB:
                state = STATE_B;
                break;
            case STATE_B:
                state = STATE_BA;
                break;
            case STATE_BA:
                state = STATE_A;
                break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&state_mutex);

    // Signal the main loop to wake up
    pthread_cond_signal(&cond);
}

// Interrupt service routine for GPIO27
void gpio27_isr(int instance, uint32_t value, uint32_t timestamp) {
    (void)instance;
    (void)timestamp;

    // Acquire the mutex to protect shared state
    pthread_mutex_lock(&state_mutex);

    // Update the state based on the interrupt
    if (value == 1) {
        switch (state) {
            case STATE_A:
                state = STATE_BA;
                break;
            case STATE_AB:
                state = STATE_A;
                break;
            case STATE_B:
                state = STATE_AB;
                break;
            case STATE_BA:
                state = STATE_B;
                break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&state_mutex);

    // Signal the main loop to wake up
    pthread_cond_signal(&cond);
}

int main() {
    // Install signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    struct gpiod_line *line17, *line27;
    if ((line17 = gpiod_line_request_byname(NULL, "gpio17", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_REQUEST_INPUT)) == NULL) {
        perror("gpiod_line_request_byname");
        return EXIT_FAILURE;
    }
    if ((line27 = gpiod_line_request_byname(NULL, "gpio27", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_REQUEST_INPUT)) == NULL) {
        gpiod_line_release(line17);
        perror("gpiod_line_request_byname");
        return EXIT_FAILURE;
    }

    // Set up interrupt handling
    if (gpiod_line_set_event_fd(line17, GPIOD_LINE_EVENT_BOTH) == -1) {
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        perror("gpiod_line_set_event_fd");
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_event_fd(line27, GPIOD_LINE_EVENT_BOTH) == -1) {
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        perror("gpiod_line_set_event_fd");
        return EXIT_FAILURE;
    }

    // Open the log file
    int fd = open(ROTATION_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        perror("open");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // Wait for an interrupt
        pthread_cond_wait(&cond, &state_mutex);

        // Acquire the mutex to protect shared state
        pthread_mutex_lock(&state_mutex);

        // Check if the state has changed
        if (state != STATE_A) {
            // Log the rotation event
            char timestamp[20];
            struct timeval tv;
            gettimeofday(&tv, NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", localtime(&tv.tv_sec));
            char log_entry[100];
            sprintf(log_entry, "%s %s\n", timestamp, state == STATE_BA ? "clockwise" : "counter-clockwise");
            if (write(fd, log_entry, strlen(log_entry)) == -1) {
                perror("write");
            }
        }

        // Release the mutex
        pthread_mutex_unlock(&state_mutex);
    }

    // Close the log file
    if (close(fd) == -1) {
        perror("close");
    }

    // Release GPIO resources
    gpiod_line_release(line17);
    gpiod_line_release(line27);

    return EXIT_SUCCESS;
}

