    gpiod_chip *chip;
    int ret = gpiod_chip_open(GPIO_CHIP, GPIOD_LINE_REQUEST, &chip);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_error_str(ret));
        exit(1);
    }
    syslog(LOG_INFO, "Opened GPIO chip");

    // Request the input line for the sensor
    gpiod_line *sensor_line;
    ret = gpiod_chip_request_line(chip, GPIO_SENSOR_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_OUTPUT, &sensor_line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request sensor line: %s", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        exit(1);
    }
    syslog(LOG_INFO, "Requested sensor line");

    // Request the output line for the LED
    gpiod_line *led_line;
    ret = gpiod_chip_request_line(chip, GPIO_LED_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_OUTPUT, &led_line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line: %s", gpiod_error_str(ret));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    syslog(LOG_INFO, "Requested LED line");

    // Set the LED line to low (off)
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set LED line to low: %s", gpiod_error_str(ret));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read the sensor line
        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read sensor line: %s", gpiod_error_str(ret));
            gpiod_line_release(sensor_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(1);
        }

        // If the sensor is touched, turn on the LED
        if (ret == 1) {
            syslog(LOG_INFO, "Sensor touched");
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to set LED line to high: %s", gpiod_error_str(ret));
                gpiod_line_release(sensor_line);
                gpiod_line_release(led_line);
                gpiod_chip_close(chip);
                exit(1);
            }
        } else {
            // If the sensor is not touched, turn off the LED
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to set LED line to low: %s", gpiod_error_str(ret));
                gpiod_line_release(sensor_line);
                gpiod_line_release(led_line);
                gpiod_chip_close(chip);
                exit(1);
            }
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // This line will never be reached
    return 0;
}

