#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

#define LOG_SIZE 100
#define DEBOUNCE_TIME 50

struct log_entry {
    int sensor;
    int state;
    uint64_t timestamp;
};

struct log_entry log_buffer[LOG_SIZE];
int log_index = 0;
int log_overflow_count = 0;

void cleanup() {
    gpiod_line_release(GPIOD_LINE(27);
    gpiod_line_release(GPIOD_LINE(22);
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *led1, *led2;
    struct gpiod_line_event event;
    struct itimerspec timer;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line1 = gpiod_chip_get_line(chip, 4);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get line 4\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    line2 = gpiod_chip_get_line(chip, 17);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        exit(1);
    }

    led1 = gpiod_chip_get_line(chip, 27);
    if (led1 == NULL) {
        fprintf(stderr, "Failed to get line 27\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        exit(1);
    }

    led2 = gpiod_chip_get_line(chip, 22);
    if (led2 == NULL) {
        fprintf(stderr, "Failed to get line 22\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(led1);
        exit(1);
    }

    // Set up LEDs as outputs
    ret = gpiod_line_request_output(line1, GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_HIGH);
    if (ret != 0) {
        fprintf(stderr, "Failed to request line 27 as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(led2);
        exit(1);
    }

    ret = gpiod_line_request_output(line2, GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_HIGH);
    if (ret != 0) {
        fprintf(stderr, "Failed to request line 22 as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(led2);
        exit(1);
    }

    // Set up timer
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = DEBOUNCE_TIME * 1000000;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = DEBOUNCE_TIME * 1000000;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        ret = gpiod_line_event_read(line1, &event, 1);
        if (ret != 0) {
            fprintf(stderr, "Failed to read event from line 4\n");
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_line_release(led1);
            gpiod_line_release(led2);
            exit(1);
        }

        if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
            gpiod_line_set_value(led1, 1);
            log_buffer[log_index].sensor = 4;
            log_buffer[log_index].state = 1;
            log_buffer[log_index].timestamp = time(NULL);
            log_index = (log_index + 1) % LOG_SIZE;
            if (log_index == 0) {
                log_overflow_count++;
            }
        } else if (event.event == GPIOD_LINE_EVENT_FALLING_EDGE) {
            gpiod_line_set_value(led1, 0);
            log_buffer[log_index].sensor = 4;
            log_buffer[log_index].state = 0;
            log_buffer[log_index].timestamp = time(NULL);
            log_index = (log_index + 1) % LOG_SIZE;
            if (log_index == 0) {
                log_overflow_count++;
            }
        }

        ret = gpiod_line_event_read(line2, &event, 1);
        if (ret != 0) {
            fprintf(stderr, "Failed to read event from line 17\n");
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_line_release(led1);
            gpiod_line_release(led2);
            exit(1);
        }

        if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
            gpiod_line_set_value(led2, 1);
            log_buffer[log_index].sensor = 17;
            log_buffer[log_index].state = 1;
            log_buffer[log_index].timestamp = time(NULL);
            log_index = (log_index + 1) % LOG_SIZE;
            if (log_index == 0) {
                log_overflow_count++;
            }
        } else if (event.event == GPIOD_LINE_EVENT_FALLING_EDGE) {
            gpiod_line_set_value(led2, 0);
            log_buffer[log_index].sensor = 17;
            log_buffer[log_index].state = 0;
            log_buffer[log_index].timestamp = time(NULL);
            log_index = (log_index + 1) % LOG_SIZE;
            if (log_index == 0) {
                log_overflow_count++;
            }
        }

        // Print log buffer
        for (int i = 0; i < LOG_SIZE; i++) {
            if (log_buffer[i].sensor != 0) {
                printf("%d %d %lu\n", log_buffer[i].sensor, log_buffer[i].state, log_buffer[i].timestamp);
            }
        }

        // Print overflow count
        printf("Overflow count: %d\n", log_overflow_count);

        // Sleep
        nanosleep(&timer);
    }

    return 0;
}

