#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL 500  // ms

static volatile bool running = true;
static FILE *log_file = NULL;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line;
    line = gpiod_chip_get_line(chip, RAIN_SENSOR_GPIO);
    if (line == NULL) {
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Enable internal pull-up resistor
    if (gpiod_line_request_output(line, "rain_sensor", GPIOD_LINE_ACTIVE_HIGH) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Set initial state
    uint32_t state;
    if (gpiod_line_get_value(line, &state) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    bool last_state = state == 0;

    while (running) {
        // Poll GPIO pin
        if (gpiod_line_get_value(line, &state) != 0) {
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Check for state change
        if (state != last_state) {
            last_state = state;
            char *message = state == 0 ? "Rain Detected" : "No Rain";
            syslog(LOG_INFO, "%s", message);
            fprintf(log_file, "%s\n", message);
            fflush(log_file);
        }

        // Sleep
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

