#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x00 // Replace with the actual I2C address of the Si1182 sensor
#define LOG_FILE "biometric_log.txt"

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close I2C handle
    if (i2c_close(fd) < 0) {
        perror("i2c_close");
    }

    // Close log file
    if (fclose(log_file) != 0) {
        perror("fclose");
    }

    // Unregister SIGINT handler
    signal(SIGINT, SIG_DFL);

    // Exit the program
    exit(0);
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Open I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    fd = i2c_open(i2c_dev_path, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(1);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }

    // Initialize I2C communication
    uint8_t reg = 0x00; // Replace with the actual register address
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read data from the Si1182 sensor
        uint8_t data[2];
        if (i2c_smbus_read_i2c_block_data(fd, reg, 2, data) < 0) {
            fprintf(stderr, "Error reading from I2C bus\n");
            continue;
        }

        // Extract heart rate and SpO2 data
        uint16_t heart_rate = (data[0] << 8) | data[1];
        uint8_t spo2 = data[2];

        // Format the log string
        char log_str[50];
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S, Heart Rate: %d BPM, SpO2: %d%%", lt, &heart_rate, spo2);

        // Write to log file
        if (fprintf(log_file, "%s\n", log_str) < 0) {
            perror("fprintf");
        }
        if (fflush(log_file) != 0) {
            perror("fflush");
        }

        // Pause for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    if (i2c_close(fd) < 0) {
        perror("i2c_close");
    }

    // Close log file
    if (fclose(log_file) != 0) {
        perror("fclose");
    }

    return 0;
}

