#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define TILT_THRESHOLD 1
#define TILT_TIMEOUT 2000  // 2 seconds
#define LOG_FILE "bridge_integrity.log"

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpiod_close();
    fclose(log_file);
    syslog(LOG_INFO, "Alarm deactivated and log file closed.");
    exit(0);
}

int main() {
    // Initialize the logger
    openlog(NULL, LOG_PID | LOG_CONS, LOG_USER);

    // Initialize the GPIO library
    gpiod_context *ctx = gpiod_ctx_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        exit(1);
    }

    // Open the GPIO lines
    gpiod_line *line17 = gpiod_line_request_by_name(ctx, "gpio17", GPIOD_LINE_ACTIVE_LOW);
    gpiod_line *line18 = gpiod_line_request_by_name(ctx, "gpio18", GPIOD_LINE_ACTIVE_LOW);
    gpiod_line *line27 = gpiod_line_request_by_name(ctx, "gpio27", GPIOD_LINE_ACTIVE_HIGH);

    if (!line17 || !line18 || !line27) {
        syslog(LOG_ERR, "Failed to open GPIO lines");
        gpiod_ctx_free(ctx);
        exit(1);
    }

    // Set the initial state of the lines
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    gpiod_line_set_value(line27, 0);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        gpiod_ctx_free(ctx);
        exit(1);
    }

    // Set up the alarm
    gpiod_line_direction(line27, GPIOD_DIRECTION_OUTPUT);

    // Initialize variables to track the last state of the sensors
    bool last_state17 = false;
    bool last_state18 = false;
    time_t last_tilt_time = 0;

    // Main loop
    while (1) {
        // Read the current state of the sensors
        gpiod_line_value_t state17 = gpiod_line_get_value(line17);
        gpiod_line_value_t state18 = gpiod_line_get_value(line18);

        // Check if the sensors have changed state
        if (state17 != last_state17 || state18 != last_state18) {
            // Log the event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: Tilt detected\n", timestamp);

            // Check if the alarm should be activated
            if (state17 == 1 || state18 == 1) {
                gpiod_line_set_value(line27, 1);
                syslog(LOG_INFO, "Alarm activated");
            } else {
                gpiod_line_set_value(line27, 0);
                syslog(LOG_INFO, "Alarm deactivated");
            }

            // Update the last state of the sensors
            last_state17 = state17;
            last_state18 = state18;
            last_tilt_time = time(NULL);
        }

        // Check if the alarm should be activated due to a timeout
        if (time(NULL) - last_tilt_time > TILT_TIMEOUT / 1000) {
            gpiod_line_set_value(line27, 1);
            syslog(LOG_INFO, "Alarm activated due to timeout");
        }

        // Check if the sensors have returned to their initial state
        if (state17 == 0 && state18 == 0) {
            gpiod_line_set_value(line27, 0);
            syslog(LOG_INFO, "Alarm deactivated");
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up on exit
    fclose(log_file);
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_line_release(line27);
    gpiod_ctx_free(ctx);
    closelog();
    return 0;
}

