    // Cleanly release resources
    i2c_close();
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (i2cOpen(1, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    FILE *log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close();
        gpioTerminate();
        return 1;
    }

    // Initialize alert LED
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);
    gpioSetPullUpDnControl(ALERT_LED_GPIO, PI_PUD_UP);

    // Initialize sensor
    uint8_t ctrl1;
    if (i2c_read_byte(SEISMIC_SENSOR_ADDRESS, 0x00, &ctrl1, 1, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read CTRL1 register\n");
        i2c_close();
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    ctrl1 &= ~(1 << 7); // Clear power-down bit
    if (i2c_write_byte(SEISMIC_SENSOR_ADDRESS, 0x00, ctrl1, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to write CTRL1 register\n");
        i2c_close();
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll sensor
        uint16_t x, y, z;
        if (i2c_read_word(SEISMIC_SENSOR_ADDRESS, 0x02, &x, 1, MAX_RETRIES) < 0 ||
            i2c_read_word(SEISMIC_SENSOR_ADDRESS, 0x04, &y, 1, MAX_RETRIES) < 0 ||
            i2c_read_word(SEISMIC_SENSOR_ADDRESS, 0x06, &z, 1, MAX_RETRIES) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            i2c_close();
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Calculate Euclidean vibration magnitude
        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z);

        // Check if magnitude exceeds threshold
        if (magnitude > THRESHOLD) {
            // Log event
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_file, "%s: %f\n", timestamp, magnitude);

