            gpioWrite(ALERT_LED_GPIO, 1);

            // Wait for 1 second
            usleep(1000000);

            // Turn off alert LED
            gpioWrite(ALERT_LED_GPIO, 0);
        }

        // Wait for next poll interval
        usleep(POLL_INTERVAL_US);
    }

    // Cleanly release resources
    i2c_close();
    fclose(log_file);
    gpioTerminate();

    return 0;
