#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle signal to clean up GPIO resources
void cleanup(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    exit(0);
}

int main() {
    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the GPIO chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Request the GPIO lines
    struct gpiod_line *lines[4];
    lines[0] = gpiod_chip_get_line(chip, 4);
    lines[1] = gpiod_chip_get_line(chip, 17);
    lines[2] = gpiod_chip_get_line(chip, 27);
    lines[3] = gpiod_chip_get_line(chip, 22);
    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Configure the lines as inputs
    struct gpiod_line_request_options req_opts = {
        .direction = GPIOD_LINE_REQUEST_INPUT,
        .active_state = GPIOD_LINE_ACTIVE_LOW,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH,
    };
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request(lines[i], &req_opts) == -1) {
            perror("gpiod_line_request");
            gpiod_chip_close(chip);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            exit(1);
        }
    }

    // Open the LED GPIO line
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, 18);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(lines[i]);
        }
        exit(1);
    }

    // Configure the LED line as an output
    struct gpiod_line_request_options led_opts = {
        .direction = GPIOD_LINE_REQUEST_OUTPUT,
        .active_state = GPIOD_LINE_ACTIVE_HIGH,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH,
    };
    if (gpiod_line_request(led_line, &led_opts) == -1) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(lines[i]);
        }
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the sensor values
        int sensor_values[4];
        for (int i = 0; i < 4; i++) {
            sensor_values[i] = gpiod_line_get_value(lines[i]);
            if (sensor_values[i] == -1) {
                perror("gpiod_line_get_value");
                gpiod_chip_close(chip);
                gpiod_line_release(led_line);
                for (int j = 0; j < 4; j++) {
                    gpiod_line_release(lines[j]);
                }
                exit(1);
            }
        }

        // Turn the LED on if any sensor detects an object
        int any_object = 0;
        for (int i = 0; i < 4; i++) {
            if (sensor_values[i] == 0) {
                any_object = 1;
                break;
            }
        }
        if (any_object) {
            gpiod_line_set_value(led_line, 0);
        } else {
            gpiod_line_set_value(led_line, 1);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(led_line);
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return 0;
}

