    int chip_fd;
    struct gpiod_line **lines = malloc(NUM_SENSORS * sizeof(struct gpiod_line *));
    struct gpiod_line **lines_requested = malloc(NUM_SENSORS * sizeof(struct gpiod_line *));
    char *log_file = "/var/log/flame_events.log";
