#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define LOG_FILE "grow_log.txt"
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define I2C_BUS 1
#define I2C_ADDR 0x5C

#define LUX_THRESHOLD_100 100
#define LUX_THRESHOLD_500 500
#define LUX_THRESHOLD_1000 1000

#define ERROR_CODE_OK 0
#define ERROR_CODE_I2C_ERROR -1
#define ERROR_CODE_SENSOR_ERROR -2
#define ERROR_CODE_LOG_ERROR -3

int log_file_fd = -1;
int gpio_fd = -1;

void log_event(int error_code, int lux, int brightness) {
    struct tm *timeinfo;
    time_t rawtime;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char log_line[100];
    sprintf(log_line, "%s lux=%d brightness=%d error_code=%d\n", timestamp, lux, brightness, error_code);
    if (write(log_file_fd, log_line, strlen(log_line)) != strlen(log_line)) {
        perror("write");
        exit(ERROR_CODE_LOG_ERROR);
    }
    if (fsync(log_file_fd) != 0) {
        perror("fsync");
        exit(ERROR_CODE_LOG_ERROR);
    }
}

void cleanup() {
    if (gpio_fd != -1) {
        gpioPWM(LED_PIN, 0);
        gpioTerminate();
        close(gpio_fd);
    }
    if (log_file_fd != -1) {
        close(log_file_fd);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return ERROR_CODE_I2C_ERROR;
    }
    gpio_fd = gpioOpen(I2C_BUS, 0);
    if (gpio_fd < 0) {
        perror("gpioOpen");
        gpioTerminate();
        return ERROR_CODE_I2C_ERROR;
    }

    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd < 0) {
        perror("open");
        gpioTerminate();
        return ERROR_CODE_LOG_ERROR;
    }

    int i2c_fd = gpioI2COpen(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("gpioI2COpen");
        close(log_file_fd);
        gpioTerminate();
        return ERROR_CODE_I2C_ERROR;
    }

    int reg = 0x00;
    if (gpioI2CWriteReg8(i2c_fd, 0x00, 0x0A) != 0) {
        perror("gpioI2CWriteReg8");
        close(log_file_fd);
        gpioTerminate();
        return ERROR_CODE_I2C_ERROR;
    }

    while (1) {
        int lux = 0;
        if (gpioI2CReadReg8(i2c_fd, 0x00, &reg) != 0) {
            perror("gpioI2CReadReg8");
            log_event(ERROR_CODE_SENSOR_ERROR, lux, 0);
            continue;
        }
        lux = (reg >> 8) & 0xFF;

        int brightness;
        if (lux < LUX_THRESHOLD_100) {
            brightness = PWM_RANGE;
        } else if (lux < LUX_THRESHOLD_500) {
            brightness = (int)((PWM_RANGE * (LUX_THRESHOLD_500 - lux)) / (LUX_THRESHOLD_500 - LUX_THRESHOLD_100));
        } else if (lux < LUX_THRESHOLD_1000) {
            brightness = (int)((PWM_RANGE * (LUX_THRESHOLD_1000 - lux)) / (LUX_THRESHOLD_1000 - LUX_THRESHOLD_500));
        } else {
            brightness = 0;
        }

        if (gpioPWM(LED_PIN, brightness) != 0) {
            perror("gpioPWM");
            log_event(ERROR_CODE_I2C_ERROR, lux, brightness);
            continue;
        }

        log_event(ERROR_CODE_OK, lux, brightness);
        sleep(1);
    }

    cleanup();
    return 0;
}

