        if (gpioI2CReadReg8(i2c_fd, 0x00, &reg) != 0) {
            perror("gpioI2CReadReg8");
            log_event(ERROR_CODE_SENSOR_ERROR, lux, 0);
            continue;
        }
        lux = (reg >> 8) & 0xFF;

        int brightness;
        if (lux < LUX_THRESHOLD_100) {
            brightness = PWM_RANGE;
        } else if (lux < LUX_THRESHOLD_500) {
            brightness = (int)((PWM_RANGE * (LUX_THRESHOLD_500 - lux)) / (LUX_THRESHOLD_500 - LUX_THRESHOLD_100));
        } else if (lux < LUX_THRESHOLD_1000) {
            brightness = (int)((PWM_RANGE * (LUX_THRESHOLD_1000 - lux)) / (LUX_THRESHOLD_1000 - LUX_THRESHOLD_500));
        } else {
            brightness = 0;
        }

        if (gpioPWM(LED_PIN, brightness) != 0) {
            perror("gpioPWM");
            log_event(ERROR_CODE_I2C_ERROR, lux, brightness);
            continue;
        }

        log_event(ERROR_CODE_OK, lux, brightness);
        sleep(1);
    }

    cleanup();
    return 0;
}
```

This code implements an adaptive grow light system using a VEML7700 lux sensor on I2C bus 1 to set the brightness of a grow light LED connected to GPIO18 (BCM) with hardware PWM at a 1000 Hz frequency. It samples the ambient light every 1 second, maps lux readings to PWM duty cycles in the range 0-100 according to the rule lux < 100 → 100% brightness, lux < 500 → 75%, lux < 1000 → 50%, lux ≥ 1000 → 25%, and writes a line to "grow_log.txt" after each sample that contains an ISO-8601 timestamp, the measured lux value, the selected brightness level, and an error code. It also provides a graceful shutdown on receipt of SIGINT or SIGTERM that turns off the LED, closes the I2C bus, closes the log file, and terminates the driver cleanly.

