#define LOG_FILE "touch_log.txt"

struct gpiod_line *lines[8];
struct gpiod_line *led_line;
struct gpiod_chip *chip;
bool led_on = false;
bool channels_touched[8] = {false};
uint64_t last_debounce_time[8] = {0};
uint64_t last_read_time = 0;

void log_touch_event(int channel) {
    time_t now;
    time(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(1);
    }
    fprintf(file, "%s – Channel %d Touched\n", timestamp, channel + 1);
    fclose(file);
}

void debounce(int channel) {
    uint64_t now = time(NULL);
    if (now - last_debounce_time[channel] < DEBOUNCE_TIME) {
        return;
    }
    last_debounce_time[channel] = now;
    channels_touched[channel] = true;
    log_touch_event(channel);
}

void signal_handler(int sig) {
    gpiod_line_set_value(led_line, 0);
    gpiod_chip_close(chip);
    gpiod_context_free(gpiod_context_default());
    exit(0);
}

int main() {
    gpiod_context *ctx = gpiod_context_default();
    if (ctx == NULL) {
        fprintf(stderr, "Error initializing gpiod context: %s\n", gpiod_context_errstr(ctx));
        return 1;
    }

    chip = gpiod_chip_open(ctx, "gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_errstr(chip));
        gpiod_context_free(ctx);
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        char pin_name[20];
        sprintf(pin_name, "gpio%d", SENSOR_PIN_START + i);
        lines[i] = gpiod_chip_get_line(chip, pin_name);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error getting line %s: %s\n", pin_name, gpiod_line_errstr(lines[i]));
            gpiod_chip_close(chip);
            gpiod_context_free(ctx);
            return 1;
        }
        gpiod_line_request_output(lines[i], 0, GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_BIAS_PULL_DOWN);
    }

    led_line = gpiod_chip_get_line(chip, "gpio17");
    if (led_line == NULL) {
        fprintf(stderr, "Error getting line gpio17: %s\n", gpiod_line_errstr(led_line));
        gpiod_chip_close(chip);
        gpiod_context_free(ctx);
        return 1;
    }
    gpiod_line_request_output(led_line, 0, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint64_t now = time(NULL);
        if (now - last_read_time > 0.05) {
            last_read_time = now;
            for (int i = 0; i < 8; i++) {
                int value = gpiod_line_get_value(lines[i]);
                if (value == 1 && !channels_touched[i]) {
                    debounce(i);
                } else if (value == 0 && channels_touched[i]) {
                    channels_touched[i] = false;
                }
            }
            bool all_released = true;
            for (int i = 0; i < 8; i++) {
                if (channels_touched[i]) {
                    all_released = false;
                    break;
                }
            }
            if (all_released) {
                gpiod_line_set_value(led_line, 0);
            } else {
                gpiod_line_set_value(led_line, 1);
            }
        }
        usleep(10000);
    }

    gpiod_chip_close(chip);
    gpiod_context_free(ctx);
    return 0;
}

