#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x27 // OPT3001 I2C address
#define FILE_NAME "light_data.txt"

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_close();
    exit(0);
}

int main() {
    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open I2C bus
    int i2c_fd = gpiod_open(I2C_BUS);
    if (i2c_fd == -1) {
        perror("gpiod_open");
        exit(1);
    }

    // Open log file
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_close(i2c_fd);
        exit(1);
    }

    // Set up OPT3001 configuration
    uint8_t config = 0x00; // Default configuration
    if (gpiod_i2c_write(i2c_fd, I2C_ADDRESS, 0x00, 1, &config, 1) == -1) {
        perror("gpiod_i2c_write");
        fclose(log_file);
        gpiod_close(i2c_fd);
        exit(1);
    }

    // Wait for 100ms
    usleep(100000);

    // Read data from OPT3001
    uint16_t data;
    if (gpiod_i2c_read(i2c_fd, I2C_ADDRESS, 0x00, 2, &data, 2) == -1) {
        perror("gpiod_i2c_read");
        fclose(log_file);
        gpiod_close(i2c_fd);
        exit(1);
    }

    // Byte-swap data
    uint16_t lux = (data >> 8) | (data << 8);

    // Format and print data
    char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S, %.2f", localtime(&time(NULL)), (double)lux / 100.0);
    fprintf(log_file, "%s\n", buffer);
    fprintf(stdout, "%s\n", buffer);

    // Close log file
    fclose(log_file);

    // Close I2C handle
    gpiod_close(i2c_fd);

    return 0;
}

