#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define GPIO_ALERT 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500  // ms

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file in append mode
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR);
        close(log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_ALERT);
        close(log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial state of alert pin to LOW
    if (gpioWrite(GPIO_ALERT, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to LOW\n", GPIO_ALERT);
        close(log_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Poll sensor
        int sensor_value = gpioRead(GPIO_SENSOR);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d: %s\n", GPIO_SENSOR, strerror(errno));
            close(log_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Log reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_line[128];
        sprintf(log_line, "%s: GPIO%d = %d\n", timestamp, GPIO_SENSOR, sensor_value);
        if (write(log_fd, log_line, strlen(log_line)) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            close(log_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Check for flame detection
        if (sensor_value == 0) {
            // Set alert pin HIGH for 1 second
            if (gpioWrite(GPIO_ALERT, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO%d to HIGH\n", GPIO_ALERT);
                close(log_fd);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            usleep(1000000);  // 1 second
            if (gpioWrite(GPIO_ALERT, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO%d to LOW\n", GPIO_ALERT);
                close(log_fd);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        // Sleep for 500 ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    gpioSetMode(GPIO_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

