#include <time.h>
#include <errno.h>

#define GPIO4 4
#define DEBOUNCE_INTERVAL_US 50000
#define LOG_FILE "touch_log.txt"

bool touch_detected = false;
int gpio_fd = -1;
int log_fd = -1;

void cleanup(int sig) {
    if (gpio_fd != -1) {
        if (ioctl(gpio_fd, GPIO_UNEXPORT, GPIO4) == -1) {
            perror("gpio_unexport");
        }
        close(gpio_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    exit(0);
}

int main() {
    struct itimerspec debounce_timer;
    struct itimerspec current_timer;
    struct sigaction sa;
    struct tm timeinfo;
    char log_line[32];

    // Set up signal handlers
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open GPIO4 as an input with a pull-down bias
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("gpiochip0");
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_DIRECTION_INPUT, GPIO4) == -1) {
        perror("gpio_direction_input");
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_LINE_REQUEST, GPIO4) == -1) {
        perror("gpio_line_request");
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_LINE_REQUEST_DIRECTION_INPUT, GPIO4) == -1) {
        perror("gpio_line_request_direction_input");
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_LINE_REQUEST_BIAS, GPIO4, GPIO_BIAS_PULL_DOWN) == -1) {
        perror("gpio_line_request_bias");
        exit(1);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror(LOG_FILE);
        if (gpio_fd != -1) {
            if (ioctl(gpio_fd, GPIO_UNEXPORT, GPIO4) == -1) {
                perror("gpio_unexport");
            }
            close(gpio_fd);
        }
        exit(1);
    }

    // Set up debounce timer
    debounce_timer.it_interval.tv_sec = 0;
    debounce_timer.it_interval.tv_nsec = DEBOUNCE_INTERVAL_US * 1000;
    debounce_timer.it_value.tv_sec = 0;
    debounce_timer.it_value.tv_nsec = DEBOUNCE_INTERVAL_US * 1000;
    if (timer_create(CLOCK_REALTIME, &debounce_timer, NULL) == -1) {
        perror("timer_create");
        exit(1);
    }

    while (1) {
        // Read GPIO4
        uint32_t value;
        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUE, GPIO4, &value) == -1) {
            perror("gpio_get_line_value");
            exit(1);
        }

        // Check for touch detection
        if (value == 1 && !touch_detected) {
            touch_detected = true;
            time(&timeinfo);
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S: Touch Detected", &timeinfo);
            if (write(log_fd, log_line, strlen(log_line)) == -1) {
                perror(LOG_FILE);
                exit(1);
            }
            if (write(log_fd, "\n", 1) == -1) {
                perror(LOG_FILE);
                exit(1);
            }
            fsync(log_fd);
        } else if (value == 0 && touch_detected) {
            touch_detected = false;
            time(&timeinfo);
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S: Touch Released", &timeinfo);
            if (write(log_fd, log_line, strlen(log_line)) == -1) {
                perror(LOG_FILE);
                exit(1);
            }
            if (write(log_fd, "\n", 1) == -1) {
                perror(LOG_FILE);
                exit(1);
            }
            fsync(log_fd);
        }

        // Check for timer expiration
        if (timer_gettime(NULL, &current_timer) == -1) {
            perror("timer_gettime");
            exit(1);
        }
        if (current_timer.it_value.tv_sec == 0 && current_timer.it_value.tv_nsec == 0) {
            // Timer expired, reset it
            if (timer_settime(NULL, 0, &debounce_timer, NULL) == -1) {
                perror("timer_settime");
                exit(1);
            }
        }
    }

    return 0;
}

