#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x10
#define I2C_TIMEOUT 1000
#define FLOW_SENSOR_COMMAND 0x00
#define CRC_POLYNOMIAL 0x1D
#define CRC_INITIAL_VALUE 0x00

#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0

#define STATUS_OK "OK"
#define STATUS_INVALID "INVALID"
#define STATUS_ERROR "ERROR"

int i2c_fd = -1;
FILE *log_file = NULL;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int i2c_init() {
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *data, int len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = len;
    msgs->buf = data;
    struct i2c_rdwr_ioctl_data i2c_data;
    i2c_data.msgs = msgs;
    i2c_data.nmsgs = 1;
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = I2C_TIMEOUT;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) == -1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

uint16_t crc8(uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);
    if (i2c_init() == -1) {
        return 1;
    }
    log_file = fopen("cooling_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }
    fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    while (1) {
        uint8_t data[3];
        if (i2c_read(data, 3) == -1) {
            fprintf(log_file, "%lld,%s,ERROR\n", (long long)time(NULL), STATUS_ERROR);
            if (i2c_init() == -1) {
                break;
            }
            continue;
        }
        uint16_t flow = (uint16_t)((data[0] << 8) | data[1]);
        uint8_t crc = data[2];
        if (crc != crc8(data, 2)) {
            fprintf(log_file, "%lld,%s,ERROR\n", (long long)time(NULL), STATUS_ERROR);
            if (i2c_init() == -1) {
                break;
            }
            continue;
        }
        if (flow < FLOW_RATE_MIN || flow > FLOW_RATE_MAX) {
            fprintf(log_file, "%lld,%s,INVALID\n", (long long)time(NULL), STATUS_INVALID);
        } else {
            fprintf(log_file, "%lld,%f,%s\n", (long long)time(NULL), (double)flow / 10.0, STATUS_OK);
        }
        usleep(1000000);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

