#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LEFT 17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define LOG_FILE "path_log.csv"
#define SAMPLE_INTERVAL 50  // ms

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *left_line, *middle_line, *right_line;
    FILE *log_file;
    char timestamp[32];

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_new("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Check if the GPIO lines exist
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LEFT);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_MIDDLE);
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_RIGHT);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the lines as input
    if (gpiod_line_request_output(left_line, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO line %d as input\n", GPIO_LEFT);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(middle_line, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO line %d as input\n", GPIO_MIDDLE);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(right_line, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO line %d as input\n", GPIO_RIGHT);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,left,middle,right\n");

    // Main loop
    while (running) {
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_INTERVAL * 1000000;
        nanosleep(&sleep_time);

        // Read the sensor values
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        // Format the timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));

        // Write the data to the log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Check for errors
        if (ferror(log_file)) {
            fprintf(stderr, "Error writing to log file\n");
            break;
        }
    }

    // Clean up
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

