        int right_value = gpiod_line_get_value(right_line);

        // Format the timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));

        // Write the data to the log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Check for errors
        if (ferror(log_file)) {
            fprintf(stderr, "Error writing to log file\n");
            break;
        }
    }

    // Clean up
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    fclose(log_file);

