    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin as input with pull-up resistor
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0 || gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open event file for appending
    int fd = open(EVENT_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open event file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up edge detection for falling edge
    if (gpioEdge(GPIO_PIN, FALLING_EDGE) < 0) {
        fprintf(stderr, "Failed to set up edge detection: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for edge event
        if (gpioWaitForEvent(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Failed to wait for edge event: %s\n", strerror(errno));
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Check if sensor is absent or bus error
        if (gpioRead(GPIO_PIN) == -1) {
            fprintf(stderr, "Sensor absent or bus error detected\n");
            continue;
        }

        // Check if sensor is active (no flame)
        if (gpioRead(GPIO_PIN) == 1) {
            continue;
        }

        // Log event
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fd, "%s: Flame detected\n", timestamp);
        fflush(fd);
    }

    // Release resources
    close(fd);
    gpioTerminate();

    return 0;
}

