static FILE *log_file = NULL;

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpiod_close_line(GPIO_CHIP, GPIO_TOUCH);
    gpiod_close_line(GPIO_CHIP, GPIO_LED);
    gpiod_chip_close(GPIO_CHIP);
}

static void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

static void sigterm_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_event event;
    struct tm *timestamp;
    char timestamp_str[32];

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(1);
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error_str(errno));
        cleanup();
        exit(1);
    }

    // Request GPIO lines
    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (touch_line == NULL) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_TOUCH, gpiod_error_str(errno));
        gpiod_chip_close(chip);
        cleanup();
        exit(1);
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (led_line == NULL) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LED, gpiod_error_str(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        cleanup();
        exit(1);
    }

    // Set up GPIO lines
    gpiod_line_request_output(touch_line, 0);
    gpiod_line_request_output(led_line, 0);

    while (1) {
        // Poll for events
        if (gpiod_line_event_read(touch_line, &event, POLL_TIMEOUT) == 0) {
            // Check if event is a rising edge
            if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
                // Toggle LED
                gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
                // Log event
                timestamp = localtime(&event.timestamp);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", timestamp);
                fprintf(log_file, "%s: Touch detected, LED state: %s\n", timestamp_str, gpiod_line_get_value(led_line) ? "on" : "off");
            }
        }
    }

    cleanup();
    return 0;
}

