        exit(1);
    }

    buzzer_gpio = gpiod_chip_open("/dev/gpiochip0");
    if (buzzer_gpio < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        gpiod_chip_close(sensor_gpio);
        exit(1);
    }

    gpiod_line_request_output(sensor_gpio, GPIO17, 0);
    if (gpiod_line_request_output(sensor_gpio, GPIO17, 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        gpiod_chip_close(sensor_gpio);
        gpiod_chip_close(buzzer_gpio);
        exit(1);
    }

    gpiod_line_request_output(buzzer_gpio, GPIO18, 0);
    if (gpiod_line_request_output(buzzer_gpio, GPIO18, 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        gpiod_chip_close(sensor_gpio);
        gpiod_chip_close(buzzer_gpio);
        exit(1);
    }

