        if (event.value == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("FLAME DETECTED");
            gpiod_line_set_value(buzzer_gpio, 1);
            usleep(BUZZER_DURATION);
            gpiod_line_set_value(buzzer_gpio, 0);
        }
    }

    return 0;
}

