// Function to handle signal to perform cleanup
void sigint_handler(int sig) {
    // Release GPIO line
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise GPIO library\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_17, PI_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    gpioSetPullUpDnControl(GPIO_17, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_17, NULL);

    // Close log file
    int fd = open("flame_log.txt", O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open log file for reading\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    close(fd);

    // Close GPIO chip
    gpioTerminate();

    // Exit with success
    exit(EXIT_SUCCESS);
}

int main() {
    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler\n");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler\n");
        exit(EXIT_FAILURE);
    }

    // Initialise GPIO library
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise GPIO library\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO mode and pull-up
    if (gpioSetMode(GPIO_17, PI_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetPullUpDnControl(GPIO_17, PI_PUD_UP) == -1) {
        fprintf(stderr, "Failed to set pull-up/down control\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up alert function for falling edge
    if (gpioSetAlertFunc(GPIO_17, (void*)1) == -1) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    int fd = open("flame_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to open log file for writing\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (ftruncate(fd, 0) == -1) {
        fprintf(stderr, "Failed to truncate log file\n");
        close(fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (fchmod(fd, 0644) == -1) {
        fprintf(stderr, "Failed to set log file permissions\n");
        close(fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Check for alert
        if (gpioGetAlert(GPIO_17) == 1) {
            // Check if line is still low
            if (gpioRead(GPIO_17) == 0) {
                // Print to console
                printf("FLAME DETECTED\n");

                // Append to log file
                char timestamp[20];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                char logline[50];
                sprintf(logline, "%s FLAME DETECTED\n", timestamp);
                if (write(fd, logline, strlen(logline)) == -1) {
                    fprintf(stderr, "Failed to write to log file\n");
                    close(fd);
                    gpioTerminate();
                    exit(EXIT_FAILURE);
                }
                if (fsync(fd) == -1) {
                    fprintf(stderr, "Failed to sync log file\n");
                    close(fd);
                    gpioTerminate();
                    exit(EXIT_FAILURE);
                }
            }
        }

        // Sleep
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

