#define OUTPUT_PINS 8
#define OUTPUT_PIN_START 17
#define OUTPUT_PIN_END 24
#define SENSOR_PINS 8
#define SENSOR_PIN_START 5
#define SENSOR_PIN_END 12
#define POLL_INTERVAL 10
#define STABILIZATION_DELAY 200

volatile bool running = true;

void cleanup() {
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    for (int pin = OUTPUT_PIN_START; pin <= OUTPUT_PIN_END; pin++) {
        gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), pin));
    }
    exit(0);
}

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct itimerspec it;
    struct sigaction sa;
    int chip, line[SENSOR_PINS], output[OUTPUT_PINS];
    char buffer[256];
    FILE *log_file;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize output pins
    for (int pin = OUTPUT_PIN_START; pin <= OUTPUT_PIN_END; pin++) {
        line[pin - OUTPUT_PIN_START] = gpiod_chip_get_line(chip, pin);
        if (line[pin - OUTPUT_PIN_START] < 0) {
            fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
        gpiod_line_request_output(line[pin - OUTPUT_PIN_START], 0, 0);
        gpiod_line_direction(line[pin - OUTPUT_PIN_START], GPIOD_LINE_DIRECTION_OUTPUT);
        output[pin - OUTPUT_PIN_START] = 0;
    }

    // Initialize sensor pins
    for (int pin = SENSOR_PIN_START; pin <= SENSOR_PIN_END; pin++) {
        line[pin - SENSOR_PIN_START] = gpiod_chip_get_line(chip, pin);
        if (line[pin - SENSOR_PIN_START] < 0) {
            fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
        gpiod_line_request_input(line[pin - SENSOR_PIN_START], 0);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Warning: unable to open log file %s: %s\n", LOG_FILE, strerror(errno));
    }

    // Wait for stabilization delay
    usleep(STABILIZATION_DELAY * 1000);

    // Initialize timer
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_nsec = POLL_INTERVAL * 1000000;
    it.it_value.tv_sec = 0;
    it.it_value.tv_nsec = 0;
    timer_create(CLOCK_REALTIME, &it, NULL);

    // Main loop
    while (running) {
        struct itimerspec new_it;
        struct timespec now;
        int value[SENSOR_PINS];

        // Read sensor values
        for (int pin = 0; pin < SENSOR_PINS; pin++) {
            value[pin] = gpiod_line_get_value(line[pin]);
            if (value[pin] < 0) {
                fprintf(stderr, "Error reading line %d: %s\n", pin + SENSOR_PIN_START, strerror(errno));
                gpiod_chip_close(chip);
                for (int i = 0; i < OUTPUT_PINS; i++) {
                    gpiod_line_release(line[i]);
                }
                fclose(log_file);
                return 1;
            }
        }

        // Check for rising edges
        for (int pin = 0; pin < SENSOR_PINS; pin++) {
            if (value[pin] == 1) {
                // Increment counter
                int counter = 0;
                for (int i = 0; i < OUTPUT_PINS; i++) {
                    counter |= (output[i] << i);
                }
                counter = (counter + 1) % 256;
                for (int i = 0; i < OUTPUT_PINS; i++) {
                    output[i] = counter & (1 << i);
                }

                // Update output pins
                for (int pin = OUTPUT_PIN_START; pin <= OUTPUT_PIN_END; pin++) {
                    gpiod_line_set_value(line[pin - OUTPUT_PIN_START], output[pin - OUTPUT_PIN_START]);
                    if (gpiod_line_set_value(line[pin - OUTPUT_PIN_START], output[pin - OUTPUT_PIN_START]) < 0) {
                        fprintf(stderr, "Error setting line %d: %s\n", pin, strerror(errno));
                    }
                }

                // Log event
                time_t now_time = time(NULL);
                struct tm *now_tm = localtime(&now_time);
                strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", now_tm);
                fprintf(log_file, "%s, Channel: %d, Counter: %d\n", buffer, pin + 1, counter);
                fprintf(stderr, "Touch on channel %d | Counter: %d\n", pin + 1, counter);
            }
        }

        // Wait for next poll interval
        clock_gettime(CLOCK_REALTIME, &now);
        new_it.it_value.tv_sec = it.it_value.tv_sec;
        new_it.it_value.tv_nsec = it.it_value.tv_nsec;
        if (nanosleep(&new_it.it_value, NULL) < 0) {
            fprintf(stderr, "Error waiting: %s\n", strerror(errno));
            gpiod_chip_close(chip);
            for (int i = 0; i < OUTPUT_PINS; i++) {
                gpiod_line_release(line[i]);
            }
            fclose(log_file);
            return 1;
        }
    }

    // Clean up
    gpiod_chip_close(chip);
    for (int i = 0; i < OUTPUT_PINS; i++) {
        gpiod_line_release(line[i]);
    }
    fclose(log_file);
    return 0;
}
