    signal(SIGTERM, cleanup);

    // Open the GPIO chip
    if ((ret = gpiod_chip_open("/dev/gpiochip0")) < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(ret));
        return 1;
    }

    // Request lines
    for (i = 0; i < 4; i++) {
        if ((lines[i] = gpiod_chip_get_line_by_number(gpiod_chip_get_id(), i + GPIO17)) == NULL) {
            fprintf(stderr, "Failed to request line %d: %s\n", i + GPIO17, gpiod_error_str(ret));
            gpiod_chip_close(gpiod_chip_get_id());
            return 1;
        }
        if ((ret = gpiod_line_request_output(lines[i], GPIOD_LINE_ACTIVE_LOW)) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", i + GPIO17, gpiod_error_str(ret));
            gpiod_chip_close(gpiod_chip_get_id());
            for (i--; i >= 0; i--) {
                gpiod_line_release(lines[i]);
            }
            return 1;
        }
    }

    // Open the CSV file
    if ((fp = fopen(CSV_FILE, "a")) == NULL) {
        if ((fp = fopen(CSV_FILE, "w")) == NULL) {
            fprintf(stderr, "Failed to open %s for writing: %s\n", CSV_FILE, strerror(errno));
            gpiod_chip_close(gpiod_chip_get_id());
            for (i = 0; i < 4; i++) {
                gpiod_line_release(lines[i]);
            }
            return 1;
        }
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(fp);
    }

    // Main loop
    while (1) {
        // Read events
        if ((ret = gpiod_chip_read_events(gpiod_chip_get_id(), &events, 1)) < 0) {
            fprintf(stderr, "Failed to read events: %s\n", gpiod_error_str(ret));
            continue;
        }

        // Process events
        for (i = 0; i < ret; i++) {
            if (events[i].line == lines[0]) {
                sensor1 = events[i].value == 0;
            } else if (events[i].line == lines[1]) {
                sensor2 = events[i].value == 0;
            } else if (events[i].line == lines[2]) {
                sensor3 = events[i].value == 0;
            } else if (events[i].line == lines[3]) {
                sensor4 = events[i].value == 0;
            }
        }

        // Write to CSV
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        sprintf(buffer, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
        if (fputs(buffer, fp) == EOF) {
            fprintf(stderr, "Failed to write to %s: %s\n", CSV_FILE, strerror(errno));
            gpiod_chip_close(gpiod_chip_get_id());
            for (i = 0; i < 4; i++) {
                gpiod_line_release(lines[i]);
            }
            fclose(fp);
            return 1;
        }
        fflush(fp);

        // Sleep
        usleep(100000);
    }

    // Cleanup
    gpiod_chip_close(gpiod_chip_get_id());
    for (i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    fclose(fp);
    return 0;
}

