#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define DEBOUNCE_WINDOW 50
#define POLL_INTERVAL 100
#define LOG_FILE "/var/log/tilt_events.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int get_line_value(int line) {
    int fd;
    struct gpiod_line *line_info;
    struct gpiod_line_event event;

    fd = gpiod_chip_open("/dev/gpiochip0");
    if (fd < 0) {
        perror("gpiod_chip_open");
        exit(1);
    }

    line_info = gpiod_chip_get_line(fd, line);
    if (!line_info) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(fd);
        exit(1);
    }

    gpiod_line_request_output(fd, line, 1, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_set_value(line_info, 1);

    while (1) {
        if (gpiod_line_get_value(line_info, &event) < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_release(line_info);
            gpiod_chip_close(fd);
            exit(1);
        }

        if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (event.value == 0) {
                struct tm *timeinfo;
                time_t rawtime;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                char timestamp[20];
                strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
                FILE *log_file = fopen(LOG_FILE, "a");
                if (!log_file) {
                    perror("fopen");
                    gpiod_line_release(line_info);
                    gpiod_chip_close(fd);
                    exit(1);
                }
                fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, line + 1);
                fclose(log_file);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_release(line_info);
    gpiod_chip_close(fd);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int fd;
    struct gpiod_chip *chip;

    fd = gpiod_chip_open("/dev/gpiochip0");
    if (fd < 0) {
        perror("gpiod_chip_open");
        exit(1);
    }

    chip = gpiod_chip_get(fd);
    if (!chip) {
        perror("gpiod_chip_get");
        gpiod_chip_close(fd);
        exit(1);
    }

    gpiod_chip_set_line_request_flags(chip, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);

    get_line_value(GPIO17);
    get_line_value(GPIO18);

    while (running) {
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_chip_close(fd);
    return 0;
}

