#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 27
#define GPIO_LED 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL 100000 // 100ms

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SENSOR2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up pull-up resistors for sensors
    if (gpioSetPullUpDnControl(GPIO_SENSOR1, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", GPIO_SENSOR1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDnControl(GPIO_SENSOR2, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", GPIO_SENSOR2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1 = gpioRead(GPIO_SENSOR1);
        int sensor2 = gpioRead(GPIO_SENSOR2);

        // Invert sensor values since they are active-low
