struct timeval last_peak_timestamp;

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Set the stop_sampling flag
    stop_sampling = 1;
}

// Define the sampling loop function
void sampling_loop() {
    // Initialize the gpiod context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create gpiod context\n");
        exit(1);
    }

    // Open the GPIO line
    line = gpiod_line_create(ctx, "gpio4", GPIOD_LINE_ACTIVE_HIGH);
    if (!line) {
        fprintf(stderr, "Failed to create gpiod line\n");
        gpiod_ctx_free(ctx);
        exit(1);
    }

    // Initialize the gpiod event
    event = gpiod_event_new();
    if (!event) {
        fprintf(stderr, "Failed to create gpiod event\n");
        gpiod_line_release(line);
        gpiod_ctx_free(ctx);
        exit(1);
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler for SIGINT\n");
        gpiod_event_free(event);
        gpiod_line_release(line);
        gpiod_ctx_free(ctx);
        exit(1);
    }

    // Initialize the last peak timestamp
    gettimeofday(&last_peak_timestamp, NULL);

    // Main sampling loop
    while (!stop_sampling) {
