    }

    // Open I2C bus
    if ((fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set I2C bus address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C bus address\n");
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read LSB and MSB registers
        if (i2c_smbus_read_byte(fd, ALS_LSB_REGISTER, &lsb) < 0) {
            fprintf(stderr, "Failed to read LSB register\n");
            close(fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (i2c_smbus_read_byte(fd, ALS_MSB_REGISTER, &msb) < 0) {
            fprintf(stderr, "Failed to read MSB register\n");
            close(fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Combine LSB and MSB registers into a single 16-bit raw value
        raw_value = (msb << 8) | lsb;

        // Log raw sensor reading to console
        printf("Raw ALS value: 0x%04x\n", raw_value);

        // Wait for the next interval
        usleep(INTERVAL);
    }

    // Cleanly release resources on exit
    close(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}
