// gcc -o touch_poll touch_poll.c -lrt -lpigpio

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>

#define GPIO5 5
#define GPIO6 6
#define GPIO13 13
#define GPIO19 19
#define GPIO26 26
#define GPIO12 12
#define GPIO16 16
#define GPIO20 20

#define TOUCH_POLL_INTERVAL 200000 // 200ms

void sigint_handler(int sig) {
    // Release all driver resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    // Open the TTP226 chip
    int chip = gpioOpen("/dev/i2c-1", 0x1D);
    if (chip < 0) {
        fprintf(stderr, "Failed to open TTP226 chip\n");
        gpioTerminate();
        exit(1);
    }

    // Set up the GPIO lines
    gpioSetMode(GPIO5, PI_INPUT);
    gpioSetMode(GPIO6, PI_INPUT);
    gpioSetMode(GPIO13, PI_INPUT);
    gpioSetMode(GPIO19, PI_INPUT);
    gpioSetMode(GPIO26, PI_INPUT);
    gpioSetMode(GPIO12, PI_INPUT);
    gpioSetMode(GPIO16, PI_INPUT);
    gpioSetMode(GPIO20, PI_INPUT);

    // Set up the GPIO pull-up resistors
    gpioSetPullUpDnControl(GPIO5, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO6, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO13, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO19, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO26, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO12, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO16, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO20, PI_PUD_UP);

    // Main loop
    struct timeval last_time;
    gettimeofday(&last_time, NULL);
    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_time.tv_sec >= TOUCH_POLL_INTERVAL / 1000000) {
            // Read the GPIO lines
            int touch1 = gpioRead(GPIO5);
            int touch2 = gpioRead(GPIO6);
            int touch3 = gpioRead(GPIO13);
            int touch4 = gpioRead(GPIO19);
            int touch5 = gpioRead(GPIO26);
            int touch6 = gpioRead(GPIO12);
            int touch7 = gpioRead(GPIO16);
            int touch8 = gpioRead(GPIO20);

            // Print the results
            printf("[%lu.%06lu] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
                   now.tv_sec, now.tv_usec, touch1, touch2, touch3, touch4, touch5, touch6, touch7, touch8);

            // Update the last time
            last_time = now;
        }

        // Sleep until the next poll interval
        struct timespec sleep_time;
        sleep_time.tv_sec = TOUCH_POLL_INTERVAL / 1000000;
        sleep_time.tv_nsec = (TOUCH_POLL_INTERVAL % 1000000) * 1000;
        nanosleep(&sleep_time, NULL);
    }

    // Release all driver resources
    gpioTerminate();
    return 0;
}

