#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpiod.h>
#include <linux/gpio.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <string.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQ 1000
#define PWM_RANGE 8
#define TRANSITION_TIME 5000
#define TRANSITION_STEPS 50

struct gpiod_line {
    int fd;
    int offset;
};

struct gpiod_line lines[3];

void cleanup() {
    for (int i = 0; i < 3; i++) {
        if (gpiod_close(lines[i].fd) != 0) {
            syslog(LOG_ERR, "Failed to close GPIO line %d: %s", i, strerror(errno));
        }
    }
    gpiod_driver_unregister();
    closelog();
    exit(0);
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    for (int i = 0; i < 3; i++) {
        gpiod_line_set_value(lines[i].fd, 0);
    }
    cleanup();
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    for (int i = 0; i < 3; i++) {
        gpiod_line_set_value(lines[i].fd, 0);
    }
    cleanup();
}

void set_hue(int r, int g, int b) {
    for (int i = 0; i < TRANSITION_STEPS; i++) {
        int t = (double)i / TRANSITION_STEPS;
        int r_value = (r * (1 - t)) + (g * t);
        int g_value = (g * (1 - t)) + (b * t);
        int b_value = (b * (1 - t)) + (r * t);
        r_value = (r_value < 0) ? 0 : (r_value > 255) ? 255 : r_value;
        g_value = (g_value < 0) ? 0 : (g_value > 255) ? 255 : g_value;
        b_value = (b_value < 0) ? 0 : (b_value > 255) ? 255 : b_value;
        gpiod_line_set_value(lines[0].fd, r_value);
        gpiod_line_set_value(lines[1].fd, g_value);
        gpiod_line_set_value(lines[2].fd, b_value);
        usleep(TRANSITION_TIME / TRANSITION_STEPS);
    }
}

int main() {
    int ret;
    int fd;

    // Initialize syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize GPIO driver
    ret = gpiod_init();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver: %s", strerror(-ret));
        return 1;
    }

    // Open GPIO lines
    for (int i = 0; i < 3; i++) {
        fd = gpiod_open("/sys/class/gpio/gpio%d/value", i + LED_RED);
        if (fd < 0) {
            syslog(LOG_ERR, "Failed to open GPIO line %d: %s", i, strerror(errno));
            return 1;
        }
        lines[i].fd = fd;
        ret = gpiod_line_request_output(lines[i].fd, i + LED_RED, "active-high");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request GPIO line %d: %s", i, strerror(-ret));
            return 1;
        }
    }

    // Set up PWM
    ret = gpiod_pwm_set_range(lines[0].fd, PWM_RANGE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set PWM range: %s", strerror(-ret));
        return 1;
    }
    ret = gpiod_pwm_set_frequency(lines[0].fd, PWM_FREQ);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency: %s", strerror(-ret));
        return 1;
    }

    // Seed random number generator
    fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %s", strerror(errno));
        return 1;
    }
    unsigned char buffer[4];
    ret = read(fd, buffer, 4);
    if (ret != 4) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom: %s", strerror(errno));
        return 1;
    }
    close(fd);
    srand(*(uint32_t*)buffer);

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        int r = rand() % 256;
        int g = rand() % 256;
        int b = rand() % 256;
        set_hue(r, g, b);
    }

    return 0;
}

