    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("Failed to initialize GPIO");
        goto cleanup;
    }

