            perror("Failed to read calibrated values");
            goto cleanup;
        }
        if (read(i2c_fd, &bdata, 2) != 2) {
            perror("Failed to read calibrated values");
            goto cleanup;
        }
        if (read(i2c_fd, &cdata, 2) != 2) {
            perror("Failed to read calibrated values");
            goto cleanup;
        }

        // Print values
        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n", rdata, gdata, bdata, cdata);

        // Control LED
        if (rdata > THRESHOLD) {
            gpioWrite(gpio_fd, 17, 1);
        } else {
            gpioWrite(gpio_fd, 17, 0);
        }

        // Sleep
        usleep(200000);
    }

cleanup:
    // Clean up
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpioTerminate();
    }
    return 0;
