#define WS2812B_DUTY 50
#define WS2812B_CHANNEL 0
#define WS2812B_EEPROM 0x00
#define WS2812B_ON 0x01
#define WS2812B_OFF 0x00
#define WS2812B_ALL_ON 0xFF
#define WS2812B_ALL_OFF 0x00
#define WS2812B_MAX 10

