void sigint_handler(int sig) {
    if (pwm_device) {
        pwm_disable(pwm_device);
        pwm_put(pwm_device, 0);
    }
    if (gpio_desc) {
        gpiod_put(gpio_desc);
    }
    if (i2c_client) {
        i2c_unregister_device(i2c_client);
    }
    if (i2c_adapter) {
        i2c_del_adapter(i2c_adapter);
    }
    exit(0);
}

int i2c_init() {
    int ret;
    i2c_adapter = i2c_get_adapter(I2C_BUS);
    if (!i2c_adapter) {
        perror("i2c_get_adapter");
        return -1;
    }
    i2c_client = i2c_new_device(i2c_adapter, I2C_ADDR);
    if (!i2c_client) {
        perror("i2c_new_device");
        i2c_del_adapter(i2c_adapter);
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg) {
    int ret;
    i2c_msg_read.msg[0].addr = I2C_ADDR;
    i2c_msg_read.msg[0].flags = I2C_M_RD;
    i2c_msg_read.msg[0].len = 2;
    i2c_msg_read.msg[1].addr = I2C_ADDR;
    i2c_msg_read.msg[1].flags = 0;
    i2c_msg_read.msg[1].len = 2;
    i2c_msg_read.msg[0].buf = (uint8_t *)&reg;
    i2c_msg_read.msg[1].buf = (uint8_t *)&reg;
    for (int i = 0; i < I2C_RETRY; i++) {
        ret = i2c_transfer(i2c_adapter, &i2c_msg_read, 2);
        if (ret >= 0) {
            break;
        }
        usleep(100000);
