    pwm_ops.put = pwm_put;
    pwm_ops.get = pwm_get;
    pwm_ops.enable = pwm_enable;
    pwm_ops.disable = pwm_disable;
    pwm_ops.get_state = pwm_get_state;
    pwm_ops.set_period = pwm_set_period;
    pwm_ops.set_duty = pwm_set_duty;
    pwm_config.dev = WS2812B_PIN;
    pwm_config.ops = &pwm_ops;
    pwm_config.pwm = WS2812B_FREQ;
    pwm_config.duty = WS2812B_DUTY;
    pwm_config.channel = WS2812B_CHANNEL;
    pwm_config.eeprom = WS2812B_EEPROM;
    pwm_config.flags = 0;
    ret = pwm_request(&pwm_config, &pwm_device);
    if (ret < 0) {
        perror("pwm_request");
        gpiod_put(gpio_desc);
        return -1;
    }
    return 0;
}

void ws2812b_set(uint8_t value) {
    uint8_t i;
    for (i = 0; i < WS2812B_MAX; i++) {
        if (value & (1 << i)) {
            gpiod_set_value(gpio_desc, 1);
        } else {
            gpiod_set_value(gpio_desc, 0);
        }
        usleep(50);
    }
}

void ws2812b_set_all(uint8_t value) {
    uint8_t i;
    for (i = 0; i < WS2812B_MAX; i++) {
        gpiod_set_value(gpio_desc, value);
        usleep(50);
    }
}

void ws2812b_off() {
    ws2812b_set_all(WS2812B_OFF);
}

void ws2812b_on() {
    ws2812b_set_all(WS2812B_ON);
}

void ws2812b_set_brightness(uint16_t lux) {
    uint8_t brightness = (uint8_t)((lux / 65535.0) * 255.0);
    ws2812b_set(brightness);
}

int main() {
    struct itimerspec it;
    struct sigaction sa;
    int ret;
