#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define APA102_LED_COUNT 10
#define I2C_ADDRESS 0x23
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_LSBFIRST 0
#define SPI_CS_HIGH 0

// Structure to represent an APA102 LED frame
typedef struct {
    uint32_t start;
    uint32_t data[APA102_LED_COUNT];
    uint32_t end;
} apa102_frame_t;

// Function to read a byte from the BH1750 sensor
uint8_t read_bh1750(uint8_t reg) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    uint8_t data[2];
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("Failed to write to BH1750");
        close(fd);
        exit(1);
    }

    usleep(120 * 1000); // Wait for conversion to complete

    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        perror("Failed to read from BH1750");
        close(fd);
        exit(1);
    }

    close(fd);
    return data[0];
}

// Function to read the ambient light level from the BH1750 sensor
uint16_t read_light_level() {
    uint8_t data[2];
    data[0] = read_bh1750(0x00);
    data[1] = read_bh1750(0x01);
    return (data[0] << 8) | data[1];
}

// Function to create an APA102 frame
apa102_frame_t create_apa102_frame(uint16_t light_level) {
    apa102_frame_t frame;
    frame.start = 0x00 << 24 | 0x00 << 16 | 0x00 << 8 | 0x00;
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        uint8_t r = (light_level * 255) / 4095;
        uint8_t g = (light_level * 255) / 4095;
        uint8_t b = 0;
        frame.data[i] = r << 24 | g << 16 | b << 8 | 0x00;
    }
    frame.end = 0xFF << 24 | 0xFF << 16 | 0xFF << 8 | 0xFF;
    return frame;
}

// Function to transmit an APA102 frame over SPI
void transmit_apa102_frame(apa102_frame_t frame) {
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI bus");
        exit(1);
    }

    struct spi_ioc_transfer xfer[1];
    memset(xfer, 0, sizeof(xfer));
    xfer[0].tx_buf = (unsigned long) &frame;
    xfer[0].len = sizeof(frame);
    xfer[0].speed_hz = SPI_SPEED;
    xfer[0].bits_per_word = SPI_BITS;
    xfer[0].cs_change = SPI_CS_HIGH;
    xfer[0].delay_usecs = 0;
    xfer[0].cs_change = 0;
    xfer[0].tx_nbits = SPI_BITS;
    xfer[0].rx_nbits = 0;
    xfer[0].tx_is_dma = 0;
    xfer[0].rx_is_dma = 0;
    xfer[0].dma_len = 0;
    xfer[0].callback = NULL;
    xfer[0].context = NULL;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), xfer) < 0) {
        perror("Failed to transmit APA102 frame");
        close(fd);
        exit(1);
    }

    close(fd);
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    apa102_frame_t frame;
    frame.start = 0x00 << 24 | 0x00 << 16 | 0x00 << 8 | 0x00;
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        uint8_t r = 0;
        uint8_t g = 0;
        uint8_t b = 0;
        frame.data[i] = r << 24 | g << 16 | b << 8 | 0x00;
    }
    frame.end = 0xFF << 24 | 0xFF << 16 | 0xFF << 8 | 0xFF;
    transmit_apa102_frame(frame);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    apa102_frame_t frame;
    while (1) {
        uint16_t light_level = read_light_level();
        frame = create_apa102_frame(light_level);
        transmit_apa102_frame(frame);
        usleep(10000); // 10ms delay
    }

    return 0;
}

