            close(fd);
        }
        sensor_value /= 2;
        sensor_value = MAX(0, MIN(sensor_value, 1023));
        int new_brightness = (int) (sensor_value / 1023.0 * 255.0);
        for (int i = 0; i < FADE_TIME / DELAY_TIME; i++) {
            for (int j = 0; j < LED_STRIP_LENGTH; j++) {
