    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Turn off the LED strip
    ws2812b_drive_simple(0);

    // Exit the program
    exit(0);
}

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
