        return 1;
    }

    // Initialize the VEML7700
    vemm7700_data_t data;
    int retries = 0;
    while (vemm7700_read(i2c_fd, &data) < 0 && retries < 3) {
        usleep(100000);
        retries++;
    }
    if (retries >= 3) {
        fprintf(stderr, "Error: unable to read from VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read from the VEML7700
        retries = 0;
        while (vemm7700_read(i2c_fd, &data) < 0 && retries < 3) {
            usleep(100000);
            retries++;
        }
        if (retries >= 3) {
            fprintf(stderr, "Error: unable to read from VEML7700\n");
            close(i2c_fd);
            return 1;
        }

        // Apply gamma correction and scaling
        uint8_t brightness = gamma_corrected_brightness(data.lux);

        // Drive the WS2812B LED strip
        uint8_t data[WS2812B_MAX_BRIGHTNESS / 8 + 1];
        for (int i = 0; i < WS2812B_MAX_BRIGHTNESS / 8 + 1; i++) {
