    if (gpio_fd == -1) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    if (write(gpio_fd, "17", 2) != 2) {
        perror("write");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    close(gpio_fd);

    close(i2c_fd);

    return 0;
