#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27

#define GPIO_BASE 0x3F200000
#define GPIO_SETDATAOUT 0x208
#define GPIO_CLEARDATAOUT 0x20C
#define GPIO_SETDIR 0x1C

int main() {
    int fd;
    int ret;
    uint32_t *gpio;
    uint32_t value;

    // Open the GPIO character device
    fd = open("/dev/gpiomem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/gpiomem");
        return 1;
    }

    // Map the GPIO memory
    gpio = (uint32_t *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio == MAP_FAILED) {
        perror("Failed to map GPIO memory");
        close(fd);
        return 1;
    }

    // Set GPIO17, GPIO18, and GPIO27 as outputs
    value = (1 << GPIO17) | (1 << GPIO18) | (1 << GPIO27);
    ret = ioctl(fd, GPIO_SETDIR, value);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        munmap(gpio, 4096);
        close(fd);
        return 1;
    }

    // Set GPIO17, GPIO18, and GPIO27 as outputs
    value = (1 << GPIO17) | (1 << GPIO18) | (1 << GPIO27);
    ret = ioctl(fd, GPIO_SETDATAOUT, value);
    if (ret < 0) {
        perror("Failed to set GPIO output");
        munmap(gpio, 4096);
        close(fd);
        return 1;
    }

    // Shift out routine
    void shift_out(uint8_t data) {
        for (int i = 0; i < 8; i++) {
            // Set the clock low
            value = ~(1 << GPIO18);
            ret = ioctl(fd, GPIO_SETDATAOUT, value);
            if (ret < 0) {
                perror("Failed to set clock low");
                munmap(gpio, 4096);
                close(fd);
                return;
            }

            // Set the data bit
            value = (data & (1 << i)) ? (1 << GPIO17) : 0;
            ret = ioctl(fd, GPIO_SETDATAOUT, value);
            if (ret < 0) {
                perror("Failed to set data bit");
                munmap(gpio, 4096);
                close(fd);
                return;
            }

            // Set the clock high
            value = (1 << GPIO18);
            ret = ioctl(fd, GPIO_SETDATAOUT, value);
            if (ret < 0) {
                perror("Failed to set clock high");
                munmap(gpio, 4096);
                close(fd);
                return;
            }
        }

        // Set the latch high
        value = (1 << GPIO27);
        ret = ioctl(fd, GPIO_SETDATAOUT, value);
        if (ret < 0) {
            perror("Failed to set latch high");
            munmap(gpio, 4096);
            close(fd);
            return;
        }
    }

    // Map the 74HC595 outputs to segments
    uint8_t segment_map[] = {0b00111111, 0b00000110, 0b01011011, 0b01001111, 0b01100110, 0b01101101, 0b01111101, 0b00000111, 0b00000000};

    // Set the pattern for digit '5'
    uint8_t pattern = segment_map[5];

    // Blink the digit on the display
    while (1) {
        shift_out(pattern);
        usleep(500000);
        shift_out(0);
        usleep(500000);
    }

    // Clean up
    munmap(gpio, 4096);
    close(fd);
    return 0;
}

