#include <signal.h>
#include <gpiod.h>

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_line_release(gpio17);
    gpiod_line_release(gpio18);
    gpiod_chip_close(gpio_chip);
    exit(0);
}

int main() {
    // Define GPIO line numbers
    int gpio17 = 17;
    int gpio18 = 18;

    // Define GPIO chip number
    int gpio_chip = 0;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open(gpio_chip);
    if (gpio_chip == -1) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Request GPIO17 as an output and set it low
    int line17 = gpiod_line_request_output(gpio_chip, gpio17, "blink");
    if (line17 == -1) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }
    if (gpiod_line_set_value(line17, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line17);
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    // Request GPIO18 as an input with pull-up and falling edge detection
    int line18 = gpiod_line_request_input(gpio_chip, gpio18, "button", GPIOD_LINE_ACTIVE_STATE_HIGH, GPIOD_LINE_EVENT_RISING_EDGE);
    if (line18 == -1) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line17);
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    // Blink LED with 2-second period
    while (1) {
        if (gpiod_line_get_value(line18) == 0) {
            // Button pressed, stop blinking and exit
            gpiod_line_release(line17);
            gpiod_line_release(line18);
            gpiod_chip_close(gpio_chip);
            printf("Button pressed\n");
            exit(0);
        }
        if (gpiod_line_get_value(line17) == 0) {
            if (gpiod_line_set_value(line17, 1) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line17);
                gpiod_line_release(line18);
                gpiod_chip_close(gpio_chip);
                exit(1);
            }
        } else {
            if (gpiod_line_set_value(line17, 0) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line17);
                gpiod_line_release(line18);
                gpiod_chip_close(gpio_chip);
                exit(1);
            }
        }
        usleep(1000000); // 1 second
    }

    // Release resources on exit
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(gpio_chip);
    return 0;
}

