    struct gpiod_line *button_line;
    if ((button_line = gpiod_chip_get_line(chip, 22)) == NULL) {
        fprintf(stderr, "Failed to get line for GPIO22\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO24 as an output initially low
    if (gpiod_line_request_output(led_line, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO24 as output\n");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

