        gpiod_line_set_value(line_green, green);
        gpiod_line_set_value(line_blue, blue);

        // Wait for 10ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000;
        nanosleep(&sleep_time);

        // Change color every 100ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000;
        nanosleep(&sleep_time);
    }

    return 0;
}

