#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define LOG_INTERVAL 10 // Hz

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} AccelerometerData;

// Function to read accelerometer data
int read_accelerometer(int fd) {
    uint8_t reg = 0x00;
    uint8_t data[6];
    int ret;

    // Read the accelerometer data
    ret = i2c_smbus_read_i2c_block_data(fd, I2C_ADDRESS, &reg, 6, data);
    if (ret < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", ret);
        return -1;
    }

    // Convert the data to G-force
    AccelerometerData data;
    data.x = (int16_t)((data[0] << 8) | data[1]);
    data.y = (int16_t)((data[2] << 8) | data[3]);
    data.z = (int16_t)((data[4] << 8) | data[5]);

    return data.x + data.y + data.z;
}

// Function to compute the total G-force magnitude
double compute_magnitude(AccelerometerData data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z) / 16384.0;
}

// Function to handle the impact interrupt
void impact_handler(int signum) {
    // Cleanly exit the program
    exit(0);
}

int main(int argc, char **argv) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the GPIO pin as an output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C bus
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for the impact interrupt
    struct sigaction sa;
    sa.sa_handler = impact_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    struct timeval last_time;
    gettimeofday(&last_time, NULL);
    while (1) {
        // Read the accelerometer data
        AccelerometerData data;
        int ret = read_accelerometer(fd);
        if (ret < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }
        data = (AccelerometerData)ret;

        // Compute the total G-force magnitude
        double magnitude = compute_magnitude(data);

        // Check if the magnitude exceeds the threshold
        if (magnitude > threshold) {
            // Pulse the GPIO pin
            gpioPulse(GPIO_PIN, 50);

            // Log the data
            struct timeval now;
            gettimeofday(&now, NULL);
            fprintf(log_file, "%ld.%06ld %f\n", now.tv_sec, now.tv_usec, magnitude);
        }

        // Check if it's time to log the data
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_time.tv_sec >= 1 / LOG_INTERVAL) {
            // Log the data
            fprintf(log_file, "%ld.%06ld %f\n", now.tv_sec, now.tv_usec, magnitude);

            // Update the last time
            last_time = now;
        }

        // Sleep for a short period
        usleep(100000 / LOG_INTERVAL);
    }

    // Cleanly exit the program
    fclose(log_file);
    close(fd);
    gpioTerminate();
    return 0;
}

