#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define WHO_AM_I_ID 0x00
#define STANDBY 0x00
#define CONFIG 0x10
#define RATE 0x12
#define RANGE 0x1E
#define ACCEL_X 0x2A
#define ACCEL_Y 0x2C
#define ACCEL_Z 0x2E
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"

int i2c_fd;
struct i2c_client *client;

void sigint_handler(int sig) {
    if (gpiod_shutdown() != 0) {
        perror("gpiod_shutdown");
    }
    if (close(i2c_fd) != 0) {
        perror("close");
    }
    exit(0);
}

int main() {
    struct i2c_client *client;
    int ret;
    uint8_t who_am_i;
    uint8_t config;
    uint8_t rate;
    uint8_t range;
    uint8_t x, y, z;
    double magnitude;
    struct tm time;
    char log_line[64];

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Create I2C client
    if ((client = gpiod_client_new(i2c_fd, I2C_ADDRESS)) == NULL) {
        perror("gpiod_client_new");
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I identifier
    if ((ret = gpiod_i2c_read(client, WHO_AM_I_ID, &who_am_i, 1)) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I: %d\n", ret);
        gpiod_client_unref(client);
        close(i2c_fd);
        return 1;
    }
    if (who_am_i != 0x00) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x00, got 0x%02x\n", who_am_i);
        gpiod_client_unref(client);
        close(i2c_fd);
        return 1;
    }

    // Place device in standby
    if ((ret = gpiod_i2c_write(client, STANDBY, &STANDBY, 1)) != 1) {
        fprintf(stderr, "Error writing to STANDBY: %d\n", ret);
    }

    // Configure sensor for ±2g range
    if ((ret = gpiod_i2c_write(client, RANGE, &range, 1)) != 1) {
        fprintf(stderr, "Error writing to RANGE: %d\n", ret);
    }
    range = 0x00; // Set range to ±2g
    if ((ret = gpiod_i2c_write(client, RANGE, &range, 1)) != 1) {
        fprintf(stderr, "Error writing to RANGE: %d\n", ret);
    }

    // Configure sensor for 200Hz output data rate
    if ((ret = gpiod_i2c_write(client, RATE, &rate, 1)) != 1) {
        fprintf(stderr, "Error writing to RATE: %d\n", ret);
    }
    rate = 0x0A; // Set rate to 200Hz
    if ((ret = gpiod_i2c_write(client, RATE, &rate, 1)) != 1) {
        fprintf(stderr, "Error writing to RATE: %d\n", ret);
    }

    // Activate sensor
    if ((ret = gpiod_i2c_write(client, CONFIG, &config, 1)) != 1) {
        fprintf(stderr, "Error writing to CONFIG: %d\n", ret);
    }
    config = 0x01; // Set config to active
    if ((ret = gpiod_i2c_write(client, CONFIG, &config, 1)) != 1) {
        fprintf(stderr, "Error writing to CONFIG: %d\n", ret);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read acceleration data
        if ((ret = gpiod_i2c_read(client, ACCEL_X, &x, 1)) != 1) {
            fprintf(stderr, "Error reading ACCEL_X: %d\n", ret);
            continue;
        }
        if ((ret = gpiod_i2c_read(client, ACCEL_Y, &y, 1)) != 1) {
            fprintf(stderr, "Error reading ACCEL_Y: %d\n", ret);
            continue;
        }
        if ((ret = gpiod_i2c_read(client, ACCEL_Z, &z, 1)) != 1) {
            fprintf(stderr, "Error reading ACCEL_Z: %d\n", ret);
            continue;
        }

        // Compute acceleration magnitude
        magnitude = sqrt((x * x + y * y + z * z) / 16384.0);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            // Get current timestamp
            time = *localtime(&time(NULL));
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", &time);
            sprintf(log_line + strlen(log_line), ",%03d,%03d,%03d,%0.3f", x, y, z, magnitude);
            // Append to log file
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(log_file, "%s\n", log_line);
            fclose(log_file);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    gpiod_client_unref(client);
    close(i2c_fd);
    return 0;
}

