#define RANGE 2  // g
#define RESOLUTION 16

#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_X0_L 0x32
#define ADXL345_REG_DATA_X1_L 0x33
#define ADXL345_REG_DATA_X0_H 0x34
#define ADXL345_REG_DATA_X1_H 0x35
#define ADXL345_REG_DATA_Y0_L 0x36
