    char buffer[50];
    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", buffer, x, y, z);
}

