    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_DATA_FORMAT, 0x0F) < 0) {
        perror("i2c_smbus_write_byte_data");
        return;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        perror("i2c_smbus_write_byte_data");
        return;
    }
    if (i2c_smbus_read_i2c_block_data(i2c_fd, ADXL345_REG_DATA_X0_L, 6, data) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return;
    }
    double x = (int16_t)((data[1] << 8) | data[0]) / 256.0 * RANGE;
    double y = (int16_t)((data[3] << 8) | data[2]) / 256.0 * RANGE;
    double z = (int16_t)((data[5] << 8) | data[4]) / 256.0 * RANGE;
    log_sample(x, y, z);
    if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
        gpioWrite(GPIO_LED, 1);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    init_i2c();
    init_gpio();
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }
    while (1) {
        read_accel();
        usleep(SAMPLE_PERIOD_USEC);
    }
    return 0;
}

