        gettimeofday(&tv, NULL);
        uint64_t sec = tv.tv_sec;
        uint64_t nsec = tv.tv_usec * 1000;

        // Compute TDOA
        int32_t tdoa = (int32_t)(sensor2 - sensor1);

        // Append to log file
        fprintf(log_file, "%lu,%lu,%d,%d,%d\n", sec, nsec, sensor1, sensor2, tdoa);

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL * 1000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

