#define IMU_SPI_BUS 0
#define IMU_CS_PIN 8
#define IMU_SPI_SPEED 1000000
#define IMU_SPI_MODE 3
#define IMU_SPI_BITS 16
#define IMU_STALL_TIME_US 40
#define IMU_SAMPLE_RATE_MS 100
#define IMU_GYRO_SENSITIVITY 0.005
#define IMU_ACCEL_SENSITIVITY 0.00025

#define IMU_GYRO_X_REG 0x00
#define IMU_GYRO_Y_REG 0x01
#define IMU_GYRO_Z_REG 0x02
#define IMU_ACCEL_X_REG 0x03
#define IMU_ACCEL_Y_REG 0x04
#define IMU_ACCEL_Z_REG 0x05

volatile bool running = true;

void cleanup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        exit(1);
    }
    gpioSetMode(IMU_CS_PIN, PI_OUTPUT);
    gpioWrite(IMU_CS_PIN, 1);
    gpioTerminate();
    fclose(fp);
}

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void non_blocking_delay(int ms) {
    struct timespec delay;
    delay.tv_sec = ms / 1000;
    delay.tv_nsec = (ms % 1000) * 1000000;
    while (nanosleep(&delay, NULL) == -1 && errno == EINTR) {
        // signal was received, exit loop
        break;
    }
}

int main() {
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Error registering cleanup function: %s\n", strerror(errno));
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        exit(1);
    }

    gpioSetMode(IMU_CS_PIN, PI_OUTPUT);
    gpioWrite(IMU_CS_PIN, 1);

    int imu_fd = spidev_open(IMU_SPI_BUS, IMU_CS_PIN);
