        usleep(IMU_STALL_TIME_US * 1000);

        if (spidev_read(imu_fd, &gyro_z, 2) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            continue;
        }

        if (spidev_write(imu_fd, 0x00 << 8 | IMU_ACCEL_X_REG, 1) < 0) {
            fprintf(stderr, "Error sending command: %s\n", strerror(errno));
            continue;
        }

        usleep(IMU_STALL_TIME_US * 1000);

        if (spidev_read(imu_fd, &accel_x, 2) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            continue;
        }

        if (spidev_write(imu_fd, 0x00 << 8 | IMU_ACCEL_Y_REG, 1) < 0) {
            fprintf(stderr, "Error sending command: %s\n", strerror(errno));
            continue;
        }

        usleep(IMU_STALL_TIME_US * 1000);

        if (spidev_read(imu_fd, &accel_y, 2) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            continue;
        }

        if (spidev_write(imu_fd, 0x00 << 8 | IMU_ACCEL_Z_REG, 1) < 0) {
            fprintf(stderr, "Error sending command: %s\n", strerror(errno));
            continue;
        }

        usleep(IMU_STALL_TIME_US * 1000);

        if (spidev_read(imu_fd, &accel_z, 2) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            continue;
        }

        double timestamp = (double)time(NULL);
        fprintf(fp, "%f,%f,%f,%f,%f,%f,%f\n",
                timestamp,
                (double)gyro_x * IMU_GYRO_SENSITIVITY,
                (double)gyro_y * IMU_GYRO_SENSITIVITY,
                (double)gyro_z * IMU_GYRO_SENSITIVITY,
