#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Define the SPI device file path
#define SPI_DEVICE "/dev/spidev0.0"

// Define the GPIO pin for CE0
#define CE_PIN 8

// Define the SPI mode and frequency
#define SPI_MODE 0
#define SPI_FREQ 1000000

// Define the register addresses for the ADIS16448 IMU
#define REG_GYRO_X_H 0x00
#define REG_GYRO_X_L 0x01
#define REG_GYRO_Y_H 0x02
#define REG_GYRO_Y_L 0x03
#define REG_GYRO_Z_H 0x04
#define REG_GYRO_Z_L 0x05
#define REG_ACCEL_X_H 0x06
#define REG_ACCEL_X_L 0x07
#define REG_ACCEL_Y_H 0x08
#define REG_ACCEL_Y_L 0x09
#define REG_ACCEL_Z_H 0x0A
#define REG_ACCEL_Z_L 0x0B

// Define the dummy value for the second transfer
#define DUMMY_VALUE 0x0000

// Function to handle Ctrl-C interrupt
void sigint_handler(int sig) {
    // Close the SPI handle
    close(spi_fd);
    // Release the GPIO line
    gpiod_line_release(CE_PIN);
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO line
    struct gpiod_line *ce_line = gpiod_line_request_output(CE_PIN, "adis16448-ce");
    if (!ce_line) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Open the SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(CE_PIN);
        return 1;
    }

    // Set the SPI mode and frequency
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 2;
    xfer.speed_hz = SPI_FREQ;
    xfer.bits_per_word = 16;
    xfer.cs_change = 1;
    xfer.cs_high = 1;
    xfer.cs_low = 1;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(CE_PIN);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_FREQ) < 0) {
        perror("Failed to set SPI frequency");
        close(spi_fd);
        gpiod_line_release(CE_PIN);
        return 1;
    }

    // Set up the signal handler for Ctrl-C interrupt
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(spi_fd);
        gpiod_line_release(CE_PIN);
        return 1;
    }

    // Main loop
    while (1) {
        // Set the CE line high
        gpiod_line_set_value(ce_line, 1);

        // Send the read command
        xfer.tx_buf = (uint64_t)&REG_GYRO_X_H;
        xfer.rx_buf = 0;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to send read command");
            close(spi_fd);
            gpiod_line_release(CE_PIN);
            return 1;
        }

        // Stall for at least 40 us
        usleep(40);

        // Send the dummy value
        xfer.tx_buf = (uint64_t)&DUMMY_VALUE;
        xfer.rx_buf = 0;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to send dummy value");
            close(spi_fd);
            gpiod_line_release(CE_PIN);
            return 1;
        }

        // Get the data
        uint16_t gyro_x = ((uint16_t*)xfer.rx_buf)[0];
        uint16_t gyro_y = ((uint16_t*)xfer.rx_buf)[1];
        uint16_t gyro_z = ((uint16_t*)xfer.rx_buf)[2];
        uint16_t accel_x = ((uint16_t*)xfer.rx_buf)[3];
        uint16_t accel_y = ((uint16_t*)xfer.rx_buf)[4];
        uint16_t accel_z = ((uint16_t*)xfer.rx_buf)[5];

        // Scale the data
        gyro_x = (gyro_x >> 1) * 0.05;
        gyro_y = (gyro_y >> 1) * 0.05;
        gyro_z = (gyro_z >> 1) * 0.05;
        accel_x = (accel_x >> 1) * 0.00025;
        accel_y = (accel_y >> 1) * 0.00025;
        accel_z = (accel_z >> 1) * 0.00025;

        // Print the data
        printf("Gyro: %.2f, %.2f, %.2f deg/sec\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: %.2f, %.2f, %.2f g\n", accel_x, accel_y, accel_z);

        // Set the CE line low
        gpiod_line_set_value(ce_line, 0);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the SPI handle
    close(spi_fd);

    // Release the GPIO line
    gpiod_line_release(CE_PIN);

    return 0;
}

