        uint16_t accel_y = ((uint16_t*)xfer.rx_buf)[4];
        uint16_t accel_z = ((uint16_t*)xfer.rx_buf)[5];

        // Scale the data
        gyro_x = (gyro_x >> 1) * 0.05;
        gyro_y = (gyro_y >> 1) * 0.05;
        gyro_z = (gyro_z >> 1) * 0.05;
        accel_x = (accel_x >> 1) * 0.00025;
        accel_y = (accel_y >> 1) * 0.00025;
        accel_z = (accel_z >> 1) * 0.00025;

        // Print the data
        printf("Gyro: %.2f, %.2f, %.2f deg/sec\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: %.2f, %.2f, %.2f g\n", accel_x, accel_y, accel_z);

        // Set the CE line low
        gpiod_line_set_value(ce_line, 0);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the SPI handle
    close(spi_fd);

    // Release the GPIO line
    gpiod_line_release(CE_PIN);

    return 0;
}
