#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define THRESHOLD 2500
#define SAMPLE_RATE 10  // ms

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Release resources
    gpioTerminate();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    uint8_t device_id;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to write to device ID register\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00) != 0xE5) {
        fprintf(stderr, "Invalid device ID\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up logging
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up LED
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED GPIO\n");
        close(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x32, 6, data) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            close(i2c_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Compute acceleration magnitude
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z) / 256.0f;

        // Check for impact
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpioWrite(LED_GPIO, 1);
            usleep(500000);
            gpioWrite(LED_GPIO, 0);

            // Log impact
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s %f %d %d %d\n", timestamp, magnitude, x, y, z);
        }

        // Sleep
        usleep(SAMPLE_RATE * 1000);
    }

    // Release resources
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

