        perror("i2c_open");
        pigpio_stop();
        exit(1);
    }

    imu_log_file = fopen("imu_log.csv", "w");
    if (imu_log_file == NULL) {
        perror("fopen");
        i2c_close(imu_fd);
        pigpio_stop();
        exit(1);
    }

    fprintf(imu_log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint32_t timestamp = tv.tv_sec * 1000000 + tv.tv_usec;

        uint8_t accel_x[2];
        uint8_t accel_y[2];
        uint8_t accel_z[2];
        uint8_t gyro_x[2];
        uint8_t gyro_y[2];
        uint8_t gyro_z[2];

        if (i2c_smbus_read_byte_data(imu_fd, IMU_ACCEL_X_REG, accel_x) != 0) {
            fprintf(stderr, "Failed to read accelerometer x\n");
            break;
        }
        if (i2c_smbus_read_byte_data(imu_fd, IMU_ACCEL_Y_REG, accel_y) != 0) {
            fprintf(stderr, "Failed to read accelerometer y\n");
            break;
        }
        if (i2c_smbus_read_byte_data(imu_fd, IMU_ACCEL_Z_REG, accel_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer z\n");
            break;
        }
        if (i2c_smbus_read_byte_data(imu_fd, IMU_GYRO_X_REG, gyro_x) != 0) {
            fprintf(stderr, "Failed to read gyroscope x\n");
            break;
        }
        if (i2c_smbus_read_byte_data(imu_fd, IMU_GYRO_Y_REG, gyro_y) != 0) {
            fprintf(stderr, "Failed to read gyroscope y\n");
            break;
        }
        if (i2c_smbus_read_byte_data(imu_fd, IMU_GYRO_Z_REG, gyro_z) != 0) {
            fprintf(stderr, "Failed to read gyroscope z\n");
            break;
        }

        uint16_t accel_x_val = (accel_x[0] << 8) | accel_x[1];
        uint16_t accel_y_val = (accel_y[0] << 8) | accel_y[1];
        uint16_t accel_z_val = (accel_z[0] << 8) | accel_z[1];
        uint16_t gyro_x_val = (gyro_x[0] << 8) | gyro_x[1];
        uint16_t gyro_y_val = (gyro_y[0] << 8) | gyro_y[1];
        uint16_t gyro_z_val = (gyro_z[0] << 8) | gyro_z[1];

        fprintf(imu_log_file, "%u,%d,%d,%d,%d,%d,%d\n",
                timestamp, accel_x_val, accel_y_val, accel_z_val, gyro_x_val, gyro_y_val, gyro_z_val);

        usleep(SAMPLE_RATE_MS * 1000);
    }

    i2c_close(imu_fd);
    pigpio_stop();
    fclose(imu_log_file);
    return 0;
}
