#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"
#define THRESHOLD 2048
#define POLL_INTERVAL 100000 // 100ms

int i2c_fd;
int gpio_fd;
FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd != -1) {
        gpioTerminate();
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

void sigint_handler(int sig) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpio_fd = gpioOpen(LED_PIN, GPIO_MODE_OUTPUT);
    if (gpio_fd == -1) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address 0x%02x\n", I2C_ADDRESS);
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    struct i2c_msg msg;
    uint8_t id[2];

    // Verify sensor identity
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.len = 2;
    msg.buf = id;
    if (i2c_smbus_write(i2c_fd, 0x0D, 1, &msg) < 0) {
        fprintf(stderr, "Failed to write to I2C address 0x%02x\n", I2C_ADDRESS);
        fclose(log_file);
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_smbus_read(i2c_fd, 0x0E, 2, &msg) < 0) {
        fprintf(stderr, "Failed to read from I2C address 0x%02x\n", I2C_ADDRESS);
        fclose(log_file);
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }
    if (id[0] != 0x1C || id[1] != 0x45) {
        fprintf(stderr, "Invalid sensor identity 0x%02x%02x\n", id[0], id[1]);
        fclose(log_file);
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        struct i2c_msg read_msg;
        uint8_t data[6];

        read_msg.addr = I2C_ADDRESS;
        read_msg.flags = 0;
        read_msg.len = 6;
        read_msg.buf = data;

        if (i2c_smbus_write(i2c_fd, 0x02, 1, &msg) < 0) {
            fprintf(stderr, "Failed to write to I2C address 0x%02x\n", I2C_ADDRESS);
            break;
        }
        if (i2c_smbus_read(i2c_fd, 0x00, 6, &read_msg) < 0) {
            fprintf(stderr, "Failed to read from I2C address 0x%02x\n", I2C_ADDRESS);
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        int magnitude = (int)sqrt(x * x + y * y + z * z) / 64;

        if (magnitude > THRESHOLD) {
            gpioWrite(gpio_fd, 1);
            usleep(500000);
            gpioWrite(gpio_fd, 0);
        }

        fprintf(log_file, "%lu %d %d %d\n", time(NULL), x, y, z);
        fflush(log_file);

        usleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

