#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define CSV_FILE "magnetic_field_log.csv"
#define CSV_HEADER "timestamp,x,y,z\n"

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        exit(1);
    }
    return fd;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int ret = read(fd, buf, len);
    if (ret < 0) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return ret;
}

void log_data(int fd, double timestamp, int16_t x, int16_t y, int16_t z) {
    char buffer[256];
    sprintf(buffer, "%f,%d,%d,%d\n", timestamp, x, y, z);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to CSV file");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        exit(1);
    }

    int fd = i2c_open();
    int csv_fd = open(CSV_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        close(fd);
        exit(1);
    }

    if (ftruncate(csv_fd, 0) < 0) {
        perror("Failed to truncate CSV file");
        close(fd);
        close(csv_fd);
        exit(1);
    }

    if (write(csv_fd, CSV_HEADER, strlen(CSV_HEADER)) < 0) {
        perror("Failed to write CSV header");
        close(fd);
        close(csv_fd);
        exit(1);
    }

    uint8_t reg = 0x00;
    while (running) {
        if (i2c_read(fd, &reg, 1) < 0) {
            fprintf(stderr, "Error reading from I2C bus, skipping sample\n");
            continue;
        }

        uint8_t data[6];
        if (i2c_read(fd, data, 6) < 0) {
            fprintf(stderr, "Error reading from I2C bus, skipping sample\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + (ts.tv_nsec / 1e9);

        log_data(csv_fd, timestamp, x, y, z);

        sleep(1);
    }

    close(fd);
    close(csv_fd);
    return 0;
}

