#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/select.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x1D
#define GPIO_INT_PIN 17
#define CSV_LOG_FILE "freefall_log.csv"

// Function to read a byte from the ADXL345
uint8_t read_byte(int i2c_fd, uint8_t reg) {
    uint8_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte(i2c_fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_byte(i2c_fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        exit(1);
    }
    return data;
}

// Function to write a byte to the ADXL345
void write_byte(int i2c_fd, uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte_data(i2c_fd, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(1);
    }
}

// Function to enable the ADXL345 interrupt
void enable_interrupt(int i2c_fd) {
    // Place the sensor in standby mode
    write_byte(i2c_fd, 0x2D, 0x00);
    // Enable the INT1 pin
    write_byte(i2c_fd, 0x2A, 0x02);
    // Enable free-fall detection
    write_byte(i2c_fd, 0x1C, 0x08);
}

// Function to disable the ADXL345 interrupt
void disable_interrupt(int i2c_fd) {
    // Disable free-fall detection
    write_byte(i2c_fd, 0x1C, 0x00);
    // Disable the INT1 pin
    write_byte(i2c_fd, 0x2A, 0x00);
}

// Function to read the ADXL345 device ID
uint8_t read_device_id(int i2c_fd) {
    uint8_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_byte(i2c_fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        exit(1);
    }
    return data;
}

// Function to read the ADXL345 acceleration data
void read_acceleration(int i2c_fd, uint8_t *x, uint8_t *y, uint8_t *z) {
    // Place the sensor in standby mode
    write_byte(i2c_fd, 0x2D, 0x00);
    // Read the acceleration data
    *x = read_byte(i2c_fd, 0x32);
    *y = read_byte(i2c_fd, 0x34);
    *z = read_byte(i2c_fd, 0x36);
