        fprintf(stderr, "Failed to write CTRL_REG5\n");
        return 1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, LSM6DSR_ADDRESS, CTRL_REG6, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG6\n");
        return 1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, LSM6DSR_ADDRESS, CTRL_REG7, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG7\n");
        return 1;
    }
