    }
    if (gpioI2CWriteReg8(I2C_BUS, LSM6DSR_ADDRESS, GYRO_CONFIG, GYRO_RANGE_250DPS) < 0) {
        fprintf(stderr, "Failed to write GYRO_CONFIG\n");
        return 1;
    }
    // Open file for logging
    FILE *log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    // Initialize state machine
    state_t state = IDLE;
    uint32_t last_impact_time = 0;
    // Main loop
    while (1) {
        // Read sensor data
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_X_L_REGISTER, &accel_x) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            return 1;
        }
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_Y_L_REGISTER, &accel_y) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            return 1;
        }
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_Z_L_REGISTER, &accel_z) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            return 1;
        }
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_X_L_REGISTER, &gyro_x) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            return 1;
        }
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_Y_L_REGISTER, &gyro_y) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            return 1;
        }
        if (gpioI2CReadReg16(I2C_BUS, LSM6DSR_ADDRESS, OUT_Z_L_REGISTER, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            return 1;
        }
        // Calculate acceleration magnitude
        float accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z) / 16384.0;
        // Update state machine
        if (state == IDLE && accel_magnitude < DETECTION_THRESHOLD_ACCEL) {
            state = FREEFALL;
            last_impact_time = 0;
        } else if (state == FREEFALL && accel_magnitude > DETECTION_THRESHOLD_IMPACT && last_impact_time + DETECTION_WINDOW > time(NULL)) {
            state = IMPACT;
            last_impact_time = time(NULL);
        } else if (state == IMPACT && accel_magnitude < DETECTION_THRESHOLD_ACCEL) {
            state = IDLE;
        }
        // Log data
        fprintf(log_file, "%f,%f,%f,%f,%f,%f,%d\n", time(NULL), accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        // Sleep for 10 ms
        usleep(10000);
    }
    // Close log file
    fclose(log_file);
    // Release I2C bus
    gpioI2CClose(I2C_BUS);
    // Release GPIO pins
    gpioRelease(SDA_PIN);
    gpioRelease(SCL_PIN);
    // Exit program
    return 0;
}
