        fprintf(stderr, "Failed to set SPI mode\n");
        spidevClose(spi_fd);
        gpioTerminate();
        close(log_fd);
        return 1;
    }

    if (spidevSetCS(spi_fd, SPI_CS_PIN, 1) == -1) {
        fprintf(stderr, "Failed to set SPI CS pin\n");
        spidevClose(spi_fd);
        gpioTerminate();
        close(log_fd);
        return 1;
    }

    struct tm time;
    time.tm_year = 2024 - 1900;
    time.tm_mon = 7 - 1;
    time.tm_mday = 26;
    time.tm_hour = 0;
    time.tm_min = 0;
    time.tm_sec = 0;

    while (running) {
