        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time);
        char buffer[20];

        if (gpioWrite(SPI_CS_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set SPI CS pin low\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

