            fprintf(stderr, "Failed to set SPI CS pin low\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        uint16_t xg, yg, zg;
        if (spidevXfer(spi_fd, 2, (uint8_t*)&xg, 2) == -1) {
            fprintf(stderr, "Failed to read XG register\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }
        if (spidevXfer(spi_fd, 2, (uint8_t*)&yg, 2) == -1) {
            fprintf(stderr, "Failed to read YG register\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }
        if (spidevXfer(spi_fd, 2, (uint8_t*)&zg, 2) == -1) {
            fprintf(stderr, "Failed to read ZG register\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        if (gpioWrite(SPI_CS_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set SPI CS pin high\n");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        double angular_rate_x = (double)xg * ADIS16266_SCALE_FACTOR;
        double angular_rate_y = (double)yg * ADIS16266_SCALE_FACTOR;
        double angular_rate_z = (double)zg * ADIS16266_SCALE_FACTOR;

        sprintf(buffer, "%s,%.6f,%.6f,%.6f\n", timestamp, angular_rate_x, angular_rate_y, angular_rate_z);
        if (write(log_fd, buffer, strlen(buffer)) == -1) {
            perror("write");
            spidevClose(spi_fd);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        time_t next_time = timegm(&time) + 10;
        while (timegm(&time) < next_time) {
            usleep(100000);
            time = *localtime(&time);
        }
    }

    spidevClose(spi_fd);
    gpioTerminate();
    close(log_fd);
    return 0;
