code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define GYRO_I2C_BUS 1
#define GYRO_I2C_ADDR 0x6A
#define GYRO_WHO_AM_I_REG 0x0F
#define GYRO_XOUT_H_REG 0x19
#define GYRO_XOUT_L_REG 0x1A
#define GYRO_YOUT_H_REG 0x1B
#define GYRO_YOUT_L_REG 0x1C
#define GYRO_ZOUT_H_REG 0x1D
#define GYRO_ZOUT_L_REG 0x1E

#define SENSITIVITY 8.75
#define SAMPLE_RATE 10  // ms

#define MAX_RETRIES 3

// Function to convert raw gyroscope values to angular velocity
void convert_gyro_values(int16_t *x, int16_t *y, int16_t *z) {
    *x = (*x / 114.285);
    *y = (*y / 114.285);
    *z = (*z / 114.285);
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, GYRO_I2C_ADDR) < 0) {
            if (errno == EBUSY) {
                // Try again
                retries++;
                usleep(100000);
            } else {
                // Error occurred
                return -1;
            }
        } else {
            // Read data from the gyroscope
            uint8_t data[6];
            if (i2c_smbus_read_i2c_block_data(fd, GYRO_XOUT_H_REG, 6, data) < 0) {
                // Error occurred
                return -1;
            }
            *x = (data[1] << 8) | data[0];
            *y = (data[3] << 8) | data[2];
            *z = (data[5] << 8) | data[4];
            convert_gyro_values(x, y, z);
            return 0;
        }
    }
    // Maximum retries exceeded
    return -1;
}

// Function to write to CSV file
void write_to_csv(FILE *file, double timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(file, "%lld,%d,%d,%d\n", (long long)timestamp, x, y, z);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    int fd = open("/dev/i2c-" GYRO_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    uint8_t who_am_i;
    if (ioctl(fd, I2C_SLAVE, GYRO_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (i2c_smbus_read_byte(fd, GYRO_WHO_AM_I_REG) != 0x69) {
        fprintf(stderr, "Sensor identity mismatch\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    FILE *file = fopen("gyro_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }
    fprintf(file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    struct timeval last_time;
    gettimeofday(&last_time, NULL);
    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        double timestamp = (double)(current_time.tv_sec - last_time.tv_sec) + (double)(current_time.tv_usec - last_time.tv_usec) / 1e6;
        last_time = current_time;

        int16_t x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        write_to_csv(file, timestamp, x, y, z);

        usleep(SAMPLE_RATE * 1000);
    }

    // Close I2C handle
    close(fd);

    // Close CSV file
    fclose(file);

    // Terminate GPIO library
    gpioTerminate();

    return 0;
}

