#include <syslog.h>
#include <libgpiod/libgpiod.h>

#define LOG_FILE "flame_events.log"
#define GPIO_PIN 17
#define POLL_INTERVAL 500000  // 500 ms in microseconds
#define MAX_LOG_LINE 64

volatile bool exit_flag = false;

void sigint_handler(int sig) {
    exit_flag = true;
}

int main() {
    gpiod_context *ctx;
    gpiod_line *line;
    gpiod_line_event *event;
    FILE *log_file;
    char log_line[MAX_LOG_LINE];

    // Initialize the GPIO driver
    ctx = gpiod_ctx_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO line
    line = gpiod_line_new(ctx, "gpio17", GPIOD_LINE_ACTIVE_LOW);
    if (!line) {
        syslog(LOG_ERR, "Failed to open GPIO line");
        gpiod_ctx_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Enable the internal pull-up resistor
    if (gpiod_line_request_output(line, GPIOD_LINE_ACTIVE_HIGH) != 0) {
        syslog(LOG_ERR, "Failed to enable pull-up resistor");
        gpiod_line_unref(line);
        gpiod_ctx_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_line_unref(line);
        gpiod_ctx_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the log file with a header
    fprintf(log_file, "YYYY-MM-DD HH:MM:SS – Flame detected: ");
    fflush(log_file);

    while (!exit_flag) {
        // Read the GPIO line
        event = gpiod_line_get_value(line);
        if (!event) {
            syslog(LOG_ERR, "Failed to read GPIO line");
            gpiod_line_unref(line);
            gpiod_ctx_free(ctx);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Check the line value
        if (event->value == GPIOD_LINE_LOW) {
            // Flame detected
            syslog(LOG_INFO, "FLAME DETECTED!");
            fprintf(log_file, "YES\n");
        } else {
            fprintf(log_file, "NO\n");
        }

        // Flush the log file
        fflush(log_file);

        // Release the event
        gpiod_line_event_unref(event);

        // Wait for the next poll interval
        usleep(POLL_INTERVAL);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO line
    gpiod_line_unref(line);

    // Free the GPIO context
    gpiod_ctx_free(ctx);

    return EXIT_SUCCESS;
}

