#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define CSV_FILE "vibration_log.csv"
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define SAMPLE_COUNT 3

// Structure to hold sensor data
typedef struct {
    int x;
    int y;
    int z;
} sensor_data_t;

// Function to read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t reg[2];
    int ret;

    // Read X-axis data
    reg[0] = 0x00; // Register address for X-axis data
    ret = i2c_smbus_read_byte_data(fd, I2C_ADDR, reg);
    if (ret < 0) {
        if (errno == EIO) {
            // Sensor-absent condition
            return -1;
        } else {
            fprintf(stderr, "Error reading X-axis data: %s\n", strerror(errno));
            return -1;
        }
    }
    data->x = (int)ret;

    // Read Y-axis data
    reg[0] = 0x01; // Register address for Y-axis data
    ret = i2c_smbus_read_byte_data(fd, I2C_ADDR, reg);
    if (ret < 0) {
        if (errno == EIO) {
            // Sensor-absent condition
            return -1;
        } else {
            fprintf(stderr, "Error reading Y-axis data: %s\n", strerror(errno));
            return -1;
        }
    }
    data->y = (int)ret;

    // Read Z-axis data
    reg[0] = 0x02; // Register address for Z-axis data
    ret = i2c_smbus_read_byte_data(fd, I2C_ADDR, reg);
    if (ret < 0) {
        if (errno == EIO) {
            // Sensor-absent condition
            return -1;
        } else {
            fprintf(stderr, "Error reading Z-axis data: %s\n", strerror(errno));
            return -1;
        }
    }
    data->z = (int)ret;

    return 0;
}

// Function to write data to CSV file
void write_to_csv(FILE *file, sensor_data_t *data) {
    char timestamp[32];
    time_t now;
    struct tm *lt;

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", lt);
    fprintf(file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    fclose(csv_file);
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    sensor_data_t data;
    struct i2c_adapter *adapter;
    struct i2c_client *client;
    struct i2c_msg msg;
    char buffer[256];
    int ret;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Get I2C adapter
    adapter = i2c_get_adapter(i2c_fd);
    if (!adapter) {
        fprintf(stderr, "Error getting I2C adapter\n");
        close(i2c_fd);
        return 1;
    }

    // Get I2C client
    client = i2c_get_client(adapter, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Error getting I2C client\n");
        i2c_put_adapter(adapter);
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2c_put_client(client);
        i2c_put_adapter(adapter);
        close(i2c_fd);
        return 1;
    }

    // Write header to CSV file
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read sensor data
        ret = read_sensor_data(i2c_fd, &data);
        if (ret < 0) {
            // Sensor-absent condition or I2C error
            continue;
        }

        // Write data to CSV file
        write_to_csv(csv_file, &data);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close I2C device and CSV file
    fclose(csv_file);
    close(i2c_fd);
    i2c_put_client(client);
    i2c_put_adapter(adapter);

    return 0;
}

