#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_HALL_SENSOR1 17
#define GPIO_HALL_SENSOR2 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL 50  // milliseconds

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void log_state(int sensor, int value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    char timestamp[20];
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s %d %d\n", timestamp, sensor, value);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_HALL_SENSOR1, PI_INPUT);
    gpioSetMode(GPIO_HALL_SENSOR2, PI_INPUT);
    gpioSetPullUpDnControl(GPIO_HALL_SENSOR1, PI_PUD_UP);
    gpioSetPullUpDnControl(GPIO_HALL_SENSOR2, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    while (running) {
        int value1 = gpioRead(GPIO_HALL_SENSOR1);
        int value2 = gpioRead(GPIO_HALL_SENSOR2);

        if (value1 == 1 && value2 == 1) {
            printf("Conveyor halted\n");
        }

        log_state(GPIO_HALL_SENSOR1, value1);
        log_state(GPIO_HALL_SENSOR2, value2);

        usleep(LOG_INTERVAL * 1000);
    }

    gpioCleanup();
    return EXIT_SUCCESS;
}

