#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CALIBRATION_OFFSET_X 0
#define CALIBRATION_OFFSET_Y 0
#define CALIBRATION_OFFSET_Z 0
#define CALIBRATION_SCALE_X 1.0
#define CALIBRATION_SCALE_Y 1.0
#define CALIBRATION_SCALE_Z 1.0
#define SENSITIVITY 0.146

#define MAX_LINE_LENGTH 256

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        exit(1);
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

void write_i2c(int fd, uint8_t reg, uint8_t value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void read_i2c(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C register");
        exit(1);
    }
}

void init_sensor(int fd) {
    write_i2c(fd, 0x0B, 0x02); // Set data rate to 100 Hz
    write_i2c(fd, 0x0A, 0x02); // Set measurement mode to 16-bit
}

void read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    read_i2c(fd, 0x02, data);
    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];
}

void apply_calibration(int16_t *x, int16_t *y, int16_t *z) {
    *x = (*x - CALIBRATION_OFFSET_X) * CALIBRATION_SCALE_X;
    *y = (*y - CALIBRATION_OFFSET_Y) * CALIBRATION_SCALE_Y;
    *z = (*z - CALIBRATION_OFFSET_Z) * CALIBRATION_SCALE_Z;
}

void print_sample(int16_t x, int16_t y, int16_t z) {
    float magnitude = sqrtf((x * x + y * y + z * z) * SENSITIVITY * SENSITIVITY);
    if (magnitude > 800) {
        fprintf(stderr, "Metal detected!\n");
    }
    fprintf(stderr, "%d,%d,%d\n", x, y, z);
    fflush(stderr);
}

int main() {
    int fd = i2c_open();
    for (int i = 0; i < 3; i++) {
        init_sensor(fd);
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == 0) {
            break;
        }
        usleep(100000);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) != 0) {
        perror("Failed to set I2C address");
        i2c_close(fd);
        exit(1);
    }

    FILE *log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_close(fd);
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        int16_t x, y, z;
        read_sensor(fd, &x, &y, &z);
        apply_calibration(&x, &y, &z);
        print_sample(x, y, z);
        fprintf(log_file, "%d,%d,%d\n", x, y, z);
        fflush(log_file);
        usleep(100000);
    }

    fclose(log_file);
    i2c_close(fd);
    return 0;
}

