        gpiod_line_release(reset);
        gpiod_line_release(cs);
        gpiod_line_release(miso);
        gpiod_line_release(mosi);
        gpiod_line_release(sck);
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return 1;
    }

