#include <signal.h>
#include <sys/time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define POLL_INTERVAL_US 100000

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct gpiod_line *line1, *line2;
    struct gpiod_chip *chip;
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO driver
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the lines
    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        fprintf(stderr, "Failed to get line 27\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return EXIT_FAILURE;
    }

    // Set the direction of the lines to input
    ret = gpiod_line_request_output(line1, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 17 as input: %d\n", ret);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 27 as input: %d\n", ret);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Create a bulk read request
    events = gpiod_chip_get_bulk_read_request(chip, 2);
    if (!events) {
        fprintf(stderr, "Failed to create bulk read request\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Add the lines to the bulk read request
    ret = gpiod_line_add_to_bulk_read_request(line1, events);
    if (ret) {
        fprintf(stderr, "Failed to add line 17 to bulk read request: %d\n", ret);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        gpiod_bulk_read_request_free(events);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_add_to_bulk_read_request(line2, events);
    if (ret) {
        fprintf(stderr, "Failed to add line 27 to bulk read request: %d\n", ret);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        gpiod_bulk_read_request_free(events);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read the lines
        ret = gpiod_bulk_read_request_read(events);
        if (ret) {
            fprintf(stderr, "Failed to read bulk request: %d\n", ret);
            break;
        }

        // Get the events
