#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_LSBFIRST 0
#define SPI_CS_PIN 8
#define SPI_DEVICE "/dev/spidev0.0"
#define SCALE_FACTOR 0.02

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} GyroData;

// Function to read data from the gyroscope
int readGyroData(int spiFd, uint8_t* address) {
    uint8_t txBuffer[2];
    uint8_t rxBuffer[4];

    // Send address byte with MSB set
    txBuffer[0] = *address | 0x80;
    if (ioctl(spiFd, SPI_IOC_MESSAGE(1), txBuffer) < 0) {
        perror("ioctl");
        return -1;
    }

    // Send read command
    txBuffer[0] = 0x00;
    if (ioctl(spiFd, SPI_IOC_MESSAGE(1), txBuffer) < 0) {
        perror("ioctl");
        return -1;
    }

    // Receive data
    if (ioctl(spiFd, SPI_IOC_MESSAGE(2), rxBuffer) < 0) {
        perror("ioctl");
        return -1;
    }

    // Extract data
    GyroData data;
    data.x = (rxBuffer[0] << 8) | rxBuffer[1];
    data.y = (rxBuffer[2] << 8) | rxBuffer[3];

    return 0;
}

int main() {
    int spiFd = open(SPI_DEVICE, O_RDWR);
    if (spiFd < 0) {
        perror("open");
        return 1;
    }

    // Set up SPI
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = 8;
    xfer.cs_change = 1;
    xfer.cs_high = 1;
    xfer.cs_low = 1;

    if (ioctl(spiFd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("ioctl");
        close(spiFd);
        return 1;
    }

    if (ioctl(spiFd, SPI_IOC_WR_LSBFIRST, &SPI_LSBFIRST) < 0) {
        perror("ioctl");
        close(spiFd);
        return 1;
    }

    if (ioctl(spiFd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl");
        close(spiFd);
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        close(spiFd);
        return 1;
    }

    // Set up CS pin as output
    if (gpioSetMode(SPI_CS_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        close(spiFd);
        return 1;
    }

    // Set CS pin low
    gpioWrite(SPI_CS_PIN, 0);

    // Main loop
    while (1) {
        uint8_t address = 0x00; // Address for X-axis data
        if (readGyroData(spiFd, &address) < 0) {
            perror("readGyroData");
            break;
        }

        // Calculate X, Y, and Z angular rates
        GyroData data;
        readGyroData(spiFd, &address);
        data.x = (data.x * SCALE_FACTOR);
        data.y = (data.y * SCALE_FACTOR);
        data.z = (data.z * SCALE_FACTOR);

        // Log data to console
        printf("X: %d deg/sec, Y: %d deg/sec, Z: %d deg/sec\n", data.x, data.y, data.z);

        // Wait 100ms
        usleep(100000);
    }

    // Clean up
    gpioWrite(SPI_CS_PIN, 1);
    gpioTerminate();
    close(spiFd);

    return 0;
}

