#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define LSM6DSR_ADDRESS 0x6A
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_OUT_X_L 0x29
#define LSM6DSR_OUT_X_H 0x2A
#define LSM6DSR_OUT_Y_L 0x2B
#define LSM6DSR_OUT_Y_H 0x2C
#define LSM6DSR_OUT_Z_L 0x2D
#define LSM6DSR_OUT_Z_H 0x2E
#define LSM6DSR_GYRO_X_L 0x1D
#define LSM6DSR_GYRO_X_H 0x1E
#define LSM6DSR_GYRO_Y_L 0x1F
#define LSM6DSR_GYRO_Y_H 0x20
#define LSM6DSR_GYRO_Z_L 0x21
#define LSM6DSR_GYRO_Z_H 0x22

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *scl, *sda;
    int ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize gpiod library
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get SCL and SDA lines
    scl = gpiod_line_create_onlabel(chip, "gpio_default");
    if (!scl) {
        fprintf(stderr, "Failed to get SCL line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    sda = gpiod_line_create_onlabel(chip, "gpio_default");
    if (!sda) {
        fprintf(stderr, "Failed to get SDA line\n");
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure SCL and SDA as I2C lines
    ret = gpiod_line_request_output(scl, "scl", GPIOD_LINE_ACTIVE_LOW);
    if (ret) {
        fprintf(stderr, "Failed to request SCL line\n");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(sda, "sda", GPIOD_LINE_ACTIVE_LOW);
    if (ret) {
        fprintf(stderr, "Failed to request SDA line\n");
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, LSM6DSR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return 1;
    }

    // Check WHO_AM_I register
    uint8_t who_am_i;
    ret = read(fd, &who_am_i, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        close(fd);
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return 1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        close(fd);
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read accelerometer and gyroscope values
        uint8_t data[6];
        ret = i2c_smbus_read_i2c_block_data(fd, LSM6DSR_OUT_X_L, 6, data);
        if (ret != 6) {
            fprintf(stderr, "Failed to read accelerometer and gyroscope values\n");
            break;
        }

        // Print values
        printf("%d %d %d %d %d %d\n",
               (data[0] << 8) | data[1], (data[2] << 8) | data[3],
               (data[4] << 8) | data[5], (data[6] << 8) | data[7],
               (data[8] << 8) | data[9], (data[10] << 8) | data[11]);

        // Wait 100ms
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 100000;
        select(0, NULL, NULL, NULL, &tv);
    }

    // Clean up
    close(fd);
    gpiod_line_release(scl);
    gpiod_line_release(sda);
    gpiod_chip_close(chip);
    gpiod_cleanup();

    return 0;
}

