#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define the I2C bus and device addresses
#define I2C_BUS 1
#define ADXL345_ADDRESS 0x1D

// Define the threshold for tilt detection
#define TILT_THRESHOLD 30.0

// Define the logging function
void log_tilt_event(const char *message) {
    char timestamp[32];
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "%s: %s", timestamp, message);
    syslog(LOG_INFO, "Tilt event detected at %s", timestamp);
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, "Tilt event detected at %s", timestamp);
    closelog();
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set the I2C bus to the ADXL345 address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize the ADXL345
    uint8_t reg = 0x2A; // POWER_CTL register
    uint8_t value = 0x08; // Measurement mode
    if (i2c_smbus_write_byte_data(i2c_fd, reg, value) < 0) {
        syslog(LOG_ERR, "Failed to initialize ADXL345");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up the sampling period
    struct timespec period = {0, 100000000}; // 100 ms
    while (1) {
        // Read the acceleration data
        uint8_t data[6];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x32, 6, data) < 0) {
            syslog(LOG_ERR, "Failed to read acceleration data");
            close(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Calculate the tilt angle
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        double angle = atan2(y, z) * 180.0 / M_PI;

        // Check if the tilt exceeds the threshold
        if (angle > TILT_THRESHOLD) {
            log_tilt_event("Tilt detected");
        }

        // Wait for the next sampling period
        nanosleep(&period);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

