#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 1000000
#define WINDOW_DURATION_S 5
#define PAUSE_DURATION_S 1

static volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    gpiod_context *ctx;
    gpiod_line *line;
    gpiod_line_event *event;
    gpiod_line_event *events;
    gpiod_line_event *event_iter;

    if ((ctx = gpiod_context_new()) == NULL) {
        fprintf(stderr, "Failed to create gpiod context: %s\n", gpiod_context_strerror(errno));
        return EXIT_FAILURE;
    }

    if ((line = gpiod_line_create(ctx, "gpio17", GPIOD_LINE_ACTIVE_HIGH)) == NULL) {
        fprintf(stderr, "Failed to create gpiod line: %s\n", gpiod_context_strerror(errno));
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_HIGH) != 0) {
        fprintf(stderr, "Failed to request gpiod line as output: %s\n", gpiod_context_strerror(errno));
        gpiod_line_release(line);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }

    gpiod_line_export(line);

    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    while (running) {
        uint32_t count = 0;
        uint64_t timestamp = start.tv_sec * 1000000000 + start.tv_nsec;

        for (int i = 0; i < WINDOW_DURATION_S * 1000; i++) {
            if (gpiod_line_get_value(line) == 1) {
                count++;
            }

            usleep(SAMPLE_INTERVAL_US);
        }

        if (count > threshold) {
            fprintf(stdout, "%lu: ALERT\n", timestamp);
        } else {
            fprintf(stdout, "%lu: %u high readings\n", timestamp, count);
        }

        clock_gettime(CLOCK_REALTIME, &end);
        timestamp = end.tv_sec * 1000000000 + end.tv_nsec - start.tv_sec * 1000000000 - start.tv_nsec;
        fprintf(stdout, "Window duration: %lu us\n", timestamp);

        gpiod_line_export(line);

        gpiod_line_set_value(line, 0);
        gpiod_line_set_value(line, 1);

        gpiod_line_unexport(line);

        sleep(PAUSE_DURATION_S);

        start = end;
    }

    gpiod_line_release(line);
    gpiod_context_free(ctx);

    return EXIT_SUCCESS;
}

