#define LOG_INTERVAL 5000
#define LOG_FILE "light_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, LIGHT_SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint16_t* value) {
    if (ioctl(fd, I2C_SLAVE, LIGHT_SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    if (read(fd, value, 2) != 2) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    int fd = i2c_open();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    uint8_t control = 0x13;
    if (i2c_write(fd, LIGHT_SENSOR_REG_CONTROL, control) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t lux;
        if (i2c_read(fd, LIGHT_SENSOR_REG_DATA, &lux) < 0) {
            fprintf(stderr, "Failed to read from light sensor\n");
            break;
        }

        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, Lux: %d\n", timestamp, lux);

        sleep(LOG_INTERVAL / 1000);
    }

    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

