#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define MAG_I2C_BUS 1
#define MAG_I2C_ADDR 0x1E
#define MAG_REG_OUT_X_H 0x00
#define MAG_REG_OUT_X_L 0x01
#define MAG_REG_OUT_Y_H 0x02
#define MAG_REG_OUT_Y_L 0x03
#define MAG_REG_OUT_Z_H 0x04
#define MAG_REG_OUT_Z_L 0x05

#define LOG_FILE "/var/log/magnetometer.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int mag_fd;
    int ret;
    uint8_t data[6];
    uint16_t z_axis;
    uint16_t max_z_axis = 0;
    uint16_t min_z_axis = 65535;
    uint16_t avg_z_axis = 0;
    uint16_t count = 0;
    int log_fd;
    struct sigaction sa;

    // Set up logging
    openlog(NULL, LOG_PID, LOG_USER);
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }

    // Set up PWM
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up PWM");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPWM(LED_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set up PWM");
        gpioTerminate();
        exit(1);
    }

    // Open I2C bus
    mag_fd = gpioI2COpen(MAG_I2C_BUS, MAG_I2C_ADDR);
    if (mag_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpioTerminate();
        exit(1);
    }

    while (running) {
        // Read data from magnetometer
        ret = gpioI2CRead(mag_fd, MAG_REG_OUT_X_H, data, 6);
        if (ret != 6) {
            syslog(LOG_ERR, "I2C read error");
            continue;
        }

        // Extract Z-axis field magnitude
        z_axis = (uint16_t)((data[4] << 8) | data[5]);
        if (z_axis > max_z_axis) {
            max_z_axis = z_axis;
        }
        if (z_axis < min_z_axis) {
            min_z_axis = z_axis;
        }
        avg_z_axis = (avg_z_axis * count + z_axis) / (count + 1);
        count++;

        // Drive LED with PWM
        gpioPWM(LED_PIN, (uint32_t)((z_axis - min_z_axis) * 100 / (max_z_axis - min_z_axis));

        // Log data
        syslog(LOG_INFO, "Z-axis: %d", z_axis);
        fprintf(log_fd, "%d\n", z_axis);
        fflush(log_fd);

        // Sleep
        usleep(100000);
    }

    // Clean up
    gpioPWM(LED_PIN, 0);
    gpioI2CClose(mag_fd);
    gpioTerminate();
    close(log_fd);
    closelog();

    return 0;
}

