#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define SAMPLES 100
#define OFFSET_UPDATE_INTERVAL 1000 // ms
#define READ_INTERVAL 500 // ms

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    int offset_x = 0;
    int offset_y = 0;
    int offset_z = 0;
    int samples[SAMPLES] = {0};
    int sample_count = 0;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(i2c_fd, &read_fds);
        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = READ_INTERVAL * 1000;
        if (select(i2c_fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                fprintf(stderr, "select() failed: %s\n", strerror(errno));
                break;
            }
        }

        if (FD_ISSET(i2c_fd, &read_fds)) {
            uint8_t data[6];
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
                fprintf(stderr, "Failed to set I2C slave address\n");
                break;
            }

            if (i2c_smbus_read_byte_data(i2c_fd, 0x03) < 0) {
