#define SAMPLES 100
#define OFFSET_UPDATE_INTERVAL 1000 // ms
#define READ_INTERVAL 500 // ms

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    int offset_x = 0;
    int offset_y = 0;
    int offset_z = 0;
    int samples[SAMPLES] = {0};
    int sample_count = 0;

