#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// Function to handle signal
void sig_handler(int sig) {
    // Set both lines LOW
    if (gpiod_line_set_value(gpiod, "gpio17", GPIOD_LINE_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO17 LOW: %s\n", gpiod_error());
        exit(1);
    }
    if (gpiod_line_set_value(gpiod, "gpio27", GPIOD_LINE_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO27 LOW: %s\n", gpiod_error());
        exit(1);
    }

    // Release all resources
    gpiod_close(gpiod);
    gpiod_exit();
    exit(0);
}

int main() {
    // Initialize GPIO
    gpiod = gpiod_open("/dev/gpiochip0");
    if (gpiod < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", gpiod_error());
        exit(1);
    }

    // Set both lines LOW at startup
    if (gpiod_line_request_output(gpiod, "gpio17", GPIOD_LINE_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO17 as output: %s\n", gpiod_error());
        gpiod_close(gpiod);
        gpiod_exit();
        exit(1);
    }
    if (gpiod_line_request_output(gpiod, "gpio27", GPIOD_LINE_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO27 as output: %s\n", gpiod_error());
        gpiod_line_release(gpiod, "gpio17");
        gpiod_close(gpiod);
        gpiod_exit();
        exit(1);
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpiod_line_release(gpiod, "gpio17");
        gpiod_line_release(gpiod, "gpio27");
        gpiod_close(gpiod);
        gpiod_exit();
        exit(1);
    }

    // Main loop
    while (1) {
        // Set GPIO17 HIGH
        if (gpiod_line_set_value(gpiod, "gpio17", GPIOD_LINE_HIGH) < 0) {
            fprintf(stderr, "Error setting GPIO17 HIGH: %s\n", gpiod_error());
            gpiod_line_release(gpiod, "gpio17");
            gpiod_line_release(gpiod, "gpio27");
            gpiod_close(gpiod);
            gpiod_exit();
            exit(1);
        }
        if (gpiod_line_set_value(gpiod, "gpio27", GPIOD_LINE_LOW) < 0) {
            fprintf(stderr, "Error setting GPIO27 LOW: %s\n", gpiod_error());
            gpiod_line_release(gpiod, "gpio17");
            gpiod_line_release(gpiod, "gpio27");
            gpiod_close(gpiod);
            gpiod_exit();
            exit(1);
        }

        // Delay
        nanosleep(&(struct timespec){.tv_sec=0, .tv_nsec=500000000});

        // Set GPIO27 HIGH
        if (gpiod_line_set_value(gpiod, "gpio17", GPIOD_LINE_LOW) < 0) {
            fprintf(stderr, "Error setting GPIO17 LOW: %s\n", gpiod_error());
            gpiod_line_release(gpiod, "gpio17");
            gpiod_line_release(gpiod, "gpio27");
            gpiod_close(gpiod);
            gpiod_exit();
            exit(1);
        }
        if (gpiod_line_set_value(gpiod, "gpio27", GPIOD_LINE_HIGH) < 0) {
            fprintf(stderr, "Error setting GPIO27 HIGH: %s\n", gpiod_error());
            gpiod_line_release(gpiod, "gpio17");
            gpiod_line_release(gpiod, "gpio27");
            gpiod_close(gpiod);
            gpiod_exit();
            exit(1);
        }
    }

