#include <unistd.h>
#include <gpiod.h>

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define SERIAL_PORT1 "/dev/serial0"
#define SERIAL_PORT2 "/dev/serial1"
#define SERIAL_BAUD 9600
#define SERIAL_TIMEOUT 5
#define EXPECTED_CODE "123456"

static volatile int running = 1;

void sigint_handler(int sig) {
    gpiod_cset(RLAY1_GPIO, 0);
    gpiod_cset(RLAY2_GPIO, 0);
    gpiod_close();
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *relay1, *relay2;
    int serial1, serial2;
    char code1[7], code2[7];
    ssize_t bytes_read1, bytes_read2;
    int i;

    // Initialize GPIO library
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    // Initialize relay lines
    if ((relay1 = gpiod_line_request_output(chip, RELAY1_GPIO, "active-high")) == NULL) {
        fprintf(stderr, "Failed to request relay1 line\n");
        gpiod_chip_close(chip);
        exit(1);
    }
    if ((relay2 = gpiod_line_request_output(chip, RELAY2_GPIO, "active-high")) == NULL) {
        fprintf(stderr, "Failed to request relay2 line\n");
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Initialize serial ports
    if ((serial1 = open(SERIAL_PORT1, O_RDWR | O_NOCTTY | O_NONBLOCK)) == -1) {
        fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT1);
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        exit(1);
    }
    if ((serial2 = open(SERIAL_PORT2, O_RDWR | O_NOCTTY | O_NONBLOCK)) == -1) {
        fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT2);
        close(serial1);
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        // Read from serial port 1
        bytes_read1 = read(serial1, code1, 6);
        if (bytes_read1 == -1) {
            if (errno == EAGAIN) {
                // No data available, try again
                continue;
            } else {
                fprintf(stderr, "Error reading from serial port %s: %s\n", SERIAL_PORT1, strerror(errno));
                break;
            }
        }
        code1[bytes_read1] = '\0';

        // Reset input buffer on non-digit character
        for (i = 0; i < bytes_read1; i++) {
            if (!isdigit(code1[i])) {
                memset(code1, 0, 7);
                break;
            }
        }

        // Read from serial port 2
        bytes_read2 = read(serial2, code2, 6);
        if (bytes_read2 == -1) {
            if (errno == EAGAIN) {
                // No data available, try again
                continue;
            } else {
                fprintf(stderr, "Error reading from serial port %s: %s\n", SERIAL_PORT2, strerror(errno));
                break;
            }
        }
        code2[bytes_read2] = '\0';

        // Reset input buffer on non-digit character
        for (i = 0; i < bytes_read2; i++) {
            if (!isdigit(code2[i])) {
                memset(code2, 0, 7);
                break;
            }
        }

        // Check if both codes match and match the expected code
        if (strcmp(code1, code2) == 0 && strcmp(code1, EXPECTED_CODE) == 0) {
            // Drive both relay GPIOs HIGH for 2 seconds
            gpiod_cset(RLAY1_GPIO, 1);
            gpiod_cset(RLAY2_GPIO, 1);
            usleep(2000000);
            gpiod_cset(RLAY1_GPIO, 0);
            gpiod_cset(RLAY2_GPIO, 0);
        }
    }

    // Clean up
    gpiod_line_release(relay1);
    gpiod_line_release(relay2);
    gpiod_chip_close(chip);
    close(serial1);
    close(serial2);
    return 0;
