#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define PIR_DEBOUNCE_TIME 10  // seconds
#define RELAY_ON_TIME 1000  // milliseconds

// Function to handle SIGINT and SIGTERM signals
void sigint_handler(int sig) {
    gpiod_close();
    syslog(LOG_INFO, "Received signal %d, shutting down.", sig);
    syslog(LOG_INFO, "Releasing GPIO lines.");
    gpiod_line_release(RELAY_PIN);
    gpiod_line_release(PIR_PIN);
    syslog(LOG_INFO, "Closing gpiod API.");
    gpiod_close();
    syslog(LOG_INFO, "Closing log.");
    closelog();
    syslog(LOG_INFO, "Exiting.");
    exit(0);
}

int main() {
    // Open the gpiod API
    gpiod_context *ctx = gpiod_context_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create gpiod context.");
        return 1;
    }

    // Open the chip
    gpiod_chip *chip = gpiod_chip_open(ctx, "gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open chip.");
        gpiod_context_free(ctx);
        return 1;
    }

    // Request the PIR and relay lines
    gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line.");
        gpiod_chip_close(chip);
        gpiod_context_free(ctx);
        return 1;
    }

    gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line.");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        gpiod_context_free(ctx);
        return 1;
    }

    // Initialize the syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGINT handler.");
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        gpiod_context_free(ctx);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler.");
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        gpiod_context_free(ctx);
        return 1;
    }

    // Initialize the relay
    gpiod_line_direction(pir_line, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_direction(relay_line, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_export(pir_line);
    gpiod_line_export(relay_line);

    // Main loop
    uint64_t last_motion_time = 0;
    while (1) {
        // Poll the PIR sensor
        gpiod_line_event *event = gpiod_line_event_read(pir_line);
        if (!event) {
            syslog(LOG_ERR, "Failed to read PIR event.");
            gpiod_line_release(pir_line);
            gpiod_line_release(relay_line);
            gpiod_chip_close(chip);
            gpiod_context_free(ctx);
            return 1;
        }

        if (event->value == GPIOD_LINE_EVENT_VALUE_HIGH) {
            // Motion detected
            uint64_t current_time = gpiod_line_event_get_timestamp(event);
            if (current_time - last_motion_time > PIR_DEBOUNCE_TIME * 1000000000) {
                // PIR signal has been HIGH for more than 10 seconds, trigger failsafe
                syslog(LOG_WARNING, "PIR signal has been HIGH for more than 10 seconds, triggering failsafe.");
                syslog(LOG_INFO, "De-energizing relay.");
                gpiod_line_direction(relay_line, GPIOD_LINE_DIRECTION_OUTPUT);
                gpiod_line_export(relay_line);
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_INFO, "Shutting down.");
                closelog();
                gpiod_line_release(pir_line);
                gpiod_line_release(relay_line);
                gpiod_chip_close(chip);
                gpiod_context_free(ctx);
                exit(0);
            }

            // Activate the relay
            syslog(LOG_INFO, "Activating relay.");
            gpiod_line_direction(relay_line, GPIOD_LINE_DIRECTION_OUTPUT);
            gpiod_line_export(relay_line);
            gpiod_line_set_value(relay_line, 1);
            syslog(LOG_INFO, "Relay on.");
            usleep(RELAY_ON_TIME * 1000);
            syslog(LOG_INFO, "De-energizing relay.");
            gpiod_line_direction(relay_line, GPIOD_LINE_DIRECTION_OUTPUT);
            gpiod_line_export(relay_line);
            gpiod_line_set_value(relay_line, 0);
            syslog(LOG_INFO, "Relay off.");
        }

        last_motion_time = gpiod_line_event_get_timestamp(event);
        gpiod_line_event_free(event);

        // Sleep for 50ms
        usleep(50000);
    }

    return 0;
}

