This code uses the `libgpiod` library to interact with the GPIO pins on the Raspberry Pi. It opens the GPIO chip, requests the PIR and relay lines, and sets up the syslog. It then enters a loop where it polls the PIR sensor every 50ms, and if motion is detected, it activates the relay for 1 second. If the PIR signal remains HIGH for more than 10 seconds, it triggers a failsafe that de-energizes the relay and shuts down the system. The code also handles SIGINT and SIGTERM signals to perform a clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

// Define the GPIO pin numbers for the relays
#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

// Define the duration of each relay activation and pause in seconds
#define DURATION 300
#define PAUSE 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the timer ID
#define TIMER_ID 0

// Define the volatile sig_atomic_t flag to check for interrupts
volatile sig_atomic_t interrupt_flag = 0;

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(gpiod_line_request_output("gpiochip0", RELAY1 + i, GPIOD_LINE_ACTIVE_LOW), 1);
    }

    // Release GPIO resources
    gpiod_chip_release(gpiod_chip_open("/dev/gpiochip0"));

    // Close syslog
    closelog();

    // Exit cleanly
    exit(0);
}

int main() {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    // Request the GPIO lines for the relays
    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_line_request_output("gpiochip0", RELAY1 + i, GPIOD_LINE_ACTIVE_LOW);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to request GPIO line %d", RELAY1 + i);
            gpiod_chip_release(chip);
            exit(1);
        }
    }

    // Initialize all relays to OFF (set HIGH)
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1);
    }

    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_PERROR, LOG_USER);

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        gpiod_chip_release(chip);
        exit(1);
    }

    // Initialize the timer
    struct itimerspec timer;
    timer.it_value.tv_sec = 60;
    timer.it_interval.tv_sec = 60;
    if (timerfd_create(CLOCK_REALTIME, 0) == -1) {
        syslog(LOG_ERR, "Failed to create timer");
        gpiod_chip_release(chip);
        exit(1);
    }
    if (timerfd_settime(TIMER_ID, 0, &timer, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set timer");
        gpiod_chip_release(chip);
        exit(1);
    }

    // Main loop
    while (!interrupt_flag) {
        // Wait for the timer to fire
        read(TIMER_ID, NULL, 0);

        // Get the current relay index
        int relay_index = (int) (time(NULL) % NUM_RELAYS);

        // Activate the current relay
        gpiod_line_set_value(lines[relay_index], 0);

        // Log the state change
        syslog(LOG_INFO, "Relay %d activated at %s", relay_index + 1, ctime(&time(NULL)));

        // Wait for the duration
        sleep(DURATION);

        // Deactivate the current relay
