#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/syscall.h>
#include <errno.h>

#define MPU6050_ADDRESS 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

#define BUFFER_SIZE 1024
#define SAMPLE_RATE_HZ 100

struct mpu6050_accel {
    int fd;
    int timer_fd;
    volatile int *buffer;
    int buffer_size;
    int buffer_head;
    int buffer_tail;
    bool running;
};

static void sigint_handler(int sig) {
    struct mpu6050_accel *mpu = (struct mpu6050_accel *)syscall(SYS_gettid);
    if (mpu != NULL) {
        mpu->running = false;
    }
}

static void read_accel(struct mpu6050_accel *mpu) {
    int ret;
    uint8_t data[6];
    ret = i2c_smbus_read_i2c_block_data(mpu->fd, ACCEL_XOUT_H, 6, data);
    if (ret < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return;
    }
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];
    mpu->buffer[mpu->buffer_head] = x;
    mpu->buffer[mpu->buffer_head + 1] = y;
    mpu->buffer[mpu->buffer_head + 2] = z;
    mpu->buffer_head = (mpu->buffer_head + 3) % mpu->buffer_size;
}

static void timer_handler(int timer_fd) {
    struct mpu6050_accel *mpu = (struct mpu6050_accel *)syscall(SYS_gettid);
    if (mpu != NULL && mpu->running) {
        read_accel(mpu);
        write(mpu->buffer_file, &mpu->buffer[mpu->buffer_head], sizeof(int16_t));
    }
}

int main() {
    struct mpu6050_accel mpu;
    mpu.buffer_size = BUFFER_SIZE;
    mpu.buffer = malloc(mpu.buffer_size * sizeof(int16_t));
    mpu.buffer_head = 0;
    mpu.buffer_tail = 0;
    mpu.running = true;

    mpu.fd = open("/dev/i2c-1", O_RDWR);
    if (mpu.fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(mpu.fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl");
        close(mpu.fd);
        return 1;
    }

    mpu.timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (mpu.timer_fd < 0) {
        perror("timerfd_create");
        close(mpu.fd);
        return 1;
    }

    struct itimerspec timer_spec;
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 10000000; // 10ms
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 10000000; // 10ms
    if (timerfd_settime(mpu.timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("timerfd_settime");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    mpu.buffer_file = open("/sys/kernel/mpu6050_accel/latest", O_RDWR | O_CREAT, 0644);
    if (mpu.buffer_file < 0) {
        perror("open");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    if (ftruncate(mpu.buffer_file, mpu.buffer_size * sizeof(int16_t)) < 0) {
        perror("ftruncate");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    struct mpu6050_accel *mpu_ptr = mmap(NULL, mpu.buffer_size * sizeof(int16_t), PROT_READ | PROT_WRITE, MAP_SHARED, mpu.buffer_file, 0);
    if (mpu_ptr == MAP_FAILED) {
        perror("mmap");
        close(mpu.timer_fd);
        close(mpu.fd);
        return 1;
    }

    mpu.buffer = mpu_ptr;

    while (mpu.running) {
        read(mpu.timer_fd, NULL, 0);
    }

    munmap(mpu_ptr, mpu.buffer_size * sizeof(int16_t));
    close(mpu.buffer_file);
    close(mpu.timer_fd);
    close(mpu.fd);
    free(mpu.buffer);
    return 0;
}

