#define LOG_FILE "alarm_log.txt"

bool relay_active = false;
struct gpiod_line *sound_line = NULL;
struct gpiod_line *relay_line = NULL;
struct gpiod_chip *chip = NULL;

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_active) {
            gpiod_line_set_value(relay_line, 0);
        }
        gpiod_chip_close(chip);
        gpiod_line_release(sound_line);
        gpiod_line_release(relay_line);
        exit(0);
    }
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_new("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_new");
        return 1;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_GPIO);
    if (sound_line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (relay_line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, 0) != 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(sound_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sound_line, 0) != 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(sound_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 100000000;  // 100 ms
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 100000000;  // 100 ms
    int timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("timerfd_create");
        gpiod_line_release(sound_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (timerfd_settime(timer_fd, 0, &timer, NULL) != 0) {
        perror("timerfd_settime");
        close(timer_fd);
        gpiod_line_release(sound_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct itimerspec remaining;
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = 0;
    while (1) {
        read(timer_fd, &remaining, sizeof(struct itimerspec));
        if (remaining.it_value.tv_sec > 0 || remaining.it_value.tv_nsec > 0) {
            continue;
        }

        if (gpiod_line_get_value(sound_line) == 1) {
            if (!relay_active) {
                relay_active = true;
                gpiod_line_set_value(relay_line, 1);
                log_event("Sound detected at ");
                struct timeval tv;
                gettimeofday(&tv, NULL);
                log_event(tv.tv_sec);
                log_event(tv.tv_usec);
                usleep(3000000);  // 3 seconds
                gpiod_line_set_value(relay_line, 0);
                relay_active = false;
            }
        }

        usleep(10000);  // 10 ms
    }

    close(timer_fd);
    gpiod_line_release(sound_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return 0;
}

