    } else {
        return 0.0;
    }
}

// Function to calculate the magnitude of a vector
float vector_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Function to handle the I2C communication with the MPU-6050
int mpu6050_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("read");
        return -1;
    }

    return 0;
}

// Function to read the angular velocity data from the MPU-6050
int mpu6050_read_angular_velocity(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    if (mpu6050_read(fd, 0x43, data, 6) < 0) {
        return -1;
    }

    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];

    *x = (*x * 131.0) / 32768.0;
    *y = (*y * 131.0) / 32768.0;
    *z = (*z * 131.0) / 32768.0;

    return 0;
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    printf("Caught SIGINT, shutting down...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Initialize the circular buffer
    buffer_init(&buffer);

    // Define the callback function
    Callback callback = (Callback)callback_function;

    // Register the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the angular velocity data from the MPU-6050
        float x, y, z;
        if (mpu6050_read_angular_velocity(i2c_fd, &x, &y, &z) < 0) {
            perror("mpu6050_read_angular_velocity");
            break;
        }

        // Calculate the magnitude of the angular velocity vector
        float magnitude = vector_magnitude(x, y, z);

        // Add the sample to the circular buffer
        buffer_add(&buffer, magnitude);

        // Check if the magnitude exceeds the threshold
        if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
            // Invoke the callback function
            callback(magnitude);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

// User-defined callback function
void callback_function(float magnitude) {
    printf("Angular velocity magnitude: %f degrees/second\n", magnitude);
}
