#define DEVIATION_THRESHOLD 10.0

// Structure to hold the compensated heading data
typedef struct {
    double heading;
    int index;
} HeadingData;

// Function to apply hard-iron compensation
double apply_hard_iron_compensation(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset) {
    return atan2(y - y_offset, x - x_offset);
}

// Function to read data from the HMC5883L magnetometer
int read_hmc5883l(int fd, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[2];
    int retries = 0;

    while (retries < 5) {
        if (i2c_read(fd, 0x03, buffer, 2) == 0) {
            *x = (buffer[0] << 8) | buffer[1];
            if (i2c_read(fd, 0x01, buffer, 2) == 0) {
                *y = (buffer[0] << 8) | buffer[1];
                if (i2c_read(fd, 0x05, buffer, 2) == 0) {
                    *z = (buffer[0] << 8) | buffer[1];
                    return 0;
                }
            }
        }
        retries++;
        usleep(10000);
    }
    return -1;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    gpio_write(GPIO_PIN, 0);
    gpio_cleanup();
    exit(0);
}

int main() {
    int fd;
    int gpio_fd;
    int16_t x, y, z;
    double heading;
    HeadingData buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int gpio_status;
    struct itimerval timer;
    struct sigaction sa;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pin as output
    gpio_status = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_status < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpio_cleanup();
        return 1;
    }

    // Set up I2C bus
    fd = i2cOpen(1, 0x1E);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpio_cleanup();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        i2cClose(fd);
        gpio_cleanup();
        return 1;
    }

    // Initialize timer
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = SAMPLE_INTERVAL;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = SAMPLE_INTERVAL;
    if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        i2cClose(fd);
        gpio_cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from HMC5883L
        if (read_hmc5883l(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read from HMC5883L: %s\n", strerror(errno));
            continue;
        }

        // Apply hard-iron compensation
        heading = apply_hard_iron_compensation(x, y, z, 100, -50);

        // Store compensated heading in buffer
        buffer[buffer_index].heading = heading;
        buffer[buffer_index].index = buffer_index;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Check if buffer is full
        if (buffer_index == 0) {
            // Calculate average heading
            double sum = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                sum += buffer[i].heading;
            }
            heading = sum / BUFFER_SIZE;

            // Check if heading deviates by more than 10 degrees from target
            if (abs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
                gpio_write(GPIO_PIN, 1);
            } else {
                gpio_write(GPIO_PIN, 0);
            }
        }

        // Sleep until next sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up on exit
    i2cClose(fd);
    gpio_cleanup();
    return 0;
}

void gpio_cleanup() {
    gpioTerminate();
}

