#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define LIGHT_SENSOR_ADDRESS 0x23
#define RELAY_RED 17
#define RELAY_GREEN 27
#define RELAY_BLUE 22
#define RELAY_THRESHOLD_RED 50
#define RELAY_THRESHOLD_GREEN 150
#define RELAY_THRESHOLD_BLUE 300

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    int relay_red = -1;
    int relay_green = -1;
    int relay_blue = -1;

    // Open I2C bus 1
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, LIGHT_SENSOR_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        goto cleanup;
    }

    // Set up relay pins as outputs
    relay_red = gpioOpen(RELAY_RED, 1);
    relay_green = gpioOpen(RELAY_GREEN, 1);
    relay_blue = gpioOpen(RELAY_BLUE, 1);
    if (relay_red == -1 || relay_green == -1 || relay_blue == -1) {
        perror("Failed to open relay pins");
        goto cleanup;
    }

    // Open log file
    if ((log_fd = open("lighting_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        // Read light level
        uint16_t light_level;
        if (i2c_smbus_write_byte(i2c_fd, 0x00) == -1) {
            perror("Failed to write to I2C bus");
            goto cleanup;
        }
        usleep(120 * 1000);
        if (i2c_smbus_read_byte_data(i2c_fd, 0x00) == -1) {
            perror("Failed to read from I2C bus");
            goto cleanup;
        }
        if (i2c_smbus_write_byte(i2c_fd, 0x01) == -1) {
            perror("Failed to write to I2C bus");
            goto cleanup;
        }
        usleep(120 * 1000);
        if (i2c_smbus_read_word_data(i2c_fd, 0x00) == -1) {
            perror("Failed to read from I2C bus");
            goto cleanup;
        }
        light_level = (uint16_t) i2c_smbus_read_word_data(i2c_fd, 0x00);

        // Calculate lux
        float lux = (float) light_level / 1.2;

        // Log data
        char buffer[64];
        time_t now = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(buffer, "%s %.2f %d %d %d %d\n", buffer, lux, gpioRead(RELAY_RED), gpioRead(RELAY_GREEN), gpioRead(RELAY_BLUE), relay_red, relay_green, relay_blue);
        if (write(log_fd, buffer, strlen(buffer)) == -1) {
            perror("Failed to write to log file");
            goto cleanup;
        }

        // Update relays
        if (lux < RELAY_THRESHOLD_RED) {
            gpioWrite(RELAY_RED, 1);
            gpioWrite(RELAY_GREEN, 0);
            gpioWrite(RELAY_BLUE, 0);
        } else if (lux < RELAY_THRESHOLD_GREEN) {
            gpioWrite(RELAY_RED, 0);
            gpioWrite(RELAY_GREEN, 1);
            gpioWrite(RELAY_BLUE, 0);
        } else if (lux < RELAY_THRESHOLD_BLUE) {
            gpioWrite(RELAY_RED, 0);
            gpioWrite(RELAY_GREEN, 0);
            gpioWrite(RELAY_BLUE, 1);
        } else {
            gpioWrite(RELAY_RED, 1);
            gpioWrite(RELAY_GREEN, 1);
            gpioWrite(RELAY_BLUE, 1);
        }

        // Sleep for 1 second
        usleep(1000 * 1000);
    }

cleanup:
    // Release resources
    if (relay_red != -1) {
        gpioTerminate();
        gpioClose(relay_red);
    }
    if (relay_green != -1) {
        gpioClose(relay_green);
    }
    if (relay_blue != -1) {
        gpioClose(relay_blue);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    return 0;
}

