        return 1;
    }
    if (motor_b_distance < MIN_DISTANCE || motor_b_distance > MAX_DISTANCE) {
        fprintf(stderr, "Motor B distance out of range: %d\n", motor_b_distance);
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up motor control pins
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 || gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 || gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up motor control pins\n");
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioPWM(MOTOR_A_IN2, 0) < 0 || gpioPWM(MOTOR_B_IN4, 0) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        gpioTerminate();
        return 1;
    }

    // Main control loop
    while (1) {
        // Read distance values
        int distance_a = motor_a_distance;
        int distance_b = motor_b_distance;

        // Calculate PWM duty cycle
        int duty_cycle_a = (distance_a < 50) ? (int)((double)(distance_a / 50) * MAX_SPEED) : MAX_SPEED;
        int duty_cycle_b = (distance_b < 50) ? (int)((double)(distance_b / 50) * MAX_SPEED) : MAX_SPEED;

        // Drive motors
        if (distance_a < 50 && distance_b < 50) {
            // Both motors forward
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_B_IN3, 1);
        } else if (distance_a >= 50 && distance_b >= 50) {
            // Both motors backward
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_B_IN3, 0);
        } else if (distance_a < 50 && distance_b >= 50) {
            // Motor A forward, Motor B backward
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_B_IN3, 0);
        } else {
            // Motor A backward, Motor B forward
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_B_IN3, 1);
        }

        // Set PWM duty cycle
        gpioPWM(MOTOR_A_IN2, duty_cycle_a);
        gpioPWM(MOTOR_B_IN4, duty_cycle_b);

        // Sleep
        usleep(CONTROL_LOOP_INTERVAL);
    }

    // Clean up GPIO
    gpioTerminate();

    return 0;
}
