        if (gpioRead(24) == 0 && gpioRead(23) == 0) {
            // Both buttons are still pressed, prevent re-triggering
            continue;
        }

        // Wait for next button press
        usleep(100000); // 100ms
    }

    // De-energize motor coils
    gpio_write(17, 0);
    gpio_write(18, 0);
    gpio_write(27, 0);
    gpio_write(22, 0);

    // Release GPIO resources
    gpio_cleanup();

    return 0;
