#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_TIME 1800
#define PWM_FREQ 100

void cleanup(int sig) {
    gpioSetMode(RELAY1, PI_INPUT);
    gpioSetMode(RELAY2, PI_INPUT);
    gpioSetMode(RELAY3, PI_INPUT);
    gpioSetMode(RELAY4, PI_INPUT);
    gpioTerminate();
    exit(0);
}

void fade(int relay, int on) {
    int duty_cycle = 0;
    if (on) {
        duty_cycle = 100;
    }
    gpioSetMode(relay, PI_OUTPUT);
    gpioPWM(relay, 0);
    for (int i = 0; i < FADE_TIME; i++) {
        gpioHardwarePWM(relay, PWM_FREQ, duty_cycle);
        usleep(1000000 / PWM_FREQ);
        if (on) {
            duty_cycle = (duty_cycle + 1) % 101;
        } else {
            duty_cycle = (duty_cycle - 1 + 101) % 101;
        }
    }
    gpioSetMode(relay, PI_OUTPUT);
    gpioWrite(relay, on);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(SCHEDULE_FILE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open schedule file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    char buffer[256];
    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        struct tm *time = localtime(&tv.tv_sec);
        char time_str[9];
        sprintf(time_str, "%02d:%02d:%02d", time->tm_hour, time->tm_min, time->tm_sec);
        char line[256];
        if (read(fd, line, 256) < 0) {
            fprintf(stderr, "Failed to read schedule file: %s\n", strerror(errno));
            close(fd);
            gpioTerminate();
            return 1;
        }
        line[strcspn(line, "\n")] = 0;
        if (strlen(line) == 0) {
            continue;
        }
        char *relay_str = strtok(line, ";");
        char *on_str = strtok(NULL, ";");
        int relay = atoi(relay_str);
        int on = (strcmp(on_str, "on") == 0);
        if (relay == RELAY1 || relay == RELAY2 || relay == RELAY3 || relay == RELAY4) {
            if (relay == RELAY1) {
                fade(RELAY1, on);
            } else if (relay == RELAY2) {
                fade(RELAY2, on);
            } else if (relay == RELAY3) {
                fade(RELAY3, on);
            } else if (relay == RELAY4) {
                fade(RELAY4, on);
            }
        } else {
            fprintf(stderr, "Invalid relay number: %d\n", relay);
        }
        usleep(1000000);
    }

    close(fd);
    gpioTerminate();
    return 0;
}

