volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int gpio = gpioInitialise();
    if (gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpioSetMode(gpio, TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate(gpio);
        return 1;
    }

    if (gpioSetMode(gpio, ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate(gpio);
        return 1;
    }

    if (gpioSetMode(gpio, BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate(gpio);
        return 1;
    }

    gpioPwmSetClock(gpio, 25000000); // 25 MHz clock

    signal(SIGINT, sigint_handler);

    int last_measurement_time = 0;
    while (running) {
        if (gpioRead(gpio, ECHO_PIN) == 1) {
            // Sensor is not connected or not working
            fprintf(stderr, "Error: HC-SR04 sensor not detected\n");
            break;
        }

        gpioPwmWrite(gpio, BUZZER_PIN, 0);
        gpioPwmWrite(gpio, TRIGGER_PIN, 1);
        usleep(10);
        gpioPwmWrite(gpio, TRIGGER_PIN, 0);

        int start_time = gpioGetTick();
        int echo_start_time = gpioGetTick();
        int echo_end_time = 0;
        while (gpioRead(gpio, ECHO_PIN) == 0) {
            echo_start_time = gpioGetTick();
        }
        while (gpioRead(gpio, ECHO_PIN) == 1) {
            echo_end_time = gpioGetTick();
        }

        if (echo_start_time == echo_end_time) {
            // Timeout
            fprintf(stderr, "Error: HC-SR04 sensor timed out\n");
            break;
        }

        int distance_cm = (echo_end_time - echo_start_time) * 34300 / 2;
        int frequency = 440 + (distance_cm * 10) / 1000;
        if (frequency < MIN_BUZZER_FREQ) {
            frequency = MIN_BUZZER_FREQ;
        } else if (frequency > MAX_BUZZER_FREQ) {
            frequency = MAX_BUZZER_FREQ;
        }

        gpioPwmWrite(gpio, BUZZER_PIN, frequency);

        int current_time = gpioGetTick();
        if (current_time - last_measurement_time < MEASUREMENT_INTERVAL_US) {
            usleep(MEASUREMENT_INTERVAL_US - (current_time - last_measurement_time));
        }
        last_measurement_time = current_time;

        if (gpioGetTick() - start_time > MAX_MEASUREMENTS * 1000000) {
            break;
        }
    }

    gpioPwmWrite(gpio, BUZZER_PIN, 0);
    gpioTerminate(gpio);
    return 0;
}
