#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define GYRO_SCALE 131.0
#define SAMPLE_INTERVAL 100000 // 100ms in microseconds

// Structure to hold the gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} GyroData;

// Function to read data from the gyroscope
int readGyroData(int fd, GyroData *data) {
    uint8_t reg = 0x43; // Register to read from
    uint8_t buffer[6];
    int bytes_read;

    // Read 6 bytes from the gyroscope
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }

    if (i2c_smbus_read_i2c_block_data(fd, reg, 6, buffer) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    // Convert the raw data to degrees per second
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]) * GYRO_SCALE;
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]) * GYRO_SCALE;
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]) * GYRO_SCALE;

    return 0;
}

// Function to handle signal interrupts
void signalHandler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Close the I2C file descriptor
        close(i2c_fd);
        exit(0);
    }
}

int main() {
    int i2c_fd;
    GyroData gyro_data;
    char filename[] = "gyro_log.txt";
    FILE *file;
    struct i2c_adapter *adapter;
    struct i2c_client *client;
    struct i2c_client_info client_info;
    struct i2c_msg msg;
    char buffer[256];

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Get the I2C adapter and client information
    adapter = i2c_get_adapter(i2c_fd);
    if (!adapter) {
        perror("i2c_get_adapter");
        close(i2c_fd);
        return 1;
    }

    client = i2c_get_client(adapter, MPU6050_ADDRESS);
    if (!client) {
        perror("i2c_get_client");
        i2c_put_adapter(adapter);
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    file = fopen(filename, "a");
    if (!file) {
        perror("fopen");
        i2c_put_client(client);
        i2c_put_adapter(adapter);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Read data from the gyroscope
        if (readGyroData(i2c_fd, &gyro_data) < 0) {
            perror("readGyroData");
            break;
        }

        // Append the data to the log file
        fprintf(file, "%lu %d %d %d\n", (unsigned long)time(NULL), gyro_data.x, gyro_data.y, gyro_data.z);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close the log file and I2C file descriptor
    fclose(file);
    close(i2c_fd);

    // Release I2C resources
    i2c_put_client(client);
    i2c_put_adapter(adapter);

    return 0;
}

