#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO17 17
#define LOG_FILE "vibration_events.log"
#define MAX_EVENTS 5

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int timeout = 1000;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    // Initialize GPIO
    gpiod_context *ctx;
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    gpiod_line_request(ctx, GPIO17, "rising", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_EVENT_BOTH);
    gpiod_line_request(ctx, GPIO17, "falling", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_EVENT_BOTH);

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_ctx_free(ctx);
        return 1;
    }

    // Initialize event buffer
    struct timeval last_event[MAX_EVENTS];
    memset(last_event, 0, sizeof(last_event));

    // Install signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler\n");
        close(log_fd);
        gpiod_ctx_free(ctx);
        return 1;
    }

    while (!exit_flag) {
        struct gpiod_line_event event;
        if (gpiod_line_event_read(ctx, GPIO17, &event, timeout) == -1) {
            if (errno == EAGAIN) {
                continue;
            } else {
                fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
                break;
            }
        }

        // Log event
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&event.timestamp));
        char log_line[64];
        sprintf(log_line, "%s %d\n", timestamp, event.value);
        if (write(log_fd, log_line, strlen(log_line)) == -1) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        }
        if (fsync(log_fd) == -1) {
            fprintf(stderr, "Failed to fsync log file: %s\n", strerror(errno));
        }

        // Update event buffer
        for (int i = 0; i < MAX_EVENTS - 1; i++) {
            last_event[i] = last_event[i + 1];
        }
        last_event[MAX_EVENTS - 1] = event;

        // Check for earthquake
        int high_count = 0;
        for (int i = 0; i < MAX_EVENTS; i++) {
            if (last_event[i].value == 1) {
                high_count++;
            }
        }
        if (high_count >= 3) {
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&event.timestamp));
            fprintf(stderr, "EARTHQUAKE ALERT at %s\n", timestamp);
        }
    }

    // Clean up
    close(log_fd);
    gpiod_line_release(ctx, GPIO17);
    gpiod_ctx_free(ctx);
    return 0;
}

