#include <errno.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_TIME 200000 // 200 ms
#define LOG_FILE "relay_log.json"

struct log_entry {
    char timestamp[32];
    char relay_state[4];
};

void log_entry(struct log_entry *entry) {
    char buffer[256];
    strftime(entry->timestamp, sizeof(entry->timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&entry->timestamp));
    sprintf(buffer, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}", entry->timestamp, entry->relay_state);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s\n", buffer);
    fclose(file);
}

void sigint_handler(int sig) {
    gpioWrite(RELAY_GPIO, 0);
    log_entry((struct log_entry){.relay_state = "OFF"});
    gpioCleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_GPIO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDnControl(TOUCH_GPIO, PI_PUD_DOWN) < 0) {
        perror("gpioSetPullUpDnControl");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    struct timeval last_touch;
    gettimeofday(&last_touch, NULL);
    while (1) {
        int level = gpioRead(TOUCH_GPIO);
        if (level == 1) {
            struct timeval now;
            gettimeofday(&now, NULL);
            if ((now.tv_sec - last_touch.tv_sec) * 1000000 + (now.tv_usec - last_touch.tv_usec) >= DEBOUNCE_TIME) {
                gpioWrite(RELAY_GPIO, 1);
                log_entry((struct log_entry){.relay_state = "ON"});
                gettimeofday(&last_touch, NULL);
            }
        } else {
            gpioWrite(RELAY_GPIO, 0);
            log_entry((struct log_entry){.relay_state = "OFF"});
            gettimeofday(&last_touch, NULL);
        }
        usleep(10000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

