#define RELAY1 17
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25
#define RELAY_COUNT 4
#define RELAY_ON 0
#define RELAY_OFF 1
#define LOG_FILE "irrigation_log.txt"

void sigint_handler(int sig) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(i + RELAY1, RELAY_OFF);
    }
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    for (int i = RELAY1; i <= RELAY4; i++) {
        if (gpioSetMode(i, PI_OUTPUT) == -1) {
            fprintf(stderr, "Failed to set mode for GPIO%d\n", i);
            gpioTerminate();
            exit(1);
        }
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        exit(1);
    }

    srand(time(NULL));

    while (1) {
        int moisture = rand() % 101;
        fprintf(stderr, "Soil moisture: %d%%\n", moisture);
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (moisture < 30) {
                gpioWrite(i + RELAY1, RELAY_ON);
                fprintf(log_file, "%s, Relay%d, %d%%\n", ctime(&time(NULL)), i + 1, moisture);
                fflush(log_file);
                sleep(5);
                gpioWrite(i + RELAY1, RELAY_OFF);
                sleep(1);
            }
        }
        sleep(10);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

