#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define VALVE_OPEN 1500
#define VALVE_CLOSE 500
#define NOZZLE_ANGLES 5
#define NOZZLE_DURATIONS 2
#define HOLD_DUR 5
#define BACKOFF 100000

volatile sig_atomic_t stop_servos = 0;
volatile sig_atomic_t stop_watering = 0;

void sig_handler(int sig) {
    stop_servos = 1;
    stop_watering = 1;
}

int retry(int (*func)(int, int), int gpio, int arg, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        int ret = func(gpio, arg);
        if (ret >= 0) {
            return ret;
        }
        if (errno == EIO) {
            retries++;
            usleep(BACKOFF);
        } else {
            return -1;
        }
    }
    return -1;
}

int main() {
    struct gpiod_line *valve_line, *nozzle_line;
    int moisture = 0;
    int angle = 0;
    int cycle = 0;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO
    valve_line = gpiod_cdev_open("/dev/gpiochip0", 0, 0);
    if (!valve_line) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    nozzle_line = gpiod_cdev_open("/dev/gpiochip0", 0, 0);
    if (!nozzle_line) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_line_release(valve_line);
        return 1;
    }

    gpiod_line_request_output(valve_line, VALVE_GPIO, 0);
    gpiod_line_request_output(nozzle_line, NOZZLE_GPIO, 0);

    // Simulate soil moisture
    while (!stop_watering) {
        moisture = (cycle % 5) * 20;
        cycle++;

        if (moisture < 50) {
            // Open valve
            int ret = retry(gpiod_line_set_value, valve_line, VALVE_GPIO, VALVE_OPEN, 3);
            if (ret < 0) {
                fprintf(stderr, "Failed to open valve\n");
                gpiod_line_release(valve_line);
                gpiod_line_release(nozzle_line);
                return 1;
            }

            // Sweep nozzle
            for (int i = 0; i < NOZZLE_ANGLES; i++) {
                int ret = retry(gpiod_line_set_value, nozzle_line, NOZZLE_GPIO, (i * 500) + 500, 3);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set nozzle angle %d\n", i);
                } else {
                    usleep(NOZZLE_DURATIONS * 1000000);
                }
            }

            // Hold spray
            usleep(HOLD_DUR * 1000000);

            // Close valve
            int ret = retry(gpiod_line_set_value, valve_line, VALVE_GPIO, VALVE_CLOSE, 3);
            if (ret < 0) {
                fprintf(stderr, "Warning: failed to close valve\n");
            }

            // Wait
            usleep(HOLD_DUR * 1000000);
        }

        // Wait for next cycle
        usleep(1000000);
    }

    // Stop servos
    gpiod_line_set_value(valve_line, VALVE_GPIO, 0);
    gpiod_line_set_value(nozzle_line, NOZZLE_GPIO, 0);

    // Release GPIO
    gpiod_line_release(valve_line);
    gpiod_line_release(nozzle_line);

    // Cleanup
    gpiod_cleanup();

    return 0;
}

