#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

// Define the GPIO pin numbers
#define LOCK_BUTTON_PIN 24
#define UNLOCK_BUTTON_PIN 23
#define STEPPER_IN1_PIN 4
#define STEPPER_IN2_PIN 17
#define STEPPER_IN3_PIN 27
#define STEPPER_IN4_PIN 22

// Define the number of steps for a full rotation
#define STEPS_PER_ROTATION 512

// Define the delay between steps in milliseconds
#define STEP_DELAY 3

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // De-energize the coils
    gpiod_line_set_value(STEPPER_IN1_PIN, 0);
    gpiod_line_set_value(STEPPER_IN2_PIN, 0);
    gpiod_line_set_value(STEPPER_IN3_PIN, 0);
    gpiod_line_set_value(STEPPER_IN4_PIN, 0);

    // Release the GPIO lines
    gpiod_line_release(STEPPER_IN1_PIN);
    gpiod_line_release(STEPPER_IN2_PIN);
    gpiod_line_release(STEPPER_IN3_PIN);
    gpiod_line_release(STEPPER_IN4_PIN);

    // Close the GPIO chip
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));

    // Exit the program
    exit(0);
}

int main() {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request the GPIO lines
    struct gpiod_line *lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON_PIN);
    struct gpiod_line *unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    struct gpiod_line *stepper_in1_line = gpiod_chip_get_line(chip, STEPPER_IN1_PIN);
    struct gpiod_line *stepper_in2_line = gpiod_chip_get_line(chip, STEPPER_IN2_PIN);
    struct gpiod_line *stepper_in3_line = gpiod_chip_get_line(chip, STEPPER_IN3_PIN);
    struct gpiod_line *stepper_in4_line = gpiod_chip_get_line(chip, STEPPER_IN4_PIN);

    // Set the direction of the GPIO lines
    gpiod_line_request_output(stepper_in1_line, "stepper_in1");
    gpiod_line_request_output(stepper_in2_line, "stepper_in2");
    gpiod_line_request_output(stepper_in3_line, "stepper_in3");
    gpiod_line_request_output(stepper_in4_line, "stepper_in4");

    // Enable the internal pull-up resistors for the button lines
    gpiod_line_request_input(lock_button_line, "lock_button");
    gpiod_line_request_input(unlock_button_line, "unlock_button");
    gpiod_line_set_active_low(lock_button_line, 1);
    gpiod_line_set_active_low(unlock_button_line, 1);

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of the buttons
        int lock_button_state = gpiod_line_get_value(lock_button_line);
        int unlock_button_state = gpiod_line_get_value(unlock_button_line);

        // Check if the LOCK button was pressed
        if (lock_button_state == 0) {
            // Rotate the motor 512 steps clockwise
            printf("Locking the door...\n");
            for (int i = 0; i < STEPS_PER_ROTATION; i++) {
                gpiod_line_set_value(stepper_in1_line, 1);
                gpiod_line_set_value(stepper_in2_line, 0);
                gpiod_line_set_value(stepper_in3_line, 1);
                gpiod_line_set_value(stepper_in4_line, 0);
                usleep(STEP_DELAY * 1000);
                gpiod_line_set_value(stepper_in1_line, 0);
                gpiod_line_set_value(stepper_in2_line, 1);
                gpiod_line_set_value(stepper_in3_line, 0);
                gpiod_line_set_value(stepper_in4_line, 1);
                usleep(STEP_DELAY * 1000);
            }
            gpiod_line_set_value(stepper_in1_line, 0);
            gpiod_line_set_value(stepper_in2_line, 0);
            gpiod_line_set_value(stepper_in3_line, 0);
            gpiod_line_set_value(stepper_in4_line, 0);
        }

        // Check if the UNLOCK button was pressed
        else if (unlock_button_state == 0) {
            // Rotate the motor 512 steps counter-clockwise
            printf("Unlocking the door...\n");
            for (int i = 0; i < STEPS_PER_ROTATION; i++) {
                gpiod_line_set_value(stepper_in1_line, 0);
                gpiod_line_set_value(stepper_in2_line, 1);
                gpiod_line_set_value(stepper_in3_line, 0);
                gpiod_line_set_value(stepper_in4_line, 1);
                usleep(STEP_DELAY * 1000);
                gpiod_line_set_value(stepper_in1_line, 1);
                gpiod_line_set_value(stepper_in2_line, 0);
                gpiod_line_set_value(stepper_in3_line, 1);
                gpiod_line_set_value(stepper_in4_line, 0);
                usleep(STEP_DELAY * 1000);
            }
            gpiod_line_set_value(stepper_in1_line, 0);
            gpiod_line_set_value(stepper_in2_line, 0);
            gpiod_line_set_value(stepper_in3_line, 0);
            gpiod_line_set_value(stepper_in4_line, 0);
        }

        // Sleep for 100ms to debounce the buttons
        usleep(100 * 1000);
    }

    // Release the GPIO lines
    gpiod_line_release(lock_button_line);
    gpiod_line_release(unlock_button_line);
    gpiod_line_release(stepper_in1_line);
    gpiod_line_release(stepper_in2_line);
    gpiod_line_release(stepper_in3_line);
    gpiod_line_release(stepper_in4_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

