    int gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialise GPIO driver\n");
        return 1;
    }

    if (gpioSetMode(gpio_fd, GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_TRIGGER);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(gpio_fd, GPIO_ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_ECHO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(gpio_fd, GPIO_ECHO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down control for GPIO%d\n", GPIO_ECHO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(gpio_fd, GPIO_ECHO, NULL) < 0) {
        fprintf(stderr, "Failed to disable interrupt for GPIO%d\n", GPIO_ECHO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioWrite(gpio_fd, GPIO_TRIGGER, 1);
        usleep(TRIGGER_PULSE_US * 1000);
        gpioWrite(gpio_fd, GPIO_TRIGGER, 0);

        int echo_fd = gpioEventFD(gpio_fd, GPIO_ECHO, PI_RISING_EDGE, ECHO_TIMEOUT_MS * 1000);
        if (echo_fd < 0) {
            fprintf(stderr, "Failed to wait for rising edge on GPIO%d\n", GPIO_ECHO);
            fprintf(log_file, "-1\n");
            continue;
        }

        int echo_fd2 = gpioEventFD(gpio_fd, GPIO_ECHO, PI_FALLING_EDGE, ECHO_TIMEOUT_MS * 1000);
        if (echo_fd2 < 0) {
            fprintf(stderr, "Failed to wait for falling edge on GPIO%d\n", GPIO_ECHO);
            fprintf(log_file, "-1\n");
            continue;
        }

        int64_t distance = gpioEventGetDistance(echo_fd, echo_fd2);
        if (distance < 0) {
            fprintf(stderr, "Failed to get distance\n");
            fprintf(log_file, "-1\n");
            continue;
        }

        fprintf(log_file, "%lld\n", distance);
        fclose(echo_fd);
        fclose(echo_fd2);

        usleep(LOG_INTERVAL * 1000);
    }

    return 0;
}

