int main() {
    // Initialize GPIO driver
    gpio = gpiod_chip_open("/dev/gpiochip0");
    if (gpio == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Export and request line for relay pin
    gpio_line = gpiod_chip_get_line(gpio, RELAY_PIN);
    if (gpio_line == NULL) {
        fprintf(stderr, "Failed to get line for pin %d\n", RELAY_PIN);
        gpiod_close(gpio);
        return 1;
    }

    // Request line as output
    if (gpiod_line_request_output(gpio_line, RELAY_PIN, "relay") != 0) {
        fprintf(stderr, "Failed to request line %d as output\n", RELAY_PIN);
        gpiod_line_release(gpio_line);
        gpiod_close(gpio);
        return 1;
    }

    // Initialize I2C interface
    i2c = gpiod_i2c_open("/dev/i2c-1");
    if (i2c == NULL) {
        fprintf(stderr, "Failed to open I2C interface\n");
        gpiod_line_release(gpio_line);
        gpiod_close(gpio);
        return 1;
    }

    // Initialize VL53L1X sensor
    if (gpiod_i2c_write(i2c, SENSOR_ADDRESS, 0x00, 0x00, 1) != 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        gpiod_i2c_close(i2c);
        gpiod_line_release(gpio_line);
        gpiod_close(gpio);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read distance from sensor
        uint16_t distance;
        if (gpiod_i2c_read(i2c, SENSOR_ADDRESS, 0x04, (uint8_t*)&distance, 2) != 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            gpiod_i2c_close(i2c);
            gpiod_line_release(gpio_line);
            gpiod_close(gpio);
            return 1;
        }

        // Convert distance to centimeters
        distance = (distance >> 4) * 100;

        // Print distance to stdout
        printf("Distance: %d cm\n", distance);

        // Drive relay based on distance
        if (distance <= 50) {
            gpiod_set_value(gpio, RELAY_PIN, 1);
        } else {
            gpiod_set_value(gpio, RELAY_PIN, 0);
        }

        // Poll every 100ms
        usleep(POLL_INTERVAL);
    }

    return 0;
}

