#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and device addresses
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68

// Define the signal handlers
void sigint_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    close(i2c_fd);
    exit(0);
}

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set the I2C bus speed to 400 kHz
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C bus speed");
        close(i2c_fd);
        exit(1);
    }

    // Define the I2C register addresses
    uint8_t reg_addr_xg = 0x43;
    uint8_t reg_addr_yg = 0x45;
    uint8_t reg_addr_zg = 0x47;

    // Define the number of samples to read
    int num_samples = 100;

    // Main loop
    while (1) {
        // Read the x, y, and z axis rotation rates
        uint16_t xg, yg, zg;
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr_xg) < 0) {
            perror("Failed to read x-axis rotation rate");
            break;
        }
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr_yg) < 0) {
            perror("Failed to read y-axis rotation rate");
            break;
        }
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr_zg) < 0) {
            perror("Failed to read z-axis rotation rate");
            break;
        }

        // Convert the raw data to 16-bit integers
        xg = (i2c_smbus_read_byte_data(i2c_fd, reg_addr_xg) << 8) | i2c_smbus_read_byte_data(i2c_fd, reg_addr_xg);
        yg = (i2c_smbus_read_byte_data(i2c_fd, reg_addr_yg) << 8) | i2c_smbus_read_byte_data(i2c_fd, reg_addr_yg);
        zg = (i2c_smbus_read_byte_data(i2c_fd, reg_addr_zg) << 8) | i2c_smbus_read_byte_data(i2c_fd, reg_addr_zg);

        // Print the rotation rates
        printf("x-axis rotation rate: %d rad/s\n", xg);
        printf("y-axis rotation rate: %d rad/s\n", yg);
        printf("z-axis rotation rate: %d rad/s\n", zg);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

