#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define RELAY1 17
#define RELAY2 18
#define RELAY3 27
#define RELAY4 22

#define RELAY_LINES { RELAY1, RELAY2, RELAY3, RELAY4 }

static void sigint_handler(int sig) {
    gpiod_close(gpiod_chip);
    for (size_t i = 0; i < 4; i++) {
        gpiod_line_release(RELAY_LINES[i]);
    }
    exit(0);
}

int main() {
    struct itimerspec timer;
    struct sigaction sa;
    struct tm start_time;
    char filename[256];
    FILE *log_file;
    int chip;
    int result;

    // Install SIGINT/SIGTERM handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines as outputs with active-low semantics
    for (size_t i = 0; i < 4; i++) {
        result = gpiod_line_request_output(chip, RELAY_LINES[i], 0, GPIOD_LINE_ACTIVE_LOW);
        if (result < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", RELAY_LINES[i], strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Set all lines HIGH (inactive)
    for (size_t i = 0; i < 4; i++) {
        result = gpiod_line_set_value(RELAY_LINES[i], 1);
        if (result < 0) {
            fprintf(stderr, "Failed to set line %d HIGH: %s\n", RELAY_LINES[i], strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Open log file
    strftime(filename, sizeof(filename), "watering_log.txt", NULL);
    log_file = fopen(filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up timer
    timer.it_interval.tv_sec = 60;
    timer.it_value.tv_sec = 0;
    result = timerfd_create(CLOCK_REALTIME, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for timer expiration
        result = read(timerfd, &timer, sizeof(timer));
        if (result < 0) {
            fprintf(stderr, "Failed to read timer: %s\n", strerror(errno));
            break;
        }

        // Log start time of full cycle
        time_t now = time(NULL);
        localtime_r(&now, &start_time);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n", start_time.tm_year + 1900, start_time.tm_mon + 1, start_time.tm_mday, start_time.tm_hour, start_time.tm_min, start_time.tm_sec);

        // Activate each relay in turn for 5 seconds
        for (size_t i = 0; i < 4; i++) {
            // Set line LOW (active)
            result = gpiod_line_set_value(RELAY_LINES[i], 0);
            if (result < 0) {
                fprintf(stderr, "Failed to set line %d LOW: %s\n", RELAY_LINES[i], strerror(errno));
                break;
            }

            // Wait for 5 seconds
            usleep(5000000);

            // Set line HIGH (inactive)
            result = gpiod_line_set_value(RELAY_LINES[i], 1);
            if (result < 0) {
                fprintf(stderr, "Failed to set line %d HIGH: %s\n", RELAY_LINES[i], strerror(errno));
                break;
            }
        }

        // Check if any error occurred
        if (result < 0) {
            break;
        }

        // Reset timer
        timer.it_value.tv_sec = 60;
    }

    // Close log file
    fclose(log_file);

    // Release all GPIO lines
    for (size_t i = 0; i < 4; i++) {
        gpiod_line_release(RELAY_LINES[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

