#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

#define LOG_FILE "smart_lighting.log"
#define RELAY_COUNT 4
#define RELAY_PINS {17, 18, 27, 22}
#define RELAY_DUTY_MAX 255
#define RELAY_DUTY_MIN 0
#define DUTY_STEP 1
#define DURATION 30 * 60  // 30 minutes in seconds

// Function to handle signal interrupts
void sigint_handler(int sig) {
    fprintf(stderr, "Received signal %d, exiting...\n", sig);
    gpioTerminate();
    exit(0);
}

// Function to log events to file
void log_event(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, message);
    fclose(file);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Set up relay pins as output
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioMode(RELAY_PINS[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set pin %d mode to output\n", RELAY_PINS[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Initialize PWM
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioPWM(RELAY_PINS[i], 0) < 0) {
            fprintf(stderr, "Failed to initialize PWM on pin %d\n", RELAY_PINS[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Log initial state
    log_event("Smart lighting started");

    // Gradually increase duty cycle over 30 minutes
    for (int duty = RELAY_DUTY_MIN; duty <= RELAY_DUTY_MAX; duty += DUTY_STEP) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (gpioPWM(RELAY_PINS[i], duty) < 0) {
                fprintf(stderr, "Failed to set PWM on pin %d to %d\n", RELAY_PINS[i], duty);
                gpioTerminate();
                return 1;
            }
        }
        log_event("Duty cycle set to %d", duty);
        sleep(1);
    }

    // Log final state
    log_event("Smart lighting finished");

    // Clean up
    gpioTerminate();
    return 0;
}

