#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_LSB_FIRST 0
#define CHIP_SELECT_LINE "/dev/gpiochip0"
#define CHIP_SELECT_OFFSET 8
#define CHIP_SELECT_PIN GPIO8
#define RETRY_COUNT 3
#define LOG_FILE "gyro_log.txt"

int spi_fd;
int chip_select_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_data(double x_rate, double y_rate, double z_rate) {
    char timestamp[32];
    time_t now;
    struct tm *now_tm;
    char buffer[128];

    time(&now);
    now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%N", now_tm);

    sprintf(buffer, "%s,%f,%f,%f\n", timestamp, x_rate, y_rate, z_rate);
    if (fprintf(stderr, "%s", buffer) < 0) {
        log_error("Error writing to log file");
    }
    if (fprintf(stdout, "%s", buffer) < 0) {
        log_error("Error writing to log file");
    }
    if (fflush(stdout) < 0) {
        log_error("Error flushing log file");
    }
}

int main() {
    int retry_count = 0;
    int retry_max = RETRY_COUNT;
    int ret;
    uint8_t buffer[6];
    struct spi_ioc_transfer transfer;
    struct timespec sleep_time;
    struct sigaction sa;
    int log_fd;

    // Open the SPI device
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        log_error("Error opening SPI device");
        return 1;
    }

    // Configure the SPI device
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        log_error("Error configuring SPI mode");
        close(spi_fd);
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        log_error("Error configuring SPI speed");
        close(spi_fd);
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        log_error("Error configuring SPI bits per word");
        close(spi_fd);
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST);
    if (ret < 0) {
        log_error("Error configuring SPI LSB first");
        close(spi_fd);
        return 1;
    }

    // Open the GPIO device
    chip = gpiod_chip_open(CHIP_SELECT_LINE);
    if (!chip) {
        log_error("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Open the chip select line
    line = gpiod_chip_get_line(chip, CHIP_SELECT_OFFSET);
    if (!line) {
        log_error("Error opening chip select line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Configure the chip select line as an output
    ret = gpiod_line_request_output(line, "chip_select", 0);
    if (ret < 0) {
        log_error("Error configuring chip select line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        log_error("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Set up signal handling
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Assert the chip select line low
        gpiod_line_set_value(line, 0);

        // Prepare the SPI transfer
        memset(buffer, 0, sizeof(buffer));
        transfer.tx_buf = (unsigned long)buffer;
        transfer.rx_buf = (unsigned long)buffer;
        transfer.len = sizeof(buffer);
        transfer.speed_hz = SPI_SPEED;
        transfer.delay_usecs = 0;
        transfer.cs_change = 1;

        // Perform the SPI transfer
        for (retry_count = 0; retry_count < retry_max; retry_count++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
            if (ret >= 0) {
                break;
            }
            if (errno != EINTR) {
                log_error("Error performing SPI transfer");
                break;
            }
        }
        if (retry_count == retry_max) {
            log_error("Persistent SPI failure");
            break;
        }

        // De-assert the chip select line high
        gpiod_line_set_value(line, 1);

        // Read the data
        double x_rate = (double)buffer[0] << 8 | buffer[1];
        double y_rate = (double)buffer[2] << 8 | buffer[3];
        double z_rate = (double)buffer[4] << 8 | buffer[5];

        // Log the data
        log_data(x_rate, y_rate, z_rate);

        // Sleep for 10ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    close(log_fd);

    return 0;
}

