int head = 0, tail = 0;
bool running = true;
gpio_fd_t spi_fd;
gpio_fd_t led_fd;

// Function to handle SIGINT
void sigint_handler(int sig) {
    running = false;
}

// Function to blink the LED
void blink_led() {
    gpio_write(led_fd, 1, 1);
    usleep(500000);
    gpio_write(led_fd, 1, 0);
    usleep(500000);
}

// Function to read from the SPI device
int read_spi(int fd, uint8_t *buf, int len) {
    int ret = gpiod_spi_transfer(fd, buf, len, 0, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "SPI read error: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return ret;
}

// Function to write to the SPI device
int write_spi(int fd, uint8_t *buf, int len) {
    int ret = gpiod_spi_transfer(fd, buf, len, 0, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "SPI write error: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return ret;
}

int main() {
    // Initialize GPIO
    led_fd = gpio_open(LED_PIN, GPIO_MODE_OUTPUT);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d: %s\n", LED_PIN, gpiod_strerror(led_fd));
        return 1;
    }

    // Initialize SPI
    spi_fd = gpiod_spi_new(SPI_BUS, SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", gpiod_strerror(spi_fd));
        gpio_close(led_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the circular buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i].timestamp = 0;
        buffer[i].x = 0;
        buffer[i].y = 0;
        buffer[i].z = 0;
    }

    // Set up the SPI device
    uint8_t config[] = {0x6B}; // PWR_MGMT_1 register
    write_spi(spi_fd, config, 1);

    while (running) {
        // Read from the SPI device
        uint8_t data[14];
        int ret = read_spi(spi_fd, data, 14);
        if (ret < 0) {
            continue;
        }

        // Check for zero or invalid data
        if (data[0] == 0 || data[1] == 0 || data[2] == 0 || data[3] == 0 || data[4] == 0 || data[5] == 0 || data[6] == 0 || data[7] == 0 || data[8] == 0 || data[9] == 0 || data[10] == 0 || data[11] == 0 || data[12] == 0 || data[13] == 0) {
            continue;
        }

        // Extract the data
        float x = (data[0] << 8) | data[1];
        float y = (data[2] << 8) | data[3];
        float z = (data[4] << 8) | data[5];

        // Store the data in the circular buffer
        buffer[head].timestamp = getnanosec();
        buffer[head].x = x / 131.0;
        buffer[head].y = y / 131.0;
        buffer[head].z = z / 131.0;
        head = (head + 1) % BUFFER_SIZE;

        // Check for threshold exceeded
        if (x > THRESHOLD || x < -THRESHOLD || y > THRESHOLD || y < -THRESHOLD || z > THRESHOLD || z < -THRESHOLD) {
            blink_led();
        }

        // Print the data
        if (head == tail) {
            printf("%llu,%f,%f,%f\n", buffer[0].timestamp, buffer[0].x, buffer[0].y, buffer[0].z);
        } else {
            for (int i = 0; i < BUFFER_SIZE; i++) {
                if (i == head) {
                    break;
                }
                printf("%llu,%f,%f,%f\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
            }
            printf("%llu,%f,%f,%f\n", buffer[head].timestamp, buffer[head].x, buffer[head].y, buffer[head].z);
        }

        // Wait for the next sample
        usleep(100000);
    }

    // Release resources
    gpiod_spi_close(spi_fd);
    gpio_close(led_fd);

    // Print the entire buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%llu,%f,%f,%f\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }

    return 0;
}
```

This code uses the `pigpio` library to interact with the GPIO and SPI interfaces on the Raspberry Pi. It initializes the SPI device and sets up a signal handler for SIGINT. The main loop reads data from the SPI device, stores it in a circular buffer, and checks for threshold exceeded. If the threshold is exceeded, it blinks the LED. The data is printed to the console in CSV format. On exit, it releases the resources and prints the entire buffer.

