#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x38
#define GPIO_LED "/sys/class/gpio/gpio17/value"
#define LOG_FILE "biometric_log.txt"
#define MAX_LOG_LINE 256
#define MAX_ATTEMPTS 3
#define DELAY 10

// Function to handle signal to close resources and exit
void signal_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    system("echo 0 > " GPIO_LED);
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }

    // Open GPIO17
    system("echo 17 > /sys/class/gpio/export");
    system("echo out > /sys/class/gpio/gpio17/direction");

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            // Read ambient light and proximity values
            uint16_t ambient_light, proximity;
            if (i2c_smbus_read_word_data(i2c_fd, 0x00, &ambient_light) < 0) {
                perror("Failed to read ambient light");
                continue;
            }
            if (i2c_smbus_read_word_data(i2c_fd, 0x02, &proximity) < 0) {
                perror("Failed to read proximity");
                continue;
            }

            // Check proximity value
            if (proximity > 100) {
                system("echo 1 > " GPIO_LED);
            } else {
                system("echo 0 > " GPIO_LED);
            }

            // Format log line
            char log_line[MAX_LOG_LINE];
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            strftime(log_line, MAX_LOG_LINE, "%Y-%m-%d %H:%M:%S,AmbientLight:%04x,Proximity:%04x", time_info, ambient_light, proximity);
            write(log_fd, log_line, strlen(log_line));

            // Sleep
            usleep(100000);
            break;
        }
    }

    return 0;
}

