    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            // Read ambient light and proximity values
            uint16_t ambient_light, proximity;
            if (i2c_smbus_read_word_data(i2c_fd, 0x00, &ambient_light) < 0) {
                perror("Failed to read ambient light");
                continue;
            }
            if (i2c_smbus_read_word_data(i2c_fd, 0x02, &proximity) < 0) {
                perror("Failed to read proximity");
                continue;
            }

            // Check proximity value
            if (proximity > 100) {
                system("echo 1 > " GPIO_LED);
            } else {
                system("echo 0 > " GPIO_LED);
            }

            // Format log line
            char log_line[MAX_LOG_LINE];
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            strftime(log_line, MAX_LOG_LINE, "%Y-%m-%d %H:%M:%S,AmbientLight:%04x,Proximity:%04x", time_info, ambient_light, proximity);
            write(log_fd, log_line, strlen(log_line));

            // Sleep
            usleep(100000);
            break;
        }
    }

    return 0;
}
