#define BUFFER_SIZE 100
#define BUFFER_SIZE_MASK (BUFFER_SIZE - 1)
#define THRESHOLD 20.0
#define LED_PIN 17
#define CE_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9

struct buffer_entry {
    double timestamp;
    double x_rate;
};

struct buffer {
    struct buffer_entry entries[BUFFER_SIZE];
    int head;
    int tail;
    pthread_mutex_t mutex;
};

struct buffer buffer;

void init_buffer() {
    pthread_mutex_init(&buffer.mutex, NULL);
    buffer.head = 0;
    buffer.tail = 0;
}

void add_to_buffer(struct buffer_entry entry) {
    pthread_mutex_lock(&buffer.mutex);
    buffer.entries[buffer.head] = entry;
    buffer.head = (buffer.head + 1) & BUFFER_SIZE_MASK;
    pthread_mutex_unlock(&buffer.mutex);
}

void* read_gyro(void* arg) {
