    if (ret < 0) {
        perror("gpiod_line_config");
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(ce_line);
        gpiod_chip_close(fd);
        exit(1);
    }

    mosi_config.mode = GPIOD_LINE_ACTIVE_HIGH;
    mosi_config.edge = GPIOD_LINE_EDGE_NONE;
