    if (ret < 0) {
        perror("gpiod_line_config");
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(ce_line);
        gpiod_chip_close(fd);
        exit(1);
    }

    miso_config.mode = GPIOD_LINE_ACTIVE_HIGH;
    miso_config.edge = GPIOD_LINE_EDGE_NONE;
    ret = gpiod_line_config(miso_line, &miso_config);
    if (ret < 0) {
        perror("gpiod_line_config");
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(ce_line);
        gpiod_chip_close(fd);
        exit(1);
    }

    ret = gpiod_chip_set_cs(ce_line, 1);
    if (ret < 0) {
        perror("gpiod_chip_set_cs");
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(ce_line);
        gpiod_chip_close(fd);
        exit(1);
    }

    while (1) {
        ret = gpiod_chip_set_cs(ce_line, 0);
        if (ret < 0) {
            perror("gpiod_chip_set_cs");
            gpiod_line_release(miso_line);
            gpiod_line_release(mosi_line);
            gpiod_line_release(sclk_line);
            gpiod_line_release(ce_line);
            gpiod_chip_close(fd);
            exit(1);
        }

        data[0] = 0x80; // Set MSB to 1 for read
        ret = gpiod_spi_transfer(fd, data, 1, data, 2, 1);
        if (ret < 0) {
            perror("gpiod_spi_transfer");
            gpiod_line_release(miso_line);
            gpiod_line_release(mosi_line);
            gpiod_line_release(sclk_line);
            gpiod_line_release(ce_line);
            gpiod_chip_close(fd);
            exit(1);
        }

        ret = gpiod_spi_transfer(fd, NULL, 0, data, 2, 1);
        if (ret < 0) {
            perror("gpiod_spi_transfer");
            gpiod_line_release(miso_line);
            gpiod_line_release(mosi_line);
            gpiod_line_release(sclk_line);
            gpiod_line_release(ce_line);
            gpiod_chip_close(fd);
            exit(1);
        }

        x_rate = (data[0] << 8) | data[1];
        x_rate /= 32768.0;

        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        entry.timestamp = timestamp.tv_sec + (timestamp.tv_nsec / 1e9);
        entry.x_rate = x_rate;

        add_to_buffer(entry);

        if (x_rate > THRESHOLD) {
            gpio_write(LED_PIN, 1);
        } else {
            gpio_write(LED_PIN, 0);
        }

        usleep(100000);
    }

    gpiod_line_release(miso_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(ce_line);
    gpiod_chip_close(fd);
}

void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/spidev0.0"));
    gpio_write(LED_PIN, 0);
    gpiod_driver_close();
    exit(0);
}

int main() {
    int ret;
    struct gpiod_driver* driver;

    driver = gpiod_driver_open();
    if (!driver) {
        perror("gpiod_driver_open");
        exit(1);
    }

    ret = gpiod_driver_register(driver);
    if (ret < 0) {
        perror("gpiod_driver_register");
        gpiod_driver_close(driver);
        exit(1);
    }

    init_buffer();

    gpio_set_mode(LED_PIN, GPIO_MODE_OUTPUT);
    gpio_write(LED_PIN, 0);

    pthread_t thread;
    pthread_create(&thread, NULL, read_gyro, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

