            gpiod_chip_close(fd);
            exit(1);
        }

        x_rate = (data[0] << 8) | data[1];
        x_rate /= 32768.0;

        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        entry.timestamp = timestamp.tv_sec + (timestamp.tv_nsec / 1e9);
        entry.x_rate = x_rate;

        add_to_buffer(entry);

        if (x_rate > THRESHOLD) {
            gpio_write(LED_PIN, 1);
        } else {
            gpio_write(LED_PIN, 0);
        }

        usleep(100000);
    }

    gpiod_line_release(miso_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(ce_line);
    gpiod_chip_close(fd);
}

void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/spidev0.0"));
    gpio_write(LED_PIN, 0);
    gpiod_driver_close();
    exit(0);
}

int main() {
    int ret;
    struct gpiod_driver* driver;

    driver = gpiod_driver_open();
    if (!driver) {
        perror("gpiod_driver_open");
        exit(1);
    }

    ret = gpiod_driver_register(driver);
    if (ret < 0) {
        perror("gpiod_driver_register");
        gpiod_driver_close(driver);
        exit(1);
    }

    init_buffer();

    gpio_set_mode(LED_PIN, GPIO_MODE_OUTPUT);
    gpio_write(LED_PIN, 0);

    pthread_t thread;
    pthread_create(&thread, NULL, read_gyro, NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}
```

This code uses the `gpiod` library to interact with the Raspberry Pi's GPIO and SPI interfaces. It initializes the SPI interface, sets up the GPIO pins, and starts a thread to continuously read the gyroscope data. The thread reads the data from the gyroscope, timestamps it, and stores it in a circular buffer. It also checks if the measured rate exceeds the threshold and turns the LED on or off accordingly. The main thread waits for a SIGINT or SIGTERM signal to exit the program, which closes the SPI interface, turns off the LED, and releases all resources.

