            for (j = 0; j < PWM_RANGE; j++) {
                pwm18 = j;
                gpioPWM(gpio18, pwm18);
                usleep(1000000 / PWM_FREQ);
            }
            printf("GPIO18 faded to 0%%\n");
        }

        // Fade GPIO27
        if (i % (duration / 3) == (duration / 3) * 2) {
