                gpioPWM(gpio27, pwm27);
                usleep(1000000 / PWM_FREQ);
            }
            printf("GPIO27 faded to 0%%\n");
        }

        // Turn off all lamps
        if (i == duration - 1) {
            gpioPWM(gpio17, 0);
            gpioPWM(gpio18, 0);
            gpioPWM(gpio27, 0);
            printf("All lamps turned off\n");
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
