#define TOUCH_CONTROLLER_SIZE 0x20
#define TOUCH_CONTROLLER_TOUCH_STATUS 0x02
#define TOUCH_CONTROLLER_TOUCH_DEBOUNCE 100000 // 100 ms

// Function to log an error with a timestamp
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "%s - %s\n", timestamp, message);
    syslog(LOG_ERR, "%s - %s", timestamp, message);
}

// Function to initialize the GPIO pin
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return -1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        log_error("Failed to set GPIO initial value");
        gpioTerminate();
        return -1;
    }
    return 0;
}

// Function to initialize the I2C interface
int init_i2c() {
    if (i2cOpen(1, TOUCH_CONTROLLER_ADDRESS, NULL) < 0) {
        log_error("Failed to open I2C interface");
        return -1;
    }
    return 0;
}

// Function to read the touch status from the MPR121 controller
int read_touch_status() {
    uint8_t data[1];
    if (i2cWriteReg(1, TOUCH_CONTROLLER_ADDRESS, TOUCH_CONTROLLER_TOUCH_STATUS, 0) < 0) {
        log_error("Failed to write to I2C register");
        return -1;
    }
    if (i2cReadReg(1, TOUCH_CONTROLLER_ADDRESS, TOUCH_CONTROLLER_TOUCH_STATUS, data, 1) < 0) {
        log_error("Failed to read from I2C register");
        return -1;
    }
    return data[0];
}

// Function to debounce a touch event
bool debounce_touch_event(uint8_t touch_status, uint32_t last_touch_time) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    uint32_t current_time = tv.tv_sec * 1000 + tv.tv_usec / 1000;
    if (current_time - last_touch_time > TOUCH_CONTROLLER_TOUCH_DEBOUNCE) {
        return true;
    }
    return false;
}

int main() {
    // Initialize the GPIO pin
    if (init_gpio() < 0) {
        exit(1);
    }

    // Initialize the I2C interface
    if (init_i2c() < 0) {
        gpioTerminate();
        exit(1);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(1);
        gpioTerminate();
        exit(1);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    uint32_t last_touch_time = 0;
    while (1) {
        // Read the touch status
        uint8_t touch_status = read_touch_status();
        if (touch_status < 0) {
            log_error("Failed to read touch status");
            break;
        }

        // Check if electrode 0 is touched
        if (touch_status & (1 << 0)) {
            // Debounce the touch event
            if (debounce_touch_event(touch_status, last_touch_time)) {
                // Toggle the relay
                if (gpioRead(RELAY_PIN) == 0) {
                    gpioWrite(RELAY_PIN, 1);
                } else {
                    gpioWrite(RELAY_PIN, 0);
                }
                last_touch_time = 0;
            }
        } else {
            last_touch_time = 0;
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close the log file
    fclose(log_file);

    // Close the I2C interface
    i2cClose(1);

    // Release the GPIO pin
    gpioTerminate();

    return 0;
}
