#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_SOLENOID1 17
#define GPIO_SOLENOID2 27
#define DISPENSE_INTERVAL 1000
#define DISPENSE_DURATION 500

static bool solenoid1_active = false;
static bool solenoid2_active = false;

static void sigint_handler(int sig) {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise GPIO library\n");
        exit(1);
    }

    gpioWrite(GPIO_SOLENOID1, 0);
    gpioWrite(GPIO_SOLENOID2, 0);

    gpioTerminate();
    exit(0);
}

static void log_event(const char *timestamp, int solenoid1, int solenoid2, int duration) {
    FILE *file = fopen("dispense_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open dispense log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s, GPIO%d, GPIO%d, %d\n", timestamp, solenoid1, solenoid2, duration);
    fclose(file);
}

int main() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise GPIO library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(GPIO_SOLENOID1, PI_OUTPUT);
    gpioSetMode(GPIO_SOLENOID2, PI_OUTPUT);

    while (1) {
        struct timeval start, end;
        gettimeofday(&start, NULL);

        gpioWrite(GPIO_SOLENOID1, 1);
        solenoid1_active = true;
        usleep(DISPENSE_DURATION * 1000);

        gettimeofday(&end, NULL);
        int duration = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec / 1000);
        log_event(gettimeofday_to_string(), GPIO_SOLENOID1, GPIO_SOLENOID2, duration);

        gpioWrite(GPIO_SOLENOID1, 0);
        solenoid1_active = false;

        gpioWrite(GPIO_SOLENOID2, 1);
        solenoid2_active = true;
        usleep(DISPENSE_DURATION * 1000);

        gettimeofday(&end, NULL);
        duration = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec / 1000);
        log_event(gettimeofday_to_string(), GPIO_SOLENOID2, GPIO_SOLENOID1, duration);

        gpioWrite(GPIO_SOLENOID2, 0);
        solenoid2_active = false;

        usleep((DISPENSE_INTERVAL - DISPENSE_DURATION * 2) * 1000);
    }

    gpioTerminate();
    return 0;
}

char *gettimeofday_to_string() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buffer[20];
    sprintf(buffer, "%ld.%06ld", tv.tv_sec, tv.tv_usec);
    return strdup(buffer);
}

