#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO22 22
#define GPIO23 23
#define GPIO24 24
#define GPIO25 25
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define LOG_FILE "balance_log.txt"
#define OBSTACLE_AVOIDANCE_DISTANCE 20.0
#define OBSTACLE_AVOIDANCE_SPEED 0.5

// PID controller parameters
#define KP 0.1
#define KI 0.0
#define KD 0.0

// PID controller state
double error_prev = 0.0;
double integral = 0.0;
double derivative = 0.0;

// Motor speeds
int motor_a_speed = 0;
int motor_b_speed = 0;

// Log file handle
FILE *log_file = NULL;

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Cleanly stop the motors
    gpiod_cset(GPIO17, 0);
    gpiod_cset(GPIO18, 0);
    gpiod_cset(GPIO22, 0);
    gpiod_cset(GPIO23, 0);
    gpiod_pwm_set(GPIO24, 0);
    gpiod_pwm_set(GPIO25, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the driver library
    gpiod_cleanup();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the driver library
    if (gpiod_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize the driver library");
        return 1;
    }

    // Set up the GPIO pins
    if (gpiod_line_request_output(GPIO17, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO17");
        gpiod_cleanup();
        return 1;
    }
    if (gpiod_line_request_output(GPIO18, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO18");
        gpiod_line_release(GPIO17);
        gpiod_cleanup();
        return 1;
    }
    if (gpiod_line_request_output(GPIO22, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO22");
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO18);
        gpiod_cleanup();
        return 1;
    }
    if (gpiod_line_request_output(GPIO23, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO23");
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO18);
        gpiod_line_release(GPIO22);
        gpiod_cleanup();
        return 1;
    }
    if (gpiod_pwm_request(GPIO24, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO24");
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO18);
        gpiod_line_release(GPIO22);
        gpiod_line_release(GPIO23);
        gpiod_cleanup();
        return 1;
    }
    if (gpiod_pwm_request(GPIO25, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO25");
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO18);
        gpiod_line_release(GPIO22);
        gpiod_line_release(GPIO23);
        gpiod_pwm_release(GPIO24);
        gpiod_cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpiod_pwm_release(GPIO24);
        gpiod_pwm_release(GPIO25);
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO18);
        gpiod_line_release(GPIO22);
        gpiod_line_release(GPIO23);
        gpiod_cleanup();
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Simulate the tilt error and distance
        double tilt_error = (double)rand() / RAND_MAX * 20.0 - 10.0;
        double distance = (double)rand() / RAND_MAX * 398.0 + 2.0;

        // PID control loop
        double error = tilt_error;
        double derivative = error - error_prev;
        integral += error * 0.01;
        double output = KP * error + KI * integral + KD * derivative;
        error_prev = error;

        // Clamp the output to the valid range
        output = fmax(-PWM_RANGE, fmin(output, PWM_RANGE));

        // Calculate the motor speeds
        motor_a_speed = (int)output;
        motor_b_speed = -motor_a_speed;

        // Check for obstacle avoidance
        if (distance < OBSTACLE_AVOIDANCE_DISTANCE) {
            motor_a_speed = (int)(output * OBSTACLE_AVOIDANCE_SPEED);
            motor_b_speed = (int)(output * OBSTACLE_AVOIDANCE_SPEED);
        }

        // Clamp the motor speeds to the valid range
        motor_a_speed = fmax(-PWM_RANGE, fmin(motor_a_speed, PWM_RANGE));
        motor_b_speed = fmax(-PWM_RANGE, fmin(motor_b_speed, PWM_RANGE));

        // Log the data
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update the motor speeds
        gpiod_pwm_set(GPIO24, motor_a_speed);
        gpiod_pwm_set(GPIO25, motor_b_speed);

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanly stop the motors
    gpiod_cset(GPIO17, 0);
    gpiod_cset(GPIO18, 0);
    gpiod_cset(GPIO22, 0);
    gpiod_cset(GPIO23, 0);
    gpiod_pwm_set(GPIO24, 0);
    gpiod_pwm_set(GPIO25, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the driver library
    gpiod_cleanup();

    return 0;
}

