// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Release GPIO resources
    gpioTerminate();
    exit(sig);
}

int main() {
    // Initialize GPIO driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up GPIO17 as an output for the relay
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO4 as an input for the TTP223 sensor
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set up internal pull-down for GPIO4
    if (gpioSetPullUpDnControl(4, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down for GPIO4\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of GPIO4
        int state = gpioRead(4);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO4\n");
            break;
        }

        // Check if a touch is detected
        if (state == 1) {
            // Toggle the relay
            if (gpioWrite(17, 1) < 0) {
                fprintf(stderr, "Failed to toggle relay\n");
                break;
            }

            // Apply debounce delay
            usleep(50000);
        }

        // Sleep for a short period to avoid busy-waiting
        usleep(10000);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

