        snd_pcm_sw_params_malloc(&sw_params);
        if ((err = snd_pcm_sw_params_current(handle, sw_params)) < 0) {
            fprintf(stderr, "Error: cannot get current sw_params: %s\n", snd_strerror(err));
            snd_pcm_sw_params_free(sw_params);
            snd_pcm_hw_params_free(hw_params);
            snd_pcm_close(handle);
            return 1;
        }

        if ((err = snd_pcm_sw_params_set_start_threshold(handle, sw_params, 0)) < 0) {
            fprintf(stderr, "Error setting start threshold: %s\n", snd_strerror(err));
            snd_pcm_sw_params_free(sw_params);
            snd_pcm_hw_params_free(hw_params);
            snd_pcm_close(handle);
            return 1;
        }

        if ((err = snd_pcm_sw_params_set_stop_threshold(handle, sw_params, 0)) < 0) {
            fprintf(stderr, "Error setting stop threshold: %s\n", snd_strerror(err));
            snd_pcm_sw_params_free(sw_params);
            snd_pcm_hw_params_free(hw_params);
            snd_pcm_close(handle);
            return 1;
        }

        if ((err = snd_pcm_sw_params(handle, sw_params)) < 0) {
            fprintf(stderr, "Error setting software parameters: %s\n", snd_strerror(err));
            snd_pcm_sw_params_free(sw_params);
            snd_pcm_hw_params_free(hw_params);
            snd_pcm_close(handle);
            return 1;
        }

        snd_pcm_sw_params_free(sw_params);

        if ((err = snd_pcm_prepare(handle)) < 0) {
            fprintf(stderr, "Error preparing ALSA device: %s\n", snd_strerror(err));
            snd_pcm_close(handle);
            return 1;
        }

        signal(SIGINT, sigint_handler);
        signal(SIGTERM, sigterm_handler);

        while (1) {
            if ((err = snd_pcm_readi(handle, NULL, period_size)) < 0) {
                if (err == -EPIPE) {
                    if ((err = snd_pcm_prepare(handle)) < 0) {
                        fprintf(stderr, "Error recovering from buffer overrun: %s\n", snd_strerror(err));
                    }
                } else if (err == -ESTRPIPE) {
                    if ((err = snd_pcm_resume(handle)) < 0) {
                        fprintf(stderr, "Error recovering from suspended state: %s\n", snd_strerror(err));
                    }
                } else {
                    fprintf(stderr, "Error reading from ALSA device: %s\n", snd_strerror(err));
                }
            } else {
                int16_t *buffer = malloc(period_size * sizeof(int16_t));
                if (!buffer) {
                    fprintf(stderr, "Error allocating memory for buffer\n");
                    break;
                }

                if ((err = snd_pcm_readi(handle, buffer, period_size)) < 0) {
                    free(buffer);
                    fprintf(stderr, "Error reading from ALSA device: %s\n", snd_strerror(err));
                    break;
                }

                int sum = 0;
                for (int i = 0; i < period_size; i++) {
                    sum += (int32_t)buffer[i] * buffer[i];
                }

                double amplitude = sqrt((double)sum / period_size);
                amplitude *= sensitivity;

                int red = (int)((amplitude * 255) / 255);
                int green = (int)((amplitude * 255) / 255);
                int blue = (int)((amplitude * 255) / 255);

                gpioWrite(LED_RED, red);
                gpioWrite(LED_GREEN, green);
                gpioWrite(LED_BLUE, blue);

                free(buffer);
            }

            usleep(10000);
        }

        snd_pcm_close(handle);
    } else {
        int i;
        for (i = 0; i < 1000000; i++) {
            int16_t sample = (int16_t)(sin(2 * M_PI * 440 * i / SAMPLE_RATE) * 32767);
            int sum = 0;
            for (int j = 0; j < PERIOD_SIZE; j++) {
                sum += (int32_t)sample * sample;
            }

            double amplitude = sqrt((double)sum / PERIOD_SIZE);
            amplitude *= sensitivity;

            int red = (int)((amplitude * 255) / 255);
            int green = (int)((amplitude * 255) / 255);
            int blue = (int)((amplitude * 255) / 255);

            gpioWrite(LED_RED, red);
            gpioWrite(LED_GREEN, green);
            gpioWrite(LED_BLUE, blue);

            usleep(10000);
        }
    }

    cleanup();

    return 0;
}
