int main() {
    int fd;
    int ret;
    struct timeval tv;
    struct tm *tm;
    char buffer[256];
    char *line;
    int c, r, g, b;
    FILE *f;

    // Register SIGINT and SIGTERM handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the I2C bus
    if ((fd = gpioOpen(1, 1)) == -1) {
        perror("gpioOpen");
        return 1;
    }

