            fprintf(stderr, "i2cReadReg16 failed\n");
            c = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_RDATAL, &r)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            r = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_RDATAH, &r)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            r = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_GDATAL, &g)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            g = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_GDATAH, &g)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            g = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_BDATAL, &b)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            b = 0;
        }
        if ((ret = i2cReadReg16(fd, TCS34725_I2C_ADDRESS, TCS34725_REG_BDATAH, &b)) == -1) {
            fprintf(stderr, "i2cReadReg16 failed\n");
            b = 0;
        }

        // Convert the sensor values to 16-bit integers
        c = (c << 8) | r;
        r = (r << 8) | g;
        g = (g << 8) | b;
        b = (b << 8) | 0;

        // Write the data to the CSV file
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(f, "%s,%d,%d,%d,%d\n", buffer, c, r, g, b);
    }

cleanup:
    if (f != NULL) {
        fclose(f);
    }
    if (fd != -1) {
        gpioClose(fd);
    }
    return 0;
}

