#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23
#define SUNRISE 3600 // 1 hour in seconds
#define DAYTIME 21600 // 6 hours in seconds
#define SUNSET 3600 // 1 hour in seconds
#define NIGHTTIME 43200 // 12 hours in seconds
#define DUTY_CYCLE_MAX 100 // 100% duty cycle
#define DUTY_CYCLE_MIN 0 // 0% duty cycle
#define DUTY_CYCLE_INCREMENT 1 // 1% duty cycle increment

volatile int running = 1;

void signal_handler(int sig) {
    gpio_write(RELAY1, 0);
    gpio_write(RELAY2, 0);
    gpio_write(RELAY3, 0);
    gpio_write(RELAY4, 0);
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_set_mode(RELAY1, PI_OUTPUT);
    gpio_set_mode(RELAY2, PI_OUTPUT);
    gpio_set_mode(RELAY3, PI_OUTPUT);
    gpio_set_mode(RELAY4, PI_OUTPUT);

    int duty_cycle = DUTY_CYCLE_MIN;
    int phase = 0;
    int time = 0;

    while (running) {
        switch (phase) {
            case 0: // sunrise
                if (time < SUNRISE) {
                    gpio_write(RELAY1, 1);
                    gpio_write(RELAY2, 1);
                    gpio_write(RELAY3, 1);
                    gpio_write(RELAY4, 1);
                    duty_cycle += DUTY_CYCLE_INCREMENT;
                    if (duty_cycle > DUTY_CYCLE_MAX) {
                        duty_cycle = DUTY_CYCLE_MAX;
                    }
                    gpio_set_PWM_dutycycle(RELAY1, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY2, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY3, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY4, duty_cycle);
                    time++;
                } else {
                    phase = 1;
                    time = 0;
                }
                break;
            case 1: // daytime
                if (time < DAYTIME) {
                    gpio_write(RELAY1, 0);
                    gpio_write(RELAY2, 0);
                    gpio_write(RELAY3, 0);
                    gpio_write(RELAY4, 0);
                    time++;
                } else {
                    phase = 2;
                    time = 0;
                }
                break;
            case 2: // sunset
                if (time < SUNSET) {
                    gpio_write(RELAY1, 1);
                    gpio_write(RELAY2, 1);
                    gpio_write(RELAY3, 1);
                    gpio_write(RELAY4, 1);
                    duty_cycle -= DUTY_CYCLE_INCREMENT;
                    if (duty_cycle < DUTY_CYCLE_MIN) {
                        duty_cycle = DUTY_CYCLE_MIN;
                    }
                    gpio_set_PWM_dutycycle(RELAY1, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY2, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY3, duty_cycle);
                    gpio_set_PWM_dutycycle(RELAY4, duty_cycle);
                    time++;
                } else {
                    phase = 3;
                    time = 0;
                }
                break;
            case 3: // nighttime
                if (time < NIGHTTIME) {
                    gpio_write(RELAY1, 0);
                    gpio_write(RELAY2, 0);
                    gpio_write(RELAY3, 0);
                    gpio_write(RELAY4, 0);
                    time++;
                } else {
                    phase = 0;
                    time = 0;
                    duty_cycle = DUTY_CYCLE_MIN;
                }
                break;
        }

        usleep(100000); // 100ms sleep
    }

    gpioTerminate();
    return 0;
}

