#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDRESS 0x1D
#define GPIO_ALARM 27
#define DELAY 500000  // 0.5 seconds in microseconds
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define FREE_FALL_THRESHOLD 0.2  // 0.2 g

// Structure to hold the ADXL345 data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} adxl345_data_t;

// Function to read data from the ADXL345
int read_adxl345(int fd, adxl345_data_t *data) {
    uint8_t reg = 0x32;  // Data register
    uint8_t buf[6];
    int ret;

    // Read 6 bytes from the data register
    ret = i2c_smbus_read_i2c_block_data(fd, ADXL345_ADDRESS, reg, buf, 6);
    if (ret < 0) {
        fprintf(stderr, "Error reading from ADXL345: %s\n", strerror(errno));
        return -1;
    }

    // Convert the data to 16-bit integers
    data->x = (buf[1] << 8) | buf[0];
    data->y = (buf[3] << 8) | buf[2];
    data->z = (buf[5] << 8) | buf[4];

    return 0;
}

// Function to check if the device is in free fall
bool is_free_fall(adxl345_data_t *data) {
    return (abs(data->x) < (FREE_FALL_THRESHOLD * 1024) && abs(data->y) < (FREE_FALL_THRESHOLD * 1024) && abs(data->z) < (FREE_FALL_THRESHOLD * 1024));
}

// Function to log a free fall event
void log_free_fall(const char *filename, adxl345_data_t *data) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x / 1024.0, data->y / 1024.0, data->z / 1024.0);
    fclose(file);
}

// Signal handler to clean up on exit
void sigint_handler(int sig) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        return;
    }

    // Set the alarm GPIO low
    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        return;
    }

    char buf[10];
    sprintf(buf, "%d", GPIO_ALARM);
    write(gpio_fd, buf, strlen(buf));
    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio%d/value", GPIO_ALARM, O_WRONLY);
    if (gpio_fd < 0) {
        return;
    }

    write(gpio_fd, "0", 1);
    close(gpio_fd);

    // Close the I2C handle
    close(fd);

    // Shut down the I2C driver
    ioctl(fd, I2C_SLAVE_FORCE, 0);
    close(fd);

    exit(0);
}

int main() {
    // Open the I2C bus
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE_FORCE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Export the GPIO pin
    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error exporting GPIO pin: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    char buf[10];
    sprintf(buf, "%d", GPIO_ALARM);
    write(gpio_fd, buf, strlen(buf));
    close(gpio_fd);

    // Set the GPIO direction
    gpio_fd = open("/sys/class/gpio/gpio%d/direction", GPIO_ALARM, O_WRONLY);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error setting GPIO direction: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    write(gpio_fd, "out", 4);
    close(gpio_fd);

    // Install the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    adxl345_data_t data;
    struct timeval last_free_fall;
    gettimeofday(&last_free_fall, NULL);
    while (1) {
        // Read data from the ADXL345
        if (read_adxl345(fd, &data) < 0) {
            continue;
        }

        // Check if the device is in free fall
        if (is_free_fall(&data)) {
            // Check if this is the second reading in a row
            struct timeval now;
            gettimeofday(&now, NULL);
            if (now.tv_sec - last_free_fall.tv_sec >= DELAY / 1000000) {
                // Log the free fall event
                log_free_fall("freefall.log", &data);

                // Set the alarm GPIO high
                gpio_fd = open("/sys/class/gpio/gpio%d/value", GPIO_ALARM, O_WRONLY);
                if (gpio_fd < 0) {
                    continue;
                }

                write(gpio_fd, "1", 1);
                close(gpio_fd);

                // Wait for 5 seconds
                usleep(5000000);
                gpio_fd = open("/sys/class/gpio/gpio%d/value", GPIO_ALARM, O_WRONLY);
                if (gpio_fd < 0) {
                    continue;
                }

                write(gpio_fd, "0", 1);
                close(gpio_fd);
            }

            // Update the last free fall timestamp
            last_free_fall = now;
        }

        // Wait for the next poll interval
        struct timeval now;
        gettimeofday(&now, NULL);
        struct timeval next_poll;
        next_poll.tv_sec = now.tv_sec + POLL_INTERVAL / 1000000;
        next_poll.tv_usec = now.tv_usec + POLL_INTERVAL % 1000000;
        select(0, NULL, NULL, NULL, &next_poll);
    }

    return 0;
}

