    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    adxl345_data_t data;
    struct timeval last_free_fall;
    gettimeofday(&last_free_fall, NULL);
    while (1) {
        // Read data from the ADXL345
        if (read_adxl345(fd, &data) < 0) {
            continue;
        }

        // Check if the device is in free fall
        if (is_free_fall(&data)) {
            // Check if this is the second reading in a row
            struct timeval now;
            gettimeofday(&now, NULL);
            if (now.tv_sec - last_free_fall.tv_sec >= DELAY / 1000000) {
                // Log the free fall event
                log_free_fall("freefall.log", &data);

                // Set the alarm GPIO high
                gpio_fd = open("/sys/class/gpio/gpio%d/value", GPIO_ALARM, O_WRONLY);
                if (gpio_fd < 0) {
                    continue;
                }

                write(gpio_fd, "1", 1);
                close(gpio_fd);

                // Wait for 5 seconds
                usleep(5000000);
                gpio_fd = open("/sys/class/gpio/gpio%d/value", GPIO_ALARM, O_WRONLY);
                if (gpio_fd < 0) {
                    continue;
                }

                write(gpio_fd, "0", 1);
                close(gpio_fd);
            }

            // Update the last free fall timestamp
            last_free_fall = now;
        }

        // Wait for the next poll interval
        struct timeval now;
        gettimeofday(&now, NULL);
        struct timeval next_poll;
        next_poll.tv_sec = now.tv_sec + POLL_INTERVAL / 1000000;
        next_poll.tv_usec = now.tv_usec + POLL_INTERVAL % 1000000;
        select(0, NULL, NULL, NULL, &next_poll);
    }

    return 0;
