#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x18
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define BUZZER_GPIO 17
#define BUZZER_DUTY_CYCLE 50
#define BUZZER_ON_TIME 1000

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Release GPIO resources
    gpioTerminate();
    // Release I2C resources
    close(i2c_fd);
    exit(0);
}

int main(int argc, char **argv) {
    // Parse command-line arguments
    float freeFallThreshold = FREE_FALL_THRESHOLD;
    float impactThreshold = IMPACT_THRESHOLD;
    if (argc > 1) {
        freeFallThreshold = atof(argv[1]);
    }
    if (argc > 2) {
        impactThreshold = atof(argv[2]);
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize I2C
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    int retry = 0;
    while (retry < 3) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            if (errno == EBUSY) {
                retry++;
                usleep(100000);
            } else {
                fprintf(stderr, "Failed to initialize LIS3DH\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
        } else {
            break;
        }
    }

    // Set LIS3DH to 16-bit mode
    uint8_t reg = 0x0F;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2A, reg) < 0) {
        fprintf(stderr, "Failed to set LIS3DH mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set LIS3DH to normal mode
    reg = 0x00;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2E, reg) < 0) {
        fprintf(stderr, "Failed to set LIS3DH mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set LIS3DH to 100 Hz sampling rate
    reg = 0x10;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x1C, reg) < 0) {
        fprintf(stderr, "Failed to set LIS3DH sampling rate\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read LIS3DH data
        uint8_t data[6];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x29, 6, data) < 0) {
            fprintf(stderr, "Failed to read LIS3DH data\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate acceleration magnitude
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z) / 16384.0f;

        // Detect free-fall
        if (magnitude < freeFallThreshold) {
            // Detect impact
            if (magnitude > impactThreshold) {
                // Activate buzzer
                gpioWrite(BUZZER_GPIO, 1);
                usleep(BUZZER_ON_TIME * 1000);
                gpioWrite(BUZZER_GPIO, 0);
            }
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

