#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define RELAY_GPIO 18
#define LISTEN_PORT 5000
#define LOG_FILE "relay_log.txt"

void sigint_handler(int sig) {
    gpiod_close();
    close(sock);
    fclose(log_file);
    gpiod_exit();
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main() {
    int sock, new_sock;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[256];
    FILE *log_file;
    int relay_state = 0;
    struct gpiod_line *relay_line;
    struct gpiod_line_request req;

    // Initialize GPIO
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return 1;
    }

    relay_line = gpiod_line_request_byname(NULL, "gpio", RELAY_GPIO, GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_REQUEST_OUTPUT);
    if (!relay_line) {
        perror("gpiod_line_request_byname");
        gpiod_exit();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(relay_line);
        gpiod_exit();
        return 1;
    }

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        fclose(log_file);
        gpiod_line_release(relay_line);
        gpiod_exit();
        return 1;
    }

    // Set up server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(LISTEN_PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind socket
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(sock);
        fclose(log_file);
        gpiod_line_release(relay_line);
        gpiod_exit();
        return 1;
    }

    // Listen for connections
    if (listen(sock, 3) < 0) {
        perror("listen");
        close(sock);
        fclose(log_file);
        gpiod_line_release(relay_line);
        gpiod_exit();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Accept connection
        new_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (new_sock < 0) {
            perror("accept");
            continue;
        }

        // Read from client
        if (read(new_sock, buffer, 256) < 0) {
            perror("read");
            close(new_sock);
            continue;
        }

        // Parse command
        char *cmd = strtok(buffer, " \t\r\n");
        if (strcasecmp(cmd, "on") == 0) {
            // Turn relay on
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("gpiod_line_set_value");
            } else {
                fprintf(log_file, "Relay turned on at %s\n", ctime(&time(NULL)));
            }
            relay_state = 1;
        } else if (strcasecmp(cmd, "off") == 0) {
            // Turn relay off
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("gpiod_line_set_value");
            } else {
                fprintf(log_file, "Relay turned off at %s\n", ctime(&time(NULL)));
            }
            relay_state = 0;
        } else {
            // Invalid command
            fprintf(log_file, "Invalid command '%s' at %s\n", cmd, ctime(&time(NULL)));
        }

        // Close connection
        close(new_sock);
    }

    // Close socket and log file
    close(sock);
    fclose(log_file);

    // Release GPIO
    gpiod_line_release(relay_line);
    gpiod_exit();

    return 0;
}

