#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS_SENSOR1 0x5A
#define I2C_ADDRESS_SENSOR2 0x5B
#define GPIO_RELAY 18
#define POLLING_INTERVAL 100
#define FLOW_LOG_FILE "flow_log.txt"

// CRC-8 polynomial
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) ^ (crc >> 1);
        crc &= 0x0F;
    }
    return crc;
}

// Function to handle signal interrupts
void sigint_handler(int sig) {
    gpio_write(GPIO_RELAY, 0);
    i2c_close(I2C_HANDLE_SENSOR1);
    i2c_close(I2C_HANDLE_SENSOR2);
    pigpio_cleanup();
    printf("Shutdown initiated\n");
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    I2C_HANDLE_SENSOR1 = i2cOpen(I2C_BUS, I2C_ADDRESS_SENSOR1, 0);
    if (I2C_HANDLE_SENSOR1 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    I2C_HANDLE_SENSOR2 = i2cOpen(I2C_BUS, I2C_ADDRESS_SENSOR2, 0);
    if (I2C_HANDLE_SENSOR2 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 for sensor 2\n");
        i2cClose(I2C_HANDLE_SENSOR1);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 18 as output
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO 18\n");
        i2cClose(I2C_HANDLE_SENSOR1);
        i2cClose(I2C_HANDLE_SENSOR2);
        gpioTerminate();
        return 1;
    }

    // Start measurement on both sensors
    uint8_t start_measurement[] = {0x00, 0x01};
    if (i2cWrite(I2C_HANDLE_SENSOR1, start_measurement, 2, 0) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1\n");
        i2cClose(I2C_HANDLE_SENSOR1);
        i2cClose(I2C_HANDLE_SENSOR2);
        gpioTerminate();
        return 1;
    }

    if (i2cWrite(I2C_HANDLE_SENSOR2, start_measurement, 2, 0) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2\n");
        i2cClose(I2C_HANDLE_SENSOR1);
        i2cClose(I2C_HANDLE_SENSOR2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from both sensors
        uint8_t data1[3];
        if (i2cRead(I2C_HANDLE_SENSOR1, data1, 3, 0) < 0 || data1[0] == 0xFF) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue;
        }

        uint8_t data2[3];
        if (i2cRead(I2C_HANDLE_SENSOR2, data2, 3, 0) < 0 || data2[0] == 0xFF) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue;
        }

        // Validate CRC-8
        if (crc8(data1, 2) != data1[2] || crc8(data2, 2) != data2[2]) {
            fprintf(stderr, "CRC-8 validation failed\n");
            continue;
        }

        // Calculate flow rates
        float flow_rate1 = (data1[0] << 8) | data1[1];
        float flow_rate2 = (data2[0] << 8) | data2[1];

        // Log flow rates
        FILE *file = fopen(FLOW_LOG_FILE, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open flow log file\n");
            continue;
        }
        fprintf(file, "%lu %f %f\n", getmicros() / 1000, flow_rate1, flow_rate2);
        fflush(file);
        fclose(file);

        // Control relay
        if (flow_rate1 < 5.0 && flow_rate2 < 5.0) {
            gpioWrite(GPIO_RELAY, 1);
        } else {
            gpioWrite(GPIO_RELAY, 0);
        }

        // Sleep
        usleep(POLLING_INTERVAL * 1000);
    }

    // Cleanup
    gpioTerminate();
    i2cClose(I2C_HANDLE_SENSOR1);
    i2cClose(I2C_HANDLE_SENSOR2);
    pigpio_cleanup();
    return 0;
}

