    if (i2cWrite(I2C_HANDLE_SENSOR2, start_measurement, 2, 0) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2\n");
        i2cClose(I2C_HANDLE_SENSOR1);
        i2cClose(I2C_HANDLE_SENSOR2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from both sensors
        uint8_t data1[3];
        if (i2cRead(I2C_HANDLE_SENSOR1, data1, 3, 0) < 0 || data1[0] == 0xFF) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue;
        }

        uint8_t data2[3];
        if (i2cRead(I2C_HANDLE_SENSOR2, data2, 3, 0) < 0 || data2[0] == 0xFF) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue;
        }

        // Validate CRC-8
        if (crc8(data1, 2) != data1[2] || crc8(data2, 2) != data2[2]) {
            fprintf(stderr, "CRC-8 validation failed\n");
            continue;
        }

        // Calculate flow rates
        float flow_rate1 = (data1[0] << 8) | data1[1];
        float flow_rate2 = (data2[0] << 8) | data2[1];

        // Log flow rates
        FILE *file = fopen(FLOW_LOG_FILE, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open flow log file\n");
            continue;
        }
        fprintf(file, "%lu %f %f\n", getmicros() / 1000, flow_rate1, flow_rate2);
        fflush(file);
        fclose(file);

        // Control relay
        if (flow_rate1 < 5.0 && flow_rate2 < 5.0) {
            gpioWrite(GPIO_RELAY, 1);
        } else {
            gpioWrite(GPIO_RELAY, 0);
        }

        // Sleep
        usleep(POLLING_INTERVAL * 1000);
    }

    // Cleanup
    gpioTerminate();
    i2cClose(I2C_HANDLE_SENSOR1);
    i2cClose(I2C_HANDLE_SENSOR2);
    pigpio_cleanup();
    return 0;
}
