    motor_running = true;
    usleep(MOTOR_CLOSE_WINDOW_DURATION_S * 1000000);
    if (gpiod_line_set_value(GPIO_MOTOR_ENA, 0) < 0) {
        syslog(LOG_ERR, "Failed to set motor enable low");
        return;
    }
