#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pin numbers
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define the pulse widths for lock and unlock
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Stop the servo by sending a pulse width of 0
    if (gpiod_cset(SERVO_PIN, 0) != 0) {
        perror("gpiod_cset");
        exit(EXIT_FAILURE);
    }

    // Call the API one final time to release the servo
    if (gpiod_call(SERVO_PIN, 0, 0) != 0) {
        perror("gpiod_call");
        exit(EXIT_FAILURE);
    }

    // Exit the program
    exit(EXIT_SUCCESS);
}

int main() {
    // Install the SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO lines
    struct gpiod_line *lock_line, *unlock_line, *servo_line;
    if ((lock_line = gpiod_line_request_byname(NULL, LOCK_BUTTON, "input", GPIOD_LINE_ACTIVE_LOW)) == NULL) {
        perror("gpiod_line_request_byname");
        exit(EXIT_FAILURE);
    }
    if ((unlock_line = gpiod_line_request_byname(NULL, UNLOCK_BUTTON, "input", GPIOD_LINE_ACTIVE_LOW)) == NULL) {
        gpiod_line_release(lock_line);
        perror("gpiod_line_request_byname");
        exit(EXIT_FAILURE);
    }
    if ((servo_line = gpiod_line_request_byname(NULL, SERVO_PIN, "output", GPIOD_LINE_ACTIVE_HIGH)) == NULL) {
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        perror("gpiod_line_request_byname");
        exit(EXIT_FAILURE);
    }

    // Enable the internal pull-up resistors for the buttons
    if (gpiod_line_set_bias(lock_line, GPIOD_LINE_BIAS_PULL_UP) != 0) {
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        gpiod_line_release(servo_line);
        perror("gpiod_line_set_bias");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_bias(unlock_line, GPIOD_LINE_BIAS_PULL_UP) != 0) {
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        gpiod_line_release(servo_line);
        perror("gpiod_line_set_bias");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Poll the buttons
        int lock_value, unlock_value;
        if (gpiod_line_get_value(lock_line, &lock_value) != 0) {
            gpiod_line_release(lock_line);
            gpiod_line_release(unlock_line);
            gpiod_line_release(servo_line);
            perror("gpiod_line_get_value");
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_get_value(unlock_line, &unlock_value) != 0) {
            gpiod_line_release(lock_line);
            gpiod_line_release(unlock_line);
            gpiod_line_release(servo_line);
            perror("gpiod_line_get_value");
            exit(EXIT_FAILURE);
        }

        // Check if the lock button is pressed
        if (lock_value == 0) {
            // Wait for the button release and a short delay
            usleep(DEBOUNCE_DELAY * 1000);
            if (gpiod_line_get_value(lock_line, &lock_value) != 0) {
                gpiod_line_release(lock_line);
                gpiod_line_release(unlock_line);
                gpiod_line_release(servo_line);
                perror("gpiod_line_get_value");
                exit(EXIT_FAILURE);
            }
            if (lock_value == 0) {
                // Send a pulse width of 2000us to lock the door
                if (gpiod_call(SERVO_PIN, 1, LOCK_PULSE_WIDTH) != 0) {
                    gpiod_line_release(lock_line);
                    gpiod_line_release(unlock_line);
                    gpiod_line_release(servo_line);
                    perror("gpiod_call");
                    exit(EXIT_FAILURE);
                }
                printf("Door locked\n");
            }
        }

        // Check if the unlock button is pressed
        if (unlock_value == 0) {
            // Wait for the button release and a short delay
            usleep(DEBOUNCE_DELAY * 1000);
            if (gpiod_line_get_value(unlock_line, &unlock_value) != 0) {
                gpiod_line_release(lock_line);
                gpiod_line_release(unlock_line);
                gpiod_line_release(servo_line);
                perror("gpiod_line_get_value");
                exit(EXIT_FAILURE);
            }
            if (unlock_value == 0) {
                // Send a pulse width of 1000us to unlock the door
                if (gpiod_call(SERVO_PIN, 1, UNLOCK_PULSE_WIDTH) != 0) {
                    gpiod_line_release(lock_line);
                    gpiod_line_release(unlock_line);
                    gpiod_line_release(servo_line);
                    perror("gpiod_call");
                    exit(EXIT_FAILURE);
                }
                printf("Door unlocked\n");
            }
        }

        // Sleep for a short period to keep CPU usage low
        usleep(10000);
    }

    // Release the GPIO lines
    gpiod_line_release(lock_line);
    gpiod_line_release(unlock_line);
    gpiod_line_release(servo_line);

    return EXIT_SUCCESS;
}

