// Function to log events to a file
void log_event(const char *event, int duration) {
    time_t now;
    struct tm *now_tm;
    char timestamp[32];

    time(&now);
    now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", now_tm);

