#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define the MPR121 I2C address
#define MPR121_ADDRESS 0x5A

// Define the GPIO pin for the relay
#define RELAY_PIN 17

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define the number of electrodes
#define NUM_ELECTRODES 12

// Define the baseline filtering values
#define MHD 0x01
#define NHD 0x01
#define NCL 0x01
#define FDL 0x01

// Define the FFI, SFI, and CDT values
#define FFI 0x01
#define SFI 0x01
#define CDT 0x01

// Define the auto-config range
#define AUTO_CONFIG_RANGE 0x01

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Release resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the relay to a known OFF state
    gpioSetMode(RELAY_PIN, GPIO_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Perform a soft reset
    uint8_t reset = 0x01;
    if (i2c_smbus_write_byte(i2c_fd, 0x0A, &reset) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure baseline filtering
    uint8_t baseline_filter = (MHD << 7) | (NHD << 6) | (NCL << 5) | (FDL << 4);
    if (i2c_smbus_write_byte(i2c_fd, 0x02, &baseline_filter) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set the debounce time
    uint8_t debounce = DEBOUNCE_TIME;
    if (i2c_smbus_write_byte(i2c_fd, 0x03, &debounce) < 0) {
        fprintf(stderr, "Failed to set debounce time\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure FFI, SFI, and CDT
    uint8_t config = (FFI << 7) | (SFI << 6) | (CDT << 5);
    if (i2c_smbus_write_byte(i2c_fd, 0x04, &config) < 0) {
        fprintf(stderr, "Failed to configure FFI, SFI, and CDT\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Enable auto-config
    uint8_t auto_config = AUTO_CONFIG_RANGE;
    if (i2c_smbus_write_byte(i2c_fd, 0x05, &auto_config) < 0) {
        fprintf(stderr, "Failed to enable auto-config\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Enable electrodes
    uint8_t electrodes = 0xFF;
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        electrodes &= ~(1 << i);
    }
    if (i2c_smbus_write_byte(i2c_fd, 0x06, &electrodes) < 0) {
        fprintf(stderr, "Failed to enable electrodes\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the touch status
        uint8_t touch_status;
        if (i2c_smbus_read_byte(i2c_fd, 0x00, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check for a fresh rising-edge touch on electrode 0
        if (touch_status & (1 << 0)) {
            // Toggle the relay
            gpioWrite(RELAY_PIN, 1);
            sleep(1);
            gpioWrite(RELAY_PIN, 0);
        }

        // Sleep for a short period
        usleep(10000);
    }

    // Release resources
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

