        va_start(args2, fmt);
        vfprintf(log_file, fmt, args2);
        va_end(args2);
        fclose(log_file);
    }
}

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    syslog(LOG_ERR, fmt, args);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        va_list args2;
        va_start(args2, fmt);
        vfprintf(log_file, fmt, args2);
        va_end(args2);
        fclose(log_file);
    }
}

void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpiod_close();
    close(sockfd);
    fclose(log_file);
    exit(0);
}

void sigint_handler(int sig) {
    cleanup();
}

void sigterm_handler(int sig) {
    cleanup();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    log_event("Starting up...");

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO: %s", strerror(errno));
        exit(1);
    }

    // Set up PIR sensor as input
    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        log_error("Failed to set PIR GPIO mode: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set up servo as output
    if (gpioSetMode(SERVO_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set servo GPIO mode: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_error("Failed to create socket: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "0.0.0.0", &addr.sin_addr);
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("Failed to bind socket: %s", strerror(errno));
        close(sockfd);
        gpioTerminate();
        exit(1);
    }

    if (listen(sockfd, 1) < 0) {
        log_error("Failed to listen on socket: %s", strerror(errno));
        close(sockfd);
        gpioTerminate();
        exit(1);
    }

    log_event("Listening on port %d...", PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            log_error("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, 1024, 0);
        if (bytes_received < 0) {
            log_error("Failed to receive data: %s", strerror(errno));
            close(client_fd);
            continue;
        }

        buffer[bytes_received] = '\0';

        if (strcmp(buffer, "PIR") == 0) {
            int pir_value = gpioRead(PIR_GPIO);
            send(client_fd, "PIR:1", 5, 0);
            log_event("PIR: %d", pir_value);
        } else {
            char *token = strtok(buffer, " ");
            if (token == NULL) {
                log_event("Invalid command: %s", buffer);
                send(client_fd, "Invalid command", 13, 0);
                close(client_fd);
                continue;
            }

            if (strcmp(token, "servo") == 0) {
                token = strtok(NULL, " ");
                if (token == NULL) {
                    log_event("Invalid command: %s", buffer);
                    send(client_fd, "Invalid command", 13, 0);
                    close(client_fd);
                    continue;
                }

                int angle = atoi(token);
                if (angle < 0 || angle > 180) {
                    log_event("Invalid angle: %d", angle);
                    send(client_fd, "Invalid angle", 10, 0);
                    close(client_fd);
                    continue;
                }

                int pulse_width = (angle * (SERVO_MAX - SERVO_MIN)) / 180 + SERVO_MIN;
                if (pulse_width < SERVO_MIN || pulse_width > SERVO_MAX) {
                    log_event("Invalid pulse width: %d", pulse_width);
                    send(client_fd, "Invalid pulse width", 15, 0);
                    close(client_fd);
                    continue;
                }

                if (gpioPWM(SERVO_GPIO, pulse_width, SERVO_FREQ) < 0) {
                    log_error("Failed to set servo PWM: %s", strerror(errno));
                    close(client_fd);
                    continue;
                }

                log_event("Servo: %d", angle);
                send(client_fd, "Servo set", 8, 0);
            } else {
                log_event("Invalid command: %s", buffer);
                send(client_fd, "Invalid command", 13, 0);
            }
        }

        close(client_fd);
    }

    cleanup();
    return 0;
}
