            exit(1);
        }
    }
    if (write(log_fd, log_line, strlen(log_line)) != strlen(log_line)) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
        exit(1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", strerror(errno));
        exit(1);
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin mode: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin low: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) == -1) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        gpioTerminate();
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler: %s", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    while (1) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
            syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
            usleep(DELAY);
            continue;
        }
        uint8_t reg = 0x00;
        if (write(i2c_fd, &reg, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to I2C register: %s", strerror(errno));
            usleep(DELAY);
            continue;
        }
        usleep(DELAY);
        uint16_t lux;
        if (read(i2c_fd, &lux, 2) != 2) {
            syslog(LOG_ERR, "Failed to read from I2C register: %s", strerror(errno));
            usleep(DELAY);
            continue;
        }
        if (lux > 65535) {
            syslog(LOG_ERR, "Invalid lux value: %d", lux);
            usleep(DELAY);
            continue;
        }
        log_data(lux);
        if (lux < LUX_THRESHOLD) {
            if (!relay_on) {
                gpioWrite(RELAY_PIN, 1);
                relay_on = true;
            }
        } else {
            if (relay_on) {
                gpioWrite(RELAY_PIN, 0);
                relay_on = false;
            }
        }
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

