#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_DOUT 23
#define GPIO_SCK 24
#define GPIO_LOCK 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

static volatile bool running = true;
static int threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;

static void sigint_handler(int sig) {
    running = false;
}

static void sigterm_handler(int sig) {
    running = false;
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck, *lock;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    dout = gpiod_chip_get_line(chip, GPIO_DOUT);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line");
        gpiod_chip_close(chip);
        exit(1);
    }

    sck = gpiod_chip_get_line(chip, GPIO_SCK);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line");
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        exit(1);
    }

    lock = gpiod_chip_get_line(chip, GPIO_LOCK);
    if (!lock) {
        syslog(LOG_ERR, "Failed to get LOCK line");
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        exit(1);
    }

    gpiod_line_request_output(dout, 0);
    gpiod_line_request_output(sck, 0);
    gpiod_line_request_output(lock, 0);

    gpiod_line_set_value(dout, 0);
    gpiod_line_set_value(sck, 0);
    gpiod_line_set_value(lock, 0);
}

static void cleanup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck, *lock;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip) {
        dout = gpiod_chip_get_line(chip, GPIO_DOUT);
        if (dout) {
            gpiod_line_release(dout);
        }

        sck = gpiod_chip_get_line(chip, GPIO_SCK);
        if (sck) {
            gpiod_line_release(sck);
        }

        lock = gpiod_chip_get_line(chip, GPIO_LOCK);
        if (lock) {
            gpiod_line_release(lock);
        }

        gpiod_chip_close(chip);
    }
}

static int read_hx711() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck;
    int value = 0;
    int retries = 0;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    dout = gpiod_chip_get_line(chip, GPIO_DOUT);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line");
        gpiod_chip_close(chip);
        return -1;
    }

    sck = gpiod_chip_get_line(chip, GPIO_SCK);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line");
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        return -1;
    }

    while (retries < 3) {
        gpiod_line_set_value(dout, 1);
        gpiod_line_set_value(sck, 1);
        usleep(1);
        gpiod_line_set_value(sck, 0);
        usleep(1);

        int i;
        for (i = 0; i < 24; i++) {
            gpiod_line_set_value(sck, 1);
            usleep(1);
            gpiod_line_set_value(sck, 0);
            usleep(1);
            if (gpiod_line_get_value(dout)) {
                value |= 1 << (23 - i);
            }
        }

        gpiod_line_set_value(sck, 1);
        usleep(1);
        gpiod_line_set_value(sck, 0);
        usleep(1);

        if (gpiod_line_get_value(dout)) {
            syslog(LOG_ERR, "Failed to read HX711 DOUT");
            retries++;
            gpiod_line_release(dout);
            gpiod_line_release(sck);
            gpiod_chip_close(chip);
            return -1;
        }

        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        return value;
    }

    syslog(LOG_ERR, "Failed to read HX711 after 3 retries");
    return -1;
}

static void tare() {
    int value;
    int i;
    int sum = 0;

    for (i = 0; i < 10; i++) {
        value = read_hx711();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read HX711 during tare");
            exit(1);
        }
        sum += value;
    }

    syslog(LOG_INFO, "Tare: %d", sum / 10);
}

static void measure() {
    int value;
    int i;
    int sum = 0;

    for (i = 0; i < 5; i++) {
        value = read_hx711();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read HX711 during measurement");
            exit(1);
        }
        sum += value;
    }

    syslog(LOG_INFO, "Weight: %.2f g", (sum / 5.0) * scale);
}

static void lock() {
    gpiod_line_set_value(GPIO_LOCK, 1);
    usleep(duration * 1000);
    gpiod_line_set_value(GPIO_LOCK, 0);
}

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                syslog(LOG_ERR, "Invalid option");
                exit(1);
        }
    }

    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    setup_gpio();

    tare();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        measure();
        if ((double)read_hx711() * scale > threshold) {
            lock();
        }
        usleep(500 * 1000);
    }

    cleanup_gpio();
    closelog();

    return 0;
}

