#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define KEEP_ALIVE 60
#define RELAY_PIN 17
#define RELAY_STATE_FILE "/sys/class/gpio/export"
#define RELAY_STATE_VALUE_FILE "/sys/class/gpio/gpio17/value"

int relay_fd;
struct mosquitto *mosq;
struct mosquitto_message *message;
struct gpiod_line *line;

void cleanup() {
    if (mosquitto_destroy(mosq) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to destroy MQTT client");
    }
    if (gpiod_line_release(line) != 0) {
        syslog(LOG_ERR, "Failed to release GPIO line");
    }
    if (gpiod_chip_close(line->chip) != 0) {
        syslog(LOG_ERR, "Failed to close GPIO chip");
    }
    gpiod_cleanup();
    closelog();
}

void sig_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, stopping relay controller", sig);
    gpiod_line_set_value(line, 0);
    mosquitto_disconnect(mosq);
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpiod_init() != 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver");
        exit(1);
    }

    if (gpiod_chip_open_by_name("gpiochip0") != 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        gpiod_cleanup();
        exit(1);
    }

    if (gpiod_line_request_output_by_name("gpio17", NULL, 0) != 0) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    if (gpiod_line_direction(line, "out") != 0) {
        syslog(LOG_ERR, "Failed to set GPIO line direction");
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    if (gpiod_line_export(line) != 0) {
        syslog(LOG_ERR, "Failed to export GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    if (gpiod_line_set_value(line, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    openlog("relay_controller", LOG_PID | LOG_PERROR, LOG_USER);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, MOSQ_FALSE, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEP_ALIVE, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    syslog(LOG_INFO, "Connected to MQTT broker");

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        gpiod_line_release(line);
        gpiod_chip_close(line->chip);
        gpiod_cleanup();
        exit(1);
    }

    syslog(LOG_INFO, "Subscribed to MQTT topic");

    while (1) {
        if (mosquitto_loop(mosq, 1000) == MOSQ_ERR_CONN_LOST) {
            syslog(LOG_ERR, "Lost connection to MQTT broker");
            sleep(5);
            continue;
        }

        if (mosquitto_loop(mosq, 1000) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to process MQTT loop");
            sleep(5);
            continue;
        }

        if (mosquitto_msg_is_subscribed(mosq, MQTT_TOPIC)) {
            while (mosquitto_msg_available(mosq)) {
                if (mosquitto_msg_pop(mosq, &message) != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Failed to pop MQTT message");
                    sleep(5);
                    continue;
                }

                if (message->payloadlen == 0) {
                    syslog(LOG_ERR, "Received empty MQTT message");
                    mosquitto_msg_free(message);
                    continue;
                }

                if (strcmp((char *)message->payload, "ON") == 0) {
                    if (gpiod_line_set_value(line, 1) != 0) {
                        syslog(LOG_ERR, "Failed to set GPIO line value");
                    }
                } else if (strcmp((char *)message->payload, "OFF") == 0) {
                    if (gpiod_line_set_value(line, 0) != 0) {
                        syslog(LOG_ERR, "Failed to set GPIO line value");
                    }
                } else {
                    syslog(LOG_ERR, "Received invalid MQTT message");
                }

                mosquitto_msg_free(message);
            }
        }
    }

    return 0;
}

