    int ret;

    // Initialize the GPIO library
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Set up the PWM channels
    ret = gpioSetMode(SERVO1_GPIO, PI_PWM);
    if (ret < 0) {
        fprintf(stderr, "Failed to set up servo 1 PWM: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetMode(SERVO2_GPIO, PI_PWM);
    if (ret < 0) {
        fprintf(stderr, "Failed to set up servo 2 PWM: %d\n", ret);
