        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPWM(SERVO5_GPIO, 0, SERVO_MIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set servo 5 pulse width: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Move the servos to their target positions
    for (int i = 0; i < 3; i++) {
        ret = gpioSetPWM(SERVO1_GPIO, 0, SERVO1_TARGET);
        if (ret < 0) {
            fprintf(stderr, "Failed to set servo 1 pulse width: %d\n", ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPWM(SERVO2_GPIO, 0, SERVO2_TARGET);
        if (ret < 0) {
            fprintf(stderr, "Failed to set servo 2 pulse width: %d\n", ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPWM(SERVO3_GPIO, 0, SERVO3_TARGET);
        if (ret < 0) {
            fprintf(stderr, "Failed to set servo 3 pulse width: %d\n", ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPWM(SERVO4_GPIO, 0, SERVO4_TARGET);
        if (ret < 0) {
            fprintf(stderr, "Failed to set servo 4 pulse width: %d\n", ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPWM(SERVO5_GPIO, 0, SERVO5_TARGET);
        if (ret < 0) {
            fprintf(stderr, "Failed to set servo 5 pulse width: %d\n", ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        sleep(1);
    }

    // Clean up
    ret = gpioTerminate();
    if (ret < 0) {
        fprintf(stderr, "Failed to terminate GPIO library: %d\n", ret);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
