#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define RELAY_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYS 10
#define POLL_INTERVAL 5000
#define READ_DELAY 180

#define MAX_LOG_LINE 64

static int i2c_fd = -1;
static int relay_fd = -1;
static bool relay_on = false;

static void log_line(const char *format, ...) {
    char log_line[MAX_LOG_LINE];
    va_list args;
    va_start(args, format);
    vsnprintf(log_line, MAX_LOG_LINE, format, args);
    va_end(args);
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s: %s\n", timestamp, log_line);
    fclose(file);
}

static void sigint_handler(int sig) {
    log_line("Received SIGINT, shutting down...");
    gpio_write(RELAY_PIN, 0);
    gpio_close();
    close(i2c_fd);
    close(relay_fd);
    unlink(LOG_FILE);
    exit(0);
}

static void sigterm_handler(int sig) {
    log_line("Received SIGTERM, shutting down...");
    gpio_write(RELAY_PIN, 0);
    gpio_close();
    close(i2c_fd);
    close(relay_fd);
    unlink(LOG_FILE);
    exit(0);
}

static int i2c_init() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

static int relay_init() {
    relay_fd = gpioInitialise();
    if (relay_fd < 0) {
        perror("gpioInitialise");
        return -1;
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    return 0;
}

static int read_lux() {
    uint16_t data;
    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x10) < 0) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    usleep(READ_DELAY * 1000);
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_read_byte_data");
        return -1;
    }
    if (i2c_smbus_read_word_data(i2c_fd, 0x00, &data) < 0) {
        perror("i2c_smbus_read_word_data");
        return -1;
    }
    return (data >> 8) | (data << 8);
}

static void update_relay() {
    int lux = read_lux();
    if (lux < 0) {
        log_line("Failed to read lux");
        gpio_write(RELAY_PIN, 0);
        return;
    }
    log_line("Lux = %d", lux);
    if (!relay_on && lux < LUX_THRESHOLD_DUSK + HYS) {
        log_line("Activating relay");
        gpio_write(RELAY_PIN, 1);
        relay_on = true;
    } else if (relay_on && lux > LUX_THRESHOLD_DAWN - HYS) {
        log_line("Deactivating relay");
        gpio_write(RELAY_PIN, 0);
        relay_on = false;
    }
}

int main() {
    if (i2c_init() < 0) {
        log_line("Failed to initialize I2C");
        return 1;
    }
    if (relay_init() < 0) {
        log_line("Failed to initialize relay");
        close(i2c_fd);
        return 1;
    }
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    while (1) {
        update_relay();
        usleep(POLL_INTERVAL * 1000);
    }
    return 0;
}

