// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_line_set_value(gpio, 17, 0);
    gpiod_line_release(gpio);
    gpiod_context_unref(gpio_context);
    fprintf(stderr, "Exiting...\n");
    exit(0);
}

int main() {
    // Initialize GPIO context
    gpio_context = gpiod_ctx_new();
    if (!gpio_context) {
        fprintf(stderr, "Failed to create GPIO context: %s\n", gpiod_ctx_errstr(gpio_context));
        return 1;
    }

    // Open GPIO line for input
    gpio = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_chip_errstr(gpio));
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Get line for GPIO 4
    line = gpiod_chip_get_line(gpio, 4);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO 4: %s\n", gpiod_line_errstr(line));
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Set line as input
    if (gpiod_line_request_output(gpio, line, 0) < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", gpiod_line_errstr(line));
        gpiod_line_release(line);
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Open GPIO line for output
    relay = gpiod_chip_open("/dev/gpiochip0");
    if (!relay) {
        fprintf(stderr, "Failed to open GPIO chip for relay: %s\n", gpiod_chip_errstr(relay));
        gpiod_line_release(line);
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Get line for GPIO 17
    relay_line = gpiod_chip_get_line(relay, 17);
    if (!relay_line) {
        fprintf(stderr, "Failed to get line for GPIO 17: %s\n", gpiod_line_errstr(relay_line));
        gpiod_chip_close(relay);
        gpiod_line_release(line);
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Set line as output
    if (gpiod_line_request_output(relay, relay_line, 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", gpiod_line_errstr(relay_line));
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay);
        gpiod_line_release(line);
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay);
        gpiod_chip_close(gpio);
        gpiod_ctx_unref(gpio_context);
        return 1;
    }

    // Main loop
    while (1) {
        // Read current state of sensor
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_line_errstr(line));
            gpiod_line_release(line);
            gpiod_line_release(relay_line);
            gpiod_chip_close(relay);
            gpiod_chip_close(gpio);
            gpiod_ctx_unref(gpio_context);
            return 1;
        }

        // Check if sensor is HIGH
        if (state == 1) {
            // Wait for 50ms to debounce
            struct timespec debounce;
            debounce.tv_sec = 0;
            debounce.tv_nsec = 50000000;
            nanosleep(&debounce);

            // Read current state of sensor again
            state = gpiod_line_get_value(line);
            if (state < 0) {
                fprintf(stderr, "Failed to read line value: %s\n", gpiod_line_errstr(line));
                gpiod_line_release(line);
                gpiod_line_release(relay_line);
                gpiod_chip_close(relay);
                gpiod_chip_close(gpio);
                gpiod_ctx_unref(gpio_context);
                return 1;
            }

            // Check if sensor is still HIGH
            if (state == 1) {
                // Toggle relay
                if (gpiod_line_get_value(relay_line) == 1) {
                    gpiod_line_set_value(relay_line, 0);
                    fprintf(stderr, "%s: Relay OFF\n", ctime(&now));
                } else {
                    gpiod_line_set_value(relay_line, 1);
                    fprintf(stderr, "%s: Relay ON\n", ctime(&now));
                }
            }
        }

        // Check if sensor is LOW
        if (state == 0) {
            // Wait for 50ms to debounce
            struct timespec debounce;
            debounce.tv_sec = 0;
            debounce.tv_nsec = 50000000;
            nanosleep(&debounce);

            // Read current state of sensor again
            state = gpiod_line_get_value(line);
            if (state < 0) {
                fprintf(stderr, "Failed to read line value: %s\n", gpiod_line_errstr(line));
                gpiod_line_release(line);
                gpiod_line_release(relay_line);
                gpiod_chip_close(relay);
                gpiod_chip_close(gpio);
                gpiod_ctx_unref(gpio_context);
                return 1;
            }

            // Check if sensor is still LOW
            if (state == 0) {
                // Toggle relay
                if (gpiod_line_get_value(relay_line) == 1) {
                    gpiod_line_set_value(relay_line, 0);
                    fprintf(stderr, "%s: Relay OFF\n", ctime(&now));
                } else {
                    gpiod_line_set_value(relay_line, 1);
                    fprintf(stderr, "%s: Relay ON\n", ctime(&now));
                }
            }
        }

        // Sleep for 10ms
        struct timespec sleep;
        sleep.tv_sec = 0;
        sleep.tv_nsec = 10000000;
        nanosleep(&sleep);
    }

    return 0;
