#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define LOG_FILE "water_flow.log"
#define FLOW_SENSOR_PIN 17
#define SOL Valve_PIN 27
#define DEBOUNCE_TIMEOUT 1000
#define FLOW_THRESHOLD 5.0
#define HYSTERESIS 0.5

// Mutex for protecting shared pulse counter
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared pulse counter
volatile uint32_t pulse_count = 0;

// Flag to track solenoid state
bool solenoid_open = true;

// Flag to track log file descriptor
int log_fd = -1;

// Function to log a message to the log file
void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    if (log_fd != -1) {
        vfprintf(log_fd, format, args);
        fputc('\n', log_fd);
    }
    va_end(args);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    log_message("Received signal %d", sig);
    solenoid_open = true;
    if (log_fd != -1) {
        fclose(log_fd);
        log_fd = -1;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpiod_cleanup();
    exit(0);
}

// Function to read pulse count from the flow sensor
void *read_pulse_count(void *arg) {
    gpiod_line_request_output(SOL, "active_low", 0);
    gpiod_line_request_output(FLOW_SENSOR_PIN, "active_low", 0);
    while (1) {
        gpiod_line_set(SOL, 0);
        gpiod_line_set(FLOW_SENSOR_PIN, 1);
        usleep(DEBOUNCE_TIMEOUT);
        gpiod_line_set(FLOW_SENSOR_PIN, 0);
        usleep(DEBOUNCE_TIMEOUT);
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        gpiod_line_request_event(FLOW_SENSOR_PIN, GPIOD_LINE_EVENT_BOTH);
        while (1) {
            struct gpiod_line_event event;
            if (gpiod_line_get_event(FLOW_SENSOR_PIN, &event) == 0) {
                if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
                    pulse_count++;
                }
            } else {
                break;
            }
        }
        gpiod_line_request_event(FLOW_SENSOR_PIN, 0);
        pthread_mutex_unlock(&pulse_mutex);
        usleep(1000000); // 1 second
        if (pulse_count > 0) {
            double flow_rate = (double)pulse_count / 7.5; // Assuming 7.5 pulses per liter
            if (flow_rate > FLOW_THRESHOLD) {
                solenoid_open = false;
                gpiod_line_set(SOL, 0);
                log_message("Flow rate: %.2f LPM, Solenoid closed", flow_rate);
            } else if (flow_rate < FLOW_THRESHOLD - HYSTERESIS && solenoid_open) {
                solenoid_open = false;
                gpiod_line_set(SOL, 0);
                log_message("Flow rate: %.2f LPM, Solenoid closed", flow_rate);
            } else if (flow_rate < FLOW_THRESHOLD + HYSTERESIS && !solenoid_open) {
                solenoid_open = true;
                gpiod_line_set(SOL, 1);
                log_message("Flow rate: %.2f LPM, Solenoid open", flow_rate);
            }
            log_message("Flow rate: %.2f LPM", flow_rate);
        }
    }
}

int main() {
    // Initialize the GPIO library
    if (gpiod_init() != 0) {
        perror("gpiod_init");
        return 1;
    }

    // Open the log file
    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == -1) {
        perror("fopen");
        gpiod_cleanup();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        fclose(log_fd);
        gpiod_cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        fclose(log_fd);
        gpiod_cleanup();
        return 1;
    }

    // Initialize the pulse counter mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        fclose(log_fd);
        gpiod_cleanup();
        return 1;
    }

    // Start the pulse counter thread
    pthread_t pulse_thread;
    if (pthread_create(&pulse_thread, NULL, read_pulse_count, NULL) != 0) {
        perror("pthread_create");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_fd);
        gpiod_cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Do nothing
    }

    // Clean up on exit
    pthread_join(pulse_thread, NULL);
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_fd);
    gpiod_cleanup();
    return 0;
}

