#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <getopt.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#include <pigpio.h>

#define DEFAULT_DEBOUNCE 50
#define RELAY_PIN 17
#define SENSOR_PIN 4

static volatile bool running = true;
static bool relay_state = false;
static uint32_t debounce_timer = 0;
static uint32_t debounce_interval = DEFAULT_DEBOUNCE * 1000; // convert ms to us

static void sigint_handler(int sig) {
    running = false;
}

static void sigterm_handler(int sig) {
    running = false;
}

static void toggle_relay() {
    if (relay_state) {
        gpioWrite(RELAY_PIN, 0);
        relay_state = false;
        printf("%s Relay: OFF\n", asctime(localtime(&time(NULL)));
    } else {
        gpioWrite(RELAY_PIN, 1);
        relay_state = true;
        printf("%s Relay: ON\n", asctime(localtime(&time(NULL)));
    }
}

static void check_sensor() {
    if (gpioRead(SENSOR_PIN) == 1 && debounce_timer == 0) {
        debounce_timer = time(NULL) + debounce_interval / 1000;
    } else if (gpioRead(SENSOR_PIN) == 0 && debounce_timer > 0 && time(NULL) >= debounce_timer) {
        toggle_relay();
        debounce_timer = 0;
    }
}

int main(int argc, char **argv) {
    int opt;
    char *endptr;
    long debounce;

    // Parse command-line argument
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce = strtol(optarg, &endptr, 10);
                if (endptr == optarg || *endptr != '\0' || debounce < 0) {
                    fprintf(stderr, "Invalid debounce interval\n");
                    return 1;
                }
                debounce_interval = debounce * 1000; // convert ms to us
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up sensor pin as input
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up initial relay state
    gpioWrite(RELAY_PIN, 0);

    // Main loop
    while (running) {
        check_sensor();
        usleep(10000); // 10ms
    }

    // Clean up
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return 0;
}

