#include <libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_WINDOW_US 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile bool running = true;
static gpiod_line *line;
static gpiod_chip *chip;
static FILE *log_file;

static void sigint_handler(int sig) {
    running = false;
}

static void sigterm_handler(int sig) {
    running = false;
}

static void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(line, 0, GPIOD_LINE_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_active_state(line, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO line high: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_edge(line, GPIOD_LINE_EVENT_RISING) != 0) {
        fprintf(stderr, "Failed to set GPIO line edge trigger: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_debounce(line, DEBOUNCE_WINDOW_US) != 0) {
        fprintf(stderr, "Failed to set GPIO line debounce: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
}

static void cleanup_gpio() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

static void init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void cleanup_log() {
    fclose(log_file);
}

static void log_rpm(double rpm) {
    char timestamp[32];
    time_t now;
    struct tm *tm;
    now = time(NULL);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
}

int main() {
    struct timespec last_sample;
    uint64_t pulses = 0;
    double last_rpm = 0.0;
    double rpm = 0.0;

    init_gpio();
    init_log();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    gpiod_line_event_subscribe(line, GPIOD_LINE_EVENT_RISING, NULL, NULL);

    clock_gettime(CLOCK_MONOTONIC, &last_sample);

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event, 1000) == 0) {
            pulses++;
        }

        clock_gettime(CLOCK_MONOTONIC, &last_sample);
        double elapsed = (double)(last_sample.tv_sec - timespec_to_time_t(last_sample)) + (double)(last_sample.tv_nsec / 1e9);
        if (elapsed >= SAMPLE_INTERVAL_S) {
            rpm = (pulses / elapsed) * 60.0;
            log_rpm(rpm);
            printf("RPM: %.2f\n", rpm);
            pulses = 0;
            last_rpm = rpm;
        }
    }

    cleanup_log();
    cleanup_gpio();

    return 0;
}

static time_t timespec_to_time_t(struct timespec ts) {
    return (time_t)ts.tv_sec + (ts.tv_nsec / 1e9);
}

