#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pin numbers
#define TOUCH_PIN 4
#define RELAY_PIN 17

// Define the maximum time to hold the relay ON
#define MAX_HOLD_TIME 10

// Define the polling interval
#define POLL_INTERVAL 50

// Flag to indicate if the relay should be ON or OFF
volatile int relay_state = 0;

// Flag to indicate if the sensor has been held for too long
volatile int sensor_held = 0;

// Flag to indicate if the program should exit
volatile int exit_program = 0;

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    exit_program = 1;
}

int main() {
    // Initialize the GPIO library
    struct gpiod_line *touch_line, *relay_line;
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open("/dev/gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", ret);
        return 1;
    }

    // Request the lines
    ret = gpiod_chip_request_lines(gpiod_chip_get_fd(ret), &touch_line, &relay_line, TOUCH_PIN, GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_REQUEST_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting lines: %d\n", ret);
        gpiod_chip_close(gpiod_chip_get_fd(ret));
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize the relay
    gpiod_line_set_value(relay_line, 0);

    // Main loop
    while (!exit_program) {
        // Read the touch sensor
        ret = gpiod_line_get_value(touch_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading touch sensor: %d\n", ret);
            gpiod_line_release(touch_line);
            gpiod_line_release(relay_line);
            gpiod_chip_close(gpiod_chip_get_fd(ret));
            return 1;
        }

        // Check if the sensor is pressed
        if (ret == 1) {
            // Check if the sensor has been held for too long
            if (sensor_held) {
                // Force the relay OFF
                gpiod_line_set_value(relay_line, 0);
                sensor_held = 0;
            } else {
                // Toggle the relay
                relay_state = !relay_state;
                gpiod_line_set_value(relay_line, relay_state);
                sensor_held = 1;
            }
        } else {
            // Reset the sensor held flag
            sensor_held = 0;
        }

        // Wait for the next poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Release the relay
    gpiod_line_set_value(relay_line, 0);

    // Release the lines
    gpiod_line_release(touch_line);
    gpiod_line_release(relay_line);

    // Close the GPIO chip
    gpiod_chip_close(gpiod_chip_get_fd(ret));

    // Clean up the GPIO library
    gpiod_cleanup();

    return 0;
}

