#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <getopt.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#include <pigpio.h>

#define GPIO_VALVE_ENABLE 23
#define GPIO_VALVE_PWM 18
#define GPIO_FLOW_SENSOR 24
#define PWM_FREQ_HZ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 255
#define CONTROL_PERIOD_MS 100
#define LOG_FILE "flow_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void sigterm_handler(int sig) {
    running = 0;
}

void cleanup() {
    if (gpioPWM(GPIO_VALVE_PWM, 0) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to 0: %s\n", strerror(errno));
    }
    if (gpioWrite(GPIO_VALVE_ENABLE, 0) != 0) {
        fprintf(stderr, "Failed to set valve enable low: %s\n", strerror(errno));
    }
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Failed to terminate GPIO library: %s\n", strerror(errno));
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
    }
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int target_flow_rate;
    char *endptr;
    struct sigaction sa;
    struct itimerspec timer;
    struct timeval last_sample_time;
    int log_fd;
    FILE *log_file;
    uint32_t flow_count;
    uint32_t last_flow_count;
    uint32_t pwm_duty_cycle;

    // Parse command-line argument
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = strtol(optarg, &endptr, 10);
                if (*endptr != '\0' || target_flow_rate <= 0) {
                    fprintf(stderr, "Invalid target flow rate: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up GPIO modes
    if (gpioSetMode(GPIO_VALVE_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output: %s\n", GPIO_VALVE_ENABLE, strerror(errno));
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_VALVE_PWM, PI_PWM) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to PWM: %s\n", GPIO_VALVE_PWM, strerror(errno));
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_FLOW_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to input: %s\n", GPIO_FLOW_SENSOR, strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up GPIO initial values
    if (gpioWrite(GPIO_VALVE_ENABLE, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_VALVE_ENABLE, strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up PWM
    if (gpioPWM(GPIO_VALVE_PWM, 128) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to 128: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up timer
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = CONTROL_PERIOD_MS * 1000000;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = CONTROL_PERIOD_MS * 1000000;
    if (timerfd_settime(0, 0, &timer, NULL) != 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    log_file = fdopen(log_fd, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up ISR
    if (gpioSetISR(GPIO_FLOW_SENSOR, RISING_EDGE, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set up ISR: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        struct itimerspec remaining;
        if (timerfd_gettime(0, &remaining) != 0) {
            fprintf(stderr, "Failed to get timer remaining time: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
        if (remaining.it_value.tv_sec > 0 || remaining.it_value.tv_nsec > 0) {
            usleep(remaining.it_value.tv_nsec / 1000);
        }

        // Read flow sensor
        flow_count = gpioGetISRCount(GPIO_FLOW_SENSOR);
        if (flow_count < 0) {
            fprintf(stderr, "Failed to read flow sensor ISR count: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        // Calculate flow rate
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec - last_sample_time.tv_sec >= 1) {
            last_flow_count = flow_count;
            last_sample_time = now;
        }
        uint32_t flow_rate = (flow_count - last_flow_count) * 60 * 1000 / (now.tv_sec - last_sample_time.tv_sec);

        // Calculate PWM duty cycle
        pwm_duty_cycle = (uint32_t)((double)target_flow_rate / 100 * PWM_DUTY_MAX);

        // Clamp PWM duty cycle
        if (pwm_duty_cycle < PWM_DUTY_MIN) {
            pwm_duty_cycle = PWM_DUTY_MIN;
        } else if (pwm_duty_cycle > PWM_DUTY_MAX) {
            pwm_duty_cycle = PWM_DUTY_MAX;
        }

        // Set PWM duty cycle
        if (gpioPWM(GPIO_VALVE_PWM, pwm_duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %u: %s\n", pwm_duty_cycle, strerror(errno));
            return EXIT_FAILURE;
        }

        // Log data
        fprintf(log_file, "%lu,%u,%u\n", now.tv_sec * 1000 + now.tv_usec / 1000, flow_rate, pwm_duty_cycle);
        fflush(log_file);
    }

    cleanup();
    return EXIT_SUCCESS;
}

