#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RFID_TAG "0000000000"
#define RFID_CHANNEL 0
#define RFID_SPEED 100000
#define RFID_CS_PIN 22
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22
#define DEBOUNCE_TIME 50
#define LOCK_RELEASE_TIME 5000

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, exiting...", sig);
    gpio_write(RFID_CS_PIN, 1);
    gpio_write(LOCK1_PIN, 1);
    gpio_write(LOCK2_PIN, 1);
    fclose(log_file);
    pigpio_close();
    exit(0);
}

int main() {
    int lock1_state = 1;
    int lock2_state = 1;
    int button_pressed = 0;
    int rfid_read = 0;
    char rfid_tag[11];
    FILE *log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    gpio_set_mode(RFID_CS_PIN, PI_OUTPUT);
    gpio_set_mode(LOCK1_PIN, PI_OUTPUT);
    gpio_set_mode(LOCK2_PIN, PI_OUTPUT);
    gpio_set_mode(BUTTON_PIN, PI_INPUT);
    gpio_set_pull_up(BUTTON_PIN);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handler");
        return 1;
    }

    while (1) {
        if (gpio_read(BUTTON_PIN) == 0) {
            button_pressed = 1;
            usleep(DEBOUNCE_TIME * 1000);
            if (gpio_read(BUTTON_PIN) == 0) {
                button_pressed = 1;
                syslog(LOG_INFO, "Button pressed");
                rfid_read = 1;
            } else {
                button_pressed = 0;
            }
        }

        if (rfid_read) {
            if (pigpio_spi_open(RFID_CHANNEL, RFID_SPEED) < 0) {
                syslog(LOG_ERR, "Failed to open SPI interface");
                return 1;
            }

            int bytes_read = pigpio_spi_transfer(RFID_CHANNEL, RFID_TAG, 10, rfid_tag, 10);
            if (bytes_read < 0) {
                syslog(LOG_ERR, "Failed to read RFID tag");
                pigpio_spi_close(RFID_CHANNEL);
                rfid_read = 0;
                continue;
            }

            if (memcmp(rfid_tag, RFID_TAG, 10) == 0) {
                syslog(LOG_INFO, "Valid RFID tag detected");
                lock1_state = 0;
                lock2_state = 0;
                pigpio_spi_close(RFID_CHANNEL);
                rfid_read = 0;
                for (int i = 0; i < LOCK_RELEASE_TIME / 1000; i++) {
                    gpio_write(LOCK1_PIN, 0);
                    gpio_write(LOCK2_PIN, 0);
                    usleep(1000);
                    gpio_write(LOCK1_PIN, 1);
                    gpio_write(LOCK2_PIN, 1);
                    usleep(1000);
                }
                lock1_state = 1;
                lock2_state = 1;
            } else {
                syslog(LOG_INFO, "Invalid RFID tag detected");
            }

            pigpio_spi_close(RFID_CHANNEL);
            rfid_read = 0;
        }

        if (lock1_state == 0 || lock2_state == 0) {
            syslog(LOG_INFO, "Locks are not engaged");
        } else {
            syslog(LOG_INFO, "Locks are engaged");
        }

        syslog(LOG_INFO, "Current time: %s", ctime(&time(NULL)));
    }

    return 0;
}

