#define PWM_FREQ 100  // 100Hz
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define SPEED_TARGET 60  // RPM

#define PID_P 0.1
#define PID_I 0.01
#define PID_D 0.0

typedef struct {
    int encoder_a;
    int encoder_b;
    int motor_en;
    int motor_in1;
    int motor_in2;
} motor_t;

typedef struct {
    pthread_mutex_t mutex;
    int count;
} encoder_t;

void sigint_handler(int sig) {
    gpio_write(MOTOR1_ENA, 0);
    gpio_write(MOTOR2_ENB, 0);
    gpio_release(MOTOR1_IN1);
    gpio_release(MOTOR1_IN2);
    gpio_release(MOTOR2_IN3);
    gpio_release(MOTOR2_IN4);
    gpio_close();
    fclose(log_file);
    exit(0);
}

void* encoder_monitor(void* arg) {
    motor_t* motor = (motor_t*) arg;
    encoder_t* encoder = (encoder_t*) motor->encoder_a;
    int fd = gpio_open("/dev/mem");
    if (fd < 0) {
        perror("gpio_open");
        return NULL;
    }
    volatile uint32_t* gpio_base = (uint32_t*) mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_base == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return NULL;
    }
    close(fd);

    while (1) {
        pthread_mutex_lock(&encoder->mutex);
        int count = encoder->count;
        pthread_mutex_unlock(&encoder->mutex);

        int a = gpio_read(motor->encoder_a);
        int b = gpio_read(motor->encoder_b);
        if (a == -1 || b == -1) {
            continue;
        }

        int direction = (a == 1) ? 1 : -1;
        int new_count = count + direction;
        pthread_mutex_lock(&encoder->mutex);
        encoder->count = new_count;
        pthread_mutex_unlock(&encoder->mutex);
    }

    munmap(gpio_base, 4096);
    return NULL;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpio_setmode(GPIO_MODE_BCM);
    gpio_setpullup(MOTOR1_IN1, GPIO_PULLUP_EN);
    gpio_setpullup(MOTOR1_IN2, GPIO_PULLUP_EN);
    gpio_setpullup(MOTOR2_IN3, GPIO_PULLUP_EN);
    gpio_setpullup(MOTOR2_IN4, GPIO_PULLUP_EN);
    gpio_setpullup(ENCODER1_A, GPIO_PULLUP_EN);
    gpio_setpullup(ENCODER1_B, GPIO_PULLUP_EN);
    gpio_setpullup(ENCODER2_A, GPIO_PULLUP_EN);
    gpio_setpullup(ENCODER2_B, GPIO_PULLUP_EN);

    gpio_write(MOTOR1_ENA, 1);
    gpio_write(MOTOR2_ENB, 1);
    gpio_write(MOTOR1_IN1, 1);
    gpio_write(MOTOR2_IN3, 1);

    pthread_t encoder_thread1;
    pthread_t encoder_thread2;
    encoder_t encoder1 = { .mutex = PTHREAD_MUTEX_INITIALIZER, .count = 0 };
    encoder_t encoder2 = { .mutex = PTHREAD_MUTEX_INITIALIZER, .count = 0 };
    motor_t motor1 = { .encoder_a = ENCODER1_A, .encoder_b = ENCODER1_B, .motor_en = MOTOR1_ENA, .motor_in1 = MOTOR1_IN1, .motor_in2 = MOTOR1_IN2 };
    motor_t motor2 = { .encoder_a = ENCODER2_A, .encoder_b = ENCODER2_B, .motor_en = MOTOR2_ENB, .motor_in1 = MOTOR2_IN3, .motor_in2 = MOTOR2_IN4 };
    pthread_create(&encoder_thread1, NULL, encoder_monitor, &motor1);
    pthread_create(&encoder_thread2, NULL, encoder_monitor, &motor2);

    FILE* log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }
    fprintf(log_file, "time,speed1,speed2,p1,i1,d1,p2,i2,d2\n");

    int last_time = 0;
    while (1) {
        int current_time = gpio_gettickus();
        if (current_time - last_time >= PID_SAMPLE_TIME) {
            last_time = current_time;

            pthread_mutex_lock(&encoder1.mutex);
            pthread_mutex_lock(&encoder2.mutex);
            int count1 = encoder1.count;
            int count2 = encoder2.count;
            pthread_mutex_unlock(&encoder1.mutex);
            pthread_mutex_unlock(&encoder2.mutex);

            int speed1 = (count1 - encoder1.count) * 60 / (PID_SAMPLE_TIME / 1000.0);
            int speed2 = (count2 - encoder2.count) * 60 / (PID_SAMPLE_TIME / 1000.0);

            int p1 = PID_P * (SPEED_TARGET - speed1);
            int i1 = PID_I * (p1 + (p1 - (p1 + PID_D * (speed1 - SPEED_TARGET))));
            int d1 = PID_D * (speed1 - SPEED_TARGET);
            int p2 = PID_P * (SPEED_TARGET - speed2);
            int i2 = PID_I * (p2 + (p2 - (p2 + PID_D * (speed2 - SPEED_TARGET))));
            int d2 = PID_D * (speed2 - SPEED_TARGET);

            int pid1 = p1 + i1 + d1;
            int pid2 = p2 + i2 + d2;

            int duty1 = (pid1 + 1) / 2;
            int duty2 = (pid2 + 1) / 2;

            gpio_write(MOTOR1_IN2, (duty1 > 0) ? 0 : 1);
            gpio_write(MOTOR2_IN4, (duty2 > 0) ? 0 : 1);
            gpio_write(MOTOR1_ENA, duty1);
            gpio_write(MOTOR2_ENB, duty2);

            fprintf(log_file, "%d,%d,%d,%d,%d,%d,%d,%d,%d\n", current_time, speed1, speed2, p1, i1, d1, p2, i2, d2);
            fflush(log_file);
        }
    }

    return 0;
