#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MPR121_ADDRESS 0x5A
#define TOUCH_THRESHOLD 0x80
#define RELEASE_THRESHOLD 0x40
#define FILTER_CONFIG 0x01
#define RUN_MODE 0x02
#define TOUCH_STATUS 0x02
#define TOUCH_COUNT 12

#define RELAY_LOG_FILE "relay_log.txt"

void sigint_handler(int sig) {
    gpioWrite(RELAY_GPIO, 0);
    close(i2cOpen(1, MPR121_ADDRESS));
    close(i2cOpen(1, MPR121_ADDRESS));
    exit(0);
}

int main() {
    struct itimerval timer;
    struct timeval tv;
    int fd;
    int i;
    uint8_t data[2];
    char timestamp[20];

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus
    if ((fd = i2cOpen(1, MPR121_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Perform MPR121 initialization sequence
    if (i2cWriteReg(fd, 0x00, 0x1F) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg(fd, 0x02, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    for (i = 0; i < TOUCH_COUNT; i++) {
        if (i2cWriteReg(fd, 0x03 + i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to write to MPR121\n");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }
    }

    if (i2cWriteReg(fd, 0x0E, FILTER_CONFIG) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg(fd, 0x0F, RUN_MODE) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set up timer to poll MPR121 every 50ms
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 50000;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 0;
    setitimer(ITIMER_REAL, &timer, NULL);

    // Open relay log file
    FILE *relay_log = fopen(RELAY_LOG_FILE, "a");
    if (!relay_log) {
        fprintf(stderr, "Failed to open relay log file\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read touch status from MPR121
        if (i2cReadReg(fd, TOUCH_STATUS, data, 2) < 0) {
            fprintf(stderr, "Failed to read from MPR121\n");
            fclose(relay_log);
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        // Check if any electrodes are touched
        int touched = 0;
        for (i = 0; i < TOUCH_COUNT; i++) {
            if (data[i / 8] & (1 << (7 - i % 8))) {
                touched = 1;
                break;
            }
        }

        // Update relay state
        if (touched) {
            gpioWrite(RELAY_GPIO, 1);
        } else {
            gpioWrite(RELAY_GPIO, 0);
        }

        // Append timestamp to relay log
        gettimeofday(&tv, NULL);
        sprintf(timestamp, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
        fprintf(relay_log, "%s", timestamp);

        // Wait for next timer event
        select(0, NULL, NULL, NULL, NULL);
    }

    fclose(relay_log);
    i2cClose(fd);
    gpioTerminate();
    return 0;
}

