#include <gpiod.h>

#define MPR121_ADDRESS 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x01
#define RELEASE_THRESHOLD 0x02
#define FILTER 0x03
#define CHARGE_TIME 0x04
#define ELECTRODE_CURRENT 0x05
#define RUN_MODE 0x06
#define STABILIZATION_DELAY 100

int i2c_fd;
struct gpiod_line *relay_line;

void cleanup(int sig) {
    if (relay_line) {
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        exit(1);
    }

    ret = gpiod_line_request_output(relay_line, 0, GPIOD_LINE_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request relay line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Initialize MPR121
    uint8_t data = 0;
    ret = write(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to write to MPR121");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Configure touch and release thresholds
    data = TOUCH_THRESHOLD | RELEASE_THRESHOLD;
    ret = write(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to write to MPR121");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Configure filter and charge time
    data = FILTER | CHARGE_TIME;
    ret = write(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to write to MPR121");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Configure electrode current
    data = ELECTRODE_CURRENT;
    ret = write(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to write to MPR121");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Switch to run mode
    data = RUN_MODE;
    ret = write(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to write to MPR121");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY * 1000);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        uint8_t touch_status;
        ret = read(i2c_fd, &touch_status, 1);
        if (ret != 1) {
            perror("Failed to read from MPR121");
            close(i2c_fd);
            gpiod_line_release(relay_line);
            gpiod_chip_close(chip);
            exit(1);
        }

        if (touch_status > 0) {
            ret = gpiod_line_set_value(relay_line, 1);
            if (ret) {
                perror("Failed to toggle relay");
                close(i2c_fd);
                gpiod_line_release(relay_line);
                gpiod_chip_close(chip);
                exit(1);
            }
            printf("Relay toggled\n");
        } else {
            ret = gpiod_line_set_value(relay_line, 0);
            if (ret) {
                perror("Failed to toggle relay");
                close(i2c_fd);
                gpiod_line_release(relay_line);
                gpiod_chip_close(chip);
                exit(1);
            }
        }

        usleep(100 * 1000);
    }

    return 0;
}

