#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <libgpiod/libgpiod.h>

#define RELAY_PIN 18
#define PIR_PIN 17
#define RATE_LIMIT 2000
#define UNLOCK_DURATION 500

static gpiod_line *relay_line = NULL;
static gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static bool rate_limited = false;
static uint64_t last_unlock_time = 0;

void cleanup(int sig) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
    }
    gpiod_context_release(gpiod_context_default());
    exit(0);
}

int main() {
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    ssize_t num_events;
    struct itimerspec timer;
    struct sigaction sa;
    struct stat sb;
    char timestamp[32];

    // Initialize GPIO driver
    gpiod_context *ctx = gpiod_context_default();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Open relay pin as output
    relay_line = gpiod_line_request_by_name(ctx, "gpiochip0", RELAY_PIN, GPIOD_LINE_ACTIVE_STATE_HIGH, GPIOD_LINE_REQUEST_OUTPUT);
    if (relay_line == NULL) {
        fprintf(stderr, "Failed to open relay pin\n");
        gpiod_context_release(ctx);
        return 1;
    }

    // Open PIR pin as input with pull-down
    pir_line = gpiod_line_request_by_name(ctx, "gpiochip0", PIR_PIN, GPIOD_LINE_ACTIVE_STATE_LOW, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_BIAS_PULL_DOWN);
    if (pir_line == NULL) {
        fprintf(stderr, "Failed to open PIR pin\n");
        gpiod_line_release(relay_line);
        gpiod_context_release(ctx);
        return 1;
    }

    // Create log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        gpiod_context_release(ctx);
        return 1;
    }

    // Set up signal handler for cleanup
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize timer for rate limiting
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 0;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 50 * 1000000; // 50ms
    timerfd_create(CLOEXEC, 0);

    while (1) {
        // Read events from PIR pin
        num_events = gpiod_line_read_events(pir_line, &events, 1);
        if (num_events < 0) {
            fprintf(stderr, "Failed to read events from PIR pin\n");
            break;
        }

        if (num_events > 0) {
            if (events[0].value == GPIOD_LINE_EVENT_RISING_EDGE) {
                if (!rate_limited) {
                    // Check if we're not rate-limited
                    // Unlock door
                    gpiod_line_set_value(relay_line, 1);
                    gettimeofday(&event.tv, NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&event.tv.tv_sec));
                    fprintf(log_file, "%s: Door unlocked\n", timestamp);
                    last_unlock_time = event.tv.tv_sec * 1000000 + event.tv.tv_usec;

                    // Set timer for rate limiting
                    timer.it_value.tv_sec = 0;
                    timer.it_value.tv_nsec = RATE_LIMIT * 1000000;
                    timerfd_settime(timerfd, 0, &timer, NULL);

                    rate_limited = true;
                } else {
                    // We're rate-limited, log the event
                    gettimeofday(&event.tv, NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&event.tv.tv_sec));
                    fprintf(log_file, "%s: Rate-limited event\n", timestamp);
                }
            }
        }

        // Check if we're rate-limited and it's time to reset
        if (rate_limited && (gettimeofday(&event.tv, NULL)->tv_sec * 1000000 + gettimeofday(&event.tv, NULL)->tv_usec - last_unlock_time >= RATE_LIMIT)) {
            rate_limited = false;
        }

        // Check if we're not rate-limited and it's time to unlock
        if (!rate_limited && (gettimeofday(&event.tv, NULL)->tv_sec * 1000000 + gettimeofday(&event.tv, NULL)->tv_usec - last_unlock_time >= UNLOCK_DURATION)) {
            gpiod_line_set_value(relay_line, 0);
            gettimeofday(&event.tv, NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&event.tv.tv_sec));
            fprintf(log_file, "%s: Door locked\n", timestamp);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    return 0;
}

