// Define the GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the maximum number of steps in a pattern
#define MAX_STEPS 15

// Define the minimum and maximum step durations in milliseconds
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

// Define the minimum and maximum PWM duty cycles
#define MIN_PWM_DUTY 0
#define MAX_PWM_DUTY 255

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    volatile sig_atomic_t *shutdown = (volatile sig_atomic_t *)0;
    *shutdown = 1;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the GPIO mode for the motor pins
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize the shutdown flag
    volatile sig_atomic_t shutdown = 0;

    // Set up the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!shutdown) {
        // Generate a random pattern
        int num_steps = rand() % (MAX_STEPS - 4) + 5; // Random number of steps between 5 and 14
        int *steps = malloc(num_steps * sizeof(int));
        if (!steps) {
            fprintf(stderr, "Failed to allocate memory for pattern\n");
            gpioTerminate();
            return 1;
        }

        for (int i = 0; i < num_steps; i++) {
            // Generate random step durations and PWM duty cycles
            int duration = rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1) + MIN_STEP_DURATION;
            int duty1 = rand() % (MAX_PWM_DUTY - MIN_PWM_DUTY + 1) + MIN_PWM_DUTY;
            int duty2 = rand() % (MAX_PWM_DUTY - MIN_PWM_DUTY + 1) + MIN_PWM_DUTY;

            // Store the step in the pattern
            steps[i] = (duration << 8) | duty1 | (duty2 << 16);
        }

        // Play the pattern
        for (int i = 0; i < num_steps; i++) {
            int step = steps[i];
            int duration = step >> 8;
            int duty1 = step & 0xFF;
            int duty2 = (step >> 16) & 0xFF;

            // Set the PWM duty cycles for the motors
            if (gpioHardwarePWM(MOTOR1_PIN, duty1, duration) < 0 || gpioHardwarePWM(MOTOR2_PIN, duty2, duration) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycles\n");
                gpioTerminate();
                free(steps);
                return 1;
            }

            // Wait for the step duration
            usleep(duration * 1000);
        }

        // Clean up the pattern
        free(steps);
    }

    // Shutdown
    gpioHardwarePWM(MOTOR1_PIN, 0, 0);
    gpioHardwarePWM(MOTOR2_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

