#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define SCALE_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define READ_TIMEOUT 500000 // 0.5 seconds
#define CALIBRATION_READINGS 100
#define CALIBRATION_THRESHOLD 10.0 // 10 kg

// Structure to hold calibration data
typedef struct {
    float scale;
    float offset;
} Calibration;

// Function to read calibration data from file
Calibration read_calibration() {
    Calibration calibration;
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file == NULL) {
        // If file does not exist, use default values
        calibration.scale = 1.0;
        calibration.offset = 0.0;
        return calibration;
    }

    char buffer[1024];
    if (fgets(buffer, sizeof(buffer), file) == NULL) {
        // If file is empty, use default values
        fclose(file);
        calibration.scale = 1.0;
        calibration.offset = 0.0;
        return calibration;
    }

    char *token = strtok(buffer, " ");
    if (token == NULL) {
        // If file is not in the correct format, use default values
        fclose(file);
        calibration.scale = 1.0;
        calibration.offset = 0.0;
        return calibration;
    }

    calibration.scale = atof(token);
    token = strtok(NULL, " ");
    if (token == NULL) {
        // If file is not in the correct format, use default values
        fclose(file);
        calibration.scale = 1.0;
        calibration.offset = 0.0;
        return calibration;
    }

    calibration.offset = atof(token);
    fclose(file);
    return calibration;
}

// Function to write calibration data to file
void write_calibration(Calibration calibration) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file == NULL) {
        perror("Error opening calibration file for writing");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%f %f", calibration.scale, calibration.offset);
    fclose(file);
}

// Function to perform one-time startup calibration
void calibrate(Calibration *calibration) {
    int fd = gpioOpen(SCALE_PIN, PI_INPUT);
    if (fd < 0) {
        perror("Error opening HX711 data pin for reading");
        exit(EXIT_FAILURE);
    }

    int clock_fd = gpioOpen(CLOCK_PIN, PI_OUTPUT);
    if (clock_fd < 0) {
        perror("Error opening HX711 clock pin for writing");
        gpioClose(fd);
        exit(EXIT_FAILURE);
    }

    gpioWrite(clock_fd, 1);

    float sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        int data = gpioRead(fd);
        if (data < 0) {
            perror("Error reading HX711 data");
            gpioClose(fd);
            gpioClose(clock_fd);
            exit(EXIT_FAILURE);
        }

        gpioDelay(10);
        int data2 = gpioRead(fd);
        if (data2 < 0) {
            perror("Error reading HX711 data");
            gpioClose(fd);
            gpioClose(clock_fd);
            exit(EXIT_FAILURE);
        }

        sum += (data << 8) | data2;
        gpioDelay(10);
    }

    gpioClose(fd);
    gpioClose(clock_fd);

    calibration->offset = sum / CALIBRATION_READINGS;
}

// Function to read weight from HX711
float read_weight(Calibration calibration) {
    int fd = gpioOpen(SCALE_PIN, PI_INPUT);
    if (fd < 0) {
        perror("Error opening HX711 data pin for reading");
        exit(EXIT_FAILURE);
    }

    int clock_fd = gpioOpen(CLOCK_PIN, PI_OUTPUT);
    if (clock_fd < 0) {
        perror("Error opening HX711 clock pin for writing");
        gpioClose(fd);
        exit(EXIT_FAILURE);
    }

    gpioWrite(clock_fd, 1);

    int data = gpioRead(fd);
    if (data < 0) {
        perror("Error reading HX711 data");
        gpioClose(fd);
        gpioClose(clock_fd);
        exit(EXIT_FAILURE);
    }

    gpioDelay(10);
    int data2 = gpioRead(fd);
    if (data2 < 0) {
        perror("Error reading HX711 data");
        gpioClose(fd);
        gpioClose(clock_fd);
        exit(EXIT_FAILURE);
    }

    gpioDelay(10);

    gpioClose(fd);
    gpioClose(clock_fd);

    return ((data << 8) | data2) * calibration.scale - calibration.offset;
}

// Function to log weight to file
void log_weight(float weight) {
    FILE *file = fopen(WIDTH_LOG_FILE, "a");
    if (file == NULL) {
        perror("Error opening weight log file for writing");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d %f\n", timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday, timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec, weight);
    fclose(file);
}

// Signal handler to clean up on exit
void cleanup(int signal) {
    gpioSetMode(LOCK_PIN, PI_OUTPUT);
    gpioWrite(LOCK_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Error initializing GPIO");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    // Initialize lock pin as output
    gpioSetMode(LOCK_PIN, PI_OUTPUT);
    gpioWrite(LOCK_PIN, 0);

    // Read calibration data
    Calibration calibration = read_calibration();

    // Perform one-time startup calibration
    calibrate(&calibration);

    // Main loop
    while (1) {
        // Read weight
        float weight = read_weight(calibration);
        if (weight < 0) {
            // If read failed, skip this iteration
            continue;
        }

        // Log weight
        log_weight(weight);

        // Check if weight exceeds threshold
        if (weight > CALIBRATION_THRESHOLD) {
            // Engage lock
            gpioWrite(LOCK_PIN, 1);
        } else {
            // Disengage lock
            gpioWrite(LOCK_PIN, 0);
        }

        // Wait for next iteration
        usleep(READ_TIMEOUT);
    }

    return 0;
}

