static void sigint_handler(int sig) {
    if (motor_running) {
        gpioWrite(MOTOR_IN1_GPIO, 0);
        gpioWrite(MOTOR_IN2_GPIO, 0);
        gpioPWM(MOTOR_PWM_GPIO, 0);
        motor_running = false;
    }
    gpioCleanup();
    syslog(LOG_INFO, "Received signal %d, shutting down.", sig);
    exit(EXIT_SUCCESS);
}

static void motor_close_window() {
    if (motor_running) {
        syslog(LOG_INFO, "Closing window.");
        gpioWrite(MOTOR_IN1_GPIO, 1);
        gpioWrite(MOTOR_IN2_GPIO, 0);
        gpioPWM(MOTOR_PWM_GPIO, MOTOR_PWM_DUTY);
        sleep(MOTOR_CLOSE_DURATION / 1000);
        gpioWrite(MOTOR_IN1_GPIO, 0);
        gpioWrite(MOTOR_IN2_GPIO, 0);
        gpioPWM(MOTOR_PWM_GPIO, 0);
        motor_running = false;
        syslog(LOG_INFO, "Window closed.");
    }
}

static void check_rain() {
    int readings[RAIN_DEBOUNCE_READINGS];
    int low_count = 0;
    for (int i = 0; i < RAIN_DEBOUNCE_READINGS; i++) {
        int reading = gpioRead(RAIN_SENSOR_GPIO);
        readings[i] = reading;
        if (reading == 0) {
            low_count++;
        }
        usleep(RAIN_DEBOUNCE_INTERVAL * 1000);
    }
    if (low_count >= RAIN_DETECTED_THRESHOLD) {
        syslog(LOG_INFO, "Rain detected.");
        motor_close_window();
        syslog(LOG_INFO, "Rain detected, closing window.");
    }
}

