    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    rain_sensor_fd = gpioOpen(RAIN_SENSOR_GPIO, GPIO_READ);
    if (rain_sensor_fd < 0) {
        syslog(LOG_ERR, "Failed to open rain sensor GPIO: %s", strerror(errno));
        gpioCleanup();
        exit(EXIT_FAILURE);
    }

    motor_in1_fd = gpioOpen(MOTOR_IN1_GPIO, GPIO_WRITE);
    if (motor_in1_fd < 0) {
        syslog(LOG_ERR, "Failed to open motor IN1 GPIO: %s", strerror(errno));
        gpioClose(rain_sensor_fd);
        gpioCleanup();
        exit(EXIT_FAILURE);
    }

    motor_in2_fd = gpioOpen(MOTOR_IN2_GPIO, GPIO_WRITE);
    if (motor_in2_fd < 0) {
        syslog(LOG_ERR, "Failed to open motor IN2 GPIO: %s", strerror(errno));
        gpioClose(rain_sensor_fd);
        gpioClose(motor_in1_fd);
        gpioCleanup();
        exit(EXIT_FAILURE);
    }

    motor_pwm_fd = gpioOpen(MOTOR_PWM_GPIO, GPIO_PWM);
    if (motor_pwm_fd < 0) {
        syslog(LOG_ERR, "Failed to open motor PWM GPIO: %s", strerror(errno));
        gpioClose(rain_sensor_fd);
        gpioClose(motor_in1_fd);
        gpioClose(motor_in2_fd);
        gpioCleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        check_rain();
        sleep(60);
        if (motor_running) {
            sleep(60);
        }
    }

    gpioClose(rain_sensor_fd);
    gpioClose(motor_in1_fd);
    gpioClose(motor_in2_fd);
    gpioClose(motor_pwm_fd);
    gpioCleanup();
    closelog();
    return EXIT_SUCCESS;
}

