#define LOG_FILE "stock_events.txt"
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5

// Function to log an event to the log file
void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s: %s\n", timestamp, message);
    fclose(file);
}

// Function to read the weight from the HX711
int read_weight() {
    int weight = 0;
    int i;

    // Set up GPIO pins
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", gpioErrorStr(gpioError()));
        return -1;
    }

    gpioSetMode(23, PI_INPUT);
    gpioSetMode(24, PI_OUTPUT);
    gpioSetMode(17, PI_OUTPUT);

    // Set up HX711 communication
    gpioWrite(24, 0); // Set SCK low
    gpioDelay(10);

    for (i = 0; i < 24; i++) {
        gpioWrite(24, 1); // Set SCK high
        gpioDelay(1);
        gpioWrite(24, 0); // Set SCK low
        gpioDelay(1);

        int bit = gpioRead(23); // Read DT
        if (bit == 1) {
            weight |= 1 << (23 - i);
        }
    }

    gpioWrite(24, 0); // Set SCK low
    gpioDelay(10);

    // Check for data line stuck high
    if (gpioRead(23) == 1) {
        syslog(LOG_ERR, "Data line stuck high");
        return -1;
    }

    // Clean up GPIO pins
    gpioSetMode(23, PI_INPUT);
    gpioSetMode(24, PI_INPUT);
    gpioSetMode(17, PI_INPUT);

    return weight;
}

// Function to activate the solenoid lock
void activate_lock() {
    gpioWrite(17, 1); // Set lock high
    sleep(LOCK_DURATION);
    gpioWrite(17, 0); // Set lock low
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, exiting", sig);
    log_event("Program terminated");
    gpioTerminate();
    exit(0);
}

int main() {
    // Set up logging
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", gpioErrorStr(gpioError()));
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(23, PI_INPUT);
    gpioSetMode(24, PI_OUTPUT);
    gpioSetMode(17, PI_OUTPUT);

    while (1) {
        int weight = read_weight();
        if (weight < 0) {
            syslog(LOG_ERR, "Failed to read weight");
            log_event("Failed to read weight");
            continue;
        }

        if (weight < WEIGHT_THRESHOLD) {
            syslog(LOG_INFO, "Weight below threshold, activating lock");
            log_event("Weight below threshold, activating lock");
            activate_lock();
        }

        syslog(LOG_INFO, "Weight: %d g", weight);
        log_event("Weight: %d g", weight);

        sleep(1);
    }

    // Clean up GPIO pins
    gpioSetMode(23, PI_INPUT);
    gpioSetMode(24, PI_INPUT);
    gpioSetMode(17, PI_INPUT);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

