#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"
#define THRESHOLD 5000  // 5.0 kg
#define LOCK_PIN 27
#define CLOCK_PIN 17
#define DATA_PIN 4
#define CLOCK_HIGH_DELAY_US 1000
#define CLOCK_LOW_DELAY_US 1000
#define TIMEOUT_MS 100

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Unlock the solenoid
    gpioWrite(LOCK_PIN, 0);
    // Close the driver
    gpioTerminate();
    // Close the calibration file
    fclose(calibration_file);
    // Close the security log file
    fclose(log_file);
    // Exit the program
    exit(0);
}

// Function to read a 24-bit signed value from the HX711
int read_hx711() {
    int value = 0;
    int i;

    // Set the clock pin high
    gpioWrite(CLOCK_PIN, 1);
    usleep(CLOCK_HIGH_DELAY_US);

    // Read the data pin
    for (i = 0; i < 24; i++) {
        int bit = gpioRead(DATA_PIN);
        value = (value << 1) | bit;
        // Apply a low delay
        usleep(CLOCK_LOW_DELAY_US);
        // Toggle the clock pin
        gpioWrite(CLOCK_PIN, 0);
        usleep(CLOCK_LOW_DELAY_US);
        gpioWrite(CLOCK_PIN, 1);
        usleep(CLOCK_LOW_DELAY_US);
    }

    // Return the 24-bit signed value
    return value;
}

int main() {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize the GPIO driver\n");
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the calibration file
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        // Create the file if it doesn't exist
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Failed to open the calibration file\n");
            gpioTerminate();
            return 1;
        }
    }

    // Read the calibration factor from the file
    fscanf(calibration_file, "%d", &calibration_factor);
    if (ferror(calibration_file)) {
        fprintf(stderr, "Failed to read the calibration factor from the file\n");
        fclose(calibration_file);
        gpioTerminate();
        return 1;
    }

    // Open the security log file
    log_file = fopen(SECURITY_LOG, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open the security log file\n");
        fclose(calibration_file);
        gpioTerminate();
        return 1;
    }

    // Set up the HX711 pins
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);

    // Prompt the user to place a known weight
    printf("Please place a known weight on the scale\n");

    // Wait for the user to place the weight
    while (1) {
        // Read the weight
        int weight = read_hx711();
        // Convert the raw value to a signed value
        weight = (weight * calibration_factor) / 16777216;
        // Check if the weight is valid
        if (weight > 0) {
            // Save the calibration factor to the file
            fprintf(calibration_file, "%d\n", calibration_factor);
            fclose(calibration_file);
            break;
        }
    }

    // Set up the solenoid pin
    gpioSetMode(LOCK_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        // Read the weight
        int weight = read_hx711();
        // Convert the raw value to a signed value
        weight = (weight * calibration_factor) / 16777216;
        // Check if the weight exceeds the threshold
        if (weight > THRESHOLD) {
            // Engage the solenoid
            gpioWrite(LOCK_PIN, 1);
            // Wait for 5 seconds
            usleep(5000000);
            // Release the solenoid
            gpioWrite(LOCK_PIN, 0);
            // Log the timestamp and weight to the security log
            fprintf(log_file, "%lu %d\n", time(NULL), weight);
            fflush(log_file);
        }
        // Check for a communication timeout
        if (gpioRead(DATA_PIN) == 1) {
            // Log the error to the security log
            fprintf(log_file, "Timeout error\n");
            fflush(log_file);
        }
        // Wait for 100 ms
        usleep(100000);
    }

    // Close the security log file
    fclose(log_file);

    // Close the calibration file
    fclose(calibration_file);

    // Terminate the GPIO driver
    gpioTerminate();

    return 0;
}

