#include <syslog.h>
#include <libgpiod.h>

#define RELAY_PIN 20
#define SENSOR_PIN 16
#define LOG_FILE "relay_events.log"

void cleanup(int sig) {
    gpiod_line_release(gpiod_line_request("gpiochip0", RELAY_PIN, "output", GPIOD_LINE_ACTIVE_HIGH));
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    syslog(LOG_INFO, "Cleanup completed");
    exit(0);
}

int main() {
    struct tm *now;
    char timestamp[20];
    char log_message[50];
    int relay_state = 0;
    int sensor_state;
    int chip;
    int line;

    // Set up logging
    openlog("relay_monitor", LOG_PID | LOG_PERROR, LOG_USER);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        exit(1);
    }

    // Request the relay pin as an output
    line = gpiod_line_request("gpiochip0", RELAY_PIN, "output", GPIOD_LINE_ACTIVE_HIGH);
    if (line < 0) {
        syslog(LOG_ERR, "Failed to request relay pin");
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    // Request the sensor pin as an input
    line = gpiod_line_request("gpiochip0", SENSOR_PIN, "input", GPIOD_LINE_ACTIVE_LOW);
    if (line < 0) {
        syslog(LOG_ERR, "Failed to request sensor pin");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Read the sensor state
        sensor_state = gpiod_line_get_value(line);
        if (sensor_state < 0) {
            syslog(LOG_ERR, "Failed to read sensor state");
            gpiod_line_release(line);
            gpiod_line_release(gpiod_line_request("gpiochip0", RELAY_PIN, "output", GPIOD_LINE_ACTIVE_HIGH));
            gpiod_chip_close(chip);
            closelog();
            exit(1);
        }

        // Toggle the relay state
        if (sensor_state == 0) {
            if (relay_state == 0) {
                gpiod_line_set_value(line, 1);
                relay_state = 1;
            } else {
                gpiod_line_set_value(line, 0);
                relay_state = 0;
            }
        }

        // Log the event
        now = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now);
        sprintf(log_message, "%s: Relay state changed to %s\n", timestamp, relay_state ? "ON" : "OFF");
        if (syslog(LOG_INFO, log_message) < 0) {
            syslog(LOG_ERR, "Failed to log event");
        }

        // Write the event to the log file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            continue;
        }
        if (fprintf(log_file, "%s: Relay state changed to %s\n", timestamp, relay_state ? "ON" : "OFF") < 0) {
            syslog(LOG_ERR, "Failed to write to log file");
            fclose(log_file);
            continue;
        }
        fclose(log_file);

        // Sleep for a short period
        usleep(100000);
    }

    return 0;
}

