#include <errno.h>
#include <string.h>
#include <time.h>

#include <pigpio.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

void sigint_handler(int sig) {
    gpio_write(BUZZER_PIN, 0);
    fclose(log_file);
    gpio_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_write(BUZZER_PIN, 0);
    fclose(log_file);
    gpio_cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        exit(1);
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin mode: %s\n", strerror(errno));
        gpio_cleanup();
        exit(1);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode: %s\n", strerror(errno));
        gpio_cleanup();
        exit(1);
    }

    if (access(LOG_FILE, F_OK) == 0) {
        log_file = fopen(LOG_FILE, "a");
    } else {
        log_file = fopen(LOG_FILE, "w");
    }

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpio_cleanup();
        exit(1);
    }

    while (1) {
        int value = gpioRead(PIR_PIN);
        if (value == 1) {
            gpio_write(BUZZER_PIN, 1);
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n", tv.tv_sec % 1000000000 / 1000000, tv.tv_sec % 10000 / 100, tv.tv_sec % 100 / 10, tv.tv_sec % 10, tv.tv_usec / 1000, tv.tv_usec % 1000);
            fflush(log_file);
            usleep(2000000);
            gpio_write(BUZZER_PIN, 0);
        }
        usleep(100);
    }

    fclose(log_file);
    gpio_cleanup();
    return 0;
}

