#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO18 18
#define VALVE_PIN GPIO18

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request options = GPIOD_LINE_REQUEST_OUTPUT;
    struct gpiod_line_request_event event;
    int fd;
    char line_str[256];
    int duration;

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open configuration file
    fd = open("watering.conf", O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Read configuration line
    if (read(fd, line_str, sizeof(line_str)) == -1) {
        fprintf(stderr, "Error reading configuration file: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);

    // Parse configuration line
    if (sscanf(line_str, "duration=%d", &duration) != 1) {
        fprintf(stderr, "Error parsing configuration file: invalid format\n");
        exit(EXIT_FAILURE);
    }
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error parsing configuration file: out-of-range duration\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO line
    line = gpiod_cdev_open("/dev/gpiochip0", 0);
    if (!line) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error());
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(line, VALVE_PIN, &options) == -1) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", gpiod_error());
        gpiod_line_release(line);
        gpiod_chip_close(line);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_direction(line, GPIOD_LINE_DIRECTION_OUTPUT) == -1) {
        fprintf(stderr, "Error setting GPIO line direction: %s\n", gpiod_error());
        gpiod_line_release(line);
        gpiod_chip_close(line);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_export(line, 0) == -1) {
        fprintf(stderr, "Error exporting GPIO line: %s\n", gpiod_error());
        gpiod_line_release(line);
        gpiod_chip_close(line);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(line, 0) == -1) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", gpiod_error());
        gpiod_line_release(line);
        gpiod_chip_close(line);
        exit(EXIT_FAILURE);
    }

    // Activate valve
    printf("Valve on for %d seconds\n", duration);
    gpiod_line_set_value(line, 1);

    // Wait for duration
    while (!exit_flag && duration > 0) {
        if (gpiod_line_get_value(line, &event) == -1) {
            fprintf(stderr, "Error getting GPIO line value: %s\n", gpiod_error());
            gpiod_line_release(line);
            gpiod_chip_close(line);
            exit(EXIT_FAILURE);
        }
        if (event.value == 1) {
            duration--;
            printf("Valve on for %d seconds\n", duration);
        }
        usleep(100000);
    }

    // Deactivate valve
    printf("Valve off\n");
    gpiod_line_set_value(line, 0);

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_chip_close(line);

    return 0;
}

