#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define RELAY_GPIO 23
#define MEASUREMENT_DELAY 180
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close I2C handle
    if (close(i2c_fd) == -1) {
        perror("close");
    }

    // Turn off relay
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
    }
    if (write(i2c_fd, "\x00", 1) == -1) {
        perror("write");
    }

    // Terminate driver library
    if (close(i2c_fd) == -1) {
        perror("close");
    }

    // Exit program
    exit(0);
}

int main() {
    // Open I2C device
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    // Set up I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Initialize relay
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, "\x00", 1) == -1) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read illuminance
        uint16_t illuminance;
        if (i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x10) == -1) {
            fprintf(log_file, "%lld: I2C write error\n", gettime());
            continue;
        }
        usleep(100000);
        if (i2c_smbus_read_word_data(i2c_fd, 0x00) == -1) {
            fprintf(log_file, "%lld: I2C read error\n", gettime());
            continue;
        }
        illuminance = (i2c_smbus_read_word_data(i2c_fd, 0x00) << 8) | i2c_smbus_read_word_data(i2c_fd, 0x00);

        // Check if lux reading is below threshold
        if (illuminance < LUX_THRESHOLD) {
            // Turn on relay
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
                perror("ioctl");
            }
            if (write(i2c_fd, "\x01", 1) == -1) {
                perror("write");
            }
            fprintf(log_file, "%lld: Relay on\n", gettime());
        } else {
            // Turn off relay
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
                perror("ioctl");
            }
            if (write(i2c_fd, "\x00", 1) == -1) {
                perror("write");
            }
            fprintf(log_file, "%lld: Relay off\n", gettime());
        }

        // Log lux reading
        fprintf(log_file, "%lld: %d lux\n", gettime(), illuminance);

        // Delay
        usleep(MEASUREMENT_DELAY * 1000);
    }

    // Close log file
    fclose(log_file);

    return 0;
}

// Function to get current time in milliseconds
uint64_t gettime() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

