            // Debounce the unlock button press
            sleep(DEBOUNCE_DELAY / 1000);
            unlock_pressed = gpiod_line_get_value(lock_line);
            if (unlock_pressed == 0) {
                // Set the servo pulse width to 0°
                if (gpiod_line_set_value(servo_line, 0) == -1) {
                    gpiod_line_release(lock_line);
                    gpiod_line_release(unlock_line);
                    gpiod_line_release(servo_line);
                    perror("gpiod_line_set_value");
                    return 1;
                }
                printf("Locking the door...\n");
            }
        }

        // Sleep for 100ms
        sleep(0.1);
    }

    // Release all resources
    gpiod_line_release(lock_line);
    gpiod_line_release(unlock_line);
    gpiod_line_release(servo_line);
    return 0;
