    gpiod_line_release(GPIO27);
    gpiod_context_unref(gpiod_ctx);
    exit(0);
}

int main() {
    // Initialize GPIO context
    gpiod_ctx = gpiod_ctx_new();
    if (!gpiod_ctx) {
        perror("gpiod_ctx_new");
        return 1;
    }

    // Request GPIO lines
    struct gpiod_line *line1 = gpiod_line_request_by_name(gpiod_ctx, "gpio17", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_OUTPUT);
    struct gpiod_line *line2 = gpiod_line_request_by_name(gpiod_ctx, "gpio27", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_OUTPUT);
    if (!line1 || !line2) {
        perror("gpiod_line_request_by_name");
        gpiod_ctx_unref(gpiod_ctx);
        return 1;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_ctx_unref(gpiod_ctx);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_ctx_unref(gpiod_ctx);
        return 1;
    }

    // Set initial state of GPIO lines
    if (gpiod_line_set_value(line1, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_ctx_unref(gpiod_ctx);
        return 1;
