    if (gpiod_line_set_value(line2, 0) == -1) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_ctx_unref(gpiod_ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Pulse motor 1
        if (gpiod_line_set_value(line1, 1) == -1) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_ctx_unref(gpiod_ctx);
            return 1;
