        usleep(200000);
        if (gpiod_line_set_value(line1, 0) == -1) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_ctx_unref(gpiod_ctx);
            return 1;
        }

        // Pulse motor 2
        if (gpiod_line_set_value(line2, 1) == -1) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_ctx_unref(gpiod_ctx);
            return 1;
