#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <zmq.h>

#define GPIO_BASE 0x3F200000
#define GPIO_SETDATAOUT 0x13C
#define GPIO_CLEARDATAOUT 0x194
#define GPIO_PULLUP_EN 0x28
#define GPIO_PULLDOWN_EN 0x29
#define GPIO_SET_DATAIN 0x1C
#define GPIO_GET_DATAIN 0x1C

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE "alarm_node"

#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"

void cleanup(int sig) {
    (void)sig;
    (void)gpio_memunmap(GPIO_BASE);
    (void)close(zmq_ctx);
    (void)zmq_ctx_term(zmq_ctx);
    (void)zmq_close(zmq_socket);
    (void)zmq_close(zmq_sub);
    exit(0);
}

void sound_sensor_mode(void) {
    int fd = open("/dev/mem", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    void *gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(1);
    }

    int *gpio = (int *)gpio_map;

    if (ioctl(fd, GPIO_SET_DATAIN, SOUND_SENSOR_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (ioctl(fd, GPIO_PULLUP_EN, SOUND_SENSOR_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_ctx = zmq_ctx_new();
    if (zmq_ctx == NULL) {
        perror("zmq_ctx_new");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_socket = zmq_socket(zmq_ctx, ZMQ_PUB);
    if (zmq_socket == -1) {
        perror("zmq_socket");
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (zmq_bind(zmq_socket, "tcp://*:5555") < 0) {
        perror("zmq_bind");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    struct zmq_pollitem_t items[] = {
        {zmq_socket, 0, ZMQ_POLLIN, 0},
        {NULL, 0, 0, 0}
    };

    while (1) {
        if (zmq_poll(items, 1, 10) < 0) {
            perror("zmq_poll");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_ctx);
            munmap(gpio_map, 4096);
            close(fd);
            exit(1);
        }

        if (items[0].revents & ZMQ_POLLIN) {
            uint32_t data = *(volatile uint32_t *)(gpio + (SOUND_SENSOR_PIN / 32));
            if (!(data & (1 << (SOUND_SENSOR_PIN % 32)))) {
                char *message = "SOUND_ALERT";
                if (zmq_send(zmq_socket, message, strlen(message), 0) < 0) {
                    perror("zmq_send");
                    zmq_close(zmq_socket);
                    zmq_ctx_destroy(zmq_ctx);
                    munmap(gpio_map, 4096);
                    close(fd);
                    exit(1);
                }
            }
        }
    }
}

void alarm_node_mode(void) {
    int fd = open("/dev/mem", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    void *gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(1);
    }

    int *gpio = (int *)gpio_map;

    if (ioctl(fd, GPIO_SET_DATAIN, ALARM_LED_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (ioctl(fd, GPIO_PULLDOWN_EN, ALARM_LED_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_ctx = zmq_ctx_new();
    if (zmq_ctx == NULL) {
        perror("zmq_ctx_new");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_sub = zmq_socket(zmq_ctx, ZMQ_SUB);
    if (zmq_sub == -1) {
        perror("zmq_socket");
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (zmq_connect(zmq_sub, "tcp://localhost:5555") < 0) {
        perror("zmq_connect");
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (zmq_setsockopt(zmq_sub, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC)) < 0) {
        perror("zmq_setsockopt");
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    struct zmq_pollitem_t items[] = {
        {zmq_sub, 0, ZMQ_POLLIN, 0},
        {NULL, 0, 0, 0}
    };

    while (1) {
        if (zmq_poll(items, 1, 10) < 0) {
            perror("zmq_poll");
            zmq_close(zmq_sub);
            zmq_ctx_destroy(zmq_ctx);
            munmap(gpio_map, 4096);
            close(fd);
            exit(1);
        }

        if (items[0].revents & ZMQ_POLLIN) {
            char *message = malloc(1024);
            if (zmq_recv(zmq_sub, message, 1024, 0) < 0) {
                perror("zmq_recv");
                free(message);
                zmq_close(zmq_sub);
                zmq_ctx_destroy(zmq_ctx);
                munmap(gpio_map, 4096);
                close(fd);
                exit(1);
            }

            if (strcmp(message, "SOUND_ALERT") == 0) {
                if (ioctl(fd, GPIO_SETDATAOUT, ALARM_LED_PIN) < 0) {
                    perror("ioctl");
                    free(message);
                    zmq_close(zmq_sub);
                    zmq_ctx_destroy(zmq_ctx);
                    munmap(gpio_map, 4096);
                    close(fd);
                    exit(1);
                }

                usleep(1000000);

                if (ioctl(fd, GPIO_CLEARDATAOUT, ALARM_LED_PIN) < 0) {
                    perror("ioctl");
                    free(message);
                    zmq_close(zmq_sub);
                    zmq_ctx_destroy(zmq_ctx);
                    munmap(gpio_map, 4096);
                    close(fd);
                    exit(1);
                }
            }

            free(message);
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        exit(1);
    }

    if (strcmp(argv[1], SOUND_SENSOR_MODE) == 0) {
        signal(SIGINT, cleanup);
        signal(SIGTERM, cleanup);
        sound_sensor_mode();
    } else if (strcmp(argv[1], ALARM_NODE_MODE) == 0) {
        signal(SIGINT, cleanup);
        signal(SIGTERM, cleanup);
