void alarm_node_mode(void) {
    int fd = open("/dev/mem", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    void *gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(1);
    }

    int *gpio = (int *)gpio_map;

    if (ioctl(fd, GPIO_SET_DATAIN, ALARM_LED_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (ioctl(fd, GPIO_PULLDOWN_EN, ALARM_LED_PIN) < 0) {
        perror("ioctl");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_ctx = zmq_ctx_new();
    if (zmq_ctx == NULL) {
        perror("zmq_ctx_new");
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    int zmq_sub = zmq_socket(zmq_ctx, ZMQ_SUB);
    if (zmq_sub == -1) {
        perror("zmq_socket");
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (zmq_connect(zmq_sub, "tcp://localhost:5555") < 0) {
        perror("zmq_connect");
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    if (zmq_setsockopt(zmq_sub, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC)) < 0) {
        perror("zmq_setsockopt");
        zmq_close(zmq_sub);
        zmq_ctx_destroy(zmq_ctx);
        munmap(gpio_map, 4096);
        close(fd);
        exit(1);
    }

    struct zmq_pollitem_t items[] = {
        {zmq_sub, 0, ZMQ_POLLIN, 0},
        {NULL, 0, 0, 0}
    };

    while (1) {
        if (zmq_poll(items, 1, 10) < 0) {
            perror("zmq_poll");
            zmq_close(zmq_sub);
            zmq_ctx_destroy(zmq_ctx);
            munmap(gpio_map, 4096);
            close(fd);
            exit(1);
        }

        if (items[0].revents & ZMQ_POLLIN) {
            char *message = malloc(1024);
            if (zmq_recv(zmq_sub, message, 1024, 0) < 0) {
                perror("zmq_recv");
                free(message);
                zmq_close(zmq_sub);
                zmq_ctx_destroy(zmq_ctx);
                munmap(gpio_map, 4096);
                close(fd);
                exit(1);
            }

            if (strcmp(message, "SOUND_ALERT") == 0) {
                if (ioctl(fd, GPIO_SETDATAOUT, ALARM_LED_PIN) < 0) {
                    perror("ioctl");
                    free(message);
                    zmq_close(zmq_sub);
                    zmq_ctx_destroy(zmq_ctx);
                    munmap(gpio_map, 4096);
                    close(fd);
                    exit(1);
                }

                usleep(1000000);

                if (ioctl(fd, GPIO_CLEARDATAOUT, ALARM_LED_PIN) < 0) {
                    perror("ioctl");
                    free(message);
                    zmq_close(zmq_sub);
                    zmq_ctx_destroy(zmq_ctx);
                    munmap(gpio_map, 4096);
                    close(fd);
                    exit(1);
                }
            }

            free(message);
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        exit(1);
    }

    if (strcmp(argv[1], SOUND_SENSOR_MODE) == 0) {
        signal(SIGINT, cleanup);
        signal(SIGTERM, cleanup);
        sound_sensor_mode();
    } else if (strcmp(argv[1], ALARM_NODE_MODE) == 0) {
        signal(SIGINT, cleanup);
        signal(SIGTERM, cleanup);
        alarm_node_mode();
    } else {
        fprintf(stderr, "Invalid mode\n");
        exit(1);
    }

    return 0;
}
```

This code implements a sound-triggered alarm system on a Raspberry Pi 5. It uses the GPIO bus directly to interact with the sound sensor and alarm LED, and ZeroMQ for inter-process communication. The program can run in two modes: sound_sensor and alarm_node. In sound_sensor mode, it polls the sound sensor every 10ms and publishes an alert on a ZeroMQ socket if a sound is detected. In alarm_node mode, it subscribes to the same ZeroMQ socket and lights the alarm LED for 1 second when an alert is received. The program handles errors and releases resources on exit.

