    gpiod_close("/dev/gpiochip0");
    mosquitto_disconnect(mqtt);
    mosquitto_destroy(mqtt);
    syslog(LOG_INFO, "Released resources");
    exit(0);
}

void decode_ir(struct ir_data *data, struct pulse *pulses, int count) {
    uint32_t address = 0;
    uint32_t command = 0;
    uint8_t checksum = 0;

    for (int i = 0; i < count; i++) {
        if (pulses[i].duration < MAX_PULSE_WIDTH) {
            syslog(LOG_ERR, "Pulse buffer overflow");
            return;
        }
        if (i % 2 == 0) {
            address = (address << 1) | (pulses[i].duration > 560);
        } else {
            command = (command << 1) | (pulses[i].duration > 560);
        }
    }

    if (count >= 32) {
        checksum = (address >> 24) ^ (address >> 16) ^ (address >> 8) ^ address;
        checksum = ~checksum & 0xFF;
        if (checksum != (command >> 24) ^ (command >> 16) ^ (command >> 8) ^ command) {
            syslog(LOG_INFO, "Invalid checksum");
            return;
        }
    }

    data->address = address;
    data->command = command;
    data->checksum = checksum;
}

