        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_chip_close("/dev/gpiochip0");
        exit(1);
    }
    line = gpiod_line_request_event("/dev/gpiochip0", GPIO17, GPIOD_LINE_EVENT_BOTH);
    if (!line) {
        syslog(LOG_ERR, "Failed to request GPIO event");
        gpiod_chip_close("/dev/gpiochip0");
        exit(1);
    }

