                mosquitto_destroy(mqtt);
                exit(1);
            }
            if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
                last_pulse = event.timestamp;
            } else if (event.event == GPIOD_LINE_EVENT_FALLING_EDGE) {
                uint64_t pulse = event.timestamp - last_pulse;
                pulses[pulse_count].start = last_pulse;
                pulses[pulse_count].duration = pulse;
                pulse_count++;
                if (pulse_count >= MAX_PULSE_COUNT) {
                    syslog(LOG_ERR, "Pulse buffer overflow");
                    pulse_count = 0;
                }
