                        syslog(LOG_INFO, "Decoded command: %s", json);
                        last_address = data.address;
                        last_command = data.command;
                        last_checksum = data.checksum;
                    }
                    pulse_count = 0;
                }
            }
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close("/dev/gpiochip0");
    mosquitto_disconnect(mqtt);
    mosquitto_destroy(mqtt);
    closelog();
    return 0;
}

