#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define AWM7300V_ADDRESS 0x5A
#define AWM7300V_REG_FLOW 0x00
#define AWM7300V_REG_STATUS 0x01
#define AWM7300V_REG_CONFIG 0x02
#define AWM7300V_REG_COUNT 0x03
#define AWM7300V_REG_ID 0x04
#define AWM7300V_REG_VERSION 0x05
#define AWM7300V_REG_FLOW_MASK 0x3FFF
#define AWM7300V_REG_FLOW_SHIFT 0
#define AWM7300V_REG_STATUS_MASK 0x01
#define AWM7300V_REG_STATUS_SHIFT 0
#define AWM7300V_REG_CONFIG_MASK 0x01
#define AWM7300V_REG_CONFIG_SHIFT 0
#define AWM7300V_REG_COUNT_MASK 0x03
#define AWM7300V_REG_COUNT_SHIFT 0
#define AWM7300V_REG_ID_MASK 0xFF
#define AWM7300V_REG_ID_SHIFT 0
#define AWM7300V_REG_VERSION_MASK 0xFF
#define AWM7300V_REG_VERSION_SHIFT 0
#define SLPM_PER_LSB 0.000225

static volatile bool running = true;
static FILE *log_file = NULL;

void sigint_handler(int sig) {
    running = false;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    msg[0].addr = AWM7300V_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = AWM7300V_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    while (running) {
        ret = ioctl(fd, I2C_RDWR, &i2c_data);
        if (ret == 0) {
            return 0;
        } else if (errno == EIO) {
            // Bus error, try again
            usleep(100000);
        } else if (errno == ENXIO) {
            // Missing sensor, exit
            fprintf(stderr, "Error: Missing sensor\n");
            return -1;
        } else {
            // Other error, exit
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return -1;
        }
    }

    return -1;
}

int main() {
    int fd;
    uint8_t buf[2];
    uint16_t flow;
    struct tm *timestamp;
    char timestamp_str[20];

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return 1;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open log file
    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        // Issue a zero-length write to generate a start condition
        if (write(fd, NULL, 0) < 0) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            break;
        }

        // Read two bytes from the sensor
        if (i2c_read(fd, AWM7300V_REG_FLOW, buf, 2) < 0) {
            break;
        }

        // Mask the 14-bit flow value
        flow = (buf[0] & AWM7300V_REG_FLOW_MASK) << AWM7300V_REG_FLOW_SHIFT | (buf[1] & AWM7300V_REG_FLOW_MASK);

        // Convert to SLPM
        flow *= SLPM_PER_LSB;

        // Get current timestamp
        timestamp = localtime(&time(NULL));
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp);

        // Log flow rate
        fprintf(log_file, "%s %.2f SLPM\n", timestamp_str, flow);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C file descriptor
    close(fd);

    // Flush and close log file
    fflush(log_file);
    fclose(log_file);

    return 0;
}

