#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x5B
#define SPECTRAL_LOG "spectral_log.csv"
#define MEASUREMENT_INTERVAL 5000  // in milliseconds

// Function to read a byte from the I2C bus
uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t data;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_read_byte(fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        exit(EXIT_FAILURE);
    }
    return data;
}

// Function to write a byte to the I2C bus
void i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte_data(fd, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Verify sensor identification register
    uint8_t id = i2c_read_byte(fd, 0x00);
    if (id != 0x5B) {
        fprintf(stderr, "Error: Sensor ID mismatch\n");
        exit(EXIT_FAILURE);
    }

    // Power on the device
    i2c_write_byte(fd, 0x01, 0x01);

    // Configure SMUX
    i2c_write_byte(fd, 0x06, 0x00);

    // Enable spectral measurement
    i2c_write_byte(fd, 0x0F, 0x01);

    // Open log file
    FILE *log_file = fopen(SPECTRAL_LOG, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read spectral channels
        uint16_t channels[10];
        for (int i = 0; i < 10; i++) {
            channels[i] = i2c_read_byte(fd, 0x10 + i);
        }

        // Compute lux approximation
        uint32_t lux = 0;
        for (int i = 0; i < 8; i++) {
            lux += channels[i] * (i + 1);
        }
        lux /= 8;

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                timestamp,
                channels[0], channels[1], channels[2], channels[3],
                channels[4], channels[5], channels[6], channels[7],
                channels[8], channels[9]);
        fflush(log_file);

        // Sleep for measurement interval
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    close(fd);
    return 0;
}

