    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read spectral channels
        uint16_t channels[10];
        for (int i = 0; i < 10; i++) {
            channels[i] = i2c_read_byte(fd, 0x10 + i);
        }

        // Compute lux approximation
        uint32_t lux = 0;
        for (int i = 0; i < 8; i++) {
            lux += channels[i] * (i + 1);
        }
        lux /= 8;

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                timestamp,
                channels[0], channels[1], channels[2], channels[3],
                channels[4], channels[5], channels[6], channels[7],
                channels[8], channels[9]);
        fflush(log_file);

        // Sleep for measurement interval
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    close(fd);
    return 0;
}
