#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x23
#define UDP_PORT 5000
#define UDP_GROUP "239.255.255.250"
#define UDP_TTL 1
#define BUFFER_SIZE 1024

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

float read_lux(int fd) {
    uint16_t raw;
    if (i2c_write(fd, "\x00\x00", 2) < 0) return -1.0;
    if (i2c_read(fd, &raw, 2) < 0) return -1.0;
    return (float)raw * 1.2;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        return 1;
    }

    int fd = i2c_open();
    if (fd < 0) {
        sleep(1);
        return 0;
    }

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Failed to create UDP socket");
        close(fd);
        return 1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, UDP_GROUP, &addr.sin_addr);
    addr.sin_port = htons(UDP_PORT);
    setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &UDP_TTL, sizeof(UDP_TTL));

    while (running) {
        if (i2c_read(fd, NULL, 0) < 0) {
            sleep(1);
            continue;
        }
        float lux = read_lux(fd);
        if (lux < 0) {
            sleep(1);
            continue;
        }
        char buffer[BUFFER_SIZE];
        sprintf(buffer, "%.2f", lux);
        sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr));
        sleep(1);
    }

    close(fd);
    close(sock);
    return 0;
}

