#include <linux/i2c-dev.h>
#include <termios.h>
#include <errno.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define UART_TIMEOUT 1000

// Function to set up the UART device
int setup_uart(int baud_rate, int timeout) {
    int fd = open(UART_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) < 0) {
        perror("Failed to get UART attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, baud_rate);
    cfsetospeed(&options, baud_rate);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHOK | ECHONL | ECHOPRT | ECHOCTL);
    options.c_oflag &= ~OPOST;
    options.c_iflag &= ~(BRKINT | ICRNL | IGNBRK | IGNCR | IGNORT | IMAXBEL);
    options.c_cc[VMIN] = 1;
    options.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("Failed to set UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to send a string over the UART device
int send_uart_string(int fd, const char *str) {
    size_t len = strlen(str);
    ssize_t bytes_written = write(fd, str, len);
    if (bytes_written < 0) {
        perror("Failed to write to UART device");
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio(int pin) {
    int fd = gpiochip_get_linehandle(0);
    if (fd < 0) {
        perror("Failed to get GPIO chip handle");
        return -1;
    }

    struct gpiod_line_request req;
    memset(&req, 0, sizeof(req));
    req.consumer = "read_gpio";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.line_offset = pin;
    if (gpiod_line_request(fd, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiochip_close(fd);
        return -1;
    }

    int value = gpiod_line_get_value(fd, pin);
    gpiod_line_release(fd, pin);
    gpiochip_close(fd);
    return value;
}

int main() {
    // Initialize the GPIO driver
    int fd = gpiochip_get_linehandle(0);
    if (fd < 0) {
        perror("Failed to get GPIO chip handle");
        return 1;
    }

    struct gpiod_line_request req;
    memset(&req, 0, sizeof(req));
    req.consumer = "read_gpio";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.line_offset = GPIO4;
    if (gpiod_line_request(fd, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiochip_close(fd);
        return 1;
    }

    req.line_offset = GPIO17;
    if (gpiod_line_request(fd, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fd, GPIO4);
        gpiochip_close(fd);
        return 1;
    }

    req.line_offset = GPIO27;
    if (gpiod_line_request(fd, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fd, GPIO4);
        gpiod_line_release(fd, GPIO17);
        gpiochip_close(fd);
        return 1;
    }

    // Enable pull-up resistors
    struct gpiod_line_request pull_up;
    memset(&pull_up, 0, sizeof(pull_up));
    pull_up.consumer = "pull_up";
    pull_up.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    pull_up.line_offset = GPIO4;
    pull_up.flags = GPIOD_LINE_FLAG_REQUEST_FLAG_PULL_UP;
    if (gpiod_line_request(fd, &pull_up) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fd, GPIO4);
        gpiod_line_release(fd, GPIO17);
        gpiochip_close(fd);
        return 1;
    }

    pull_up.line_offset = GPIO17;
    pull_up.flags = GPIOD_LINE_FLAG_REQUEST_FLAG_PULL_UP;
    if (gpiod_line_request(fd, &pull_up) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fd, GPIO4);
        gpiod_line_release(fd, GPIO17);
        gpiochip_close(fd);
        return 1;
    }

    pull_up.line_offset = GPIO27;
    pull_up.flags = GPIOD_LINE_FLAG_REQUEST_FLAG_PULL_UP;
    if (gpiod_line_request(fd, &pull_up) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fd, GPIO4);
        gpiod_line_release(fd, GPIO17);
        gpiochip_close(fd);
        return 1;
